  app.post("/api/finance/account-products", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const parsed = insertAccountProductSchema.safeParse({ ...req.body, createdBy: ctx.userId });
      if (!parsed.success) return res.status(400).json({ message: "Invalid data", errors: parsed.error.flatten() });
      const { customerId, productId, isActive } = parsed.data;
      // Guard: prevent duplicate active assignments for the same product on the same account
      if (isActive !== false) {
        const [existing] = await db.select({ id: accountProducts.id })
          .from(accountProducts)
          .where(and(
            eq(accountProducts.customerId, customerId),
            eq(accountProducts.productId, productId),
            eq(accountProducts.isActive, true),
          ))
          .limit(1);
        if (existing) {
          return res.status(409).json({
            error_code: "DUPLICATE_ACTIVE_ASSIGNMENT",
            message: "This product is already actively assigned to this account. Deactivate the existing assignment before creating a new one.",
            existingAssignmentId: existing.id,
          });
        }
      }
      const [row] = await db.insert(accountProducts).values(parsed.data).returning();
      res.status(201).json(row);
    } catch (e: any) {
      if (e.code === "23505" && e.constraint === "account_products_active_unique") {
        return res.status(409).json({
          error_code: "DUPLICATE_ACTIVE_ASSIGNMENT",
          message: "This product is already actively assigned to this account (database constraint).",
        });
      }
      res.status(500).json({ message: e.message });
    }
  });

