  // ─── Assembly: Charges eligible for a given cycle (for Billing Candidates UI) ─
  app.get("/api/billing/assembly/eligible-charges", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { cycleStart, cycleEnd, customerId } = req.query as Record<string, string>;
      if (!cycleStart || !cycleEnd) {
        return res.status(400).json({ message: "cycleStart and cycleEnd query params required" });
      }

      const { runAssembly } = await import("./services/invoiceAssemblyEngine");
      const result = await runAssembly({
        cycleStart,
        cycleEnd,
        dryRun: true,
        createdBy: req.user.claims.sub,
        customerIds: customerId ? [customerId] : undefined,
      });

      // Flatten into a charge-level response useful for the Billing Candidates grid
      const eligible: any[] = [];
      const excluded: any[] = [];
      for (const r of result.results) {
        for (const line of r.lines) {
          for (const chargeId of line.chargeIds) {
            eligible.push({
              chargeId,
              customerId: r.customerId,
              customerName: r.customerName,
              groupingKey: line.groupingKey,
              productId: line.productId,
              productName: line.productName,
              revenueCategory: line.revenueCategory,
              description: line.description,
            });
          }
        }
        for (const ex of r.exclusions) {
          excluded.push(ex);
        }
      }

      res.json({
        cycleStart, cycleEnd,
        eligibleCount: eligible.length,
        excludedCount: excluded.length,
        eligible,
        excluded,
        summary: result.results.map(r => ({
          customerId: r.customerId,
          customerName: r.customerName,
          status: r.status,
          includedCharges: r.includedCharges,
          excludedCharges: r.excludedCharges,
          subtotal: r.subtotal,
          validationErrors: r.validationErrors,
        })),
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

