  // GET /api/admin/account-report-campaigns
  app.get("/api/admin/account-report-campaigns", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const callerUser = await storage.getUser(userId);
      const ALLOWED = new Set(["super_user", "super_admin", "corporate", "corporate_admin"]);
      if (!callerUser || !ALLOWED.has(callerUser.role ?? "")) {
        return res.status(403).json({ message: "Access restricted. Allowed roles: Super Admin, Corporate Admin, Corporate." });
      }

      const search       = `%${(req.query.search       as string || "").trim()}%`;
      const status       = (req.query.status       as string) || "";
      const reportType   = (req.query.reportType   as string) || "";
      const senderProfile= (req.query.senderProfile as string) || "";

      const rows = await db.execute(sql`
        SELECT
          c.id, c.campaign_name, c.report_type, c.sender_profile, c.status,
          c.schedule_type, c.schedule_day, c.schedule_time, c.timezone,
          c.created_by_user_id, c.created_at, c.updated_at,
          COALESCE(
            NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''),
            u.email
          ) AS created_by_name,
          CAST(COUNT(DISTINCT ca.id) AS int) AS account_count,
          lr.id              AS last_run_id,
          lr.status          AS last_run_status,
          lr.started_at      AS last_run_started_at,
          lr.completed_at    AS last_run_completed_at,
          lr.total_accounts  AS last_run_total_accounts,
          lr.delivered_count      AS last_run_delivered_count,
          lr.failed_count         AS last_run_failed_count,
          lr.not_sent_count       AS last_run_not_sent_count,
          lr.schedule_week_start  AS last_run_schedule_week_start,
          lr.schedule_week_end    AS last_run_schedule_week_end
        FROM account_report_campaigns c
        LEFT JOIN users u ON u.id = c.created_by_user_id
        LEFT JOIN account_report_campaign_accounts ca ON ca.campaign_id = c.id
        LEFT JOIN LATERAL (
          SELECT * FROM account_report_campaign_runs
          WHERE campaign_id = c.id
          ORDER BY created_at DESC
          LIMIT 1
        ) lr ON true
        WHERE
          c.campaign_name ILIKE ${search}
          AND (${status}        = '' OR c.status         = ${status})
          AND (${reportType}    = '' OR c.report_type    = ${reportType})
          AND (${senderProfile} = '' OR c.sender_profile = ${senderProfile})
        GROUP BY
          c.id, u.first_name, u.last_name, u.email,
          lr.id, lr.status, lr.started_at, lr.completed_at,
          lr.total_accounts, lr.delivered_count, lr.failed_count, lr.not_sent_count,
          lr.schedule_week_start, lr.schedule_week_end
        ORDER BY c.created_at DESC
      `);
      res.json((rows as any).rows ?? rows);
    } catch (e: any) {
      console.error("[AMR] account-report-campaigns list error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

