  app.post("/api/admin/comm-templates", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { slug, name, channel, category, subject, body_html, is_active } = req.body;
      if (!slug || !name || !body_html) {
        return res.status(400).json({ message: "slug, name, and body_html are required" });
      }

      // Extract merge fields automatically from body
      const mergeMatches = (body_html + " " + (subject || "")).match(/\{\{(\w+)\}\}/g) || [];
      const variables = [...new Set(mergeMatches.map((m: string) => m.replace(/\{\{|\}\}/g, "")))];

      const r = await pool.query(`
        INSERT INTO comm_templates
          (slug, name, channel, category, subject_template, body_html_template, variables, is_active, version)
        VALUES ($1,$2,$3,$4,$5,$6,$7,$8,1)
        RETURNING id, slug, name, channel, category,
                  subject_template AS subject, body_html_template AS body_html, variables, is_active, updated_at
      `, [
        slug.toUpperCase(), name, channel || "email", category || null,
        subject || null, body_html, JSON.stringify(variables), is_active !== false,
      ]);
      res.status(201).json(r.rows[0]);
    } catch (e: any) {
      if (e.code === "23505") return res.status(409).json({ message: "A template with this slug already exists" });
      console.error("[CommTemplates] POST error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  app.patch("/api/admin/comm-templates/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { id } = req.params;
      const { name, channel, category, subject, body_html, is_active } = req.body;

      const sets: string[] = ["updated_at = now()"];
      const vals: any[] = [];
      let i = 1;

      if (name !== undefined)      { sets.push(`name = $${i++}`);                 vals.push(name); }
      if (channel !== undefined)   { sets.push(`channel = $${i++}`);              vals.push(channel); }
      if (category !== undefined)  { sets.push(`category = $${i++}`);             vals.push(category || null); }
      if (subject !== undefined)   { sets.push(`subject_template = $${i++}`);     vals.push(subject || null); }
      if (is_active !== undefined) { sets.push(`is_active = $${i++}`);            vals.push(is_active); }
      if (body_html !== undefined) {
        sets.push(`body_html_template = $${i++}`);
        vals.push(body_html);
        // Re-extract merge fields
        const mergeMatches = (body_html + " " + (subject || "")).match(/\{\{(\w+)\}\}/g) || [];
        const variables = [...new Set(mergeMatches.map((m: string) => m.replace(/\{\{|\}\}/g, "")))];
        sets.push(`variables = $${i++}`);
        vals.push(JSON.stringify(variables));
      }

      vals.push(id);
      const r = await pool.query(
        `UPDATE comm_templates SET ${sets.join(", ")} WHERE id = $${i} RETURNING id, slug, name, channel, category, subject_template AS subject, body_html_template AS body_html, variables, is_active, updated_at`,
        vals
      );
      if (!r.rows.length) return res.status(404).json({ message: "Template not found" });

      // Invalidate template cache
      const { invalidateTemplateCache } = await import("./services/communications/templateEngine");
      invalidateTemplateCache(r.rows[0].slug);

      res.json(r.rows[0]);
    } catch (e: any) {
      console.error("[CommTemplates] PATCH error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

