  app.post("/api/admin/comm-templates/:id/test-send", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { email } = req.body;
      if (!email) return res.status(400).json({ message: "email is required" });

      const tRow = await pool.query(
        `SELECT slug, name, subject_template, body_html_template, channel FROM comm_templates WHERE id = $1 LIMIT 1`,
        [req.params.id]
      );
      if (!tRow.rows.length) return res.status(404).json({ message: "Template not found" });

      const t = tRow.rows[0];
      if (t.channel !== "email") {
        return res.status(400).json({ message: "Test send is only supported for email templates" });
      }

      // Render with sample context
      const sampleCtx: Record<string, string> = {
        DriverName: "John Smith",
        AccountName: "Acme Logistics",
        ClaimNumber: "CLM-2026-00142",
        ClaimStatus: "Under Review",
        ClaimAmount: "$4,250.00",
        MoveID: "MOV-98321",
        Date: new Date().toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }),
        Time: "9:30 AM",
      };

      const renderFn = (tmpl: string) =>
        tmpl.replace(/\{\{(\w+)\}\}/g, (_, key) => sampleCtx[key] ?? `{{${key}}}`);

      const subject = renderFn(t.subject_template || `[TEST] ${t.name}`);
      const bodyHtml = renderFn(t.body_html_template);

      const { communicationOrchestrator } = await import("./services/communications/orchestrator");
      const result = await communicationOrchestrator.send({
        channel:   "email",
        provider:  "microsoft_365",
        subject:   `[TEST] ${subject}`,
        body:      bodyHtml,
        recipients: [{
          recipientType:        "unknown",
          destinationRaw:       email,
          destinationNormalized: email.toLowerCase().trim(),
        }],
        relatedModule: "comm_templates",
        createdByUserId: ctx.userId,
      });

      const ok = result.status === "sent" || result.sent > 0;
      if (!ok) {
        return res.status(500).json({ message: `Send failed: ${result.errors.join("; ")}` });
      }
      res.json({ ok: true, message: `Test email sent to ${email}` });
    } catch (e: any) {
      console.error("[CommTemplates] test-send error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  // ── Communication Logs ───────────────────────────────────────────────────────

  // GET /api/admin/comm-logs — paginated, filtered audit log of all outbound comms
  app.get("/api/admin/comm-logs", isAuthenticated, async (req: any, res: Response) => {
    try {
      // Ensure open/click tracking columns exist
      await pool.query(`
        ALTER TABLE driver_communication_logs
          ADD COLUMN IF NOT EXISTS opened_at   TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS clicked_at  TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS sender_email_override TEXT
      `);

      const channel  = (req.query.channel  as string) || "";
      const module   = (req.query.module   as string) || "";
      const search   = (req.query.search   as string) || "";
      const dateFrom = (req.query.dateFrom as string) || "";
      const dateTo   = (req.query.dateTo   as string) || "";
      const page     = Math.max(1, parseInt((req.query.page as string) || "1", 10));
      const pageSize = 50;
      const offset   = (page - 1) * pageSize;

      const conditions: string[] = ["1=1"];
      const params: any[] = [];

      if (channel) {
        params.push(channel);
        conditions.push(`dcl.channel = $${params.length}`);
      }
      if (module) {
        params.push(`%${module}%`);
        conditions.push(`dcl.context_module ILIKE $${params.length}`);
      }
      if (search) {
        params.push(`%${search}%`);
        conditions.push(`(
          COALESCE(du.first_name,'') || ' ' || COALESCE(du.last_name,'') ILIKE $${params.length}
          OR COALESCE(dcl.recipient_name,'') ILIKE $${params.length}
          OR COALESCE(dcl.recipient_email,'') ILIKE $${params.length}
          OR COALESCE(dcl.subject,'') ILIKE $${params.length}
        )`);
      }
      if (dateFrom) {
        params.push(dateFrom);
        conditions.push(`COALESCE(dcl.sent_at, dcl.created_at) >= $${params.length}::timestamptz`);
      }
      if (dateTo) {
        params.push(dateTo);
        conditions.push(`COALESCE(dcl.sent_at, dcl.created_at) <= ($${params.length}::timestamptz + interval '1 day')`);
      }

      const where = conditions.join(" AND ");

      const countResult = await pool.query(
        `SELECT COUNT(*) AS total
         FROM driver_communication_logs dcl
         LEFT JOIN drivers d   ON d.id   = dcl.driver_id
         LEFT JOIN users   du  ON du.id  = d.user_id
         WHERE ${where}`,
        params
      );
      const total = parseInt(countResult.rows[0]?.total || "0", 10);

      params.push(pageSize, offset);
      const dataResult = await pool.query(
        `SELECT
           dcl.id,
           to_char(COALESCE(dcl.sent_at, dcl.created_at) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS sent_at,
           COALESCE(su.first_name || ' ' || su.last_name, 'System') AS sender_name,
           COALESCE(su.email, dcl.sender_email_override, '') AS sender_email,
           dcl.recipient_name,
           dcl.recipient_email,
           dcl.recipient_phone,
           dcl.channel,
           dcl.subject,
           LEFT(COALESCE(dcl.message_body, ''), 200) AS body_preview,
           dcl.status,
           dcl.context_module,
           dcl.opened_at,
           dcl.clicked_at,
           dcl.driver_id,
           COALESCE(du.first_name || ' ' || du.last_name, '') AS driver_name
         FROM driver_communication_logs dcl
         LEFT JOIN users   su  ON su.id  = dcl.sent_by_user_id
         LEFT JOIN drivers d   ON d.id   = dcl.driver_id
         LEFT JOIN users   du  ON du.id  = d.user_id
         WHERE ${where}
         ORDER BY COALESCE(dcl.sent_at, dcl.created_at) DESC
         LIMIT $${params.length - 1} OFFSET $${params.length}`,
        params
      );

      res.json({ rows: dataResult.rows, total, page, pageSize });
    } catch (e: any) {
      console.error("[comm-logs] error:", e.message);
      res.status(500).json({ message: "Failed to fetch communication logs" });
    }
  });

  // ── Driver Email Compose / Drafts ─────────────────────────────────────────────

  // Ensure comm_driver_drafts table (runs on first request)
  async function ensureDriverDraftsTable() {
    await pool.query(`
      CREATE TABLE IF NOT EXISTS comm_driver_drafts (
        id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        driver_id     UUID NOT NULL REFERENCES drivers(id) ON DELETE CASCADE,
        created_by    TEXT NOT NULL,
        from_email    TEXT,
        to_emails     TEXT[]   NOT NULL DEFAULT '{}',
        cc_emails     TEXT[]   NOT NULL DEFAULT '{}',
        subject       TEXT,
        body_html     TEXT,
        attachments   JSONB    NOT NULL DEFAULT '[]',
        status        TEXT     NOT NULL DEFAULT 'draft',
        scheduled_at  TIMESTAMPTZ,
        created_at    TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at    TIMESTAMPTZ NOT NULL DEFAULT NOW()
      )
    `);
  }

  // POST /api/drivers/:id/send-email — compose & send with full audit log
  app.post("/api/drivers/:id/send-email", isAuthenticated, async (req: any, res: Response) => {
    try {
      const driverId = req.params.id;
      const userId   = req.user.claims.sub;
      const { fromEmail, to, cc, subject, body, attachments } = req.body;

      if (!to || !subject || !body) {
        return res.status(400).json({ message: "to, subject, and body are required" });
      }

      // Resolve driver name for the log
      const driverRow = await pool.query(
        `SELECT u.first_name, u.last_name FROM drivers d LEFT JOIN users u ON u.id = d.user_id WHERE d.id = $1`,
        [driverId]
      );
      const driverName = driverRow.rows[0]
        ? `${driverRow.rows[0].first_name} ${driverRow.rows[0].last_name}`.trim()
        : "Driver";

      const toArr: string[] = Array.isArray(to) ? to : [to];
      const ccArr: string[] = Array.isArray(cc) ? cc : (cc ? [cc] : []);

      // Send via Microsoft Graph
      const { sendEmail: sendMsEmail } = await import("./services/microsoftGraphService");
      const sendResult = await sendMsEmail({
        to: toArr,
        cc: ccArr.length ? ccArr : undefined,
        subject,
        bodyHtml: body,
        fromEmail: fromEmail || undefined,
        attachments: (attachments || []).map((a: any) => ({
          name: a.name,
          contentType: a.contentType,
          contentBytes: a.contentBytes,
        })),
      });

      const sentStatus = sendResult.ok ? "sent" : "failed";

      // Ensure open/click columns exist
      await pool.query(`
        ALTER TABLE driver_communication_logs
          ADD COLUMN IF NOT EXISTS opened_at              TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS clicked_at             TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS sender_email_override  TEXT
      `);

      // Log the communication
      await pool.query(
        `INSERT INTO driver_communication_logs
           (driver_id, sent_by_user_id, channel, provider, recipient_email, recipient_name,
            subject, message_body, status, sent_at, context_module, context_entity_id, sender_email_override)
         VALUES ($1,$2,'email','microsoft_graph',$3,$4,$5,$6,$7,NOW(),'direct_email',$8,$9)`,
        [driverId, userId, toArr[0], driverName, subject, body, sentStatus, driverId, fromEmail || null]
      );

      if (!sendResult.ok) {
        return res.status(502).json({ message: sendResult.error || "Email delivery failed" });
      }

      res.json({ ok: true, sentTo: toArr });
    } catch (e: any) {
      console.error("[send-driver-email]", e.message);
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/drivers/:id/save-email-draft
  app.post("/api/drivers/:id/save-email-draft", isAuthenticated, async (req: any, res: Response) => {
    try {
      await ensureDriverDraftsTable();
      const driverId = req.params.id;
      const userId   = req.user.claims.sub;
      const { draftId, fromEmail, to, cc, subject, body, attachments } = req.body;

      const toArr = Array.isArray(to) ? to : (to ? [to] : []);
      const ccArr = Array.isArray(cc) ? cc : (cc ? [cc] : []);
      const attJson = JSON.stringify(attachments || []);

      let id: string;
      if (draftId) {
        // Update existing draft
        const upd = await pool.query(
          `UPDATE comm_driver_drafts
           SET from_email=$1, to_emails=$2, cc_emails=$3, subject=$4, body_html=$5,
               attachments=$6::jsonb, updated_at=NOW()
           WHERE id=$7 AND driver_id=$8 AND status='draft'
           RETURNING id`,
          [fromEmail || null, toArr, ccArr, subject || "", body || "", attJson, draftId, driverId]
        );
        if (!upd.rows[0]) return res.status(404).json({ message: "Draft not found" });
        id = upd.rows[0].id;
      } else {
        const ins = await pool.query(
          `INSERT INTO comm_driver_drafts
             (driver_id, created_by, from_email, to_emails, cc_emails, subject, body_html, attachments, status)
           VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,'draft')
           RETURNING id`,
          [driverId, userId, fromEmail || null, toArr, ccArr, subject || "", body || "", attJson]
        );
        id = ins.rows[0].id;
      }

      res.json({ ok: true, draftId: id });
    } catch (e: any) {
      console.error("[save-email-draft]", e.message);
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/drivers/:id/schedule-email
  app.post("/api/drivers/:id/schedule-email", isAuthenticated, async (req: any, res: Response) => {
    try {
      await ensureDriverDraftsTable();
      const driverId = req.params.id;
      const userId   = req.user.claims.sub;
      const { fromEmail, to, cc, subject, body, attachments, scheduledAt } = req.body;

      if (!scheduledAt) return res.status(400).json({ message: "scheduledAt is required" });
      const scheduledDate = new Date(scheduledAt);
      if (isNaN(scheduledDate.getTime()) || scheduledDate <= new Date()) {
        return res.status(400).json({ message: "scheduledAt must be a future date/time" });
      }

      const toArr = Array.isArray(to) ? to : (to ? [to] : []);
      const ccArr = Array.isArray(cc) ? cc : (cc ? [cc] : []);
      const attJson = JSON.stringify(attachments || []);

      const ins = await pool.query(
        `INSERT INTO comm_driver_drafts
           (driver_id, created_by, from_email, to_emails, cc_emails, subject, body_html, attachments, status, scheduled_at)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8::jsonb,'scheduled',$9)
         RETURNING id`,
        [driverId, userId, fromEmail || null, toArr, ccArr, subject || "", body || "", attJson, scheduledDate]
      );

      // Also log as "scheduled" in comm logs
      await pool.query(`
        ALTER TABLE driver_communication_logs
          ADD COLUMN IF NOT EXISTS opened_at              TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS clicked_at             TIMESTAMPTZ,
          ADD COLUMN IF NOT EXISTS sender_email_override  TEXT
      `);
      const driverRow = await pool.query(
        `SELECT u.first_name, u.last_name FROM drivers d LEFT JOIN users u ON u.id = d.user_id WHERE d.id = $1`,
        [driverId]
      );
      const driverName = driverRow.rows[0]
        ? `${driverRow.rows[0].first_name} ${driverRow.rows[0].last_name}`.trim()
        : "Driver";

      await pool.query(
        `INSERT INTO driver_communication_logs
           (driver_id, sent_by_user_id, channel, provider, recipient_email, recipient_name,
            subject, message_body, status, sent_at, context_module, context_entity_id, sender_email_override)
         VALUES ($1,$2,'email','microsoft_graph',$3,$4,$5,$6,'scheduled',$7,'direct_email',$8,$9)`,
        [driverId, userId, toArr[0], driverName, subject || "", body || "", scheduledDate, driverId, fromEmail || null]
      );

      res.json({ ok: true, draftId: ins.rows[0].id, scheduledAt: scheduledDate });
    } catch (e: any) {
      console.error("[schedule-email]", e.message);
      res.status(500).json({ message: e.message });
    }
  });

