  // GET /api/admin/amr-delivery-history/runs/:runId/reconciliation
  app.get("/api/admin/amr-delivery-history/runs/:runId/reconciliation", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const callerUser = await storage.getUser(userId);
      const ALLOWED = new Set(["super_user", "super_admin", "corporate", "corporate_admin"]);
      if (!callerUser || !ALLOWED.has(callerUser.role ?? "")) {
        return res.status(403).json({ message: "Access restricted. Allowed roles: Super Admin, Corporate Admin, Corporate." });
      }

      const { runId } = req.params;

      // Verify run exists
      const runRows = await db.execute(sql`
        SELECT id, schedule_week_start FROM account_report_campaign_runs WHERE id = ${runId} LIMIT 1
      `);
      const run = ((runRows as any).rows ?? runRows)[0];
      if (!run) return res.status(404).json({ message: "Run not found" });

      // Delivery status counts
      const countsRows = await db.execute(sql`
        SELECT status, COUNT(*)::int AS cnt
        FROM account_report_run_deliveries
        WHERE run_id = ${runId}
        GROUP BY status
      `);
      const counts: any[] = (countsRows as any).rows ?? countsRows;
      const delivered   = Number(counts.find((r: any) => r.status === "delivered")?.cnt  ?? 0);
      const failed      = Number(counts.find((r: any) => r.status === "failed")?.cnt     ?? 0);
      const blocked     = Number(counts.find((r: any) => r.status === "blocked")?.cnt    ?? 0);
      const no_schedule = Number(counts.find((r: any) => r.status === "not_sent")?.cnt   ?? 0);

      // All active DriverShift/Hybrid accounts NOT already in this run's delivery records
      const notInRunRows = await db.execute(sql`
        SELECT
          c.id                  AS account_id,
          c.customer_name,
          c.send_weekly_report,
          c.report_primary_email,
          c.report_primary_emails,
          EXISTS(
            SELECT 1 FROM driver_accounts da
            INNER JOIN drivers d ON d.id = da.driver_id
            WHERE da.account_id = c.id
              AND da.assignment_ended_at IS NULL
              AND LOWER(d.status) = 'active'
          ) AS has_active_drivers,
          EXISTS(
            SELECT 1 FROM weekly_report_recipients wr
            WHERE wr.account_id = c.id AND wr.active = true AND wr.recipient_type = 'TO'
          ) AS has_to_recipients
        FROM customers c
        WHERE c.is_deleted   = false
          AND c.status       = 'Active'
          AND c.driver_model IN ('DriverShift', 'Hybrid')
          AND NOT EXISTS (
            SELECT 1 FROM account_report_run_deliveries d
            WHERE d.run_id = ${runId} AND d.account_id = c.id
          )
        ORDER BY c.customer_name
      `);
      const notInRun: any[] = (notInRunRows as any).rows ?? notInRunRows;

      const not_included = notInRun.map((acc: any) => {
        const sendEnabled = acc.send_weekly_report === true;
        const hasDrivers  = acc.has_active_drivers  === true;

        let reason: string;
        let notes:  string;
        let is_eligible = false;

        if (!sendEnabled) {
          reason = "Weekly Reports Disabled";
          notes  = "Weekly report delivery is disabled on this account.";
        } else if (!hasDrivers) {
          reason = "No Schedule Data";
          notes  = "No active drivers assigned — no shift data available for this week.";
        } else {
          is_eligible = true;
          let hasLegacyEmail = false;
          try {
            const parsed = JSON.parse(acc.report_primary_emails ?? "[]");
            hasLegacyEmail = (Array.isArray(parsed) && parsed.length > 0) || !!acc.report_primary_email;
          } catch {}

          if (!acc.has_to_recipients && !hasLegacyEmail) {
            reason = "Missing Recipient";
            notes  = "No TO recipients configured in weekly report recipients or legacy email fields.";
          } else {
            reason = "Campaign Excluded";
            notes  = "Eligible account was not included in this run. May have been delivered in an earlier run this week, or was outside the configured send window at run time.";
          }
        }

        return { account_id: acc.account_id, customer_name: acc.customer_name, reason, notes, is_eligible };
      });

      const excluded_count = not_included.filter((a: any) => a.is_eligible).length;
      const eligible_count = delivered + failed + blocked + no_schedule + excluded_count;

      res.json({
        eligible_count,
        delivered_count:   delivered,
        failed_count:      failed,
        blocked_count:     blocked,
        no_schedule_count: no_schedule,
        excluded_count,
        not_included,
      });
    } catch (e: any) {
      console.error("[AMR] reconciliation error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/admin/amr-delivery-history/deliveries/:deliveryId/report — stream stored PDF
  app.get("/api/admin/amr-delivery-history/deliveries/:deliveryId/report", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const callerUser = await storage.getUser(userId);
      const ALLOWED = new Set(["super_user", "super_admin", "corporate", "corporate_admin"]);
      if (!callerUser || !ALLOWED.has(callerUser.role ?? "")) {
        return res.status(403).json({ message: "Access restricted. Allowed roles: Super Admin, Corporate Admin, Corporate." });
      }

      const { deliveryId } = req.params;

      // Resolve delivery → account + week
      const deliveryRows = await db.execute(sql`
        SELECT d.account_id, cust.customer_name,
               r.schedule_week_start
        FROM account_report_run_deliveries d
        JOIN account_report_campaign_runs r  ON r.id    = d.run_id
        JOIN customers                  cust ON cust.id = d.account_id
        WHERE d.id = ${deliveryId}
        LIMIT 1
      `);
      const delivery = ((deliveryRows as any).rows ?? deliveryRows)[0];
      if (!delivery) return res.status(404).json({ message: "Delivery record not found" });
      if (!delivery.schedule_week_start)
        return res.status(404).json({ message: "No schedule week on this run" });

      // Find the stored PDF in account_documents
      const docRows = await db.execute(sql`
        SELECT storage_key, filename
        FROM account_documents
        WHERE customer_id = ${delivery.account_id}
          AND category    = 'weekly_schedule_report'
          AND issue_date  = ${delivery.schedule_week_start}::date
          AND is_deleted  = false
        ORDER BY uploaded_at DESC
        LIMIT 1
      `);
      const doc = ((docRows as any).rows ?? docRows)[0];
      if (!doc?.storage_key)
        return res.status(404).json({ message: "No stored report for this delivery. Historical and unsaved runs do not have report artifacts." });

      // Stream from object storage using the safe stream-based approach
      const { ObjectStorageService } = await import("./objectStorage");
      const svc = new ObjectStorageService();
      const buf = await svc.downloadToBuffer(doc.storage_key);
      if (!buf) return res.status(404).json({ message: "Report file not found in storage" });

      const safeName = encodeURIComponent(doc.filename ?? "schedule_report.pdf");
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="${safeName}"`);
      res.setHeader("Content-Length", String(buf.length));
      res.send(buf);
    } catch (e: any) {
      console.error("[AMR] delivery report download error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/admin/amr-delivery-history/export  — CSV download
  app.get("/api/admin/amr-delivery-history/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const callerUser = await storage.getUser(userId);
      const ALLOWED = new Set(["super_user", "super_admin", "corporate", "corporate_admin"]);
      if (!callerUser || !ALLOWED.has(callerUser.role ?? "")) {
        return res.status(403).json({ message: "Access restricted. Allowed roles: Super Admin, Corporate Admin, Corporate." });
      }

      const search        = `%${((req.query.search as string) || "").trim()}%`;
      const statusFilter  = (req.query.status        as string) || "";
      const senderProfile = (req.query.senderProfile as string) || "";
      const triggeredBy   = (req.query.triggeredBy   as string) || "";
      const dateFrom      = (req.query.dateFrom      as string) || null;
      const dateTo        = (req.query.dateTo        as string) || null;

      const rows = await db.execute(sql`
        SELECT
          c.campaign_name,
          c.report_type,
          c.sender_profile,
          TO_CHAR(r.schedule_week_start, 'MM/DD/YYYY')                                   AS schedule_week_start,
          TO_CHAR(r.schedule_week_end,   'MM/DD/YYYY')                                   AS schedule_week_end,
          TO_CHAR(r.started_at AT TIME ZONE 'America/Chicago', 'MM/DD/YYYY HH12:MI AM')  AS run_date,
          r.triggered_by,
          r.status   AS run_status,
          r.id       AS run_id,
          COALESCE(
            NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''),
            u.email
          )           AS created_by,
          TO_CHAR(c.created_at AT TIME ZONE 'America/Chicago', 'MM/DD/YYYY HH12:MI AM') AS campaign_created_at,
          cust.customer_name,
          recip.name  AS recipient_name,
          d.recipient_email,
          d.status    AS delivery_status,
          TO_CHAR(d.sent_at AT TIME ZONE 'America/Chicago', 'MM/DD/YYYY HH12:MI AM')    AS sent_at,
          d.error_message,
          d.failure_type
        FROM account_report_run_deliveries d
        JOIN account_report_campaign_runs r    ON r.id    = d.run_id
        JOIN account_report_campaigns     c    ON c.id    = r.campaign_id
        JOIN customers                   cust  ON cust.id = d.account_id
        LEFT JOIN users u ON u.id = c.created_by_user_id
        LEFT JOIN account_report_campaign_recipients recip
          ON  recip.campaign_id = c.id
          AND recip.account_id  = d.account_id
          AND recip.email       = d.recipient_email
        WHERE
          (c.campaign_name  ILIKE ${search}
           OR cust.customer_name ILIKE ${search}
           OR d.recipient_email  ILIKE ${search})
          AND (${statusFilter}  = '' OR d.status         = ${statusFilter})
          AND (${senderProfile} = '' OR c.sender_profile = ${senderProfile})
          AND (${triggeredBy}   = '' OR r.triggered_by   = ${triggeredBy})
          ${dateFrom ? sql`AND r.started_at >= ${dateFrom}::date` : sql``}
          ${dateTo   ? sql`AND r.started_at <  (${dateTo}::date + interval '1 day')` : sql``}
        ORDER BY r.started_at DESC, cust.customer_name, d.recipient_email
      `);

      const data: any[] = (rows as any).rows ?? rows;
      const headers = [
        "Run Name","Campaign","Report Type","Sender Profile",
        "Schedule Week Start","Schedule Week End",
        "Run Date","Triggered By","Run Status","Run ID","Created By",
        "Account Name","Recipient Name","Recipient Email",
        "Delivery Status","Sent At","Failure Type","Error Message",
        "Opened","First Opened At","Open Count",
      ];
      const csvLine = (vals: string[]) =>
        vals.map(v => `"${(v ?? "").toString().replace(/"/g, '""')}"`).join(",");

      const buildRunName = (r: any): string => {
        if (r.report_type === "WEEKLY_ACCOUNT_SCHEDULE" || (r.campaign_name ?? "").includes("Weekly") || (r.campaign_name ?? "").includes("Driver Schedules")) {
          if (r.schedule_week_start) {
            const [mm, dd, yyyy] = r.schedule_week_start.split("/");
            return `Driver Schedules — ${mm}/${dd}/${yyyy}`;
          }
        }
        return r.campaign_name ?? "";
      };

      const lines = [
        csvLine(headers),
        ...data.map(r => csvLine([
          buildRunName(r),
          r.campaign_name    ?? "",  r.report_type      ?? "",  r.sender_profile    ?? "",
          r.schedule_week_start ?? "", r.schedule_week_end ?? "",
          r.run_date         ?? "",  r.triggered_by     ?? "",  r.run_status        ?? "",
          r.run_id           ?? "",  r.created_by       ?? "",
          r.customer_name    ?? "",  r.recipient_name   ?? "",  r.recipient_email   ?? "",
          r.delivery_status  ?? "",  r.sent_at          ?? "",  r.failure_type      ?? "",
          r.error_message    ?? "",
          "Not Tracked", "", "",
        ])),
      ];

      res.setHeader("Content-Type", "text/csv; charset=utf-8");
      res.setHeader("Content-Disposition",
        `attachment; filename="amr-delivery-history-${new Date().toISOString().split("T")[0]}.csv"`);
      res.send(lines.join("\r\n"));
    } catch (e: any) {
      console.error("[AMR] delivery-history export error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/admin/amr-delivery-history/test-send
  // Controlled internal test: sends a Weekly Account Schedule to one internal address only.
  // Creates campaign/run/delivery records so the Delivery History tab populates.
  // Never sends to customer/dealer recipients.
  app.post("/api/admin/amr-delivery-history/test-send", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const callerUser = await storage.getUser(userId);
      const ALLOWED = new Set(["super_user", "super_admin", "corporate", "corporate_admin"]);
      if (!callerUser || !ALLOWED.has(callerUser.role ?? "")) {
        return res.status(403).json({ message: "Access restricted. Allowed roles: Super Admin, Corporate Admin, Corporate." });
      }

      const { accountId, internalEmail, weekStart: wsOverride, weekEnd: weOverride } =
        req.body as { accountId: string; internalEmail: string; weekStart?: string; weekEnd?: string };

      if (!accountId)     return res.status(400).json({ message: "accountId is required" });
      if (!internalEmail) return res.status(400).json({ message: "internalEmail is required" });

      // Safety: reject non-internal domains
      const ALLOWED_INTERNAL_DOMAINS = ["driverondemand.co", "driverondemand.com"];
      const emailDomain = internalEmail.split("@")[1]?.toLowerCase() ?? "";
      if (!ALLOWED_INTERNAL_DOMAINS.includes(emailDomain)) {
        return res.status(400).json({ message: `internalEmail must be a Driver on Demand address (@driverondemand.co or @driverondemand.com). Got: ${internalEmail}` });
      }

      const { getUpcomingWeekBounds } = await import("./services/weeklyGenerationService");
      const { weekStart: ws, weekEnd: we } = wsOverride && weOverride
        ? { weekStart: wsOverride, weekEnd: weOverride }
        : getUpcomingWeekBounds();

      // Resolve account
      const accRaw = await db.execute(sql`
        SELECT c.id, c.customer_name, c.driver_model, c.report_sender_profile,
               (SELECT COUNT(*) FROM driver_accounts da
                INNER JOIN drivers d ON d.id = da.driver_id
                WHERE da.account_id = c.id
                  AND da.assignment_ended_at IS NULL
                  AND LOWER(d.status) = 'active') AS active_driver_count
        FROM customers c
        WHERE c.id = ${accountId} AND c.is_deleted = false LIMIT 1
      `);
      const acc: any = ((accRaw as any).rows ?? accRaw)[0];
      if (!acc) return res.status(404).json({ message: "Account not found" });

      const driverCount = parseInt(acc.active_driver_count ?? "0", 10);
      if (driverCount < 1) {
        return res.status(422).json({ message: `${acc.customer_name} has no active drivers — cannot generate schedule PDF` });
      }

      // Find or create the "Internal Test Campaign"
      let campaignId: string;
      const existingCamp = await db.execute(sql`
        SELECT id FROM account_report_campaigns WHERE campaign_name = 'Internal Test Campaign' LIMIT 1
      `);
      const existingRow: any = ((existingCamp as any).rows ?? existingCamp)[0];
      if (existingRow) {
        campaignId = existingRow.id;
      } else {
        const newCamp = await db.execute(sql`
          INSERT INTO account_report_campaigns
            (campaign_name, report_type, sender_profile, status, schedule_type, timezone, created_by_user_id)
          VALUES
            ('Internal Test Campaign', 'WEEKLY_ACCOUNT_SCHEDULE', 'Reports', 'active', 'manual', 'America/Chicago', ${req.user?.claims?.sub ?? null})
          RETURNING id
        `);
        campaignId = ((newCamp as any).rows ?? newCamp)[0].id;
      }

      // Create the run record (status = sending → we'll update to completed/failed)
      const runInsert = await db.execute(sql`
        INSERT INTO account_report_campaign_runs
          (campaign_id, run_type, status, total_accounts, delivered_count, failed_count,
           not_sent_count, blocked_count, schedule_week_start, schedule_week_end,
           triggered_by, started_at)
        VALUES
          (${campaignId}, 'manual', 'sending', 1, 0, 0, 0, 0,
           ${ws}::date, ${we}::date, 'internal_test', now())
        RETURNING id
      `);
      const runId: string = ((runInsert as any).rows ?? runInsert)[0].id;

      // Generate PDF
      let pdfBuffer: Buffer | null = null;
      let pdfError: string | null = null;
      let pdfFileName = "";
      try {
        const { generateSchedulePdf } = await import("./services/scheduleReportPdfService");
        const pdfResult = await generateSchedulePdf({
          customerId: accountId, accountName: acc.customer_name, weekStart: ws, weekEnd: we,
        });
        if (pdfResult.buffer.length > 100) {
          pdfBuffer   = pdfResult.buffer;
          pdfFileName = pdfResult.fileName;
        } else {
          pdfError = "PDF generated but appears empty (no schedule data this week)";
        }
      } catch (e: any) {
        pdfError = `PDF generation failed: ${e.message}`;
      }

      // Send email — internal only
      let emailOk = false;
      let emailError: string | null = null;
      let providerMessageId: string | null = null;
      let sentAt: Date | null = null;

      if (!pdfBuffer) {
        emailError = pdfError ?? "No PDF available — email skipped";
      } else {
        const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
        if (!isMicrosoftGraphConfigured()) {
          emailError = "Microsoft Graph not configured — email skipped";
        } else {
          const slug      = acc.customer_name.replace(/[^a-z0-9]/gi, "_");
          const weekLabel = ws.replace(/-/g, "");
          const subject   = `[INTERNAL TEST] Upcoming Week Driver Schedule – ${acc.customer_name} – Week of ${ws}`;
          const bodyHtml  = `<p>This is an internal test delivery from DriverHub 360.</p>
<p>Account: <strong>${acc.customer_name}</strong></p>
<p>Schedule week: ${ws} – ${we}</p>
<p>This email was sent to <strong>${internalEmail}</strong> only. No customer/dealer recipients were contacted.</p>`;
          try {
            const r = await sendEmail({
              to:          [internalEmail],
              subject,
              bodyHtml,
              attachments: [{
                name:         `Schedule_${slug}_${weekLabel}.pdf`,
                contentType:  "application/pdf",
                contentBytes: pdfBuffer.toString("base64"),
              }],
            });
            if (r.ok) {
              emailOk          = true;
              sentAt           = new Date();
              providerMessageId = (r as any).messageId ?? null;
            } else {
              emailError = r.error ?? "Send failed";
            }
          } catch (e: any) {
            emailError = e.message;
          }
        }
      }

      // Write to account_report_logs
      const overallStatus = emailOk ? "success" : pdfBuffer ? "partial" : "failed";
      await db.execute(sql`
        INSERT INTO account_report_logs
          (account_id, report_week, pdf_generated, excel_generated, status, error_message,
           triggered_by, email_sent, email_sent_at, email_status, email_error_message, recipients_json)
        VALUES
          (${accountId}, ${ws}::date,
           ${pdfBuffer !== null}, false,
           ${overallStatus}, ${emailError},
           'internal_test',
           ${emailOk}, ${sentAt ? sentAt.toISOString() : null}::timestamptz,
           ${emailOk ? "success" : "failed"}, ${emailError},
           ${JSON.stringify([internalEmail])})
        ON CONFLICT DO NOTHING
      `);

      // Write to account_report_run_deliveries
      const deliveryStatus = emailOk ? "delivered" : "failed";
      const delInsert = await db.execute(sql`
        INSERT INTO account_report_run_deliveries
          (run_id, account_id, status, recipient_email, sent_at, error_message, provider_message_id)
        VALUES
          (${runId}, ${accountId}, ${deliveryStatus},
           ${internalEmail},
           ${sentAt ? sentAt.toISOString() : null}::timestamptz,
           ${emailError},
           ${providerMessageId})
        RETURNING id
      `);
      const deliveryId: string = ((delInsert as any).rows ?? delInsert)[0].id;

      // Update run record with final counts
      await db.execute(sql`
        UPDATE account_report_campaign_runs
        SET status          = ${emailOk ? "completed" : "failed"},
            delivered_count = ${emailOk ? 1 : 0},
            failed_count    = ${emailOk ? 0 : 1},
            completed_at    = now()
        WHERE id = ${runId}
      `);

      res.json({
        ok:               emailOk,
        campaignId,
        runId,
        deliveryId,
        account:          acc.customer_name,
        accountId,
        weekStart:        ws,
        weekEnd:          we,
        internalEmail,
        pdfGenerated:     pdfBuffer !== null,
        emailStatus:      emailOk ? "delivered" : "failed",
        emailError,
        sentAt:           sentAt?.toISOString() ?? null,
        overallStatus,
        message:          emailOk
          ? `Test delivery succeeded. Email sent to ${internalEmail}. Run ID: ${runId}`
          : `Test delivery failed. ${emailError}. Run ID: ${runId} still recorded for UI verification.`,
      });
    } catch (e: any) {
      console.error("[AMR] test-send error:", e?.message);
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/admin/run-generation-job  (manual full batch trigger)
  app.post("/api/admin/run-generation-job", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });
      const { weekStart, weekEnd } = req.body as { weekStart?: string; weekEnd?: string };
      const { runWeeklyGenerationBatch } = await import("./services/weeklyGenerationService");
      const result = await runWeeklyGenerationBatch({ weekStart, weekEnd, triggeredBy: "manual" });
      res.json(result);
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // GET /api/customers/:id/report-delivery-logs
  app.get("/api/customers/:id/report-delivery-logs", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const limit = Math.min(parseInt((req.query.limit as string) || "50", 10), 200);
      const rows = await db.execute(sql`
        SELECT id, customer_id, report_week_start, report_week_end,
               status, email_to, email_cc, error_message, attachment_count,
               sent_at, created_at
        FROM report_delivery_logs
        WHERE customer_id = ${req.params.id}
        ORDER BY created_at DESC
        LIMIT ${limit}
      `);
      res.json(((rows as any).rows ?? rows));
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // GET /api/customers/:id/report-preview/pdf  (inline PDF preview — same template as email)
  app.get("/api/customers/:id/report-preview/pdf", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { weekStart, weekEnd } = req.query as { weekStart?: string; weekEnd?: string };
      const { pool } = await import("./db");
      const accRaw = await pool.query(`SELECT customer_name FROM customers WHERE id = $1 LIMIT 1`, [req.params.id]);
      if (!accRaw.rows[0]) return res.status(404).json({ message: "Account not found" });
      const accountName = accRaw.rows[0].customer_name;
      const ws = weekStart ?? (() => { const d = new Date(); const dow = d.getDay(); d.setDate(d.getDate() + (dow === 0 ? -6 : 1 - dow)); return d.toISOString().split("T")[0]; })();
      const weDate = new Date(ws + "T00:00:00Z"); weDate.setUTCDate(weDate.getUTCDate() + 6);
      const we = weekEnd ?? weDate.toISOString().split("T")[0];
      const { generateSchedulePdf } = await import("./services/scheduleReportPdfService");
      const result = await generateSchedulePdf({ customerId: req.params.id, accountName, weekStart: ws, weekEnd: we });
      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `inline; filename="${result.fileName}"`);
      res.setHeader("X-Shift-Count", String(result.shiftCount));
      res.setHeader("X-Driver-Count", String(result.driverCount));
      res.send(result.buffer);
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // POST /api/customers/:id/report-delivery/send  (manual trigger)
  app.post("/api/customers/:id/report-delivery/send", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { weekStart, weekEnd, recipientOverrides, ccOverrides } = req.body as {
        weekStart?: string;
        weekEnd?: string;
        recipientOverrides?: string[];
        ccOverrides?: string[];
      };
      const { sendAccountWeeklyReport } = await import("./services/weeklyReportService");
      const result = await sendAccountWeeklyReport(req.params.id, weekStart, weekEnd, {
        recipientEmails: recipientOverrides,
        ccEmails: ccOverrides,
      });
      if (result.status === "success") {
        res.json({ success: true, ...result });
      } else if (result.status === "skipped") {
        res.json({ success: false, skipped: true, ...result });
      } else if (result.status === "blocked") {
        res.status(503).json({
          success: false,
          blocked: true,
          error: result.error,
          blockedChecks: result.blockedChecks,
          message: result.error ?? "Report delivery blocked. Microsoft 365 Email integration is not fully operational.",
        });
      } else {
        res.status(500).json({ success: false, ...result });
      }
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // GET /api/customers/:id/report-delivery/log  (delivery history — reads account_report_logs)
  app.get("/api/customers/:id/report-delivery/log", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const limit = Math.min(Number(req.query.limit ?? 20), 50);
      const { pool } = await import("./db");
      const rows = await pool.query(
        `SELECT id, account_id, report_week, email_status, email_sent_at,
                email_error_message, recipients_json, triggered_by, created_at
         FROM account_report_logs
         WHERE account_id = $1
           AND email_sent = true
         ORDER BY created_at DESC
         LIMIT $2`,
        [req.params.id, limit],
      );
      res.json(rows.rows.map((r: any) => {
        let recipientCount = 0;
        try { recipientCount = JSON.parse(r.recipients_json ?? "[]").length; } catch {}
        // Compute week end (report_week is always the Monday start)
        const ws = r.report_week instanceof Date
          ? r.report_week.toISOString().split("T")[0]
          : String(r.report_week).split("T")[0];
        const weDate = new Date(ws + "T12:00:00Z");
        weDate.setUTCDate(weDate.getUTCDate() + 6);
        const we = weDate.toISOString().split("T")[0];
        return {
          id:              r.id,
          reportWeekStart: ws,
          reportWeekEnd:   we,
          status:          r.email_status ?? "skipped",
          sentAt:          r.email_sent_at,
          errorMessage:    r.email_error_message,
          recipientCount,
          triggeredBy:     r.triggered_by,
          createdAt:       r.created_at,
        };
      }));
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── Account Analytics ────────────────────────────────────────────────────────

  // GET /api/customers/:id/analytics/weekly
  // Returns prior-week (or specified week) operational analytics for one account
  app.get("/api/customers/:id/analytics/weekly", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const { weekStart: weekStartParam, driverType = "all" } = req.query as {
        weekStart?: string;
        driverType?: string;
      };

      // Compute default prior-week bounds (Mon–Sun)
      function priorWeekBounds(): { start: string; end: string } {
        const now = new Date();
        const dow = now.getDay(); // 0=Sun
        const daysToMon = dow === 0 ? 6 : dow - 1;
        const thisMonday = new Date(now);
        thisMonday.setDate(now.getDate() - daysToMon);
        thisMonday.setHours(0, 0, 0, 0);
        const priorMon = new Date(thisMonday);
        priorMon.setDate(thisMonday.getDate() - 7);
        const priorSun = new Date(priorMon);
        priorSun.setDate(priorMon.getDate() + 7);
        return {
          start: priorMon.toISOString().slice(0, 10),
          end: priorSun.toISOString().slice(0, 10),
        };
      }

      let weekStartStr: string, weekEndStr: string;
      if (weekStartParam) {
        weekStartStr = weekStartParam;
        const d = new Date(weekStartParam + "T00:00:00Z");
        d.setDate(d.getDate() + 7);
        weekEndStr = d.toISOString().slice(0, 10);
      } else {
        const b = priorWeekBounds();
        weekStartStr = b.start;
        weekEndStr = b.end;
      }

      // Driver type WHERE clause (only for utilization table)
      const dtFilter =
        driverType === "employee"
          ? "AND COALESCE(d.driver_type, 'unknown') = 'employee'"
          : driverType === "ic"
          ? "AND COALESCE(d.driver_type, 'unknown') IN ('independent_contractor','ic')"
          : "";

      // Resolve account timezone: WIW location → explicit customer tz → state-derived → Eastern
      const acctTzRes = await pool.query(
        `SELECT COALESCE(
           (SELECT wl.timezone FROM wiw_locations wl WHERE wl.account_id = $1 AND wl.timezone IS NOT NULL ORDER BY wl.created_at LIMIT 1),
           (SELECT NULLIF(TRIM(c.timezone), '') FROM customers c WHERE c.id = $1 LIMIT 1),
           (SELECT CASE UPPER(COALESCE(c2.customer_state,''))
              WHEN 'AK' THEN 'America/Anchorage' WHEN 'HI' THEN 'Pacific/Honolulu'
              WHEN 'CA' THEN 'America/Los_Angeles' WHEN 'OR' THEN 'America/Los_Angeles'
              WHEN 'WA' THEN 'America/Los_Angeles' WHEN 'NV' THEN 'America/Los_Angeles'
              WHEN 'MT' THEN 'America/Denver' WHEN 'ID' THEN 'America/Denver'
              WHEN 'WY' THEN 'America/Denver' WHEN 'CO' THEN 'America/Denver'
              WHEN 'UT' THEN 'America/Denver' WHEN 'NM' THEN 'America/Denver'
              WHEN 'AZ' THEN 'America/Phoenix'
              WHEN 'ND' THEN 'America/Chicago' WHEN 'SD' THEN 'America/Chicago'
              WHEN 'NE' THEN 'America/Chicago' WHEN 'KS' THEN 'America/Chicago'
              WHEN 'OK' THEN 'America/Chicago' WHEN 'TX' THEN 'America/Chicago'
              WHEN 'MN' THEN 'America/Chicago' WHEN 'IA' THEN 'America/Chicago'
              WHEN 'MO' THEN 'America/Chicago' WHEN 'AR' THEN 'America/Chicago'
              WHEN 'LA' THEN 'America/Chicago' WHEN 'WI' THEN 'America/Chicago'
              WHEN 'IL' THEN 'America/Chicago' WHEN 'MS' THEN 'America/Chicago'
              WHEN 'AL' THEN 'America/Chicago' WHEN 'TN' THEN 'America/Chicago'
              WHEN 'IN' THEN 'America/Indiana/Indianapolis'
              ELSE 'America/New_York'
            END FROM customers c2 WHERE c2.id = $1 LIMIT 1)
         ) AS tz`,
        [id]
      );
      const acctTz: string = acctTzRes.rows[0]?.tz ?? "America/New_York";

      // --- KPI: totals from wiw_times ---
      const kpiRes = await pool.query(
        `SELECT
           COUNT(DISTINCT t.wiw_user_id)::int AS total_drivers,
           ROUND(COALESCE(SUM(t.total_minutes), 0) / 60.0, 1) AS worked_hours
         FROM wiw_times t
         JOIN wiw_locations wl ON wl.id = t.wiw_location_id
         WHERE wl.account_id = $1
           AND t.clock_in >= $2::date AND t.clock_in < $3::date`,
        [id, weekStartStr, weekEndStr]
      );

      // --- KPI: scheduled hours from wiw_shifts ---
      const schedRes = await pool.query(
        `SELECT ROUND(COALESCE(SUM(s.scheduled_minutes), 0) / 60.0, 1) AS scheduled_hours
         FROM wiw_shifts s
         JOIN wiw_locations wl ON wl.id = s.wiw_location_id
         WHERE wl.account_id = $1
           AND s.start_time >= $2::date AND s.start_time < $3::date
           AND s.status NOT IN ('deleted','cancelled')`,
        [id, weekStartStr, weekEndStr]
      );

      // --- KPI: employee OT (>40h/week) ---
      const otRes = await pool.query(
        `WITH dh AS (
           SELECT t.wiw_user_id, SUM(t.total_minutes) / 60.0 AS total_hours
           FROM wiw_times t
           JOIN wiw_locations wl ON wl.id = t.wiw_location_id
           JOIN wiw_users wu ON wu.id = t.wiw_user_id
           JOIN drivers d ON d.id = wu.driver_id
           WHERE wl.account_id = $1
             AND t.clock_in >= $2::date AND t.clock_in < $3::date
             AND d.driver_type = 'employee'
           GROUP BY t.wiw_user_id
         )
         SELECT
           ROUND(COALESCE(SUM(GREATEST(total_hours - 40, 0)), 0), 1) AS ot_hours,
           COUNT(CASE WHEN total_hours > 40 THEN 1 END)::int AS ot_driver_count,
           COUNT(*)::int AS employee_driver_count
         FROM dh`,
        [id, weekStartStr, weekEndStr]
      );

      // --- Hours by day (worked) ---
      const dayRes = await pool.query(
        `SELECT
           EXTRACT(DOW FROM t.clock_in AT TIME ZONE '${acctTz}')::int AS dow,
           TO_CHAR(t.clock_in AT TIME ZONE '${acctTz}', 'Dy') AS day_abbr,
           COUNT(DISTINCT t.wiw_user_id)::int AS driver_count,
           ROUND(COALESCE(SUM(t.total_minutes), 0) / 60.0, 1) AS worked_hours
         FROM wiw_times t
         JOIN wiw_locations wl ON wl.id = t.wiw_location_id
         WHERE wl.account_id = $1
           AND t.clock_in >= $2::date AND t.clock_in < $3::date
         GROUP BY 1, 2 ORDER BY 1`,
        [id, weekStartStr, weekEndStr]
      );

      // --- Scheduled hours by day ---
      const schedDayRes = await pool.query(
        `SELECT
           EXTRACT(DOW FROM s.start_time AT TIME ZONE '${acctTz}')::int AS dow,
           ROUND(COALESCE(SUM(s.scheduled_minutes), 0) / 60.0, 1) AS scheduled_hours
         FROM wiw_shifts s
         JOIN wiw_locations wl ON wl.id = s.wiw_location_id
         WHERE wl.account_id = $1
           AND s.start_time >= $2::date AND s.start_time < $3::date
           AND s.status NOT IN ('deleted','cancelled')
         GROUP BY 1 ORDER BY 1`,
        [id, weekStartStr, weekEndStr]
      );

      // --- Driver utilization table ---
      const utilRes = await pool.query(
        `WITH dh AS (
           SELECT
             t.wiw_user_id,
             wu.name AS driver_name,
             COALESCE(d.driver_type, 'unknown') AS driver_type,
             SUM(t.total_minutes) / 60.0 AS total_hours
           FROM wiw_times t
           JOIN wiw_locations wl ON wl.id = t.wiw_location_id
           JOIN wiw_users wu ON wu.id = t.wiw_user_id
           LEFT JOIN drivers d ON d.id = wu.driver_id
           WHERE wl.account_id = $1
             AND t.clock_in >= $2::date AND t.clock_in < $3::date
             ${dtFilter}
           GROUP BY t.wiw_user_id, wu.name, d.driver_type
         )
         SELECT
           driver_name,
           driver_type,
           ROUND(total_hours, 1) AS worked_hours,
           ROUND(GREATEST(total_hours - 40, 0), 1) AS ot_hours,
           CASE WHEN total_hours > 40 AND driver_type = 'employee' THEN 'OT' ELSE 'Normal' END AS status
         FROM dh
         ORDER BY total_hours DESC
         LIMIT 100`,
        [id, weekStartStr, weekEndStr]
      );

      // --- OT Concentration: top 5 employee drivers ---
      const otConcRes = await pool.query(
        `WITH dh AS (
           SELECT
             wu.name AS driver_name,
             SUM(t.total_minutes) / 60.0 AS total_hours
           FROM wiw_times t
           JOIN wiw_locations wl ON wl.id = t.wiw_location_id
           JOIN wiw_users wu ON wu.id = t.wiw_user_id
           JOIN drivers d ON d.id = wu.driver_id
           WHERE wl.account_id = $1
             AND t.clock_in >= $2::date AND t.clock_in < $3::date
             AND d.driver_type = 'employee'
           GROUP BY wu.name
         ),
         total AS (SELECT SUM(total_hours) AS all_hours FROM dh)
         SELECT
           driver_name,
           ROUND(GREATEST(total_hours - 40, 0), 1) AS ot_hours,
           ROUND(total_hours, 1) AS total_hours,
           ROUND(total_hours / NULLIF((SELECT all_hours FROM total), 0) * 100, 1) AS hours_pct
         FROM dh
         WHERE total_hours > 40
         ORDER BY ot_hours DESC
         LIMIT 5`,
        [id, weekStartStr, weekEndStr]
      );

      // Build Mon–Sun hoursByDay array (DOW: 1=Mon … 6=Sat, 0=Sun)
      const DOW_ORDER = [1, 2, 3, 4, 5, 6, 0];
      const DAY_LABELS: Record<number, string> = {
        1: "Mon", 2: "Tue", 3: "Wed", 4: "Thu", 5: "Fri", 6: "Sat", 0: "Sun",
      };
      const workedByDow: Record<number, { worked: number; count: number }> = {};
      for (const r of dayRes.rows)
        workedByDow[+r.dow] = { worked: parseFloat(r.worked_hours), count: r.driver_count };
      const schedByDow: Record<number, number> = {};
      for (const r of schedDayRes.rows)
        schedByDow[+r.dow] = parseFloat(r.scheduled_hours);
      const hoursByDay = DOW_ORDER.map((dow) => ({
        day: DAY_LABELS[dow],
        scheduledHours: schedByDow[dow] ?? 0,
        workedHours: workedByDow[dow]?.worked ?? 0,
        driverCount: workedByDow[dow]?.count ?? 0,
      }));

      const kpi = kpiRes.rows[0] || {};
      const ot = otRes.rows[0] || {};
      const empDrivers = parseInt(ot.employee_driver_count ?? "0", 10);
      const otDriverCt = parseInt(ot.ot_driver_count ?? "0", 10);

      res.json({
        weekStart: weekStartStr,
        weekEnd: weekEndStr,
        kpi: {
          totalDrivers: parseInt(kpi.total_drivers ?? "0", 10),
          workedHours: parseFloat(kpi.worked_hours ?? "0"),
          scheduledHours: parseFloat(schedRes.rows[0]?.scheduled_hours ?? "0"),
          employeeOtHours: parseFloat(ot.ot_hours ?? "0"),
          otPct: empDrivers > 0 ? Math.round((otDriverCt / empDrivers) * 100) : 0,
          otDriverCount: otDriverCt,
          employeeDriverCount: empDrivers,
        },
        hoursByDay,
        driverUtilization: utilRes.rows.map((r) => ({
          name: r.driver_name,
          driverType: r.driver_type,
          workedHours: parseFloat(r.worked_hours),
          otHours: parseFloat(r.ot_hours),
          status: r.status,
        })),
        otConcentration: otConcRes.rows.map((r) => ({
          name: r.driver_name,
          otHours: parseFloat(r.ot_hours),
          totalHours: parseFloat(r.total_hours),
          hoursPct: parseFloat(r.hours_pct),
        })),
      });
    } catch (e: any) {
      console.error("Error fetching account analytics:", e);
      res.status(500).json({ message: e.message });
    }
  });

