  // GET /api/admin/report-delivery-monitor/stats
  app.get("/api/admin/report-delivery-monitor/stats", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { dateFrom, dateTo, accountId } = req.query as Record<string, string>;
      const { pool } = await import("./db");
      const batchWhere: string[] = ["1=1"];
      const batchParams: any[] = [];
      if (dateFrom) { batchParams.push(dateFrom); batchWhere.push(`created_at >= $${batchParams.length}`); }
      if (dateTo)   { batchParams.push(dateTo + " 23:59:59"); batchWhere.push(`created_at <= $${batchParams.length}`); }
      if (accountId && accountId !== "all") { batchParams.push(accountId); batchWhere.push(`account_id = $${batchParams.length}`); }
      const batchQ = await pool.query(
        `SELECT
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE status = 'success')::int AS successes,
          COUNT(*) FILTER (WHERE status IN ('failed','error'))::int AS failures
         FROM account_report_logs WHERE ${batchWhere.join(" AND ")}`,
        batchParams,
      );
      const emailWhere: string[] = ["1=1"];
      const emailParams: any[] = [];
      if (dateFrom) { emailParams.push(dateFrom); emailWhere.push(`created_at >= $${emailParams.length}`); }
      if (dateTo)   { emailParams.push(dateTo + " 23:59:59"); emailWhere.push(`created_at <= $${emailParams.length}`); }
      if (accountId && accountId !== "all") { emailParams.push(accountId); emailWhere.push(`customer_id = $${emailParams.length}`); }
      const emailQ = await pool.query(
        `SELECT
          COUNT(*)::int AS total,
          COUNT(*) FILTER (WHERE status IN ('failed','error'))::int AS failures
         FROM report_delivery_logs WHERE ${emailWhere.join(" AND ")}`,
        emailParams,
      );
      const b = batchQ.rows[0];
      const e = emailQ.rows[0];
      res.json({
        batchTotal:   b.total,
        batchSuccess: b.successes,
        batchFailed:  b.failures,
        emailTotal:   e.total,
        emailFailed:  e.failures,
      });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

