  // PATCH /api/reports/custom/:id — update report
  app.patch("/api/reports/custom/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { pool } = await import("./db");

      const { id } = req.params;
      const existing = await pool.query(`SELECT * FROM custom_reports WHERE id = $1`, [id]);
      if (!existing.rows.length) return res.status(404).json({ message: "Report not found" });
      const report = existing.rows[0];
      const isAdmin = ["super_admin", "super_user", "admin", "corporate_admin"].includes(user?.role || "");
      if (report.owner_id !== userId && !isAdmin) return res.status(403).json({ message: "Cannot edit this report" });

      const { name, description, subject, isPublic, config, scheduledCron, scheduleEnabled, nextRunAt } = req.body;
      const result = await pool.query(`
        UPDATE custom_reports SET
          name = COALESCE($1, name),
          description = COALESCE($2, description),
          subject = COALESCE($3, subject),
          is_public = COALESCE($4, is_public),
          config = COALESCE($5::jsonb, config),
          scheduled_cron = COALESCE($6, scheduled_cron),
          schedule_enabled = COALESCE($7, schedule_enabled),
          next_run_at = COALESCE($8, next_run_at),
          updated_at = now()
        WHERE id = $9
        RETURNING *
      `, [name || null, description ?? null, subject || null, isPublic ?? null,
          config ? JSON.stringify(config) : null,
          scheduledCron ?? null, scheduleEnabled ?? null, nextRunAt ?? null, id]);

      res.json(result.rows[0]);
    } catch (e: any) {
      console.error("[reports/custom PATCH]", e);
      res.status(500).json({ message: "Failed to update report" });
    }
  });

