  // PATCH /api/weekly-report-recipients/:id
  app.patch("/api/weekly-report-recipients/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const body = req.body as Record<string, any>;
      const sets: string[] = [];
      const vals: any[] = [];
      const add = (col: string, val: any) => { sets.push(`${col} = $${vals.length + 1}`); vals.push(val); };
      if ("recipientName"  in body) add("recipient_name",  body.recipientName ?? null);
      if ("recipientEmail" in body) {
        if (!EMAIL_RE.test(body.recipientEmail)) return res.status(400).json({ message: "Valid email required" });
        add("recipient_email", body.recipientEmail.trim().toLowerCase());
      }
      if ("recipientType" in body) add("recipient_type", (body.recipientType ?? "TO").toUpperCase());
      if ("active"        in body) add("active",          body.active);
      if ("notes"         in body) add("notes",           body.notes ?? null);
      if (sets.length === 0) return res.json({ success: true });
      sets.push(`updated_at = NOW()`);
      const { pool } = await import("./db");
      await pool.query(
        `UPDATE weekly_report_recipients SET ${sets.join(", ")} WHERE id = $${vals.length + 1}`,
        [...vals, req.params.id],
      );
      res.json({ success: true });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

