  // POST /api/weekly-report-recipients/import/validate
  // Accepts parsed rows from client, validates + matches accounts, returns preview
  app.post("/api/weekly-report-recipients/import/validate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { rows } = req.body as { rows: Array<Record<string, any>> };
      if (!Array.isArray(rows) || rows.length === 0) return res.status(400).json({ message: "No rows provided" });
      const { pool } = await import("./db");

      // Load all eligible accounts (DriverShift + Hybrid) once
      const accResult = await pool.query(
        `SELECT id, customer_name FROM customers WHERE is_deleted = false ORDER BY customer_name`,
      );
      const accById   = new Map(accResult.rows.map(r => [r.id, r.customer_name]));
      const accByName = new Map(accResult.rows.map(r => [r.customer_name.toLowerCase().trim(), r.id]));

      // Load existing recipients for dup check
      const existResult = await pool.query(
        `SELECT account_id, lower(recipient_email) as email, recipient_type FROM weekly_report_recipients`,
      );
      const existSet = new Set(existResult.rows.map(r => `${r.account_id}|${r.email}|${r.recipient_type}`));

      // Track duplicates within the import batch
      const batchSet = new Set<string>();

      const validated = rows.map((raw, idx) => {
        const errors: string[] = [];
        const warnings: string[] = [];

        // Normalize field lookup (case-insensitive key matching)
        const get = (keys: string[]): string => {
          for (const k of keys) {
            for (const [rk, rv] of Object.entries(raw)) {
              if (rk.trim().toLowerCase() === k.toLowerCase() && rv !== null && rv !== undefined && String(rv).trim() !== "") {
                return String(rv).trim();
              }
            }
          }
          return "";
        };

        const rawAccountRef  = get(["account id", "accountid", "account_id"]);
        const rawAccountName = get(["account name", "accountname", "account_name"]);
        const recipientName  = get(["recipient name", "recipientname", "recipient_name", "name"]);
        const recipientEmail = get(["recipient email", "recipientemail", "recipient_email", "email"]);
        const rawType        = get(["recipient type", "recipienttype", "recipient_type", "type"]) || "TO";
        const rawActive      = get(["active"]);
        const notes          = get(["notes"]);

        const recipientType = rawType.trim().toUpperCase() === "CC" ? "CC" : "TO";
        const active = rawActive === "" || ["yes", "true", "1", "y"].includes(rawActive.toLowerCase());

        // Validate email
        if (!recipientEmail) {
          errors.push("Email is required");
        } else if (!EMAIL_RE.test(recipientEmail)) {
          errors.push(`Invalid email: "${recipientEmail}"`);
        }

        // Resolve account
        let accountId: string | null = null;
        let accountName: string | null = null;
        if (rawAccountRef && accById.has(rawAccountRef)) {
          accountId = rawAccountRef;
          accountName = accById.get(rawAccountRef) ?? null;
        } else if (rawAccountRef && accByName.has(rawAccountRef.toLowerCase())) {
          accountId = accByName.get(rawAccountRef.toLowerCase()) ?? null;
          accountName = accById.get(accountId!) ?? null;
        } else if (rawAccountName && accByName.has(rawAccountName.toLowerCase())) {
          accountId = accByName.get(rawAccountName.toLowerCase()) ?? null;
          accountName = accById.get(accountId!) ?? null;
        } else if (rawAccountRef || rawAccountName) {
          errors.push(`Account not found: "${rawAccountRef || rawAccountName}"`);
        } else {
          warnings.push("No account specified — recipient will be unassigned");
        }

        // Duplicate check: within batch
        const batchKey = `${accountId ?? ""}|${recipientEmail.toLowerCase()}|${recipientType}`;
        if (recipientEmail && EMAIL_RE.test(recipientEmail)) {
          if (batchSet.has(batchKey)) {
            errors.push("Duplicate row within this import file");
          } else {
            batchSet.add(batchKey);
          }
        }

        // Duplicate check: existing in DB
        if (accountId && recipientEmail && EMAIL_RE.test(recipientEmail)) {
          const dbKey = `${accountId}|${recipientEmail.toLowerCase()}|${recipientType}`;
          if (existSet.has(dbKey)) {
            warnings.push("Already exists in database — will be skipped");
          }
        }

        const status = errors.length > 0 ? "invalid"
          : warnings.some(w => w.startsWith("Already exists")) ? "duplicate"
          : "valid";

        return {
          rowIndex:      idx + 1,
          accountId,
          accountName,
          recipientName: recipientName || null,
          recipientEmail,
          recipientType,
          active,
          notes:         notes || null,
          status,
          errors,
          warnings,
        };
      });

      const counts = validated.reduce(
        (acc, r) => { acc[r.status] = (acc[r.status] ?? 0) + 1; return acc; },
        {} as Record<string, number>,
      );
      res.json({ rows: validated, counts });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // POST /api/weekly-report-recipients/import/commit
  app.post("/api/weekly-report-recipients/import/commit", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { rows } = req.body as { rows: Array<Record<string, any>> };
      if (!Array.isArray(rows) || rows.length === 0) return res.json({ inserted: 0, skipped: 0 });
      const validRows = rows.filter(r => r.status === "valid");
      if (validRows.length === 0) return res.json({ inserted: 0, skipped: rows.length });
      const { pool } = await import("./db");
      let inserted = 0;
      let skipped  = 0;
      for (const r of validRows) {
        const result = await pool.query(
          `INSERT INTO weekly_report_recipients (account_id, recipient_name, recipient_email, recipient_type, active, notes)
           VALUES ($1, $2, $3, $4, $5, $6)
           ON CONFLICT (account_id, lower(recipient_email), recipient_type) DO NOTHING
           RETURNING id`,
          [r.accountId ?? null, r.recipientName ?? null, r.recipientEmail.trim().toLowerCase(),
           r.recipientType ?? "TO", r.active !== false, r.notes ?? null],
        );
        if (result.rowCount! > 0) inserted++; else skipped++;
      }
      res.json({ inserted, skipped });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // ── Microsoft Graph Admin (Ticket 3.1) ───────────────────────────────────────
  // GET /api/integrations/microsoft-graph/status
  // Returns which env vars are set (without revealing values) + connectivity status
  app.get("/api/integrations/microsoft-graph/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { getEffectiveMs365Config } = await import("./services/microsoftGraphService");
      const cfg = await getEffectiveMs365Config();

      const envKeys = ["MICROSOFT_TENANT_ID", "MICROSOFT_CLIENT_ID", "MICROSOFT_CLIENT_SECRET", "MICROSOFT_SENDER_EMAIL"];
      const envStatus = Object.fromEntries([
        ...envKeys.map(k => [k, !!process.env[k]]),
        ["MICROSOFT_SENDER_OBJECT_ID", !!process.env.MICROSOFT_SENDER_OBJECT_ID],
      ]);
      const allConfigured = envKeys.every(k => !!process.env[k]);

      const mailboxIdentifier = cfg.senderObjectId ?? cfg.senderEmail;
      res.json({
        configured:     allConfigured,
        senderEmail:    cfg.senderEmail,
        senderObjectId: cfg.senderObjectId,
        envStatus,
        requiredVars: envKeys,
        permissions: ["Mail.Send"],
        authFlow:    "OAuth2 Client Credentials (app-level)",
        endpoint:    mailboxIdentifier
          ? `https://graph.microsoft.com/v1.0/users/${mailboxIdentifier}/sendMail`
          : "https://graph.microsoft.com/v1.0/users/{MICROSOFT_SENDER_EMAIL}/sendMail",
      });
    } catch (e: any) { res.status(500).json({ message: e.message }); }
  });

  // POST /api/integrations/microsoft-graph/test-connection
  // Attempts to acquire an OAuth token and verifies credentials are valid
  app.post("/api/integrations/microsoft-graph/test-connection", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const tenantId     = process.env.MICROSOFT_TENANT_ID;
      const clientId     = process.env.MICROSOFT_CLIENT_ID;
      const clientSecret = process.env.MICROSOFT_CLIENT_SECRET;

      if (!tenantId || !clientId || !clientSecret) {
        return res.json({ ok: false, error: "Missing MICROSOFT_TENANT_ID, MICROSOFT_CLIENT_ID, or MICROSOFT_CLIENT_SECRET" });
      }

      const tokenUrl = `https://login.microsoftonline.com/${tenantId}/oauth2/v2.0/token`;
      const body = new URLSearchParams({
        grant_type:    "client_credentials",
        client_id:     clientId,
        client_secret: clientSecret,
        scope:         "https://graph.microsoft.com/.default",
      });

      const tokenRes = await fetch(tokenUrl, {
        method:  "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body:    body.toString(),
      });

      if (!tokenRes.ok) {
        const text = await tokenRes.text();
        let detail = text;
        try { const j = JSON.parse(text); detail = j.error_description ?? j.error ?? text; } catch {}
        return res.json({ ok: false, error: `Token request failed (${tokenRes.status}): ${detail.slice(0, 300)}` });
      }

      const tokenData: any = await tokenRes.json();
      const expiresIn = tokenData.expires_in ?? 3600;

      res.json({
        ok:        true,
        tokenType: tokenData.token_type ?? "Bearer",
        expiresIn,
        message:   `OAuth token acquired successfully — expires in ${Math.round(expiresIn / 60)} minutes`,
      });
    } catch (e: any) {
      res.json({ ok: false, error: e.message });
    }
  });

  // POST /api/integrations/microsoft-graph/test-email
  // Runs pre-flight validation, then sends a real test email via Microsoft Graph.
  // Returns the updated ValidationResult so the UI checklist reflects the real outcome.
  // Logs every attempt to ms365_test_email_log. Super Admin only.
  app.post("/api/integrations/microsoft-graph/test-email", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { to, subject, message: bodyText, senderProfile } = req.body as {
        to?: string; subject?: string; message?: string; senderProfile?: string;
      };
      if (!to || !to.includes("@")) return res.status(400).json({ message: "Valid 'to' email address required" });

      const { sendTestEmail, VALID_MAILBOX_PROFILES } = await import("./services/microsoftGraphService");

      const resolvedProfile = senderProfile?.trim() || "Reports";
      if (!VALID_MAILBOX_PROFILES.includes(resolvedProfile)) {
        return res.status(400).json({ message: `Invalid senderProfile. Must be one of: ${VALID_MAILBOX_PROFILES.join(", ")}` });
      }

      const resolvedSubject = subject?.trim() || `DriverHub Microsoft 365 Email Test — ${resolvedProfile}`;
      const sentAtDisplay   = new Date().toLocaleString("en-US", { timeZone: "America/Chicago" });
      const bodyHtml = `<!DOCTYPE html>
<html><head><meta charset="utf-8"></head>
<body style="font-family: Arial, sans-serif; color: #333; padding: 30px;">
  <div style="background:#FF6B35;padding:20px 30px;border-radius:4px 4px 0 0;">
    <h1 style="color:#fff;margin:0;font-size:18px;">DriverHub 360 — Integration Test</h1>
  </div>
  <div style="border:1px solid #eee;border-top:none;padding:30px;border-radius:0 0 4px 4px;">
    <p>This is a test email sent from the <strong>${resolvedProfile}</strong> mailbox via the <strong>Microsoft Graph API</strong>.</p>
    ${bodyText?.trim() ? `<p><em>${bodyText.trim()}</em></p>` : "<p>This is a test email from DriverHub Microsoft 365 Email integration.</p>"}
    <p>If you received this, the <strong>${resolvedProfile}</strong> mailbox is configured and Mail.Send is working correctly.</p>
    <hr style="border:none;border-top:1px solid #eee;margin:20px 0;">
    <p style="font-size:12px;color:#888;">Sent at: ${sentAtDisplay} CT &bull; Mailbox: ${resolvedProfile}</p>
  </div>
</body></html>`;

      const result = await sendTestEmail(to, resolvedSubject, bodyHtml, ctx.userId ?? "unknown", resolvedProfile);
      res.json(result);
    } catch (e: any) {
      res.status(500).json({ ok: false, error: e.message });
    }
  });

