  // POST /api/integrations/microsoft-graph/update-config
  // Updates one or more Microsoft 365 configuration values (DB override).
  // Logs the change and re-runs validation. Super Admin only.
  app.post("/api/integrations/microsoft-graph/update-config", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { tenantId, clientId, clientSecret, senderEmail, senderObjectId } = req.body as {
        tenantId?: string;
        clientId?: string;
        clientSecret?: string;
        senderEmail?: string;
        senderObjectId?: string;
      };

      // At least one field required
      if (!tenantId && !clientId && !clientSecret && !senderEmail && !senderObjectId) {
        return res.status(400).json({ message: "No fields provided to update." });
      }

      // Basic format validation
      const GUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      if (tenantId !== undefined) {
        if (!tenantId.trim()) return res.status(400).json({ message: "Tenant ID cannot be blank." });
        if (!GUID_RE.test(tenantId.trim())) return res.status(400).json({ message: "Tenant ID must be a valid GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)." });
      }
      if (clientId !== undefined) {
        if (!clientId.trim()) return res.status(400).json({ message: "Client ID cannot be blank." });
        if (!GUID_RE.test(clientId.trim())) return res.status(400).json({ message: "Client ID must be a valid GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)." });
      }
      if (clientSecret !== undefined && !clientSecret.trim()) {
        return res.status(400).json({ message: "Client Secret cannot be blank." });
      }
      if (senderEmail !== undefined) {
        if (!senderEmail.trim()) return res.status(400).json({ message: "Sender Email cannot be blank." });
        if (!EMAIL_RE.test(senderEmail.trim())) return res.status(400).json({ message: "Sender Email must be a valid email address." });
      }
      if (senderObjectId !== undefined) {
        if (!senderObjectId.trim()) return res.status(400).json({ message: "Mailbox Object ID cannot be blank." });
        if (!GUID_RE.test(senderObjectId.trim())) return res.status(400).json({ message: "Mailbox Object ID must be a valid GUID (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx)." });
      }

      const { updateMs365Config, validateMicrosoft365EmailIntegration } = await import("./services/microsoftGraphService");

      const updates: Record<string, string> = {};
      if (tenantId)       updates.tenantId       = tenantId.trim();
      if (clientId)       updates.clientId       = clientId.trim();
      if (clientSecret)   updates.clientSecret   = clientSecret.trim();
      if (senderEmail)    updates.senderEmail    = senderEmail.trim();
      if (senderObjectId) updates.senderObjectId = senderObjectId.trim();

      await updateMs365Config(updates, ctx.userId ?? "unknown");

      // Auto re-run validation
      const validationResult = await validateMicrosoft365EmailIntegration(ctx.userId ?? undefined);

      res.json({ ok: true, validationResult });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // POST /api/integrations/microsoft-graph/update-mailbox-config
  // Overrides the email address for a single predefined sender profile.
  // Persists to ms365_mailbox_config, logs the change, re-runs validation. Super Admin only.
  app.post("/api/integrations/microsoft-graph/update-mailbox-config", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      if (!ctx.isSuperAdmin) return res.status(403).json({ message: "Super admin required" });

      const { profile, email } = req.body as { profile?: string; email?: string };
      if (!profile || !email) {
        return res.status(400).json({ message: "Both 'profile' and 'email' are required." });
      }

      const { VALID_MAILBOX_PROFILES, updateMailboxProfileEmail, validateMicrosoft365EmailIntegration } =
        await import("./services/microsoftGraphService");

      if (!VALID_MAILBOX_PROFILES.includes(profile as any)) {
        return res.status(400).json({
          message: `Invalid profile. Must be one of: ${VALID_MAILBOX_PROFILES.join(", ")}.`,
        });
      }

      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      if (!EMAIL_RE.test(email.trim())) {
        return res.status(400).json({ message: "Email must be a valid email address." });
      }

      await updateMailboxProfileEmail(profile, email.trim(), ctx.userId ?? "unknown");

      const validationResult = await validateMicrosoft365EmailIntegration(ctx.userId ?? undefined);
      res.json({ ok: true, validationResult });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // ─── Schedule Report (Ticket 2.1) ────────────────────────────────────────────
  // POST /api/customers/:id/schedule-report/generate
  app.post("/api/customers/:id/schedule-report/generate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const customerId = req.params.id;
      const { weekStart, weekEnd, force } = req.body as { weekStart?: string; weekEnd?: string; force?: boolean };

      // Default to current week (Mon–Sun, CT)
      function currentWeekBounds() {
        const now = new Date();
        const chi = new Date(now.toLocaleString("en-US", { timeZone: "America/Chicago" }));
        const dow = chi.getDay();
        const diffToMon = dow === 0 ? -6 : 1 - dow;
        const mon = new Date(chi); mon.setDate(chi.getDate() + diffToMon); mon.setHours(0,0,0,0);
        const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
        return { weekStart: mon.toISOString().split("T")[0], weekEnd: sun.toISOString().split("T")[0] };
      }
      const bounds = currentWeekBounds();
      const ws = weekStart ?? bounds.weekStart;
      const we = weekEnd   ?? bounds.weekEnd;

      // Fetch account name
      const accRaw = await db.execute(sql`
        SELECT customer_name FROM customers WHERE id = ${customerId} AND is_deleted = false LIMIT 1
      `);
      const acc: any = ((accRaw as any).rows ?? accRaw)[0];
      if (!acc) return res.status(404).json({ message: "Account not found" });

      // Check for existing (skip if !force)
      const { scheduleReportExistsForWeek, storeScheduleReport, listScheduleReports } = await import("./services/scheduleReportStorageService");
      if (!force) {
        const exists = await scheduleReportExistsForWeek(customerId, ws);
        if (exists) {
          const list = await listScheduleReports(customerId, 5);
          const match = list.find(r => r.weekStart === ws);
          return res.json({ alreadyExists: true, report: match ?? null });
        }
      }

      // Generate PDF
      const { generateSchedulePdf } = await import("./services/scheduleReportPdfService");
      const result = await generateSchedulePdf({ customerId, accountName: acc.customer_name, weekStart: ws, weekEnd: we });

      // Store in Object Storage + account_documents
      const record = await storeScheduleReport({
        customerId,
        accountName:       acc.customer_name,
        weekStart:         ws,
        weekEnd:           we,
        buffer:            result.buffer,
        fileName:          result.fileName,
        shiftCount:        result.shiftCount,
        driverCount:       result.driverCount,
        uploadedByUserId:  ctx.userId,
      });

      res.status(201).json({ success: true, report: record, shiftCount: result.shiftCount, driverCount: result.driverCount });
    } catch (e: any) {
      console.error("[ScheduleReport] generate error:", e);
      res.status(500).json({ message: e.message });
    }
  });

