  // POST /api/customers/:id/weekly-shift-report/generate
  app.post("/api/customers/:id/weekly-shift-report/generate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const customerId = req.params.id;
      const { weekStart, weekEnd, timezone } = req.body as {
        weekStart?: string; weekEnd?: string; timezone?: string;
      };

      function currentWeekBounds() {
        const now = new Date();
        const chi = new Date(now.toLocaleString("en-US", { timeZone: "America/Chicago" }));
        const dow = chi.getDay();
        const diffToMon = dow === 0 ? -6 : 1 - dow;
        const mon = new Date(chi); mon.setDate(chi.getDate() + diffToMon); mon.setHours(0,0,0,0);
        const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
        return { weekStart: mon.toISOString().split("T")[0], weekEnd: sun.toISOString().split("T")[0] };
      }
      const bounds = currentWeekBounds();
      const ws = weekStart ?? bounds.weekStart;
      const we = weekEnd   ?? bounds.weekEnd;

      const accRaw = await db.execute(sql`
        SELECT customer_name, timezone FROM customers WHERE id = ${customerId} AND is_deleted = false LIMIT 1
      `);
      const acc: any = ((accRaw as any).rows ?? accRaw)[0];
      if (!acc) return res.status(404).json({ message: "Account not found" });

      const tz = timezone ?? (acc.timezone && acc.timezone.trim() ? acc.timezone : null) ?? "America/New_York";

      const { generateWeeklyShiftReport } = await import("./services/weeklyShiftReportPdfService");
      const result = await generateWeeklyShiftReport({
        customerId,
        accountName: acc.customer_name,
        weekStart: ws,
        weekEnd:   we,
        timezone:  tz,
      });

      res.setHeader("Content-Type", "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="${result.fileName}"`);
      res.setHeader("Content-Length", result.buffer.length);
      res.setHeader("X-Shift-Count",     String(result.shiftCount));
      res.setHeader("X-Driver-Count",    String(result.driverCount));
      res.setHeader("X-Exception-Count", String(result.exceptionCount));
      res.send(result.buffer);
    } catch (e: any) {
      console.error("[WeeklyShiftReport] generate error:", e?.message ?? e);
      console.error("[WeeklyShiftReport] stack:", e?.stack ?? "(no stack)");
      res.status(500).json({ message: e?.message ?? "Internal server error" });
    }
  });

