  app.get("/api/finance/invoices/:invoiceId/lines", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext, hasFinanceAccess, buildTenantFilter } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance access required" });
      const rows = await db.select().from(invoiceLines)
        .where(and(eq(invoiceLines.invoiceId, req.params.invoiceId), ...(ctx.tenantId && !ctx.isSuperAdmin ? [eq(invoiceLines.tenantId, ctx.tenantId)] : [])))
        .orderBy(invoiceLines.sortOrder);
      res.json(rows);
    } catch (e: any) { res.status(e.statusCode || 500).json({ error_code: e.errorCode || "INTERNAL_ERROR", message: e.message }); }
  });

  app.post("/api/finance/invoices/:invoiceId/lines", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext, hasFinanceAccess } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance access required" });
      let lineData = { ...req.body };
      // Auto-populate accounting codes from posting profile when productId is provided
      if (lineData.productId && !lineData.incomeAccountCode) {
        const [profile] = await db.select().from(postingProfiles).where(eq(postingProfiles.productId, lineData.productId));
        if (profile) {
          lineData.incomeAccountCode = lineData.incomeAccountCode || profile.incomeAccountCode;
          lineData.cogsAccountCode = lineData.cogsAccountCode || profile.cogsAccountCode;
          lineData.taxCode = lineData.taxCode || profile.taxCode;
          lineData.classCode = lineData.classCode || profile.classCode;
        }
        // Check accounting settings for suspense routing fallback
        if (!lineData.incomeAccountCode) {
          const [acctSettings] = await db.select().from(accountingSettings);
          if (acctSettings?.routeUnmappedToSuspense && acctSettings.suspenseIncomeAccountId) {
            const [suspenseAcct] = await db.select().from(accountRegistry).where(eq(accountRegistry.id, acctSettings.suspenseIncomeAccountId));
            if (suspenseAcct) lineData.incomeAccountCode = suspenseAcct.accountCode;
          }
        }
      }
      const [row] = await db.insert(invoiceLines).values({ ...lineData, invoiceId: req.params.invoiceId, tenantId: ctx.tenantId, createdBy: ctx.userId, updatedBy: ctx.userId }).returning();
      res.status(201).json(row);
    } catch (e: any) { res.status(e.statusCode || 500).json({ error_code: e.errorCode || "INTERNAL_ERROR", message: e.message }); }
  });

