      const [existing] = await db.select().from(invoiceLines).where(eq(invoiceLines.id, req.params.id));
      if (!existing) return res.status(404).json({ error_code: "NOT_FOUND", message: "Invoice line not found" });
      assertTenantAccess(ctx, existing.tenantId);
      const [row] = await db.update(invoiceLines).set({ ...req.body, updatedBy: ctx.userId, updatedAt: new Date() }).where(eq(invoiceLines.id, req.params.id)).returning();
      res.json(row);
