  app.post("/api/finance/bills", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext, hasFinanceAccess } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance access required" });
      const body = req.body;
      // Duplicate detection: vendor_id + invoice_number
      if (body.vendorId && body.invoiceNumber) {
        const dupFilter = ctx.tenantId
          ? and(eq(bills.vendorId, body.vendorId), eq(bills.invoiceNumber, body.invoiceNumber), eq(bills.tenantId, ctx.tenantId), ne(bills.status, 'voided'))
          : and(eq(bills.vendorId, body.vendorId), eq(bills.invoiceNumber, body.invoiceNumber), ne(bills.status, 'voided'));
        const [dup] = await db.select({ id: bills.id, billNumber: bills.billNumber }).from(bills).where(dupFilter).limit(1);
        if (dup) return res.status(409).json({ error_code: "DUPLICATE_BILL", message: `Duplicate: bill ${dup.billNumber || dup.id} already recorded for this vendor and invoice number.`, duplicateBillId: dup.id });
      }
      // Auto-calculate due date from payment_terms if dueDate not provided
      let dueDate = body.dueDate;
      if (!dueDate && body.billDate && body.paymentTerms) {
        const termDays: Record<string, number> = { net_15: 15, net_30: 30, net_45: 45, net_60: 60, net_90: 90, due_on_receipt: 0, net_7: 7, net_10: 10 };
        const days = termDays[body.paymentTerms] ?? 30;
        const d = new Date(body.billDate);
        d.setDate(d.getDate() + days);
        dueDate = d.toISOString().split('T')[0];
      }
      const [row] = await db.insert(bills).values({ ...body, dueDate, tenantId: ctx.tenantId, createdBy: ctx.userId, updatedBy: ctx.userId }).returning();
      res.status(201).json(row);
    } catch (e: any) { res.status(e.statusCode || 500).json({ error_code: e.errorCode || "INTERNAL_ERROR", message: e.message }); }
  });

