  app.patch("/api/finance/accounting-settings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext, hasFinanceAccess } = await import("./services/tenantService");
      const ctx = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance access required" });
      // upsert: update if exists, insert if not
      const existing = ctx.tenantId
        ? await db.select().from(accountingSettings).where(eq(accountingSettings.tenantId, ctx.tenantId)).limit(1)
        : await db.select().from(accountingSettings).where(sql`${accountingSettings.tenantId} IS NULL`).limit(1);
      const updates = { ...req.body, updatedBy: ctx.userId, updatedAt: new Date() };
      if (existing.length > 0) {
        const [row] = await db.update(accountingSettings).set(updates).where(eq(accountingSettings.id, existing[0].id)).returning();
        res.json(row);
      } else {
        const [row] = await db.insert(accountingSettings).values({ ...updates, tenantId: ctx.tenantId }).returning();
        res.json(row);
      }
    } catch (e: any) { res.status(e.statusCode || 500).json({ error_code: e.errorCode || "INTERNAL_ERROR", message: e.message }); }
  });

