  // GET /api/public/invoices/:token/attachments/:attachmentId/download - Download customer-visible attachment (no auth)
  app.get("/api/public/invoices/:token/attachments/:attachmentId/download", PUBLIC_RATE_LIMITS.invoicePortal, TOKEN_THROTTLE, async (req: Request, res: Response) => {
    try {
      const { token, attachmentId } = req.params;
      if (!token) {
        return res.status(400).json({ error: 'MISSING_TOKEN', message: 'Payment token is required' });
      }

      const [invoice] = await db.select()
        .from(invoices)
        .where(eq(invoices.paymentAccessToken, token))
        .limit(1);

      if (!invoice) {
        return res.status(404).json({ error: 'NOT_FOUND', message: 'Invoice not found' });
      }

      const attachment = await storage.getInvoiceAttachment(attachmentId);
      if (!attachment || attachment.invoiceId !== invoice.id || !attachment.customerVisible) {
        return res.status(404).json({ error: 'NOT_FOUND', message: 'Attachment not found' });
      }

      let fileBuffer: Buffer;
      const provider = getStorageProvider();

      if (provider === "s3") {
        const s3Service = getS3StorageService();
        try {
          fileBuffer = await s3Service.downloadAsBytes(attachment.objectPath);
        } catch (dlErr: any) {
          console.error('S3 download error:', dlErr.message);
          return res.status(404).json({ error: 'NOT_FOUND', message: 'File not found in storage' });
        }
      } else {
        const client = new (await import("@replit/object-storage")).Client({
          bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID!,
        });
        const objectName = attachment.objectPath.replace('/objects/', '');
        const result = await client.downloadAsBytes(objectName);
        if (!result.ok || !result.value) {
          return res.status(404).json({ error: 'NOT_FOUND', message: 'File not found in storage' });
        }
        fileBuffer = Buffer.from(result.value);
      }

      res.set({
        'Content-Type': attachment.mimeType,
        'Content-Disposition': `attachment; filename="${attachment.fileName}"`,
        'Content-Length': String(fileBuffer.length),
      });
      res.send(fileBuffer);
    } catch (error) {
      console.error('Error downloading public attachment:', error);
      res.status(500).json({ error: 'INTERNAL_ERROR', message: 'Failed to download attachment' });
    }
  });

