  // GET /api/public/referral/:code/qr — PNG QR code for the referral URL
  app.get("/api/public/referral/:code/qr", async (req: Request, res: Response) => {
    try {
      const { getReferralCodeInfo } = await import("./recruitingService");
      const info = await getReferralCodeInfo(req.params.code);
      if (!info) return res.status(404).json({ error: "Referral code not found" });

      const QRCode = await import("qrcode");
      const size = Math.min(400, Math.max(100, parseInt(String(req.query.size || "280")) || 280));
      const referralUrl = `${req.protocol}://${req.get("host")}/ref/${info.code}`;
      const pngBuffer = await QRCode.toBuffer(referralUrl, {
        width: size,
        margin: 2,
        color: { dark: "#000000", light: "#ffffff" },
      });
      res.setHeader("Content-Type", "image/png");
      res.setHeader("Cache-Control", "public, max-age=86400");
      return res.send(pngBuffer);
    } catch (err: any) {
      return res.status(500).json({ error: err.message });
    }
  });

  // POST /api/public/referral/:code/apply — submit application via referral landing page
  app.post("/api/public/referral/:code/apply", async (req: Request, res: Response) => {
    try {
      const { getReferralCodeInfo, submitExternalReferral } = await import("./recruitingService");
      const info = await getReferralCodeInfo(req.params.code);
      if (!info) return res.status(404).json({ error: "Referral code not found" });

      const { firstName, lastName, email, phone, driverType, city, state } = req.body;
      if (!firstName || !lastName || !email) {
        return res.status(400).json({ error: "firstName, lastName, and email are required" });
      }

      const result = await submitExternalReferral({
        referrerDriverId: info.driverId,
        referredFirstName: firstName,
        referredLastName: lastName,
        referredEmail: email,
        referredPhone: phone || null,
        referredDriverType: driverType || null,
        referredCity: city || null,
        referredState: state || null,
        consentToShare: true,
        sourceSystem: "referral_link",
        campaignSource: "referral_link",
        referralCode: info.code,
        notes: null,
      });

      if (result.isDuplicate) {
        return res.status(409).json({
          error: "This candidate has already been referred.",
          referralId: result.referralId,
        });
      }
      return res.status(201).json({ success: true, referralId: result.referral.id });
    } catch (err: any) {
      return res.status(500).json({ error: err.message });
    }
  });

