  // GET /api/public/billing-documents/:type/download — stream the active document (no auth)
  app.get("/api/public/billing-documents/:type/download", async (req: Request, res: Response) => {
    try {
      const { billingDocuments } = await import("../shared/schema");
      const { eq: eqFn, and: andFn } = await import("drizzle-orm");
      const docType = req.params.type.toLowerCase();

      const [doc] = await db
        .select()
        .from(billingDocuments)
        .where(andFn(eqFn(billingDocuments.documentType, docType), eqFn(billingDocuments.status, "active")))
        .limit(1);

      if (!doc) {
        return res.status(404).json({ message: `No active ${docType.toUpperCase()} document found.` });
      }

      // Serve the file
      const provider = getStorageProvider();
      let fileBuffer: Buffer;

      if (provider === "s3") {
        const s3 = getS3StorageService();
        fileBuffer = await s3.downloadByKey(doc.storageKey);
      } else {
        const { Client: ReplClient } = await import("@replit/object-storage");
        const client = new ReplClient({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID! });
        const result = await client.downloadAsBytes(doc.storageKey);
        if (!result.ok || !result.value) {
          return res.status(404).json({ message: "File not found in storage" });
        }
        fileBuffer = Buffer.from(result.value);
      }

      // Increment download count (fire-and-forget)
      db.update(billingDocuments)
        .set({ downloadCount: (doc.downloadCount ?? 0) + 1 })
        .where(eqFn(billingDocuments.id, doc.id))
        .catch(() => {});

      const safeFileName = doc.fileName.replace(/[^a-zA-Z0-9._-]/g, "_");
      res.set({
        "Content-Type":        doc.contentType ?? "application/pdf",
        "Content-Disposition": `attachment; filename="${safeFileName}"`,
        "Content-Length":      String(fileBuffer.length),
        "Cache-Control":       "no-store",
      });
      res.send(fileBuffer);
    } catch (err) {
      console.error("[BillingDocs] Error downloading public doc:", err);
      res.status(500).json({ message: "Failed to download document" });
    }
  });

  // POST /api/public/invoices/:token/payment-intent - Create payment intent for invoice
  app.post("/api/public/invoices/:token/payment-intent", PUBLIC_RATE_LIMITS.invoicePortal, TOKEN_THROTTLE, async (req: Request, res: Response) => {
    try {
      const { token } = req.params;
      
      if (!token) {
        return res.status(400).json({ error: 'MISSING_TOKEN', message: 'Payment token is required' });
      }

      // Find invoice by payment access token
      const [invoice] = await db.select()
        .from(invoices)
        .where(eq(invoices.paymentAccessToken, token))
        .limit(1);

      if (!invoice) {
        return res.status(404).json({ error: 'NOT_FOUND', message: 'Invoice not found' });
      }

      // Validate invoice status
      if (invoice.status === 'paid') {
        return res.status(400).json({ error: 'ALREADY_PAID', message: 'This invoice has already been paid' });
      }
      if (invoice.status === 'cancelled' || invoice.status === 'void') {
        return res.status(400).json({ error: 'CANCELLED', message: 'This invoice has been cancelled' });
      }
      if (invoice.status === 'written_off') {
        return res.status(400).json({ error: 'WRITTEN_OFF', message: 'This invoice has been written off and is no longer accepting payments' });
      }

      // Calculate balance due
      const balanceDue = parseFloat(invoice.balanceDue || invoice.totalAmount);
      if (balanceDue <= 0) {
        return res.status(400).json({ error: 'NO_BALANCE', message: 'No balance due on this invoice' });
      }

      // Check if Stripe is configured
      if (!isStripeConfigured()) {
        return res.status(503).json({ error: 'PAYMENTS_UNAVAILABLE', message: 'Online payments are not configured' });
      }

      // Determine allowed payment method types from billing profile
      let allowedStripeTypes: string[] | undefined;
      if (invoice.customerId) {
        const billingProfile = await storage.getCustomerBillingProfile(invoice.customerId);
        if (billingProfile) {
          const types: string[] = [];
          if (billingProfile.acceptsCreditCard) types.push('card');
          if (billingProfile.acceptsAch) types.push('us_bank_account');
          if (types.length > 0) allowedStripeTypes = types;
        }
      }

      // Create payment intent
      const result = await createPaymentIntent({
        amount: balanceDue,
        currency: 'usd',
        customerId: invoice.customerId || undefined,
        invoiceId: invoice.id,
        description: `Payment for Invoice #${invoice.invoiceNumber}`,
        allowedPaymentMethodTypes: allowedStripeTypes,
        metadata: {
          invoiceNumber: invoice.invoiceNumber,
          draftSequence,
          invoiceNumberFinalized: false,
          customerName: invoice.customerName,
        },
      });

      res.json({
        clientSecret: result.clientSecret,
        paymentIntentId: result.paymentIntentId,
      });
    } catch (error) {
      console.error('[Public Invoice] Error creating payment intent:', error);
      res.status(500).json({ error: 'INTERNAL_ERROR', message: 'Failed to create payment' });
    }
  });

  // POST /api/public/invoices/:token/payment-complete - Handle payment completion
  app.post("/api/public/invoices/:token/payment-complete", PUBLIC_RATE_LIMITS.invoicePortal, TOKEN_THROTTLE, async (req: Request, res: Response) => {
    try {
      const { token } = req.params;
      const { paymentIntentId } = req.body;
      
      if (!token || !paymentIntentId) {
        return res.status(400).json({ error: 'MISSING_DATA', message: 'Token and payment intent ID are required' });
      }

      // Duplicate payment prevention: check if this payment intent was already recorded
      const [existingPayment] = await db.select()
        .from(payments)
        .where(eq(payments.stripePaymentIntentId, paymentIntentId))
        .limit(1);
      if (existingPayment) {
        console.log('[Payment Dedup] Payment already recorded for intent:', paymentIntentId, 'paymentId:', existingPayment.id);
        const dedupInvoice = await db.select()
          .from(invoices)
          .where(eq(invoices.paymentAccessToken, token))
          .limit(1);
        return res.json({
          success: true,
          paymentId: existingPayment.id,
          paymentNumber: existingPayment.paymentNumber,
          deduplicated: true,
          invoiceStatus: dedupInvoice[0]?.status || 'unknown',
          balanceDue: parseFloat(dedupInvoice[0]?.balanceDue || '0'),
          message: 'Payment was already recorded',
        });
      }

      // Find invoice by payment access token
      const [invoice] = await db.select()
        .from(invoices)
        .where(eq(invoices.paymentAccessToken, token))
        .limit(1);

      if (!invoice) {
        return res.status(404).json({ error: 'NOT_FOUND', message: 'Invoice not found' });
      }

      // Verify payment intent status with Stripe
      if (!isStripeConfigured()) {
        return res.status(503).json({ error: 'PAYMENTS_UNAVAILABLE', message: 'Online payments are not configured' });
      }

      const paymentIntent = await getPaymentIntent(paymentIntentId);
      
      if (paymentIntent.status !== 'succeeded') {
        return res.status(400).json({ 
          error: 'PAYMENT_NOT_COMPLETE', 
          message: 'Payment has not been completed',
          status: paymentIntent.status,
        });
      }

      // Calculate payment amount
      const paymentAmount = paymentIntent.amount / 100; // Convert from cents
      const currentPaid = parseFloat(invoice.paidAmount || '0');
      const newPaidAmount = currentPaid + paymentAmount;
      const totalAmount = parseFloat(invoice.totalAmount);
      const newBalanceDue = Math.max(0, totalAmount - newPaidAmount);
      
      // Determine new status
      let newStatus = invoice.status;
      if (newBalanceDue <= 0) {
        newStatus = 'paid';
      } else if (newPaidAmount > 0) {
        newStatus = 'partially_paid';
      }

      // Generate payment number using storage method (avoids race conditions)
      const paymentNumber = await storage.generatePaymentNumber();

      // Create payment record
      const [payment] = await db.insert(payments).values({
        paymentNumber,
        customerId: invoice.customerId || '',
        paymentDate: new Date().toISOString().split('T')[0],
        amount: String(paymentAmount),
        paymentMethod: paymentIntent.payment_method_types?.[0] || 'card',
        status: 'completed',
        stripePaymentIntentId: paymentIntentId,
        stripeChargeId: paymentIntent.latest_charge as string || null,
        appliedAmount: String(paymentAmount),
        unappliedAmount: '0',
        referenceNumber: invoice.invoiceNumber,
        memo: `Online payment for Invoice #${invoice.invoiceNumber}`,
      }).returning();

      // Create payment application
      await db.insert(paymentApplications).values({
        paymentId: payment.id,
        invoiceId: invoice.id,
        amount: String(paymentAmount),
        matchMethod: 'online_payment',
        matchConfidence: '100',
      });

      // Update invoice
      await db.update(invoices)
        .set({
          paidAmount: String(newPaidAmount),
          balanceDue: String(newBalanceDue),
          status: newStatus,
          updatedAt: new Date(),
        })
        .where(eq(invoices.id, invoice.id));

      // Create AR ledger entry
      await db.insert(arLedgerEntries).values({
        customerId: invoice.customerId || '',
        entryType: 'payment',
        referenceType: 'payment',
        referenceId: payment.id,
        entryDate: new Date().toISOString().split('T')[0],
        description: `Online payment for Invoice #${invoice.invoiceNumber}`,
        amount: String(-paymentAmount), // Negative for payments (decreases AR)
        invoiceId: invoice.id,
      });

      res.json({
        success: true,
        paymentId: payment.id,
        invoiceStatus: newStatus,
        balanceDue: newBalanceDue,
      });
    } catch (error) {
      console.error('[Public Invoice] Error completing payment:', error);
      res.status(500).json({ error: 'INTERNAL_ERROR', message: 'Failed to record payment' });
    }
  });

  // AUTH ENDPOINTS - User provisioning state
  // ============================================

  // GET /api/auth/me - Returns user provisioning state for routing decisions.
  // Use the same session/token validation as protected API routes so the client
  // cannot render an authenticated portal from a stale password or OIDC session.
  app.get("/api/auth/me", isAuthenticated, async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let claims: any = null;
      
      // Check for session-based auth first (password login)
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      }
      // Check for OIDC auth
      else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        claims = req.user.claims;
      }
      
      if (!userId) {
        return res.status(401).json({ error: "UNAUTHORIZED", message: "Not authenticated" });
      }
      
      // Get or create user (only for OIDC flow)
      let user = await storage.getUser(userId);
      // Also try to find by email for OIDC users matched to existing accounts
      if (!user && claims?.email) {
        const canonicalEmail = String(claims.email).trim().toLowerCase();
        const [userByEmail] = await db.select().from(users).where(sql`lower(trim(${users.email})) = ${canonicalEmail}`);
        user = userByEmail;
      }
      if (!user && claims) {
        user = await storage.createUser({
          id: userId,
          email: claims.email || null,
          firstName: claims.first_name || claims.given_name || null,
          lastName: claims.last_name || claims.family_name || null,
          profileImageUrl: claims.profile_image || claims.picture || null,
        }, {
          source: "auth_user_endpoint",
          actorUserId: userId,
          actorEmail: claims.email || null,
          reason: "Created a user from the authenticated profile endpoint.",
        });
      }
      
      if (!user) {
        return res.status(404).json({ error: "USER_NOT_FOUND", message: "User not found" });
      }
      
      // Check if user is disabled
      if ((user as any).status === "DISABLED") {
        return res.status(403).json({ error: "ACCOUNT_DISABLED", message: "Your DriverHub access is inactive. Please contact an administrator for assistance." });
      }
      
      // Get organization name and environment if user has one
      let orgName: string | null = null;
      let orgEnvironment: string = 'production';
      if (user.orgId) {
        const [org] = await db.select().from(organizations).where(eq(organizations.id, user.orgId)).limit(1);
        orgName = org?.name || null;
        orgEnvironment = (org as any)?.environment || 'production';
      }
      
      // Active corporate users receive access from their organization and role.
      // The legacy onboarding flag must never put them behind an approval screen.
      const isProvisioned = isUserProvisionedForAccess(user);
      
      // Resolve profile photo: employee record takes priority over user record
      let profileImageUrl: string | null = user.profileImageUrl || null;
      try {
        const [emp] = await db.select({ profilePhotoUrl: employees.profilePhotoUrl })
          .from(employees)
          .where(eq(employees.userId, user.id))
          .limit(1);
        if (emp?.profilePhotoUrl) profileImageUrl = emp.profilePhotoUrl;
      } catch {
        // non-blocking — photo is optional
      }

      res.json({
        userId: user.id,
        email: user.email,
        firstName: user.firstName,
        lastName: user.lastName,
        role: user.role,
        orgId: user.orgId,
        orgName,
        orgEnvironment,
        isProvisioned,
        hasSelectedRole: !!user.roleSelectedAt,
        status: (user as any).status || 'ACTIVE',
        isRootSuperAdmin: (user as any).isRootSuperAdmin ?? false,
        corporateAccessAdmin: (user as any).corporateAccessAdmin ?? false,
        forcePasswordReset: (user as any).forcePasswordReset ?? false,
        profileImageUrl,
      });
    } catch (error) {
      console.error("[Auth] /api/auth/me error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to get user info" });
    }
  });

  app.get("/api/me/permissions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(404).json({ error: "USER_NOT_FOUND", message: "User not found" });
      }

      const { computeEffectivePermissions } = await import("./services/corporatePermissions");
      const permissions = computeEffectivePermissions(user);
      res.json(permissions);
    } catch (error) {
      console.error("[Permissions] /api/me/permissions error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to get permissions" });
    }
  });

  // ============================================
  // ONBOARDING ENDPOINTS - Provisioning gate
  // ============================================

  // GET /api/onboarding/status - Check if user needs onboarding
  app.get("/api/onboarding/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      
      if (!user) {
        return res.status(404).json({ error: "USER_NOT_FOUND", message: "User not found" });
      }
      
      // Check if any organization exists in the system
      const orgs = await db.select().from(organizations).limit(1);
      const hasOrganization = orgs.length > 0;
      
      const isProvisioned = isUserProvisionedForAccess(user);
      
      res.json({
        user_id: userId,
        is_provisioned: !!isProvisioned,
        has_organization: hasOrganization,
        org_id: user.orgId || null,
        role: user.role,
        needs_onboarding: !isProvisioned,
      });
    } catch (error) {
      console.error("[Onboarding] Status check error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to check onboarding status" });
    }
  });

  // GET /api/session/context - Get current user context for routing decisions
  app.get("/api/session/context", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      
      if (!user) {
        return res.status(404).json({ error: "USER_NOT_FOUND", message: "User not found" });
      }
      
      // Use centralized driver resolution
      const { getDriverContext } = await import('./utils/driverResolution');
      const driverContext = await getDriverContext(userId);
      
      const context = {
        userId: user.id,
        orgId: user.orgId || null,
        roles: user.role ? [user.role] : [],
        employeeId: user.employeeId || null,
        driverId: driverContext.driverId,
        isDriver: driverContext.isDriver,
        isProvisioned: isUserProvisionedForAccess(user),
      };
      
      res.json(context);
    } catch (error) {
      console.error("[Session] Context error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to get session context" });
    }
  });

  // Valid roles for onboarding
  const EMPLOYEE_ROLES = ['admin', 'ops_manager', 'payroll_admin', 'dispatcher'];
  const DRIVER_ROLE = 'driver';

  // Helper: Ensure organization exists or create one
  async function ensureOrg(userId: string, orgName: string, orgSlug?: string): Promise<string> {
    const existingOrgs = await db.select().from(organizations).limit(1);
    
    if (existingOrgs.length > 0) {
      return existingOrgs[0].id;
    }
    
    const slug = orgSlug || orgName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
    const [newOrg] = await db.insert(organizations).values({
      name: orgName,
      slug: slug,
      isActive: true,
    }).returning();
    
    return newOrg.id;
  }

  // Helper: Ensure employee record exists or create one
  async function ensureEmployee(
    userId: string, 
    orgId: string, 
    profile: { firstName: string; lastName: string; email: string; jobTitle?: string; phone?: string; department?: string }
  ): Promise<string> {
    const existingEmployee = await db.select().from(employees).where(eq(employees.userId, userId)).limit(1);
    
    if (existingEmployee.length > 0) {
      return existingEmployee[0].id;
    }
    
    const [employee] = await db.insert(employees).values({
      userId: userId,
      firstName: profile.firstName,
      lastName: profile.lastName,
      email: profile.email,
      jobTitle: profile.jobTitle || 'Staff',
      department: profile.department || 'Operations',
      phoneNumber: profile.phone || null,
      employmentType: 'Full-Time (Exempt)',
      status: 'active',
      hireDate: new Date().toISOString().split('T')[0],
    }).returning();
    
    return employee.id;
  }

  // Helper: Ensure driver record exists or create one
  async function ensureDriver(
    userId: string,
    orgId: string,
    profile: { firstName: string; lastName: string; email: string; phone?: string }
  ): Promise<string> {
    const existingDriver = await db.select().from(drivers).where(eq(drivers.userId, userId)).limit(1);
    
    if (existingDriver.length > 0) {
      return existingDriver[0].id;
    }
    
    const driverId = `DRV-${Date.now()}-${Math.random().toString(36).substr(2, 5).toUpperCase()}`;
    const [driver] = await db.insert(drivers).values({
      id: driverId,
      userId: userId,
      firstName: profile.firstName,
      lastName: profile.lastName,
      email: profile.email,
      phone: profile.phone || null,
      status: 'active',
      tier: 'standard',
      safetyState: 'ACTIVE',
    }).returning();
    
    return driver.id;
  }

  // Helper: Assign role to user
  async function assignRole(userId: string, orgId: string, role: string): Promise<void> {
    await db.update(users)
      .set({ role, orgId, updatedAt: new Date() })
      .where(eq(users.id, userId));
  }

  // Helper: Get user context
  async function getUserContext(userId: string) {
    const user = await storage.getUser(userId);
    return {
      userId: user?.id,
      orgId: user?.orgId || null,
      roles: user?.role ? [user.role] : [],
      employeeId: user?.employeeId || null,
      driverId: user?.driverId || null,
      isProvisioned: user ? isUserProvisionedForAccess(user) : false,
    };
  }

  // POST /api/onboarding/initialize - Complete onboarding with role-based provisioning
  const onboardingInitializeSchema = z.object({
    org_name: z.string().min(2, "Organization name must be at least 2 characters"),
    org_slug: z.string().optional(),
    selected_role: z.enum(['admin', 'ops_manager', 'payroll_admin', 'dispatcher', 'driver']),
    profile: z.object({
      first_name: z.string().min(1, "First name is required"),
      last_name: z.string().min(1, "Last name is required"),
      job_title: z.string().optional(),
      phone: z.string().optional(),
      department: z.string().optional(),
    }),
  });

  app.post("/api/onboarding/initialize", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      
      if (!user) {
        return res.status(404).json({ error: "USER_NOT_FOUND", message: "User not found" });
      }
      
      // Check if already provisioned
      if (isUserProvisionedForAccess(user)) {
        const context = await getUserContext(userId);
        return res.status(400).json({ 
          error: "ALREADY_PROVISIONED", 
          message: "User is already provisioned",
          context
        });
      }
      
      // Validate request body with Zod
      const parseResult = onboardingInitializeSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          error: "VALIDATION_ERROR", 
          message: "Invalid request data",
          details: parseResult.error.flatten().fieldErrors
        });
      }
      
      const { org_name, org_slug, selected_role, profile } = parseResult.data;
      
      // Transaction-like operations
      const orgId = await ensureOrg(userId, org_name, org_slug);
      
      let employeeId: string | null = null;
      let driverId: string | null = null;
      let assignedRole: string;
      
      const profileData = {
        firstName: profile.first_name,
        lastName: profile.last_name,
        email: user.email || `${userId}@placeholder.local`,
        jobTitle: profile.job_title,
        phone: profile.phone,
        department: profile.department,
      };
      
      if (EMPLOYEE_ROLES.includes(selected_role)) {
        // Employee roles: ADMIN, OPS_MANAGER, PAYROLL_ADMIN, DISPATCHER
        employeeId = await ensureEmployee(userId, orgId, profileData);
        assignedRole = selected_role;
        
        // For MVP: ADMIN also gets payroll access by default
        // (handled via role check in payroll permissions)
      } else if (selected_role === DRIVER_ROLE) {
        // Driver role
        driverId = await ensureDriver(userId, orgId, profileData);
        assignedRole = 'driver';
      } else {
        return res.status(400).json({ 
          error: "INVALID_ROLE", 
          message: "Invalid role selected" 
        });
      }
      
      // Assign role and update user
      await assignRole(userId, orgId, assignedRole);
      
      // Update user with employee/driver link and provisioned status
      await db.update(users)
        .set({
          employeeId: employeeId,
          driverId: driverId,
          isProvisioned: true,
          firstName: profile.first_name,
          lastName: profile.last_name,
          updatedAt: new Date(),
        })
        .where(eq(users.id, userId));
      
      // Get final context and assert provisioned
      const context = await getUserContext(userId);
      
      if (!context.isProvisioned) {
        throw new Error("Provisioning assertion failed: user not marked as provisioned");
      }
      
      res.json({
        success: true,
        context,
        message: "Onboarding completed successfully"
      });
    } catch (error) {
      console.error("[Onboarding] Initialize error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to complete onboarding" });
    }
  });

  // Object Storage Routes - Protected file uploading for profile photos
  // Public route for uploaded profile photos — must come BEFORE the authenticated route
  // Photos in the uploads/ prefix are served without auth so <img> tags can load them
  app.get("/objects/uploads/:filename(*)", async (req, res) => {
    try {
      const provider = getStorageProvider();
      if (provider === "s3") {
        const s3Service = getS3StorageService();
        await s3Service.serveFile(req.path, res);
        return;
      }
      const objectStorageService = new ObjectStorageService();
      const served = await objectStorageService.downloadFromReplitStorage(req.path, res);
      if (!served) {
        return res.sendStatus(404);
      }
    } catch (err) {
      console.error("[Objects/uploads] serve error:", (err as any)?.message ?? err);
      return res.sendStatus(500);
    }
  });

  app.get("/objects/:objectPath(*)", isAuthenticated, async (req, res) => {
    const userId = req.user?.claims?.sub || (req.session as any)?.userId;
    const provider = getStorageProvider();

    try {
      if (provider === "s3") {
        const s3Service = getS3StorageService();
        await s3Service.serveFile(req.path, res);
      } else {
        const objectStorageService = new ObjectStorageService();

        const served = await objectStorageService.downloadFromReplitStorage(req.path, res);
        if (served) return;

        try {
          const objectFile = await objectStorageService.getObjectEntityFile(
            req.path,
          );
          const canAccess = await objectStorageService.canAccessObjectEntity({
            objectFile,
            userId: userId,
            requestedPermission: "read" as any,
          });
          if (!canAccess) {
            return res.sendStatus(401);
          }
          objectStorageService.downloadObject(objectFile, res);
        } catch (legacyError) {
          if (legacyError instanceof ObjectNotFoundError) {
            // Fallback: check unified documents table by storageKey
            try {
              const { downloadDocumentByStorageKey } = await import("./services/documentService");
              const storageKey = req.params.objectPath;
              const result = await downloadDocumentByStorageKey(storageKey, userId || "anonymous");
              if (result) {
                res.set({
                  "Content-Type": result.contentType,
                  "Content-Disposition": `inline; filename="${result.fileName}"`,
                  "Content-Length": String(result.buffer.length),
                  "Cache-Control": "private, max-age=3600",
                });
                return res.send(result.buffer);
              }
            } catch (unifiedErr) {
              // Not found in unified table either
            }
            return res.sendStatus(404);
          }
          throw legacyError;
        }
      }
    } catch (error) {
      console.error("Error checking object access:", error);
      if (error instanceof ObjectNotFoundError) {
        return res.sendStatus(404);
      }
      return res.sendStatus(500);
    }
  });

  app.post("/api/objects/upload", isAuthenticated, async (req, res) => {
    const objectStorageService = new ObjectStorageService();
    const uploadURL = await objectStorageService.getObjectEntityUploadURL();
    res.json({ uploadURL });
  });

  // Server-side file upload endpoint (bypasses signed URL issues)
  app.post("/api/objects/upload-file", isAuthenticated, express.raw({ type: () => true, limit: '15mb' }), async (req: any, res) => {
    const requestId = crypto.randomUUID().substring(0, 8);
    const userId = req.user?.claims?.sub || 'unknown';
    try {
      const contentType = req.headers['content-type'] || 'application/octet-stream';
      const rawFilename = req.headers['x-filename'] as string | undefined;
      const filename = rawFilename ? decodeURIComponent(rawFilename) : undefined;

      console.log(`[Upload:${requestId}] userId=${userId} contentType=${contentType} filename=${filename || 'unknown'}`);

      let fileBuffer: Buffer;
      if (Buffer.isBuffer(req.body)) {
        fileBuffer = req.body;
      } else if (req.body instanceof ArrayBuffer) {
        fileBuffer = Buffer.from(req.body);
      } else if (req.body && typeof req.body === 'object' && Object.keys(req.body).length > 0) {
        fileBuffer = Buffer.from(Object.values(req.body) as number[]);
      } else {
        console.error(`[Upload:${requestId}] No file data received (contentType=${contentType})`);
        const allowedMimeCheck = [
          "image/jpeg", "image/png", "image/gif", "image/webp",
          "application/pdf", "application/msword",
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        ];
        const isTypeIssue = contentType !== "application/octet-stream" && !allowedMimeCheck.some(t => contentType.startsWith(t.replace("/*", "/")));
        if (isTypeIssue) {
          return res.status(415).json({
            errorCode: "UNSUPPORTED_TYPE",
            message: `File type "${contentType}" is not supported. Supported: PDF, DOCX, JPG, PNG.`,
            requestId,
          });
        }
        return res.status(400).json({
          errorCode: "UNKNOWN_ERROR",
          message: "No file data received in the request.",
          requestId,
        });
      }

      if (fileBuffer.length === 0) {
        console.error(`[Upload:${requestId}] Empty file buffer (contentType=${contentType})`);
        const knownAllowed = [
          "image/jpeg", "image/png", "image/gif", "image/webp",
          "application/pdf", "application/msword",
          "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
          "application/octet-stream",
        ];
        if (!knownAllowed.includes(contentType) && !contentType.startsWith("image/")) {
          return res.status(415).json({
            errorCode: "UNSUPPORTED_TYPE",
            message: `File type "${contentType}" is not supported. Supported: PDF, DOCX, JPG, PNG.`,
            requestId,
          });
        }
        return res.status(400).json({
          errorCode: "UNKNOWN_ERROR",
          message: "The file appears to be empty.",
          requestId,
        });
      }

      const MAX_FILE_SIZE = 10 * 1024 * 1024;
      if (fileBuffer.length > MAX_FILE_SIZE) {
        console.warn(`[Upload:${requestId}] File too large: ${fileBuffer.length} bytes`);
        return res.status(413).json({
          errorCode: "FILE_TOO_LARGE",
          message: `File is ${(fileBuffer.length / 1024 / 1024).toFixed(1)}MB. Maximum allowed is 10MB.`,
          requestId,
        });
      }

      const allowedMimeTypes = [
        "image/jpeg", "image/png", "image/gif", "image/webp",
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
      ];
      if (contentType !== "application/octet-stream" && !allowedMimeTypes.includes(contentType)) {
        console.warn(`[Upload:${requestId}] Unsupported type: ${contentType}`);
        return res.status(415).json({
          errorCode: "UNSUPPORTED_TYPE",
          message: `File type "${contentType}" is not supported. Supported: PDF, DOCX, JPG, PNG.`,
          requestId,
        });
      }

      const provider = getStorageProvider();
      console.log(`[Upload:${requestId}] Using storage provider: ${provider}, uploading ${fileBuffer.length} bytes...`);

      let result: { objectPath: string; uploadURL: string };

      if (provider === "s3") {
        const s3Service = getS3StorageService();
        result = await s3Service.uploadFile(fileBuffer, contentType, rawFilename);
      } else {
        if (!process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID) {
          console.error(`[Upload:${requestId}] Object storage not configured - DEFAULT_OBJECT_STORAGE_BUCKET_ID missing`);
          return res.status(503).json({
            errorCode: "STORAGE_NOT_CONFIGURED",
            message: "Uploads are not available in this environment yet. Please contact Admin.",
            requestId,
          });
        }
        const objectStorageService = new ObjectStorageService();
        result = await objectStorageService.uploadFile(fileBuffer, contentType, rawFilename);
      }

      console.log(`[Upload:${requestId}] Success (${provider}) - objectPath: ${result.objectPath}`);

      res.json(result);
    } catch (error: any) {
      const errorMessage = error?.message || "Unknown error";
      const errorDetails = error?.errorDetails || errorMessage;
      console.error(`[Upload:${requestId}] Error: ${errorMessage}`);
      console.error(`[Upload:${requestId}] ErrorDetails: ${errorDetails}`);
      console.error(`[Upload:${requestId}] Stack: ${error?.stack?.substring(0, 500)}`);

      let errorCode = error?.errorCode || "STORAGE_ERROR";
      let statusCode = 502;
      let userMessage = "The upload service encountered an error. Please try again.";

      const combined = `${errorMessage} ${errorDetails}`.toLowerCase();

      if (combined.includes("not set") || combined.includes("not configured") || combined.includes("bucket_id")) {
        errorCode = "STORAGE_NOT_CONFIGURED";
        statusCode = 503;
        userMessage = "Uploads are not available in this environment yet. Please contact Admin.";
      } else if (combined.includes("replid mismatch") || combined.includes("identity daemon")) {
        errorCode = "STORAGE_NOT_CONFIGURED";
        statusCode = 503;
        userMessage = "Uploads are not available in this environment yet. Please contact Admin.";
      } else if (combined.includes("econnrefused") || combined.includes("unavailable") || combined.includes("network") || combined.includes("dns")) {
        errorCode = "STORAGE_UNREACHABLE";
        statusCode = 503;
        userMessage = "The storage service is temporarily unavailable. Please try again in a few minutes.";
      } else if (combined.includes("replidentity") || combined.includes("repl_identity") || combined.includes("token") || combined.includes("credential") || combined.includes("auth") || combined.includes("permission") || combined.includes("403") || combined.includes("401")) {
        errorCode = "STORAGE_AUTH_FAILED";
        statusCode = 502;
        userMessage = "Storage authentication failed. This may be a temporary issue — please try again in a moment. If it persists, contact your administrator.";
      } else if (errorCode === "STORAGE_AUTH_FAILED") {
        statusCode = 502;
        userMessage = "Storage authentication failed. This may be a temporary issue — please try again in a moment. If it persists, contact your administrator.";
      }

      res.status(statusCode).json({
        errorCode,
        message: userMessage,
        requestId,
        debug: process.env.NODE_ENV === 'development' ? errorDetails : undefined,
      });
    }
  });

  // Helper function to sync photos across User, Driver, and Employee records
  async function syncProfilePhoto(photoUrl: string, userId: string, objectStorageService: ObjectStorageService) {
    // Photo is served via the authenticated /objects/ endpoint — use path as-is
    const objectPath: string = photoUrl;

    // Update user record
    await storage.updateUser(userId, { profileImageUrl: objectPath });

    // Check if user has a driver record and update it
    const driver = await storage.getDriverByUserId(userId);
    if (driver) {
      await storage.updateDriver(driver.id, { profilePhotoUrl: objectPath });
    }

    // Check if user has an employee record and update it
    const employee = await storage.getEmployeeByUserId(userId);
    if (employee) {
      await storage.updateEmployee(employee.id, { profilePhotoUrl: objectPath });
    }

    return objectPath;
  }

