  // Corporate route - update driver profile photo (by driver ID)
  app.put("/api/corporate/drivers/:driverId/photo", isAuthenticated, async (req: any, res: Response) => {
    if (!req.body.profilePhotoUrl) {
      return res.status(400).json({ error: "profilePhotoUrl is required" });
    }

    const currentUserId = req.user.claims.sub;
    const currentUser = await storage.getUser(currentUserId);
    const corporateRoles = ["super_user", "admin", "regional_cl", "network_cl", "dealer_cl", "certification_liaison", "custom_user_list", "testing"];

    if (!currentUser || !corporateRoles.includes(currentUser.role)) {
      return res.status(403).json({ message: "Forbidden: Corporate access only" });
    }

    const { driverId } = req.params;
    const driver = await storage.getDriver(driverId);

    if (!driver) {
      return res.status(404).json({ error: "Driver not found" });
    }

    try {
      const objectPath: string = req.body.profilePhotoUrl;
      const fileName = req.body.fileName || `profile_photo_${Date.now()}.jpg`;
      const fileSize = req.body.fileSize || "0";
      const mimeType = req.body.mimeType || "image/jpeg";

      // 1. Update driver record immediately (corporate bypass — no approval needed)
      const updatedDriver = await storage.updateDriver(driverId, { profilePhotoUrl: objectPath });

      // 2. Sync to user record if driver has a linked user
      if (driver.userId) {
        await storage.updateUser(driver.userId, { profileImageUrl: objectPath });
      }

      // 3. Add photo to Driver Documents for history (every upload is preserved)
      let photoDocumentId: string | null = null;
      try {
        const photoDoc = await storage.createDocument({
          driverId,
          documentType: "profile_photo",
          fileName,
          fileSize,
          mimeType,
          fileData: objectPath, // object storage path
          description: "Profile photo uploaded by corporate user",
          expirationDate: null,
          uploadedBy: currentUserId,
        });
        photoDocumentId = photoDoc.id;
      } catch (docErr) {
        console.warn("[PhotoUpload] Could not save photo to driver documents:", docErr);
      }

      // 4. Record in the photo approval framework — status 'bypassed' for corporate uploads
      //    (framework is built now; approval required only for driver_app submissions)
      try {
        const { db } = await import('./db');
        await db.execute(
          `INSERT INTO driver_photo_approvals
             (driver_id, proposed_photo_document_id, submitted_by_type, submitted_by_user_id,
              status, approved_photo_applied_at, updated_at)
           VALUES ($1, $2, 'corporate_user', $3, 'bypassed', NOW(), NOW())`,
          [driverId, photoDocumentId, currentUserId]
        );
      } catch (approvalErr) {
        console.warn("[PhotoUpload] Could not create photo approval record:", approvalErr);
      }

      res.status(200).json({
        objectPath,
        driver: updatedDriver,
        photoDocumentId,
      });
    } catch (error) {
      console.error("Error setting driver profile photo:", error);
      res.status(500).json({ error: "Internal server error" });
    }
  });

