  // Auth routes - returns user with full context
  app.get('/api/auth/user', isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const claims = req.user.claims;
      
      // Upsert user with auth provider data
      let user = await storage.getUser(userId);
      if (!user) {
        // Create user if doesn't exist
        user = await storage.createUser({
          id: userId,
          email: claims.email || null,
          firstName: claims.first_name || claims.given_name || null,
          lastName: claims.last_name || claims.family_name || null,
          profileImageUrl: claims.profile_image || claims.picture || null,
        });
      } else {
        // Update user info if changed
        const updates: any = {};
        if (claims.email && claims.email !== user.email) updates.email = claims.email;
        if ((claims.first_name || claims.given_name) && (claims.first_name || claims.given_name) !== user.firstName) {
          updates.firstName = claims.first_name || claims.given_name;
        }
        if ((claims.last_name || claims.family_name) && (claims.last_name || claims.family_name) !== user.lastName) {
          updates.lastName = claims.last_name || claims.family_name;
        }
        if (Object.keys(updates).length > 0) {
          user = await storage.updateUser(userId, updates, {
            source: "auth_user_endpoint",
            actorUserId: userId,
            actorEmail: claims.email || null,
            reason: "Updated user identity from the authenticated profile endpoint.",
          });
        }
      }
      
      // Build context object
      const context = {
        userId: user?.id,
        orgId: user?.orgId || null,
        roles: user?.role ? [user.role] : [],
        employeeId: user?.employeeId || null,
        driverId: user?.driverId || null,
        isProvisioned: user ? isUserProvisionedForAccess(user) : false,
      };
      
      // Determine redirect based on provisioning status
      const needsOnboarding = !context.isProvisioned && 
        context.roles.length > 0 && 
        !context.roles.includes('driver');
      
      const redirect = needsOnboarding ? '/onboarding' : '/dashboard';
      
      res.json({
        ...user,
        context,
        redirect,
        needsOnboarding,
      });
    } catch (error) {
      console.error("Error fetching user:", error);
      res.status(500).json({ message: "Failed to fetch user" });
    }
  });

  // User onboarding route - allows users to set their role
  // Only driver and employee roles are self-selectable
  // Other roles must be assigned via invitation by super_user or admin
  app.post('/api/admin/set-role', isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { role, inviteCode } = req.body;
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      // Get user's email from Replit Auth claims
      const userEmail = req.user.claims.email;

      // Check if user has an invitation
      let invitation;
      if (inviteCode) {
        invitation = await storage.getInvitationByCode(inviteCode);
        if (!invitation) {
          return res.status(404).json({ message: "Invalid invitation code" });
        }
      } else {
        // Check if there's an invitation for this email
        invitation = await storage.getInvitationByEmail(userEmail);
      }

      // If user has an invitation, validate and use the invited role
      if (invitation) {
        // Validate invitation regardless of how it was found (code or email)
        if (invitation.usedAt) {
          return res.status(400).json({ message: "This invitation has already been used" });
        }
        if (new Date() > invitation.expiresAt) {
          return res.status(400).json({ message: "This invitation has expired" });
        }
        if (invitation.email.toLowerCase() !== userEmail?.toLowerCase()) {
          return res.status(403).json({ message: "This invitation is for a different email address" });
        }

        // All validations passed - assign the invited role
        const updatedUser = await storage.updateUserRole(userId, invitation.role);
        await storage.markInvitationAsUsed(invitation.id, userId);
        return res.json(updatedUser);
      }

      // No invitation - only allow self-selectable roles (driver, employee)
      if (role !== "driver" && role !== "employee") {
        return res.status(403).json({ 
          message: "This role requires an administrator invitation. Only Driver and Employee roles can be self-selected." 
        });
      }

      const updatedUser = await storage.updateUserRole(userId, role);

      // Auto-create driver profile when user selects driver role
      if (role === "driver") {
        const existingDriver = await storage.getDriverByUserId(userId);
        if (!existingDriver) {
          await storage.createDriver({
            userId: userId,
          });
        }
      }

      res.json(updatedUser);
    } catch (error: any) {
      console.error("Error updating role:", error);
      const statusCode = error.message.includes("already been selected") ? 400 : 500;
      res.status(statusCode).json({ message: error.message || "Failed to update role" });
    }
  });

  // MVP: Admin endpoint to link a user to a driver profile
  app.post('/api/admin/link-driver', async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId;
      if (!userId) {
        return res.status(401).json({ error: "UNAUTHORIZED", message: "Not authenticated" });
      }
      
      const adminUser = await storage.getUser(userId);
      if (!adminUser || !['super_user', 'admin'].includes(adminUser.role || '')) {
        return res.status(403).json({ error: "FORBIDDEN", message: "Admin access required" });
      }
      
      const { targetUserId, driverId } = req.body;
      if (!targetUserId || !driverId) {
        return res.status(400).json({ error: "VALIDATION_ERROR", message: "targetUserId and driverId are required" });
      }
      
      // Verify driver exists
      const driver = await storage.getDriver(driverId);
      if (!driver) {
        return res.status(404).json({ error: "NOT_FOUND", message: "Driver not found" });
      }
      
      // Verify target user exists
      const targetUser = await storage.getUser(targetUserId);
      if (!targetUser) {
        return res.status(404).json({ error: "NOT_FOUND", message: "User not found" });
      }
      
      // Update driver's userId
      await db.update(drivers).set({ userId: targetUserId, updatedAt: new Date() }).where(eq(drivers.id, driverId));
      
      // Link driverId to user — intentionally does NOT change the user's role.
      // Role changes may only be made manually by Super Admin or Corporate Admin.
      await db.update(users).set({ 
        driverId: driverId, 
        updatedAt: new Date() 
      }).where(eq(users.id, targetUserId));
      
      console.log(`[Admin] Linked user ${targetUserId} (role: ${targetUser.role}) to driver ${driverId} — role unchanged.`);
      res.json({ success: true, message: `User ${targetUser.email} linked to driver ${driverId}` });
    } catch (error: any) {
      console.error("[Admin] Link driver error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: error.message || "Failed to link driver" });
    }
  });

