  // Update driver profile
  app.patch("/api/drivers/profile", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (user?.role !== "driver") {
        return res.status(403).json({ message: "Forbidden: Driver access only" });
      }

      const driver = await storage.getDriverByUserId(userId);

      if (!driver) {
        return res.status(404).json({ message: "Driver profile not found. Please contact your administrator." });
      }

      const validatedData = insertDriverSchema.partial().parse(req.body);

      const driverEditableFields = [
        'phoneNumber', 'address', 'city', 'state', 'zipCode',
        'emergencyContactName', 'emergencyContactRelationship', 'emergencyContactPhone', 'emergencyContactEmail',
        'profilePhotoUrl',
      ];
      const filteredData: Record<string, any> = {};
      for (const key of Object.keys(validatedData)) {
        if (driverEditableFields.includes(key)) {
          filteredData[key] = (validatedData as any)[key];
        }
      }

      const updatedDriver = await storage.updateDriver(driver.id, filteredData);

      if (updatedDriver) {
        try {
          const { detectDriverChangedFields, emitDriverUpdatedEvent } = await import("./driverMasterDataService");
          const changedFields = detectDriverChangedFields(driver as unknown as Record<string, unknown>, updatedDriver as unknown as Record<string, unknown>);
          if (changedFields.length > 0) {
            await emitDriverUpdatedEvent(driver.id, changedFields, userId);
          }
        } catch (eventError) {
          console.error("[Driver Profile Update] Failed to emit driver event:", eventError);
        }
      }

      const { stripDriverInternalFields } = await import("./services/corporatePermissions");
      res.json(stripDriverInternalFields(updatedDriver));
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error updating driver profile:", error);
      res.status(500).json({ message: "Failed to update driver profile" });
    }
  });

