  // Upload document for authenticated driver
  app.post("/api/drivers/documents", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (user?.role !== "driver") {
        return res.status(403).json({ message: "Forbidden: Driver access only" });
      }

      const driver = await storage.getDriverByUserId(userId);
      if (!driver) {
        return res.status(404).json({ message: "Driver profile not found" });
      }

      // Validate document type
      const allowedTypes = ["license", "certification", "compliance", "other"];
      if (!allowedTypes.includes(req.body.documentType)) {
        return res.status(400).json({ message: "Invalid document type" });
      }

      // Validate MIME type
      const allowedMimeTypes = ["application/pdf", "image/jpeg", "image/jpg", "image/png"];
      if (!allowedMimeTypes.includes(req.body.mimeType)) {
        return res.status(400).json({ message: "Invalid file type. Only PDF, JPG, and PNG are allowed" });
      }

      // Validate file size (5MB limit)
      const fileSizeNum = parseInt(req.body.fileSize);
      if (isNaN(fileSizeNum) || fileSizeNum > 5 * 1024 * 1024) {
        return res.status(400).json({ message: "File size must be less than 5MB" });
      }

      // Validate base64 data exists and format
      if (!req.body.fileData || typeof req.body.fileData !== 'string') {
        return res.status(400).json({ message: "Invalid file data" });
      }

      // Validate base64 format and size
      try {
        const base64Data = req.body.fileData;
        // Check if valid base64
        if (!/^[A-Za-z0-9+/]*={0,2}$/.test(base64Data)) {
          return res.status(400).json({ message: "Invalid base64 format" });
        }
        
        // Calculate actual decoded size
        const padding = (base64Data.match(/=/g) || []).length;
        const actualSize = (base64Data.length * 3) / 4 - padding;
        
        // Enforce 5MB limit on actual payload
        if (actualSize > 5 * 1024 * 1024) {
          return res.status(400).json({ message: "File size exceeds 5MB limit" });
        }
      } catch (error) {
        return res.status(400).json({ message: "Invalid file data encoding" });
      }

      // Validate required fields
      if (!req.body.fileName || !req.body.mimeType) {
        return res.status(400).json({ message: "Missing required fields" });
      }

      const document = await storage.createDocument({
        driverId: driver.id,
        documentType: req.body.documentType,
        fileName: req.body.fileName,
        fileSize: req.body.fileSize,
        mimeType: req.body.mimeType,
        fileData: req.body.fileData,
        description: req.body.description || null,
        expirationDate: req.body.expirationDate || null,
        uploadedBy: userId,
      });

      res.json(document);
    } catch (error) {
      console.error("Error uploading document:", error);
      res.status(500).json({ message: "Failed to upload document" });
    }
  });

  // Delete document for authenticated driver
  app.delete("/api/drivers/documents/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      // Only Super Admins can delete documents
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete documents and attachments' });
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      const { driverDocuments: driverDocsTable } = await import('../shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');
      const [existing] = await db.select().from(driverDocsTable).where(eq(driverDocsTable.id, req.params.id)).limit(1);
      if (!existing || existing.isDeleted) {
        return res.status(404).json({ message: 'Document not found' });
      }

      await db.update(driverDocsTable)
        .set({ isDeleted: true, deletedAt: new Date(), deletedByUserId: userId, deletionReason: String(deletionReason).trim() })
        .where(eq(driverDocsTable.id, req.params.id));

      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'driver_document',
        targetEntityId: req.params.id,
        targetEntityLabel: existing.fileName,
        reason: String(deletionReason).trim(),
        metadata: { fileName: existing.fileName, documentType: existing.documentType, restrictedAction: true },
        ipAddress: req.ip,
      });

      res.json({ message: 'Document removed successfully' });
    } catch (error) {
      console.error('Error deleting document:', error);
      res.status(500).json({ message: 'Failed to delete document' });
    }
  });

