  // Parse dashboard filters from query params
  function parseDashboardFilters(query: any): any {
    const now = new Date();
    let startDate: Date;
    let endDate = now;
    
    const range = query.range || '30d';
    switch (range) {
      case 'today':
        startDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        break;
      case '7d':
        startDate = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case '30d':
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        break;
      case '90d':
        startDate = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
        break;
      case 'custom':
        startDate = query.startDate ? new Date(query.startDate) : new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        endDate = query.endDate ? new Date(query.endDate) : now;
        break;
      default:
        startDate = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    }

    return {
      dateRange: range,
      startDate,
      endDate,
      locationIds: query.location ? query.location.split(',') : [],
      accountIds: query.account ? query.account.split(',') : [],
      driverType: query.driverType || 'all',
      status: query.status || 'all'
    };
  }

  // Dashboard Summary - Executive KPIs with sparklines and deltas
  app.get("/api/dashboard/summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const filters = parseDashboardFilters(req.query);
      const drivers = await storage.getAllDriversWithUsers();
      const trips = await storage.getAllTrips();
      const accidents = await storage.getAllAccidents();

      // Filter by status if specified
      const filteredDrivers = filters.status === 'all' 
        ? drivers 
        : drivers.filter((d: any) => d.status === filters.status);

      // Filter by driver type (W2/IC)
      const typedDrivers = filters.driverType === 'all'
        ? filteredDrivers
        : filteredDrivers.filter((d: any) => {
            if (filters.driverType === 'w2') return d.driverClassification === 'Employee';
            if (filters.driverType === 'ic') return d.driverClassification === 'Independent Contractor';
            return true;
          });

      const activeDrivers = typedDrivers.filter((d: any) => d.status === 'active');

      // Filter trips by date range
      const tripsInRange = trips.filter((t: any) => {
        if (!t.tripDate) return false;
        const tripDate = new Date(t.tripDate);
        return tripDate >= filters.startDate && tripDate <= filters.endDate;
      });

      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const tripsToday = trips.filter((t: any) => {
        if (!t.tripDate) return false;
        const tripDate = new Date(t.tripDate);
        tripDate.setHours(0, 0, 0, 0);
        return tripDate.getTime() === today.getTime();
      });

      const tripsInProgress = tripsToday.filter((t: any) => t.status === 'in_progress');
      const tripsCompletedToday = tripsToday.filter((t: any) => t.status === 'completed');

      // Calculate open exceptions (accidents + compliance issues)
      const openAccidents = accidents.filter((a: any) => a.status === 'open' || a.status === 'investigating');
      const expiringLicenses = drivers.filter((d: any) => {
        if (!d.licenseExpiration) return false;
        const exp = new Date(d.licenseExpiration);
        const thirtyDays = new Date(today.getTime() + 30 * 24 * 60 * 60 * 1000);
        return exp <= thirtyDays && exp >= today;
      });
      const exceptionsOpen = openAccidents.length + expiringLicenses.length;

      // Calculate utilization (simplified: active drivers / total drivers)
      const utilization = drivers.length > 0 
        ? Math.round((activeDrivers.length / drivers.length) * 100) 
        : 0;

      // Generate sparkline data (last 7 or 30 days depending on range)
      const sparklineDays = filters.dateRange === 'today' || filters.dateRange === '7d' ? 7 : 30;
      const sparkline: { date: string; value: number }[] = [];
      for (let i = sparklineDays - 1; i >= 0; i--) {
        const date = new Date(today.getTime() - i * 24 * 60 * 60 * 1000);
        const dateStr = date.toISOString().split('T')[0];
        const count = trips.filter((t: any) => {
          if (!t.tripDate) return false;
          const td = new Date(t.tripDate);
          td.setHours(0, 0, 0, 0);
          return td.toISOString().split('T')[0] === dateStr;
        }).length;
        sparkline.push({ date: dateStr, value: count });
      }

      // Calculate deltas (compare to previous period)
      const previousStart = new Date(filters.startDate.getTime() - (filters.endDate.getTime() - filters.startDate.getTime()));
      const tripsPrevious = trips.filter((t: any) => {
        if (!t.tripDate) return false;
        const tripDate = new Date(t.tripDate);
        return tripDate >= previousStart && tripDate < filters.startDate;
      });

      const tripsDelta = tripsPrevious.length > 0 
        ? Math.round(((tripsInRange.length - tripsPrevious.length) / tripsPrevious.length) * 100)
        : 0;

      const kpis = [
        {
          id: 'active-drivers',
          title: 'Active Drivers',
          value: activeDrivers.length,
          previousValue: activeDrivers.length,
          delta: 0,
          deltaDirection: 'neutral' as const,
          sparkline,
          drilldownRoute: '/reports/drivers?status=active',
          icon: 'users',
          color: 'success' as const
        },
        {
          id: 'utilization',
          title: 'Utilization %',
          value: utilization,
          previousValue: utilization,
          delta: 0,
          deltaDirection: 'neutral' as const,
          sparkline,
          drilldownRoute: '/reports/drivers',
          icon: 'activity',
          color: 'default' as const
        },
        {
          id: 'trips-in-progress',
          title: 'Trips In Progress',
          value: tripsInProgress.length,
          previousValue: 0,
          delta: 0,
          deltaDirection: 'neutral' as const,
          sparkline: [],
          drilldownRoute: '/reports/trips?status=in_progress',
          icon: 'truck',
          color: 'default' as const
        },
        {
          id: 'trips-completed',
          title: 'Trips Completed Today',
          value: tripsCompletedToday.length,
          previousValue: tripsPrevious.length,
          delta: tripsDelta,
          deltaDirection: tripsDelta > 0 ? 'up' : tripsDelta < 0 ? 'down' : 'neutral' as const,
          sparkline,
          drilldownRoute: '/reports/trips?status=completed',
          icon: 'check-circle',
          color: 'success' as const
        },
        {
          id: 'exceptions',
          title: 'Exceptions Open',
          value: exceptionsOpen,
          previousValue: 0,
          delta: 0,
          deltaDirection: 'neutral' as const,
          sparkline: [],
          drilldownRoute: '/reports/compliance',
          icon: 'alert-triangle',
          color: exceptionsOpen > 0 ? 'danger' : 'success' as const
        }
      ];

      res.json({
        kpis,
        lastUpdated: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error fetching dashboard summary:", error);
      res.status(500).json({ message: "Failed to fetch dashboard summary" });
    }
  });

  // Dashboard Risk - Compliance and risk metrics
  app.get("/api/dashboard/risk", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const drivers = await storage.getAllDriversWithUsers();
      const accidents = await storage.getAllAccidents();

      const now = new Date();
      const thirtyDays = new Date(now.getTime() + 30 * 24 * 60 * 60 * 1000);
      const sixtyDays = new Date(now.getTime() + 60 * 24 * 60 * 60 * 1000);
      const ninetyDays = new Date(now.getTime() + 90 * 24 * 60 * 60 * 1000);

      // License expiration buckets
      const licensesBucket30 = drivers.filter((d: any) => {
        if (!d.licenseExpiration) return false;
        const exp = new Date(d.licenseExpiration);
        return exp >= now && exp <= thirtyDays;
      });
      const licensesBucket60 = drivers.filter((d: any) => {
        if (!d.licenseExpiration) return false;
        const exp = new Date(d.licenseExpiration);
        return exp > thirtyDays && exp <= sixtyDays;
      });
      const licensesBucket90 = drivers.filter((d: any) => {
        if (!d.licenseExpiration) return false;
        const exp = new Date(d.licenseExpiration);
        return exp > sixtyDays && exp <= ninetyDays;
      });

      // Missing documents (drivers without required documents)
      const missingDocs = drivers.filter((d: any) => !d.licenseNumber || !d.licenseExpiration).length;

      // Open incidents
      const openIncidents = accidents.filter((a: any) => a.status === 'open' || a.status === 'investigating');

      // Claims in review
      const claimsInReview = accidents.filter((a: any) => a.status === 'pending' || a.status === 'investigating');

      const totalLicensesExpiring = licensesBucket30.length + licensesBucket60.length + licensesBucket90.length;

      const metrics = [
        {
          id: 'licenses-expiring',
          title: 'Licenses Expiring',
          count: totalLicensesExpiring,
          severity: licensesBucket30.length > 0 ? 'critical' : licensesBucket60.length > 0 ? 'high' : 'medium' as const,
          buckets: [
            { label: '30 Days', count: licensesBucket30.length, severity: 'critical' as const },
            { label: '60 Days', count: licensesBucket60.length, severity: 'high' as const },
            { label: '90 Days', count: licensesBucket90.length, severity: 'medium' as const }
          ],
          drilldownRoute: '/reports/compliance?type=licenses',
          icon: 'id-card'
        },
        {
          id: 'missing-documents',
          title: 'Missing Documents',
          count: missingDocs,
          severity: missingDocs > 5 ? 'high' : missingDocs > 0 ? 'medium' : 'low' as const,
          drilldownRoute: '/reports/compliance?type=documents',
          icon: 'file-x'
        },
        {
          id: 'open-incidents',
          title: 'Open Incidents',
          count: openIncidents.length,
          severity: openIncidents.length > 3 ? 'critical' : openIncidents.length > 0 ? 'high' : 'low' as const,
          drilldownRoute: '/reports/incidents?status=open',
          icon: 'alert-triangle'
        },
        {
          id: 'claims-review',
          title: 'Claims In Review',
          count: claimsInReview.length,
          severity: claimsInReview.length > 5 ? 'high' : claimsInReview.length > 0 ? 'medium' : 'low' as const,
          drilldownRoute: '/reports/incidents?status=review',
          icon: 'clipboard-list'
        }
      ];

      res.json({
        metrics,
        totalIssues: totalLicensesExpiring + missingDocs + openIncidents.length + claimsInReview.length,
        lastUpdated: new Date().toISOString()
      });
    } catch (error) {
      console.error("Error fetching dashboard risk:", error);
      res.status(500).json({ message: "Failed to fetch dashboard risk metrics" });
    }
  });

  // Dashboard Trends - Chart data
  app.get("/api/dashboard/trends", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const filters = parseDashboardFilters(req.query);
      const trips = await storage.getAllTrips();
      const drivers = await storage.getAllDriversWithUsers();

      const activeDrivers = drivers.filter((d: any) => d.status === 'active');
      const days = filters.dateRange === 'today' ? 1 : filters.dateRange === '7d' ? 7 : filters.dateRange === '90d' ? 90 : 30;

      const today = new Date();
      today.setHours(0, 0, 0, 0);

      // Trips per day trend
      const tripsByDay: { date: string; value: number; label?: string }[] = [];
      for (let i = days - 1; i >= 0; i--) {
        const date = new Date(today.getTime() - i * 24 * 60 * 60 * 1000);
        const dateStr = date.toISOString().split('T')[0];
        const count = trips.filter((t: any) => {
          if (!t.tripDate) return false;
          const td = new Date(t.tripDate);
          td.setHours(0, 0, 0, 0);
          return td.toISOString().split('T')[0] === dateStr;
        }).length;
        tripsByDay.push({ 
          date: dateStr, 
          value: count,
          label: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
        });
      }

      // Trips per driver (average)
      const tripsPerDriver: { date: string; value: number; label?: string }[] = [];
      for (let i = days - 1; i >= 0; i--) {
        const date = new Date(today.getTime() - i * 24 * 60 * 60 * 1000);
        const dateStr = date.toISOString().split('T')[0];
        const tripCount = trips.filter((t: any) => {
          if (!t.tripDate) return false;
          const td = new Date(t.tripDate);
          td.setHours(0, 0, 0, 0);
          return td.toISOString().split('T')[0] === dateStr;
        }).length;
        const avg = activeDrivers.length > 0 ? Math.round((tripCount / activeDrivers.length) * 10) / 10 : 0;
        tripsPerDriver.push({ 
          date: dateStr, 
          value: avg,
          label: date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })
        });
      }

      res.json({
        tripsPerDriver,
        tripsByDay,
        period: filters.dateRange
      });
    } catch (error) {
      console.error("Error fetching dashboard trends:", error);
      res.status(500).json({ message: "Failed to fetch dashboard trends" });
    }
  });

  // Dashboard Top Drivers
  app.get("/api/dashboard/topDrivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const metric = (req.query.metric as string) || 'trips';
      const filters = parseDashboardFilters(req.query);
      const drivers = await storage.getAllDriversWithUsers();
      const trips = await storage.getAllTrips();

      // Filter trips by date range
      const tripsInRange = trips.filter((t: any) => {
        if (!t.tripDate) return false;
        const tripDate = new Date(t.tripDate);
        return tripDate >= filters.startDate && tripDate <= filters.endDate;
      });

      // Calculate metrics for each driver
      const driverMetrics = drivers.map((driver: any) => {
        const driverTrips = tripsInRange.filter((t: any) => t.driverId === driver.id);
        const completedTrips = driverTrips.filter((t: any) => t.status === 'completed');
        
        return {
          driverId: driver.id,
          driverName: `${driver.user?.firstName || ''} ${driver.user?.lastName || ''}`.trim() || 'Unknown',
          profileImageUrl: driver.user?.profileImageUrl || driver.profilePhotoUrl,
          trips: driverTrips.length,
          hours: driverTrips.length * 2, // Stub: estimate 2 hours per trip
          onTimePercent: completedTrips.length > 0 ? 95 : 0, // Stub: will need actual on-time data
          revenue: 0 // Stub: for future implementation
        };
      });

      // Sort by selected metric
      let sorted;
      switch (metric) {
        case 'hours':
          sorted = driverMetrics.sort((a: any, b: any) => b.hours - a.hours);
          break;
        case 'onTime':
          sorted = driverMetrics.sort((a: any, b: any) => b.onTimePercent - a.onTimePercent);
          break;
        case 'revenue':
          sorted = driverMetrics.sort((a: any, b: any) => (b.revenue || 0) - (a.revenue || 0));
          break;
        default:
          sorted = driverMetrics.sort((a: any, b: any) => b.trips - a.trips);
      }

      res.json({
        drivers: sorted.slice(0, 10),
        metric
      });
    } catch (error) {
      console.error("Error fetching top drivers:", error);
      res.status(500).json({ message: "Failed to fetch top drivers" });
    }
  });

