  /**
   * GET /api/compliance/mvr-expiring-soon
   *
   * Returns drivers whose MVR expiration date falls within the next N days
   * (default 7). Includes primary account name and computed daysRemaining.
   * Sorted soonest-to-expire first.
   *
   * Query params:
   *   days  — lookahead window in days (default 7, max 90)
   *
   * Response: { total, windowDays, drivers: MvrExpiringSoonRow[] }
   */
  app.get("/api/compliance/mvr-expiring-soon", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const userEmail = req.user.claims.email;
      let user = await storage.getUser(userId);
      if (!user && userEmail) user = await storage.getUserByEmail(userEmail);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rawDays = parseInt((req.query.days as string) || "7", 10);
      const windowDays = isNaN(rawDays) || rawDays < 1 ? 7 : Math.min(rawDays, 90);

      // MVR is valid for 365 days from the completion date (mvr_date).
      // Expiration Date = mvr_date + 365 days.
      // Show drivers where expiration falls between today and today + windowDays.
      // This means: mvr_date BETWEEN (today - 365 days) AND (today - 365 days + windowDays).
      const result = await db.execute(sql`
        SELECT
          d.id                                                         AS driver_id,
          u.first_name,
          u.last_name,
          u.email,
          d.status,
          d.mvr_date                                                   AS mvr_completed_date,
          (d.mvr_date + INTERVAL '365 days')::date                    AS mvr_expiration_date,
          365 - (CURRENT_DATE - d.mvr_date)                           AS days_remaining,
          d.drivershift_customer_id                                    AS primary_account_id,
          c.customer_name                                              AS primary_account_name,
          d.driver_number
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        LEFT JOIN customers c ON c.id = d.drivershift_customer_id
        WHERE d.mvr_date IS NOT NULL
          AND (CURRENT_DATE - d.mvr_date) <= 365
          AND (CURRENT_DATE - d.mvr_date) >= 365 - ${windowDays}
          AND d.status = 'active'
        ORDER BY mvr_expiration_date ASC
      `);

      const rows = ((result as any).rows ?? result) as {
        driver_id: string;
        first_name: string | null;
        last_name: string | null;
        email: string | null;
        status: string;
        mvr_completed_date: string;
        mvr_expiration_date: string;
        days_remaining: number;
        primary_account_id: string | null;
        primary_account_name: string | null;
        driver_number: string | null;
      }[];

      return res.json({
        total: rows.length,
        windowDays,
        drivers: rows.map(r => ({
          driverId: r.driver_id,
          firstName: r.first_name,
          lastName: r.last_name,
          email: r.email,
          status: r.status,
          mvrDate: r.mvr_completed_date,
          mvrExpirationDate: r.mvr_expiration_date,
          daysRemaining: r.days_remaining,
          primaryAccountId: r.primary_account_id,
          primaryAccountName: r.primary_account_name,
          driverNumber: r.driver_number,
        })),
      });
    } catch (err: any) {
      console.error("[compliance/mvr-expiring-soon] error:", err?.message);
      return res.status(500).json({ error: err?.message });
    }
  });

