  app.get("/api/compliance/license-submissions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user   = userId ? await storage.getUser(userId) : null;
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Access denied" });
      const { status, driverId } = req.query;
      let q = `SELECT * FROM driver_license_submissions WHERE 1=1`;
      const p: any[] = []; let n = 1;
      if (status)   { q += ` AND status = $${n++}`;    p.push(String(status)); }
      if (driverId) { q += ` AND driver_id = $${n++}`; p.push(String(driverId)); }
      q += ` ORDER BY submitted_at DESC LIMIT 200`;
      const { rows } = await pool.query(q, p);
      res.json(rows);
    } catch (e: any) {
      res.status(500).json({ message: "Failed to fetch submissions" });
    }
  });

