  /**
   * GET /api/compliance/attendance-exceptions
   *
   * Returns two metrics from WIW shift data:
   *   1. scheduledToday  — shifts that started today, not yet ended, no clock-in
   *   2. noShows7d       — shifts ended in last 7 days with no clock-in (true no-shows)
   *
   * Also returns a combined `exceptions[]` list for the drill-down view,
   * sorted: active "late" (today, ongoing) first, then no-shows newest-first.
   *
   * Optional query params:
   *   accountId  — filter by driverhub_account_id
   *   dateFrom   — ISO date string, lower bound on shift start_time
   *   dateTo     — ISO date string, upper bound on shift start_time
   *   status     — "late" | "no_show" | "all" (default "all")
   *
   * Response: { scheduledToday, noShows7d, exceptions: AttendanceExceptionRow[] }
   */
  app.get("/api/compliance/attendance-exceptions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const userEmail = req.user.claims.email;
      let user = await storage.getUser(userId);
      if (!user && userEmail) user = await storage.getUserByEmail(userEmail);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const accountId = (req.query.accountId as string) || null;
      const dateFrom  = (req.query.dateFrom  as string) || null;
      const dateTo    = (req.query.dateTo    as string) || null;
      const statusFilter = (req.query.status as string) || "all";

      // ── Summary counts (always full 7-day window, no user filters applied) ──

      // Data Governance Rule 1+2: acquisition date floor + active users only
      const todayCountResult = await db.execute(sql`
        SELECT COUNT(*)::int AS cnt
        FROM wiw_shifts s
        JOIN wiw_users wu ON wu.id = s.wiw_user_id AND wu.wiw_status = 'active'
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        WHERE s.status != 'deleted'
          AND s.start_time >= '2026-02-09'
          AND s.start_time::date = CURRENT_DATE
          AND s.start_time <= NOW()
          AND t.id IS NULL
      `);
      const scheduledToday: number =
        (((todayCountResult as any).rows ?? todayCountResult)[0] as any)?.cnt ?? 0;

      const noShowCountResult = await db.execute(sql`
        SELECT COUNT(*)::int AS cnt
        FROM wiw_shifts s
        JOIN wiw_users wu ON wu.id = s.wiw_user_id AND wu.wiw_status = 'active'
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        WHERE s.status != 'deleted'
          AND s.start_time >= '2026-02-09'
          AND s.end_time < NOW()
          AND s.start_time >= NOW() - INTERVAL '7 days'
          AND t.id IS NULL
      `);
      const noShows7d: number =
        (((noShowCountResult as any).rows ?? noShowCountResult)[0] as any)?.cnt ?? 0;

      // ── Drill-down list (user filters applied) ───────────────────────────────

      // Build date window: combine today-no-clockin + 7-day no-shows
      // start_time >= 7 days ago AND start_time <= NOW() (covers both cohorts)
      // Data Governance Rule 1+2: acquisition floor + active users enforced below
      const baseConditions = sql`
        s.status != 'deleted'
        AND s.start_time >= '2026-02-09'
        AND s.start_time >= NOW() - INTERVAL '7 days'
        AND s.start_time <= NOW()
        AND t.id IS NULL
      `;

      const accountCond   = accountId ? sql`AND s.driverhub_account_id = ${accountId}` : sql``;
      const dateFromCond  = dateFrom  ? sql`AND s.start_time >= ${dateFrom}::timestamptz` : sql``;
      const dateToCond    = dateTo    ? sql`AND s.start_time <= (${dateTo}::date + INTERVAL '1 day')` : sql``;
      const statusCond    = statusFilter === "late"    ? sql`AND s.end_time >= NOW()`
                          : statusFilter === "no_show" ? sql`AND s.end_time < NOW()`
                          : sql``;

      const drillResult = await db.execute(sql`
        SELECT
          wu.driver_id,
          wu.name                          AS driver_name,
          wu.email                         AS driver_email,
          s.id                             AS shift_id,
          s.start_time,
          s.end_time,
          s.driverhub_account_id           AS account_id,
          c.customer_name,
          CASE
            WHEN s.end_time < NOW() THEN 'no_show'
            ELSE 'late'
          END                              AS exception_status,
          CASE
            WHEN s.end_time >= NOW()
            THEN EXTRACT(EPOCH FROM (NOW() - s.start_time))::int / 60
            ELSE NULL
          END                              AS minutes_late
        FROM wiw_shifts s
        JOIN wiw_users wu ON wu.id = s.wiw_user_id AND wu.wiw_status = 'active'
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        LEFT JOIN customers c ON c.id = s.driverhub_account_id
        WHERE ${baseConditions}
          ${accountCond}
          ${dateFromCond}
          ${dateToCond}
          ${statusCond}
        ORDER BY
          CASE WHEN s.end_time >= NOW() THEN 0 ELSE 1 END,
          s.start_time DESC
        LIMIT 500
      `);

      const rows = ((drillResult as any).rows ?? drillResult) as {
        driver_id: string | null;
        driver_name: string;
        driver_email: string | null;
        shift_id: string;
        start_time: string;
        end_time: string;
        account_id: string | null;
        customer_name: string | null;
        exception_status: "late" | "no_show";
        minutes_late: number | null;
      }[];

      return res.json({
        scheduledToday,
        noShows7d,
        exceptions: rows.map(r => ({
          driverId: r.driver_id,
          driverName: r.driver_name,
          driverEmail: r.driver_email,
          shiftId: r.shift_id,
          startTime: r.start_time,
          endTime: r.end_time,
          accountId: r.account_id,
          accountName: r.customer_name,
          exceptionStatus: r.exception_status,
          minutesLate: r.minutes_late,
        })),
      });
    } catch (err: any) {
      console.error("[compliance/attendance-exceptions] error:", err?.message);
      return res.status(500).json({ error: err?.message });
    }
  });

  /**
   * GET /api/compliance/late-drivers
   *
   * Two metrics:
   *   1. lateToday     — shifts active right now (past 10-min grace), no clock-in
   *   2. lateCount7d   — shifts in last 7 days where clock-in > shift start + 1 min
   *
   * Drill-down combines both cohorts sorted by minutes_late DESC.
   * Each row includes: driver, account, shift start, actual clock-in, minutes late, late_type.
   *
   * Optional query params:
   *   accountId  — filter drill-down by driverhub_account_id
   *   dateFrom   — ISO date, lower bound on shift start_time
   *   dateTo     — ISO date, upper bound on shift start_time
   *   type       — "no_clockin" | "clocked_in_late" | "all" (default "all")
   *
   * Response: { lateToday, lateCount7d, records: LateDriverRecord[] }
   */
  app.get("/api/compliance/late-drivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const userEmail = req.user.claims.email;
      let user = await storage.getUser(userId);
      if (!user && userEmail) user = await storage.getUserByEmail(userEmail);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const accountId  = (req.query.accountId  as string) || null;
      const dateFrom   = (req.query.dateFrom   as string) || null;
      const dateTo     = (req.query.dateTo     as string) || null;
      const typeFilter = (req.query.type       as string) || "all";

      // ── Summary counts (unfiltered, canonical window) ────────────────────────

      const lateTodayResult = await db.execute(sql`
        SELECT COUNT(*)::int AS cnt
        FROM wiw_shifts s
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        WHERE s.status != 'deleted'
          AND s.start_time::date = CURRENT_DATE
          AND s.start_time <= NOW() - INTERVAL '10 minutes'
          AND s.end_time > NOW()
          AND t.id IS NULL
      `);
      const lateToday: number =
        (((lateTodayResult as any).rows ?? lateTodayResult)[0] as any)?.cnt ?? 0;

      const late7dResult = await db.execute(sql`
        SELECT COUNT(*)::int AS cnt
        FROM wiw_shifts s
        JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        WHERE s.status != 'deleted'
          AND s.start_time >= NOW() - INTERVAL '7 days'
          AND t.clock_in > s.start_time + INTERVAL '1 minute'
      `);
      const lateCount7d: number =
        (((late7dResult as any).rows ?? late7dResult)[0] as any)?.cnt ?? 0;

      // ── Drill-down list (filters applied) ────────────────────────────────────

      const accountCond  = accountId ? sql`AND s.driverhub_account_id = ${accountId}` : sql``;
      const dateFromCond = dateFrom  ? sql`AND s.start_time >= ${dateFrom}::timestamptz` : sql``;
      const dateToCond   = dateTo    ? sql`AND s.start_time <= (${dateTo}::date + INTERVAL '1 day')` : sql``;
      const typeCond     = typeFilter === "no_clockin"      ? sql`AND t.clock_in IS NULL`
                         : typeFilter === "clocked_in_late" ? sql`AND t.clock_in IS NOT NULL`
                         : sql``;

      const drillResult = await db.execute(sql`
        SELECT
          wu.driver_id,
          wu.name                                          AS driver_name,
          wu.email                                         AS driver_email,
          s.id                                             AS shift_id,
          s.start_time,
          s.end_time,
          t.clock_in,
          s.driverhub_account_id                           AS account_id,
          c.customer_name,
          CASE
            WHEN t.clock_in IS NOT NULL
            THEN EXTRACT(EPOCH FROM (t.clock_in - s.start_time))::int / 60
            ELSE EXTRACT(EPOCH FROM (NOW() - s.start_time))::int / 60
          END                                              AS minutes_late,
          CASE
            WHEN t.clock_in IS NOT NULL THEN 'clocked_in_late'
            ELSE 'no_clockin'
          END                                              AS late_type
        FROM wiw_shifts s
        JOIN wiw_users wu ON wu.id = s.wiw_user_id
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id
        LEFT JOIN customers c ON c.id = s.driverhub_account_id
        WHERE s.status != 'deleted'
          AND s.start_time >= NOW() - INTERVAL '7 days'
          AND (
            -- Cohort A: late today (ongoing, past grace, no clock-in)
            (
              s.start_time::date = CURRENT_DATE
              AND s.start_time <= NOW() - INTERVAL '10 minutes'
              AND s.end_time > NOW()
              AND t.id IS NULL
            )
            OR
            -- Cohort B: clocked in late (any day in window)
            (
              t.clock_in IS NOT NULL
              AND t.clock_in > s.start_time + INTERVAL '1 minute'
            )
          )
          ${accountCond}
          ${dateFromCond}
          ${dateToCond}
          ${typeCond}
        ORDER BY minutes_late DESC
        LIMIT 500
      `);

      const rows = ((drillResult as any).rows ?? drillResult) as {
        driver_id: string | null;
        driver_name: string;
        driver_email: string | null;
        shift_id: string;
        start_time: string;
        end_time: string;
        clock_in: string | null;
        account_id: string | null;
        customer_name: string | null;
        minutes_late: number;
        late_type: "clocked_in_late" | "no_clockin";
      }[];

      return res.json({
        lateToday,
        lateCount7d,
        records: rows.map(r => ({
          driverId: r.driver_id,
          driverName: r.driver_name,
          driverEmail: r.driver_email,
          shiftId: r.shift_id,
          startTime: r.start_time,
          endTime: r.end_time,
          clockIn: r.clock_in,
          accountId: r.account_id,
          accountName: r.customer_name,
          minutesLate: r.minutes_late,
          lateType: r.late_type,
        })),
      });
    } catch (err: any) {
      console.error("[compliance/late-drivers] error:", err?.message);
      return res.status(500).json({ error: err?.message });
    }
  });

  app.post("/api/corporate/drivers/bulk-action", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!user || !["admin", "super_user"].includes(user.role || "")) {
        return res.status(403).json({ message: "Forbidden: Admin access required" });
      }

      const { action, driverIds } = req.body;
      if (!Array.isArray(driverIds) || driverIds.length === 0) {
        return res.status(400).json({ message: "No drivers selected" });
      }

      let successCount = 0;
      let failCount = 0;

      if (action === "activate" || action === "deactivate") {
        const newStatus = action === "activate" ? "active" : "inactive";
        for (const driverId of driverIds) {
          try {
            await storage.updateDriver(driverId, { status: newStatus } as any);
            successCount++;
          } catch {
            failCount++;
          }
        }
        return res.json({ message: `${action === "activate" ? "Activated" : "Deactivated"} ${successCount} driver(s)`, successCount, failCount });
      }

      return res.status(400).json({ message: "Invalid action" });
    } catch (error) {
      console.error("Error in bulk action:", error);
      res.status(500).json({ message: "Bulk action failed" });
    }
  });

  app.post("/api/corporate/drivers/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden" });
      }

      const { driverIds, mode = "visible", search, statuses, networks, driverTypes, lastAccessDays, includeArchived: exportIncludeArchived } = req.body;
      let driversList = await storage.getAllDriversWithStats(exportIncludeArchived === true);

      if (Array.isArray(driverIds) && driverIds.length > 0) {
        driversList = driversList.filter((d: any) => driverIds.includes(d.id));
      }

      if (search) {
        const term = String(search).toLowerCase();
        driversList = driversList.filter((d: any) => {
          const firstName = (d.user?.firstName || "").toLowerCase();
          const lastName = (d.user?.lastName || "").toLowerCase();
          const fullName = `${firstName} ${lastName}`;
          const email = (d.user?.email || "").toLowerCase();
          const phone = (d.phoneNumber || "").toLowerCase();
          const openforce = (d.openforceId || "").toLowerCase();
          const payId = (d.paymentId || "").toLowerCase();
          return fullName.includes(term) || firstName.includes(term) || lastName.includes(term) || email.includes(term) || phone.includes(term) || openforce.includes(term) || payId.includes(term);
        });
      }
      if (Array.isArray(statuses) && statuses.length > 0) {
        const statusListLower = statuses.map((s: string) => s.toLowerCase());
        driversList = driversList.filter((d: any) => statusListLower.includes((d.status || "").toLowerCase()));
      }
      if (Array.isArray(networks) && networks.length > 0) {
        const includeBlank = networks.includes("__blank__");
        const realNetworksLower = networks.filter((n: string) => n !== "__blank__").map((n: string) => n.toLowerCase());
        driversList = driversList.filter((d: any) => {
          const driverNetwork = (d.network || "").toLowerCase().trim();
          if (includeBlank && !driverNetwork) return true;
          return realNetworksLower.some((n: string) => driverNetwork === n || driverNetwork.includes(n));
        });
      }
      if (typeof driverTypes === "string" && driverTypes !== "all") {
        const typeList = driverTypes.split(",").map((type: string) => type.trim().toLowerCase());
        const includeUnassigned = typeList.includes("__unassigned__");
        const assignedTypes = typeList.filter((type: string) => type !== "__unassigned__");
        driversList = driversList.filter((d: any) => {
          const driverType = (d.driverType || "").trim();
          if (includeUnassigned && !driverType) return true;
          return assignedTypes.includes(driverType.toLowerCase());
        });
      }
      if (lastAccessDays && lastAccessDays !== "all") {
        const days = parseInt(lastAccessDays, 10);
        if (days === 0) {
          driversList = driversList.filter((d: any) => !d.lastAccessAt);
        } else if (!isNaN(days)) {
          const cutoff = new Date();
          cutoff.setDate(cutoff.getDate() - days);
          driversList = driversList.filter((d: any) => d.lastAccessAt && new Date(d.lastAccessAt) >= cutoff);
        }
      }

      const csvEscape = (v: any) => `"${String(v == null ? "" : v).replace(/"/g, '""')}"`;
      const fmtDate = (v: any) => {
        if (!v) return "";
        try { return new Date(v).toISOString().split("T")[0]; } catch { return ""; }
      };
      const fmtTimestamp = (v: any) => {
        if (!v) return "";
        try { return new Date(v).toISOString().replace("T", " ").replace(/\.\d+Z$/, ""); } catch { return ""; }
      };

      if (mode === "full") {
        const allCustomers = await storage.getAllCustomers();
        const allEmployees = await storage.getAllEmployees();
        const allUsers = await db.select().from(users);
        const customerMap = new Map(allCustomers.map((c: any) => [c.id, c.name || c.companyName || ""]));
        const employeeMap = new Map(allEmployees.map((e: any) => [e.id, `${e.firstName || ""} ${e.lastName || ""}`.trim()]));
        const userMap = new Map(allUsers.map((u: any) => [u.id, `${u.firstName || ""} ${u.lastName || ""}`.trim()]));

        const fullHeaders = [
          "Driver ID","User ID","Driver Number","First Name","Last Name","Email","Mobile","Address","City","State","Zip Code",
          "Date of Birth","Gender","Profile Photo URL","Status","Previous Status","Safety State",
          "Driver Type","Driver Classification","Employee ID","Independent Contractor ID",
          "Market","Customer","Recruiter",
          "IC Agreement Signed","IC Agreement URL","CDL Certified","Hazmat Certified",
          "Hire Date","Termination Date","Contract Cancelled Date","Termination Reason","Eligible for Rehire",
          "Termination Updated By","Termination Updated At","Status Changed By","Status Changed At",
          "Inactive Date","Inactive Reason","Date Certified","Certified By",
          "License Number","License State","License Expiration",
          "Drug Test Date","Background Check Date","MVR Date",
          "Base Pay Rate","Fuel Surcharge Rate","Network Pay Rate","Network",
          "Payment ID","OpenForce ID","ADP Marketplace ID","SSN/EIN Last 4","Last Pay Date",
          "Direct Manager","Driver Advocate",
          "Hours WTD","Hours MTD","Hours YTD","Lifetime Hours","Avg Hours/Week",
          "Pay Last Week","Pay WTD","Pay MTD","Pay YTD","Lifetime Pay","Avg Pay/Week",
          "Lifetime Moves","Current Month Moves","Last Month Moves","First Move Date","Last Move Date",
          "Safety Score",
          "Emergency Contact Name","Emergency Contact Relationship","Emergency Contact Phone","Emergency Contact Email",
          "Last Access","Needs Update","Needs Update Reasons","Needs Update Fields",
          "Needs Update Set At","Needs Update Set By","Needs Update Import Batch ID",
          "Created Date","Updated Date"
        ];

        const csvRows = driversList.map((d: any) => {
          return [
            d.id,
            d.userId,
            d.driverNumber,
            d.user?.firstName,
            d.user?.lastName,
            d.user?.email,
            d.phoneNumber,
            d.address,
            d.city,
            d.state,
            d.zipCode,
            d.dateOfBirth,
            d.gender,
            d.profilePhotoUrl,
            d.status,
            d.previousStatus,
            d.safetyState,
            d.driverType,
            d.driverClassification,
            d.employeeId,
            d.independentContractorId,
            d.market,
            customerMap.get(d.drivershiftCustomerId) || "",
            d.recruiter,
            d.icAgreementSigned === "Y" ? "Yes" : d.icAgreementSigned === "N" ? "No" : d.icAgreementSigned,
            d.icAgreementUrl,
            d.cdlCertified,
            d.hazmatCertified,
            d.hireDate,
            d.terminationDate,
            d.contractCancelledDate,
            d.terminationReason,
            d.terminationEligibleForRehire,
            userMap.get(d.terminationUpdatedBy) || d.terminationUpdatedBy || "",
            fmtTimestamp(d.terminationUpdatedAt),
            userMap.get(d.statusChangedBy) || d.statusChangedBy || "",
            fmtTimestamp(d.statusChangedAt),
            d.inactiveDate,
            d.inactiveReason,
            d.dateCertified,
            d.certifiedBy,
            d.licenseNumber,
            d.licenseState,
            d.licenseExpiration,
            d.drugTestDate,
            d.backgroundCheckDate,
            d.mvrDate,
            d.basePayPerMile,
            d.fuelSurchargeRate,
            d.networkPayRate,
            d.network,
            d.paymentId,
            d.openforceId,
            d.adpMarketplaceId,
            d.ssnOrEinLast4,
            d.lastPayDate,
            employeeMap.get(d.directManagerId) || "",
            employeeMap.get(d.driverAdvocateId) || "",
            d.hoursWtd,
            d.hoursMtd,
            d.hoursYtd,
            d.lifetimeHours,
            d.averageHoursPerWeek,
            d.payLastWeek,
            d.payWtd,
            d.payMtd,
            d.payYtd,
            d.lifetimePay,
            d.averagePayPerWeek,
            d.lifetimeMoveCount,
            d.currentMonthMoveCount,
            d.lastMonthMoveCount,
            d.firstMoveDate,
            d.lastMoveDate,
            d.safetyScore,
            d.emergencyContactName,
            d.emergencyContactRelationship,
            d.emergencyContactPhone,
            d.emergencyContactEmail,
            fmtTimestamp(d.lastAccessAt),
            d.needsUpdate ? "Yes" : "No",
            Array.isArray(d.needsUpdateReasons) ? d.needsUpdateReasons.join("; ") : "",
            Array.isArray(d.needsUpdateFields) ? d.needsUpdateFields.join("; ") : "",
            fmtTimestamp(d.needsUpdateSetAt),
            userMap.get(d.needsUpdateSetBy) || d.needsUpdateSetBy || "",
            d.needsUpdateImportBatchId,
            fmtDate(d.createdAt),
            fmtDate(d.updatedAt),
          ].map(csvEscape).join(",");
        }).join("\n");

        res.setHeader("Content-Type", "text/csv");
        res.setHeader("Content-Disposition", "attachment; filename=drivers_full_export.csv");
        res.send(fullHeaders.join(",") + "\n" + csvRows);
      } else {
        const visibleCustomers = await storage.getAllCustomers();
        const visibleCustomerMap = new Map(visibleCustomers.map((c: any) => [c.id, c.customerName || c.companyName || c.name || ""]));

        const visibleHeaders = [
          "First Name",
          "Last Name",
          "Email",
          "Network",
          "Mobile",
          "Created Date",
          "Status",
            "Driver Type",
          "Last Access",
          "Network Pay Rate",
          "Classification",
          "DriverShift Customer",
        ];

        const csvRows = driversList.map((d: any) => {
          return [
            d.user?.firstName || "",
            d.user?.lastName || "",
            d.user?.email || "",
            d.network || "",
            d.phoneNumber || "",
            fmtDate(d.createdAt),
            d.status || "",
            d.driverType?.trim() || "Unassigned",
            fmtTimestamp(d.lastAccessAt),
            d.networkPayRate || "",
            d.driverClassification || "",
            visibleCustomerMap.get(d.drivershiftCustomerId) || "",
          ].map(csvEscape).join(",");
        }).join("\n");

        res.setHeader("Content-Type", "text/csv");
        res.setHeader("Content-Disposition", "attachment; filename=drivers_export.csv");
        res.send(visibleHeaders.join(",") + "\n" + csvRows);
      }
    } catch (error) {
      console.error("Error exporting drivers:", error);
      res.status(500).json({ message: "Export failed" });
    }
  });

  // Archive a driver (corporate admin+ only) — soft delete, never hard delete
  app.post("/api/corporate/drivers/:id/archive", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { id: driverId } = req.params;
      const { reason } = req.body;

      const driver = await storage.getDriver(driverId);
      if (!driver) return res.status(404).json({ message: "Driver not found" });
      if ((driver as any).isDeleted) return res.status(409).json({ message: "Driver is already archived" });

      await storage.archiveDriver(driverId, userId, reason || undefined);

      try {
        const { systemAuditLogService } = await import("./services/systemAuditLogService");
        await systemAuditLogService.log({
          action: "driver.archived",
          entityType: "driver",
          entityId: driverId,
          performedByUserId: userId,
          metadata: { previousStatus: driver.status, reason: reason || null },
        });
      } catch (_) {}

      res.json({ ok: true, message: "Driver archived" });
    } catch (error) {
      console.error("Error archiving driver:", error);
      res.status(500).json({ message: "Failed to archive driver" });
    }
  });

  // Restore an archived driver (Super Admin only)
  app.post("/api/corporate/drivers/:id/restore", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!((user as any)?.isSuperAdmin || (user as any)?.isRootSuperAdmin || user?.role === 'super_admin')) {
        return res.status(403).json({ message: "Forbidden: Super Admin only" });
      }

      const { id: driverId } = req.params;
      const driver = await storage.getDriver(driverId);
      if (!driver) return res.status(404).json({ message: "Driver not found" });
      if (!(driver as any).isDeleted) return res.status(409).json({ message: "Driver is not archived" });

      await storage.restoreDriver(driverId, userId);

      try {
        const { systemAuditLogService } = await import("./services/systemAuditLogService");
        await systemAuditLogService.log({
          action: "driver.restored",
          entityType: "driver",
          entityId: driverId,
          performedByUserId: userId,
          metadata: { restoredToStatus: "inactive" },
        });
      } catch (_) {}

      res.json({ ok: true, message: "Driver restored to inactive status" });
    } catch (error) {
      console.error("Error restoring driver:", error);
      res.status(500).json({ message: "Failed to restore driver" });
    }
  });

  // Get single driver (corporate only)
  app.get("/api/corporate/drivers/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const driverId = req.params.id;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const driver = await storage.getDriverWithUser(req.params.id);
      if (!driver) {
        return res.status(404).json({ message: "Driver not found" });
      }

      // Add termination updated by user name if exists
      let terminationUpdatedByName: string | null = null;
      if (driver.terminationUpdatedBy) {
        const updatedByUser = await storage.getUser(driver.terminationUpdatedBy);
        if (updatedByUser) {
          terminationUpdatedByName = `${updatedByUser.firstName || ''} ${updatedByUser.lastName || ''}`.trim() || updatedByUser.username || 'Unknown';
        }
      }

      // DH-002144: For terminated drivers, expose the most recent status-history termination event
      // so the UI can display termination details even when driver fields are incomplete (legacy data).
      let mostRecentTerminationEvent: any = null;
      if ((driver as any).status === 'terminated') {
        try {
          const [histRow] = await db
            .select()
            .from(driverStatusHistory)
            .where(
              and(
                eq(driverStatusHistory.driverId, driverId),
                eq(driverStatusHistory.eventType, 'terminated')
              )
            )
            .orderBy(desc(driverStatusHistory.createdAt))
            .limit(1);

          if (histRow) {
            let histChangedByName: string | null = null;
            if (histRow.changedByUserId) {
              const histUser = await storage.getUser(histRow.changedByUserId);
              if (histUser) {
                histChangedByName = `${histUser.firstName || ''} ${histUser.lastName || ''}`.trim() || histUser.email || 'Unknown';
              }
            }
            // Most recent reactivation event — used for "Most Recent Reactivation" display
            const [reactivationRow] = await db
              .select({ effectiveDate: driverStatusHistory.effectiveDate })
              .from(driverStatusHistory)
              .where(
                and(
                  eq(driverStatusHistory.driverId, driverId),
                  eq(driverStatusHistory.eventType, 'reactivated')
                )
              )
              .orderBy(desc(driverStatusHistory.effectiveDate))
              .limit(1);

            mostRecentTerminationEvent = {
              id: histRow.id,
              effectiveDate: histRow.effectiveDate,
              reasonCode: histRow.reasonCode,
              createdAt: histRow.createdAt,
              changedByUserId: histRow.changedByUserId,
              changedByName: histChangedByName,
              mostRecentReactivationDate: reactivationRow?.effectiveDate ?? null,
            };
          }
        } catch (histFetchErr) {
          console.error('[DriverDetail] Failed to fetch termination history for display:', histFetchErr);
        }
      }

      let age: number | null = null;
      if (driver.dateOfBirth) {
        // Parse date-only string as UTC to avoid any timezone ambiguity on the server.
        // "YYYY-MM-DD" is returned as a plain string by our Neon type-parser override.
        const [y, m, d] = String(driver.dateOfBirth).split("-").map(Number);
        const dob = new Date(Date.UTC(y, m - 1, d));
        const today = new Date();
        age = today.getUTCFullYear() - dob.getUTCFullYear();
        const monthDiff = today.getUTCMonth() - dob.getUTCMonth();
        if (monthDiff < 0 || (monthDiff === 0 && today.getUTCDate() < dob.getUTCDate())) {
          age--;
        }
      }

      const { canViewFullDriverSsn } = await import("./services/corporatePermissions");
      const canViewFullSsn = canViewFullDriverSsn(user);
      const canEditSsn = hasCorporateAccess(user?.role);

      // Resolve drivershiftCustomerName for Tier-3 primary account fallback
      let drivershiftCustomerName: string | null = null;
      if ((driver as any).drivershiftCustomerId) {
        const [custRow] = await db
          .select({ id: customers.id, customerName: customers.customerName })
          .from(customers)
          .where(eq(customers.id, (driver as any).drivershiftCustomerId))
          .limit(1);
        drivershiftCustomerName = custRow?.customerName ?? null;
      }

      const driverResponse: any = redactDriverSsnFields({
        ...driver,
        terminationUpdatedByName,
        mostRecentTerminationEvent,
        age,
        canViewFullSsn,
        canEditSsn,
        drivershiftCustomerName,
      });

      res.json(driverResponse);
    } catch (error) {
      console.error("Error fetching driver:", error);
      res.status(500).json({ message: "Failed to fetch driver" });
    }
  });

  // Intentional, permission-controlled reveal of a Driver's SSN/EIN.
  // This endpoint re-reads the current user permissions on every request and
  // writes the audit event before returning the sensitive value.
  app.post(
    "/api/corporate/drivers/:id/ssn/reveal",
    isAuthenticated,
    createDriverSsnRevealHandler({
      getUser: (userId) => storage.getUser(userId),
      getDriverScope: async (driverId) => {
        const [driverScope] = await db
          .select({
            id: drivers.id,
          })
          .from(drivers)
          .where(eq(drivers.id, driverId))
          .limit(1);
        return driverScope;
      },
      getEncryptedDriver: async (driverId) => {
        const { ssnOrEinEncrypted } = drivers;
        const [driver] = await db
          .select({
            id: drivers.id,
            ssnOrEinEncrypted,
          })
          .from(drivers)
          .where(eq(drivers.id, driverId))
          .limit(1);
        return driver;
      },
      recordAudit: async (entry) => {
        const { systemAuditLog } = await import("@shared/schema");
        await db.insert(systemAuditLog).values(entry);
      },
    }),
  );

  // Update driver (corporate only)
  app.patch("/api/corporate/drivers/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const driverId = req.params.id;
      const updates = req.body;

      const allowedDriverFields = [
        'phoneNumber', 'address', 'city', 'state', 'zipCode', 'dateOfBirth',
        'emergencyContactName', 'emergencyContactPhone', 'emergencyContactEmail',
        'emergencyContactRelationship', 'driverType', 'employmentType', 'driverNumber',
        'licenseNumber', 'licenseState', 'licenseExpiration', 'hireDate',
        'basePayPerMile', 'fuelSurchargeRate', 'status', 'driverClassification',
        'market', 'drivershiftCustomerId', 'drivershiftCustomerIds', 'employeeId', 'independentContractorId', 'openforceId',
        'terminationDate', 'contractCancelledDate', 'terminationReason', 'terminationEligibleForRehire', 'reactivationDate',
        'paymentId', 'drugTestDate', 'mvrDate', 'recruiter', 'directManager', 'network', 'certifiedBy', 'dateCertified', 'gender',
        'ssnOrEinEncrypted'
      ];

      const allowedUserFields = ['firstName', 'lastName'];

      const driverUpdates: Record<string, any> = {};
      const userUpdates: Record<string, any> = {};

      for (const key of Object.keys(updates)) {
        if (allowedDriverFields.includes(key)) {
          driverUpdates[key] = updates[key];
        } else if (allowedUserFields.includes(key)) {
          userUpdates[key] = updates[key];
        }
      }

      // Coerce empty strings to null for all driver fields so FK/nullable columns
      // are never written with "" (which violates FK constraints or wastes storage)
      for (const key of Object.keys(driverUpdates)) {
        if (driverUpdates[key] === "") {
          driverUpdates[key] = null;
        }
      }

      // SSN permission gate — corporate and above may update
      if (driverUpdates.ssnOrEinEncrypted !== undefined) {
        if (!hasCorporateAccess(user?.role)) {
          return res.status(403).json({ message: "Forbidden: Insufficient permissions to update SSN/EIN" });
        }
        // Extract and persist last-4 digits alongside the encrypted value
        const ssnVal = String(driverUpdates.ssnOrEinEncrypted || '');
        const digits = ssnVal.replace(/\D/g, '');
        driverUpdates.ssnOrEinLast4 = digits.slice(-4) || null;
      }

      if (Object.keys(driverUpdates).length === 0 && Object.keys(userUpdates).length === 0) {
        return res.status(400).json({ message: "No valid fields to update" });
      }

      // Get driver to find associated user
      const driver = await storage.getDriverWithUser(driverId);
      if (!driver) {
        return res.status(404).json({ message: "Driver not found" });
      }

      // Validate compliance & profile fields
      if (driverUpdates.paymentId !== undefined && driverUpdates.paymentId) {
        if (!/^[a-zA-Z0-9]*$/.test(driverUpdates.paymentId)) {
          return res.status(422).json({ message: "Payment ID must be alphanumeric", field: "paymentId" });
        }
        if (driverUpdates.paymentId.length > 12) {
          return res.status(422).json({ message: "Payment ID must be 12 characters or less", field: "paymentId" });
        }
      }
      if (driverUpdates.recruiter !== undefined && driverUpdates.recruiter) {
        const { RECRUITER_VALUES } = await import("@shared/schema");
        if (!RECRUITER_VALUES.includes(driverUpdates.recruiter as any)) {
          return res.status(422).json({ message: `Recruiter "${driverUpdates.recruiter}" is not a valid recruiter. Must be one of: ${RECRUITER_VALUES.join(", ")}`, field: "recruiter" });
        }
      }
      if (driverUpdates.certifiedBy !== undefined && driverUpdates.certifiedBy) {
        const { CERTIFIED_BY_VALUES } = await import("@shared/schema");
        if (!CERTIFIED_BY_VALUES.includes(driverUpdates.certifiedBy as any)) {
          return res.status(422).json({ message: `Certified By "${driverUpdates.certifiedBy}" is not valid. Must be one of: ${CERTIFIED_BY_VALUES.join(", ")}`, field: "certifiedBy" });
        }
      }
      if (driverUpdates.network !== undefined && driverUpdates.network) {
        if (driverUpdates.network.length > 50) {
          return res.status(422).json({ message: "Network must be 50 characters or less", field: "network" });
        }
      }
      if (driverUpdates.certifiedBy !== undefined && driverUpdates.certifiedBy) {
        if (!/^[a-zA-Z0-9 ]*$/.test(driverUpdates.certifiedBy)) {
          return res.status(422).json({ message: "Certified By must be alphanumeric (letters, numbers, and spaces)", field: "certifiedBy" });
        }
        if (driverUpdates.certifiedBy.length > 20) {
          return res.status(422).json({ message: "Certified By must be 20 characters or less", field: "certifiedBy" });
        }
      }
      if (driverUpdates.networkPayRate !== undefined && driverUpdates.networkPayRate) {
        const rate = parseFloat(driverUpdates.networkPayRate);
        if (isNaN(rate) || rate < 0 || rate > 999.99) {
          return res.status(422).json({ message: "Network Pay Rate must be a valid currency amount (0.00-999.99)", field: "networkPayRate" });
        }
        driverUpdates.networkPayRate = rate.toFixed(2);
      }
      if (driverUpdates.gender !== undefined && driverUpdates.gender) {
        if (!/^[a-zA-Z0-9]*$/.test(driverUpdates.gender)) {
          return res.status(422).json({ message: "Gender must be alphanumeric", field: "gender" });
        }
        if (driverUpdates.gender.length > 8) {
          return res.status(422).json({ message: "Gender must be 8 characters or less", field: "gender" });
        }
      }
      if (driverUpdates.drugTestDate !== undefined) {
        if (driverUpdates.drugTestDate === '' || driverUpdates.drugTestDate === null) {
          driverUpdates.drugTestDate = null;
        } else if (isNaN(Date.parse(driverUpdates.drugTestDate))) {
          return res.status(422).json({ message: "Invalid date for Drug Test Date", field: "drugTestDate" });
        }
      }
      if (driverUpdates.mvrDate !== undefined) {
        if (driverUpdates.mvrDate === '' || driverUpdates.mvrDate === null) {
          driverUpdates.mvrDate = null;
        } else if (isNaN(Date.parse(driverUpdates.mvrDate))) {
          return res.status(422).json({ message: "Invalid date for MVR Record Date", field: "mvrDate" });
        }
      }

      // Handle status change audit
      if (driverUpdates.status !== undefined && driverUpdates.status !== driver.status) {
        const validStatuses = ["active", "onboarding", "inactive", "suspended", "terminated"];
        const normalizedStatus = String(driverUpdates.status).toLowerCase();
        if (!validStatuses.includes(normalizedStatus)) {
          return res.status(422).json({ message: `Invalid status. Must be one of: ${validStatuses.join(", ")}`, field: "status" });
        }
        driverUpdates.status = normalizedStatus;
        driverUpdates.previousStatus = driver.status || "active";
        driverUpdates.statusChangedBy = userId;
        driverUpdates.statusChangedAt = new Date();
      }

      // DH-002144: Block status=terminated when no termination date exists or is being set.
      // A driver must never reach Terminated status while termination data silently fails to save.
      // Directs users to the lifecycle form which captures the full termination transaction atomically.
      if (driverUpdates.status === 'terminated' && (driver as any).status !== 'terminated') {
        const incomingTermDate   = driverUpdates.terminationDate;
        const incomingCancelDate = driverUpdates.contractCancelledDate;
        const existingTermDate   = (driver as any).terminationDate;
        const existingCancelDate = (driver as any).contractCancelledDate;
        const willHaveDate =
          (incomingTermDate   && incomingTermDate   !== '') ||
          (incomingCancelDate && incomingCancelDate !== '') ||
          (existingTermDate   && existingTermDate   !== '') ||
          (existingCancelDate && existingCancelDate !== '');
        if (!willHaveDate) {
          return res.status(400).json({
            message: "Cannot set status to Terminated without a termination or contract cancellation date. Use the Termination lifecycle form to record the full termination details.",
            code: "TERMINATION_REQUIRES_DATE",
          });
        }
      }

      // Handle termination fields validation and audit
      
      // Check if reason is being updated and validate length
      // terminationReason is a structured dropdown value — no length restriction needed
      
      // Calculate final state after this update
      const finalTerminationDate = driverUpdates.terminationDate !== undefined ? driverUpdates.terminationDate : driver.terminationDate;
      const finalContractCancelledDate = driverUpdates.contractCancelledDate !== undefined ? driverUpdates.contractCancelledDate : driver.contractCancelledDate;
      const finalReason = driverUpdates.terminationReason !== undefined ? driverUpdates.terminationReason : driver.terminationReason;
      const finalEligibleForRehire = driverUpdates.terminationEligibleForRehire !== undefined ? driverUpdates.terminationEligibleForRehire : driver.terminationEligibleForRehire;
      
      // If final state has a termination/cancellation date, reason and eligible for rehire are required.
      // Only enforce when termination-related fields are part of this update — do NOT block saves of
      // unrelated fields (phone, address, etc.) on historical drivers with incomplete termination data.
      // Per product spec: "Require the missing fields the next time the termination details are edited."
      const isTerminationRelatedUpdate =
        driverUpdates.terminationDate !== undefined ||
        driverUpdates.contractCancelledDate !== undefined ||
        driverUpdates.terminationReason !== undefined ||
        driverUpdates.terminationEligibleForRehire !== undefined;

      const hasDateInFinalState = (finalTerminationDate && finalTerminationDate !== '') || 
                                   (finalContractCancelledDate && finalContractCancelledDate !== '');
      const hasValidReason = finalReason && finalReason.trim() !== '';
      const hasValidEligible = finalEligibleForRehire && finalEligibleForRehire.trim() !== '';
      
      if (isTerminationRelatedUpdate && hasDateInFinalState) {
        if (!hasValidReason) {
          return res.status(400).json({ message: "Termination Reason is required when a termination or contract cancelled date is set.", code: "TERMINATION_REQUIRES_REASON" });
        }
        if (!hasValidEligible) {
          return res.status(400).json({ message: "Eligible for Rehire is required when a termination or contract cancelled date is set.", code: "TERMINATION_REQUIRES_ELIGIBLE" });
        }
      }
      
      // Set audit fields when any termination-related field changes
      const terminationFieldsChanged = 
        (driverUpdates.terminationDate !== undefined && driverUpdates.terminationDate !== driver.terminationDate) ||
        (driverUpdates.contractCancelledDate !== undefined && driverUpdates.contractCancelledDate !== driver.contractCancelledDate) ||
        (driverUpdates.terminationReason !== undefined && driverUpdates.terminationReason !== driver.terminationReason) ||
        (driverUpdates.terminationEligibleForRehire !== undefined && driverUpdates.terminationEligibleForRehire !== driver.terminationEligibleForRehire);
      
      if (terminationFieldsChanged) {
        driverUpdates.terminationUpdatedBy = userId;
        driverUpdates.terminationUpdatedAt = new Date();
      }

      // Auto-derive status from termination dates when status is not explicitly provided.
      // Only fires when the termination/cancellation DATE itself changes — never when only
      // reason or eligibleForRehire changes. Changing rehire eligibility must not trigger
      // a status transition (DH-002051).
      const terminationDateChanged =
        (driverUpdates.terminationDate !== undefined && driverUpdates.terminationDate !== driver.terminationDate) ||
        (driverUpdates.contractCancelledDate !== undefined && driverUpdates.contractCancelledDate !== driver.contractCancelledDate);

      if (driverUpdates.status === undefined && terminationDateChanged) {
        const resolvedTermDate = driverUpdates.terminationDate !== undefined ? driverUpdates.terminationDate : driver.terminationDate;
        const resolvedCancelDate = driverUpdates.contractCancelledDate !== undefined ? driverUpdates.contractCancelledDate : driver.contractCancelledDate;
        const hasTermDate = !!(resolvedTermDate && resolvedTermDate !== '');
        const hasCancelDate = !!(resolvedCancelDate && resolvedCancelDate !== '');
        if (hasTermDate || hasCancelDate) {
          driverUpdates.status = 'terminated';
          driverUpdates.previousStatus = driver.status || 'active';
          driverUpdates.statusChangedBy = userId;
          driverUpdates.statusChangedAt = new Date();
        } else if (driver.status === 'terminated') {
          driverUpdates.status = 'active';
          driverUpdates.previousStatus = 'terminated';
          driverUpdates.statusChangedBy = userId;
          driverUpdates.statusChangedAt = new Date();
        }
      }

      // Update user fields if any
      if (Object.keys(userUpdates).length > 0) {
        const previousUserValues: Record<string, any> = {};
        for (const key of Object.keys(userUpdates)) {
          previousUserValues[key] = (driver as any).user?.[key] ?? null;
        }
        await storage.updateUser(driver.userId, userUpdates);
        // Audit name changes
        const nameFields = ['firstName', 'lastName'].filter(f => userUpdates[f] !== undefined);
        if (nameFields.length > 0) {
          try {
            const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
            await writeSystemAuditEvent({
              eventType: 'driver_name_updated',
              actorUserId: userId,
              actorUserEmail: (user as any)?.email,
              targetEntityType: 'driver',
              targetEntityId: driverId,
              targetEntityLabel: `Driver ${driverId}`,
              previousValue: Object.fromEntries(nameFields.map(f => [f, previousUserValues[f]])),
              newValue: Object.fromEntries(nameFields.map(f => [f, userUpdates[f]])),
              ipAddress: req.ip,
            });
          } catch (auditErr) {
            console.error('[Driver Name Audit] Failed to write audit event:', auditErr);
          }
        }
      }

      // Update driver fields if any
      let updatedDriver = driver;
      if (Object.keys(driverUpdates).length > 0) {
        updatedDriver = await storage.updateDriver(driverId, driverUpdates);
        if (!updatedDriver) {
          return res.status(404).json({ message: "Driver not found" });
        }

        // Phone normalization — runs whenever phoneNumber is part of this update
        if (driverUpdates.phoneNumber !== undefined) {
          try {
            const { validatePhone } = await import("./services/phoneNormalizationService");
            const norm = validatePhone(driverUpdates.phoneNumber);
            await pool.query(
              `UPDATE drivers
                  SET mobile_phone_normalized  = $1,
                      mobile_phone_is_valid    = $2,
                      sms_eligible             = $3,
                      sms_invalid_reason       = $4,
                      last_phone_validation_at = now(),
                      updated_at               = now()
                WHERE id = $5`,
              [norm.normalized, norm.isValid, norm.smsEligible, norm.invalidReason, driverId]
            );
            console.log(`[PhoneNorm] PATCH driver ${driverId}: eligible=${norm.smsEligible} reason=${norm.invalidReason ?? "none"}`);
          } catch (normErr) {
            console.error("[PhoneNorm] PATCH normalization failed (non-fatal):", normErr);
          }
        }

        // Emit driver updated event for Ops Console
        try {
          const { detectDriverChangedFields, emitDriverUpdatedEvent } = await import("./driverMasterDataService");
          const changedFields = detectDriverChangedFields(driver as unknown as Record<string, unknown>, updatedDriver as unknown as Record<string, unknown>);
          if (changedFields.length > 0) {
            await emitDriverUpdatedEvent(driverId, changedFields, userId);
          }
        } catch (eventError) {
          console.error("[Driver Update] Failed to emit driver event:", eventError);
        }

        // Write driver status history record for lifecycle events
        try {
          const historyRows: any[] = [];

          if (driverUpdates.previousStatus !== undefined && driverUpdates.status !== undefined) {
            // Status transition occurred — classify the event type
            const newSt = driverUpdates.status as string;
            const priorSt = driverUpdates.previousStatus as string;
            let eventType: string;
            if (newSt === 'terminated') {
              eventType = 'terminated';
            } else if (priorSt === 'terminated') {
              eventType = 'reactivated';
            } else {
              eventType = 'status_changed';
            }
            const effectiveDate =
              newSt === 'terminated'
                ? (driverUpdates.terminationDate || driverUpdates.contractCancelledDate || new Date().toISOString().split('T')[0])
                : priorSt === 'terminated'
                ? (driverUpdates.reactivationDate || new Date().toISOString().split('T')[0])
                : new Date().toISOString().split('T')[0];

            historyRows.push({
              driverId,
              eventType,
              priorStatus: priorSt,
              newStatus: newSt,
              effectiveDate: effectiveDate || null,
              reasonCode: (driverUpdates.terminationReason || (driver as any).terminationReason) ?? null,
              changedByUserId: userId,
              sourceType: 'manual',
            });
          } else {
            // No status change — check if termination or reactivation date was explicitly set
            const termDateChanged =
              (driverUpdates.terminationDate !== undefined && driverUpdates.terminationDate !== (driver as any).terminationDate) ||
              (driverUpdates.contractCancelledDate !== undefined && driverUpdates.contractCancelledDate !== (driver as any).contractCancelledDate);
            const reactivationDateChanged =
              driverUpdates.reactivationDate !== undefined &&
              driverUpdates.reactivationDate !== (driver as any).reactivationDate;

            if (termDateChanged && (driverUpdates.terminationDate || driverUpdates.contractCancelledDate)) {
              historyRows.push({
                driverId,
                eventType: 'terminated',
                priorStatus: (driver as any).status || 'active',
                newStatus: 'terminated',
                effectiveDate: driverUpdates.terminationDate || driverUpdates.contractCancelledDate || null,
                reasonCode: (driverUpdates.terminationReason || (driver as any).terminationReason) ?? null,
                changedByUserId: userId,
                sourceType: 'manual',
              });
            }
            if (reactivationDateChanged && driverUpdates.reactivationDate) {
              historyRows.push({
                driverId,
                eventType: 'reactivated',
                priorStatus: (driver as any).status || 'active',
                newStatus: (driver as any).status || 'active',
                effectiveDate: driverUpdates.reactivationDate,
                changedByUserId: userId,
                sourceType: 'manual',
              });
            }
          }

          for (const row of historyRows) {
            await db.insert(driverStatusHistory).values(row);
          }
        } catch (histErr) {
          console.error('[DriverStatusHistory] Failed to write history record:', histErr);
        }
      }

      // Re-evaluate needs_update flag after edit
      try {
        const { evaluateAndApplySingleDriver } = await import("./services/driverNeedsUpdateEngine");
        await evaluateAndApplySingleDriver(driverId, "system");
      } catch (evalErr) {
        console.error("[NeedsUpdate] Post-update evaluation failed:", evalErr);
      }

      // SSN/EIN DWP sync — keeps tasks for Susanne Beebe + leadership in sync
      try {
        const { syncSsnEinDwpItems } = await import("./services/ssnEinDwpService");
        const finalStatus = (updatedDriver as any)?.status ?? driver.status;
        const finalSsn = (updatedDriver as any)?.ssnOrEinEncrypted ?? (driver as any).ssnOrEinEncrypted;
        const driverFirstName = (driver as any)?.user?.firstName || "";
        const driverLastName = (driver as any)?.user?.lastName || "";
        const driverFullName = `${driverFirstName} ${driverLastName}`.trim() || "Unknown Driver";
        await syncSsnEinDwpItems(driverId, driverFullName, finalStatus, finalSsn, user?.orgId ?? null);
      } catch (ssnDwpErr) {
        console.error("[SSN/EIN DWP] Sync failed (non-critical):", ssnDwpErr);
      }

      // Sync Employee record when driver is classified as Employee
      try {
        const finalClassification =
          (updatedDriver as any)?.driverClassification ?? (driver as any)?.driverClassification;
        if (finalClassification === "Employee") {
          const { syncEmployeeFromDriver } = await import("./services/driverEmployeeSyncService");
          await syncEmployeeFromDriver(driverId, { triggeredBy: "auto", triggeredByUserId: userId });
        }
      } catch (empSyncErr) {
        console.error("[DriverEmployeeSync] Sync failed (non-critical):", empSyncErr);
      }

      // Return updated driver with user, never the full SSN/EIN.
      const refreshedDriver = await storage.getDriverWithUser(driverId);
      const { canViewFullDriverSsn } = await import("./services/corporatePermissions");
      const refreshedResponse: any = redactDriverSsnFields({
        ...refreshedDriver,
        canViewFullSsn: canViewFullDriverSsn(user),
        canEditSsn: hasCorporateAccess(user?.role),
      });
      res.json(refreshedResponse);
    } catch (error: any) {
      console.error("Error updating driver:", error);
      console.error("Error details:", error.message, error.stack);
      res.status(500).json({ message: "Failed to update driver", error: error.message });
    }
  });

  // GET /api/corporate/drivers/:id/linked-employee — return the linked Employee record (or null)
  app.get("/api/corporate/drivers/:id/linked-employee", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;
      const driverRow = await storage.getDriverWithUser(driverId);
      if (!driverRow) return res.status(404).json({ message: "Driver not found" });

      // Search by drivers.employeeId first, then by employees.driver_id
      let linkedEmployee: any = null;
      if ((driverRow as any).employeeId) {
        linkedEmployee = await storage.getEmployee((driverRow as any).employeeId);
      }
      if (!linkedEmployee) {
        const rows = await db
          .select()
          .from(employees)
          .where(eq(employees.driverId as any, driverId))
          .limit(1);
        linkedEmployee = rows[0] ?? null;
      }

      res.json({ employee: linkedEmployee });
    } catch (err: any) {
      console.error("[linked-employee GET]", err);
      res.status(500).json({ message: "Failed to fetch linked employee" });
    }
  });

  // POST /api/corporate/drivers/:id/sync-employee — manual sync trigger
  app.post("/api/corporate/drivers/:id/sync-employee", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;
      const { syncEmployeeFromDriver } = await import("./services/driverEmployeeSyncService");
      const result = await syncEmployeeFromDriver(driverId, { triggeredBy: "manual", triggeredByUserId: userId });
      res.json({ success: true, ...result });
    } catch (err: any) {
      console.error("[sync-employee POST]", err);
      res.status(400).json({ message: err.message || "Sync failed" });
    }
  });

  // GET /api/corporate/drivers/:id/sync-log — driver→employee sync audit trail
  app.get("/api/corporate/drivers/:id/sync-log", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;
      const limit = Math.min(parseInt(String(req.query.limit ?? "50"), 10), 200);

      const rows = await db
        .select()
        .from(driverEmployeeSyncLog)
        .where(eq(driverEmployeeSyncLog.driverId, driverId))
        .orderBy(sql`synced_at DESC`)
        .limit(limit);

      res.json({ logs: rows });
    } catch (err: any) {
      console.error("[sync-log GET]", err);
      res.status(500).json({ message: "Failed to fetch sync log" });
    }
  });

  // GET /api/drivers/:id/status-history — append-only lifecycle audit trail
  app.get("/api/drivers/:id/status-history", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const driverId = req.params.id;

      const rows = await db
        .select({
          id: driverStatusHistory.id,
          driverId: driverStatusHistory.driverId,
          eventType: driverStatusHistory.eventType,
          priorStatus: driverStatusHistory.priorStatus,
          newStatus: driverStatusHistory.newStatus,
          effectiveDate: driverStatusHistory.effectiveDate,
          reasonCode: driverStatusHistory.reasonCode,
          notes: driverStatusHistory.notes,
          sourceType: driverStatusHistory.sourceType,
          createdAt: driverStatusHistory.createdAt,
          changedByUserId: driverStatusHistory.changedByUserId,
          changedByName: sql<string | null>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        })
        .from(driverStatusHistory)
        .leftJoin(users, eq(driverStatusHistory.changedByUserId, users.id))
        .where(eq(driverStatusHistory.driverId, driverId))
        .orderBy(desc(driverStatusHistory.createdAt));

      res.json(rows);
    } catch (error: any) {
      console.error('[DriverStatusHistory] GET error:', error);
      res.status(500).json({ message: 'Failed to fetch status history' });
    }
  });

  // POST /api/drivers/:id/lifecycle — append a lifecycle event (termination or reactivation)
  // This endpoint handles the full cycle: validates chronological ordering, updates the driver
  // record, and appends an immutable row to driver_status_history.
  app.post("/api/drivers/:id/lifecycle", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;
      const { eventType, date, reason, eligibleForRehire } = req.body as {
        eventType: string; date: string; reason?: string; eligibleForRehire?: string;
      };

      if (!["terminated", "reactivated"].includes(eventType))
        return res.status(400).json({ message: "eventType must be 'terminated' or 'reactivated'" });
      if (!date || !/^\d{4}-\d{2}-\d{2}$/.test(date))
        return res.status(400).json({ message: "date is required (YYYY-MM-DD)" });
      if (eventType === "terminated") {
        if (!reason?.trim()) return res.status(400).json({ message: "reason is required for termination" });
        if (!eligibleForRehire?.trim()) return res.status(400).json({ message: "eligibleForRehire is required for termination" });
      }

      const driver = await storage.getDriver(driverId);
      if (!driver) return res.status(404).json({ message: "Driver not found" });

      // Chronological guard: new event date must be >= the most recent TERMINATION or
      // REACTIVATION event (ordered by effective_date, not created_at). System events such
      // as driver_created / activated are intentionally excluded — they represent onboarding
      // timestamps that should not prevent backdated terminations.
      const lastLifecycleRow = await db
        .select({ effectiveDate: driverStatusHistory.effectiveDate })
        .from(driverStatusHistory)
        .where(
          and(
            eq(driverStatusHistory.driverId, driverId),
            inArray(driverStatusHistory.eventType, ["terminated", "reactivated"])
          )
        )
        .orderBy(desc(driverStatusHistory.effectiveDate))
        .limit(1);

      if (lastLifecycleRow.length && lastLifecycleRow[0].effectiveDate) {
        const lastDate = String(lastLifecycleRow[0].effectiveDate).slice(0, 10);
        if (date < lastDate) {
          const label = eventType === "terminated" ? "termination" : "reactivation";
          return res.status(400).json({
            message: `The selected ${label} date must be on or after the driver's most recent lifecycle event (${lastDate}).`,
          });
        }
      }

      const isEmployee = (driver as any).driverClassification === "Employee";

      // Build driver field updates
      const driverUpdates: Record<string, any> = {};
      let newStatus: string;
      let priorStatus: string = (driver as any).status || "active";

      if (eventType === "terminated") {
        if (isEmployee) {
          driverUpdates.terminationDate = date;
          driverUpdates.contractCancelledDate = null;
        } else {
          driverUpdates.contractCancelledDate = date;
          driverUpdates.terminationDate = null;
        }
        driverUpdates.terminationReason = reason!;
        driverUpdates.terminationEligibleForRehire = eligibleForRehire!;
        driverUpdates.terminationUpdatedBy = userId;
        driverUpdates.terminationUpdatedAt = new Date();
        driverUpdates.status = "terminated";
        driverUpdates.previousStatus = priorStatus;
        driverUpdates.statusChangedBy = userId;
        driverUpdates.statusChangedAt = new Date();
        newStatus = "terminated";
      } else {
        // reactivated — preserve all existing termination fields, just add reactivation date
        driverUpdates.reactivationDate = date;
        driverUpdates.status = "active";
        driverUpdates.previousStatus = priorStatus;
        driverUpdates.statusChangedBy = userId;
        driverUpdates.statusChangedAt = new Date();
        newStatus = "active";
      }

      await storage.updateDriver(driverId, driverUpdates);

      await db.insert(driverStatusHistory).values({
        driverId,
        eventType,
        priorStatus,
        newStatus,
        effectiveDate: date,
        reasonCode: reason ?? null,
        changedByUserId: userId,
        sourceType: "manual",
      });

      const updated = await storage.getDriver(driverId);

      // Evaluate linked user's access eligibility after termination/reactivation
      const linkedUserId: string | undefined = (driver as any).userId;
      let accessWarning: string | undefined;
      if (linkedUserId) {
        try {
          if (eventType === "terminated") {
            const { enforceEligibilityOrDisable } = await import("./accessEligibility");
            const result = await enforceEligibilityOrDisable(linkedUserId, userId, `driver_terminated:${driverId}`);
            if (result.disabled) {
              accessWarning = `DriverHub access has been automatically disabled for ${result.userName} — no remaining active Driver or Employee record.`;
            }
          } else if (eventType === "reactivated") {
            const { reevaluateAfterReactivation } = await import("./accessEligibility");
            const result = await reevaluateAfterReactivation(linkedUserId, userId, `driver_reactivated:${driverId}`);
            if (result.enabled) {
              accessWarning = `DriverHub access has been automatically restored for ${result.userName}.`;
            }
          }
        } catch (eligErr) {
          console.error("[LifecycleEvent] Access eligibility evaluation failed:", eligErr);
        }
      }

      return res.json(accessWarning ? { ...updated, _accessWarning: accessWarning } : updated);
    } catch (e: any) {
      console.error("[LifecycleEvent] error:", e);
      res.status(500).json({ message: "Failed to record lifecycle event" });
    }
  });

  // Pre-flight: check whether terminating this driver would disable the linked user's access
