  // Create a new driver (corporate only)
  app.post("/api/corporate/drivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { firstName, lastName, email: rawEmail, ...driverData } = req.body;

      // Generate a placeholder email if none provided so the user record can be created
      const email = rawEmail || `driver-${Date.now()}-${Math.random().toString(36).substr(2, 9)}@noemail.local`;

      // Check if email already exists (only meaningful when a real email was supplied)
      const existingUser = rawEmail ? await storage.getUserByEmail(email) : null;
      if (existingUser) {
        // Check if this user is already a driver
        const existingDriver = await storage.getDriverByUserId(existingUser.id);
        if (existingDriver) {
          return res.status(400).json({ message: "A driver with this email already exists" });
        }
      }

      // RULE: Driver record creation must NEVER change an existing user's role.
      // Role is only set to 'driver' when provisioning a brand-new account with no prior access.
      // Any existing user — regardless of their current role — keeps their role unchanged.
      const isExistingUser = !!existingUser;

      if (isExistingUser) {
        console.log(`[Driver Create] Linking driver record to existing user ${existingUser!.email} (role: ${existingUser!.role}) — role preserved, no access change.`);
      }

      // Create or upsert user record
      const newUserId = existingUser?.id || `driver-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      const newUser = await storage.upsertUser({
        id: newUserId,
        firstName: firstName || "",
        lastName: lastName || "",
        email,
        // Existing users always keep their current role — only new accounts default to 'driver'
        role: isExistingUser ? (existingUser!.role as any) : 'driver',
      });

      // Create driver record linked to user
      const validatedDriverData = insertDriverSchema.parse({
        userId: newUser.id,
        ...driverData,
      });

      const driver = await storage.createDriver(validatedDriverData);

      // Phone normalization on create
      try {
        const rawPhone = (validatedDriverData as any).phoneNumber ?? null;
        const { validatePhone } = await import("./services/phoneNormalizationService");
        const norm = validatePhone(rawPhone);
        await pool.query(
          `UPDATE drivers
              SET mobile_phone_normalized  = $1,
                  mobile_phone_is_valid    = $2,
                  sms_eligible             = $3,
                  sms_invalid_reason       = $4,
                  last_phone_validation_at = now()
            WHERE id = $5`,
          [norm.normalized, norm.isValid, norm.smsEligible, norm.invalidReason, driver.id]
        );
        console.log(`[PhoneNorm] CREATE driver ${driver.id}: eligible=${norm.smsEligible} reason=${norm.invalidReason ?? "none"}`);
      } catch (normErr) {
        console.error("[PhoneNorm] CREATE normalization failed (non-fatal):", normErr);
      }

      // Auto-provision: link driver record to user.
      // For existing users: ONLY update driverId — never touch role, status, or password flags.
      // For brand-new accounts: set role + status as part of onboarding provisioning.
      try {
        const provisionUpdates: Record<string, any> = {
          driverId: driver.id,
          updatedAt: new Date(),
        };
        if (!isExistingUser) {
          provisionUpdates.role = 'driver';
          provisionUpdates.status = 'INVITED';
          provisionUpdates.isProvisioned = false;
          provisionUpdates.forcePasswordReset = true;
        }
        await db.update(users).set(provisionUpdates).where(eq(users.id, newUser.id));
      } catch (linkErr) {
        console.error("[Driver Auto-Provision] Failed to link user to driver:", linkErr);
      }

      const driverWithUser = await storage.getDriverWithUser(driver.id);

      // Emit driver created event for Ops Console
      try {
        const { emitDriverCreatedEvent } = await import("./driverMasterDataService");
        await emitDriverCreatedEvent(driver.id, userId);
      } catch (eventError) {
        console.error("[Driver Create] Failed to emit driver event:", eventError);
      }

      // Write initial status history record
      try {
        await db.insert(driverStatusHistory).values({
          driverId: driver.id,
          eventType: 'driver_created',
          priorStatus: null,
          newStatus: (driver as any).status || 'active',
          effectiveDate: (driverData as any).hireDate || new Date().toISOString().split('T')[0],
          changedByUserId: userId,
          sourceType: 'manual',
        });
      } catch (histErr) {
        console.error('[DriverStatusHistory] Failed to write initial history record:', histErr);
      }

      // Evaluate needs_update flag for newly created driver
      try {
        const { evaluateAndApplySingleDriver } = await import("./services/driverNeedsUpdateEngine");
        await evaluateAndApplySingleDriver(driver.id, "system");
      } catch (evalErr) {
        console.error("[NeedsUpdate] Post-create evaluation failed:", evalErr);
      }

      // SSN/EIN DWP sync for new driver
      try {
        const { syncSsnEinDwpItems } = await import("./services/ssnEinDwpService");
        const driverFullName = [firstName, lastName].filter(Boolean).join(" ") || "Unknown Driver";
        await syncSsnEinDwpItems(
          driver.id,
          driverFullName,
          (driver as any).status ?? "active",
          (driver as any).ssnOrEinEncrypted ?? null,
          user?.orgId ?? null,
        );
      } catch (ssnDwpErr) {
        console.error("[SSN/EIN DWP] Post-create sync failed (non-critical):", ssnDwpErr);
      }

      // Auto-provision: send invitation email with classification-appropriate messaging
      const workEmail = driverData.workEmail || email;
      const classification = driverData.driverClassification || 'Employee';
      if (workEmail) {
        try {
          const inviteCode = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);
          const expiresAt = new Date();
          expiresAt.setDate(expiresAt.getDate() + 7);

          const existingInvitation = await storage.getInvitationByEmail(workEmail);
          if (!existingInvitation || existingInvitation.usedAt) {
            await storage.createUserInvitation({
              email: workEmail,
              role: "driver",
              invitedBy: userId,
              inviteCode,
              expiresAt,
            });

            await sendInvitationEmail({
              to: workEmail,
              firstName: firstName,
              lastName: lastName,
              role: classification === 'Independent Contractor' ? 'independent_contractor' : 'driver',
              inviteCode,
            });
          }
        } catch (emailError) {
          console.error("Error sending driver invitation email:", emailError);
        }
      }

      // Auto-create linked Employee record for Employee-classified drivers
      try {
        if ((driverData as any).driverClassification === "Employee") {
          const { syncEmployeeFromDriver } = await import("./services/driverEmployeeSyncService");
          await syncEmployeeFromDriver(driver.id, { triggeredBy: "auto", triggeredByUserId: userId });
        }
      } catch (empSyncErr) {
        console.error("[DriverEmployeeSync] Post-create auto-sync failed (non-critical):", empSyncErr);
      }

      res.json(driverWithUser);
    } catch (error) {
      if (error instanceof z.ZodError) {
        const errorMessages = error.errors.map(e => e.message).join(', ');
        return res.status(400).json({ message: errorMessages || "Validation error", errors: error.errors });
      }
      console.error("Error creating driver:", error);
      res.status(500).json({ message: "Failed to create driver" });
    }
  });

