  // PATCH /api/corporate/drivers/:id/notes/:noteId — Corporate, Corporate Admin, Super User: edit note with reason (immutable audit)
  app.patch("/api/corporate/drivers/:id/notes/:noteId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      const canEditNotes = !!(user as any)?.isRootSuperAdmin ||
        ["super_user", "super_admin", "corporate_admin", "corporate"].includes(user?.role ?? "");
      if (!canEditNotes) {
        return res.status(403).json({
          message: "You do not have permission to edit notes.",
          error_code: "PERMISSION_DENIED",
        });
      }

      const { noteText, reason } = req.body ?? {};
      if (!noteText || String(noteText).trim().length < 1) {
        return res.status(400).json({ message: "noteText is required." });
      }
      if (!reason || String(reason).trim().length < 10) {
        return res.status(400).json({ message: "A reason of at least 10 characters is required to edit a note." });
      }

      const note = await storage.getDriverNote(req.params.noteId);
      if (!note || note.deletedAt) {
        return res.status(404).json({ message: "Note not found." });
      }

      const updated = await storage.editDriverNote(
        req.params.noteId, userId, String(noteText).trim(), String(reason).trim()
      );

      const { writeSystemAuditEvent } = await import("./services/systemAuditLogService");
      await writeSystemAuditEvent({
        eventType: "note_edited",
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: "note",
        targetEntityId: req.params.noteId,
        targetEntityLabel: `Driver ${req.params.id} note`,
        reason: String(reason).trim(),
        previousValue: { noteText: note.originalContent ?? note.noteText },
        newValue: { noteText: String(noteText).trim() },
        ipAddress: req.ip,
      });

      res.json(updated);
    } catch (error) {
      console.error("Error editing note:", error);
      res.status(500).json({ message: "Failed to edit note" });
    }
  });

  // DELETE /api/corporate/drivers/:id/notes/:noteId — Corporate, Corporate Admin, Super User: soft-delete with reason (immutable audit)
  app.delete("/api/corporate/drivers/:id/notes/:noteId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      const canDeleteNotes = !!(user as any)?.isRootSuperAdmin ||
        ["super_user", "super_admin", "corporate_admin", "corporate"].includes(user?.role ?? "");
      if (!canDeleteNotes) {
        return res.status(403).json({
          message: "You do not have permission to delete notes.",
          error_code: "PERMISSION_DENIED",
        });
      }

      const { reason } = req.body ?? {};
      if (!reason || String(reason).trim().length < 10) {
        return res.status(400).json({ message: "A reason of at least 10 characters is required to remove a note." });
      }

      const note = await storage.getDriverNote(req.params.noteId);
      if (!note || note.deletedAt) {
        return res.status(404).json({ message: "Note not found or already removed." });
      }

      await storage.softDeleteDriverNote(req.params.noteId, userId, String(reason).trim());

      const { writeSystemAuditEvent } = await import("./services/systemAuditLogService");
      await writeSystemAuditEvent({
        eventType: "note_deleted",
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: "note",
        targetEntityId: req.params.noteId,
        targetEntityLabel: `Driver ${req.params.id} note`,
        reason: String(reason).trim(),
        previousValue: { noteText: note.noteText, isImportant: note.isImportant },
        ipAddress: req.ip,
      });

      res.json({ success: true, message: "Note soft-deleted and audit record created." });
    } catch (error) {
      console.error("Error removing note:", error);
      res.status(500).json({ message: "Failed to remove note" });
    }
  });

  // ── GET /api/corporate/drivers/:id/communications — unified Notes & Comms timeline
  app.get("/api/corporate/drivers/:id/communications", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const driverId = req.params.id;

      // 1. Notes — created_at is TIMESTAMP WITHOUT TIME ZONE (stored as UTC).
      //    Use to_char() so pg always returns a clean ISO-Z string regardless of type-parser config.
      const notesResult = await pool.query(
        `SELECT
           dn.id, dn.note_text AS content, dn.note_type, dn.is_imported,
           dn.author_name,
           to_char(dn.created_at, 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS timestamp,
           u.first_name, u.last_name, u.email, u.profile_image_url
         FROM driver_notes dn
         LEFT JOIN users u ON u.id = dn.corporate_user_id
         WHERE dn.driver_id = $1 AND dn.deleted_at IS NULL
         ORDER BY dn.created_at DESC`,
        [driverId]
      );

      // 2. SMS / Email communication logs — sent_at/created_at are TIMESTAMPTZ.
      //    Convert to UTC then format with to_char() for a clean ISO-Z string.
      const commsResult = await pool.query(
        `SELECT
           dcl.id, dcl.channel, dcl.provider, dcl.message_body AS content,
           dcl.subject, dcl.status, dcl.recipient_phone, dcl.recipient_name,
           dcl.external_message_id, dcl.bulk_send_id, dcl.context_module,
           dcl.group_signature,
           to_char(COALESCE(dcl.sent_at, dcl.created_at) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS timestamp,
           u.first_name, u.last_name, u.email, u.profile_image_url
         FROM driver_communication_logs dcl
         LEFT JOIN users u ON u.id = dcl.sent_by_user_id
         WHERE dcl.driver_id = $1
         ORDER BY dcl.created_at DESC`,
        [driverId]
      );

      // 3. Call logs — call_date is TIMESTAMPTZ.
      //    Convert to UTC then format with to_char() for a clean ISO-Z string.
      const callsResult = await pool.query(
        `SELECT
           dcl.id, dcl.call_type, dcl.duration_minutes, dcl.outcome,
           dcl.notes AS content,
           to_char(dcl.call_date AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS timestamp,
           u.first_name, u.last_name, u.email, u.profile_image_url
         FROM driver_call_logs dcl
         LEFT JOIN users u ON u.id = dcl.logged_by_user_id
         WHERE dcl.driver_id = $1
         ORDER BY dcl.call_date DESC`,
        [driverId]
      );

      // 4. Inbound SMS replies — stored in communication_messages by the Heymarket inbound webhook.
      const inboundResult = await pool.query(
        `SELECT
           cm.id,
           cm.body AS content,
           cm.from_identity AS sender_phone,
           cm.provider_message_id,
           to_char(COALESCE(cm.sent_at, cm.created_at) AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"') AS timestamp,
           u.first_name, u.last_name
         FROM communication_messages cm
         LEFT JOIN drivers d ON d.id = cm.related_entity_id
         LEFT JOIN users u ON u.id = d.user_id
         WHERE cm.direction = 'inbound'
           AND cm.channel   = 'sms'
           AND cm.provider  = 'heymarket'
           AND cm.related_entity_id = $1
         ORDER BY cm.created_at DESC`,
        [driverId]
      );

      const items: any[] = [];

      for (const row of notesResult.rows) {
        items.push({
          id: row.id,
          type: "note",
          timestamp: row.timestamp,
          content: row.content,
          metadata: { noteType: row.note_type, isImported: row.is_imported },
          author: {
            name: row.is_imported && row.author_name
              ? row.author_name
              : (row.first_name && row.last_name ? `${row.first_name} ${row.last_name}` : row.email ?? "Unknown"),
            avatar: row.profile_image_url ?? null,
          },
        });
      }

      for (const row of commsResult.rows) {
        items.push({
          id: row.id,
          type: row.channel === "email" ? "email" : "sms",
          timestamp: row.timestamp,
          content: row.content ?? row.subject ?? "",
          metadata: {
            direction: "outbound",
            status: row.status,
            provider: row.provider,
            subject: row.subject,
            bulkSendId: row.bulk_send_id,
            contextModule: row.context_module,
            recipientPhone: row.recipient_phone,
            groupSignature: row.group_signature ?? null,
          },
          author: {
            name: row.first_name && row.last_name ? `${row.first_name} ${row.last_name}` : row.email ?? "System",
            avatar: row.profile_image_url ?? null,
          },
        });
      }

      for (const row of callsResult.rows) {
        items.push({
          id: row.id,
          type: "call",
          timestamp: row.timestamp,
          content: row.content ?? "",
          metadata: {
            callType: row.call_type,
            durationMinutes: row.duration_minutes,
            outcome: row.outcome,
          },
          author: {
            name: row.first_name && row.last_name ? `${row.first_name} ${row.last_name}` : row.email ?? "Unknown",
            avatar: row.profile_image_url ?? null,
          },
        });
      }

      for (const row of inboundResult.rows) {
        const driverFullName = row.first_name && row.last_name
          ? `${row.first_name} ${row.last_name}`.trim()
          : "Driver";
        items.push({
          id: row.id,
          type: "sms",
          timestamp: row.timestamp,
          content: row.content ?? "",
          metadata: {
            direction: "inbound",
            status: "received",
            provider: "heymarket",
            recipientPhone: row.sender_phone,
          },
          author: {
            name: driverFullName,
            avatar: null,
          },
        });
      }

      // Sort by timestamp descending
      items.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());

      res.json({ items });
    } catch (e: any) {
      console.error("[DriverComms]", e);
      res.status(500).json({ message: e.message });
    }
  });

  // ── GET /api/corporate/drivers/:id/sms-thread — full SMS conversation for a driver+phone pair
  // Returns all outbound (driver_communication_logs) and inbound (communication_messages) SMS messages
  // for the driver, optionally scoped to a specific phone number, ordered chronologically (ascending).
  app.get("/api/corporate/drivers/:id/sms-thread", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;
      const rawPhone  = (req.query.phone as string | undefined) ?? "";

      // Normalise to E.164 so we can match both tables cleanly.
      // Both tables store numbers as +1XXXXXXXXXX — strip to digits then re-add +.
      const digits = rawPhone.replace(/\D/g, "");
      const normPhone = digits.length === 10
        ? `+1${digits}`
        : digits.length === 11 && digits[0] === "1"
        ? `+${digits}`
        : rawPhone; // pass through if already formatted

      // ── 1. Outbound — driver_communication_logs ──────────────────────────
      const outboundQ = normPhone
        ? `SELECT
             dcl.id,
             'outbound' AS direction,
             dcl.message_body  AS body,
             dcl.status,
             dcl.group_signature,
             dcl.external_message_id AS provider_message_id,
             COALESCE(dcl.sent_at, dcl.created_at) AS ts,
             u.first_name, u.last_name, u.email, u.profile_image_url
           FROM driver_communication_logs dcl
           LEFT JOIN users u ON u.id = dcl.sent_by_user_id
           WHERE dcl.driver_id      = $1
             AND dcl.channel        = 'sms'
             AND dcl.recipient_phone = $2`
        : `SELECT
             dcl.id,
             'outbound' AS direction,
             dcl.message_body  AS body,
             dcl.status,
             dcl.group_signature,
             dcl.external_message_id AS provider_message_id,
             COALESCE(dcl.sent_at, dcl.created_at) AS ts,
             u.first_name, u.last_name, u.email, u.profile_image_url
           FROM driver_communication_logs dcl
           LEFT JOIN users u ON u.id = dcl.sent_by_user_id
           WHERE dcl.driver_id = $1
             AND dcl.channel   = 'sms'`;

      const outboundParams = normPhone ? [driverId, normPhone] : [driverId];
      const outboundResult = await pool.query(outboundQ, outboundParams);

      // ── 2. Inbound — communication_messages ─────────────────────────────
      const inboundQ = normPhone
        ? `SELECT
             cm.id,
             'inbound' AS direction,
             cm.body,
             cm.status,
             NULL AS group_signature,
             cm.provider_message_id,
             COALESCE(cm.sent_at, cm.created_at) AS ts,
             u.first_name, u.last_name, u.email,
             u.profile_image_url
           FROM communication_messages cm
           LEFT JOIN drivers d ON d.id = cm.related_entity_id
           LEFT JOIN users u ON u.id = d.user_id
           WHERE cm.related_entity_id = $1
             AND cm.direction         = 'inbound'
             AND cm.channel           = 'sms'
             AND cm.from_identity     = $2`
        : `SELECT
             cm.id,
             'inbound' AS direction,
             cm.body,
             cm.status,
             NULL AS group_signature,
             cm.provider_message_id,
             COALESCE(cm.sent_at, cm.created_at) AS ts,
             u.first_name, u.last_name, u.email,
             u.profile_image_url
           FROM communication_messages cm
           LEFT JOIN drivers d ON d.id = cm.related_entity_id
           LEFT JOIN users u ON u.id = d.user_id
           WHERE cm.related_entity_id = $1
             AND cm.direction         = 'inbound'
             AND cm.channel           = 'sms'`;

      const inboundParams = normPhone ? [driverId, normPhone] : [driverId];
      const inboundResult = await pool.query(inboundQ, inboundParams);

      // ── 3. Merge and sort chronologically (ascending for chat display) ───
      const messages: any[] = [];

      for (const row of outboundResult.rows) {
        const senderName = row.first_name && row.last_name
          ? `${row.first_name} ${row.last_name}`
          : row.email ?? "Staff";
        messages.push({
          id:              row.id,
          direction:       "outbound",
          body:            row.body ?? "",
          status:          row.status ?? "sent",
          senderName,
          senderAvatar:    row.profile_image_url ?? null,
          groupSignature:  row.group_signature ?? null,
          providerMessageId: row.provider_message_id ?? null,
          timestamp:       row.ts ? new Date(row.ts).toISOString() : null,
        });
      }

      for (const row of inboundResult.rows) {
        const driverName = row.first_name && row.last_name
          ? `${row.first_name} ${row.last_name}`
          : "Driver";
        messages.push({
          id:              row.id,
          direction:       "inbound",
          body:            row.body ?? "",
          status:          "received",
          senderName:      driverName,
          senderAvatar:    row.profile_image_url ?? null,
          groupSignature:  null,
          providerMessageId: row.provider_message_id ?? null,
          timestamp:       row.ts ? new Date(row.ts).toISOString() : null,
        });
      }

      // Ascending order for chat-bubble display (oldest first).
      messages.sort((a, b) => {
        const ta = a.timestamp ? new Date(a.timestamp).getTime() : 0;
        const tb = b.timestamp ? new Date(b.timestamp).getTime() : 0;
        return ta - tb;
      });

      res.json({ messages, phone: normPhone || null, total: messages.length });
    } catch (e: any) {
      console.error("[DriverSmsThread]", e);
      res.status(500).json({ message: e.message });
    }
  });

