  // ── POST /api/corporate/drivers/:id/send-mvr-request ─────────────────────────
  // Sends the standardised MVR request email, stamps mvr_request_sent_date and
  // mvr_progress on the driver record, and logs the outbound communication.
  app.post("/api/corporate/drivers/:id/send-mvr-request", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const driverId = req.params.id;

      // ── Resolve driver + email ───────────────────────────────────────────────
      const driverRows = await db.execute(sql`
        SELECT d.id, u.first_name, u.last_name, u.email
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        WHERE d.id = ${driverId}
        LIMIT 1
      `);
      const driverRow = ((driverRows as any).rows ?? driverRows)[0];
      if (!driverRow) return res.status(404).json({ message: "Driver not found" });

      const driverName = `${driverRow.first_name || ""} ${driverRow.last_name || ""}`.trim() || "Driver";
      const recipientEmail: string | null = driverRow.email ?? null;

      if (!recipientEmail) {
        return res.status(400).json({ message: "This driver does not have an email address on file." });
      }

      // ── Build email ──────────────────────────────────────────────────────────
      const subject = "DOD: Updated Motor Vehicle Report";
      const bodyHtml = `
<p>Hi ${driverName},</p>
<p>I hope this message finds you well. As part of Driver on Demand's ongoing compliance program, we need an updated Motor Vehicle Record (MVR) on file for you.</p>
<p>Please submit your updated MVR at your earliest convenience. This is required to maintain your active status with Driver on Demand.</p>
<p>If you have any questions or need assistance with this process, please don't hesitate to reach out to our compliance team.</p>
<p>Thank you for your prompt attention to this matter.</p>
<br/>
<p>Best regards,<br/>
Driver on Demand Compliance Team<br/>
<a href="mailto:reports@driverondemand.co">reports@driverondemand.co</a></p>
      `.trim();

      // ── Send via Microsoft Graph ─────────────────────────────────────────────
      const { sendEmail } = await import("./services/microsoftGraphService");
      const emailResult = await sendEmail({ to: [recipientEmail], subject, bodyHtml });

      if (emailResult.skipped) {
        return res.status(503).json({ message: "Email service is not configured. Please contact your administrator." });
      }
      if (!emailResult.ok) {
        return res.status(500).json({ message: "Email delivery failed.", detail: emailResult.error });
      }

      // ── Update driver fields ─────────────────────────────────────────────────
      await db.execute(sql`
        UPDATE drivers
        SET
          mvr_request_sent_date   = CURRENT_DATE,
          mvr_progress            = 'Link Sent',
          mvr_progress_updated_at = NOW()
        WHERE id = ${driverId}
      `);

      // ── Log communication ────────────────────────────────────────────────────
      const messageBody = `MVR request email sent to ${recipientEmail}. Subject: "${subject}"`;
      await pool.query(
        `INSERT INTO driver_communication_logs
           (driver_id, sent_by_user_id, channel, provider, recipient_email, recipient_name,
            subject, message_body, status, sent_at, context_module, context_entity_id)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9, NOW(), $10, $11)`,
        [
          driverId,
          userId,
          "email",
          "microsoft_graph",
          recipientEmail,
          driverName,
          subject,
          messageBody,
          "sent",
          "compliance_mvr",
          driverId,
        ]
      );

      // ── Invalidate server-side caches ────────────────────────────────────────
      res.json({
        ok: true,
        recipientEmail,
        driverName,
        sentAt: new Date().toISOString(),
      });
    } catch (e: any) {
      console.error("[send-mvr-request]", e);
      res.status(500).json({ message: "Failed to send MVR request email" });
    }
  });

  // ── PATCH /api/corporate/drivers/:id/mvr-progress ─────────────────────────
  // Manual state transition for the MVR compliance workflow.
  // Valid states: Not Started | Link Sent | Unresponsive | Waiting for Results | Completed
  // Constraint: "Completed" requires mvr_result to already be set or provided in body.
  app.patch("/api/corporate/drivers/:id/mvr-progress", isAuthenticated, async (req: any, res: Response) => {
    const VALID_STATES = ["Not Started", "Link Sent", "Unresponsive", "Waiting for Results", "Completed"];
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const driverId = req.params.id;
      if (!driverId) return res.status(400).json({ message: "Invalid driver ID" });

      const { progress, result: mvrResult } = req.body as { progress: string; result?: string };
      if (!progress || !VALID_STATES.includes(progress)) {
        return res.status(400).json({ message: `Invalid progress value. Must be one of: ${VALID_STATES.join(", ")}` });
      }

      // If completing, validate that a result is available
      if (progress === "Completed") {
        let effectiveResult = mvrResult;
        if (!effectiveResult) {
          const rows = await pool.query<{ mvr_result: string | null }>(
            `SELECT mvr_result FROM drivers WHERE id = $1`, [driverId]
          );
          effectiveResult = rows.rows[0]?.mvr_result ?? undefined;
        }
        if (!effectiveResult) {
          return res.status(422).json({
            message: "Cannot mark Completed without an MVR result. Please enter a result (Passed / Failed / Pending Review) first.",
          });
        }
      }

      const setClauses: string[] = ["mvr_progress = $1", "mvr_progress_updated_at = NOW()"];
      const params: unknown[] = [progress, driverId];
      if (mvrResult) {
        setClauses.push(`mvr_result = $${params.length}`);
        params.splice(params.length - 1, 0, mvrResult);
      }
      await pool.query(
        `UPDATE drivers SET ${setClauses.join(", ")} WHERE id = $${params.length}`,
        params
      );

      res.json({ ok: true, driverId, progress, result: mvrResult ?? null });
    } catch (e: any) {
      console.error("[mvr-progress PATCH]", e);
      res.status(500).json({ message: "Failed to update MVR progress" });
    }
  });

  // Delete driver comment (corporate only - only author can delete)
  app.delete("/api/corporate/drivers/:id/comments/:commentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Policy: Comments are append-only. Only Super Admin can remove with a reason.
      const isSuperAdmin = !!(user as any)?.isRootSuperAdmin || user?.role === "super_user";
      if (!isSuperAdmin) {
        return res.status(403).json({
          message: "Comments are append-only per data governance policy. Contact a Super Admin to request removal.",
          error_code: "APPEND_ONLY_POLICY",
        });
      }

      const comment = await storage.getComment(req.params.commentId);
      if (!comment) {
        return res.status(404).json({ message: "Comment not found" });
      }

      const { reason } = req.body ?? {};
      if (!reason || String(reason).trim().length < 10) {
        return res.status(400).json({ message: "A reason of at least 10 characters is required to remove a comment." });
      }

      const { writeSystemAuditEvent } = await import("./services/systemAuditLogService");
      await storage.softDeleteDriverComment(req.params.commentId, userId, String(reason).trim());

      await writeSystemAuditEvent({
        eventType: "comment_deleted",
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: "comment",
        targetEntityId: req.params.commentId,
        targetEntityLabel: `Driver ${req.params.id} comment`,
        reason: String(reason).trim(),
        previousValue: { commentText: comment.commentText, authorId: comment.authorId },
        ipAddress: req.ip,
      });

      res.json({ message: "Comment removed (soft-deleted with audit record)." });
    } catch (error) {
      console.error("Error removing comment:", error);
      res.status(500).json({ message: "Failed to remove comment" });
    }
  });

