  // Create exception for a move (ops roles only)
  app.post("/api/moves/:moveId/exceptions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { moveId } = req.params;
      
      // Verify move exists
      const move = await db.select().from(trips).where(eq(trips.id, moveId)).limit(1);
      if (!move.length) {
        return res.status(404).json({ message: "Move not found" });
      }

      const { type, severity, public_message, internal_notes } = req.body;

      // Validate type
      const validTypes = ['DRIVER_DELAYED', 'VEHICLE_NOT_READY', 'CUSTOMER_UNAVAILABLE', 'WEATHER', 'OTHER'];
      if (!type || !validTypes.includes(type)) {
        return res.status(400).json({ message: `Invalid type. Must be one of: ${validTypes.join(', ')}` });
      }

      // Validate severity
      const validSeverities = ['LOW', 'MEDIUM', 'HIGH'];
      if (!severity || !validSeverities.includes(severity)) {
        return res.status(400).json({ message: `Invalid severity. Must be one of: ${validSeverities.join(', ')}` });
      }

      // Get user's display name
      const createdByName = user?.firstName && user?.lastName 
        ? `${user.firstName} ${user.lastName}`
        : user?.email || 'Unknown User';

      const [newException] = await db.insert(moveExceptions).values({
        moveId,
        type,
        severity,
        publicMessage: public_message || null,
        internalNotes: internal_notes || null,
        createdByUserId: userId,
        createdByName,
      }).returning();

      // Send DELAY_EXCEPTION notification to customer if enabled and has public message
      if (newException.publicMessage && move[0].customerId) {
        const customer = await storage.getCustomer(move[0].customerId);
        if (customer?.email && customer.contactUserId) {
          sendCustomerNotificationIfEnabled(
            customer.contactUserId,
            'DELAY_EXCEPTION',
            () => sendDelayExceptionNotification({
              to: customer.email!,
              customerName: customer.name || 'Customer',
              moveNumber: move[0].moveNumber || move[0].id,
              publicMessage: newException.publicMessage!,
              exceptionType: newException.type,
            })
          );
        }
      }

      res.status(201).json({
        id: newException.id,
        move_id: newException.moveId,
        type: newException.type,
        severity: newException.severity,
        public_message: newException.publicMessage,
        internal_notes: newException.internalNotes,
        created_by_user_id: newException.createdByUserId,
        created_by_name: newException.createdByName,
        created_at: newException.createdAt?.toISOString(),
      });
    } catch (error) {
      console.error("Error creating move exception:", error);
      res.status(500).json({ message: "Failed to create move exception" });
    }
  });

