  // ==========================================
  // CLAIM NARRATIVE ENDPOINTS
  // ==========================================

  // GET /api/claims/:claimId/narrative — fetch stored narrative (with staleness flag)
  app.get("/api/claims/:claimId/narrative", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { claimId } = req.params;
      const accident = await storage.getAccidentById(claimId);
      if (!accident) return res.status(404).json({ message: "Claim not found" });

      const { claimNarratives } = await import("../shared/schema");
      const [row] = await db.select().from(claimNarratives)
        .where(eq(claimNarratives.accidentId, claimId))
        .limit(1);

      if (!row) return res.json({ exists: false });

      // Compute current input hash to detect staleness
      let driver: any = null;
      if (accident.driverId) { try { driver = await storage.getDriver(accident.driverId); } catch {} }
      let attachmentCount = 0;
      try { attachmentCount = await storage.getAttachmentCountByAccidentId(claimId); } catch {}

      const { buildInputHash } = await import("./services/claimNarrativeService");
      const currentHash = buildInputHash(accident, driver, attachmentCount);
      const isStale = !!row.inputHash && row.inputHash !== currentHash;

      const content = row.isEdited && row.editedContent ? row.editedContent : row.generatedContent;

      res.json({
        exists: true,
        id: row.id,
        content,
        generatedContent: row.generatedContent,
        editedContent: row.editedContent,
        isEdited: row.isEdited,
        isStale,
        generatedAt: row.generatedAt,
        lastEditedAt: row.lastEditedAt,
      });
    } catch (error) {
      console.error("Error fetching claim narrative:", error);
      res.status(500).json({ message: "Failed to fetch narrative" });
    }
  });

  // POST /api/claims/:claimId/narrative/generate — AI generate (or regenerate)
  app.post("/api/claims/:claimId/narrative/generate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { claimId } = req.params;
      const accident = await storage.getAccidentById(claimId);
      if (!accident) return res.status(404).json({ message: "Claim not found" });

      let driver: any = null;
      if (accident.driverId) { try { driver = await storage.getDriver(accident.driverId); } catch {} }
      let attachmentCount = 0;
      try { attachmentCount = await storage.getAttachmentCountByAccidentId(claimId); } catch {}

      const { generateClaimNarrative, buildInputHash } = await import("./services/claimNarrativeService");
      const sections = await generateClaimNarrative(accident, driver, attachmentCount);
      const inputHash = buildInputHash(accident, driver, attachmentCount);

      const { claimNarratives } = await import("../shared/schema");

      // Upsert — one narrative record per claim
      const [existing] = await db.select({ id: claimNarratives.id })
        .from(claimNarratives)
        .where(eq(claimNarratives.accidentId, claimId))
        .limit(1);

      const now = new Date();
      if (existing) {
        await db.update(claimNarratives)
          .set({
            generatedContent: sections as any,
            inputHash,
            generatedAt: now,
            updatedAt: now,
            // Reset edited flag when regenerating
            isEdited: false,
            editedContent: null,
          })
          .where(eq(claimNarratives.id, existing.id));
      } else {
        await db.insert(claimNarratives).values({
          accidentId: claimId,
          generatedContent: sections as any,
          inputHash,
          generatedAt: now,
        });
      }

      res.json({ content: sections, generatedAt: now });
    } catch (error) {
      console.error("Error generating claim narrative:", error);
      res.status(500).json({ message: "Failed to generate narrative. AI service may be unavailable." });
    }
  });

  // PATCH /api/claims/:claimId/narrative — save user edits
  app.patch("/api/claims/:claimId/narrative", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { claimId } = req.params;
      const { content } = req.body;
      if (!content || typeof content !== "object") {
        return res.status(400).json({ message: "content is required and must be an object with narrative sections" });
      }

      const { claimNarratives } = await import("../shared/schema");

      const [existing] = await db.select({ id: claimNarratives.id })
        .from(claimNarratives)
        .where(eq(claimNarratives.accidentId, claimId))
        .limit(1);

      const now = new Date();
      if (!existing) {
        // No AI narrative yet — store edits as generatedContent so it still shows
        await db.insert(claimNarratives).values({
          accidentId: claimId,
          generatedContent: content as any,
          editedContent: content as any,
          isEdited: true,
          lastEditedAt: now,
          lastEditedByUserId: userId,
        });
      } else {
        await db.update(claimNarratives)
          .set({
            editedContent: content as any,
            isEdited: true,
            lastEditedAt: now,
            lastEditedByUserId: userId,
            updatedAt: now,
          })
          .where(eq(claimNarratives.id, existing.id));
      }

      res.json({ success: true });
    } catch (error) {
      console.error("Error saving claim narrative:", error);
      res.status(500).json({ message: "Failed to save narrative" });
    }
  });

