      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Get all accidents/claims with move info
      const claimsWithMoves = await db
        .select({
          id: accidents.id,
          driverId: accidents.driverId,
          customerId: accidents.customerId,
          moveId: accidents.moveId,
          incidentDate: accidents.incidentDate,
          accidentDate: accidents.accidentDate,
          incidentType: accidents.incidentType,
          status: accidents.status,
          claimStatus: accidents.claimStatus,
          description: accidents.description,
          notesReceived: accidents.notesReceived,
          location: accidents.location,
          totalEstimate: accidents.totalEstimate,
          createdAt: accidents.createdAt,
          // Move details
          moveNumber: trips.moveNumber,
          tripDate: trips.tripDate,
        })
        .from(accidents)
        .leftJoin(trips, eq(accidents.moveId, trips.id))
        .orderBy(sql`${accidents.createdAt} DESC`);

