  // Update driver accident (corporate only)
  app.patch("/api/corporate/drivers/:id/accidents/:accidentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Import claim state machine helpers
      const { isClaimEditable, CLAIM_STATUSES } = await import('./helpers/claimStateMachine');
      type ClaimStatus = typeof CLAIM_STATUSES[number];

      // Get current claim to check editability
      const currentAccident = await storage.getAccidentById(req.params.accidentId);
      if (!currentAccident) {
        return res.status(404).json({ message: "Claim not found" });
      }

      const currentStatus = (currentAccident.claimStatus || 'DRAFT') as ClaimStatus;

      // Block claim_status changes via generic PATCH
      if (req.body.claimStatus !== undefined) {
        return res.status(400).json({ 
          message: "Cannot change claim status via this endpoint. Use POST /api/claims/:claimId/transition instead." 
        });
      }

      // Enforce claim editability after SUBMITTED
      if (!isClaimEditable(currentStatus)) {
        return res.status(403).json({ 
          message: `Claim cannot be edited in ${currentStatus} status. Claims in Denied, Paid, or Closed status are locked.` 
        });
      }

      if (req.body.accidentDate !== undefined || req.body.incidentDate !== undefined) {
        const dateToValidate = req.body.incidentDate || req.body.accidentDate;
        const { validateIncidentDate } = await import("@shared/schema");
        const dateCheck = validateIncidentDate(String(dateToValidate));
        if (!dateCheck.valid) {
          return res.status(400).json({ message: dateCheck.error });
        }
      }

      const updateData: Record<string, any> = {};
      if (req.body.accidentDate !== undefined) updateData.accidentDate = parseDateAsLocal(req.body.accidentDate);
      if (req.body.incidentDate !== undefined) updateData.incidentDate = parseDateAsLocal(req.body.incidentDate);
      if (req.body.location !== undefined) updateData.location = req.body.location;
      if (req.body.status !== undefined) updateData.status = req.body.status;
      if (req.body.policeReportFiled !== undefined) updateData.policeReportFiled = req.body.policeReportFiled;
      if (req.body.policeReportNumber !== undefined) updateData.policeReportNumber = req.body.policeReportNumber;
      if (req.body.atFault !== undefined) updateData.atFault = req.body.atFault;
      if (req.body.repairCost !== undefined) updateData.repairCost = req.body.repairCost;
      if (req.body.insuranceSubmitted !== undefined) updateData.insuranceSubmitted = req.body.insuranceSubmitted;
      if (req.body.insuranceClaimNumber !== undefined) updateData.insuranceClaimNumber = req.body.insuranceClaimNumber;
      if (req.body.description !== undefined) updateData.description = req.body.description;
      if (req.body.resolutionNotes !== undefined) updateData.resolutionNotes = req.body.resolutionNotes;

      const accident = await storage.updateAccident(req.params.accidentId, updateData);
      if (!accident) {
        return res.status(404).json({ message: "Accident not found" });
      }

      // Log audit events for changes
      const auditLogs: { eventType: string; summary: string; prevValue?: string; newValue?: string }[] = [];
      
      // Track status changes
      if (req.body.status !== undefined && req.body.status !== currentAccident.status) {
        const prevStatus = currentAccident.status || 'unknown';
        const newStatus = req.body.status;
        auditLogs.push({
          eventType: newStatus === 'closed' ? 'CLAIM_CLOSED' : 'STATUS_CHANGED',
          summary: newStatus === 'closed' 
            ? `Claim closed (was: ${prevStatus})` 
            : `Status changed from ${prevStatus} to ${newStatus}`,
          prevValue: prevStatus,
          newValue: newStatus,
        });
      }
      
      // Track notes/description added
      if (req.body.resolutionNotes !== undefined && 
          req.body.resolutionNotes !== currentAccident.resolutionNotes) {
        auditLogs.push({
          eventType: 'NOTES_ADDED',
          summary: 'Resolution notes updated',
        });
      }

      // Write audit logs
      for (const log of auditLogs) {
        await storage.createClaimAuditLog({
          claimId: accident.id,
          userId: userId,
          eventType: log.eventType,
          actionSummary: log.summary,
          previousValue: log.prevValue || null,
          newValue: log.newValue || null,
        });
      }

      res.json(accident);
    } catch (error) {
      console.error("Error updating accident:", error);
      res.status(500).json({ message: "Failed to update accident" });
    }
  });

  // Change driver on a claim with audit log
  app.patch("/api/corporate/accidents/:id/driver", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { driverId } = req.body;
      if (!driverId) return res.status(400).json({ message: "driverId is required" });

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      // Validate the new driver exists — any status is permitted for claim assignment
      const newDriver = await storage.getDriver(driverId);
      if (!newDriver) return res.status(404).json({ message: "Driver not found" });

      // Resolve old driver name for audit log
      let prevDriverName = "Unassigned";
      if (claim.driverId) {
        const prevDriver = await storage.getDriver(claim.driverId);
        if (prevDriver) {
          const prevUser = (prevDriver as any).user || await storage.getUser((prevDriver as any).userId);
          prevDriverName = `${prevUser?.firstName || ''} ${prevUser?.lastName || ''}`.trim() || prevDriverName;
        }
      }

      // Resolve new driver name
      const newUser = (newDriver as any).user || await storage.getUser((newDriver as any).userId);
      const newDriverName = `${newUser?.firstName || ''} ${newUser?.lastName || ''}`.trim() || `Driver ${driverId}`;

      // Update the claim
      const updated = await storage.updateAccident(req.params.id, { driverId });
      if (!updated) return res.status(500).json({ message: "Failed to update claim" });

      // Audit log
      const actorName = `${user?.firstName || ''} ${user?.lastName || ''}`.trim() || user?.email || 'Unknown';
      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: 'DRIVER_CHANGED',
        actionSummary: `Driver changed from ${prevDriverName} to ${newDriverName} by ${actorName}`,
        previousValue: prevDriverName,
        newValue: newDriverName,
        metadata: JSON.stringify({ prevDriverId: claim.driverId, newDriverId: driverId }),
      });

      res.json({ success: true, driverId, driverName: newDriverName });
    } catch (error: any) {
      console.error("Error updating claim driver:", error);
      res.status(500).json({ message: "Failed to update driver on claim" });
    }
  });

