  // Auto-check trigger on claim update (call this after claim updates)
  app.post("/api/claims/:claimId/drug-test/check-trigger", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { claimId } = req.params;
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;

      const [claim] = await db.select().from(accidents).where(eq(accidents.id, claimId)).limit(1);
      if (!claim) {
        return res.status(404).json({ message: "Claim not found" });
      }

      // Check if already required
      if (claim.drugTestRequired) {
        return res.json({ triggered: false, message: "Drug test already required" });
      }

      // Check auto-trigger conditions
      const { trigger, reason } = shouldAutoTriggerDrugTest(claim);
      
      if (trigger) {
        // Auto-trigger the drug test requirement
        const now = new Date();
        const dueBy = new Date(now.getTime() + 24 * 60 * 60 * 1000);

        await db.update(accidents)
          .set({
            drugTestRequired: true,
            drugTestStatus: 'required',
            drugTestRequiredAt: now,
            drugTestDueBy: dueBy,
            drugTestRequiredReason: reason,
            updatedAt: now,
          })
          .where(eq(accidents.id, claimId));

        // Create driver task
        const [newTask] = await db.insert(driverTasks).values({
          driverId: claim.driverId,
          claimId,
          taskType: 'drug_test_required',
          title: 'Post-Accident Drug Test Required',
          description: 'A drug test is required following the incident.',
          instructions: 'Visit an approved testing facility to complete your drug test.',
          status: 'open',
          dueBy,
          createdByUserId: userId,
        }).returning();

        // Create notification
        await db.insert(notificationLogs).values({
          claimId,
          driverId: claim.driverId,
          taskId: newTask.id,
          channel: 'push',
          notificationType: 'drug_test_required',
          title: 'Action Required: Post-Accident Drug Test',
          body: 'A drug test is required following the incident. Open the app for instructions.',
          sentAt: now,
          deliveryStatus: 'sent',
          createdByUserId: userId,
        });

        // Update to notified
        await db.update(accidents)
          .set({
            drugTestStatus: 'notified',
            drugTestLastNotifiedAt: now,
          })
          .where(eq(accidents.id, claimId));

        // Audit logs
        await db.insert(drugTestAuditLogs).values({
          claimId,
          userId,
          actionType: 'REQUIRED_SET',
          previousStatus: 'not_required',
          newStatus: 'required',
          reason,
        });

        await db.insert(drugTestAuditLogs).values({
          claimId,
          userId,
          actionType: 'NOTIFICATION_SENT',
          previousStatus: 'required',
          newStatus: 'notified',
        });

        return res.json({ triggered: true, reason });
      }

      res.json({ triggered: false, message: "No trigger conditions met" });
    } catch (error) {
      console.error("Error checking drug test trigger:", error);
      res.status(500).json({ message: "Failed to check trigger" });
    }
  });

  // Driver App: Get required tasks for current driver
  app.get("/api/driver/tasks", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;

      // Get the driver record for this user
      const [driver] = await db.select()
        .from(drivers)
        .where(eq(drivers.userId, userId))
        .limit(1);

      if (!driver) {
        return res.json({ tasks: [] });
      }

      // Get open tasks for this driver
      const tasks = await db.select()
        .from(driverTasks)
        .where(eq(driverTasks.driverId, driver.id))
        .orderBy(desc(driverTasks.createdAt));

      // Filter to only show open/acknowledged tasks (not completed/cancelled)
      const activeTasks = tasks.filter(t => ['open', 'acknowledged', 'in_progress'].includes(t.status));

      res.json({ tasks: activeTasks });
    } catch (error) {
      console.error("Error fetching driver tasks:", error);
      res.status(500).json({ message: "Failed to fetch tasks" });
    }
  });

  // Driver App: Acknowledge a task
  app.post("/api/driver/tasks/:taskId/acknowledge", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { taskId } = req.params;
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;

      const [task] = await db.select()
        .from(driverTasks)
        .where(eq(driverTasks.id, taskId))
        .limit(1);

      if (!task) {
        return res.status(404).json({ message: "Task not found" });
      }

      const user = await storage.getUser(userId);
      if (user?.role === "driver") {
        const driver = await storage.getDriverByUserId(userId);
        if (!driver || task.driverId !== driver.id) {
          return res.status(403).json({ message: "You can only acknowledge your own tasks" });
        }
      }

      const now = new Date();

      // Update task status
      await db.update(driverTasks)
        .set({
          status: 'acknowledged',
          acknowledgedAt: now,
          updatedAt: now,
        })
        .where(eq(driverTasks.id, taskId));

      // If it's a drug test task, update the claim status too
      if (task.taskType === 'drug_test_required' && task.claimId) {
        const [claim] = await db.select()
          .from(accidents)
          .where(eq(accidents.id, task.claimId))
          .limit(1);

        if (claim) {
          await db.update(accidents)
            .set({
              drugTestStatus: 'acknowledged',
              drugTestAcknowledgedAt: now,
              updatedAt: now,
            })
            .where(eq(accidents.id, task.claimId));

          // Audit log
          await db.insert(drugTestAuditLogs).values({
            claimId: task.claimId,
            userId,
            actionType: 'ACKNOWLEDGED',
            previousStatus: claim.drugTestStatus,
            newStatus: 'acknowledged',
          });
        }
      }

      res.json({ success: true, message: "Task acknowledged" });
    } catch (error) {
      console.error("Error acknowledging task:", error);
      res.status(500).json({ message: "Failed to acknowledge task" });
    }
  });

