  // Invite a new user to the customer account (ADMIN only)
  const inviteUserSchema = z.object({
    email: z.string().email("Valid email is required"),
    role: z.enum(['ACCOUNT_ADMIN', 'ACCOUNT_VIEWER']),
  });

  app.post("/api/customer/users/invite", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      
      // Get the customer user record for the current user
      const customerUser = await storage.getCustomerUserByUserId(userId);
      if (!customerUser) {
        return res.status(403).json({ message: "Not associated with a customer account" });
      }

      // Check if user is an admin
      if (customerUser.role !== 'ACCOUNT_ADMIN') {
        return res.status(403).json({ message: "Only account admins can invite users" });
      }

      // Validate request body
      const validationResult = inviteUserSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({ 
          message: "Invalid request data",
          errors: validationResult.error.flatten().fieldErrors 
        });
      }

      const { email, role } = validationResult.data;

      // Check if user already exists in this account
      const existingUser = await storage.getCustomerUserByEmail(customerUser.customerId, email);
      if (existingUser) {
        return res.status(400).json({ message: "User with this email already exists in your account" });
      }

      // Create the customer user invitation
      const newCustomerUser = await storage.createCustomerUser({
        customerId: customerUser.customerId,
        email,
        role,
        status: 'PENDING',
        invitedBy: userId,
      });

      // Get customer info for the email
      const customer = await storage.getCustomer(customerUser.customerId);

      // Send invitation email
      const { sendCustomerUserInvitation } = await import('./emailService');
      await sendCustomerUserInvitation(email, customer?.customerName || 'Customer Account', newCustomerUser.id);

      res.status(201).json(newCustomerUser);
    } catch (error) {
      console.error("Error inviting customer user:", error);
      res.status(500).json({ message: "Failed to invite user" });
    }
  });

  // Update a customer user's role (ADMIN only)
  const updateRoleSchema = z.object({
    role: z.enum(['ACCOUNT_ADMIN', 'ACCOUNT_VIEWER']),
  });

  app.patch("/api/customer/users/:id/role", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { id } = req.params;
      
      // Get the customer user record for the current user
      const customerUser = await storage.getCustomerUserByUserId(userId);
      if (!customerUser) {
        return res.status(403).json({ message: "Not associated with a customer account" });
      }

      // Check if user is an admin
      if (customerUser.role !== 'ACCOUNT_ADMIN') {
        return res.status(403).json({ message: "Only account admins can update user roles" });
      }

      // Validate request body
      const validationResult = updateRoleSchema.safeParse(req.body);
      if (!validationResult.success) {
        return res.status(400).json({ 
          message: "Invalid request data",
          errors: validationResult.error.flatten().fieldErrors 
        });
      }

      // Get the target user
      const targetUser = await storage.getCustomerUserById(id);
      if (!targetUser) {
        return res.status(404).json({ message: "User not found" });
      }

      // Verify same customer account
      if (targetUser.customerId !== customerUser.customerId) {
        return res.status(403).json({ message: "Cannot modify users from other accounts" });
      }

      // Prevent self-demotion (admin can't remove their own admin role)
      if (targetUser.userId === userId && validationResult.data.role !== 'ACCOUNT_ADMIN') {
        return res.status(400).json({ message: "You cannot remove your own admin privileges" });
      }

      const updated = await storage.updateCustomerUserRole(id, validationResult.data.role);
      res.json(updated);
    } catch (error) {
      console.error("Error updating customer user role:", error);
      res.status(500).json({ message: "Failed to update user role" });
    }
  });

  // Delete a customer user (ADMIN only)
  app.delete("/api/customer/users/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { id } = req.params;
      
      // Get the customer user record for the current user
      const customerUser = await storage.getCustomerUserByUserId(userId);
      if (!customerUser) {
        return res.status(403).json({ message: "Not associated with a customer account" });
      }

      // Check if user is an admin
      if (customerUser.role !== 'ACCOUNT_ADMIN') {
        return res.status(403).json({ message: "Only account admins can remove users" });
      }

      // Get the target user
      const targetUser = await storage.getCustomerUserById(id);
      if (!targetUser) {
        return res.status(404).json({ message: "User not found" });
      }

      // Verify same customer account
      if (targetUser.customerId !== customerUser.customerId) {
        return res.status(403).json({ message: "Cannot remove users from other accounts" });
      }

      // Prevent self-deletion
      if (targetUser.userId === userId) {
        return res.status(400).json({ message: "You cannot remove yourself from the account" });
      }

      // Policy: no hard deletes — deactivate the customer user record
      await storage.deleteCustomerUser(id);

      const { writeSystemAuditEvent } = await import("./services/systemAuditLogService");
      await writeSystemAuditEvent({
        eventType: "customer_user_deactivated",
        actorUserId: userId,
        actorUserEmail: undefined,
        targetEntityType: "customer_user",
        targetEntityId: id,
        targetEntityLabel: `Customer user ${targetUser.userId}`,
        reason: "Removed from account by Account Admin",
        previousValue: { userId: targetUser.userId, customerId: targetUser.customerId },
        ipAddress: req.ip,
      });

      res.status(200).json({ success: true, deactivated: true });
    } catch (error) {
      console.error("Error deactivating customer user:", error);
      res.status(500).json({ message: "Failed to remove user" });
    }
  });

