  // Get attachments for an accident (corporate only)
  app.get("/api/corporate/accidents/:accidentId/attachments", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const attachments = await storage.getAttachmentsByAccidentId(req.params.accidentId);
      // Enrich with uploader display names and chain-of-custody data
      const userCache: Record<string, any> = {};
      const resolveUser = async (id: string | null | undefined) => {
        if (!id) return null;
        if (!userCache[id]) userCache[id] = await storage.getUser(id);
        return userCache[id] ?? null;
      };

      // Compute integrity flags across all active attachments
      const active = attachments.filter(a => !a.isDeleted);
      const normalizedNames = active.map(a => a.fileName.toLowerCase().trim());
      const duplicateIds = new Set<string>();
      for (let i = 0; i < active.length; i++) {
        for (let j = i + 1; j < active.length; j++) {
          if (normalizedNames[i] === normalizedNames[j]) {
            duplicateIds.add(active[i].id);
            duplicateIds.add(active[j].id);
          }
        }
      }

      const enriched = await Promise.all(attachments.map(async (a) => {
        const uploader = await resolveUser(a.uploadedBy);
        const locker   = await resolveUser((a as any).lockedByUserId);
        const uploaderName = uploader
          ? ([uploader.firstName, uploader.lastName].filter(Boolean).join(' ') || uploader.email || 'Unknown')
          : 'Unknown';
        const lockerName = locker
          ? ([locker.firstName, locker.lastName].filter(Boolean).join(' ') || locker.email || 'Unknown')
          : null;
        const integrityFlags: string[] = duplicateIds.has(a.id) ? ['duplicate_filename'] : [];
        return { ...a, uploaderName, lockerName, integrityFlags };
      }));
      res.json(enriched);
    } catch (error) {
      console.error("Error fetching attachments:", error);
      res.status(500).json({ message: "Failed to fetch attachments" });
    }
  });

  // Add attachment to an accident (corporate only)
  app.post("/api/corporate/accidents/:accidentId/attachments", isAuthenticated, async (req: any, res: Response) => {
    const requestId = crypto.randomUUID().substring(0, 8);
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ errorCode: "NOT_AUTHORIZED", message: "You don't have permission to upload attachments for claims.", requestId });
      }

      const accident = await storage.getAccidentById(req.params.accidentId);
      if (!accident) {
        return res.status(404).json({ errorCode: "CLAIM_NOT_FOUND", message: "This claim may have been deleted or you may not have access.", requestId });
      }
      if (accident.claimStatus === "CLOSED" || accident.claimStatus === "DENIED") {
        return res.status(403).json({ errorCode: "NOT_AUTHORIZED", message: "Cannot add attachments to a closed or denied claim.", requestId });
      }

      const allowedTypes = [
        // Images
        "image/jpeg", "image/png", "image/webp", "image/gif",
        "image/heic", "image/heif",
        // Video — ICs use video evidence (mp4, mov, avi, webm, m4v)
        "video/mp4",
        "video/quicktime",     // .mov
        "video/x-msvideo",     // .avi
        "video/avi",
        "video/webm",
        "video/x-m4v",         // .m4v
        "video/3gpp",
        "video/3gpp2",
        // Documents
        "application/pdf",
        "application/msword",
        "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
        "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        "application/vnd.ms-excel",
        "text/csv", "application/csv",
      ];
      if (req.body.fileType && !allowedTypes.includes(req.body.fileType)) {
        return res.status(415).json({ errorCode: "UNSUPPORTED_TYPE", message: "Supported file types: images (JPG, PNG, WEBP), video (MP4, MOV, AVI, WEBM, M4V), PDF, DOCX, XLSX, CSV. Please choose a supported file.", requestId });
      }

      const validCategories = [
        "general", "accident_report", "traffic_citations", "vehicle_towing", "video_photos",
        "carrier_form", "submission_packet", "gl_claim_form", "gl_submission_packet",
        "scene_photos", "vehicle_damage_photos", "driver_photos", "police_report",
        "insurance_claim_form", "customer_documentation", "repair_estimate",
        "invoice_receipt", "video", "other",
        "driver_statement",  // DH-002139: was missing — caused uploads to coerce to "general"
      ];
      const category = validCategories.includes(req.body.category) ? req.body.category : "general";

      // Auto-determine attachment source from user role
      const autoSource = req.body.attachmentSource || (() => {
        if (user?.role === 'driver') return 'driver_app';
        if (user?.role === 'customer') return 'customer';
        return 'internal_user';
      })();

      const attachment = await storage.createAccidentAttachment({
        accidentId: req.params.accidentId,
        fileName: req.body.fileName,
        fileType: req.body.fileType,
        fileSize: req.body.fileSize || null,
        fileUrl: req.body.fileUrl,
        uploadedBy: userId,
        category,
        attachmentSource: autoSource,
        metadata: JSON.stringify({
          driverId: accident.driverId || null,
          customerId: accident.customerId || null,
          attachmentSource: autoSource,
        }),
      });

      await storage.createClaimAuditLog({
        claimId: req.params.accidentId,
        userId: userId,
        eventType: "DOCUMENT_UPLOADED",
        actionSummary: `Document uploaded: ${req.body.fileName} (${category}) — source: ${autoSource}`,
        metadata: JSON.stringify({
          fileName: req.body.fileName,
          fileType: req.body.fileType,
          fileSize: req.body.fileSize,
          category,
          attachmentSource: autoSource,
        }),
      });

      // Create unified document record for reliable retry-based download
      // Skip for data: URIs — stored directly in DB, no object storage key
      const rawFileUrl: string = req.body.fileUrl || "";
      if (!rawFileUrl.startsWith("data:")) try {
        const { createDocumentRecord, getStorageStatus } = await import("./services/documentService");
        const storageKey = rawFileUrl.replace(/^\/objects\//, "").replace(/^\/+/, "");
        const storageInfo = getStorageStatus();
        const unifiedDoc = await createDocumentRecord({
          ownerType: "claim",
          ownerId: req.params.accidentId,
          category: category || "claim_attachment",
          title: req.body.fileName,
          fileName: req.body.fileName,
          contentType: req.body.fileType || "application/octet-stream",
          fileSizeBytes: req.body.fileSize || undefined,
          storageKey,
          storageProvider: storageInfo.provider,
          uploadedByUserId: userId,
        });
        if (unifiedDoc?.id) {
          await storage.updateAccidentAttachment(attachment.id, { attachmentDocumentId: unifiedDoc.id });
          (attachment as any).attachmentDocumentId = unifiedDoc.id;
        }
      } catch (unifiedErr) {
        console.warn("[ClaimAttachment] Non-blocking unified doc creation failed:", (unifiedErr as any)?.message);
      }

      res.json(attachment);
    } catch (error: any) {
      console.error(`[Attachment:${requestId}] Error creating attachment:`, error?.message);
      res.status(500).json({ errorCode: "UNKNOWN_ERROR", message: "Something went wrong while saving the attachment. Please try again.", requestId });
    }
  });

  // Get just the fileUrl for a single attachment (separate endpoint to avoid
  // fetching large base64 data in the bulk accident detail response).
  app.get("/api/corporate/accidents/:accidentId/attachments/:attachmentId/url", isAuthenticated, async (req: any, res: Response) => {
    try {
      const attachment = await storage.getAccidentAttachmentById(req.params.attachmentId);
      if (!attachment || attachment.accidentId !== req.params.accidentId) {
        return res.status(404).json({ message: "Attachment not found" });
      }
      return res.json({ fileUrl: attachment.fileUrl });
    } catch (err) {
      console.error("Error fetching attachment URL:", err);
      return res.status(500).json({ message: "Failed to fetch attachment URL" });
    }
  });

  // Delete attachment from an accident (corporate only)
  app.delete("/api/corporate/accidents/:accidentId/attachments/:attachmentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Only Super Admins can delete attachments
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete documents and attachments' });
      }

      const accident = await storage.getAccidentById(req.params.accidentId);
      if (!accident) {
        return res.status(404).json({ message: "Claim not found" });
      }

      const existingAttachment = await storage.getAccidentAttachmentById(req.params.attachmentId);
      if (!existingAttachment) {
        return res.status(404).json({ message: "Attachment not found" });
      }
      if (existingAttachment.accidentId !== req.params.accidentId) {
        return res.status(403).json({ message: "Attachment does not belong to this claim" });
      }

      // Per-attachment lock check — blocks even Super Admins from deleting without explicitly unlocking first
      if ((existingAttachment as any).isLocked) {
        return res.status(403).json({
          error_code: 'ATTACHMENT_LOCKED',
          message: 'This evidence file is individually locked. Unlock it first before deletion.',
        });
      }

      const { db } = await import('./db');
      const { eq, and } = await import('drizzle-orm');
      const { EVIDENCE_LOCKED_CLAIM_STATUSES, deletionOverrideRequests: overrideTable, accidentAttachments: accAttachTable } = await import('../shared/schema');

      // Evidence lock check — applies when:
      //   1. claim has evidenceLock toggled on, OR
      //   2. claimStatus is in a carrier-reported/litigation state, OR
      //   3. litigation hold is active
      const { getActiveLegalHold } = await import("./legalHoldService");
      const hold = await getActiveLegalHold("case", req.params.accidentId);
      const isStatusLocked = EVIDENCE_LOCKED_CLAIM_STATUSES.includes((accident as any).claimStatus as any);
      const isEvidenceLocked = !!(accident as any).evidenceLock || isStatusLocked || !!(accident as any).litigationHoldActive || !!hold;

      let usedOverrideId: string | null = null;
      if (isEvidenceLocked) {
        // Require a valid (approved, not expired) override for this specific attachment
        const now = new Date();
        const [validOverride] = await db
          .select()
          .from(overrideTable)
          .where(and(
            eq(overrideTable.attachmentId, req.params.attachmentId),
            eq(overrideTable.status, 'approved'),
          ))
          .limit(10);
        const isValid = validOverride && new Date(validOverride.expiresAt) > now;
        if (!isValid) {
          return res.status(403).json({
            error_code: 'EVIDENCE_LOCKED',
            message: 'Evidence Lock active. Deletion requires dual approval. Submit a Deletion Override Request.',
          });
        }
        usedOverrideId = validOverride.id;
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      await db.update(accAttachTable)
        .set({
          isDeleted: true,
          deletedAt: new Date(),
          deletedByUserId: userId,
          deletionReason: String(deletionReason).trim(),
          deletionOverrideId: usedOverrideId,
        })
        .where(eq(accAttachTable.id, req.params.attachmentId));

      // Mark override as consumed (keep status=approved but log that delete occurred)
      if (usedOverrideId) {
        await db.update(overrideTable)
          .set({ status: 'expired' })
          .where(eq(overrideTable.id, usedOverrideId));
      }

      await storage.createClaimAuditLog({
        claimId: req.params.accidentId,
        userId: userId,
        eventType: 'DOCUMENT_DELETED',
        actionSummary: `Document removed by Super Admin: ${existingAttachment.fileName}${usedOverrideId ? ' (via approved deletion override)' : ''}`,
        metadata: JSON.stringify({ attachmentId: req.params.attachmentId, fileName: existingAttachment.fileName, deletionReason: String(deletionReason).trim(), softDelete: true, overrideId: usedOverrideId }),
      });

      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'accident_attachment',
        targetEntityId: req.params.attachmentId,
        targetEntityLabel: existingAttachment.fileName,
        reason: String(deletionReason).trim(),
        metadata: { accidentId: req.params.accidentId, fileName: existingAttachment.fileName, category: existingAttachment.category, evidenceLocked: isEvidenceLocked, overrideId: usedOverrideId, restrictedAction: true },
        ipAddress: req.ip,
      });

      res.json({ success: true });
    } catch (error) {
      console.error('Error deleting attachment:', error);
      res.status(500).json({ message: 'Failed to delete attachment' });
    }
  });

  // ===== Evidence Lock Toggle =====
  app.patch("/api/corporate/accidents/:accidentId/evidence-lock", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can modify the evidence lock' });
      }
      const { enabled, reason } = req.body || {};
      if (enabled && (!reason || String(reason).trim().length < 10)) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A reason of at least 10 characters is required to enable the evidence lock' });
      }
      const { db } = await import('./db');
      const { eq } = await import('drizzle-orm');
      const { accidents: accidentsTable } = await import('../shared/schema');
      await db.update(accidentsTable).set({
        evidenceLock: !!enabled,
        evidenceLockReason: enabled ? String(reason).trim() : null,
        evidenceLockSetByUserId: enabled ? userId : null,
        evidenceLockSetAt: enabled ? new Date() : null,
      }).where(eq(accidentsTable.id, req.params.accidentId));
      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: enabled ? 'evidence_lock.enabled' : 'evidence_lock.disabled',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'accident',
        targetEntityId: req.params.accidentId,
        reason: enabled ? String(reason).trim() : 'Evidence lock disabled',
        metadata: { accidentId: req.params.accidentId },
        ipAddress: req.ip,
      });
      res.json({ success: true, evidenceLock: !!enabled });
    } catch (err) {
      console.error('Evidence lock toggle error:', err);
      res.status(500).json({ message: 'Failed to update evidence lock' });
    }
  });

  // ===== Deletion Override Requests =====
  // GET  — list all overrides for a claim
  app.get("/api/corporate/accidents/:accidentId/deletion-overrides", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: 'Forbidden' });
      const { db } = await import('./db');
      const { eq, desc } = await import('drizzle-orm');
      const { deletionOverrideRequests: overrideTable, users: usersTable, accidentAttachments: attachTable } = await import('../shared/schema');
      const overrides = await db
        .select({
          override: overrideTable,
          requester: { firstName: usersTable.firstName, lastName: usersTable.lastName, email: usersTable.email },
          attachment: { fileName: attachTable.fileName, category: attachTable.category },
        })
        .from(overrideTable)
        .leftJoin(usersTable, eq(overrideTable.requestedByUserId, usersTable.id))
        .leftJoin(attachTable, eq(overrideTable.attachmentId, attachTable.id))
        .where(eq(overrideTable.claimId, req.params.accidentId))
        .orderBy(desc(overrideTable.requestedAt));
      // Mark expired
      const now = new Date();
      const enriched = overrides.map(r => ({
        ...r.override,
        requesterName: `${r.requester?.firstName || ''} ${r.requester?.lastName || ''}`.trim() || r.requester?.email,
        attachmentFileName: r.attachment?.fileName,
        attachmentCategory: r.attachment?.category,
        isExpired: r.override.status === 'approved' && new Date(r.override.expiresAt) < now,
      }));
      res.json({ overrides: enriched });
    } catch (err) {
      console.error('List overrides error:', err);
      res.status(500).json({ message: 'Failed to list deletion override requests' });
    }
  });

  // POST — create override request
  app.post("/api/corporate/accidents/:accidentId/deletion-overrides", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can request deletion overrides' });
      const { attachmentId, requestReason } = req.body || {};
      if (!attachmentId) return res.status(400).json({ message: 'attachmentId is required' });
      if (!requestReason || String(requestReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A reason of at least 10 characters is required' });
      }
      const { db } = await import('./db');
      const { eq, and } = await import('drizzle-orm');
      const { deletionOverrideRequests: overrideTable, accidentAttachments: attachTable } = await import('../shared/schema');
      // Validate attachment belongs to claim
      const [attachment] = await db.select().from(attachTable).where(and(eq(attachTable.id, attachmentId), eq(attachTable.accidentId, req.params.accidentId))).limit(1);
      if (!attachment) return res.status(404).json({ message: 'Attachment not found on this claim' });
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000); // +24h
      const [created] = await db.insert(overrideTable).values({
        claimId: req.params.accidentId,
        attachmentId,
        requestedByUserId: userId,
        requestReason: String(requestReason).trim(),
        expiresAt,
        status: 'pending',
      }).returning();
      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'deletion_override.requested',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'accident_attachment',
        targetEntityId: attachmentId,
        reason: String(requestReason).trim(),
        metadata: { claimId: req.params.accidentId, overrideId: created.id },
        ipAddress: req.ip,
      });
      res.json({ override: created });
    } catch (err) {
      console.error('Create override error:', err);
      res.status(500).json({ message: 'Failed to create deletion override request' });
    }
  });

  // POST — approve override (different super admin only)
  app.post("/api/corporate/accidents/:accidentId/deletion-overrides/:overrideId/approve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can approve deletion overrides' });
      const { approvalNotes } = req.body || {};
      const { db } = await import('./db');
      const { eq } = await import('drizzle-orm');
      const { deletionOverrideRequests: overrideTable } = await import('../shared/schema');
      const [override] = await db.select().from(overrideTable).where(eq(overrideTable.id, req.params.overrideId)).limit(1);
      if (!override) return res.status(404).json({ message: 'Override request not found' });
      if (override.claimId !== req.params.accidentId) return res.status(403).json({ message: 'Override does not belong to this claim' });
      if (override.status !== 'pending') return res.status(409).json({ message: `Cannot approve a request with status: ${override.status}` });
      if (override.requestedByUserId === userId) return res.status(403).json({ error_code: 'SELF_APPROVAL_FORBIDDEN', message: 'You cannot approve your own deletion override request' });
      const [updated] = await db.update(overrideTable).set({
        status: 'approved',
        approvedByUserId: userId,
        approvedAt: new Date(),
        approvalNotes: approvalNotes ? String(approvalNotes).trim() : null,
      }).where(eq(overrideTable.id, req.params.overrideId)).returning();
      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'deletion_override.approved',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'accident_attachment',
        targetEntityId: override.attachmentId,
        reason: approvalNotes || 'Approved',
        metadata: { claimId: req.params.accidentId, overrideId: req.params.overrideId },
        ipAddress: req.ip,
      });
      res.json({ override: updated });
    } catch (err) {
      console.error('Approve override error:', err);
      res.status(500).json({ message: 'Failed to approve deletion override request' });
    }
  });

