  // ── Per-attachment lock / unlock (Super Admin only, Chain of Custody) ───────
  app.patch("/api/corporate/accidents/:accidentId/attachments/:attachmentId/lock", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can lock or unlock individual evidence files' });
      }

      const attachment = await storage.getAccidentAttachmentById(req.params.attachmentId);
      if (!attachment) return res.status(404).json({ message: "Attachment not found" });
      if (attachment.accidentId !== req.params.accidentId) {
        return res.status(403).json({ message: "Attachment does not belong to this claim" });
      }

      const { locked, reason } = req.body;
      if (typeof locked !== 'boolean') {
        return res.status(400).json({ message: "'locked' (boolean) is required" });
      }

      const { db } = await import('./db');
      const { eq } = await import('drizzle-orm');
      const { accidentAttachments: attTable } = await import('../shared/schema');

      const [updated] = await db
        .update(attTable)
        .set({
          isLocked: locked,
          lockedAt: locked ? new Date() : null,
          lockedByUserId: locked ? userId : null,
          lockReason: locked ? (reason || null) : null,
        })
        .where(eq(attTable.id, req.params.attachmentId))
        .returning();

      const eventType = locked ? 'DOCUMENT_LOCKED' : 'DOCUMENT_UNLOCKED';
      const actionSummary = locked
        ? `Evidence file locked: "${attachment.fileName}"${reason ? ` — ${reason}` : ''}`
        : `Evidence file unlocked: "${attachment.fileName}"${reason ? ` — ${reason}` : ''}`;
      await storage.createClaimAuditLog({
        claimId: req.params.accidentId,
        userId,
        eventType,
        actionSummary,
        metadata: JSON.stringify({ attachmentId: req.params.attachmentId, fileName: attachment.fileName, locked, reason }),
      });

      res.json(updated);
    } catch (error) {
      console.error("Error updating attachment lock:", error);
      res.status(500).json({ message: "Failed to update attachment lock" });
    }
  });

  // ============================================
  // CARRIER SUBMISSION PACKET ROUTES
  // ============================================

  const CARRIER_SUBMISSION_TRANSITIONS: Record<string, string[]> = {
    DRAFT: ["SUBMISSION_READY"],
    SUBMISSION_READY: ["PACKET_GENERATED", "DRAFT"],
    PACKET_GENERATED: ["REPORTED", "SUBMISSION_READY"],
    REPORTED: ["ACKNOWLEDGED"],
    ACKNOWLEDGED: ["ADJUSTER_ASSIGNED"],
    ADJUSTER_ASSIGNED: ["CLOSED"],
    CLOSED: [],
  };

  app.patch("/api/corporate/accidents/:id/carrier-submission", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      const forbiddenFields = ['carrierSubmissionStatus', 'id', 'driverId', 'reportedBy', 'createdAt'];
      for (const field of forbiddenFields) {
        delete req.body[field];
      }

      const allowedFields = [
        'lossDate', 'lossTime', 'lossLocation', 'descriptionOfLoss', 'pointOfImpact',
        'weatherConditions', 'roadConditions', 'vehicleYear', 'vehicleMake', 'vehicleModel',
        'vehicleVin', 'vehicleLicensePlate', 'vehicleState', 'claimantName', 'claimantPhone',
        'claimantAddress', 'claimantInsurance', 'claimantPolicyNumber', 'claimantVehicleYear',
        'claimantVehicleMake', 'claimantVehicleModel', 'claimantVehicleVin',
        'policeReportObtained', 'policeReportDepartment', 'policeReportCaseNumber',
        'witnessName', 'witnessPhone', 'witnessStatement', 'injuryDescription',
        'medicalTreatmentSought', 'medicalProvider', 'catastrophicLoss', 'catastrophicAcknowledged',
        'branchName', 'branchNumber', 'policyNumber', 'accountNumber',
        'adjusterName', 'adjusterPhone', 'adjusterEmail',
        'insuredName', 'lossLocationAddress', 'lossLocationCity', 'lossLocationState', 'lossLocationZip',
        'allegedIncidentDescription', 'productInvolved', 'productDescription',
        'injuredParties', 'propertyDamageEntries', 'lawsuitFiled', 'lawsuitCountyState', 'dateOfService',
        'reportFiledByName', 'reportFiledByEmail', 'reportFiledByPhone', 'dateOfReport',
      ];

      const sanitized: Record<string, any> = {};
      for (const key of Object.keys(req.body)) {
        if (allowedFields.includes(key)) {
          sanitized[key] = req.body[key];
        }
      }

      if (Object.keys(sanitized).length === 0) {
        return res.status(400).json({ message: "No valid fields to update" });
      }

      // Convert date strings → Date objects for Drizzle's timestamp() columns.
      // The client sends YYYY-MM-DD strings (HTML date input). Passing a bare
      // string to a timestamp() column causes Drizzle to call .toISOString() on
      // it and throw "value.toISOString is not a function" → 500.
      const dateFields = ['lossDate', 'dateOfService', 'dateOfReport'];
      for (const field of dateFields) {
        if (sanitized[field]) {
          const d = new Date(sanitized[field]);
          if (isNaN(d.getTime())) {
            return res.status(400).json({ message: `${field} is not a valid date` });
          }
          if (d > new Date()) {
            return res.status(400).json({ message: `${field} cannot be a future date` });
          }
          sanitized[field] = d; // give Drizzle a proper Date object
        }
      }

      const updated = await storage.updateAccident(req.params.id, sanitized);

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: "CARRIER_SUBMISSION_UPDATED",
        actionSummary: `Carrier submission fields updated`,
        metadata: JSON.stringify({ updatedFields: Object.keys(req.body) }),
      });

      res.json(updated);
    } catch (error: any) {
      console.error("Error updating carrier submission:", error);
      res.status(500).json({ message: "Failed to update carrier submission" });
    }
  });

  app.post("/api/corporate/accidents/:id/carrier-submission/transition", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      const { toStatus, note } = req.body;
      if (!toStatus) return res.status(400).json({ message: "toStatus is required" });

      const currentStatus = claim.carrierSubmissionStatus || "DRAFT";
      const allowed = CARRIER_SUBMISSION_TRANSITIONS[currentStatus] || [];
      if (!allowed.includes(toStatus)) {
        return res.status(400).json({
          message: `Invalid transition from ${currentStatus} to ${toStatus}. Allowed: ${allowed.join(', ') || 'none'}`,
        });
      }

      const updateData: any = { carrierSubmissionStatus: toStatus };
      if (toStatus === "CLOSED") {
        updateData.carrierSubmissionClosedAt = new Date();
        updateData.carrierSubmissionClosedReason = note || "Closed";
      }

      await storage.updateAccident(req.params.id, updateData);

      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown';
      const [event] = await db.insert(carrierSubmissionEvents).values({
        claimId: req.params.id,
        fromStatus: currentStatus,
        toStatus,
        action: `transition_${currentStatus}_to_${toStatus}`.toLowerCase(),
        changedByUserId: userId,
        changedByName: userName,
        note: note || null,
        metadata: null,
      }).returning();

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: "CARRIER_SUBMISSION_TRANSITION",
        actionSummary: `Carrier submission transitioned from ${currentStatus} to ${toStatus}`,
        metadata: JSON.stringify({ fromStatus: currentStatus, toStatus, note }),
      });

      res.json({ event, newStatus: toStatus });
    } catch (error: any) {
      console.error("Error transitioning carrier submission:", error);
      res.status(500).json({ message: "Failed to transition carrier submission" });
    }
  });

  app.get("/api/corporate/accidents/:id/carrier-submission/events", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const events = await db.select()
        .from(carrierSubmissionEvents)
        .where(eq(carrierSubmissionEvents.claimId, req.params.id))
        .orderBy(desc(carrierSubmissionEvents.createdAt));

      res.json(events);
    } catch (error: any) {
      console.error("Error fetching carrier submission events:", error);
      res.status(500).json({ message: "Failed to fetch carrier submission events" });
    }
  });

  // ── Claim Activity Timeline ─────────────────────────────────────────────────
  app.get("/api/corporate/accidents/:accidentId/timeline", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const { accidentId } = req.params;

      const events: Array<{ id: string; eventType: string; label: string; detail?: string | null; userName: string; createdAt: string; targetId?: string | null; targetSection?: string | null }> = [];

      // 1. Primary audit log (CLAIM_CREATED, STATUS_CHANGED, NOTES_ADDED, DOCUMENT_UPLOADED, etc.)
      const audits = await db
        .select({
          id: claimAuditLogs.id,
          eventType: claimAuditLogs.eventType,
          actionSummary: claimAuditLogs.actionSummary,
          metadata: claimAuditLogs.metadata,
          createdAt: claimAuditLogs.createdAt,
          userFirstName: users.firstName,
          userLastName: users.lastName,
          userEmail: users.email,
        })
        .from(claimAuditLogs)
        .leftJoin(users, eq(claimAuditLogs.userId, users.id))
        .where(eq(claimAuditLogs.claimId, accidentId));

      for (const a of audits) {
        const userName = [a.userFirstName, a.userLastName].filter(Boolean).join(" ") || a.userEmail || "Unknown";
        const t = (a.eventType || "").toLowerCase();

        // Parse metadata for deep-link targeting
        let targetId: string | null = null;
        let targetSection: string | null = null;
        try {
          const meta = a.metadata ? (typeof a.metadata === "string" ? JSON.parse(a.metadata) : a.metadata) as Record<string, unknown> : null;
          if (meta?.noteId) {
            targetId = String(meta.noteId);
            targetSection = "notes";
          }
        } catch { /* ignore parse errors */ }

        // Section mapping from event type
        if (!targetSection) {
          if (t.includes("note") || t === "notes_added") targetSection = "notes";
          else if (t.includes("status") || t.includes("created") || t.includes("closed") || t.includes("transition")) targetSection = "review";
          else if (t.includes("upload") || t.includes("attachment") || t.includes("document") || t.includes("evidence") || t.includes("photo")) targetSection = "attachments";
          else if (t.includes("repair") || t.includes("estimate")) targetSection = "repair";
          else if (t.includes("carrier") || t.includes("submission") || t.includes("packet") || t.includes("form") || t.includes("generated")) targetSection = "carrier";
          else if (t.includes("hold") || t.includes("legal")) targetSection = "legal";
          else if (t.includes("drug")) targetSection = "drug_test";
        }

        events.push({
          id: `audit-${a.id}`,
          eventType: a.eventType,
          label: a.actionSummary,
          detail: null,
          userName,
          createdAt: a.createdAt?.toISOString() ?? new Date().toISOString(),
          targetId,
          targetSection,
        });
      }

      // 2. Claim status transition events
      const statusEvts = await db
        .select()
        .from(claimEvents)
        .where(eq(claimEvents.claimId, accidentId));

      for (const e of statusEvts) {
        const toLabel = (e.toStatus || "").replace(/_/g, " ").replace(/w/g, c => c.toUpperCase());
        events.push({
          id: `status-${e.id}`,
          eventType: "STATUS_CHANGED",
          label: `Status changed to ${toLabel}`,
          detail: e.note || null,
          userName: e.changedByName || "Unknown",
          createdAt: e.createdAt?.toISOString() ?? new Date().toISOString(),
          targetId: null,
          targetSection: "review",
        });
      }

      // 3. Carrier submission events
      const carrierEvts = await db
        .select()
        .from(carrierSubmissionEvents)
        .where(eq(carrierSubmissionEvents.claimId, accidentId));

      for (const e of carrierEvts) {
        const actionLabel = (e.action || "").replace(/_/g, " ").replace(/w/g, c => c.toUpperCase());
        events.push({
          id: `carrier-${e.id}`,
          eventType: e.action?.toUpperCase() ?? "CARRIER_EVENT",
          label: actionLabel,
          detail: e.note || null,
          userName: e.changedByName || "Unknown",
          createdAt: e.createdAt?.toISOString() ?? new Date().toISOString(),
          targetId: null,
          targetSection: "carrier",
        });
      }

      // 4. Attachment uploads (and removals)
      const uploaderAlias = users;
      const attachments = await db
        .select({
          id: accidentAttachments.id,
          fileName: accidentAttachments.fileName,
          fileType: accidentAttachments.fileType,
          category: accidentAttachments.category,
          isDeleted: accidentAttachments.isDeleted,
          createdAt: accidentAttachments.createdAt,
          deletedAt: accidentAttachments.deletedAt,
          uploaderFirstName: uploaderAlias.firstName,
          uploaderLastName: uploaderAlias.lastName,
          uploaderEmail: uploaderAlias.email,
        })
        .from(accidentAttachments)
        .leftJoin(uploaderAlias, eq(accidentAttachments.uploadedBy, uploaderAlias.id))
        .where(eq(accidentAttachments.accidentId, accidentId));

      for (const att of attachments) {
        const uploaderName = [att.uploaderFirstName, att.uploaderLastName].filter(Boolean).join(" ") || att.uploaderEmail || "Unknown";
        const isPhoto = (att.fileType || "").startsWith("image/");
        const catLabel = (att.category || "general").replace(/_/g, " ").replace(/w/g, c => c.toUpperCase());

        if (!att.isDeleted) {
          events.push({
            id: `att-upload-${att.id}`,
            eventType: "ATTACHMENT_UPLOADED",
            label: isPhoto ? "Photo Uploaded" : "Document Uploaded",
            detail: `${att.fileName} (${catLabel})`,
            userName: uploaderName,
            createdAt: att.createdAt?.toISOString() ?? new Date().toISOString(),
            targetId: att.id,
            targetSection: "attachments",
          });
        } else if (att.deletedAt) {
          events.push({
            id: `att-upload-${att.id}`,
            eventType: "ATTACHMENT_UPLOADED",
            label: isPhoto ? "Photo Uploaded" : "Document Uploaded",
            detail: `${att.fileName} (${catLabel})`,
            userName: uploaderName,
            createdAt: att.createdAt?.toISOString() ?? new Date().toISOString(),
            targetId: att.id,
            targetSection: "attachments",
          });
          events.push({
            id: `att-removed-${att.id}`,
            eventType: "ATTACHMENT_REMOVED",
            label: isPhoto ? "Photo Removed" : "Document Removed",
            detail: att.fileName,
            userName: uploaderName,
            createdAt: att.deletedAt.toISOString(),
            targetId: att.id,
            targetSection: "attachments",
          });
        }
      }

      // 5. Litigation hold audit logs
      const holdAudits = await db
        .select({
          id: litigationHoldAuditLogs.id,
          actionType: litigationHoldAuditLogs.actionType,
          reason: litigationHoldAuditLogs.reason,
          createdAt: litigationHoldAuditLogs.createdAt,
          userFirstName: users.firstName,
          userLastName: users.lastName,
          userEmail: users.email,
        })
        .from(litigationHoldAuditLogs)
        .leftJoin(users, eq(litigationHoldAuditLogs.userId, users.id))
        .where(eq(litigationHoldAuditLogs.claimId, accidentId));

      const holdActionLabels: Record<string, string> = {
        HOLD_ACTIVATED: "Litigation Hold Activated",
        HOLD_RELEASED: "Litigation Hold Released",
        EVIDENCE_ACCESS_BLOCKED: "Evidence Access Blocked",
        EDIT_BLOCKED: "Field Edit Blocked (Litigation Hold)",
        ATTORNEY_LETTER_RECEIVED: "Attorney Letter Received",
      };

      for (const h of holdAudits) {
        const userName = [h.userFirstName, h.userLastName].filter(Boolean).join(" ") || h.userEmail || "Unknown";
        const label = holdActionLabels[h.actionType] || (h.actionType || "").replace(/_/g, " ").replace(/w/g, c => c.toUpperCase());
        events.push({
          id: `hold-${h.id}`,
          eventType: h.actionType,
          label,
          detail: h.reason || null,
          userName,
          createdAt: h.createdAt?.toISOString() ?? new Date().toISOString(),
          targetId: null,
          targetSection: "legal",
        });
      }

      // Sort descending (newest first)
      events.sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());

      res.json(events);
    } catch (error: any) {
      console.error("Error fetching claim timeline:", error);
      res.status(500).json({ message: "Failed to fetch claim timeline" });
    }
  });

  // ── Transportation Auto Loss Report generation ─────────────────────────────
  app.post("/api/corporate/accidents/:id/auto-loss-report/generate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      const claimType = claim.claimType || 'auto';
      const isGL = claimType === 'general_liability' || claimType === 'INJURY' || claimType === 'PROPERTY';
      if (isGL) {
        return res.status(400).json({ message: "Transportation Auto Loss Report is for auto claims only" });
      }

      let driver: any = null;
      if (claim.driverId) {
        driver = await storage.getDriver(claim.driverId);
      }
      let account: any = null;
      if (claim.customerId) {
        account = await storage.getCustomer(claim.customerId);
      }

      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown';
      const { generateAutoLossReportPdf, saveAutoLossReportToAll } = await import("./services/carrierSubmissionPdfService");

      const pdfBuffer = await generateAutoLossReportPdf(claim, driver, account, userName);
      const fileName = `Auto_Loss_Report_${claim.id.substring(0, 8).toUpperCase()}_${Date.now()}.pdf`;

      const result = await saveAutoLossReportToAll(pdfBuffer, claim, driver, account, fileName, userId, userName);

      await db.insert(carrierSubmissionEvents).values({
        claimId: req.params.id,
        fromStatus: claim.carrierSubmissionStatus || 'DRAFT',
        toStatus: claim.carrierSubmissionStatus || 'DRAFT',
        action: 'generate_auto_loss_report',
        changedByUserId: userId,
        changedByName: userName,
        note: `Generated Transportation Auto Loss Report PDF`,
        metadata: JSON.stringify({ fileName, attachmentId: result.attachmentId }),
      });

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: "AUTO_LOSS_REPORT_GENERATED",
        actionSummary: `Generated Transportation Auto Loss Report: ${fileName}`,
        metadata: JSON.stringify({ fileName, attachmentId: result.attachmentId }),
      });

      res.json({ fileName, attachmentId: result.attachmentId, objectPath: result.objectPath });
    } catch (error: any) {
      console.error("Error generating auto loss report:", error);
      res.status(500).json({ message: "Failed to generate auto loss report" });
    }
  });

