  app.patch("/api/corporate/accidents/:id/carrier-submission/waive-police-report", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      const waived: boolean = req.body.waived === true;
      const reason = typeof req.body.reason === 'string' ? req.body.reason.trim() : '';
      if (waived && reason.length === 0) {
        return res.status(400).json({
          error_code: "REASON_REQUIRED",
          message: "A reason is required when No Police Involvement is enabled",
        });
      }
      if (reason.length > 1000) {
        return res.status(400).json({ message: "Reason must be 1,000 characters or fewer" });
      }

      const { isClaimEditable } = await import('./helpers/claimStateMachine');
      const currentStatus = claim.claimStatus || 'DRAFT';
      if (!isClaimEditable(currentStatus)) {
        return res.status(403).json({
          message: `Claim cannot be edited in ${currentStatus} status`,
        });
      }

      const previousValue = !!claim.policeReportWaived;
      if (previousValue === waived) {
        return res.json({
          success: true,
          policeReportWaived: waived,
          policeReportWaivedReason: claim.policeReportWaivedReason || null,
        });
      }

      const actorName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown User';
      const changedAt = new Date();
      const [updated] = await db.transaction(async (tx) => {
        const [updatedClaim] = await tx
          .update(accidents)
          .set({
            policeReportWaived: waived,
            policeReportWaivedReason: waived ? reason : null,
            policeReportWaivedByUserId: waived ? userId : null,
            policeReportWaivedAt: waived ? changedAt : null,
            updatedAt: changedAt,
            updatedBy: userId,
          })
          .where(eq(accidents.id, req.params.id))
          .returning();

        await tx.insert(claimAuditLogs).values({
          claimId: req.params.id,
          userId,
          eventType: "POLICE_INVOLVEMENT_CHANGED",
          actionSummary: `No Police Involvement ${waived ? 'enabled' : 'disabled'} by ${actorName}`,
          previousValue: String(previousValue),
          newValue: String(waived),
          metadata: JSON.stringify({
            reason: waived ? reason : null,
            previousReason: claim.policeReportWaivedReason || null,
          }),
        });

        return [updatedClaim];
      });

      const { syncClaimWorkflowStage } = await import('./helpers/claimReadiness');
      const { claim: syncedClaim, readiness } = await syncClaimWorkflowStage(updated);

      res.json({
        success: true,
        policeReportWaived: waived,
        policeReportWaivedReason: syncedClaim.policeReportWaivedReason || null,
        readiness,
        claimStatus: syncedClaim.claimStatus,
      });
    } catch (error: any) {
      console.error("Error updating No Police Involvement:", error);
      res.status(500).json({ message: "Failed to update No Police Involvement" });
    }
  });

  app.post("/api/corporate/accidents/:id/carrier-submission/mark-reported", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ message: "Claim not found" });

      const currentStatus = claim.carrierSubmissionStatus || 'DRAFT';
      if (currentStatus !== 'PACKET_GENERATED' && currentStatus !== 'SUBMISSION_READY') {
        return res.status(400).json({ message: `Cannot mark as reported from status ${currentStatus}. Must be PACKET_GENERATED or SUBMISSION_READY.` });
      }

      const { carrierReportedTo, carrierReportedMethod, carrierReportedNotes, glAcknowledged } = req.body;

      const isGL = claim.claimType === 'general_liability';
      if (isGL && !claim.glReportingAcknowledged && !glAcknowledged) {
        return res.status(400).json({ message: "GL claims require acknowledgment of claimant contact restriction before marking as reported." });
      }

      const updateFields: any = {
        carrierSubmissionStatus: 'REPORTED',
        carrierReportedAt: new Date(),
        carrierReportedByUserId: userId,
        carrierReportedTo: carrierReportedTo || null,
        carrierReportedMethod: carrierReportedMethod || null,
        carrierReportedNotes: carrierReportedNotes || null,
      };

      if (isGL && glAcknowledged && !claim.glReportingAcknowledged) {
        updateFields.glReportingAcknowledged = true;
        updateFields.glReportingAcknowledgedBy = userId;
        updateFields.glReportingAcknowledgedAt = new Date();
      }

      await storage.updateAccident(req.params.id, updateFields);

      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown';

      if (isGL && glAcknowledged) {
        await db.insert(carrierSubmissionEvents).values({
          claimId: req.params.id,
          fromStatus: currentStatus,
          toStatus: currentStatus,
          action: 'gl_reporting_acknowledged',
          changedByUserId: userId,
          changedByName: userName,
          note: 'User acknowledged GL claimant contact restriction before reporting',
          metadata: JSON.stringify({ acknowledgedAt: new Date().toISOString() }),
        });

        await storage.createClaimAuditLog({
          claimId: req.params.id,
          userId,
          eventType: "GL_REPORTING_ACKNOWLEDGED",
          actionSummary: "Acknowledged GL claimant contact restriction",
          metadata: JSON.stringify({ acknowledgedBy: userName }),
        });
      }

      await db.insert(carrierSubmissionEvents).values({
        claimId: req.params.id,
        fromStatus: currentStatus,
        toStatus: 'REPORTED',
        action: 'mark_reported',
        changedByUserId: userId,
        changedByName: userName,
        note: carrierReportedNotes || `Reported to ${carrierReportedTo || 'carrier'} via ${carrierReportedMethod || 'unknown'}`,
        metadata: JSON.stringify({ carrierReportedTo, carrierReportedMethod }),
      });

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: "CARRIER_MARKED_REPORTED",
        actionSummary: `Claim marked as reported to carrier`,
        metadata: JSON.stringify({ carrierReportedTo, carrierReportedMethod, carrierReportedNotes }),
      });

      res.json({ newStatus: 'REPORTED', carrierReportedAt: new Date().toISOString() });
    } catch (error: any) {
      console.error("Error marking as reported:", error);
      res.status(500).json({ message: "Failed to mark as reported" });
    }
  });

  // ============================================================
  // SUBMIT TO CARRIER — Email push with PDF attachments (v1)
  // ============================================================
  app.post('/api/corporate/accidents/:id/carrier-submission/submit-to-carrier', isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ error_code: 'FORBIDDEN', message: 'Corporate access required' });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ error_code: 'NOT_FOUND', message: 'Claim not found' });

      const allowedStatuses = ['SUBMISSION_READY', 'PACKET_GENERATED'];
      if (!allowedStatuses.includes(claim.carrierSubmissionStatus || 'DRAFT')) {
        return res.status(400).json({
          error_code: 'INVALID_STATUS',
          message: `Cannot submit from status ${claim.carrierSubmissionStatus || 'DRAFT'}. Complete required fields and set to Submission Ready first.`
        });
      }

      const { submissionNotes, recipients: recipientsOverride, cc: ccOverride } = req.body;

      const isGL = claim.claimType === 'general_liability' || claim.claimType === 'INJURY' || claim.claimType === 'PROPERTY';

      // Default carrier contacts from Claim Reporting Kit
      const defaultRecipients = ['crumandforsternol@cfins.com'];
      const recipients: string[] = recipientsOverride?.length ? recipientsOverride : defaultRecipients;
      const cc: string[] = ccOverride || [];

      // Gather PDF attachments — most recent submission packet for this claim
      const existingAttachments = await storage.getAttachmentsByAccidentId(req.params.id);
      const packetCategory = isGL ? 'gl_submission_packet' : 'submission_packet';
      const formCategory = isGL ? 'gl_claim_form' : 'carrier_form';

      const packetAttachments = existingAttachments
        .filter((a: any) => a.category === packetCategory || a.category === formCategory)
        .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
        .slice(0, 2);

      const { ObjectStorageService } = await import('./objectStorage');
      const storageService = new ObjectStorageService();

      const emailAttachments: Array<{ filename: string; content: Buffer; contentType: string }> = [];
      const artifactManifest: Array<{ type: string; fileName: string; fileUrl: string; fileSizeBytes: number | null; createdAt: string }> = [];

      for (const att of packetAttachments) {
        try {
          const objectPath = att.fileUrl.startsWith('/objects/') ? att.fileUrl : '/objects/' + att.fileUrl;
          let buf: Buffer | null = null;
          try {
            const gcsFile = await storageService.getObjectEntityFile(objectPath);
            const [downloaded] = await gcsFile.download();
            buf = downloaded;
          } catch (_e) { buf = null; }
          if (buf) {
            emailAttachments.push({ filename: att.fileName, content: buf, contentType: 'application/pdf' });
            artifactManifest.push({ type: att.category, fileName: att.fileName, fileUrl: att.fileUrl, fileSizeBytes: att.fileSize || null, createdAt: att.createdAt?.toISOString?.() || new Date().toISOString() });
          }
        } catch (attErr) {
          console.warn('[CarrierSubmission] Could not load attachment:', att.fileName, attErr);
        }
      }

      // Resolve account name
      let accountName = 'Unknown Account';
      if (claim.customerId) {
        const acct = await storage.getCustomer(claim.customerId);
        if (acct) accountName = acct.customerName;
      }

      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown';
      const lossDateFormatted = claim.lossDate
        ? new Date(claim.lossDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
        : claim.accidentDate
          ? new Date(claim.accidentDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
          : 'Unknown Date';

      const { sendCarrierSubmissionEmail } = await import('./emailService');
      const emailResult = await sendCarrierSubmissionEmail({
        claimId: req.params.id,
        claimType: isGL ? 'general_liability' : 'auto',
        dateOfLoss: lossDateFormatted,
        accountName,
        submittedByName: userName,
        submissionNotes: submissionNotes || undefined,
        recipients,
        cc,
        attachments: emailAttachments,
      });

      const now = new Date();

      if (!emailResult.success) {
        // Store failure on claim but do NOT advance status
        await storage.updateAccident(req.params.id, {
          carrierSubmissionFailureReason: emailResult.error || 'Unknown email delivery error',
          updatedAt: now,
        });
        await storage.createClaimAuditLog({
          claimId: req.params.id,
          userId,
          eventType: 'CARRIER_SUBMISSION_FAILED',
          actionSummary: `Carrier email submission failed: ${emailResult.error}`,
          metadata: JSON.stringify({ error: emailResult.error, recipients }),
        });
        return res.status(502).json({
          error_code: 'EMAIL_DELIVERY_FAILED',
          message: emailResult.error || 'Email delivery failed',
          hint: emailResult.error?.includes('not configured') ? 'Contact your administrator to configure the RESEND_API_KEY environment variable.' : undefined,
        });
      }

      // Success — advance to REPORTED and store submission record
      await storage.updateAccident(req.params.id, {
        carrierSubmissionStatus: 'REPORTED',
        carrierSubmissionEmailedAt: now,
        carrierSubmissionEmailedBy: userId,
        carrierSubmissionRecipients: recipients,
        carrierSubmissionCc: cc.length > 0 ? cc : null,
        carrierSubmissionNotes: submissionNotes || null,
        carrierSubmissionArtifacts: artifactManifest.length > 0 ? artifactManifest : null,
        carrierSubmissionFailureReason: null,
        carrierSubmissionMessageId: emailResult.messageId || null,
        carrierReportedAt: now,
        carrierReportedByUserId: userId,
        carrierReportedMethod: 'email',
        updatedAt: now,
      });

      await db.insert(carrierSubmissionEvents).values({
        claimId: req.params.id,
        fromStatus: claim.carrierSubmissionStatus || 'DRAFT',
        toStatus: 'REPORTED',
        action: 'submit_to_carrier',
        changedByUserId: userId,
        changedByName: userName,
        note: `Submitted to carrier via email. Recipients: ${recipients.join(', ')}. Attachments: ${artifactManifest.length}.`,
        metadata: JSON.stringify({ recipients, cc, attachments: artifactManifest, messageId: emailResult.messageId }),
      });

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: 'CARRIER_SUBMISSION_SENT',
        actionSummary: `Submitted to carrier via email by ${userName}`,
        metadata: JSON.stringify({ recipients, cc, attachments: artifactManifest.length, messageId: emailResult.messageId }),
      });

      res.json({
        success: true,
        newStatus: 'REPORTED',
        emailedAt: now.toISOString(),
        emailedBy: userName,
        recipients,
        cc,
        messageId: emailResult.messageId,
        artifacts: artifactManifest,
      });
    } catch (error: any) {
      console.error('[CarrierSubmission] Error submitting to carrier:', error);
      res.status(500).json({ error_code: 'INTERNAL_ERROR', message: 'Failed to submit to carrier. ' + (error.message || '') });
    }
  });

  // RESEND SUBMISSION — Admin only
  app.post('/api/corporate/accidents/:id/carrier-submission/resend', isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!['super_user', 'admin'].includes(user?.role || '')) {
        return res.status(403).json({ error_code: 'FORBIDDEN', message: 'Admin role required to resend submissions' });
      }

      const claim = await storage.getAccidentById(req.params.id);
      if (!claim) return res.status(404).json({ error_code: 'NOT_FOUND', message: 'Claim not found' });

      if (!['REPORTED', 'ACKNOWLEDGED', 'ADJUSTER_ASSIGNED', 'CLOSED'].includes(claim.carrierSubmissionStatus || '')) {
        return res.status(400).json({ error_code: 'INVALID_STATUS', message: 'Can only resend after a successful initial submission.' });
      }

      const { submissionNotes, recipients: recipientsOverride, cc: ccOverride } = req.body;
      const isGL = claim.claimType === 'general_liability' || claim.claimType === 'INJURY' || claim.claimType === 'PROPERTY';

      const storedRecipients = Array.isArray(claim.carrierSubmissionRecipients) ? claim.carrierSubmissionRecipients as string[] : ['crumandforsternol@cfins.com'];
      const recipients: string[] = recipientsOverride?.length ? recipientsOverride : storedRecipients;
      const cc: string[] = ccOverride || (Array.isArray(claim.carrierSubmissionCc) ? claim.carrierSubmissionCc as string[] : []);

      const existingAttachments = await storage.getAttachmentsByAccidentId(req.params.id);
      const packetCategory = isGL ? 'gl_submission_packet' : 'submission_packet';
      const formCategory = isGL ? 'gl_claim_form' : 'carrier_form';
      const packetAttachments = existingAttachments
        .filter((a: any) => a.category === packetCategory || a.category === formCategory)
        .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime())
        .slice(0, 2);

      const { ObjectStorageService } = await import('./objectStorage');
      const storageService = new ObjectStorageService();
      const emailAttachments: Array<{ filename: string; content: Buffer; contentType: string }> = [];
      const artifactManifest: Array<{ type: string; fileName: string; fileUrl: string; fileSizeBytes: number | null; createdAt: string }> = [];

      for (const att of packetAttachments) {
        try {
          const objectPath = att.fileUrl.startsWith('/objects/') ? att.fileUrl : '/objects/' + att.fileUrl;
          let buf: Buffer | null = null;
          try {
            const gcsFile = await storageService.getObjectEntityFile(objectPath);
            const [downloaded] = await gcsFile.download();
            buf = downloaded;
          } catch (_e) { buf = null; }
          if (buf) {
            emailAttachments.push({ filename: att.fileName, content: buf, contentType: 'application/pdf' });
            artifactManifest.push({ type: att.category, fileName: att.fileName, fileUrl: att.fileUrl, fileSizeBytes: att.fileSize || null, createdAt: att.createdAt?.toISOString?.() || new Date().toISOString() });
          }
        } catch (e) { console.warn('[CarrierSubmission][Resend] Attachment load failed:', att.fileName); }
      }

      let accountName = 'Unknown Account';
      if (claim.customerId) {
        const acct = await storage.getCustomer(claim.customerId);
        if (acct) accountName = acct.customerName;
      }

      const userName = [user?.firstName, user?.lastName].filter(Boolean).join(' ') || user?.email || 'Unknown';
      const lossDateFormatted = claim.lossDate
        ? new Date(claim.lossDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
        : claim.accidentDate
          ? new Date(claim.accidentDate).toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
          : 'Unknown Date';

      const { sendCarrierSubmissionEmail } = await import('./emailService');
      const emailResult = await sendCarrierSubmissionEmail({
        claimId: req.params.id,
        claimType: isGL ? 'general_liability' : 'auto',
        dateOfLoss: lossDateFormatted,
        accountName,
        submittedByName: userName,
        submissionNotes: submissionNotes ? `[RESEND] ${submissionNotes}` : '[RESEND of prior submission]',
        recipients,
        cc,
        attachments: emailAttachments,
      });

      const now = new Date();

      if (!emailResult.success) {
        await storage.createClaimAuditLog({
          claimId: req.params.id,
          userId,
          eventType: 'CARRIER_SUBMISSION_RESEND_FAILED',
          actionSummary: `Resend failed: ${emailResult.error}`,
          metadata: JSON.stringify({ error: emailResult.error }),
        });
        return res.status(502).json({ error_code: 'EMAIL_DELIVERY_FAILED', message: emailResult.error || 'Resend failed' });
      }

      await storage.updateAccident(req.params.id, {
        carrierSubmissionEmailedAt: now,
        carrierSubmissionEmailedBy: userId,
        carrierSubmissionRecipients: recipients,
        carrierSubmissionNotes: submissionNotes || (claim.carrierSubmissionNotes as any),
        carrierSubmissionMessageId: emailResult.messageId || null,
        carrierSubmissionFailureReason: null,
        updatedAt: now,
      });

      await db.insert(carrierSubmissionEvents).values({
        claimId: req.params.id,
        fromStatus: claim.carrierSubmissionStatus || 'REPORTED',
        toStatus: claim.carrierSubmissionStatus || 'REPORTED',
        action: 'resend_submission',
        changedByUserId: userId,
        changedByName: userName,
        note: `Resent submission to carrier. Recipients: ${recipients.join(', ')}.`,
        metadata: JSON.stringify({ recipients, cc, attachments: artifactManifest, messageId: emailResult.messageId }),
      });

      await storage.createClaimAuditLog({
        claimId: req.params.id,
        userId,
        eventType: 'CARRIER_SUBMISSION_RESENT',
        actionSummary: `Submission resent to carrier by ${userName}`,
        metadata: JSON.stringify({ recipients, messageId: emailResult.messageId }),
      });

      res.json({ success: true, emailedAt: now.toISOString(), recipients, messageId: emailResult.messageId });
    } catch (error: any) {
      console.error('[CarrierSubmission] Resend error:', error);
      res.status(500).json({ error_code: 'INTERNAL_ERROR', message: 'Resend failed. ' + (error.message || '') });
    }
  });

