  // Required photo categories
  const PICKUP_REQUIRED_PHOTOS = ["angle_front_left", "angle_front_right", "angle_rear_left", "angle_rear_right", "vin"];
  const DROPOFF_REQUIRED_PHOTOS = ["angle_front_left", "angle_front_right", "angle_rear_left", "angle_rear_right", "surroundings"];

  // Simple blur detection using image variance (higher = blurrier)
  function calculateBlurScore(imageBuffer: Buffer): number {
    // Simple variance-based blur detection
    // In production, use a proper image processing library like sharp
    // For now, return a random-ish score based on buffer size/patterns
    const bytes = imageBuffer.subarray(0, Math.min(1000, imageBuffer.length));
    let sum = 0;
    let sumSq = 0;
    for (let i = 0; i < bytes.length; i++) {
      sum += bytes[i];
      sumSq += bytes[i] * bytes[i];
    }
    const mean = sum / bytes.length;
    const variance = (sumSq / bytes.length) - (mean * mean);
    // Normalize to 0-100 scale (lower variance = blurrier)
    // Images with variance < 1000 are considered blurry
    const normalizedScore = Math.min(100, Math.max(0, 100 - (variance / 50)));
    return Math.round(normalizedScore * 100) / 100;
  }

  // Quality scoring (0-100, higher = better)
  function calculateQualityScore(imageBuffer: Buffer, contentType: string): { score: number; passed: boolean; issues: string[] } {
    const issues: string[] = [];
    let score = 100;

    // Check file size (minimum 50KB for reasonable quality)
    const MIN_SIZE = 50 * 1024;
    const MAX_SIZE = 20 * 1024 * 1024;
    if (imageBuffer.length < MIN_SIZE) {
      score -= 30;
      issues.push("Image too small - may be low resolution");
    }
    if (imageBuffer.length > MAX_SIZE) {
      score -= 10;
      issues.push("Image very large - may take time to load");
    }

    // Check content type
    const validTypes = ["image/jpeg", "image/png", "image/webp"];
    if (!validTypes.includes(contentType)) {
      score -= 20;
      issues.push("Unsupported image format");
    }

    // Apply blur penalty
    const blurScore = calculateBlurScore(imageBuffer);
    if (blurScore > 50) {
      score -= Math.min(40, blurScore - 50);
      issues.push("Image appears blurry");
    }

    // Quality passes if score >= 60
    const passed = score >= 60;
    return { score: Math.max(0, score), passed, issues };
  }

