  app.get("/api/moves/:moveId/photo-compliance", isAuthenticated, async (req: any, res: Response) => {
    try {
      const moveId = req.params.moveId;
      const trip = await storage.getTrip(moveId);
      
      if (!trip) {
        return res.status(404).json({ message: "Move not found" });
      }

      const photos = await storage.getMoveMediaByMoveId(moveId);
      const overrides = await storage.getPhotoGateOverridesByMoveId(moveId);

      // Calculate missing photos for each stage
      const pickupPhotos = photos.filter(p => p.stage === "pickup" && p.qualityPassed);
      const pickupCategories = new Set(pickupPhotos.map(p => p.category));
      const pickupMissing = PICKUP_REQUIRED_PHOTOS.filter(cat => !pickupCategories.has(cat));

      const dropoffPhotos = photos.filter(p => p.stage === "dropoff" && p.qualityPassed);
      const dropoffCategories = new Set(dropoffPhotos.map(p => p.category));
      const dropoffMissing = DROPOFF_REQUIRED_PHOTOS.filter(cat => !dropoffCategories.has(cat));

      res.json({
        moveId,
        pickup: {
          status: trip.pickupPhotoComplianceStatus || "not_started",
          required: PICKUP_REQUIRED_PHOTOS,
          captured: Array.from(pickupCategories),
          missing: pickupMissing,
          photos: pickupPhotos.map(p => ({ id: p.id, category: p.category, fileUrl: p.fileUrl, qualityScore: p.qualityScore })),
          overridden: overrides.some(o => o.stage === "pickup"),
        },
        dropoff: {
          status: trip.dropoffPhotoComplianceStatus || "not_started",
          required: DROPOFF_REQUIRED_PHOTOS,
          captured: Array.from(dropoffCategories),
          missing: dropoffMissing,
          photos: dropoffPhotos.map(p => ({ id: p.id, category: p.category, fileUrl: p.fileUrl, qualityScore: p.qualityScore })),
          overridden: overrides.some(o => o.stage === "dropoff"),
        },
        overrides,
      });
    } catch (error) {
      console.error("Error fetching compliance status:", error);
      res.status(500).json({ message: "Failed to fetch compliance status" });
    }
  });

  // Upload a photo for a move
  app.post("/api/moves/:moveId/photos", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const moveId = req.params.moveId;
      const { stage, category, imageData, contentType, forceAccept } = req.body;

      // Validate required fields
      if (!stage || !category || !imageData || !contentType) {
        return res.status(400).json({ message: "Missing required fields: stage, category, imageData, contentType" });
      }

      // Validate stage
      if (!["pickup", "dropoff", "claim"].includes(stage)) {
        return res.status(400).json({ message: "Invalid stage. Must be 'pickup', 'dropoff', or 'claim'" });
      }

      // Validate category
      const validCategories = ["angle_front_left", "angle_front_right", "angle_rear_left", "angle_rear_right", "vin", "surroundings", "other"];
      if (!validCategories.includes(category)) {
        return res.status(400).json({ message: `Invalid category. Must be one of: ${validCategories.join(", ")}` });
      }

      // Verify move exists
      const trip = await storage.getTrip(moveId);
      if (!trip) {
        return res.status(404).json({ message: "Move not found" });
      }

      // Decode base64 image
      const imageBuffer = Buffer.from(imageData, "base64");
      
      // Calculate quality score
      const quality = calculateQualityScore(imageBuffer, contentType);
      const blurScore = calculateBlurScore(imageBuffer);

      // If quality failed and not forcing accept, return warning
      if (!quality.passed && !forceAccept) {
        return res.status(422).json({
          message: "Photo quality check failed",
          qualityScore: quality.score,
          blurScore,
          issues: quality.issues,
          requiresConfirmation: true,
        });
      }

      // Upload to object storage
      const objectStorageService = new ObjectStorageService();
      const { objectPath } = await objectStorageService.uploadFile(imageBuffer, contentType, `${moveId}_${stage}_${category}.jpg`);

      // Create move media record
      const mediaRecord = await storage.createMoveMedia({
        moveId,
        stage,
        category,
        fileUrl: objectPath,
        storageKey: objectPath,
        capturedByUserId: userId,
        capturedAt: new Date(),
        blurScore: blurScore.toString(),
        qualityScore: quality.score.toString(),
        qualityPassed: quality.passed || forceAccept,
        qualityOverridden: !quality.passed && forceAccept,
        metadata: {
          width: null,
          height: null,
          fileSize: imageBuffer.length,
          mimeType: contentType,
        },
      });

      res.status(201).json({
        ...mediaRecord,
        qualityIssues: quality.issues,
      });
    } catch (error) {
      console.error("Error uploading photo:", error);
      res.status(500).json({ message: "Failed to upload photo" });
    }
  });

