  app.delete("/api/moves/:moveId/photos/:photoId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete move photos' });
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      const { moveMedia: moveMediaTable } = await import('../shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');
      const [photo] = await db.select().from(moveMediaTable).where(eq(moveMediaTable.id, req.params.photoId)).limit(1);
      if (!photo || photo.isDeleted) {
        return res.status(404).json({ message: 'Photo not found' });
      }

      await db.update(moveMediaTable)
        .set({ isDeleted: true, deletedAt: new Date(), deletedByUserId: userId, deletionReason: String(deletionReason).trim() })
        .where(eq(moveMediaTable.id, req.params.photoId));

      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'move_photo',
        targetEntityId: req.params.photoId,
        targetEntityLabel: photo.category,
        reason: String(deletionReason).trim(),
        metadata: { moveId: req.params.moveId, stage: photo.stage, category: photo.category, restrictedAction: true },
        ipAddress: req.ip,
      });

      res.json({ success: true });
    } catch (error) {
      console.error('Error deleting photo:', error);
      res.status(500).json({ message: 'Failed to delete photo' });
    }
  });

