  app.get("/api/moves/:moveId/can-transition", isAuthenticated, async (req: any, res: Response) => {
    try {
      const moveId = req.params.moveId;
      const targetState = req.query.targetState as string;

      const trip = await storage.getTrip(moveId);
      if (!trip) {
        return res.status(404).json({ message: "Move not found" });
      }

      const overrides = await storage.getPhotoGateOverridesByMoveId(moveId);
      const hasPickupOverride = overrides.some(o => o.stage === "pickup");
      const hasDropoffOverride = overrides.some(o => o.stage === "dropoff");

      // States that require pickup photos
      const REQUIRES_PICKUP = ["EN_ROUTE_PICKUP", "AT_PICKUP", "EN_ROUTE_DESTINATION", "AT_DESTINATION", "COMPLETED"];
      // States that require dropoff photos
      const REQUIRES_DROPOFF = ["COMPLETED"];

      const pickupComplete = trip.pickupPhotoComplianceStatus === "complete" || hasPickupOverride;
      const dropoffComplete = trip.dropoffPhotoComplianceStatus === "complete" || hasDropoffOverride;

      const requiresPickup = REQUIRES_PICKUP.includes(targetState);
      const requiresDropoff = REQUIRES_DROPOFF.includes(targetState);

      const canTransition = (!requiresPickup || pickupComplete) && (!requiresDropoff || dropoffComplete);

      const blockers: string[] = [];
      if (requiresPickup && !pickupComplete) {
        blockers.push("Pickup photos required");
      }
      if (requiresDropoff && !dropoffComplete) {
        blockers.push("Dropoff photos required");
      }

      res.json({
        canTransition,
        blockers,
        pickupStatus: trip.pickupPhotoComplianceStatus,
        dropoffStatus: trip.dropoffPhotoComplianceStatus,
        hasPickupOverride,
        hasDropoffOverride,
      });
    } catch (error) {
      console.error("Error checking transition:", error);
      res.status(500).json({ message: "Failed to check transition" });
    }
  });

  // EXPENSE ROUTES

  // Expense Summary endpoint with average age and date range filtering
  app.get("/api/corporate/expenses/summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Get all expenses
      const allExpenses = await storage.getAllExpenses();
      const now = new Date();
      
      // Date range helpers
      const getStartOfMonth = () => new Date(now.getFullYear(), now.getMonth(), 1);
      const getStartOfQuarter = () => {
        const quarter = Math.floor(now.getMonth() / 3);
        return new Date(now.getFullYear(), quarter * 3, 1);
      };
      const getStartOfYear = () => new Date(now.getFullYear(), 0, 1);

      // Calculate average age in days
      const calculateAverageAge = (expenses: any[]) => {
        if (expenses.length === 0) return 0;
        const totalDays = expenses.reduce((sum, e) => {
          const createdDate = e.createdAt ? new Date(e.createdAt) : new Date(e.expenseDate);
          const ageMs = now.getTime() - createdDate.getTime();
          return sum + (ageMs / (1000 * 60 * 60 * 24));
        }, 0);
        return Math.round((totalDays / expenses.length) * 10) / 10; // Round to 1 decimal
      };

      // Filter by date range
      const filterByDateRange = (expenses: any[], startDate: Date) => {
        return expenses.filter(e => {
          const expenseDate = e.approvalDate ? new Date(e.approvalDate) : 
                             e.reimbursementDate ? new Date(e.reimbursementDate) :
                             new Date(e.createdAt || e.expenseDate);
          return expenseDate >= startDate;
        });
      };

      // Not-Submitted (drafts) - all time
      const drafts = allExpenses.filter(e => e.status === 'draft');
      const draftTotal = drafts.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);
      const draftAvgAge = calculateAverageAge(drafts);

      // Pending Approval - expenses with approval stage other than Not-Submitted, Fully Approved, or Reimbursed
      const pending = allExpenses.filter(e => {
        // Exclude drafts (Not-Submitted)
        if (e.status === 'draft') return false;
        // Exclude Fully Approved (status approved or stage completed)
        if (e.status === 'approved' || e.currentApprovalStage === 'completed') return false;
        // Exclude Reimbursed
        if (e.status === 'reimbursed') return false;
        // Include if has an approval stage (manager, coo, executive, etc.)
        return e.currentApprovalStage && e.currentApprovalStage !== 'completed';
      });
      const pendingTotal = pending.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);
      const pendingAvgAge = calculateAverageAge(pending);

      // Approved - with date range options (status === 'approved' OR currentApprovalStage === 'completed')
      const approved = allExpenses.filter(e => e.status === 'approved' || e.currentApprovalStage === 'completed');
      const approvedMTD = filterByDateRange(approved, getStartOfMonth());
      const approvedQTD = filterByDateRange(approved, getStartOfQuarter());
      const approvedYTD = filterByDateRange(approved, getStartOfYear());

      // Reimbursed - with date range options
      const reimbursed = allExpenses.filter(e => e.status === 'reimbursed');
      const reimbursedMTD = filterByDateRange(reimbursed, getStartOfMonth());
      const reimbursedQTD = filterByDateRange(reimbursed, getStartOfQuarter());
      const reimbursedYTD = filterByDateRange(reimbursed, getStartOfYear());

      // Calculate category breakdown for expenses
      const getCategoryBreakdown = (expenses: any[]) => {
        const categoryMap = new Map<string, number>();
        expenses.forEach(e => {
          const category = e.category || 'other';
          const amount = parseFloat(e.amount || '0');
          categoryMap.set(category, (categoryMap.get(category) || 0) + amount);
        });
        return Array.from(categoryMap.entries()).map(([category, amount]) => ({
          category,
          amount: Math.round(amount * 100) / 100,
        })).sort((a, b) => b.amount - a.amount);
      };

      res.json({
        draft: {
          count: drafts.length,
          total: draftTotal,
          avgAgeDays: draftAvgAge,
          expenses: drafts.map(e => e.id),
        },
        pending: {
          count: pending.length,
          total: pendingTotal,
          avgAgeDays: pendingAvgAge,
          expenses: pending.map(e => e.id),
        },
        approved: {
          all: { count: approved.length, total: approved.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: approved.map(e => e.id), byCategory: getCategoryBreakdown(approved) },
          mtd: { count: approvedMTD.length, total: approvedMTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: approvedMTD.map(e => e.id), byCategory: getCategoryBreakdown(approvedMTD) },
          qtd: { count: approvedQTD.length, total: approvedQTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: approvedQTD.map(e => e.id), byCategory: getCategoryBreakdown(approvedQTD) },
          ytd: { count: approvedYTD.length, total: approvedYTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: approvedYTD.map(e => e.id), byCategory: getCategoryBreakdown(approvedYTD) },
        },
        reimbursed: {
          all: { count: reimbursed.length, total: reimbursed.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: reimbursed.map(e => e.id), byCategory: getCategoryBreakdown(reimbursed) },
          mtd: { count: reimbursedMTD.length, total: reimbursedMTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: reimbursedMTD.map(e => e.id), byCategory: getCategoryBreakdown(reimbursedMTD) },
          qtd: { count: reimbursedQTD.length, total: reimbursedQTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: reimbursedQTD.map(e => e.id), byCategory: getCategoryBreakdown(reimbursedQTD) },
          ytd: { count: reimbursedYTD.length, total: reimbursedYTD.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0), expenses: reimbursedYTD.map(e => e.id), byCategory: getCategoryBreakdown(reimbursedYTD) },
        },
      });
    } catch (error) {
      console.error("Error fetching expense summary:", error);
      res.status(500).json({ message: "Failed to fetch expense summary" });
    }
  });

