  // CORPORATE EXPENSE ROUTES

  // Get all expenses (corporate only) with enriched data
  app.get("/api/corporate/expenses", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const expenses = await storage.getAllExpenses();
      
      // Enrich expenses with submitter name and customer name
      const enrichedExpenses = await Promise.all(expenses.map(async (expense) => {
        let submitterName = "Unknown";
        let customerName = "";
        let driverClassification = "";
        let submissionDate = expense.createdAt;
        
        // Get submitter name
        if (expense.submittedBy) {
          const submitter = await storage.getUser(expense.submittedBy);
          if (submitter) {
            submitterName = `${submitter.firstName || ''} ${submitter.lastName || ''}`.trim() || submitter.email || "Unknown";
          }
        }
        
        // Get customer name from trip if available
        if (expense.tripId) {
          const trip = await storage.getTrip(expense.tripId);
          if (trip && trip.customerId) {
            const customer = await storage.getCustomer(trip.customerId);
            if (customer) {
              customerName = customer.customerName || "";
            }
          }
        }
        
        // Get driver classification if driver expense
        if (expense.driverId) {
          const driver = await storage.getDriver(expense.driverId);
          if (driver) {
            driverClassification = driver.driverClassification || "";
          }
        }
        
        return {
          ...expense,
          submitterName,
          customerName,
          driverClassification,
          submissionDate,
        };
      }));
      
      res.json(enrichedExpenses);
    } catch (error) {
      console.error("Error fetching expenses:", error);
      res.status(500).json({ message: "Failed to fetch expenses" });
    }
  });

