  // Approve an expense at the current approval stage
  app.post("/api/corporate/expenses/:id/approve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { notes } = req.body;
      const expenseId = req.params.id;

      // Get the expense and current approval record
      const expense = await storage.getExpense(expenseId);
      if (!expense) {
        return res.status(404).json({ message: "Expense not found" });
      }

      if (expense.status !== 'pending') {
        return res.status(400).json({ message: "Expense is not pending approval" });
      }

      // Find the pending approval for current stage that this user can approve
      const approvals = await storage.getExpenseApprovalsByExpenseId(expenseId);
      const pendingApproval = approvals.find(a => 
        a.status === 'pending' && 
        a.stage === expense.currentApprovalStage &&
        a.approverUserId === userId
      );

      if (!pendingApproval) {
        return res.status(403).json({ message: "You are not authorized to approve this expense at the current stage" });
      }

      // Approve this stage
      const approval = await storage.approveExpense(expenseId, pendingApproval.id, userId, notes);
      
      // Advance to next stage
      const updatedExpense = await storage.advanceExpenseToNextStage(expenseId);

      // If the expense completed, and it's a driver expense, we'd create an invoice
      // For now, just return success
      res.json({ 
        message: "Expense approved successfully",
        approval,
        expense: updatedExpense
      });
    } catch (error) {
      console.error("Error approving expense:", error);
      res.status(500).json({ message: "Failed to approve expense" });
    }
  });

