  // Initialize approval workflow for an expense (called when expense is created)
  app.post("/api/corporate/expenses/:id/init-workflow", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const expenseId = req.params.id;
      const expense = await storage.getExpense(expenseId);
      
      if (!expense) {
        return res.status(404).json({ message: "Expense not found" });
      }

      // Get COO employee
      const coo = await storage.getCOOEmployee();
      
      // Build approval chain based on expense type and submitter type
      const approvals: any[] = [];

      if (expense.expenseType === 'driver' && expense.driverId) {
        // Driver expense - need driver info to determine classification
        const driver = await storage.getDriver(expense.driverId);
        
        if (driver?.driverClassification === 'Employee' && driver.directManagerId) {
          // Employee driver: Manager → COO → Invoice
          const manager = await storage.getEmployee(driver.directManagerId);
          if (manager) {
            approvals.push({
              expenseId,
              stage: 'manager',
              level: 1,
              approverEmployeeId: manager.id,
              approverUserId: manager.userId,
              status: 'pending',
            });
          }
        } else if (driver?.driverClassification === 'Independent Contractor' && driver.driverAdvocateId) {
          // Independent Contractor: Driver Advocate → COO → Invoice
          const advocate = await storage.getEmployee(driver.driverAdvocateId);
          if (advocate) {
            approvals.push({
              expenseId,
              stage: 'manager',
              level: 1,
              approverEmployeeId: advocate.id,
              approverUserId: advocate.userId,
              status: 'pending',
            });
          }
        }
        
        // COO approval (level 2) for all driver expenses
        if (coo) {
          approvals.push({
            expenseId,
            stage: 'coo',
            level: 2,
            approverEmployeeId: coo.id,
            approverUserId: coo.userId,
            status: 'pending',
          });
        }

      } else if (expense.expenseType === 'employee' && expense.employeeId) {
        // Employee expense: Manager → COO → Will Walton → Reimbursement
        const employee = await storage.getEmployee(expense.employeeId);
        
        if (employee?.directManagerId) {
          const manager = await storage.getEmployee(employee.directManagerId);
          if (manager) {
            approvals.push({
              expenseId,
              stage: 'manager',
              level: 1,
              approverEmployeeId: manager.id,
              approverUserId: manager.userId,
              status: 'pending',
            });
          }
        }
        
        // COO approval (level 2)
        if (coo) {
          approvals.push({
            expenseId,
            stage: 'coo',
            level: 2,
            approverEmployeeId: coo.id,
            approverUserId: coo.userId,
            status: 'pending',
          });
        }

        // Will Walton approval (level 3) for employee expenses
        const willWalton = await storage.getWillWaltonEmployee();
        if (willWalton) {
          approvals.push({
            expenseId,
            stage: 'executive',
            level: 3,
            approverEmployeeId: willWalton.id,
            approverUserId: willWalton.userId,
            status: 'pending',
          });
        }
      }

      // Create all approval records
      const createdApprovals = [];
      for (const approvalData of approvals) {
        const created = await storage.createExpenseApproval(approvalData);
        createdApprovals.push(created);
      }

      res.json({
        message: "Approval workflow initialized",
        approvals: createdApprovals,
      });
    } catch (error) {
      console.error("Error initializing approval workflow:", error);
      res.status(500).json({ message: "Failed to initialize approval workflow" });
    }
  });

