      const COMP_PERF_FIELDS_EMP = ['annualSalary','hourlyRate','bonusEligible','annualBonusPercentageTarget','lastPerformanceReviewDate','lastPerformanceReviewRating','lastMeritIncrease','lastMeritIncreaseAmount'];
      const finalEmployee: any = { ...maskedEmployee };
