  // Get account metrics for dashboard (corporate only)
  app.get("/api/corporate/customers/metrics", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const customers = await storage.getAllCustomers();
      const now = new Date();
      const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      const ninetyDaysFromNow = new Date(now.getTime() + 90 * 24 * 60 * 60 * 1000);

      // Calculate metrics
      const activeAccounts = customers.filter(c => c.status?.toLowerCase() === "active");
      const atRiskAccounts = customers.filter(c => 
        c.potentialRisk && c.potentialRisk.toLowerCase() !== "none" && c.potentialRisk !== ""
      );
      const pastDueAccounts = customers.filter(c => 
        c.arStatus && (c.arStatus.toLowerCase().includes("past due") || c.arStatus.toLowerCase().includes("overdue"))
      );
      const noActivityAccounts = customers.filter(c => {
        if (!c.lastInvoiceDate) return c.status?.toLowerCase() === "active"; // Active but never invoiced
        const lastActivity = new Date(c.lastInvoiceDate);
        return lastActivity < thirtyDaysAgo && c.status?.toLowerCase() === "active";
      });
      const contractsExpiringAccounts = customers.filter(c => {
        if (!c.cancellationDate) return false;
        const cancelDate = new Date(c.cancellationDate);
        return cancelDate > now && cancelDate <= ninetyDaysFromNow;
      });

      res.json({
        activeAccounts: { count: activeAccounts.length, ids: activeAccounts.map(c => c.id) },
        atRiskAccounts: { count: atRiskAccounts.length, ids: atRiskAccounts.map(c => c.id) },
        pastDueAccounts: { count: pastDueAccounts.length, ids: pastDueAccounts.map(c => c.id) },
        noActivityAccounts: { count: noActivityAccounts.length, ids: noActivityAccounts.map(c => c.id) },
        contractsExpiringAccounts: { count: contractsExpiringAccounts.length, ids: contractsExpiringAccounts.map(c => c.id) },
      });
    } catch (error) {
      console.error("Error fetching customer metrics:", error);
      res.status(500).json({ message: "Failed to fetch customer metrics" });
    }
  });

