  // GET /api/corporate/customers/export — server-side XLSX download
  // Queries dealer_id DIRECTLY from the database so the Dealer ID column is always accurate.
  // Must be registered BEFORE the /:id route so "export" is not captured as an id.
  app.get("/api/corporate/customers/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const userEmail = req.user.claims.email;
      let user = await storage.getUser(userId);
      if (!user && userEmail) user = await storage.getUserByEmail(userEmail);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const exportType = (req.query.exportType as string) || "active";
      const { db } = await import("./db");
      const { customers: customersTable } = await import("@shared/schema");
      const { eq, and, asc, sql: drizzleSql } = await import("drizzle-orm");

      const baseWhere = and(
        eq(customersTable.isDeleted, false),
        eq(customersTable.isArchived, false),
      );
      const whereClause = exportType === "active"
        ? and(baseWhere, drizzleSql`lower(coalesce(${customersTable.status}, '')) = 'active'`)
        : baseWhere;

      // Explicit column selection — dealerId maps DIRECTLY to the dealer_id DB column.
      const rows = await db
        .select({
          customerNumber:       customersTable.customerNumber,
          dealerId:             customersTable.dealerId,        // ← DB column: dealer_id
          customerName:         customersTable.customerName,
          parentAccountId:      customersTable.parentAccountId,
          customerType:         customersTable.customerType,
          program:              customersTable.program,
          status:               customersTable.status,
          primaryContactName:   customersTable.primaryContactName,
          primaryContactEmail:  customersTable.primaryContactEmail,
          primaryContactNumber: customersTable.primaryContactNumber,
          primaryContactCell:   customersTable.primaryContactCell,
          customerCity:         customersTable.customerCity,
          customerState:        customersTable.customerState,
          implementationDate:   customersTable.implementationDate,
          network:              customersTable.network,
          health:               customersTable.health,
          createdAt:            customersTable.createdAt,
          updatedAt:            customersTable.updatedAt,
        })
        .from(customersTable)
        .where(whereClause)
        .orderBy(asc(drizzleSql`lower(coalesce(${customersTable.customerName}, ''))`));

      // Parent account name lookup
      const allParents = await db
        .select({ id: customersTable.id, customerName: customersTable.customerName })
        .from(customersTable)
        .where(and(eq(customersTable.isDeleted, false), eq(customersTable.isArchived, false)));
      const parentMap = new Map(allParents.map(c => [c.id, c.customerName || ""]));

      const fmt = (val: string | null | undefined): string => {
        if (!val) return "";
        const d = val.replace(/\D/g, "");
        if (d.length === 10) return `(${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}`;
        if (d.length === 11 && d[0] === "1") return `+1 (${d.slice(1,4)}) ${d.slice(4,7)}-${d.slice(7)}`;
        return val;
      };

      const sheetRows = rows.map(c => ({
        "Account Number":        c.customerNumber            ?? "",
        "Dealer ID":             c.dealerId                  ?? "",  // ← directly from dealer_id
        "Account Name":          c.customerName              ?? "",
        "Parent Account":        (c.parentAccountId ? parentMap.get(c.parentAccountId) ?? "" : ""),
        "Industry":              c.customerType              ?? "",
        "Segment":               c.program                   ?? "",
        "Status":                c.status                    ?? "",
        "Primary Contact Name":  c.primaryContactName        ?? "",
        "Primary Contact Email": c.primaryContactEmail       ?? "",
        "Primary Contact Phone": fmt(c.primaryContactNumber ?? c.primaryContactCell),
        "City":                  c.customerCity              ?? "",
        "State":                 c.customerState             ?? "",
        "Go Live Date":          c.implementationDate        ?? "",
        "Network":               c.network                   ?? "",
        "Health Status":         c.health                    ?? "",
        "Created Date":          c.createdAt ? new Date(c.createdAt as any).toLocaleDateString("en-US") : "",
        "Last Updated Date":     c.updatedAt ? new Date(c.updatedAt as any).toLocaleDateString("en-US") : "",
      }));

      const ws = XLSX.utils.json_to_sheet(sheetRows);
      if (sheetRows.length > 0) {
        const headerKeys = Object.keys(sheetRows[0]);
        ws["!cols"] = headerKeys.map(h => ({
          wch: Math.min(
            Math.max(h.length, ...sheetRows.map(r => String((r as any)[h] ?? "").length)) + 2,
            60,
          ),
        }));
        const range = XLSX.utils.decode_range(ws["!ref"] ?? "A1");
        for (let C = range.s.c; C <= range.e.c; C++) {
          const addr = XLSX.utils.encode_cell({ r: 0, c: C });
          if (ws[addr]) ws[addr].s = { font: { bold: true } };
        }
      }

      const wb = XLSX.utils.book_new();
      XLSX.utils.book_append_sheet(wb, ws, exportType === "active" ? "Active Accounts" : "All Accounts");

      const today = new Date().toISOString().slice(0, 10);
      const prefix = exportType === "active" ? "Accounts_Active" : "Accounts_All";
      const buffer = XLSX.write(wb, { type: "buffer", bookType: "xlsx" });

      res.setHeader("Content-Type", "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet");
      res.setHeader("Content-Disposition", `attachment; filename="${prefix}_${today}.xlsx"`);
      res.send(buffer);
    } catch (e: any) {
      console.error("[customers/export]", e);
      res.status(500).json({ message: "Export failed" });
    }
  });

