  // Create customer (corporate only)
  app.post("/api/corporate/customers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const result = createAccountSchema.safeParse(req.body);
      if (!result.success) {
        const fieldErrors: Record<string, string> = {};
        for (const issue of result.error.issues) {
          const fieldName = issue.path.join(".");
          if (fieldName && !fieldErrors[fieldName]) {
            fieldErrors[fieldName] = issue.message;
          }
        }
        return res.status(422).json({ message: "Validation error", fieldErrors });
      }

      const validatedData = result.data;
      
      if (!validatedData.customerLatitude || !validatedData.customerLongitude) {
        const geoResult = await geocodeCustomerAddress(validatedData);
        if (geoResult.customerLatitude && geoResult.customerLongitude) {
          validatedData.customerLatitude = geoResult.customerLatitude;
          validatedData.customerLongitude = geoResult.customerLongitude;
        }
      }
      
      const customer = await storage.createCustomer(validatedData);

      // Auto-generate "Account created" activity event
      await storage.createAccountActivityEvent({
        accountId: customer.id,
        category: 'system',
        eventType: 'account_created',
        summary: 'Account created',
        createdByUserId: userId,
        metadata: null,
      });

      // Calculate initial health
      await storage.calculateAccountHealth(customer.id);

      res.json(customer);
    } catch (error: any) {
      if (error instanceof z.ZodError) {
        const fieldErrors: Record<string, string> = {};
        for (const issue of error.issues) {
          const fieldName = issue.path.join(".");
          if (fieldName && !fieldErrors[fieldName]) {
            fieldErrors[fieldName] = issue.message;
          }
        }
        return res.status(422).json({ message: "Validation error", fieldErrors });
      }
      console.error("Error creating customer:", error);
      // Surface DB-level constraint details in development for easier debugging
      const detail = error?.cause?.message || error?.message || "Failed to create customer";
      res.status(500).json({ message: detail });
    }
  });

  // Update customer (corporate only)
  app.patch("/api/corporate/customers/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const validatedData = updateCustomerSchema.parse(req.body);
      
      const hasAddressChange = validatedData.customerAddress !== undefined || 
                                validatedData.customerCity !== undefined || 
                                validatedData.customerState !== undefined || 
                                validatedData.customerZip !== undefined;
      
      if (hasAddressChange && !validatedData.customerLatitude && !validatedData.customerLongitude) {
        const existingCustomer = await storage.getCustomer(req.params.id);
        if (existingCustomer) {
          const addressData = {
            customerAddress: validatedData.customerAddress ?? existingCustomer.customerAddress,
            customerCity: validatedData.customerCity ?? existingCustomer.customerCity,
            customerState: validatedData.customerState ?? existingCustomer.customerState,
            customerZip: validatedData.customerZip ?? existingCustomer.customerZip,
          };
          const geoResult = await geocodeCustomerAddress(addressData);
          if (geoResult.customerLatitude && geoResult.customerLongitude) {
            validatedData.customerLatitude = geoResult.customerLatitude;
            validatedData.customerLongitude = geoResult.customerLongitude;
          } else {
            validatedData.customerLatitude = null;
            validatedData.customerLongitude = null;
            console.log(`[Customer Update] Geocoding failed for customer ${req.params.id}, clearing stale coordinates`);
          }
        }
      }
      
      // Get existing customer for comparison
      const existingCustomer = await storage.getCustomer(req.params.id);
      if (!existingCustomer) {
        return res.status(404).json({ message: "Customer not found" });
      }

      const customer = await storage.updateCustomer(req.params.id, validatedData);

      if (!customer) {
        return res.status(404).json({ message: "Customer not found" });
      }

      // Auto-generate activity events for tracked changes
      const activityPromises: Promise<any>[] = [];

      // Status changed
      if (validatedData.status !== undefined && validatedData.status !== existingCustomer.status) {
        activityPromises.push(storage.createAccountActivityEvent({
          accountId: req.params.id,
          category: 'status',
          eventType: 'status_changed',
          summary: `Status changed to ${validatedData.status}`,
          createdByUserId: userId,
          metadata: JSON.stringify({ 
            previousValue: existingCustomer.status, 
            newValue: validatedData.status 
          }),
        }));
      }

      // Owner changed
      if (validatedData.accountOwnerId !== undefined && validatedData.accountOwnerId !== existingCustomer.accountOwnerId) {
        let ownerName = validatedData.accountOwnerId;
        if (validatedData.accountOwnerId) {
          const owner = await storage.getUser(validatedData.accountOwnerId);
          if (owner) {
            ownerName = `${owner.firstName || ''} ${owner.lastName || ''}`.trim() || owner.email;
          }
        }
        activityPromises.push(storage.createAccountActivityEvent({
          accountId: req.params.id,
          category: 'status',
          eventType: 'owner_changed',
          summary: validatedData.accountOwnerId ? `Owner assigned to ${ownerName}` : 'Owner removed',
          createdByUserId: userId,
          metadata: JSON.stringify({ 
            previousValue: existingCustomer.accountOwnerId, 
            newValue: validatedData.accountOwnerId 
          }),
        }));
      }

      // Next Required Touch changed - recalculate health
      if (validatedData.nextRequiredTouchDate !== undefined && 
          validatedData.nextRequiredTouchDate !== existingCustomer.nextRequiredTouchDate) {
        activityPromises.push(storage.calculateAccountHealth(req.params.id));
      }

      await Promise.all(activityPromises);

      // Dispatch account.updated webhook for all org subscribers
      if (user?.orgId) {
        dispatchWebhook(user.orgId, 'account.updated', {
          account_id: req.params.id,
          account_name: (customer as any)?.customerName,
          changed_fields: Object.keys(validatedData),
          updated_by: userId,
        }).catch(() => {});
      }

      res.json(customer);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error updating customer:", error);
      res.status(500).json({ message: "Failed to update customer" });
    }
  });

