  // PUT /api/corporate/accounts/:accountId/dealership-profile
  app.put("/api/corporate/accounts/:accountId/dealership-profile", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { accountId } = req.params;

      const account = await storage.getCustomer(accountId);
      if (!account) {
        return res.status(404).json({ message: "Account not found" });
      }

      const { franchiseBrand, dealerCode, storeNumber, rooftopGroup } = req.body;

      const [existing] = await db.select()
        .from(accountDealershipProfiles)
        .where(eq(accountDealershipProfiles.accountId, accountId))
        .limit(1);

      const [result] = await db.insert(accountDealershipProfiles)
        .values({
          accountId,
          franchiseBrand: franchiseBrand || null,
          dealerCode: dealerCode || null,
          storeNumber: storeNumber || null,
          rooftopGroup: rooftopGroup || null,
        })
        .onConflictDoUpdate({
          target: accountDealershipProfiles.accountId,
          set: {
            franchiseBrand: franchiseBrand || null,
            dealerCode: dealerCode || null,
            storeNumber: storeNumber || null,
            rooftopGroup: rooftopGroup || null,
            updatedAt: new Date(),
          },
        })
        .returning();

      if (existing) {
        const changedFields: Record<string, { from: string | null; to: string | null }> = {};
        if (existing.franchiseBrand !== (franchiseBrand || null)) changedFields.franchiseBrand = { from: existing.franchiseBrand, to: franchiseBrand || null };
        if (existing.dealerCode !== (dealerCode || null)) changedFields.dealerCode = { from: existing.dealerCode, to: dealerCode || null };
        if (existing.storeNumber !== (storeNumber || null)) changedFields.storeNumber = { from: existing.storeNumber, to: storeNumber || null };
        if (existing.rooftopGroup !== (rooftopGroup || null)) changedFields.rooftopGroup = { from: existing.rooftopGroup, to: rooftopGroup || null };

        await storage.createAccountActivityEvent({
          accountId,
          category: 'system',
          eventType: 'dealership_profile_updated',
          summary: 'Dealership profile updated',
          createdByUserId: userId,
          metadata: JSON.stringify({ changedFields }),
        });
      } else {
        await storage.createAccountActivityEvent({
          accountId,
          category: 'system',
          eventType: 'dealership_profile_created',
          summary: 'Dealership profile created',
          createdByUserId: userId,
          metadata: null,
        });
      }

      res.json(result);
    } catch (error) {
      console.error("Error upserting dealership profile:", error);
      res.status(500).json({ message: "Failed to save dealership profile" });
    }
  });

