  // Update account flags (Admin/Exec roles only)
  // Flags: isStrategicAccount, isHighSensitivity, isCarrierVisible, requiresExecAttention
  // These flags do NOT affect health scores - they're for prioritization and routing
  app.patch("/api/accounts/:id/flags", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      // Only Admin/Exec roles can set flags (super_user = super admin, admin = corporate admin)
      if (!role || !['super_user', 'admin'].includes(role)) {
        return res.status(403).json({ message: "Access denied: Admin or Executive role required" });
      }

      const accountId = req.params.id;
      const existingAccount = await storage.getCustomer(accountId);
      if (!existingAccount) {
        return res.status(404).json({ message: "Account not found" });
      }

      // Validate request body - only allow specific flag fields
      const { isStrategicAccount, isHighSensitivity, isCarrierVisible, requiresExecAttention } = req.body;
      const flagUpdates: Partial<{ isStrategicAccount: boolean; isHighSensitivity: boolean; isCarrierVisible: boolean; requiresExecAttention: boolean }> = {};
      
      // Track what flags are being changed for activity logging
      const flagChanges: { flag: string; oldValue: boolean; newValue: boolean }[] = [];
      const flagLabels: Record<string, string> = {
        isStrategicAccount: 'Strategic Account',
        isHighSensitivity: 'High Sensitivity',
        isCarrierVisible: 'Carrier Visible',
        requiresExecAttention: 'Executive Attention Required',
      };

      if (typeof isStrategicAccount === 'boolean' && isStrategicAccount !== existingAccount.isStrategicAccount) {
        flagUpdates.isStrategicAccount = isStrategicAccount;
        flagChanges.push({ flag: 'isStrategicAccount', oldValue: !!existingAccount.isStrategicAccount, newValue: isStrategicAccount });
      }
      if (typeof isHighSensitivity === 'boolean' && isHighSensitivity !== existingAccount.isHighSensitivity) {
        flagUpdates.isHighSensitivity = isHighSensitivity;
        flagChanges.push({ flag: 'isHighSensitivity', oldValue: !!existingAccount.isHighSensitivity, newValue: isHighSensitivity });
      }
      if (typeof isCarrierVisible === 'boolean' && isCarrierVisible !== existingAccount.isCarrierVisible) {
        flagUpdates.isCarrierVisible = isCarrierVisible;
        flagChanges.push({ flag: 'isCarrierVisible', oldValue: !!existingAccount.isCarrierVisible, newValue: isCarrierVisible });
      }
      if (typeof requiresExecAttention === 'boolean' && requiresExecAttention !== existingAccount.requiresExecAttention) {
        flagUpdates.requiresExecAttention = requiresExecAttention;
        flagChanges.push({ flag: 'requiresExecAttention', oldValue: !!existingAccount.requiresExecAttention, newValue: requiresExecAttention });
      }

      if (Object.keys(flagUpdates).length === 0) {
        return res.json({ message: "No flag changes to apply", account: existingAccount });
      }

      // Update the account
      const updatedAccount = await storage.updateCustomer(accountId, flagUpdates);

      // Log flag changes to Activity Timeline
      const activityPromises = flagChanges.map(change => 
        storage.createAccountActivityEvent({
          accountId,
          category: 'status',
          eventType: 'flag_changed',
          summary: `${flagLabels[change.flag]} flag ${change.newValue ? 'enabled' : 'disabled'}`,
          createdByUserId: currentUser?.id || undefined,
          metadata: JSON.stringify({
            flag: change.flag,
            previousValue: change.oldValue,
            newValue: change.newValue,
          }),
        })
      );
      await Promise.all(activityPromises);

      res.json(updatedAccount);
    } catch (error) {
      console.error("Error updating account flags:", error);
      res.status(500).json({ message: "Failed to update account flags" });
    }
  });

