  // POST /api/corporate/move-export-schedules — create a schedule
  app.post("/api/corporate/move-export-schedules", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
      const scheduleSchema = z.object({
        name:               z.string().min(1).max(100),
        recipients:         z.string().min(1).max(1000).refine((v) => {
          const addrs = v.split(",").map((s) => s.trim()).filter(Boolean);
          return addrs.length > 0 && addrs.every((a) => EMAIL_RE.test(a));
        }, { message: "Recipients must be valid comma-separated email addresses" }),
        cronExpression:     z.string().min(1).max(100),
        cronLabel:          z.string().max(200).nullable().optional(),
        timezone:           z.string().max(50).optional().default("America/Chicago"),
        enabled:            z.boolean().optional().default(true),
        filterMoveNumber:   z.string().nullable().optional(),
        filterDriver:       z.string().nullable().optional(),
        filterCustomer:     z.string().nullable().optional(),
        filterStatus:       z.string().nullable().optional(),
        filterMoveType:     z.string().nullable().optional(),
        filterSourceSystem: z.string().nullable().optional(),
        dateWindow:         z.enum(["today", "this_week", "this_month", "last_7_days", "last_30_days", "custom"]).optional().default("this_week"),
        filterStartDate:    z.string().nullable().optional(),
        filterEndDate:      z.string().nullable().optional(),
      });
      const data = scheduleSchema.parse(req.body);
      const created = await storage.createMoveExportSchedule({ ...data, userId });
      res.status(201).json(created);
    } catch (error) {
      if (error instanceof z.ZodError) return res.status(400).json({ message: "Validation error", errors: error.errors });
      console.error("[MoveExportSchedules] POST error:", error);
      res.status(500).json({ message: "Failed to create export schedule" });
    }
  });

