  // Export all matching trips as CSV
  app.get("/api/corporate/trips/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const EXPORT_CAP = 5000;
      const result = await storage.getTripsForExport({
        moveNumber:    req.query.moveNumber    as string | undefined,
        driver:        req.query.driver        as string | undefined,
        customer:      req.query.customer      as string | undefined,
        startDate:     req.query.startDate     as string | undefined,
        endDate:       req.query.endDate       as string | undefined,
        importBatchId: req.query.importBatchId as string | undefined,
        status:        req.query.status        as string | undefined,
        moveType:      req.query.moveType      as string | undefined,
        sourceSystem:  req.query.sourceSystem  as string | undefined,
        sortBy:        req.query.sortBy        as string | undefined,
        sortDir:       req.query.sortDir       as string | undefined,
        limit:         EXPORT_CAP,
      });

      const { rows, truncated, cap } = result;

      // Return JSON payload so the client can render the rows via excelExport
      // and display a truncation warning when needed.
      res.json({
        trips: rows,
        truncated,
        cap,
        count: rows.length,
      });
    } catch (error) {
      console.error("Error exporting trips:", error);
      res.status(500).json({ message: "Failed to export trips" });
    }
  });

