  // Create trip with GATE 1: Eligibility snapshot at ingestion (INCREMENT 25B)
  // Refactored to use unified importMoves() function
  app.post("/api/corporate/trips", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const validatedData = insertTripSchema.parse(req.body);
      
      // Use unified importMoves for manual trip creation
      const { importMoves } = await import('./imports/importMoves');
      
      const moveInput = {
        moveNumber: validatedData.moveNumber,
        driverId: validatedData.driverId || null,
        customerId: validatedData.customerId || null,
        tripDate: validatedData.tripDate,
        origin: validatedData.origin,
        destination: validatedData.destination,
        distance: validatedData.distance || null,
        duration: validatedData.duration || null,
        status: validatedData.status || 'completed',
        moveType: validatedData.moveType || null,
        vehicleType: validatedData.vehicleType || null,
        billRate: validatedData.billRate || null,
        payRate: validatedData.payRate || null,
        notes: validatedData.notes || null,
        marketId: validatedData.marketId || null,
        zoneId: validatedData.zoneId || null,
        workType: validatedData.workType || null,
        executionMode: validatedData.executionMode || null,
      };
      
      const result = await importMoves([moveInput], {
        source: 'MANUAL',
        ingestedBy: userId,
        storage: {
          getDriver: (id: string) => storage.getDriver(id),
          createTrip: (trip: any) => storage.createTrip(trip),
        },
      });
      
      if (result.results[0]?.success) {
        // Fetch the created trip to return full data
        const trip = await storage.getTrip(result.results[0].tripId!);
        
        // Send MOVE_SCHEDULED notification to customer if enabled
        if (trip?.customerId) {
          const customer = await storage.getCustomer(trip.customerId);
          if (customer?.email && customer.contactUserId) {
            sendCustomerNotificationIfEnabled(
              customer.contactUserId,
              'MOVE_SCHEDULED',
              () => sendMoveScheduledNotification({
                to: customer.email!,
                customerName: customer.name || 'Customer',
                moveNumber: trip.moveNumber || trip.id,
                tripDate: trip.tripDate ? new Date(trip.tripDate).toLocaleDateString() : 'TBD',
                origin: trip.origin || 'Origin',
                destination: trip.destination || 'Destination',
              })
            );
          }
        }
        
        // Emit MOVE_CREATED event for Ops Console integration
        try {
          const { emitMoveCreatedEvent } = await import('./moveEventService');
          await emitMoveCreatedEvent(trip.id, userId);
        } catch (eventError) {
          console.error("[Move Events] Failed to emit MOVE_CREATED event:", eventError);
        }
        
        res.json(trip);
      } else {
        res.status(400).json({ 
          message: "Failed to create trip", 
          error: result.results[0]?.error,
          eligibilityStatus: result.results[0]?.eligibilityStatus,
          eligibilityReasons: result.results[0]?.eligibilityReasons,
        });
      }
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error creating trip:", error);
      res.status(500).json({ message: "Failed to create trip" });
    }
  });

  // Update trip
  app.patch("/api/corporate/trips/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Get the existing trip to check for driver assignment change
      const existingTrip = await storage.getTrip(req.params.id);
      const validatedData = updateTripSchema.parse(req.body);
      const trip = await storage.updateTrip(req.params.id, validatedData);

      if (!trip) {
        return res.status(404).json({ message: "Trip not found" });
      }

      // Send MOVE_ASSIGNED notification if driver was just assigned
      const wasAssigned = !existingTrip?.driverId && trip.driverId;
      if (wasAssigned && trip.customerId) {
        const customer = await storage.getCustomer(trip.customerId);
        const driver = trip.driverId ? await storage.getDriver(trip.driverId) : null;
        if (customer?.email && customer.contactUserId) {
          sendCustomerNotificationIfEnabled(
            customer.contactUserId,
            'MOVE_ASSIGNED',
            () => sendMoveAssignedNotification({
              to: customer.email!,
              customerName: customer.name || 'Customer',
              moveNumber: trip.moveNumber || trip.id,
              tripDate: trip.tripDate ? new Date(trip.tripDate).toLocaleDateString() : 'TBD',
              driverFirstName: driver?.firstName || 'Your driver',
            })
          );
        }
      }

      // Send MOVE_COMPLETED notification if status changed to completed
      const wasCompleted = existingTrip?.status !== 'completed' && trip.status === 'completed';
      if (wasCompleted && trip.customerId) {
        const customer = await storage.getCustomer(trip.customerId);
        if (customer?.email && customer.contactUserId) {
          sendCustomerNotificationIfEnabled(
            customer.contactUserId,
            'MOVE_COMPLETED',
            () => sendMoveCompletedNotification({
              to: customer.email!,
              customerName: customer.name || 'Customer',
              moveNumber: trip.moveNumber || trip.id,
              completedAt: new Date().toLocaleDateString(),
              origin: trip.origin || 'Origin',
              destination: trip.destination || 'Destination',
            })
          );
        }
      }

      // Auto-update driver first/last trip dates when move is marked completed
      if (wasCompleted && trip.driverId) {
        try {
          const driverForDates = await storage.getDriver(trip.driverId);
          if (driverForDates) {
            const today = new Date().toISOString().split('T')[0];
            const dateUpdates: Record<string, string> = { lastMoveDate: today };
            if (!driverForDates.firstMoveDate) {
              dateUpdates.firstMoveDate = today;
            }
            await storage.updateDriver(trip.driverId, dateUpdates as any);
          }
        } catch (dateErr) {
          console.error('[Trip] Failed to update driver trip dates:', dateErr);
        }
      }

      // Emit MOVE_UPDATED event for Ops Console integration
      if (existingTrip) {
        try {
          const { emitMoveUpdatedEvent, detectChangedFields } = await import('./moveEventService');
          const changedFields = detectChangedFields(
            existingTrip as Record<string, unknown>,
            trip as Record<string, unknown>
          );
          if (changedFields.length > 0) {
            await emitMoveUpdatedEvent(trip.id, changedFields, userId);
          }
        } catch (eventError) {
          console.error("[Move Events] Failed to emit MOVE_UPDATED event:", eventError);
        }
      }

      res.json(trip);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error updating trip:", error);
      res.status(500).json({ message: "Failed to update trip" });
    }
  });

