  // Get expense alerts for current user
  app.get("/api/me/expense-alerts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      if (!user) {
        return res.status(404).json({ message: "User not found" });
      }

      const today = new Date();
      const yesterday = new Date(today);
      yesterday.setDate(yesterday.getDate() - 1);
      
      // Get start of last week (Monday)
      const lastWeekStart = new Date(today);
      lastWeekStart.setDate(today.getDate() - today.getDay() - 6); // Previous Monday
      lastWeekStart.setHours(0, 0, 0, 0);

      let hasOpenExpenses = false;
      let overdueCount = 0;
      let message = "";
      let userType: "driver" | "employee" = "employee";

      if (user.role === "driver") {
        userType = "driver";
        // Drivers: Check for pending expenses from yesterday or earlier
        const driverId = await storage.getDriverIdByUserId(userId);
        if (driverId) {
          const expenses = await storage.getExpensesByDriverId(driverId);
          const pendingExpenses = expenses.filter((e: any) => 
            e.status === "pending" && 
            new Date(e.expenseDate) < today
          );
          overdueCount = pendingExpenses.length;
          hasOpenExpenses = overdueCount > 0;
          if (hasOpenExpenses) {
            message = `You have ${overdueCount} expense(s) that should be submitted daily. Please submit them now.`;
          }
        }
      } else {
        // Employees: Check for pending expenses from last week
        const employee = await storage.getEmployeeByUserId(userId);
        if (employee) {
          const expenses = await storage.getExpensesByEmployeeId(employee.id);
          const pendingExpenses = expenses.filter((e: any) => 
            e.status === "pending" && 
            new Date(e.expenseDate) < lastWeekStart
          );
          overdueCount = pendingExpenses.length;
          hasOpenExpenses = overdueCount > 0;
          if (hasOpenExpenses) {
            message = `You have ${overdueCount} expense(s) from previous weeks that need to be submitted. Weekly expenses are due by Monday afternoon.`;
          }
        }
      }

      res.json({
        hasOpenExpenses,
        overdueCount,
        message,
        userType,
      });
    } catch (error) {
      console.error("Error fetching expense alerts:", error);
      res.status(500).json({ message: "Failed to fetch expense alerts" });
    }
  });

