  // GET /api/admin/abuse-events - List abuse events (admin only)
  app.get("/api/admin/abuse-events", isAuthenticated, requireAdmin, async (req: any, res: Response) => {
    try {
      const { type, severity, ip, route: routeFilter, limit: limitParam, offset: offsetParam, startDate, endDate } = req.query;
      const conditions: any[] = [];

      if (type) conditions.push(eq(abuseEvents.type, type as string));
      if (severity) conditions.push(eq(abuseEvents.severity, severity as string));
      if (ip) conditions.push(eq(abuseEvents.ip, ip as string));
      if (routeFilter) conditions.push(ilike(abuseEvents.route, `%${routeFilter}%`));
      if (startDate) conditions.push(gte(abuseEvents.createdAt, new Date(startDate as string)));
      if (endDate) conditions.push(lte(abuseEvents.createdAt, new Date(endDate as string)));

      const whereClause = conditions.length > 0 ? and(...conditions) : undefined;
      const queryLimit = Math.min(parseInt(limitParam as string) || 50, 200);
      const queryOffset = parseInt(offsetParam as string) || 0;

      const events = await db.select()
        .from(abuseEvents)
        .where(whereClause)
        .orderBy(desc(abuseEvents.createdAt))
        .limit(queryLimit)
        .offset(queryOffset);

      const [countResult] = await db.select({ count: sql<number>`count(*)::int` })
        .from(abuseEvents)
        .where(whereClause);

      res.json({ events, total: countResult?.count || 0, limit: queryLimit, offset: queryOffset });
    } catch (err) {
      console.error("[Admin] Failed to fetch abuse events:", err);
      res.status(500).json({ message: "Failed to fetch abuse events" });
    }
  });

