  // GET /api/admin/purge-claims/preview — Get counts of all claim records before purge
  app.get("/api/admin/purge-claims/preview", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ error: "UNAUTHORIZED", message: "Authentication required" });
      const user = await storage.getUser(userId);
      if (!user?.isRootSuperAdmin) return res.status(403).json({ error: "FORBIDDEN", message: "Root Super Admin access required" });

      const counts = await db.execute(sql`
        SELECT
          (SELECT COUNT(*) FROM accidents)                      AS accidents,
          (SELECT COUNT(*) FROM accident_attachments)           AS accident_attachments,
          (SELECT COUNT(*) FROM carrier_submission_events)      AS carrier_submission_events,
          (SELECT COUNT(*) FROM deletion_override_requests)     AS deletion_override_requests,
          (SELECT COUNT(*) FROM accident_category_meta)         AS accident_category_meta,
          (SELECT COUNT(*) FROM claim_events)                   AS claim_events,
          (SELECT COUNT(*) FROM claim_audit_logs)               AS claim_audit_logs,
          (SELECT COUNT(*) FROM claim_recoveries)               AS claim_recoveries,
          (SELECT COUNT(*) FROM claim_recovery_audit_logs)      AS claim_recovery_audit_logs
      `);

      const row = (counts as any).rows?.[0] ?? (counts as any)[0] ?? {};
      const totalChildRecords =
        Number(row.accident_attachments ?? 0) +
        Number(row.carrier_submission_events ?? 0) +
        Number(row.deletion_override_requests ?? 0) +
        Number(row.accident_category_meta ?? 0) +
        Number(row.claim_events ?? 0) +
        Number(row.claim_audit_logs ?? 0) +
        Number(row.claim_recoveries ?? 0) +
        Number(row.claim_recovery_audit_logs ?? 0);

      res.json({
        counts: {
          accidents: Number(row.accidents ?? 0),
          accidentAttachments: Number(row.accident_attachments ?? 0),
          carrierSubmissionEvents: Number(row.carrier_submission_events ?? 0),
          deletionOverrideRequests: Number(row.deletion_override_requests ?? 0),
          accidentCategoryMeta: Number(row.accident_category_meta ?? 0),
          claimEvents: Number(row.claim_events ?? 0),
          claimAuditLogs: Number(row.claim_audit_logs ?? 0),
          claimRecoveries: Number(row.claim_recoveries ?? 0),
          claimRecoveryAuditLogs: Number(row.claim_recovery_audit_logs ?? 0),
        },
        totalChildRecords,
        totalRecords: Number(row.accidents ?? 0) + totalChildRecords,
      });
    } catch (error: any) {
      console.error("[PurgeClaims] Preview error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: "Failed to load preview counts" });
    }
  });

  // POST /api/admin/purge-claims — Execute full claims data purge (Root Super Admin only)
  app.post("/api/admin/purge-claims", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ error: "UNAUTHORIZED", message: "Authentication required" });
      const user = await storage.getUser(userId);
      if (!user?.isRootSuperAdmin) return res.status(403).json({ error: "FORBIDDEN", message: "Root Super Admin access required" });

      const { confirmationPhrase, backupConfirmed } = req.body;
      if (confirmationPhrase !== "PURGE ALL CLAIMS DATA") {
        return res.status(400).json({ error: "INVALID_CONFIRMATION", message: "Confirmation phrase does not match. Type exactly: PURGE ALL CLAIMS DATA" });
      }
      if (!backupConfirmed) {
        return res.status(400).json({ error: "BACKUP_NOT_CONFIRMED", message: "You must confirm that a backup has been completed before purging." });
      }

      // 1. Capture pre-delete counts for audit log
      const countsBefore = await db.execute(sql`
        SELECT
          (SELECT COUNT(*) FROM accidents)                      AS accidents,
          (SELECT COUNT(*) FROM accident_attachments)           AS accident_attachments,
          (SELECT COUNT(*) FROM carrier_submission_events)      AS carrier_submission_events,
          (SELECT COUNT(*) FROM deletion_override_requests)     AS deletion_override_requests,
          (SELECT COUNT(*) FROM accident_category_meta)         AS accident_category_meta,
          (SELECT COUNT(*) FROM claim_events)                   AS claim_events,
          (SELECT COUNT(*) FROM claim_audit_logs)               AS claim_audit_logs,
          (SELECT COUNT(*) FROM claim_recoveries)               AS claim_recoveries,
          (SELECT COUNT(*) FROM claim_recovery_audit_logs)      AS claim_recovery_audit_logs
      `);
      const cb = (countsBefore as any).rows?.[0] ?? (countsBefore as any)[0] ?? {};

      // 2. Collect attachment storage keys before deletion (for file cleanup)
      const attachmentsResult = await db.execute(sql`
        SELECT id, file_url, file_name FROM accident_attachments WHERE is_deleted = false OR is_deleted = true
      `);
      const attachmentRows: any[] = (attachmentsResult as any).rows ?? (attachmentsResult as any) ?? [];

      // 3. DELETE all accidents — CASCADE handles all child tables
      await db.execute(sql`DELETE FROM accidents`);

      // 4. Best-effort: delete stored attachment files
      const storageErrors: string[] = [];
      if (attachmentRows.length > 0) {
        try {
          const { ObjectStorageService } = await import("./objectStorage");
          const storageService = new ObjectStorageService();
          for (const row of attachmentRows) {
            try {
              const rawUrl: string = row.file_url || "";
              const key = rawUrl.replace(/^\/objects\//, "").replace(/^\/+/, "");
              if (key) await storageService.deleteObject(key);
            } catch (fileErr: any) {
              storageErrors.push(row.id);
            }
          }
        } catch (storageImportErr) {
          console.warn("[PurgeClaims] Could not import storage service for file cleanup:", storageImportErr);
        }
      }

      // 5. Write immutable audit log entry
      const purgedCounts = {
        accidents: Number(cb.accidents ?? 0),
        accidentAttachments: Number(cb.accident_attachments ?? 0),
        carrierSubmissionEvents: Number(cb.carrier_submission_events ?? 0),
        deletionOverrideRequests: Number(cb.deletion_override_requests ?? 0),
        accidentCategoryMeta: Number(cb.accident_category_meta ?? 0),
        claimEvents: Number(cb.claim_events ?? 0),
        claimAuditLogs: Number(cb.claim_audit_logs ?? 0),
        claimRecoveries: Number(cb.claim_recoveries ?? 0),
        claimRecoveryAuditLogs: Number(cb.claim_recovery_audit_logs ?? 0),
      };
      const totalPurged = Object.values(purgedCounts).reduce((a, b) => a + b, 0);

      try {
        const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
        await writeSystemAuditEvent({
          eventType: 'CLAIMS_DATA_PURGE_EXECUTED',
          userId,
          roleClass: 'root_super_admin',
          metadata: {
            purgedCounts,
            totalPurged,
            backupConfirmed,
            filesAttempted: attachmentRows.length,
            fileCleanupErrors: storageErrors.length,
            environment: process.env.NODE_ENV || 'unknown',
            executedAt: new Date().toISOString(),
          },
        });
      } catch (auditErr) {
        console.error("[PurgeClaims] Failed to write audit log:", auditErr);
      }

      console.log(`[PurgeClaims] Purge executed by ${userId}: ${totalPurged} total records deleted`);

      res.json({
        success: true,
        purgedCounts,
        totalPurged,
        filesAttempted: attachmentRows.length,
        fileCleanupErrors: storageErrors.length,
        executedAt: new Date().toISOString(),
        message: `Successfully purged ${Number(cb.accidents ?? 0)} claims and ${totalPurged - Number(cb.accidents ?? 0)} child records.`,
      });
    } catch (error: any) {
      console.error("[PurgeClaims] Purge execution error:", error);
      res.status(500).json({ error: "INTERNAL_ERROR", message: error.message || "Purge failed. No data was changed." });
    }
  });

