  app.post("/api/corporate/claims/scan-invalid-dates", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!user || !["admin", "super_user"].includes(user.role || "")) {
        return res.status(403).json({ message: "Forbidden: Admin access required" });
      }

      const allAccidents = await db.select({
        id: accidents.id,
        incidentDate: accidents.incidentDate,
        accidentDate: accidents.accidentDate,
        claimStatus: accidents.claimStatus,
        driverId: accidents.driverId,
      }).from(accidents);

      const { validateIncidentDate } = await import("@shared/schema");
      const flagged: Array<{ id: string; date: string; reason: string }> = [];

      for (const acc of allAccidents) {
        const dateToCheck = acc.incidentDate || acc.accidentDate;
        if (!dateToCheck) continue;
        const dateStr = new Date(dateToCheck).toISOString().split("T")[0];
        const check = validateIncidentDate(dateStr);
        if (!check.valid) {
          flagged.push({ id: acc.id, date: dateStr, reason: check.error || "Invalid date" });
        }
      }

      res.json({
        message: `Scan complete. Found ${flagged.length} claims with invalid incident dates.`,
        total: allAccidents.length,
        flaggedCount: flagged.length,
        flagged: flagged.slice(0, 100),
      });
    } catch (error: any) {
      console.error("Error scanning claims:", error);
      res.status(500).json({ message: "Failed to scan claims" });
    }
  });

