  const SCHEDULING_PERMISSION_HIERARCHY: Record<string, number> = {
    'view': 1, 'edit': 2, 'approve': 3, 'publish': 4
  };

  async function resolveSchedulingPermission(userId: string, userRole: string | undefined, locationId?: string, teamId?: string): Promise<string> {
    if (userRole === 'super_user' || userRole === 'admin') return 'publish';
    
    const perms = await db.select().from(schedulingPermissions)
      .where(and(
        eq(schedulingPermissions.userId, userId),
        eq(schedulingPermissions.isActive, true)
      ));
    
    if (perms.length === 0) {
      return hasCorporateAccess(userRole) ? 'view' : 'none';
    }
    
    let highestLevel = 0;
    for (const perm of perms) {
      const locationMatch = !perm.locationId || perm.locationId === locationId;
      const teamMatch = !perm.teamId || perm.teamId === teamId;
      if (locationMatch && teamMatch) {
        const level = SCHEDULING_PERMISSION_HIERARCHY[perm.permissionLevel] || 0;
        if (level > highestLevel) highestLevel = level;
      }
    }
    
    const levelToName: Record<number, string> = { 1: 'view', 2: 'edit', 3: 'approve', 4: 'publish' };
    return levelToName[highestLevel] || 'none';
  }

  function hasSchedulingPermission(userPermLevel: string, requiredLevel: string): boolean {
    const hierarchy = SCHEDULING_PERMISSION_HIERARCHY;
    return (hierarchy[userPermLevel] || 0) >= (hierarchy[requiredLevel] || 0);
  }

