  async function resolveSchedulingUserId(req) {
    if (req.session?.userId) return req.session.userId;
    if (req.user?.claims?.sub) {
      const sub = req.user.claims.sub;
      const email = req.user.claims.email;
      let dbUser = await db.select({ id: users.id }).from(users).where(eq(users.id, sub)).limit(1);
      if (dbUser.length === 0 && email) {
        dbUser = await db.select({ id: users.id }).from(users).where(eq(users.email, email)).limit(1);
      }
      return dbUser[0]?.id || null;
    }
    return null;
  }

  // Scheduling Analytics Dashboard
  app.get('/api/corporate/scheduling/analytics', isAuthenticated, async (req: any, res: Response) => {
    try {
      const { startDate, endDate, locationId, role } = req.query;
      
      if (!startDate || !endDate) {
        return res.status(400).json({ message: 'startDate and endDate are required' });
      }

      const locationFilter = locationId && locationId !== 'all' ? locationId : null;
      const roleFilter = role && role !== 'all' ? role : null;

      // 1. Fill Rate: % of shifts filled (assignedStaff / requiredStaff)
      // Apply location filter; apply role filter by checking if shift has assignments with that role
      const fillRateResult = await db.execute(sql`
        SELECT 
          COALESCE(SUM(s.required_staff), 0) as total_required,
          COALESCE(SUM(s.assigned_staff), 0) as total_assigned
        FROM shifts s
        WHERE s.date >= ${startDate} AND s.date <= ${endDate}
          AND s.status != 'cancelled'
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
          ${roleFilter ? sql`AND s.template_id IN (SELECT st2.id FROM shift_templates st2 WHERE st2.role = ${roleFilter})` : sql``}
      `);
      
      const totalRequired = Number(fillRateResult.rows[0]?.total_required) || 0;
      const totalAssigned = Number(fillRateResult.rows[0]?.total_assigned) || 0;
      const fillRate = totalRequired > 0 ? Math.round((totalAssigned / totalRequired) * 100) : 0;

      // 2. Overtime Hours from shift assignments (more granular with location/role filters)
      const overtimeResult = await db.execute(sql`
        SELECT 
          COALESCE(SUM(CASE WHEN sa.is_overtime THEN CAST(sa.scheduled_hours AS numeric) ELSE 0 END), 0) as assignment_ot_hours,
          COALESCE(SUM(CASE WHEN sa.is_overtime THEN CAST(sa.actual_hours AS numeric) ELSE 0 END), 0) as assignment_ot_actual
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        LEFT JOIN shift_templates st ON s.template_id = st.id
        WHERE s.date >= ${startDate} AND s.date <= ${endDate}
          AND sa.status NOT IN ('declined', 'cancelled')
          AND s.status != 'cancelled'
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
          ${roleFilter ? sql`AND st.role = ${roleFilter}` : sql``}
      `);
      
      const overtimeHoursFromAssignments = Number(overtimeResult.rows[0]?.assignment_ot_hours) || 0;
      const overtimeActualFromAssignments = Number(overtimeResult.rows[0]?.assignment_ot_actual) || 0;

      // Also get timesheet OT for the period (filtered by users who have assignments matching filters)
      const timesheetOtResult = await db.execute(sql`
        SELECT 
          COALESCE(SUM(CAST(t.overtime_hours AS numeric)), 0) as ts_overtime,
          COALESCE(SUM(CAST(t.double_time_hours AS numeric)), 0) as ts_double_time
        FROM timesheets t
        WHERE t.period_start <= ${endDate} AND t.period_end >= ${startDate}
          ${(locationFilter || roleFilter) ? sql`AND t.user_id IN (
            SELECT DISTINCT sa3.user_id FROM shift_assignments sa3
            JOIN shifts s3 ON sa3.shift_id = s3.id
            LEFT JOIN shift_templates st3 ON s3.template_id = st3.id
            WHERE s3.date >= ${startDate} AND s3.date <= ${endDate}
              AND s3.status != 'cancelled'
              ${locationFilter ? sql`AND s3.location_id = ${locationFilter}` : sql``}
              ${roleFilter ? sql`AND st3.role = ${roleFilter}` : sql``}
          )` : sql``}
      `);
      
      const timesheetOt = Number(timesheetOtResult.rows[0]?.ts_overtime) || 0;
      const timesheetDt = Number(timesheetOtResult.rows[0]?.ts_double_time) || 0;
      const totalOvertimeHours = Math.max(timesheetOt + timesheetDt, overtimeActualFromAssignments);
      const projectedOtHours = overtimeHoursFromAssignments;

      // 3. Missed shifts (no_show) and late starts - deduplicated by assignment
      const missedShiftsResult = await db.execute(sql`
        SELECT DISTINCT ON (sa.id)
          sa.id as assignment_id,
          sa.user_id,
          sa.status as assignment_status,
          sa.scheduled_hours,
          st.role as role,
          s.id as shift_id,
          s.date as shift_date,
          s.start_time as shift_start_time,
          s.location_id,
          CONCAT(u.first_name, ' ', u.last_name) as driver_name,
          u.email as driver_email,
          wl.name as location_name,
          tce.event_time as clock_in_time
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        LEFT JOIN shift_templates st ON s.template_id = st.id
        LEFT JOIN users u ON sa.user_id = u.id
        LEFT JOIN work_locations wl ON s.location_id = wl.id
        LEFT JOIN time_clock_events tce ON tce.shift_assignment_id = sa.id AND tce.event_type = 'clock_in'
        WHERE s.date >= ${startDate} AND s.date <= ${endDate}
          AND (sa.status = 'no_show' OR (tce.event_time IS NOT NULL AND tce.event_time > s.start_time + interval '10 minutes'))
          AND s.status != 'cancelled'
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
          ${roleFilter ? sql`AND st.role = ${roleFilter}` : sql``}
        ORDER BY sa.id, tce.event_time ASC
        LIMIT 200
      `);

      const noShowCount = missedShiftsResult.rows.filter((r: any) => r.assignment_status === 'no_show').length;
      const lateStartCount = missedShiftsResult.rows.filter((r: any) => r.assignment_status !== 'no_show').length;

      // 4. Utilization by driver
      const utilizationResult = await db.execute(sql`
        SELECT 
          sa.user_id,
          CONCAT(u.first_name, ' ', u.last_name) as driver_name,
          u.email as driver_email,
          st.role as role,
          COALESCE(SUM(CAST(sa.scheduled_hours AS numeric)), 0) as total_scheduled_hours,
          COALESCE(SUM(CAST(sa.actual_hours AS numeric)), 0) as total_actual_hours,
          COALESCE(SUM(CASE WHEN sa.is_overtime THEN CAST(sa.scheduled_hours AS numeric) ELSE 0 END), 0) as overtime_hours,
          COUNT(*) as total_shifts,
          COUNT(CASE WHEN sa.status = 'no_show' THEN 1 END) as no_show_count,
          COUNT(CASE WHEN sa.status IN ('assigned', 'confirmed', 'completed') THEN 1 END) as completed_shifts
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        LEFT JOIN shift_templates st ON s.template_id = st.id
        LEFT JOIN users u ON sa.user_id = u.id
        WHERE s.date >= ${startDate} AND s.date <= ${endDate}
          AND sa.status NOT IN ('declined', 'cancelled')
          AND s.status != 'cancelled'
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
          ${roleFilter ? sql`AND st.role = ${roleFilter}` : sql``}
        GROUP BY sa.user_id, u.first_name, u.last_name, u.email, st.role
        ORDER BY total_scheduled_hours DESC
        LIMIT 200
      `);

      // Calculate utilization % based on working days in range (8h per weekday as baseline)
      const startD = new Date(startDate as string);
      const endD = new Date(endDate as string);
      const totalDays = Math.max(1, Math.ceil((endD.getTime() - startD.getTime()) / (1000 * 60 * 60 * 24)) + 1);
      const workingDays = Math.ceil(totalDays * 5 / 7);
      const maxHoursPerDriver = workingDays * 8;

      const utilizationByDriver = utilizationResult.rows.map((row: any) => ({
        userId: row.user_id,
        driverName: row.driver_name || row.driver_email || 'Unknown',
        role: row.role || 'Unassigned',
        scheduledHours: Number(row.total_scheduled_hours),
        actualHours: Number(row.total_actual_hours),
        overtimeHours: Number(row.overtime_hours),
        totalShifts: Number(row.total_shifts),
        noShowCount: Number(row.no_show_count),
        completedShifts: Number(row.completed_shifts),
        utilizationPercent: maxHoursPerDriver > 0 
          ? Math.min(100, Math.round((Number(row.total_scheduled_hours) / maxHoursPerDriver) * 100))
          : 0,
      }));

      const missedShifts = missedShiftsResult.rows.map((row: any) => {
        const lateMinutes = row.clock_in_time && row.shift_start_time 
          ? Math.round((new Date(row.clock_in_time).getTime() - new Date(row.shift_start_time).getTime()) / 60000)
          : null;
        return {
          assignmentId: row.assignment_id,
          userId: row.user_id,
          driverName: row.driver_name || row.driver_email || 'Unknown',
          shiftDate: row.shift_date,
          shiftStartTime: row.shift_start_time,
          locationName: row.location_name || 'Unassigned',
          role: row.role || 'Unassigned',
          type: row.assignment_status === 'no_show' ? 'no_show' : 'late_start',
          lateMinutes,
        };
      });

      // 5. Filter options
      const locationsResult = await db.execute(sql`
        SELECT id, name FROM work_locations WHERE is_active = true ORDER BY name
      `);

      const rolesResult = await db.execute(sql`
        SELECT DISTINCT role FROM shift_templates WHERE role IS NOT NULL AND role != '' AND is_active = true ORDER BY role
      `);

      // 6. Total shifts count
      const totalShiftsResult = await db.execute(sql`
        SELECT COUNT(*) as count FROM shifts 
        WHERE date >= ${startDate} AND date <= ${endDate}
          AND status != 'cancelled'
          ${locationFilter ? sql`AND location_id = ${locationFilter}` : sql``}
      `);

      const totalShifts = Number(totalShiftsResult.rows[0]?.count) || 0;

      const avgUtilization = utilizationByDriver.length > 0
        ? Math.round(utilizationByDriver.reduce((sum: number, d: any) => sum + d.utilizationPercent, 0) / utilizationByDriver.length)
        : 0;

      res.json({
        summary: {
          fillRate,
          totalRequired,
          totalAssigned,
          totalShifts,
          overtimeHours: totalOvertimeHours,
          projectedOvertimeHours: projectedOtHours,
          noShowCount,
          lateStartCount,
          avgUtilization,
          driverCount: utilizationByDriver.length,
        },
        utilizationByDriver,
        missedShifts,
        filters: {
          locations: locationsResult.rows.map((r: any) => ({ id: r.id, name: r.name })),
          roles: rolesResult.rows.map((r: any) => r.role).filter(Boolean),
        },
      });
    } catch (error) {
      console.error('Error fetching scheduling analytics:', error);
      res.status(500).json({ message: 'Failed to fetch scheduling analytics' });
    }
  });

  // iCal helper functions
  function formatICalDate(date: Date): string {
    return date.toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, '');
  }

  function escapeICalText(text: string): string {
    return text.replace(/\\/g, '\\\\').replace(/;/g, '\\;').replace(/,/g, '\\,').replace(/\n/g, '\\n');
  }

    // Calendar Sync - iCal Feed Management
  // Generate or get existing feed token for current user
  app.post('/api/scheduling/calendar-feed/token', isAuthenticated, async (req: any, res: Response) => {
    try {
      let userId = (req.session as any)?.userId;
      if (!userId && req.user?.claims?.sub) {
        // OIDC: resolve actual user ID from DB by sub or email
        const sub = req.user.claims.sub;
        const email = req.user.claims.email;
        let dbUser = await db.execute(sql`SELECT id FROM users WHERE id = ${sub} LIMIT 1`);
        if (dbUser.rows.length === 0 && email) {
          dbUser = await db.execute(sql`SELECT id FROM users WHERE email = ${email} LIMIT 1`);
        }
        userId = dbUser.rows[0]?.id as string || null;
      }
      if (!userId) return res.status(401).json({ message: 'Unauthorized' });

      const label = req.body.label || 'My Schedule';

      // Check for existing active token
      const existing = await db.execute(sql`
        SELECT * FROM calendar_feed_tokens WHERE user_id = ${userId} AND is_active = true LIMIT 1
      `);

      if (existing.rows.length > 0) {
        return res.json({ token: existing.rows[0] });
      }

      // Generate new token (crypto-safe random)
      const crypto = await import('crypto');
      const token = crypto.randomBytes(32).toString('hex');

      const result = await db.execute(sql`
        INSERT INTO calendar_feed_tokens (user_id, token, label)
        VALUES (${userId}, ${token}, ${label})
        RETURNING *
      `);

      res.json({ token: result.rows[0] });
    } catch (error) {
      console.error('Error creating calendar feed token:', error);
      res.status(500).json({ message: 'Failed to create calendar feed token' });
    }
  });

  // Get current user's feed tokens
  app.get('/api/scheduling/calendar-feed/tokens', isAuthenticated, async (req: any, res: Response) => {
    try {
      let userId = (req.session as any)?.userId;
      if (!userId && req.user?.claims?.sub) {
        // OIDC: resolve actual user ID from DB by sub or email
        const sub = req.user.claims.sub;
        const email = req.user.claims.email;
        let dbUser = await db.execute(sql`SELECT id FROM users WHERE id = ${sub} LIMIT 1`);
        if (dbUser.rows.length === 0 && email) {
          dbUser = await db.execute(sql`SELECT id FROM users WHERE email = ${email} LIMIT 1`);
        }
        userId = dbUser.rows[0]?.id as string || null;
      }
      if (!userId) return res.status(401).json({ message: 'Unauthorized' });

      const tokens = await db.execute(sql`
        SELECT id, token, label, is_active, last_accessed_at, access_count, created_at
        FROM calendar_feed_tokens WHERE user_id = ${userId} ORDER BY created_at DESC
      `);

      res.json({ tokens: tokens.rows });
    } catch (error) {
      console.error('Error fetching calendar feed tokens:', error);
      res.status(500).json({ message: 'Failed to fetch calendar feed tokens' });
    }
  });

  // Revoke a feed token
  app.delete('/api/scheduling/calendar-feed/token/:tokenId', isAuthenticated, async (req: any, res: Response) => {
    try {
      let userId = (req.session as any)?.userId;
      if (!userId && req.user?.claims?.sub) {
        // OIDC: resolve actual user ID from DB by sub or email
        const sub = req.user.claims.sub;
        const email = req.user.claims.email;
        let dbUser = await db.execute(sql`SELECT id FROM users WHERE id = ${sub} LIMIT 1`);
        if (dbUser.rows.length === 0 && email) {
          dbUser = await db.execute(sql`SELECT id FROM users WHERE email = ${email} LIMIT 1`);
        }
        userId = dbUser.rows[0]?.id as string || null;
      }
      if (!userId) return res.status(401).json({ message: 'Unauthorized' });

      await db.execute(sql`
        UPDATE calendar_feed_tokens SET is_active = false
        WHERE id = ${req.params.tokenId} AND user_id = ${userId}
      `);

      res.json({ success: true });
    } catch (error) {
      console.error('Error revoking calendar feed token:', error);
      res.status(500).json({ message: 'Failed to revoke token' });
    }
  });

  // ── Account Contacts CRUD ─────────────────────────────────────────────────────

  // GET /api/accounts/:id/contacts
  app.get("/api/accounts/:id/contacts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const contacts = await db.execute(sql`
        SELECT ac.*,
               u.first_name || ' ' || u.last_name AS created_by_name,
               u2.first_name || ' ' || u2.last_name AS updated_by_name
        FROM account_contacts ac
        LEFT JOIN users u  ON u.id  = ac.created_by_user_id
        LEFT JOIN users u2 ON u2.id = ac.updated_by_user_id
        WHERE ac.account_id = ${id}
        ORDER BY ac.is_primary DESC, ac.is_billing DESC, ac.created_at ASC
      `);
      // Raw SQL returns snake_case — map to camelCase for the frontend
      const toCamel = (row: any): any => Object.fromEntries(
        Object.entries(row).map(([k, v]) => [k.replace(/_([a-z])/g, (_: string, c: string) => c.toUpperCase()), v])
      );
      res.json({ contacts: contacts.rows.map(toCamel) });
    } catch (err) {
      console.error("Error fetching account contacts:", err);
      res.status(500).json({ message: "Failed to fetch contacts" });
    }
  });

  // POST /api/accounts/:id/contacts
  app.post("/api/accounts/:id/contacts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const {
        firstName, lastName, role, department, email,
        primaryPhone, secondaryPhone, mobilePhone, extension,
        notes, isPrimary, isBilling, isCommunication,
        receivesScheduleEmails, receivesEscalations, receivesBilling,
        receivesServiceUpdates, preferredCommunicationMethod, timeZone, status,
      } = req.body;

      if (!firstName || !lastName) {
        return res.status(400).json({ message: "First name and last name are required" });
      }

      // Enforce single-primary / single-billing uniqueness
      if (isPrimary) {
        await db.execute(sql`UPDATE account_contacts SET is_primary = false WHERE account_id = ${id} AND is_primary = true`);
      }
      if (isBilling) {
        await db.execute(sql`UPDATE account_contacts SET is_billing = false WHERE account_id = ${id} AND is_billing = true`);
      }

      const result = await db.execute(sql`
        INSERT INTO account_contacts (
          account_id, first_name, last_name, role, department, email,
          primary_phone, secondary_phone, mobile_phone, extension, notes,
          is_primary, is_billing, is_communication,
          receives_schedule_emails, receives_escalations, receives_billing, receives_service_updates,
          preferred_communication_method, time_zone, status, created_by_user_id, updated_by_user_id
        ) VALUES (
          ${id}, ${firstName}, ${lastName}, ${role || null}, ${department || null}, ${email || null},
          ${primaryPhone || null}, ${secondaryPhone || null}, ${mobilePhone || null}, ${extension || null}, ${notes || null},
          ${!!isPrimary}, ${!!isBilling}, ${!!isCommunication},
          ${!!receivesScheduleEmails}, ${!!receivesEscalations}, ${!!receivesBilling}, ${!!receivesServiceUpdates},
          ${preferredCommunicationMethod || null}, ${timeZone || null}, ${status || 'active'}, ${userId}, ${userId}
        ) RETURNING *
      `);

      const contact = result.rows[0] as any;

      // Sync to customers table if designated
      if (isPrimary) {
        await db.execute(sql`
          UPDATE customers SET
            primary_contact_name   = ${`${firstName} ${lastName}`},
            primary_contact_email  = ${email || null},
            primary_contact_number = ${primaryPhone || null},
            primary_contact_cell   = ${mobilePhone || null}
          WHERE id = ${id}
        `);
      }
      if (isBilling) {
        await db.execute(sql`
          UPDATE customers SET
            billing_contact_name   = ${`${firstName} ${lastName}`},
            billing_contact_email  = ${email || null},
            billing_contact_number = ${primaryPhone || null}
          WHERE id = ${id}
        `);
      }

      // Log to account activity
      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'contact', 'contact_created', ${`Contact added: ${firstName} ${lastName}${role ? ` (${role})` : ''}`}, ${userId})
      `);

      res.status(201).json({ contact });
    } catch (err) {
      console.error("Error creating account contact:", err);
      res.status(500).json({ message: "Failed to create contact" });
    }
  });

  // PATCH /api/accounts/:id/contacts/:contactId
  app.patch("/api/accounts/:id/contacts/:contactId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, contactId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const {
        firstName, lastName, role, department, email,
        primaryPhone, secondaryPhone, mobilePhone, extension,
        notes, isPrimary, isBilling, isCommunication,
        receivesScheduleEmails, receivesEscalations, receivesBilling,
        receivesServiceUpdates, preferredCommunicationMethod, timeZone, status,
      } = req.body;

      // Enforce uniqueness for designations
      if (isPrimary) {
        await db.execute(sql`UPDATE account_contacts SET is_primary = false WHERE account_id = ${id} AND is_primary = true AND id != ${contactId}`);
      }
      if (isBilling) {
        await db.execute(sql`UPDATE account_contacts SET is_billing = false WHERE account_id = ${id} AND is_billing = true AND id != ${contactId}`);
      }

      await db.execute(sql`
        UPDATE account_contacts SET
          first_name = COALESCE(${firstName || null}, first_name),
          last_name  = COALESCE(${lastName  || null}, last_name),
          role       = ${role ?? null},
          department = ${department ?? null},
          email      = ${email || null},
          primary_phone   = ${primaryPhone   || null},
          secondary_phone = ${secondaryPhone || null},
          mobile_phone    = ${mobilePhone    || null},
          extension       = ${extension      || null},
          notes           = ${notes          || null},
          is_primary        = ${!!isPrimary},
          is_billing        = ${!!isBilling},
          is_communication  = ${!!isCommunication},
          receives_schedule_emails  = ${!!receivesScheduleEmails},
          receives_escalations      = ${!!receivesEscalations},
          receives_billing          = ${!!receivesBilling},
          receives_service_updates  = ${!!receivesServiceUpdates},
          preferred_communication_method = ${preferredCommunicationMethod || null},
          time_zone           = ${timeZone || null},
          status              = ${status   || 'active'},
          updated_by_user_id  = ${userId},
          updated_at          = NOW()
        WHERE id = ${contactId} AND account_id = ${id}
      `);

      const fn = firstName || '';
      const ln = lastName  || '';

      // Sync to customers
      if (isPrimary) {
        await db.execute(sql`
          UPDATE customers SET
            primary_contact_name   = ${`${fn} ${ln}`.trim()},
            primary_contact_email  = ${email || null},
            primary_contact_number = ${primaryPhone || null},
            primary_contact_cell   = ${mobilePhone || null}
          WHERE id = ${id}
        `);
      }
      if (isBilling) {
        await db.execute(sql`
          UPDATE customers SET
            billing_contact_name   = ${`${fn} ${ln}`.trim()},
            billing_contact_email  = ${email || null},
            billing_contact_number = ${primaryPhone || null}
          WHERE id = ${id}
        `);
      }

      // Log activity
      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'contact', 'contact_updated', ${`Contact updated: ${fn} ${ln}`.trim()}, ${userId})
      `);

      res.json({ success: true });
    } catch (err) {
      console.error("Error updating account contact:", err);
      res.status(500).json({ message: "Failed to update contact" });
    }
  });

  // PATCH /api/accounts/:id/contacts/:contactId/archive
  app.patch("/api/accounts/:id/contacts/:contactId/archive", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, contactId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;

      const result = await db.execute(sql`
        UPDATE account_contacts
        SET is_archived = true, archived_at = NOW(), archived_by_user_id = ${userId},
            status = 'inactive', is_primary = false, is_billing = false
        WHERE id = ${contactId} AND account_id = ${id}
        RETURNING first_name, last_name
      `);

      const c = result.rows[0] as any;
      if (!c) return res.status(404).json({ message: "Contact not found" });

      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'contact', 'contact_archived', ${`Contact archived: ${c.first_name} ${c.last_name}`}, ${userId})
      `);

      res.json({ success: true });
    } catch (err) {
      console.error("Error archiving account contact:", err);
      res.status(500).json({ message: "Failed to archive contact" });
    }
  });

  // PATCH /api/accounts/:id/contacts/:contactId/status — inline status-only update
  app.patch("/api/accounts/:id/contacts/:contactId/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, contactId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const { status } = req.body;
      if (!status || !["active", "inactive"].includes(status)) {
        return res.status(400).json({ message: "Invalid status value" });
      }
      const result = await db.execute(sql`
        UPDATE account_contacts
        SET status = ${status}, updated_at = NOW(), updated_by_user_id = ${userId}
        WHERE id = ${contactId} AND account_id = ${id}
        RETURNING id
      `);
      if (result.rows.length === 0) return res.status(404).json({ message: "Contact not found" });
      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'contact', 'contact_updated', ${`Contact status set to ${status}`}, ${userId})
      `);
      res.json({ success: true });
    } catch (err) {
      console.error("Error updating contact status:", err);
      res.status(500).json({ message: "Failed to update contact status" });
    }
  });

  // ── Account Departments CRUD ──────────────────────────────────────────────────

  const toCamelRow = (row: any): any => Object.fromEntries(
    Object.entries(row).map(([k, v]) => [k.replace(/_([a-z])/g, (_: string, c: string) => c.toUpperCase()), v])
  );

  // GET /api/accounts/:id/departments
  app.get("/api/accounts/:id/departments", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const result = await db.execute(sql`
        SELECT * FROM account_departments
        WHERE account_id = ${id}
        ORDER BY sort_order ASC, name ASC
      `);
      res.json({ departments: result.rows.map(toCamelRow) });
    } catch (err) {
      console.error("Error fetching account departments:", err);
      res.status(500).json({ message: "Failed to fetch departments" });
    }
  });

  // POST /api/accounts/:id/departments
  app.post("/api/accounts/:id/departments", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const { name, code, description, sortOrder, isActive } = req.body;

      if (!name || !String(name).trim()) {
        return res.status(400).json({ message: "Department name is required" });
      }

      const account = await storage.getCustomer(id);
      if (!account) {
        return res.status(404).json({ message: "Account not found" });
      }

      const dupe = await db.execute(sql`
        SELECT id FROM account_departments
        WHERE account_id = ${id} AND lower(name) = lower(${name})
      `);
      if (dupe.rows.length > 0) {
        return res.status(409).json({ message: "A department with this name already exists for this account" });
      }

      const result = await db.execute(sql`
        INSERT INTO account_departments (
          account_id, name, code, description, sort_order, is_active,
          created_by_user_id, updated_by_user_id
        ) VALUES (
          ${id}, ${String(name).trim()}, ${code || null}, ${description || null},
          ${sortOrder ?? 0}, ${isActive === undefined ? true : !!isActive},
          ${userId}, ${userId}
        ) RETURNING *
      `);

      const department = toCamelRow(result.rows[0]);

      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'department', 'department_created', ${`Department created: ${department.name}`}, ${userId})
      `);

      res.status(201).json({ department });
    } catch (err) {
      console.error("Error creating account department:", err);
      res.status(500).json({ message: "Failed to create department" });
    }
  });

  // PATCH /api/accounts/:id/departments/:departmentId
  app.patch("/api/accounts/:id/departments/:departmentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, departmentId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const { name, code, description, sortOrder, isActive } = req.body;

      const existingResult = await db.execute(sql`
        SELECT * FROM account_departments WHERE id = ${departmentId} AND account_id = ${id}
      `);
      const existing = existingResult.rows[0] as any;
      if (!existing) {
        return res.status(404).json({ message: "Department not found" });
      }

      if (name !== undefined && !String(name).trim()) {
        return res.status(400).json({ message: "Department name is required" });
      }

      if (name !== undefined && name.trim().toLowerCase() !== existing.name.toLowerCase()) {
        const dupe = await db.execute(sql`
          SELECT id FROM account_departments
          WHERE account_id = ${id} AND lower(name) = lower(${name}) AND id != ${departmentId}
        `);
        if (dupe.rows.length > 0) {
          return res.status(409).json({ message: "A department with this name already exists for this account" });
        }
      }

      // Deactivation must never leave an account with zero active departments
      if (isActive === false && existing.is_active) {
        const activeCountResult = await db.execute(sql`
          SELECT count(*)::int AS count FROM account_departments
          WHERE account_id = ${id} AND is_active = true AND id != ${departmentId}
        `);
        const activeCount = (activeCountResult.rows[0] as any).count;
        if (activeCount === 0) {
          return res.status(400).json({ message: "At least one active department is required for this account" });
        }
      }

      const result = await db.execute(sql`
        UPDATE account_departments SET
          name = ${name !== undefined ? String(name).trim() : existing.name},
          code = ${code !== undefined ? (code || null) : existing.code},
          description = ${description !== undefined ? (description || null) : existing.description},
          sort_order = ${sortOrder !== undefined ? sortOrder : existing.sort_order},
          is_active = ${isActive !== undefined ? !!isActive : existing.is_active},
          updated_at = NOW(),
          updated_by_user_id = ${userId}
        WHERE id = ${departmentId} AND account_id = ${id}
        RETURNING *
      `);

      const department = toCamelRow(result.rows[0]);

      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'department', 'department_updated', ${`Department updated: ${department.name}`}, ${userId})
      `);

      res.json({ department });
    } catch (err) {
      console.error("Error updating account department:", err);
      res.status(500).json({ message: "Failed to update department" });
    }
  });

  // PATCH /api/accounts/:id/departments/:departmentId/status — activate / deactivate (soft only, never deletes)
  app.patch("/api/accounts/:id/departments/:departmentId/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, departmentId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const { isActive } = req.body;

      if (typeof isActive !== "boolean") {
        return res.status(400).json({ message: "isActive (boolean) is required" });
      }

      const existingResult = await db.execute(sql`
        SELECT * FROM account_departments WHERE id = ${departmentId} AND account_id = ${id}
      `);
      const existing = existingResult.rows[0] as any;
      if (!existing) {
        return res.status(404).json({ message: "Department not found" });
      }

      if (!isActive && existing.is_active) {
        const activeCountResult = await db.execute(sql`
          SELECT count(*)::int AS count FROM account_departments
          WHERE account_id = ${id} AND is_active = true AND id != ${departmentId}
        `);
        const activeCount = (activeCountResult.rows[0] as any).count;
        if (activeCount === 0) {
          return res.status(400).json({ message: "At least one active department is required for this account" });
        }
      }

      const result = await db.execute(sql`
        UPDATE account_departments
        SET is_active = ${isActive}, updated_at = NOW(), updated_by_user_id = ${userId}
        WHERE id = ${departmentId} AND account_id = ${id}
        RETURNING *
      `);

      const department = toCamelRow(result.rows[0]);

      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'department', ${isActive ? 'department_reactivated' : 'department_deactivated'},
                ${`Department ${isActive ? 'reactivated' : 'deactivated'}: ${department.name}`}, ${userId})
      `);

      res.json({ department });
    } catch (err) {
      console.error("Error updating account department status:", err);
      res.status(500).json({ message: "Failed to update department status" });
    }
  });

  // ── Department Business Configuration ─────────────────────────────────────────
  // Per-department operational settings (business hours, timezone, holiday
  // calendar, cost center/GL code) that inherit from the parent Account unless
  // explicitly overridden. Effective settings are exposed both under the
  // account-scoped path (for the Account Detail UI) and a standalone
  // departmentId path (for other platform modules that only have a departmentId).

  const buildEffectiveSettings = (deptRow: any, accountRow: any) =>
    resolveDepartmentSettings(deptRow.id, deptRow.account_id, {
      timezone: deptRow.timezone,
      businessHours: deptRow.business_hours,
      useAccountHolidayCalendar: deptRow.use_account_holiday_calendar,
      customHolidays: deptRow.custom_holidays,
      costCenter: deptRow.cost_center,
      glCode: deptRow.gl_code,
      defaultPromiseModel: deptRow.default_promise_model,
      spendApprovalThreshold: deptRow.spend_approval_threshold,
    }, {
      timezone: accountRow.timezone,
      operatingHours: accountRow.operating_hours,
    });

  // GET /api/accounts/:id/departments/:departmentId/settings
  app.get("/api/accounts/:id/departments/:departmentId/settings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, departmentId } = req.params;

      const deptResult = await db.execute(sql`
        SELECT * FROM account_departments WHERE id = ${departmentId} AND account_id = ${id}
      `);
      const deptRow = deptResult.rows[0] as any;
      if (!deptRow) {
        return res.status(404).json({ message: "Department not found" });
      }

      const accountResult = await db.execute(sql`
        SELECT timezone, operating_hours FROM customers WHERE id = ${id}
      `);
      const accountRow = (accountResult.rows[0] as any) || { timezone: null, operating_hours: null };

      res.json({
        raw: toCamelRow(deptRow),
        effective: buildEffectiveSettings(deptRow, accountRow),
      });
    } catch (err) {
      console.error("Error fetching department settings:", err);
      res.status(500).json({ message: "Failed to fetch department settings" });
    }
  });

  // PATCH /api/accounts/:id/departments/:departmentId/settings
  app.patch("/api/accounts/:id/departments/:departmentId/settings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { id, departmentId } = req.params;
      const userId = (req.session as any)?.userId || req.user?.claims?.sub || null;
      const {
        timezone, businessHours, useAccountHolidayCalendar, customHolidays,
        costCenter, glCode, defaultPromiseModel, spendApprovalThreshold,
      } = req.body;

      const existingResult = await db.execute(sql`
        SELECT * FROM account_departments WHERE id = ${departmentId} AND account_id = ${id}
      `);
      const existing = existingResult.rows[0] as any;
      if (!existing) {
        return res.status(404).json({ message: "Department not found" });
      }

      if (customHolidays !== undefined && customHolidays !== null && !Array.isArray(customHolidays)) {
        return res.status(400).json({ message: "customHolidays must be an array of { name, date } entries" });
      }

      if (spendApprovalThreshold !== undefined && spendApprovalThreshold !== null && isNaN(Number(spendApprovalThreshold))) {
        return res.status(400).json({ message: "spendApprovalThreshold must be a number" });
      }

      const result = await db.execute(sql`
        UPDATE account_departments
        SET
          timezone = ${timezone === undefined ? existing.timezone : (timezone || null)},
          business_hours = ${businessHours === undefined ? existing.business_hours : (businessHours ? JSON.stringify(businessHours) : null)},
          use_account_holiday_calendar = ${useAccountHolidayCalendar === undefined ? existing.use_account_holiday_calendar : !!useAccountHolidayCalendar},
          custom_holidays = ${customHolidays === undefined ? existing.custom_holidays : (customHolidays ? JSON.stringify(customHolidays) : null)},
          cost_center = ${costCenter === undefined ? existing.cost_center : (costCenter || null)},
          gl_code = ${glCode === undefined ? existing.gl_code : (glCode || null)},
          default_promise_model = ${defaultPromiseModel === undefined ? existing.default_promise_model : (defaultPromiseModel || null)},
          spend_approval_threshold = ${spendApprovalThreshold === undefined ? existing.spend_approval_threshold : (spendApprovalThreshold === null ? null : spendApprovalThreshold)},
          updated_at = NOW(),
          updated_by_user_id = ${userId}
        WHERE id = ${departmentId} AND account_id = ${id}
        RETURNING *
      `);

      const deptRow = result.rows[0] as any;

      const accountResult = await db.execute(sql`
        SELECT timezone, operating_hours FROM customers WHERE id = ${id}
      `);
      const accountRow = (accountResult.rows[0] as any) || { timezone: null, operating_hours: null };

      await db.execute(sql`
        INSERT INTO account_activity_events (account_id, category, event_type, summary, created_by_user_id)
        VALUES (${id}, 'department', 'department_settings_updated', ${`Business configuration updated for department: ${deptRow.name}`}, ${userId})
      `);

      res.json({
        raw: toCamelRow(deptRow),
        effective: buildEffectiveSettings(deptRow, accountRow),
      });
    } catch (err) {
      console.error("Error updating department settings:", err);
      res.status(500).json({ message: "Failed to update department settings" });
    }
  });

