  // Public iCal feed endpoint (no auth - uses token)
  app.get('/api/calendar-feed/:token.ics', async (req: any, res: Response) => {
    try {
      const { token } = req.params;

      // Validate token
      const tokenResult = await db.execute(sql`
        SELECT cft.*, u.first_name, u.last_name, u.email
        FROM calendar_feed_tokens cft
        JOIN users u ON cft.user_id = u.id
        WHERE cft.token = ${token} AND cft.is_active = true
      `);

      if (tokenResult.rows.length === 0) {
        return res.status(404).send('Calendar feed not found or expired');
      }

      const feedToken = tokenResult.rows[0];
      const userId = feedToken.user_id as string;

      // Update access tracking
      await db.execute(sql`
        UPDATE calendar_feed_tokens
        SET last_accessed_at = NOW(), access_count = access_count + 1
        WHERE token = ${token}
      `);

      // Fetch upcoming shifts for this user (next 90 days + past 7 days)
      const now = new Date();
      const pastDate = new Date(now);
      pastDate.setDate(pastDate.getDate() - 7);
      const futureDate = new Date(now);
      futureDate.setDate(futureDate.getDate() + 90);
      const pastStr = pastDate.toISOString().split('T')[0];
      const futureStr = futureDate.toISOString().split('T')[0];

      const shifts = await db.execute(sql`
        SELECT 
          sa.id as assignment_id,
          s.id as shift_id,
          s.date,
          s.start_time,
          s.end_time,
          s.notes as shift_notes,
          s.status as shift_status,
          st.name as template_name,
          st.role,
          wl.name as location_name,
          wl.address as location_address,
          sa.status as assignment_status,
          sa.notes as assignment_notes
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        LEFT JOIN shift_templates st ON s.template_id = st.id
        LEFT JOIN work_locations wl ON s.location_id = wl.id
        WHERE sa.user_id = ${userId}
          AND s.date >= ${pastStr} AND s.date <= ${futureStr}
          AND sa.status NOT IN ('declined', 'cancelled')
          AND s.status != 'cancelled'
        ORDER BY s.start_time ASC
      `);

      // Generate iCal content
      const driverName = [feedToken.first_name, feedToken.last_name].filter(Boolean).join(' ') || feedToken.email;
      const hostname = req.get('host') || 'driverhub360.replit.app';

      let ical = [
        'BEGIN:VCALENDAR',
        'VERSION:2.0',
        'PRODID:-//DriverHub 360//Scheduling//EN',
        'CALSCALE:GREGORIAN',
        'METHOD:PUBLISH',
        'X-WR-CALNAME:DriverHub Schedule - ' + driverName.replace(/[,;\\]/g, ''),
        'X-WR-TIMEZONE:America/Chicago',
        'REFRESH-INTERVAL;VALUE=DURATION:PT30M',
        'X-PUBLISHED-TTL:PT30M',
      ];

      for (const shift of shifts.rows) {
        const startTime = new Date(shift.start_time as string);
        const endTime = new Date(shift.end_time as string);
        const uid = (shift.assignment_id as string) + '@' + hostname;

        const summary = [
          shift.template_name || 'Shift',
          shift.role ? '(' + shift.role + ')' : '',
        ].filter(Boolean).join(' ');

        const location = [
          shift.location_name,
          shift.location_address,
        ].filter(Boolean).join(', ');

        const description = [
          shift.role ? 'Role: ' + shift.role : '',
          shift.location_name ? 'Location: ' + shift.location_name : '',
          shift.assignment_status ? 'Status: ' + (shift.assignment_status as string).charAt(0).toUpperCase() + (shift.assignment_status as string).slice(1) : '',
          shift.shift_notes ? 'Notes: ' + shift.shift_notes : '',
          shift.assignment_notes ? 'Assignment Notes: ' + shift.assignment_notes : '',
        ].filter(Boolean).join('\\n');

        ical.push('BEGIN:VEVENT');
        ical.push('UID:' + uid);
        ical.push('DTSTART:' + formatICalDate(startTime));
        ical.push('DTEND:' + formatICalDate(endTime));
        ical.push('DTSTAMP:' + formatICalDate(now));
        ical.push('SUMMARY:' + escapeICalText(summary));
        if (location) ical.push('LOCATION:' + escapeICalText(location));
        if (description) ical.push('DESCRIPTION:' + escapeICalText(description));

        // Status mapping
        if (shift.assignment_status === 'confirmed') {
          ical.push('STATUS:CONFIRMED');
        } else if (shift.assignment_status === 'assigned') {
          ical.push('STATUS:TENTATIVE');
        }

        ical.push('END:VEVENT');
      }

      ical.push('END:VCALENDAR');

      res.setHeader('Content-Type', 'text/calendar; charset=utf-8');
      res.setHeader('Content-Disposition', 'inline; filename="schedule.ics"');
      res.setHeader('Cache-Control', 'no-cache, no-store, must-revalidate');
      res.send(ical.join('\r\n'));
    } catch (error) {
      console.error('Error generating calendar feed:', error);
      res.status(500).send('Error generating calendar feed');
    }
  });

  // Labor Forecasting (Advisory Stub)
  app.get('/api/corporate/scheduling/labor-forecast', isAuthenticated, async (req: any, res: Response) => {
    try {
      const { forecastDays = '7', locationId } = req.query;
      const days = Math.min(Math.max(parseInt(forecastDays as string) || 7, 1), 30);
      const locationFilter = locationId && locationId !== 'all' ? locationId : null;

      const today = new Date();
      const todayStr = today.toISOString().split('T')[0];

      const forecastStart = new Date(today);
      forecastStart.setDate(forecastStart.getDate() + 1);
      const forecastEnd = new Date(today);
      forecastEnd.setDate(forecastEnd.getDate() + days);
      const forecastStartStr = forecastStart.toISOString().split('T')[0];
      const forecastEndStr = forecastEnd.toISOString().split('T')[0];

      const historicalStart = new Date(today);
      historicalStart.setDate(historicalStart.getDate() - 90);
      const historicalStartStr = historicalStart.toISOString().split('T')[0];

      const historicalStaffing = await db.execute(sql`
        SELECT 
          EXTRACT(DOW FROM s.date::date) as day_of_week,
          ROUND(AVG(s.required_staff), 1) as avg_required,
          ROUND(AVG(s.assigned_staff), 1) as avg_assigned,
          COUNT(DISTINCT s.date) as sample_days,
          COUNT(*) as shift_count
        FROM shifts s
        WHERE s.date >= ${historicalStartStr} AND s.date <= ${todayStr}
          AND s.status NOT IN ('cancelled', 'draft')
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
        GROUP BY EXTRACT(DOW FROM s.date::date)
        ORDER BY day_of_week
      `);

      const historicalVolume = await db.execute(sql`
        SELECT 
          EXTRACT(DOW FROM t.trip_date) as day_of_week,
          COUNT(*) as total_moves,
          COUNT(DISTINCT t.trip_date::date) as sample_days,
          ROUND(COUNT(*)::numeric / GREATEST(COUNT(DISTINCT t.trip_date::date), 1), 1) as avg_moves_per_day
        FROM trips t
        WHERE t.trip_date >= ${historicalStartStr}::timestamp AND t.trip_date <= ${todayStr}::timestamp
          AND t.status != 'cancelled'
        GROUP BY EXTRACT(DOW FROM t.trip_date)
        ORDER BY day_of_week
      `);

      const scheduledShifts = await db.execute(sql`
        SELECT 
          s.date,
          SUM(s.required_staff) as required_staff,
          SUM(s.assigned_staff) as assigned_staff,
          COUNT(*) as shift_count
        FROM shifts s
        WHERE s.date >= ${forecastStartStr} AND s.date <= ${forecastEndStr}
          AND s.status != 'cancelled'
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
        GROUP BY s.date
        ORDER BY s.date
      `);

      const hourlyPatterns = await db.execute(sql`
        SELECT 
          EXTRACT(HOUR FROM s.start_time) as hour_of_day,
          ROUND(AVG(s.required_staff), 1) as avg_required,
          COUNT(*) as shift_count
        FROM shifts s
        WHERE s.date >= ${historicalStartStr} AND s.date <= ${todayStr}
          AND s.status NOT IN ('cancelled', 'draft')
          ${locationFilter ? sql`AND s.location_id = ${locationFilter}` : sql``}
        GROUP BY EXTRACT(HOUR FROM s.start_time)
        ORDER BY hour_of_day
      `);

      const staffByDow: Record<number, any> = {};
      for (const row of historicalStaffing.rows) {
        staffByDow[Number(row.day_of_week)] = {
          avgRequired: Number(row.avg_required) || 0,
          avgAssigned: Number(row.avg_assigned) || 0,
          sampleDays: Number(row.sample_days) || 0,
          shiftCount: Number(row.shift_count) || 0,
        };
      }

      const volumeByDow: Record<number, any> = {};
      for (const row of historicalVolume.rows) {
        volumeByDow[Number(row.day_of_week)] = {
          avgMovesPerDay: Number(row.avg_moves_per_day) || 0,
          totalMoves: Number(row.total_moves) || 0,
          sampleDays: Number(row.sample_days) || 0,
        };
      }

      const scheduledByDate: Record<string, any> = {};
      for (const row of scheduledShifts.rows) {
        scheduledByDate[String(row.date)] = {
          requiredStaff: Number(row.required_staff) || 0,
          assignedStaff: Number(row.assigned_staff) || 0,
          shiftCount: Number(row.shift_count) || 0,
        };
      }

      let movesToStaffRatio = 5;
      let totalHistMoves = 0;
      let totalHistStaff = 0;
      for (let dow = 0; dow <= 6; dow++) {
        const vol = volumeByDow[dow];
        const staff = staffByDow[dow];
        if (vol && staff && staff.avgRequired > 0) {
          totalHistMoves += vol.avgMovesPerDay;
          totalHistStaff += staff.avgRequired;
        }
      }
      if (totalHistStaff > 0 && totalHistMoves > 0) {
        movesToStaffRatio = totalHistMoves / totalHistStaff;
      }

      const dailyForecast: any[] = [];
      const dayNames = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];

      for (let i = 1; i <= days; i++) {
        const forecastDate = new Date(today);
        forecastDate.setDate(forecastDate.getDate() + i);
        const dateStr = forecastDate.toISOString().split('T')[0];
        const dow = forecastDate.getDay();

        const histStaff = staffByDow[dow];
        const histVolume = volumeByDow[dow];
        const scheduled = scheduledByDate[dateStr];

        let recommendedMin = 0;
        let recommendedMax = 0;
        let confidence: 'high' | 'medium' | 'low' | 'none' = 'none';

        if (histStaff && histStaff.sampleDays >= 4) {
          recommendedMin = Math.max(1, Math.floor(histStaff.avgRequired * 0.8));
          recommendedMax = Math.ceil(histStaff.avgRequired * 1.2);
          confidence = histStaff.sampleDays >= 8 ? 'high' : 'medium';
        } else if (histVolume && histVolume.sampleDays >= 3) {
          const volumeBasedEstimate = Math.ceil(histVolume.avgMovesPerDay / movesToStaffRatio);
          recommendedMin = Math.max(1, Math.floor(volumeBasedEstimate * 0.8));
          recommendedMax = Math.ceil(volumeBasedEstimate * 1.3);
          confidence = histVolume.sampleDays >= 6 ? 'medium' : 'low';
        }

        let status: string = 'unscheduled';
        const currentStaff = scheduled?.assignedStaff || 0;
        const currentRequired = scheduled?.requiredStaff || 0;

        if (scheduled) {
          if (recommendedMin > 0) {
            if (currentStaff < recommendedMin) status = 'understaffed';
            else if (currentStaff > recommendedMax) status = 'overstaffed';
            else status = 'adequate';
          } else {
            if (currentRequired > 0 && currentStaff < currentRequired) status = 'understaffed';
            else if (currentRequired > 0 && currentStaff >= currentRequired) status = 'adequate';
          }
        }

        dailyForecast.push({
          date: dateStr,
          dayOfWeek: dow,
          dayName: dayNames[dow],
          historicalAvgStaff: histStaff?.avgRequired || 0,
          historicalAvgVolume: histVolume?.avgMovesPerDay || 0,
          recommendedMin,
          recommendedMax,
          confidence,
          currentScheduled: currentStaff,
          currentRequired,
          shiftCount: scheduled?.shiftCount || 0,
          status,
        });
      }

      const hourlyForecastArr = [];
      for (let h = 0; h < 24; h++) {
        const pattern = hourlyPatterns.rows.find((r: any) => Number(r.hour_of_day) === h);
        hourlyForecastArr.push({
          hour: h,
          label: h.toString().padStart(2, '0') + ':00',
          avgRequired: pattern ? Number(pattern.avg_required) : 0,
          shiftCount: pattern ? Number(pattern.shift_count) : 0,
        });
      }

      const understaffedDays = dailyForecast.filter(d => d.status === 'understaffed').length;
      const overstaffedDays = dailyForecast.filter(d => d.status === 'overstaffed').length;
      const unscheduledDays = dailyForecast.filter(d => d.status === 'unscheduled').length;
      const adequateDays = dailyForecast.filter(d => d.status === 'adequate').length;

      const locationsResult = await db.execute(sql`
        SELECT id, name FROM work_locations WHERE is_active = true ORDER BY name
      `);

      res.json({
        forecastWindow: { start: forecastStartStr, end: forecastEndStr, days },
        summary: {
          understaffedDays,
          overstaffedDays,
          adequateDays,
          unscheduledDays,
          historicalDataAvailable: Object.keys(staffByDow).length > 0 || Object.keys(volumeByDow).length > 0,
          movesToStaffRatio: Math.round(movesToStaffRatio * 10) / 10,
        },
        dailyForecast,
        hourlyPattern: hourlyForecastArr,
        locations: locationsResult.rows.map((r: any) => ({ id: r.id, name: r.name })),
        advisory: "This forecast is advisory only. No automated scheduling changes will be made.",
      });
    } catch (error) {
      console.error('Error fetching labor forecast:', error);
      res.status(500).json({ message: 'Failed to fetch labor forecast' });
    }
  });

