  app.get('/api/corporate/scheduling/permissions', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can manage scheduling permissions' });
      }
      const { locationId, userId: filterUserId } = req.query;
      let conditions = [eq(schedulingPermissions.isActive, true)];
      if (locationId) conditions.push(eq(schedulingPermissions.locationId, locationId as string));
      if (filterUserId) conditions.push(eq(schedulingPermissions.userId, filterUserId as string));
      
      const perms = await db.select({
        permission: schedulingPermissions,
        userName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        userEmail: users.email,
        userRole: users.role,
        locationName: workLocations.name,
      })
      .from(schedulingPermissions)
      .leftJoin(users, eq(schedulingPermissions.userId, users.id))
      .leftJoin(workLocations, eq(schedulingPermissions.locationId, workLocations.id))
      .where(and(...conditions))
      .orderBy(desc(schedulingPermissions.grantedAt));
      
      res.json({ permissions: perms });
    } catch (error) {
      console.error('Error fetching scheduling permissions:', error);
      res.status(500).json({ message: 'Failed to fetch scheduling permissions' });
    }
  });

  app.post('/api/corporate/scheduling/permissions', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can manage scheduling permissions' });
      }
      const { userId: targetUserId, permissionLevel, locationId, teamId, notes } = req.body;
      if (!targetUserId || !permissionLevel) {
        return res.status(400).json({ message: 'userId and permissionLevel are required' });
      }
      if (!['view', 'edit', 'approve', 'publish'].includes(permissionLevel)) {
        return res.status(400).json({ message: 'Invalid permission level' });
      }
      
      const existing = await db.select().from(schedulingPermissions).where(and(
        eq(schedulingPermissions.userId, targetUserId),
        eq(schedulingPermissions.isActive, true),
        locationId ? eq(schedulingPermissions.locationId, locationId) : isNull(schedulingPermissions.locationId)
      ));
      
      if (existing.length > 0) {
        const [updated] = await db.update(schedulingPermissions)
          .set({ permissionLevel, notes, teamId })
          .where(eq(schedulingPermissions.id, existing[0].id))
          .returning();
        
        await logSchedulingAudit({
          actorUserId: user.id,
          actionType: 'permission_granted',
          entityType: 'permission',
          entityId: updated.id,
          locationId,
          previousData: { permissionLevel: existing[0].permissionLevel },
          newData: { permissionLevel, userId: targetUserId, locationId, teamId },
          ipAddress: req.ip,
          userAgent: req.get('user-agent'),
        });
        
        return res.json({ permission: updated });
      }
      
      const [perm] = await db.insert(schedulingPermissions).values({
        userId: targetUserId,
        permissionLevel,
        locationId: locationId || null,
        teamId: teamId || null,
        grantedBy: user.id,
        notes: notes || null,
      }).returning();
      
      await logSchedulingAudit({
        actorUserId: user.id,
        actionType: 'permission_granted',
        entityType: 'permission',
        entityId: perm.id,
        locationId,
        newData: { permissionLevel, userId: targetUserId, locationId, teamId },
        ipAddress: req.ip,
        userAgent: req.get('user-agent'),
      });
      
      res.json({ permission: perm });
    } catch (error) {
      console.error('Error granting scheduling permission:', error);
      res.status(500).json({ message: 'Failed to grant scheduling permission' });
    }
  });

  app.delete('/api/corporate/scheduling/permissions/:id', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can manage scheduling permissions' });
      }
      
      const [existing] = await db.select().from(schedulingPermissions).where(eq(schedulingPermissions.id, req.params.id));
      if (!existing) return res.status(404).json({ message: 'Permission not found' });
      
      const [revoked] = await db.update(schedulingPermissions)
        .set({ isActive: false, revokedAt: new Date(), revokedBy: user.id })
        .where(eq(schedulingPermissions.id, req.params.id))
        .returning();
      
      await logSchedulingAudit({
        actorUserId: user.id,
        actionType: 'permission_revoked',
        entityType: 'permission',
        entityId: req.params.id,
        locationId: existing.locationId,
        previousData: { permissionLevel: existing.permissionLevel, userId: existing.userId },
        ipAddress: req.ip,
        userAgent: req.get('user-agent'),
      });
      
      res.json({ success: true, permission: revoked });
    } catch (error) {
      console.error('Error revoking scheduling permission:', error);
      res.status(500).json({ message: 'Failed to revoke scheduling permission' });
    }
  });

  // ===== SCHEDULING AUDIT LOG =====

  app.get('/api/corporate/scheduling/audit-log', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can view the scheduling audit log' });
      }
      
      const { actionType, entityType, actorUserId, locationId, startDate, endDate, limit: queryLimit, offset: queryOffset } = req.query;
      let conditions: any[] = [];
      
      if (actionType) conditions.push(eq(schedulingAuditLog.actionType, actionType as string));
      if (entityType) conditions.push(eq(schedulingAuditLog.entityType, entityType as string));
      if (actorUserId) conditions.push(eq(schedulingAuditLog.actorUserId, actorUserId as string));
      if (locationId) conditions.push(eq(schedulingAuditLog.locationId, locationId as string));
      if (startDate) conditions.push(gte(schedulingAuditLog.createdAt, new Date(startDate as string)));
      if (endDate) conditions.push(lte(schedulingAuditLog.createdAt, new Date(endDate as string)));
      
      const totalResult = await db.select({ count: sql<number>`count(*)::int` })
        .from(schedulingAuditLog)
        .where(conditions.length > 0 ? and(...conditions) : undefined);
      
      const logs = await db.select({
        log: schedulingAuditLog,
        actorName: sql<string>`CONCAT(${users.firstName}, ' ', ${users.lastName})`,
        actorEmail: users.email,
        locationName: workLocations.name,
      })
      .from(schedulingAuditLog)
      .leftJoin(users, eq(schedulingAuditLog.actorUserId, users.id))
      .leftJoin(workLocations, eq(schedulingAuditLog.locationId, workLocations.id))
      .where(conditions.length > 0 ? and(...conditions) : undefined)
      .orderBy(desc(schedulingAuditLog.createdAt))
      .limit(parseInt(queryLimit as string) || 50)
      .offset(parseInt(queryOffset as string) || 0);
      
      res.json({ 
        logs, 
        total: totalResult[0]?.count || 0,
        limit: parseInt(queryLimit as string) || 50,
        offset: parseInt(queryOffset as string) || 0,
      });
    } catch (error) {
      console.error('Error fetching scheduling audit log:', error);
      res.status(500).json({ message: 'Failed to fetch scheduling audit log' });
    }
  });


