  // Route 6: PUT /api/corporate/scheduling/noshow/config - Update noshow config
  app.put('/api/corporate/scheduling/noshow/config', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can update no-show config' });
      }

      const { enabled, lateGracePeriodMinutes, noshowGracePeriodMinutes, managementEscalationMinutes } = req.body;

      const updateData: any = { updatedBy: resolvedId };
      if (typeof enabled === 'boolean') updateData.enabled = enabled;
      if (typeof lateGracePeriodMinutes === 'number') {
        updateData.lateGracePeriodMinutes = Math.max(1, Math.min(120, lateGracePeriodMinutes));
      }
      if (typeof noshowGracePeriodMinutes === 'number') {
        updateData.noshowGracePeriodMinutes = Math.max(1, Math.min(240, noshowGracePeriodMinutes));
      }
      if (typeof managementEscalationMinutes === 'number') {
        updateData.managementEscalationMinutes = Math.max(1, Math.min(480, managementEscalationMinutes));
      }

      let [config] = await db.select().from(schedulingNoshowConfig).limit(1);
      if (!config) {
        [config] = await db.insert(schedulingNoshowConfig).values({
          ...updateData,
          enabled: updateData.enabled ?? true,
          lateGracePeriodMinutes: updateData.lateGracePeriodMinutes ?? 15,
          noshowGracePeriodMinutes: updateData.noshowGracePeriodMinutes ?? 30,
          managementEscalationMinutes: updateData.managementEscalationMinutes ?? 60,
        }).returning();
      } else {
        [config] = await db.update(schedulingNoshowConfig)
          .set(updateData)
          .where(eq(schedulingNoshowConfig.id, config.id))
          .returning();
      }

      res.json({ config });
    } catch (error) {
      console.error('Error updating no-show config:', error);
      res.status(500).json({ message: 'Failed to update config' });
    }
  });

