  // POST /api/scheduling/time-off with balance validation + manager workflow
  app.post("/api/scheduling/time-off/with-balance", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { requestType, startDate, endDate, totalHours, reason, isFullDay, startTime, endTime } = req.body;

      if (!requestType || !startDate || !endDate) {
        return res.status(400).json({ message: "Request type, start date, and end date are required" });
      }

      const hours = parseFloat(totalHours) || 8;
      const year = new Date(startDate).getFullYear();

      // Check balance if not unpaid
      if (requestType !== "unpaid") {
        const [balance] = await db.select().from(leaveBalances)
          .where(and(
            eq(leaveBalances.employeeId, userId),
            eq(leaveBalances.leaveType, requestType),
            eq(leaveBalances.year, year)
          )).limit(1);

        if (balance) {
          const remaining = parseFloat(balance.remainingHours || "0");
          const pending = parseFloat(balance.pendingHours || "0");
          const available = remaining - pending;

          if (available < hours && !balance.adminOverrideEnabled) {
            return res.status(409).json({
              message: `Insufficient ${requestType} balance. Available: ${available.toFixed(1)}h, Requested: ${hours}h`,
              available,
              requested: hours,
            });
          }

          // Add to pending hours
          await db.update(leaveBalances)
            .set({
              pendingHours: sql`COALESCE(${leaveBalances.pendingHours}, 0) + ${hours}`,
              updatedAt: new Date(),
            })
            .where(eq(leaveBalances.id, balance.id));
        }
      }

      // Look up manager from employee record
      let managerId: string | null = null;
      const [emp] = await db.select().from(employees)
        .where(eq(employees.userId, userId)).limit(1);
      if (emp?.directManagerId) {
        const [mgr] = await db.select().from(employees)
          .where(eq(employees.id, emp.directManagerId)).limit(1);
        if (mgr?.userId) managerId = mgr.userId;
      }

      const request = await storage.createTimeOffRequest({
        userId,
        requestType,
        startDate,
        endDate,
        totalHours: hours.toString(),
        reason: reason || null,
        isFullDay: isFullDay !== false,
        startTime: startTime || null,
        endTime: endTime || null,
        accrualYear: year,
        status: "pending",
        managerId,
      });

      // Send in-app notification to manager
      if (managerId) {
        const submitter = await storage.getUser(userId);
        const submitterName = [submitter?.firstName, submitter?.lastName].filter(Boolean).join(" ") || "An employee";
        await storage.createNotification({
          userId: managerId,
          type: "time_off_request",
          title: "Time Off Request Pending",
          message: `${submitterName} has requested ${hours}h of ${requestType} from ${startDate} to ${endDate}. Please review and approve or deny.`,
          relatedEntityType: "time_off_request",
          relatedEntityId: request.id,
        });
      }

      res.json(request);
    } catch (error) {
      console.error("Error creating time-off request:", error);
      res.status(500).json({ message: "Failed to create time-off request" });
    }
  });

  // POST /api/scheduling/time-off/:id/respond-clarification - employee responds to clarification
  app.post("/api/scheduling/time-off/:id/respond-clarification", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const request = await storage.getTimeOffRequest(req.params.id);
      if (!request) return res.status(404).json({ message: "Request not found" });
      if (request.userId !== userId) return res.status(403).json({ message: "Not your request" });
      if (request.status !== "clarification_requested") {
        return res.status(409).json({ message: "Request is not awaiting clarification" });
      }

      const updated = await storage.updateTimeOffRequest(req.params.id, {
        clarificationResponse: req.body.response,
        clarificationRespondedAt: new Date(),
        status: "pending",
        updatedAt: new Date(),
      });

      // Notify manager that clarification was provided
      if (request.managerId) {
        const submitter = await storage.getUser(userId);
        const name = [submitter?.firstName, submitter?.lastName].filter(Boolean).join(" ") || "Employee";
        await storage.createNotification({
          userId: request.managerId,
          type: "time_off_clarification",
          title: "Clarification Provided",
          message: `${name} has responded to your clarification request for their time-off request (${request.startDate} to ${request.endDate}).`,
          relatedEntityType: "time_off_request",
          relatedEntityId: request.id,
        });
      }

      res.json(updated);
    } catch (error) {
      console.error("Error responding to clarification:", error);
      res.status(500).json({ message: "Failed to respond to clarification" });
    }
  });

  // POST /api/scheduling/time-off/:id/cancel - employee cancels their own request
  app.post("/api/scheduling/time-off/:id/cancel", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const request = await storage.getTimeOffRequest(req.params.id);
      if (!request) return res.status(404).json({ message: "Request not found" });
      if (request.userId !== userId) return res.status(403).json({ message: "Not your request" });
      if (request.status === "approved" || request.status === "cancelled") {
        return res.status(409).json({ message: "Cannot cancel an already " + request.status + " request" });
      }

      // Restore pending hours
      const hours = parseFloat(request.totalHours || "0");
      if (request.requestType !== "unpaid" && hours > 0) {
        const year = new Date(request.startDate).getFullYear();
        const [balance] = await db.select().from(leaveBalances)
          .where(and(
            eq(leaveBalances.employeeId, userId),
            eq(leaveBalances.leaveType, request.requestType),
            eq(leaveBalances.year, year)
          )).limit(1);
        if (balance) {
          const currentPending = parseFloat(balance.pendingHours || "0");
          await db.update(leaveBalances)
            .set({ pendingHours: Math.max(0, currentPending - hours).toFixed(2), updatedAt: new Date() })
            .where(eq(leaveBalances.id, balance.id));
        }
      }

      const updated = await storage.updateTimeOffRequest(req.params.id, {
        status: "cancelled",
        updatedAt: new Date(),
      });

      res.json(updated);
    } catch (error) {
      console.error("Error cancelling request:", error);
      res.status(500).json({ message: "Failed to cancel request" });
    }
  });

