  // Corporate: POST accrue hours for a pay period (batch accrual)
  app.post("/api/corporate/scheduling/leave-balances/accrue", isAuthenticated, async (req: any, res: Response) => {
    try {
      const adminUser = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(adminUser?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const year = parseInt(req.body.year as string) || new Date().getFullYear();
      const reason = req.body.reason || "Pay period accrual";

      // Find all balances with per_pay_period accrual method and a positive accrual rate
      const eligibleBalances = await db.select().from(leaveBalances)
        .where(and(
          eq(leaveBalances.year, year),
          eq(leaveBalances.accrualMethod, "per_pay_period"),
        ));

      let accrued = 0;
      for (const balance of eligibleBalances) {
        const rate = parseFloat(balance.accrualRateHours || "0");
        if (rate <= 0) continue;

        const currentAccrued = parseFloat(balance.accruedHours || "0");
        const currentRemaining = parseFloat(balance.remainingHours || "0");
        const newAccrued = currentAccrued + rate;
        const newRemaining = currentRemaining + rate;

        await db.update(leaveBalances)
          .set({
            accruedHours: newAccrued.toFixed(2),
            remainingHours: newRemaining.toFixed(2),
            updatedAt: new Date(),
          })
          .where(eq(leaveBalances.id, balance.id));

        await db.insert(leaveBalanceAdjustments).values({
          leaveBalanceId: balance.id,
          employeeId: balance.employeeId,
          adjustmentType: "accrual",
          hours: rate.toFixed(2),
          balanceBefore: currentRemaining.toFixed(2),
          balanceAfter: newRemaining.toFixed(2),
          reason,
          performedByUserId: req.user.claims.sub,
        });
        accrued++;
      }

      res.json({ message: `Accrual processed for ${accrued} balances`, count: accrued });
    } catch (error) {
      console.error("Error running accrual:", error);
      res.status(500).json({ message: "Failed to run accrual" });
    }
  });

  // Enhanced time-off approval: deduct from leave balance on approval
  app.post("/api/corporate/scheduling/time-off/:id/approve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const adminUser = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(adminUser?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const request = await storage.getTimeOffRequest(req.params.id);
      if (!request) return res.status(404).json({ message: "Time-off request not found" });
      if (request.status !== "pending") return res.status(409).json({ message: "Request is already " + request.status });

      const hours = parseFloat(request.totalHours || "8");
      const year = new Date(request.startDate).getFullYear();

      // Deduct from leave balance
      if (request.requestType !== "unpaid") {
        const [balance] = await db.select().from(leaveBalances)
          .where(and(
            eq(leaveBalances.employeeId, request.userId),
            eq(leaveBalances.leaveType, request.requestType),
            eq(leaveBalances.year, year)
          )).limit(1);

        if (balance) {
          const currentUsed = parseFloat(balance.usedHours || "0");
          const currentRemaining = parseFloat(balance.remainingHours || "0");
          const currentPending = parseFloat(balance.pendingHours || "0");

          const newUsed = currentUsed + hours;
          const newRemaining = currentRemaining - hours;
          const newPending = Math.max(0, currentPending - hours);

          await db.update(leaveBalances)
            .set({
              usedHours: newUsed.toFixed(2),
              remainingHours: newRemaining.toFixed(2),
              pendingHours: newPending.toFixed(2),
              updatedAt: new Date(),
            })
            .where(eq(leaveBalances.id, balance.id));

          await db.insert(leaveBalanceAdjustments).values({
            leaveBalanceId: balance.id,
            employeeId: request.userId,
            adjustmentType: "approval_deduct",
            hours: (-hours).toFixed(2),
            balanceBefore: currentRemaining.toFixed(2),
            balanceAfter: newRemaining.toFixed(2),
            reason: `Approved time-off: ${request.startDate} to ${request.endDate}`,
            relatedRequestId: request.id,
            performedByUserId: req.user.claims.sub,
          });

          // Update time-off request with balance info + payroll + calendar
          await storage.updateTimeOffRequest(req.params.id, {
            status: "approved",
            reviewedBy: req.user.claims.sub,
            reviewedAt: new Date(),
            reviewNotes: req.body.reviewNotes || null,
            managerNotes: req.body.managerNotes || null,
            accrualBalanceBefore: currentRemaining.toFixed(2),
            accrualBalanceAfter: newRemaining.toFixed(2),
            accrualYear: year,
            payrollExportFlag: true,
            calendarBlocked: true,
          });
        } else {
          await storage.updateTimeOffRequest(req.params.id, {
            status: "approved",
            reviewedBy: req.user.claims.sub,
            reviewedAt: new Date(),
            reviewNotes: req.body.reviewNotes || null,
            managerNotes: req.body.managerNotes || null,
            payrollExportFlag: true,
            calendarBlocked: true,
          });
        }
      } else {
        await storage.updateTimeOffRequest(req.params.id, {
          status: "approved",
          reviewedBy: req.user.claims.sub,
          reviewedAt: new Date(),
          reviewNotes: req.body.reviewNotes || null,
          managerNotes: req.body.managerNotes || null,
          payrollExportFlag: true,
          calendarBlocked: true,
        });
      }

      // Notify employee of approval
      await storage.createNotification({
        userId: request.userId,
        type: "time_off_approved",
        title: "Time Off Approved",
        message: `Your ${request.requestType} request for ${request.startDate} to ${request.endDate} has been approved.${req.body.managerNotes ? ` Note: ${req.body.managerNotes}` : ""}`,
        relatedEntityType: "time_off_request",
        relatedEntityId: request.id,
      });

      const updated = await storage.getTimeOffRequest(req.params.id);
      res.json(updated);
    } catch (error) {
      console.error("Error approving time-off:", error);
      res.status(500).json({ message: "Failed to approve time-off request" });
    }
  });

