  // GET /api/scheduling/time-clock/shifts - get completed shift summaries
  app.get("/api/scheduling/time-clock/shifts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      const { startDate, endDate, employeeId } = req.query;

      // Corporate users can view any employee's shifts
      let targetUserId = userId;
      if (employeeId && hasCorporateAccess(user?.role)) {
        targetUserId = employeeId as string;
      }

      // Get all clock_in events with shift summaries
      let conditions: any[] = [eq(timeClockEvents.userId, targetUserId), eq(timeClockEvents.eventType, "clock_in")];
      if (startDate) conditions.push(gte(timeClockEvents.eventTime, new Date(startDate as string)));
      if (endDate) conditions.push(lte(timeClockEvents.eventTime, new Date(endDate as string)));

      const shifts = await db.select().from(timeClockEvents)
        .where(and(...conditions))
        .orderBy(desc(timeClockEvents.eventTime))
        .limit(100);

      // For each shift, get related events
      const shiftDetails = await Promise.all(shifts.map(async (clockIn) => {
        if (!clockIn.shiftId) return { ...clockIn, events: [] };
        const events = await db.select().from(timeClockEvents)
          .where(eq(timeClockEvents.shiftId, clockIn.shiftId))
          .orderBy(asc(timeClockEvents.eventTime));
        const clockOut = events.find(e => e.eventType === "clock_out");
        return {
          shiftId: clockIn.shiftId,
          clockIn: clockIn.eventTime,
          clockOut: clockOut?.eventTime || null,
          breakMinutes: clockIn.breakMinutes || 0,
          totalShiftMinutes: clockIn.totalShiftMinutes,
          overtimeFlag: clockIn.overtimeFlag,
          longShiftFlag: clockIn.longShiftFlag,
          userId: clockIn.userId,
          events,
        };
      }));

      res.json(shiftDetails);
    } catch (error) {
      console.error("Error fetching shifts:", error);
      res.status(500).json({ message: "Failed to fetch shifts" });
    }
  });

  // POST /api/scheduling/time-clock/edit-request - submit an edit request (users cannot edit punches directly)
  app.post("/api/scheduling/time-clock/edit-request", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const { punchId, reason, requestedEventType, requestedEventTime } = req.body;

      if (!punchId || !reason) {
        return res.status(400).json({ message: "Punch ID and reason are required" });
      }

      // Verify punch exists and belongs to the user
      const [punch] = await db.select().from(timeClockEvents).where(eq(timeClockEvents.id, punchId)).limit(1);
      if (!punch) return res.status(404).json({ message: "Punch not found" });
      if (punch.userId !== userId) return res.status(403).json({ message: "You can only request edits for your own punches" });

      const [editRequest] = await db.insert(punchEditRequests).values({
        punchId,
        requestedByUserId: userId,
        reason,
        requestedEventType: requestedEventType || null,
        requestedEventTime: requestedEventTime ? new Date(requestedEventTime) : null,
        status: "pending",
      }).returning();

      res.json(editRequest);
    } catch (error) {
      console.error("Error creating edit request:", error);
      res.status(500).json({ message: "Failed to submit edit request" });
    }
  });

