  // PATCH /api/corporate/scheduling/time-clock/edit-requests/:id - approve/deny edit request (manager only)
  app.patch("/api/corporate/scheduling/time-clock/edit-requests/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { status, reviewNotes } = req.body;
      if (!status || !["approved", "denied"].includes(status)) {
        return res.status(400).json({ message: "Status must be 'approved' or 'denied'" });
      }

      const [editRequest] = await db.select().from(punchEditRequests).where(eq(punchEditRequests.id, req.params.id)).limit(1);
      if (!editRequest) return res.status(404).json({ message: "Edit request not found" });
      if (editRequest.status !== "pending") return res.status(409).json({ message: "Edit request is already " + editRequest.status });

      const [updated] = await db.update(punchEditRequests)
        .set({ status, reviewedByUserId: userId, reviewedAt: new Date(), reviewNotes: reviewNotes || null, updatedAt: new Date() })
        .where(eq(punchEditRequests.id, req.params.id))
        .returning();

      // If approved, apply the edit to the punch
      if (status === "approved") {
        const patchData: any = { editedBy: userId, editReason: editRequest.reason, updatedAt: new Date() };
        if (editRequest.requestedEventType) patchData.eventType = editRequest.requestedEventType;
        if (editRequest.requestedEventTime) patchData.eventTime = editRequest.requestedEventTime;
        await db.update(timeClockEvents).set(patchData).where(eq(timeClockEvents.id, editRequest.punchId));
      }

      res.json(updated);
    } catch (error) {
      console.error("Error reviewing edit request:", error);
      res.status(500).json({ message: "Failed to review edit request" });
    }
  });

