  // ─── Financial Security Middleware ─────────────────────────────────────────
  // Intercepts every HTTP 403 on financial write endpoints and writes a denial
  // record to the immutable financial audit trail for compliance and forensics.
  // This is defence-in-depth: individual route role checks still fire first.
  app.use('/api/corporate/invoicing', (req: any, res: any, next: any) => {
    if (req.method === 'GET' || req.method === 'HEAD' || req.method === 'OPTIONS') return next();
    const _origJson = res.json.bind(res);
    res.json = function(data: any) {
      if (res.statusCode === 403) {
        const userId = req.user?.claims?.sub ?? req.user?.id ?? 'unauthenticated';
        const endpoint = `${req.method} ${req.originalUrl}`;
        console.warn(`[FinancialSecurity] ACCESS_DENIED user=${userId} ip=${req.ip} endpoint=${endpoint} error_code=${data?.error_code ?? 'n/a'} reason="${data?.message ?? 'unknown'}"`);
        import('./services/financialIntegrityService').then(({ writeFinancialAuditEvent }) => {
          writeFinancialAuditEvent({
            eventType: 'financial.access_denied',
            actorUserId: userId,
            actorUserEmail: req.user?.claims?.email ?? req.user?.email ?? null,
            targetEntityType: 'financial_api',
            targetEntityId: req.originalUrl,
            notes: data?.message ?? 'Access denied',
            metadata: {
              method: req.method,
              endpoint,
              errorCode: data?.error_code ?? 'UNKNOWN',
              ipAddress: req.ip,
            },
          }).catch(() => {});
        }).catch(() => {});
      }
      return _origJson(data);
    };
    next();
  });
  // ─── End Financial Security Middleware ─────────────────────────────────────

