  // ==========================================
  // BILLABLE CHARGES ROUTES
  // ==========================================

  // Get all billable charges with optional filters
  app.get("/api/corporate/invoicing/charges", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const conditions: any[] = [];
      if (req.query.customerId) conditions.push(eq(billableCharges.customerId, req.query.customerId as string));
      if (req.query.status) conditions.push(eq(billableCharges.status, req.query.status as string));
      if (req.query.sourceType) conditions.push(eq(billableCharges.sourceType, req.query.sourceType as string));
      if (req.query.startDate) conditions.push(gte(billableCharges.chargeDate, req.query.startDate as string));
      if (req.query.endDate) conditions.push(lte(billableCharges.chargeDate, req.query.endDate as string));
      const rows = await db
        .select({
          id: billableCharges.id,
          customerId: billableCharges.customerId,
          productId: billableCharges.productId,
          productName: products.name,
          revenueCategory: billableCharges.revenueCategory,
          sourceType: billableCharges.sourceType,
          chargeDate: billableCharges.chargeDate,
          description: billableCharges.description,
          quantity: billableCharges.quantity,
          unitRate: billableCharges.unitRate,
          amount: billableCharges.amount,
          status: billableCharges.status,
          billingStatus: billableCharges.billingStatus,
          notes: billableCharges.notes,
          createdAt: billableCharges.createdAt,
        })
        .from(billableCharges)
        .leftJoin(products, eq(products.id, billableCharges.productId))
        .where(conditions.length ? and(...conditions) : undefined)
        .orderBy(desc(billableCharges.chargeDate));
      res.json(rows);
    } catch (error) {
      console.error("Error fetching billable charges:", error);
      res.status(500).json({ message: "Failed to fetch billable charges" });
    }
  });

