  // Create billable charge (idempotency-protected)
  app.post("/api/corporate/invoicing/charges", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const _invUserChgCreate = { id: req.user.claims.sub, email: user?.email || '', role: user?.role };
      if (!hasInvoicingPermission(_invUserChgCreate, 'invoice:create_draft')) {
        return res.status(403).json({ error_code: 'CHARGE_PERMISSION_REQUIRED', message: 'Permission denied: creating billable charges requires invoice:create_draft', required_permission: 'invoice:create_draft' });
      }
      const { sourceReferenceId, sourceId, sourceType } = req.body;
      // ── Idempotency check: sourceReferenceId (preferred) ─────────────────────
      if (sourceReferenceId) {
        const [existing] = await db.select({ id: billableCharges.id, billingStatus: billableCharges.billingStatus })
          .from(billableCharges)
          .where(eq(billableCharges.sourceReferenceId, sourceReferenceId))
          .limit(1);
        if (existing) {
          return res.status(409).json({
            error_code: "CHARGE_ALREADY_EXISTS",
            message: "A charge already exists for this source reference. Duplicate charge creation is not allowed.",
            existingChargeId: existing.id,
            existingBillingStatus: existing.billingStatus,
          });
        }
      }
      // ── Fallback guard: sourceId + sourceType ────────────────────────────────
      if (!sourceReferenceId && sourceId && sourceType) {
        const [existing] = await db.select({ id: billableCharges.id })
          .from(billableCharges)
          .where(and(eq(billableCharges.sourceId, sourceId), eq(billableCharges.sourceType, sourceType)))
          .limit(1);
        if (existing) {
          return res.status(409).json({
            error_code: "CHARGE_ALREADY_EXISTS",
            message: "A charge already exists for this source (sourceType + sourceId).",
            existingChargeId: existing.id,
          });
        }
      }
      // Resolve product snapshot fields before inserting
      let productSnapshot: Record<string, any> = {};
      if (req.body.productId) {
        const [prod] = await db.select().from(products).where(eq(products.id, req.body.productId)).limit(1);
        if (prod) {
          productSnapshot = {
            productName: prod.name,
            billingCategory: prod.category || null,
            productTypeSnapshot: prod.productType || null,
            billingFrequencySnapshot: prod.billingFrequency || null,
            unitOfMeasure: prod.unit || null,
            glCode: prod.glCode || null,
            revenueCategory: req.body.revenueCategory || prod.revenueCategory || null,
            isTaxable: prod.taxable ?? false,
            taxRate: prod.taxRate ? String(prod.taxRate) : undefined,
          };
        }
      }
      const charge = await storage.createBillableCharge({
        ...req.body,
        ...productSnapshot,
        createdBy: req.user.claims.sub,
      });
      res.json(charge);
    } catch (error: any) {
      // DB-level unique constraint safety net
      if (error.code === "23505" && error.constraint === "billable_charges_source_ref_uniq") {
        return res.status(409).json({
          error_code: "CHARGE_ALREADY_EXISTS",
          message: "A charge already exists for this source reference (database constraint).",
        });
      }
      console.error("Error creating billable charge:", error);
      res.status(500).json({ message: "Failed to create billable charge" });
    }
  });

  // Batch create billable charges (idempotency-aware — skips duplicates, reports results)
  app.post("/api/corporate/invoicing/charges/batch", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const _invUserChgBatch = { id: req.user.claims.sub, email: user?.email || '', role: user?.role };
      if (!hasInvoicingPermission(_invUserChgBatch, 'invoice:create_draft')) {
        return res.status(403).json({ error_code: 'CHARGE_PERMISSION_REQUIRED', message: 'Permission denied: batch charge creation requires invoice:create_draft', required_permission: 'invoice:create_draft' });
      }
      const incoming: any[] = req.body.charges || [];
      if (!Array.isArray(incoming) || incoming.length === 0) {
        return res.status(400).json({ message: "charges array is required and must be non-empty" });
      }
      const created: any[] = [];
      const skipped: Array<{ sourceReferenceId?: string; sourceId?: string; existingChargeId: string; reason: string }> = [];

      for (const item of incoming) {
        const { sourceReferenceId, sourceId, sourceType } = item;
        // Check sourceReferenceId first
        if (sourceReferenceId) {
          const [existing] = await db.select({ id: billableCharges.id, billingStatus: billableCharges.billingStatus })
            .from(billableCharges)
            .where(eq(billableCharges.sourceReferenceId, sourceReferenceId))
            .limit(1);
          if (existing) {
            skipped.push({ sourceReferenceId, existingChargeId: existing.id, reason: "CHARGE_ALREADY_EXISTS" });
            continue;
          }
        } else if (sourceId && sourceType) {
          // Fallback guard
          const [existing] = await db.select({ id: billableCharges.id })
            .from(billableCharges)
            .where(and(eq(billableCharges.sourceId, sourceId), eq(billableCharges.sourceType, sourceType)))
            .limit(1);
          if (existing) {
            skipped.push({ sourceId, existingChargeId: existing.id, reason: "CHARGE_ALREADY_EXISTS" });
            continue;
          }
        }
        try {
          const charge = await storage.createBillableCharge({ ...item, createdBy: req.user.claims.sub });
          created.push(charge);
        } catch (itemErr: any) {
          if (itemErr.code === "23505" && itemErr.constraint === "billable_charges_source_ref_uniq") {
            skipped.push({ sourceReferenceId, existingChargeId: "unknown", reason: "CHARGE_ALREADY_EXISTS" });
          } else {
            throw itemErr; // re-throw unexpected errors
          }
        }
      }
      res.json({ created, skipped, summary: { total: incoming.length, created: created.length, skipped: skipped.length } });
    } catch (error) {
      console.error("Error creating billable charges:", error);
      res.status(500).json({ message: "Failed to create billable charges" });
    }
  });

