  // Update allowed payment methods for a customer (with audit logging)
  app.put("/api/corporate/invoicing/payment-methods/:customerId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const invUser = { id: req.user.claims.sub, email: user?.email || "", role: user?.role };
      assertInvoicingPermission(invUser, 'billing_profile:edit', 'payment_method_update');
      const { customerId } = req.params;
      const { acceptsCreditCard, acceptsAch, acceptsCheck, acceptsWire, enforcePrepay, reason } = req.body;

      // At least one payment method must remain enabled
      const enabledCount = [acceptsCreditCard, acceptsAch, acceptsCheck, acceptsWire].filter(Boolean).length;
      if (enabledCount === 0 && !enforcePrepay) {
        return res.status(400).json({ message: "At least one payment method must be enabled, or enforce prepay must be on" });
      }

      // Get current settings for audit comparison
      const currentProfile = await storage.getCustomerBillingProfile(customerId);
      const currentSettings = {
        acceptsCreditCard: currentProfile?.acceptsCreditCard ?? true,
        acceptsAch: currentProfile?.acceptsAch ?? true,
        acceptsCheck: currentProfile?.acceptsCheck ?? true,
        acceptsWire: currentProfile?.acceptsWire ?? true,
        enforcePrepay: currentProfile?.enforcePrepay ?? false,
      };

      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() : 'Unknown';

      // Create audit log entries for each change
      const auditEntries: any[] = [];
      const methodMap: Record<string, { field: string; label: string }> = {
        acceptsCreditCard: { field: 'credit_card', label: 'Credit Card' },
        acceptsAch: { field: 'ach', label: 'ACH' },
        acceptsCheck: { field: 'check', label: 'Check' },
        acceptsWire: { field: 'wire', label: 'Wire' },
      };

      for (const [key, { field }] of Object.entries(methodMap)) {
        const newVal = req.body[key];
        const oldVal = (currentSettings as any)[key];
        if (newVal !== undefined && newVal !== oldVal) {
          auditEntries.push({
            customerId,
            changedBy: user!.id,
            changedByName: userName,
            changeType: newVal ? 'enabled' : 'disabled',
            paymentMethod: field,
            previousValue: oldVal,
            newValue: newVal,
            reason: reason || null,
          });
        }
      }

      if (enforcePrepay !== undefined && enforcePrepay !== currentSettings.enforcePrepay) {
        auditEntries.push({
          customerId,
          changedBy: user!.id,
          changedByName: userName,
          changeType: enforcePrepay ? 'enabled' : 'disabled',
          paymentMethod: 'prepay_enforcement',
          previousValue: currentSettings.enforcePrepay,
          newValue: enforcePrepay,
          reason: reason || null,
        });
      }

      // Update billing profile
      const updateData: any = {};
      if (acceptsCreditCard !== undefined) updateData.acceptsCreditCard = acceptsCreditCard;
      if (acceptsAch !== undefined) updateData.acceptsAch = acceptsAch;
      if (acceptsCheck !== undefined) updateData.acceptsCheck = acceptsCheck;
      if (acceptsWire !== undefined) updateData.acceptsWire = acceptsWire;
      if (enforcePrepay !== undefined) updateData.enforcePrepay = enforcePrepay;

      let profile;
      if (currentProfile) {
        profile = await storage.updateCustomerBillingProfile(customerId, updateData);
      } else {
        profile = await storage.createCustomerBillingProfile({
          customerId,
          ...updateData,
        });
      }

      // Insert audit entries
      if (auditEntries.length > 0) {
        await db.insert(paymentMethodAuditLog).values(auditEntries);
      }

      await storage.logInvoicingAction({
        userId: req.user.claims.sub,
        action: "payment_method_update",
        resourceType: "payment_method",
        resourceId: customerId,
        details: { changes: auditEntries.map(e => ({ method: e.paymentMethod, changeType: e.changeType })) },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });

      res.json({
        customerId,
        acceptsCreditCard: profile?.acceptsCreditCard ?? true,
        acceptsAch: profile?.acceptsAch ?? true,
        acceptsCheck: profile?.acceptsCheck ?? true,
        acceptsWire: profile?.acceptsWire ?? true,
        enforcePrepay: profile?.enforcePrepay ?? false,
        changesLogged: auditEntries.length,
      });
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error updating payment methods:", error);
      res.status(500).json({ message: "Failed to update payment methods" });
    }
  });

