  // ==========================================
  // CREDIT EXPOSURE & LIMIT ENFORCEMENT
  // ==========================================

  app.get("/api/corporate/invoicing/credit-exposure/:customerId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const customerId = req.params.customerId;
      const billingProfile = await storage.getCustomerBillingProfile(customerId);
      const creditLimit = billingProfile?.creditLimit ? parseFloat(billingProfile.creditLimit) : null;
      const enforcePrepay = billingProfile?.enforcePrepay || false;
      const creditLimitAction = billingProfile?.creditLimitAction || 'warn';

      const unpaidInvoices = await db.select({
        id: invoices.id,
        invoiceNumber: invoices.invoiceNumber,
        balanceDue: invoices.balanceDue,
        totalAmount: invoices.totalAmount,
        status: invoices.status,
        dueDate: invoices.dueDate,
      })
      .from(invoices)
      .where(and(
        eq(invoices.customerId, customerId),
        or(
          eq(invoices.status, 'sent'),
          eq(invoices.status, 'overdue'),
          eq(invoices.status, 'partial')
        )
      ));

      const totalExposure = unpaidInvoices.reduce((sum, inv) => {
        return sum + parseFloat(inv.balanceDue || inv.totalAmount || '0');
      }, 0);

      const isOverLimit = creditLimit !== null && totalExposure > creditLimit;
      const availableCredit = creditLimit !== null ? Math.max(0, creditLimit - totalExposure) : null;

      res.json({
        customerId,
        creditLimit,
        enforcePrepay,
        creditLimitAction,
        totalExposure: parseFloat(totalExposure.toFixed(2)),
        isOverLimit,
        availableCredit: availableCredit !== null ? parseFloat(availableCredit.toFixed(2)) : null,
        unpaidInvoiceCount: unpaidInvoices.length,
      });
    } catch (error) {
      console.error("Error calculating credit exposure:", error);
      res.status(500).json({ message: "Failed to calculate credit exposure" });
    }
  });

  app.post("/api/corporate/invoicing/credit-override", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!user || !['admin', 'finance', 'super_user'].includes(user.role || '')) {
        return res.status(403).json({ message: "Forbidden: Only admin or finance can override credit limits" });
      }
      const { invoiceId, customerId, reason } = req.body;
      if (!invoiceId || !customerId || !reason) {
        return res.status(400).json({ message: "invoiceId, customerId, and reason are required" });
      }
      const billingProfile = await storage.getCustomerBillingProfile(customerId);
      const creditLimit = billingProfile?.creditLimit ? parseFloat(billingProfile.creditLimit) : null;
      const unpaidResult = await db.select({ total: sql`COALESCE(SUM(COALESCE(CAST(balance_due AS numeric), CAST(total_amount AS numeric))), 0)` })
        .from(invoices)
        .where(and(
          eq(invoices.customerId, customerId),
          or(eq(invoices.status, 'sent'), eq(invoices.status, 'overdue'), eq(invoices.status, 'partial'))
        ));
      const exposure = parseFloat((unpaidResult[0] as any)?.total || '0');
      const userName = `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || 'Unknown';
      const [override] = await db.insert(creditLimitOverrides).values({
        invoiceId,
        customerId,
        overriddenBy: req.user.claims.sub,
        overriddenByName: userName,
        reason,
        creditLimitAtTime: creditLimit?.toString() || null,
        exposureAtTime: exposure.toFixed(2),
      }).returning();
      res.json(override);
    } catch (error) {
      console.error("Error creating credit override:", error);
      res.status(500).json({ message: "Failed to create credit override" });
    }
  });

