  // GET /api/corporate/invoicing/invoices/:id/pdf — Download branded PDF (admin)
  app.get("/api/corporate/invoicing/invoices/:id/pdf", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const invoice = await storage.getInvoiceWithLineItems(req.params.id);
      if (!invoice) return res.status(404).json({ message: "Invoice not found" });

      const lineItems = await db.select().from(invoiceLineItems).where(eq(invoiceLineItems.invoiceId, invoice.id)).orderBy(asc(invoiceLineItems.lineNumber));
      let billingEntity = null;
      if (invoice.billingEntityId) billingEntity = await storage.getBillingEntity(invoice.billingEntityId);

      // Try to fetch logo
      let logoBuffer: Buffer | null = null;
      if (billingEntity?.logoUrl) {
        try {
          const sp = getStorageProvider();
          if (sp === "s3") {
            logoBuffer = await getS3StorageService().downloadByKey(billingEntity.logoUrl).catch(() => null);
          } else {
            const { Client: RC } = await import("@replit/object-storage");
            const rc = new RC({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID! });
            const r2 = await rc.downloadAsBytes(billingEntity.logoUrl);
            if (r2.ok && r2.value) logoBuffer = Buffer.from(r2.value);
          }
        } catch { /* skip */ }
      }

      const proto   = req.headers["x-forwarded-proto"] || "https";
      const host    = req.headers["x-forwarded-host"] || req.headers.host || "driverondemand.co";
      const appBase = `${proto}://${host}`;

      const pdfBuf = await generateInvoicePdf({
        invoiceNumber:      invoice.invoiceNumber,
        invoiceDate:        invoice.invoiceDate  ? String(invoice.invoiceDate)  : "",
        dueDate:            invoice.dueDate      ? String(invoice.dueDate)      : "",
        customerName:       invoice.customerName || "Customer",
        customerMemo:       invoice.customerMemo,
        status:             invoice.status,
        subtotalAmount:     invoice.subtotalAmount ?? invoice.totalAmount,
        taxAmount:          invoice.taxAmount,
        totalAmount:        invoice.totalAmount,
        paidAmount:         invoice.paidAmount,
        balanceDue:         invoice.balanceDue   ?? invoice.totalAmount,
        paymentAccessToken: invoice.paymentAccessToken,
        lineItems: lineItems.map(li => ({
          description:   li.description || "Service",
          quantity:      li.quantity    ?? 1,
          unitPrice:     li.unitPrice   ?? li.totalPrice ?? 0,
          totalPrice:    li.totalPrice  ?? 0,
          dateOfService: li.dateOfService ? String(li.dateOfService) : null,
        })),
        billingEntity: billingEntity ? {
          legalName:              billingEntity.legalName,
          dbaName:                billingEntity.dbaName,
          taxId:                  billingEntity.taxId,
          phone:                  billingEntity.phone,
          email:                  billingEntity.email,
          website:                billingEntity.website,
          addressLine1:           billingEntity.addressLine1,
          city:                   billingEntity.city,
          state:                  billingEntity.state,
          postalCode:             billingEntity.postalCode,
          remitAddressLine1:      billingEntity.remitAddressLine1,
          remitCity:              billingEntity.remitCity,
          remitState:             billingEntity.remitState,
          remitPostalCode:        billingEntity.remitPostalCode,
          primaryColor:           billingEntity.primaryColor,
          logoBuffer,
          footerNotes:            billingEntity.footerNotes,
          remittanceInstructions: billingEntity.remittanceInstructions,
          defaultTermsText:       billingEntity.defaultTermsText,
        } : null,
        appBaseUrl: appBase,
        w9Url: `${appBase}/api/public/billing-documents/w9/download`,
      });

      res.setHeader("Content-Type",        "application/pdf");
      res.setHeader("Content-Disposition", `attachment; filename="Invoice-${invoice.invoiceNumber}.pdf"`);
      res.setHeader("Content-Length",      String(pdfBuf.length));
      res.setHeader("Cache-Control",       "no-store");
      res.send(pdfBuf);
    } catch (err) {
      console.error("[InvoicePDF] admin download error:", err);
      res.status(500).json({ message: "Failed to generate invoice PDF" });
    }
  });

  // ─── Invoice Charge Groups (Revenue Engine grouping) ─────────────────────────
  // Returns billable_charges linked to an invoice, grouped by revenue_category.
  // Only populated for invoices created by the Revenue Engine (run-weekly).
  // Manual invoices use invoice_lines instead and will return an empty groups array.
  app.get("/api/corporate/invoicing/invoices/:id/charge-groups", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const invoiceId = req.params.id;

      const rows = await db.execute(sql`
        SELECT
          bc.id,
          bc.description,
          bc.source_type,
          bc.source_reference_id,
          bc.charge_date::text AS charge_date,
          bc.product_type_snapshot,
          bc.billing_frequency_snapshot,
          bc.quantity::numeric      AS quantity,
          bc.unit_rate::numeric     AS unit_rate,
          bc.amount::numeric        AS amount,
          bc.revenue_category,
          bc.notes,
          p.name                    AS product_name
        FROM billable_charges bc
        LEFT JOIN products p ON p.id = bc.product_id
        WHERE bc.invoice_id = ${invoiceId}
          AND bc.billing_status != 'voided'
        ORDER BY bc.revenue_category, bc.charge_date, bc.created_at
      `);
      const charges = ((rows as any).rows ?? rows) as any[];

      if (charges.length === 0) {
        return res.json({ invoiceId, totalAmount: 0, chargeCount: 0, groups: [] });
      }

      // Canonical category order — ticket requires: Labor, Moves, Rideshare, Fees
      const CATEGORY_DEFS = [
        { key: "labor",     label: "Labor",     matches: ["labor"],                          quantityLabel: "hrs"   },
        { key: "moves",     label: "Moves",     matches: ["moves"],                          quantityLabel: "moves" },
        { key: "rideshare", label: "Rideshare", matches: ["rideshare"],                      quantityLabel: "trips" },
        { key: "fees",      label: "Fees",      matches: ["fees", "insurance", "technology"], quantityLabel: null   },
        { key: "other",     label: "Other",     matches: ["other"],                           quantityLabel: null   },
      ];

      // Bucket charges into category groups
      const groupMap: Record<string, any[]> = {};
      for (const charge of charges) {
        const raw = charge.revenue_category || "other";
        const def = CATEGORY_DEFS.find(d => d.matches.includes(raw)) ?? CATEGORY_DEFS[4];
        if (!groupMap[def.key]) groupMap[def.key] = [];
        groupMap[def.key].push(charge);
      }

      const groups = CATEGORY_DEFS
        .filter(def => (groupMap[def.key]?.length ?? 0) > 0)
        .map(def => {
          const gc = groupMap[def.key];
          const totalAmount   = gc.reduce((s: number, c: any) => s + parseFloat(c.amount    || "0"), 0);
          const totalQuantity = def.quantityLabel
            ? gc.reduce((s: number, c: any) => s + parseFloat(c.quantity || "0"), 0)
            : null;
          return {
            category: def.key,
            label: def.label,
            chargeCount: gc.length,
            totalAmount,
            totalQuantity,
            quantityLabel: def.quantityLabel,
            charges: gc.map((c: any) => ({
              id: c.id,
              description: c.description,
              productName: c.product_name,
              sourceType: c.source_type,
              sourceReferenceId: c.source_reference_id,
              chargeDate: c.charge_date,
              productType: c.product_type_snapshot,
              billingFrequency: c.billing_frequency_snapshot,
              quantity: parseFloat(c.quantity || "0"),
              unitRate: parseFloat(c.unit_rate || "0"),
              amount: parseFloat(c.amount || "0"),
              notes: c.notes,
            })),
          };
        });

      const totalAmount = charges.reduce((s: number, c: any) => s + parseFloat(c.amount || "0"), 0);
      res.json({ invoiceId, totalAmount, chargeCount: charges.length, groups });
    } catch (e: any) {
      console.error("Error fetching invoice charge groups:", e);
      res.status(500).json({ message: e.message });
    }
  });

