  // ─── Invoice Preview Data ─────────────────────────────────────────────────────
  // Combined payload: invoice + line items + charge groups + client-ready validation issues.
  // Powers the Invoice Preview Screen (read-only PDF-matching render).
  app.get("/api/corporate/invoicing/invoices/:id/preview-data", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const invoiceId = req.params.id;

      // ── Invoice + line items ────────────────────────────────────────────────
      const invoice = await storage.getInvoiceWithLineItems(invoiceId);
      if (!invoice) return res.status(404).json({ message: "Invoice not found" });

      // ── Charge groups (Revenue Engine grouped charges) ──────────────────────
      const chargeRows = await db.execute(sql`
        SELECT
          bc.id, bc.description, bc.source_type, bc.source_reference_id,
          bc.charge_date::text AS charge_date, bc.service_type,
          bc.quantity::numeric  AS quantity,
          bc.unit_rate::numeric AS unit_rate,
          bc.amount::numeric    AS amount,
          bc.revenue_category, bc.notes,
          p.name AS product_name
        FROM billable_charges bc
        LEFT JOIN products p ON p.id = bc.product_id
        WHERE bc.invoice_id = ${invoiceId}
          AND bc.billing_status != 'voided'
        ORDER BY bc.revenue_category, bc.charge_date, bc.created_at
      `);
      const charges = ((chargeRows as any).rows ?? chargeRows) as any[];

      const CATEGORY_DEFS = [
        { key: "labor",     label: "Labor",     matches: ["labor"],                           quantityLabel: "hrs"   },
        { key: "moves",     label: "Moves",     matches: ["moves"],                           quantityLabel: "moves" },
        { key: "rideshare", label: "Rideshare", matches: ["rideshare"],                       quantityLabel: "trips" },
        { key: "fees",      label: "Fees",      matches: ["fees", "insurance", "technology"], quantityLabel: null    },
        { key: "other",     label: "Other",     matches: ["other"],                           quantityLabel: null    },
      ];
      const groupMap: Record<string, any[]> = {};
      for (const c of charges) {
        const raw = c.revenue_category || "other";
        const def = CATEGORY_DEFS.find(d => d.matches.includes(raw)) ?? CATEGORY_DEFS[4];
        if (!groupMap[def.key]) groupMap[def.key] = [];
        groupMap[def.key].push(c);
      }
      const chargeGroups = CATEGORY_DEFS
        .filter(def => (groupMap[def.key]?.length ?? 0) > 0)
        .map(def => {
          const gc = groupMap[def.key];
          return {
            category: def.key, label: def.label,
            chargeCount: gc.length,
            totalAmount: gc.reduce((s: number, c: any) => s + parseFloat(c.amount || "0"), 0),
            totalQuantity: def.quantityLabel ? gc.reduce((s: number, c: any) => s + parseFloat(c.quantity || "0"), 0) : null,
            quantityLabel: def.quantityLabel,
            charges: gc.map((c: any) => ({
              id: c.id, description: c.description, productName: c.product_name,
              sourceType: c.source_type, chargeDate: c.charge_date, serviceType: c.service_type,
              quantity: parseFloat(c.quantity || "0"), unitRate: parseFloat(c.unit_rate || "0"),
              amount: parseFloat(c.amount || "0"), notes: c.notes,
            })),
          };
        });

      // ── Line item grouping by category (for invoice_line_items based invoices) ─
      const lineItemCategoryMap: Record<string, { label: string; items: any[]; total: number }> = {};
      const CAT_ORDER = ["service", "fee", "mileage", "surcharge", "late_fee", "bad_debt", "other"];
      const CAT_LABELS: Record<string, string> = {
        service: "Services", fee: "Fees", mileage: "Mileage", surcharge: "Surcharges",
        late_fee: "Late Fees", bad_debt: "Write-offs / Bad Debt", other: "Other",
      };
      for (const li of (invoice.lineItems ?? [])) {
        const cat = li.category ?? "other";
        if (!lineItemCategoryMap[cat]) lineItemCategoryMap[cat] = { label: CAT_LABELS[cat] ?? cat, items: [], total: 0 };
        lineItemCategoryMap[cat].items.push(li);
        lineItemCategoryMap[cat].total += parseFloat(li.totalPrice ?? "0");
      }
      const lineItemGroups = CAT_ORDER
        .filter(c => lineItemCategoryMap[c]?.items.length)
        .map(c => ({ category: c, ...lineItemCategoryMap[c] }));

      // ── Allowed actions ─────────────────────────────────────────────────────
      const { getAllowedActions } = await import("./invoiceStateMachine");
      const allowedActions = getAllowedActions(invoice.status ?? "draft");

      // ── Validation ──────────────────────────────────────────────────────────
      type IssueSeverity = "error" | "warning" | "info";
      interface ValidationIssue { severity: IssueSeverity; code: string; message: string }
      const issues: ValidationIssue[] = [];

      const hasLineItems = (invoice.lineItems?.length ?? 0) > 0;
      const hasCharges = charges.length > 0;

      if (!hasLineItems && !hasCharges) {
        issues.push({ severity: "error", code: "NO_LINE_ITEMS", message: "Invoice has no line items. Add at least one billable item before sending." });
      }

      if (["cancelled", "void"].includes(invoice.status ?? "")) {
        issues.push({ severity: "error", code: "TERMINAL_STATUS", message: `This invoice is ${invoice.status} and cannot be sent.` });
      }

      const dueDate = invoice.dueDate ? new Date(invoice.dueDate + "T00:00:00") : null;
      if (dueDate && dueDate < new Date()) {
        issues.push({ severity: "warning", code: "DUE_DATE_PAST", message: `Due date (${invoice.dueDate}) is in the past. Update before sending.` });
      }

      if (!invoice.customerMemo) {
        issues.push({ severity: "info", code: "NO_MEMO", message: "No customer memo or payment instructions. Consider adding payment details." });
      }

      const zeroLines = (invoice.lineItems ?? []).filter((li: any) => parseFloat(li.totalPrice ?? "0") === 0);
      if (zeroLines.length > 0) {
        issues.push({ severity: "warning", code: "ZERO_AMOUNT_LINES", message: `${zeroLines.length} line item${zeroLines.length > 1 ? "s" : ""} with $0.00 amount — verify they are intentional.` });
      }

      const descriptions = (invoice.lineItems ?? []).map((li: any) => li.description?.trim().toLowerCase());
      const dupes = descriptions.filter((d: string, i: number) => d && descriptions.indexOf(d) !== i);
      if (dupes.length > 0) {
        issues.push({ severity: "warning", code: "DUPLICATE_DESCRIPTIONS", message: `${dupes.length} duplicate line item description${dupes.length > 1 ? "s" : ""} detected.` });
      }

      if (invoice.status === "draft") {
        issues.push({ severity: "info", code: "DRAFT_STATUS", message: "Invoice is in draft status. Approve before sending, or send directly from draft." });
      }

      if (!invoice.billingPeriodStart || !invoice.billingPeriodEnd) {
        issues.push({ severity: "info", code: "NO_BILLING_PERIOD", message: "No billing period specified on this invoice." });
      }

      const totalDiscrepancy = Math.abs(
        parseFloat(invoice.totalAmount ?? "0") -
        parseFloat(invoice.subtotalAmount ?? invoice.totalAmount ?? "0") -
        parseFloat(invoice.taxAmount ?? "0")
      );
      if (totalDiscrepancy > 0.02 && parseFloat(invoice.taxAmount ?? "0") === 0) {
        // Only flag if there's a genuine discrepancy that isn't explained by tax
      }

      const isValid = !issues.some(i => i.severity === "error");

      res.json({
        invoice,
        chargeGroups,
        lineItemGroups,
        allowedActions,
        validation: { isValid, issues },
      });
    } catch (e: any) {
      console.error("Preview data error:", e);
      res.status(500).json({ message: e.message });
    }
  });

  // Create invoice from approved charges (batch)
  app.post("/api/corporate/invoicing/invoices/from-charges", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      
      const { chargeIds, customerId, invoiceDate, dueDate, notes } = req.body;
      
      if (!chargeIds || chargeIds.length === 0) {
        return res.status(400).json({ message: "No charges selected" });
      }
      
      // Get all charges and validate they are approved and belong to same customer
      const charges = await Promise.all(chargeIds.map((id: string) => storage.getBillableCharge(id)));
      const validCharges = charges.filter(c => c !== undefined);
      
      if (validCharges.length === 0) {
        return res.status(400).json({ message: "No valid charges found" });
      }
      
      // Verify all charges belong to the same customer
      const chargeCustomerId = validCharges[0]?.customerId;
      if (!chargeCustomerId || validCharges.some(c => c?.customerId !== chargeCustomerId)) {
        return res.status(400).json({ message: "All charges must belong to the same customer" });
      }
      
      // Calculate totals
      const subtotal = validCharges.reduce((sum, c) => sum + parseFloat(c?.amount || '0'), 0);
      const customer = await storage.getCustomer(chargeCustomerId);
      
      // Use draft invoice number (real number assigned on send to avoid gaps)
      const { invoiceNumber, draftSequence } = await storage.generateDraftInvoiceNumber();
      
      // Create line items from charges
      const lineItems = validCharges.map((charge, index) => ({
        lineNumber: index + 1,
        serviceType: charge?.serviceType || 'other',
        description: charge?.description || 'Service',
        quantity: charge?.quantity || '1',
        unitPrice: charge?.unitRate || charge?.amount || '0',
        totalPrice: charge?.amount || '0',
        chargeId: charge?.id,
        sourceType: charge?.sourceType || 'manual',
        sourceId: charge?.sourceId,
        dateOfService: charge?.chargeDate,
      }));
      
      // Create invoice with line items
      const invoice = await storage.createInvoiceWithLineItems(
        {
          invoiceNumber,
          draftSequence,
          invoiceNumberFinalized: false,
          customerId: chargeCustomerId,
          customerName: customer?.customerName || 'Unknown',
          invoiceDate: invoiceDate || new Date().toISOString().split('T')[0],
          dueDate: dueDate || new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0],
          subtotalAmount: subtotal.toFixed(2),
          totalAmount: subtotal.toFixed(2),
          balanceDue: subtotal.toFixed(2),
          status: 'draft',
          internalNotes: notes,
          createdBy: req.user.claims.sub,
        },
        lineItems as any
      );
      
      // Update charges to mark them as invoiced
      for (const charge of validCharges) {
        if (charge) {
          await storage.updateBillableCharge(charge.id, { 
            status: 'invoiced',
            invoiceId: invoice.id,
          });
        }
      }
      
      res.json(invoice);
    } catch (error) {
      console.error("Error creating invoice from charges:", error);
      res.status(500).json({ message: "Failed to create invoice from charges" });
    }
  });


  // Create invoice with line items
  app.post("/api/corporate/invoicing/invoices", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      
      // Check invoicing permission
      if (!InvoicingPermissionChecks.canCreateDraft({ id: req.user.claims.sub, email: user?.email || "", role: user?.role })) {
        await storage.logInvoicingAction({
          userId: req.user.claims.sub,
          action: "invoice_create_draft_denied",
          resourceType: "invoice",
          resourceId: null,
          details: { reason: "Permission denied" },
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"] || null,
        });
        return res.status(403).json({ message: "Permission denied: Cannot create invoices" });
      }
      // Idempotency check for invoice creation
      const idempotencyKey = req.headers['x-idempotency-key'] || req.headers['idempotency-key'];
      if (idempotencyKey) {
        const requestHash = hashRequestBody(req.body);
        const idempResult = await checkIdempotency('invoice_create', idempotencyKey, requestHash, req.user.claims.sub);
        if (!idempResult.isNew && idempResult.cachedResponse) {
          console.log('[Idempotency] Returning cached response for invoice creation key:', idempotencyKey);
          return res.status(idempResult.cachedResponse.status).json(idempResult.cachedResponse.body);
        }
      }

      // Invoice duplicate prevention (bypass with force=true in body)
      if (req.body.customerId && req.body.totalAmount && req.body.invoiceDate && !req.body.force) {
        const invDupCheck = await checkInvoiceDuplicate({
          customerId: req.body.customerId,
          amount: req.body.totalAmount,
          invoiceDate: req.body.invoiceDate,
          referenceNumber: req.body.referenceNumber,
          poNumber: req.body.poNumber,
        });
        if (invDupCheck.isDuplicate) {
          if (idempotencyKey) await storage.finalizeIdempotencyKey('invoice_create', idempotencyKey, 409, { error_code: 'DUPLICATE_INVOICE' }).catch(() => {});
          return res.status(409).json({ error_code: 'DUPLICATE_INVOICE', message: invDupCheck.reason, duplicateId: invDupCheck.duplicateId, duplicateRef: invDupCheck.duplicateRef });
        }
        if (invDupCheck.isSoftDuplicate) {
          if (idempotencyKey) await storage.finalizeIdempotencyKey('invoice_create', idempotencyKey, 409, { error_code: 'SOFT_DUPLICATE_INVOICE' }).catch(() => {});
          return res.status(409).json({ error_code: 'SOFT_DUPLICATE_INVOICE', message: invDupCheck.reason, duplicateId: invDupCheck.duplicateId, duplicateRef: invDupCheck.duplicateRef, bypassable: true });
        }
      }

      // Use draft invoice number (real number assigned on send to avoid gaps)
      const { invoiceNumber, draftSequence } = await storage.generateDraftInvoiceNumber();
      const { lineItems, ...invoiceData } = req.body;
      const invoice = await storage.createInvoiceWithLineItems(
        {
          ...invoiceData,
          invoiceNumber,
          draftSequence,
          invoiceNumberFinalized: false,
          createdBy: req.user.claims.sub,
        },
        lineItems || []
      );

      // Send INVOICE_PREVIEW notification to customer if enabled
      if (invoice.customerId) {
        const customer = await storage.getCustomer(invoice.customerId);
        if (customer?.email && customer.contactUserId) {
          const totalAmount = invoice.totalAmount 
            ? `$${(Number(invoice.totalAmount) / 100).toFixed(2)}` 
            : '$0.00';
          const dueDate = invoice.dueDate 
            ? new Date(invoice.dueDate).toLocaleDateString()
            : 'Not set';
          
          sendCustomerNotificationIfEnabled(
            customer.contactUserId,
            'INVOICE_PREVIEW',
            () => sendInvoicePreviewNotification({
              to: customer.email!,
              customerName: customer.name || 'Customer',
              invoiceNumber: invoice.invoiceNumber || invoice.id,
              totalAmount,
              dueDate,
            })
          );
        }
      }

      // Finalize idempotency key on success
      if (idempotencyKey) {
        await storage.finalizeIdempotencyKey('invoice_create', idempotencyKey, 200, invoice, invoice.id);
      }

      writeFinancialAuditEvent({
        eventType: 'invoice.created',
        actorUserId: req.user.claims.sub,
        actorUserEmail: user?.email ?? null,
        actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
        targetEntityType: 'invoice',
        targetEntityId: invoice.id,
        targetEntityLabel: invoice.invoiceNumber,
        newValue: { invoiceNumber: invoice.invoiceNumber, totalAmount: invoice.totalAmount, customerId: invoice.customerId, status: invoice.status, invoiceDate: invoice.invoiceDate, dueDate: invoice.dueDate },
        ipAddress: req.ip,
      }).catch(() => {});

      res.json(invoice);
    } catch (error) {
      console.error("Error creating invoice:", error);
      if (idempotencyKey) {
        try { await storage.finalizeIdempotencyKey('invoice_create', idempotencyKey, 500, { message: 'Failed to create invoice' }); } catch (e) {}
      }
      res.status(500).json({ message: "Failed to create invoice" });
    }
  });

  // Clone invoice - copy header + line items, reset dates/status/payments

  // ─── QB Desktop IIF Export ───────────────────────────────────────────────────
  // GET /api/corporate/invoicing/invoices/:id/export-iif
  // Generates and downloads a QuickBooks Desktop IIF file for a single invoice.
  // Enforces GL mapping requirements per accounting_settings.
  // Logs export attempt to export_logs table.
  app.get("/api/corporate/invoicing/invoices/:id/export-iif", isAuthenticated, async (req: any, res: Response) => {
    const userId = (req as any).user?.id || (req as any).user?.claims?.sub;
    let logId: string | null = null;
    try {
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ error_code: "UNAUTHENTICATED", message: "Not authenticated" });
      const allowed = ['super_user','super_admin','admin','finance','ops_manager','corporate_admin'];
      if (!allowed.includes(user.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance or admin role required" });

      const [inv] = await db.select().from(invoices).where(eq(invoices.id, req.params.id));
      if (!inv) return res.status(404).json({ error_code: "NOT_FOUND", message: "Invoice not found" });
      if (!['approved','exported','sent','viewed','partially_paid','paid'].includes(inv.status || '')) {
        return res.status(422).json({ error_code: "APPROVAL_REQUIRED", message: "Invoice must be approved before exporting to QuickBooks Desktop." });
      }

      // Create pending export log
      const [logRow] = await db.insert(exportLogs).values({
        exportType: 'ar_invoice_iif',
        exportFormat: 'iif',
        status: 'pending',
        invoiceId: req.params.id,
        requestedBy: userId,
        startedAt: new Date(),
        filterParams: { invoiceId: req.params.id, invoiceNumber: inv.invoiceNumber },
        createdBy: userId,
        updatedBy: userId,
      }).returning();
      logId = logRow.id;

      // Fetch invoice lines
      const lines = await db.select().from(invoiceLines).where(eq(invoiceLines.invoiceId, req.params.id)).orderBy(invoiceLines.sortOrder);

      // Fetch accounting settings for enforcement + AR account
      const [acctSettings] = await db.select().from(accountingSettings);
      const requireMapping = acctSettings?.requireMappingBeforeExport || false;
      const routeToSuspense = acctSettings?.routeUnmappedToSuspense || false;

      // Resolve suspense income account if configured
      let suspenseCode: string | null = null;
      if (routeToSuspense && acctSettings?.suspenseIncomeAccountId) {
        const [suspenseAcct] = await db.select().from(accountRegistry).where(eq(accountRegistry.id, acctSettings.suspenseIncomeAccountId));
        if (suspenseAcct) suspenseCode = suspenseAcct.accountCode;
      }

      // Build IIF line items, applying suspense routing for unmapped lines
      const { validateIifMappings, buildIifContent } = await import('./services/iifExportService.js');
      const iifLines = lines.map(l => ({
        description: l.description,
        quantity: l.quantity,
        unitPrice: l.unitPrice,
        totalAmount: l.totalAmount,
        incomeAccountCode: l.incomeAccountCode || l.glCode || suspenseCode,
        taxCode: l.taxCode,
        classCode: l.classCode,
        productName: l.description,
      }));

      const validationErrors = validateIifMappings(inv.invoiceNumber || inv.id, iifLines, requireMapping);
      if (validationErrors.length > 0) {
        await db.update(exportLogs).set({ status: 'failed', errorMessage: validationErrors.join('; '), completedAt: new Date(), updatedBy: userId, updatedAt: new Date() }).where(eq(exportLogs.id, logId));
        return res.status(422).json({ error_code: "UNMAPPED_LINES", message: validationErrors[0], errors: validationErrors });
      }

      // Resolve AR account
      let arAccountCode = 'Accounts Receivable';
      if (acctSettings?.defaultArAccountId) {
        const [arAcct] = await db.select().from(accountRegistry).where(eq(accountRegistry.id, acctSettings.defaultArAccountId));
        if (arAcct) arAccountCode = arAcct.accountCode;
      }

      const iifInvoice = {
        invoiceNumber: inv.invoiceNumber || inv.id,
        invoiceDate: inv.invoiceDate ? new Date(inv.invoiceDate).toLocaleDateString('en-US') : new Date(inv.createdAt).toLocaleDateString('en-US'),
        dueDate: inv.dueDate ? new Date(inv.dueDate).toLocaleDateString('en-US') : '',
        customerName: inv.customerName || '',
        totalAmount: inv.totalAmount || '0',
        arAccountCode,
        memo: inv.customerMemo,
        lines: iifLines,
      };

      const iifContent = buildIifContent([iifInvoice]);
      const filename = `invoice-${(inv.invoiceNumber || inv.id).replace(/[^a-zA-Z0-9-_]/g, '_')}.iif`;
      const fileReference = `exports/iif/${logId}/${filename}`;

      // Update export log as completed
      await db.update(exportLogs).set({
        status: 'completed',
        fileUrl: fileReference,
        recordCount: 1,
        completedAt: new Date(),
        updatedBy: userId,
        updatedAt: new Date(),
      }).where(eq(exportLogs.id, logId));

      res.setHeader('Content-Type', 'text/plain; charset=utf-8');
      res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
      res.setHeader('Content-Length', Buffer.byteLength(iifContent, 'utf8'));
      res.send(iifContent);
    } catch (e: any) {
      if (logId) {
        await db.update(exportLogs).set({ status: 'failed', errorMessage: e.message, completedAt: new Date(), updatedBy: userId, updatedAt: new Date() }).where(eq(exportLogs.id, logId)).catch(() => {});
      }
      res.status(500).json({ error_code: "INTERNAL_ERROR", message: e.message });
    }
  });

  // GET /api/corporate/invoicing/invoices/:id/export-logs — fetch export logs for a single invoice
  app.get("/api/corporate/invoicing/invoices/:id/export-logs", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req as any).user?.id || (req as any).user?.claims?.sub;
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ error_code: "UNAUTHENTICATED", message: "Not authenticated" });
      const rows = await db.select().from(exportLogs)
        .where(eq(exportLogs.invoiceId, req.params.id))
        .orderBy(desc(exportLogs.createdAt))
        .limit(50);
      res.json(rows);
    } catch (e: any) { res.status(500).json({ error_code: "INTERNAL_ERROR", message: e.message }); }
  });


  // ─── AR Lifecycle: Approve & Export ──────────────────────────────────────────
  // POST /api/corporate/invoicing/invoices/:id/approve
  // Moves invoice from draft → approved. Requires finance or admin role.
  app.post("/api/corporate/invoicing/invoices/:id/approve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req as any).user?.id || (req as any).user?.claims?.sub;
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ error_code: "UNAUTHENTICATED", message: "Not authenticated" });
      const allowed = ['super_user','super_admin','admin','finance','ops_manager','corporate_admin'];
      if (!allowed.includes(user.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance or admin role required to approve invoices" });
      const [inv] = await db.select().from(invoices).where(eq(invoices.id, req.params.id));
      if (!inv) return res.status(404).json({ error_code: "NOT_FOUND", message: "Invoice not found" });
      if (inv.status === 'void') return res.status(422).json({ error_code: "INVALID_STATUS", message: "Cannot approve a voided invoice" });
      if (inv.status === 'approved') return res.json(inv); // idempotent
      const { notes } = req.body || {};
      const [updated] = await db.update(invoices)
        .set({
          status: 'approved',
          approvedBy: userId,
          approvedAt: new Date(),
          approvalWorkflowState: 'approved',
          updatedBy: userId,
          updatedAt: new Date(),
          ...(notes ? { internalNotes: (inv.internalNotes ? inv.internalNotes + '\n' : '') + `[AR Approved] ${notes}` } : {}),
        })
        .where(eq(invoices.id, req.params.id))
        .returning();
      res.json(updated);
    } catch (e: any) { res.status(500).json({ error_code: "INTERNAL_ERROR", message: e.message }); }
  });

  // POST /api/corporate/invoicing/invoices/:id/export
  // Moves invoice from approved → exported. Blocked if not approved.
  // Applies suspense routing if accounting settings require it.
  app.post("/api/corporate/invoicing/invoices/:id/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = (req as any).user?.id || (req as any).user?.claims?.sub;
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ error_code: "UNAUTHENTICATED", message: "Not authenticated" });
      const allowed = ['super_user','super_admin','admin','finance'];
      if (!allowed.includes(user.role)) return res.status(403).json({ error_code: "FORBIDDEN", message: "Finance or admin role required to export invoices" });
      const [inv] = await db.select().from(invoices).where(eq(invoices.id, req.params.id));
      if (!inv) return res.status(404).json({ error_code: "NOT_FOUND", message: "Invoice not found" });
      if (inv.status === 'void') return res.status(422).json({ error_code: "INVALID_STATUS", message: "Cannot export a voided invoice" });
      if (inv.status !== 'approved') {
        return res.status(422).json({ error_code: "APPROVAL_REQUIRED", message: "Invoice must be approved before it can be exported. Current status: " + inv.status });
      }
      // Check accounting settings for mapping enforcement
      const [acctSettings] = await db.select().from(accountingSettings);
      if (acctSettings?.requireMappingBeforeExport) {
        const lines = await db.select().from(invoiceLines).where(eq(invoiceLines.invoiceId, req.params.id));
        const unmapped = lines.filter(l => !l.incomeAccountCode && !l.glCode);
        if (unmapped.length > 0) {
          // Apply suspense routing if configured, else block
          if (acctSettings.routeUnmappedToSuspense && acctSettings.suspenseIncomeAccountId) {
            const [suspenseAcct] = await db.select().from(accountRegistry).where(eq(accountRegistry.id, acctSettings.suspenseIncomeAccountId));
            if (suspenseAcct) {
              for (const line of unmapped) {
                await db.update(invoiceLines)
                  .set({ incomeAccountCode: suspenseAcct.accountCode, updatedBy: userId, updatedAt: new Date() })
                  .where(eq(invoiceLines.id, line.id));
              }
            }
          } else {
            return res.status(422).json({
              error_code: "UNMAPPED_LINES",
              message: `${unmapped.length} invoice line(s) are missing GL account mappings. Assign income account codes before exporting.`,
              unmappedCount: unmapped.length,
            });
          }
        }
      }
      const [updated] = await db.update(invoices)
        .set({ status: 'exported', updatedBy: userId, updatedAt: new Date() })
        .where(eq(invoices.id, req.params.id))
        .returning();
      res.json(updated);
    } catch (e: any) { res.status(500).json({ error_code: "INTERNAL_ERROR", message: e.message }); }
  });

  app.post("/api/corporate/invoicing/invoices/:id/clone", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      if (!InvoicingPermissionChecks.canCreateDraft({ id: req.user.claims.sub, email: user?.email || "", role: user?.role })) {
        return res.status(403).json({ message: "Permission denied: Cannot create invoices" });
      }

      const sourceInvoice = await storage.getInvoice(req.params.id);
      if (!sourceInvoice) {
        return res.status(404).json({ message: "Source invoice not found" });
      }

      const sourceLineItems = await storage.getInvoiceLineItems(req.params.id);
      const { invoiceNumber, draftSequence } = await storage.generateDraftInvoiceNumber();
      const today = new Date().toISOString().split('T')[0];
      const dueDate = new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

      const clonedInvoice = await storage.createInvoiceWithLineItems(
        {
          invoiceNumber,
          draftSequence,
          invoiceNumberFinalized: false,
          customerId: sourceInvoice.customerId,
          customerName: sourceInvoice.customerName,
          invoiceDate: today,
          dueDate,
          billingEntityId: sourceInvoice.billingEntityId,
          locationId: sourceInvoice.locationId,
          billingPeriodStart: null,
          billingPeriodEnd: null,
          paymentTerms: sourceInvoice.paymentTerms,
          subtotalAmount: sourceInvoice.subtotalAmount,
          taxAmount: sourceInvoice.taxAmount,
          feesAmount: sourceInvoice.feesAmount,
          totalAmount: sourceInvoice.totalAmount || '0',
          paidAmount: '0.00',
          creditApplied: '0.00',
          balanceDue: sourceInvoice.totalAmount,
          currency: sourceInvoice.currency,
          status: 'draft',
          poNumber: sourceInvoice.poNumber,
          referenceNumber: null,
          customerMemo: sourceInvoice.customerMemo,
          internalNotes: `Cloned from invoice ${sourceInvoice.invoiceNumber}`,
          notes: sourceInvoice.notes,
          createdBy: req.user.claims.sub,
          termsText: sourceInvoice.termsText,
          footerNotes: sourceInvoice.footerNotes,
          remittanceInstructions: sourceInvoice.remittanceInstructions,
        },
        sourceLineItems.map(item => ({
          invoiceId: '',
          lineNumber: item.lineNumber,
          lineItemType: item.lineItemType,
          category: item.category as any,
          serviceType: item.serviceType,
          description: item.description,
          quantity: item.quantity,
          unitPrice: item.unitPrice,
          totalPrice: item.totalPrice,
          isTaxable: item.isTaxable,
          taxRate: item.taxRate,
          taxAmount: item.taxAmount,
          dateOfService: null,
          jobReference: item.jobReference,
          notes: item.notes,
        }))
      );

      await storage.createInvoiceActivity({
        invoiceId: clonedInvoice.id,
        activityType: 'created',
        description: `Invoice cloned from ${sourceInvoice.invoiceNumber}`,
        performedBy: req.user.claims.sub,
        metadata: { sourceInvoiceId: sourceInvoice.id, sourceInvoiceNumber: sourceInvoice.invoiceNumber },
      });

      res.json(clonedInvoice);
    } catch (error) {
      console.error("Error cloning invoice:", error);
      res.status(500).json({ message: "Failed to clone invoice" });
    }
  });


