  // Bulk send invoices
  app.post("/api/corporate/invoicing/invoices/bulk-send", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      if (!InvoicingPermissionChecks.canSend({ id: req.user.claims.sub, email: user?.email || "", role: user?.role })) {
        return res.status(403).json({ message: "Permission denied: Cannot send invoices" });
      }

      const { invoiceIds } = req.body;
      if (!Array.isArray(invoiceIds) || invoiceIds.length === 0) {
        return res.status(400).json({ message: "No invoice IDs provided" });
      }

      const results: { invoiceId: string; invoiceNumber: string; success: boolean; error?: string }[] = [];

      for (const invoiceId of invoiceIds) {
        try {
          const [existingInvoice] = await db.select().from(invoices).where(eq(invoices.id, invoiceId)).limit(1);
          if (!existingInvoice) {
            results.push({ invoiceId, invoiceNumber: '', success: false, error: 'Invoice not found' });
            continue;
          }
          if (existingInvoice.status !== 'draft') {
            results.push({ invoiceId, invoiceNumber: existingInvoice.invoiceNumber, success: false, error: `Cannot send: status is ${existingInvoice.status}` });
            continue;
          }
          const approvalState = existingInvoice.approvalWorkflowState || 'draft';
          if (approvalState !== 'approved' && !['admin', 'finance'].includes(user?.role || '')) {
            results.push({ invoiceId, invoiceNumber: existingInvoice.invoiceNumber, success: false, error: 'Invoice must be approved before sending' });
            continue;
          }

          if (existingInvoice.customerId) {
            const billingProfile = await storage.getCustomerBillingProfile(existingInvoice.customerId);
            const bulkCreditLimit = billingProfile?.creditLimit ? parseFloat(billingProfile.creditLimit) : null;
            const bulkCreditLimitAction = billingProfile?.creditLimitAction || 'warn';
            if (bulkCreditLimit !== null && bulkCreditLimitAction === 'block') {
              const unpaidResult = await db.select({ total: sql`COALESCE(SUM(COALESCE(CAST(balance_due AS numeric), CAST(total_amount AS numeric))), 0)` })
                .from(invoices)
                .where(and(
                  eq(invoices.customerId, existingInvoice.customerId),
                  or(eq(invoices.status, 'sent'), eq(invoices.status, 'overdue'), eq(invoices.status, 'partial'))
                ));
              const bulkCurrentExposure = parseFloat((unpaidResult[0] as any)?.total || '0');
              const bulkInvoiceAmount = parseFloat(existingInvoice.totalAmount || '0');
              const bulkProjectedExposure = bulkCurrentExposure + bulkInvoiceAmount;
              if (bulkProjectedExposure > bulkCreditLimit) {
                const hasOverride = await db.select()
                  .from(creditLimitOverrides)
                  .where(eq(creditLimitOverrides.invoiceId, invoiceId))
                  .limit(1);
                if (hasOverride.length === 0) {
                  results.push({ invoiceId, invoiceNumber: existingInvoice.invoiceNumber, success: false, error: 'Credit limit exceeded — override required' });
                  continue;
                }
              }
            }
          }

          let customerEmail = '';
          if (existingInvoice.customerId) {
            const [customer] = await db.select().from(customers).where(eq(customers.id, existingInvoice.customerId)).limit(1);
            if (customer) {
              customerEmail = customer.billingEmail || customer.email || '';
            }
          }

          let paymentAccessToken = existingInvoice.paymentAccessToken;
          if (!paymentAccessToken) {
            const tokenResult = await db.execute(sql`SELECT replace(gen_random_uuid()::text, '-', '') as token`);
            paymentAccessToken = (tokenResult.rows[0] as any).token;
            await db.update(invoices).set({ paymentAccessToken, paymentLinkUrl: `/pay/${paymentAccessToken}`, updatedAt: new Date() }).where(eq(invoices.id, invoiceId));
          }

          const baseUrl = process.env.REPLIT_DEPLOYMENT_URL ||
            (process.env.REPL_SLUG ? `https://${process.env.REPL_SLUG}.${process.env.REPL_OWNER?.toLowerCase()}.repl.co` : 'http://localhost:5000');
          const fullPaymentLink = `${baseUrl}/pay/${paymentAccessToken}`;

          const lineItems = await db.select().from(invoiceLineItems).where(eq(invoiceLineItems.invoiceId, invoiceId));

          // Fetch billing entity for branding
          let bulkBillingEntity: any = null;
          if (existingInvoice.billingEntityId) {
            bulkBillingEntity = await storage.getBillingEntity(existingInvoice.billingEntityId).catch(() => null);
          }
          const bulkW9Url = `${baseUrl}/api/public/billing-documents/w9/download`;
          const bulkAddress = bulkBillingEntity ? [bulkBillingEntity.addressLine1, bulkBillingEntity.city, bulkBillingEntity.state, bulkBillingEntity.postalCode].filter(Boolean).join(', ') : '';

          if (customerEmail) {
            try {
              await sendInvoiceEmail({
                to: customerEmail,
                customerName: existingInvoice.customerName || 'Customer',
                invoiceNumber: existingInvoice.invoiceNumber || '',
                invoiceDate: existingInvoice.invoiceDate || new Date().toISOString().split('T')[0],
                dueDate: existingInvoice.dueDate || new Date().toISOString().split('T')[0],
                totalAmount: existingInvoice.totalAmount || '0',
                balanceDue: existingInvoice.balanceDue || existingInvoice.totalAmount || '0',
                paymentLink: fullPaymentLink,
                lineItems: lineItems.map(item => ({
                  description: item.description || '',
                  quantity: Number(item.quantity) || 1,
                  unitPrice: item.unitPrice || '0',
                  amount: item.totalPrice || '0',
                })),
                billingEntityName:    bulkBillingEntity?.legalName  || undefined,
                billingEntityDba:     bulkBillingEntity?.dbaName    || undefined,
                billingEntityEmail:   bulkBillingEntity?.email      || undefined,
                billingEntityPhone:   bulkBillingEntity?.phone      || undefined,
                billingEntityAddress: bulkAddress || undefined,
                billingEntityWebsite: bulkBillingEntity?.website    || undefined,
                w9Url: bulkW9Url,
              });
            } catch (emailErr) {
              console.error(`[Bulk Send] Email error for ${existingInvoice.invoiceNumber}:`, emailErr);
            }
          }

          await storage.sendInvoice(invoiceId, req.user.claims.sub, customerEmail ? [customerEmail] : []);
          await storage.createInvoiceDeliveryEvent({
            invoiceId,
            eventType: 'sent',
            recipientEmail: customerEmail,
            sentBy: req.user.claims.sub,
            metadata: { bulkSend: true },
          });

          results.push({ invoiceId, invoiceNumber: existingInvoice.invoiceNumber, success: true });
        } catch (err) {
          results.push({ invoiceId, invoiceNumber: '', success: false, error: err.message || 'Unknown error' });
        }
      }

      const successCount = results.filter(r => r.success).length;
      const failCount = results.filter(r => !r.success).length;
      res.json({ results, successCount, failCount, total: invoiceIds.length });
    } catch (error) {
      console.error("Error in bulk send:", error);
      res.status(500).json({ message: "Failed to process bulk send" });
    }
  });

