  // Add line item to invoice
  app.post("/api/corporate/invoicing/invoices/:invoiceId/line-items", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const _invUserLiCreate = { id: req.user.claims.sub, email: user?.email || '', role: user?.role };
      if (!hasInvoicingPermission(_invUserLiCreate, 'invoice:edit_draft')) {
        return res.status(403).json({ error_code: 'LINE_ITEM_PERMISSION_REQUIRED', message: 'Permission denied: adding line items requires invoice:edit_draft', required_permission: 'invoice:edit_draft' });
      }
      // Validate required category field
      const validCategories = ['service', 'mileage', 'fee', 'surcharge', 'late_fee', 'other'];
      const category = req.body.category || 'service';
      if (!validCategories.includes(category)) {
        return res.status(400).json({ message: `Invalid category. Must be one of: ${validCategories.join(', ')}` });
      }
      
      // Check invoice status - only draft invoices can have line items added
      const invoice = await storage.getInvoice(req.params.invoiceId);
      if (!invoice) {
        return res.status(404).json({ message: "Invoice not found" });
      }
      if (invoice.status !== 'draft') {
        return res.status(400).json({ message: "Cannot add line items to non-draft invoices" });
      }
      
      const lineItem = await storage.createInvoiceLineItem({
        ...req.body,
        invoiceId: req.params.invoiceId,
      });
      
      // Update invoice total after adding line item
      const lineItems = await storage.getInvoiceLineItems(req.params.invoiceId);
      const newTotal = lineItems.reduce((sum, item) => sum + parseFloat(item.totalPrice || '0'), 0);
      await storage.updateInvoice(req.params.invoiceId, { 
        subtotalAmount: newTotal.toFixed(2),
        totalAmount: newTotal.toFixed(2),
        balanceDue: newTotal.toFixed(2)
      });
      
      res.json(lineItem);
    } catch (error) {
      console.error("Error creating line item:", error);
      res.status(500).json({ message: "Failed to create line item" });
    }
  });

  // Update line item
  app.patch("/api/corporate/invoicing/line-items/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const _invUserLiEdit = { id: req.user.claims.sub, email: user?.email || '', role: user?.role };
      if (!hasInvoicingPermission(_invUserLiEdit, 'invoice:edit_draft')) {
        return res.status(403).json({ error_code: 'LINE_ITEM_PERMISSION_REQUIRED', message: 'Permission denied: editing line items requires invoice:edit_draft', required_permission: 'invoice:edit_draft' });
      }
      // Validate category if provided
      const validCategories = ['service', 'mileage', 'fee', 'surcharge', 'late_fee', 'other'];
      if (req.body.category && !validCategories.includes(req.body.category)) {
        return res.status(400).json({ message: `Invalid category. Must be one of: ${validCategories.join(', ')}` });
      }
      
      // Get line item to check invoice status
      const existingLineItem = await storage.getInvoiceLineItem(req.params.id);
      if (!existingLineItem) {
        return res.status(404).json({ message: "Line item not found" });
      }
      
      // Check invoice status - only draft invoices can be modified
      const invoice = await storage.getInvoice(existingLineItem.invoiceId);
      if (!invoice) {
        return res.status(404).json({ message: "Invoice not found" });
      }
      if (invoice.status !== 'draft') {
        return res.status(400).json({ message: "Cannot modify line items on non-draft invoices" });
      }
      
      const lineItem = await storage.updateInvoiceLineItem(req.params.id, req.body);
      
      // Update invoice total after modifying line item
      const lineItems = await storage.getInvoiceLineItems(existingLineItem.invoiceId);
      const newTotal = lineItems.reduce((sum, item) => sum + parseFloat(item.totalPrice || '0'), 0);
      await storage.updateInvoice(existingLineItem.invoiceId, { 
        subtotalAmount: newTotal.toFixed(2),
        totalAmount: newTotal.toFixed(2),
        balanceDue: newTotal.toFixed(2)
      });
      
      res.json(lineItem);
    } catch (error) {
      console.error("Error updating line item:", error);
      res.status(500).json({ message: "Failed to update line item" });
    }
  });

