  // Upload attachment to an invoice
  app.post("/api/corporate/invoicing/invoices/:invoiceId/attachments", isAuthenticated, express.raw({ type: ['image/*', 'application/pdf', 'text/csv', 'application/vnd.ms-excel', 'application/octet-stream'], limit: '10mb' }), async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const invoice = await storage.getInvoice(req.params.invoiceId);
      if (!invoice) {
        return res.status(404).json({ message: "Invoice not found" });
      }

      const contentType = req.headers['content-type'] || 'application/octet-stream';
      const fileName = req.headers['x-filename'] as string || 'attachment';
      const attachmentType = req.headers['x-attachment-type'] as string || 'other';
      const customerVisible = req.headers['x-customer-visible'] === 'true';

      // Validate attachment type
      const validAttachmentTypes = ['proof_of_service', 'signed_document', 'rate_sheet', 'other'];
      if (!validAttachmentTypes.includes(attachmentType)) {
        return res.status(400).json({ message: `Invalid attachment type. Must be one of: ${validAttachmentTypes.join(', ')}` });
      }

      // Validate MIME type
      if (!ALLOWED_ATTACHMENT_TYPES.includes(contentType) && !contentType.startsWith('image/')) {
        return res.status(400).json({ message: "Invalid file type. Allowed: PDF, images (JPEG, PNG, GIF, WebP), CSV" });
      }

      // Process buffer
      let fileBuffer: Buffer;
      if (Buffer.isBuffer(req.body)) {
        fileBuffer = req.body;
      } else if (req.body instanceof ArrayBuffer) {
        fileBuffer = Buffer.from(req.body);
      } else if (req.body && typeof req.body === 'object') {
        fileBuffer = Buffer.from(Object.values(req.body) as number[]);
      } else {
        return res.status(400).json({ message: "No file data received" });
      }

      if (fileBuffer.length === 0) {
        return res.status(400).json({ message: "Empty file received" });
      }

      if (fileBuffer.length > MAX_ATTACHMENT_SIZE) {
        return res.status(400).json({ message: "File size exceeds 10MB limit" });
      }

      // Upload to object storage
      const objectStorageService = new ObjectStorageService();
      const result = await objectStorageService.uploadFile(fileBuffer, contentType, fileName);

      // Save attachment metadata
      const attachment = await storage.createInvoiceAttachment({
        invoiceId: req.params.invoiceId,
        fileName,
        fileSize: fileBuffer.length,
        mimeType: contentType,
        objectPath: result.objectPath,
        attachmentType: attachmentType as any,
        customerVisible,
        uploadedBy: user!.id,
      });

      // Log activity
      await storage.createInvoiceActivity({
        invoiceId: req.params.invoiceId,
        activityType: 'attachment_added',
        description: `Attachment "${fileName}" uploaded (${attachmentType.replace(/_/g, ' ')})${customerVisible ? ' - visible to customer' : ''}`,
        performedBy: user!.id,
        performedByType: 'user',
        metadata: {
          attachmentId: attachment.id,
          fileName,
          attachmentType,
          customerVisible,
          fileSize: fileBuffer.length,
        },
      });

      res.json(attachment);
    } catch (error) {
      console.error("Error uploading attachment:", error);
      res.status(500).json({ message: "Failed to upload attachment" });
    }
  });

  // Download attachment
  app.get("/api/corporate/invoicing/attachments/:attachmentId/download", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const attachment = await storage.getInvoiceAttachment(req.params.attachmentId);
      if (!attachment) {
        return res.status(404).json({ message: "Attachment not found" });
      }

      let fileBuffer: Buffer;
      const provider = getStorageProvider();

      if (provider === "s3") {
        const s3Service = getS3StorageService();
        try {
          fileBuffer = await s3Service.downloadAsBytes(attachment.objectPath);
        } catch (dlErr: any) {
          console.error('S3 download error:', dlErr.message);
          return res.status(404).json({ message: "File not found in storage" });
        }
      } else {
        const client = new (await import("@replit/object-storage")).Client({
          bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID!,
        });
        const objectName = attachment.objectPath.replace('/objects/', '');
        const result = await client.downloadAsBytes(objectName);
        if (!result.ok || !result.value) {
          return res.status(404).json({ message: "File not found in storage" });
        }
        fileBuffer = Buffer.from(result.value);
      }

      res.set({
        'Content-Type': attachment.mimeType,
        'Content-Disposition': `attachment; filename="${attachment.fileName}"`,
        'Content-Length': String(fileBuffer.length),
      });
      res.send(fileBuffer);
    } catch (error) {
      console.error("Error downloading attachment:", error);
      res.status(500).json({ message: "Failed to download attachment" });
    }
  });

  // Delete attachment
  app.delete("/api/corporate/invoicing/invoices/:invoiceId/attachments/:attachmentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);

      // Only Super Admins can delete invoice attachments
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete documents and attachments' });
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      const attachment = await storage.getInvoiceAttachment(req.params.attachmentId);
      if (!attachment) {
        return res.status(404).json({ message: 'Attachment not found' });
      }

      if (attachment.invoiceId !== req.params.invoiceId) {
        return res.status(400).json({ message: 'Attachment does not belong to this invoice' });
      }

      // Soft delete — mark as deleted (no physical file removal)
      const { invoiceAttachments: invAttachTable } = await import('../shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');
      await db.update(invAttachTable)
        .set({ isDeleted: true, deletedAt: new Date(), deletedByUserId: userId, deletionReason: String(deletionReason).trim() })
        .where(eq(invAttachTable.id, req.params.attachmentId));
      
      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: userId,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'invoice_attachment',
        targetEntityId: req.params.attachmentId,
        targetEntityLabel: attachment.fileName,
        reason: String(deletionReason).trim(),
        metadata: { invoiceId: req.params.invoiceId, fileName: attachment.fileName, attachmentType: attachment.attachmentType, restrictedAction: true },
        ipAddress: req.ip,
      });
      
      // Log activity (keep existing activity log)
      const placeholderUser = user;
      const placeholderAttachment = attachment;
      // (activity log below)

      // Log activity
      await storage.createInvoiceActivity({
        invoiceId: req.params.invoiceId,
        activityType: 'attachment_removed',
        description: `Attachment "${attachment.fileName}" removed`,
        performedBy: user!.id,
        performedByType: 'user',
        metadata: {
          attachmentId: attachment.id,
          fileName: attachment.fileName,
          attachmentType: attachment.attachmentType,
        },
      });

      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting attachment:", error);
      res.status(500).json({ message: "Failed to delete attachment" });
    }
  });

