  // Unapply payment from invoice
  app.delete("/api/corporate/invoicing/payment-applications/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      // Removing a payment from an invoice requires Owner or Controller role
      const { isPaymentController } = await import("./services/invoicingPermissions");
      if (!isPaymentController(user?.role)) {
        writeFinancialAuditEvent({
          eventType: "payment.remove_denied",
          actorUserId: user?.id ?? req.user.claims.sub,
          actorUserEmail: user?.email ?? null,
          targetEntityType: "payment_application",
          targetEntityId: req.params.id,
          notes: `Denied payment removal by role=${user?.role ?? "unknown"}`,
          metadata: { role: user?.role },
        }).catch(() => {});
        return res.status(403).json({ message: "Permission denied: Removing payment applications requires Owner or Controller role.", error_code: "PAYMENT_CONTROLLER_REQUIRED" });
      }
      // Reason is mandatory
      const reason = req.body?.reason || req.query?.reason as string;
      if (!reason || typeof reason !== 'string' || reason.trim().length < 3) {
        return res.status(400).json({ message: "A reason for removing this payment application is required (minimum 3 characters).", error_code: "REASON_REQUIRED" });
      }
      const userId = user?.id ?? req.user.claims.sub;
      const actorName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null;

      await storage.unapplyPayment(req.params.id);

      await storage.logInvoicingAction({
        userId,
        action: "payment_unapply",
        resourceType: "payment_application",
        resourceId: req.params.id,
        details: { reason: reason.trim() },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });
      writeFinancialAuditEvent({
        eventType: 'payment.removed_from_invoice',
        actorUserId: userId,
        actorUserEmail: user?.email ?? null,
        actorUserName: actorName,
        targetEntityType: 'payment_application',
        targetEntityId: req.params.id,
        notes: reason.trim(),
        ipAddress: req.ip,
      }).catch(() => {});

      res.json({ success: true });
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error unapplying payment:", error);
      res.status(500).json({ message: "Failed to unapply payment" });
    }
  });

