  // Create deposit batch
  app.post("/api/corporate/invoicing/deposit-batches", isAuthenticated, async (req: any, res: Response) => {
    try {
      let user = await storage.getUser(req.user.claims.sub);
      if (!user && req.user.claims.email) {
        user = await storage.getUserByEmail(req.user.claims.email);
      }
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || '' : '';
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({
          message: "Permission denied: Only Billing Team members (finance, admin, or higher) may create deposit batches.",
          error_code: "DEPOSIT_BILLING_TEAM_REQUIRED",
        });
      }
      const batchNumber = await storage.generateBatchNumber();
      const batch = await storage.createDepositBatch({
        ...req.body,
        status: 'draft',
        batchNumber,
        createdBy: userId,
      });
      await storage.logDepositBatchAudit(batch.id, 'created', null, 'draft', userId, userName, { batchNumber });
      await storage.logInvoicingAction({
        userId,
        action: "deposit_batch_create",
        resourceType: "deposit_batch",
        resourceId: batch.id,
        details: { batchNumber },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });
      writeFinancialAuditEvent({
        eventType: 'deposit_batch.created',
        actorUserId: userId,
        actorUserEmail: user?.email ?? null,
        actorUserName: userName || null,
        targetEntityType: 'deposit_batch',
        targetEntityId: batch.id,
        targetEntityLabel: batchNumber,
        newValue: { batchNumber, status: 'draft', depositDate: req.body.depositDate, bankAccountName: req.body.bankAccountName },
        ipAddress: req.ip,
      }).catch(() => {});
      res.json(batch);
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error creating deposit batch:", error);
      res.status(500).json({ message: "Failed to create deposit batch" });
    }
  });

  // Add payment to deposit batch
  app.post("/api/corporate/invoicing/deposit-batches/:batchId/payments/:paymentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || '' : '';
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({
          message: "Permission denied: Only Billing Team members may add payments to a deposit batch.",
          error_code: "DEPOSIT_BILLING_TEAM_REQUIRED",
        });
      }
      const batch = await storage.getDepositBatch(req.params.batchId);
      if (!batch) {
        return res.status(404).json({ message: "Deposit batch not found" });
      }
      if (batch.status === 'submitted' || batch.status === 'locked' || batch.status === 'reconciled') {
        return res.status(403).json({
          message: `Cannot add payments to a ${batch.status} batch. Batches in this state are immutable.`,
          error_code: "BATCH_IMMUTABLE",
        });
      }
      if (batch.status !== 'draft' && batch.status !== 'balanced') {
        return res.status(400).json({ message: `Cannot add payments to a ${batch.status} deposit batch. Only draft or balanced batches accept payments.` });
      }
      const { reverted } = await storage.addPaymentToDepositBatch(req.params.batchId, req.params.paymentId);
      if (reverted) {
        await storage.logDepositBatchAudit(req.params.batchId, 'status_reverted', 'balanced', 'draft', userId, userName, { reason: 'payment_added', paymentId: req.params.paymentId });
      }
      await storage.logDepositBatchAudit(req.params.batchId, 'payment_added', null, null, userId, userName, { paymentId: req.params.paymentId });
      res.json({ success: true, reverted });
    } catch (error) {
      console.error("Error adding payment to batch:", error);
      res.status(500).json({ message: "Failed to add payment to batch" });
    }
  });

  // Remove payment from deposit batch — super_user (Owner / Super Admin) only
  app.delete("/api/corporate/invoicing/deposit-batches/:batchId/payments/:paymentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || '' : '';
      const invoicingUser = { id: userId, email: user?.email || "", role: user?.role };
      // Removing a payment from a batch requires Controller/Owner role
      const { isDepositBatchController } = await import("./services/invoicingPermissions");
      if (!isDepositBatchController(user?.role)) {
        const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
        await writeFinancialAuditEvent({
          eventType: "financial.recon.access_denied",
          actorUserId: userId,
          actorUserEmail: user?.email ?? null,
          targetEntityType: "deposit_batch_payment",
          targetEntityId: req.params.paymentId,
          notes: `Denied attempt to remove payment from batch by role=${user?.role ?? "unknown"}`,
          metadata: { batchId: req.params.batchId, paymentId: req.params.paymentId, role: user?.role },
        }).catch(() => {});
        return res.status(403).json({
          message: "Permission denied: Only Controllers and Owners (finance, admin, or higher) may remove payments from deposit batches.",
          error_code: "DEPOSIT_CONTROLLER_REQUIRED",
        });
      }
      const batch = await storage.getDepositBatch(req.params.batchId);
      if (!batch) {
        return res.status(404).json({ message: "Deposit batch not found" });
      }
      if (batch.status !== 'draft' && batch.status !== 'balanced') {
        return res.status(400).json({ message: `Cannot remove payments from a ${batch.status} deposit batch. Only draft or balanced batches can be modified.` });
      }
      const { reverted } = await storage.removePaymentFromDepositBatch(req.params.paymentId);
      if (reverted) {
        await storage.logDepositBatchAudit(req.params.batchId, 'status_reverted', 'balanced', 'draft', userId, userName, { reason: 'payment_removed', paymentId: req.params.paymentId });
      }
      await storage.logDepositBatchAudit(req.params.batchId, 'payment_removed', null, null, userId, userName, { paymentId: req.params.paymentId });
      import('./services/exceptionEngine').then(eng => eng.onPaymentRemovedFromBatch(req.params.paymentId, req.params.batchId)).catch(() => {});
      res.json({ success: true, reverted });
    } catch (error) {
      console.error("Error removing payment from batch:", error);
      res.status(500).json({ message: "Failed to remove payment from batch" });
    }
  });

  // Transition deposit batch (generic lifecycle endpoint)
  app.post("/api/corporate/invoicing/deposit-batches/:id/transition", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || '' : '';
      const invUser = { id: userId, email: user?.email || "", role: user?.role };

      const existingBatch = await storage.getDepositBatch(req.params.id);
      if (!existingBatch) {
        return res.status(404).json({ message: "Deposit batch not found" });
      }

      const { action, actualAmount, statementDate, reconciliationReference, notes } = req.body;
      if (!action) {
        return res.status(400).json({ message: "Action is required" });
      }

      const currentStatus = existingBatch.status || 'draft';

      // Validate transition via state machine
      const transitionResult = await validateBatchTransition({
        batchId: req.params.id,
        fromStatus: currentStatus,
        action,
        userRole: user?.role || '',
        batch: existingBatch,
        actualAmount,
        reconciliationReference,
        statementDate,
        notes,
      });

      if (!transitionResult.ok) {
        const httpStatus = transitionResult.code === 'PERMISSION_DENIED' ? 403
          : transitionResult.code === 'BALANCE_MISMATCH' ? 422
          : 400;
        return res.status(httpStatus).json({
          message: transitionResult.error,
          code: transitionResult.code,
          ...(transitionResult.balanceDetails ? { balanceDetails: transitionResult.balanceDetails } : {}),
        });
      }

      // Compute update data from state machine
      const updateData = computeBatchTransitionData({
        batchId: req.params.id,
        fromStatus: currentStatus,
        action,
        userRole: user?.role || '',
        batch: existingBatch,
        actualAmount,
        reconciliationReference,
        statementDate,
        notes,
      });

      // Inject actor fields for tracked transitions
      if (action === 'submit') { updateData.submittedBy = userId; }
      if (action === 'lock')   { updateData.lockedBy = userId; }
      if (action === 'reconcile') { updateData.reconciledBy = userId; }

      const targetStatus = updateData.status;
      const batch = await storage.updateDepositBatch(req.params.id, updateData);
      await storage.logDepositBatchAudit(req.params.id, action, currentStatus, targetStatus, userId, userName, { ...req.body });

      // Financial Record Locking: lock all payments in this batch when batch is locked or reconciled
      if (action === 'lock' || action === 'reconcile') {
        const { lockPaymentsInBatch } = await import("./services/financialLockService");
        lockPaymentsInBatch({
          batchId:     req.params.id,
          batchNumber: existingBatch.batchNumber,
          lockSource:  action === 'lock' ? 'deposit_locked' : 'deposit_reconciled',
          actorId:     userId,
          actorRole:   user?.role,
        }).catch((err) => console.error("[FinancialLock] Failed to lock batch payments:", err));
      }
      await storage.logInvoicingAction({
        userId,
        action: `deposit_batch_${action}`,
        resourceType: "deposit_batch",
        resourceId: req.params.id,
        details: { batchNumber: existingBatch.batchNumber, fromStatus: currentStatus, toStatus: targetStatus, ...(transitionResult.balanceDetails || {}) },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });
      writeFinancialAuditEvent({
        eventType: `deposit_batch.${action}`,
        actorUserId: userId,
        actorUserEmail: user?.email || '',
        targetEntityType: 'deposit_batch',
        targetEntityId: req.params.id,
        targetEntityLabel: existingBatch.batchNumber,
        previousValue: { status: currentStatus },
        newValue: { status: targetStatus, ...(action === 'reconcile' ? { actualAmount, discrepancy: updateData.discrepancyAmount } : {}) },
        ipAddress: req.ip,
      }).catch(() => {});
      res.json(batch);
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error transitioning deposit batch:", error);
      res.status(500).json({ message: "Failed to transition deposit batch" });
    }
  });

  // Get deposit batch audit log
