  // Update deposit batch metadata (only in draft or balanced)
  app.patch("/api/corporate/invoicing/deposit-batches/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const userName = user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || '' : '';
      const { isDepositBillingTeam, isDepositBatchController } = await import("./services/invoicingPermissions");
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({
          message: "Permission denied: Only Billing Team members may update deposit batch details.",
          error_code: "DEPOSIT_BILLING_TEAM_REQUIRED",
        });
      }
      const existingBatch = await storage.getDepositBatch(req.params.id);
      if (!existingBatch) {
        return res.status(404).json({ message: "Deposit batch not found" });
      }
      if (existingBatch.status === 'submitted' || existingBatch.status === 'locked' || existingBatch.status === 'reconciled') {
        return res.status(403).json({
          message: `Cannot edit a ${existingBatch.status} batch. Only draft or balanced batches may be edited.`,
          error_code: "BATCH_IMMUTABLE",
        });
      }
      // Modifying declared totals (totalAmount / itemCount) is a Controller-only action
      if ((req.body.totalAmount !== undefined || req.body.itemCount !== undefined) && !isDepositBatchController(user?.role)) {
        return res.status(403).json({
          message: "Permission denied: Only Controllers and Owners may modify batch totals.",
          error_code: "DEPOSIT_CONTROLLER_REQUIRED",
        });
      }
      const { depositDate, bankAccountName, bankAccountLast4, depositMethod, notes } = req.body;
      const updates: any = {};
      if (depositDate !== undefined) updates.depositDate = depositDate;
      if (bankAccountName !== undefined) updates.bankAccountName = bankAccountName;
      if (bankAccountLast4 !== undefined) updates.bankAccountLast4 = bankAccountLast4;
      if (depositMethod !== undefined) updates.depositMethod = depositMethod;
      if (notes !== undefined) updates.notes = notes;

      let reverted = false;
      if (existingBatch.status === 'balanced') {
        updates.status = 'draft';
        reverted = true;
      }

      const batch = await storage.updateDepositBatch(req.params.id, updates);
      if (reverted) {
        await storage.logDepositBatchAudit(req.params.id, 'status_reverted', 'balanced', 'draft', userId, userName, { reason: 'metadata_updated' });
      }
      await storage.logDepositBatchAudit(req.params.id, 'metadata_updated', null, null, userId, userName, { fields: Object.keys(updates).filter(k => k !== 'status') });
      writeFinancialAuditEvent({
        eventType: 'deposit_batch.updated',
        actorUserId: userId,
        actorUserEmail: user?.email ?? null,
        actorUserName: userName || null,
        targetEntityType: 'deposit_batch',
        targetEntityId: req.params.id,
        targetEntityLabel: existingBatch.batchNumber,
        previousValue: { depositDate: existingBatch.depositDate, bankAccountName: existingBatch.bankAccountName, notes: existingBatch.notes, status: existingBatch.status },
        newValue: updates,
        ipAddress: req.ip,
      }).catch(() => {});
      res.json(batch);
    } catch (error) {
      console.error("Error updating deposit batch:", error);
      res.status(500).json({ message: "Failed to update deposit batch" });
    }
  });

  // Delete deposit batch (only in draft status)
  app.delete("/api/corporate/invoicing/deposit-batches/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const userId = user?.id || req.user.claims.sub;
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({
          message: "Permission denied: Only Billing Team members may delete deposit batches.",
          error_code: "DEPOSIT_BILLING_TEAM_REQUIRED",
        });
      }
      const existingBatch = await storage.getDepositBatch(req.params.id);
      if (!existingBatch) {
        return res.status(404).json({ message: "Deposit batch not found" });
      }
      if (existingBatch.status !== 'draft') {
        return res.status(400).json({ message: `Cannot delete a ${existingBatch.status} batch. Only draft batches can be deleted.` });
      }
      await storage.deleteDepositBatch(req.params.id);
      await storage.logInvoicingAction({
        userId,
        action: "deposit_batch_delete",
        resourceType: "deposit_batch",
        resourceId: req.params.id,
        details: { batchNumber: existingBatch.batchNumber },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });
      writeFinancialAuditEvent({
        eventType: 'deposit_batch.deleted',
        actorUserId: userId,
        actorUserEmail: user?.email ?? null,
        actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
        targetEntityType: 'deposit_batch',
        targetEntityId: req.params.id,
        targetEntityLabel: existingBatch.batchNumber,
        previousValue: { batchNumber: existingBatch.batchNumber, status: existingBatch.status },
        ipAddress: req.ip,
      }).catch(() => {});
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting deposit batch:", error);
      res.status(500).json({ message: "Failed to delete deposit batch" });
    }
  });

