  // GET /api/corporate/invoicing/financial-audit-log/active-users
  // Returns distinct users who have financial audit entries (for filter dropdowns)
  app.get("/api/corporate/invoicing/financial-audit-log/active-users", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const { fromDate, toDate } = req.query;
      const { db } = await import("./db");
      const { systemAuditLog } = await import("../shared/schema");
      const { sql: drizzleSql, and, gte, lte, isNotNull, ilike } = await import("drizzle-orm");
      const conditions: any[] = [isNotNull(systemAuditLog.actorUserId), ilike(systemAuditLog.eventType, "financial.%") as any];
      if (fromDate) conditions.push(gte(systemAuditLog.createdAt, new Date(fromDate as string)));
      if (toDate) conditions.push(lte(systemAuditLog.createdAt, new Date(new Date(toDate as string).setHours(23,59,59,999))));
      const rows = await db
        .selectDistinct({
          actorUserId: systemAuditLog.actorUserId,
          actorUserEmail: systemAuditLog.actorUserEmail,
        })
        .from(systemAuditLog)
        .where(and(...conditions))
        .orderBy(systemAuditLog.actorUserEmail);
      res.json(rows.filter(r => r.actorUserId));
    } catch (error) {
      console.error("Error fetching active audit users:", error);
      res.status(500).json({ message: "Failed to fetch active audit users" });
    }
  });

  // GET /api/corporate/invoicing/financial-audit-log/user-activity-summary
  // Aggregates financial audit events by user and action category
  app.get("/api/corporate/invoicing/financial-audit-log/user-activity-summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const { fromDate, toDate, actorUserId } = req.query;
      const { db } = await import("./db");
      const { systemAuditLog } = await import("../shared/schema");
      const { sql: drizzleSql, and, gte, lte, isNotNull, ilike, eq } = await import("drizzle-orm");

      const conditions: any[] = [isNotNull(systemAuditLog.actorUserId), ilike(systemAuditLog.eventType, "financial.%") as any];
      if (fromDate) conditions.push(gte(systemAuditLog.createdAt, new Date(fromDate as string)));
      if (toDate) conditions.push(lte(systemAuditLog.createdAt, new Date(new Date(toDate as string).setHours(23,59,59,999))));
      if (actorUserId && actorUserId !== "all") conditions.push(eq(systemAuditLog.actorUserId, actorUserId as string));

      // Fetch raw rows and aggregate in JS for portability
      const rows = await db
        .select({
          actorUserId: systemAuditLog.actorUserId,
          actorUserEmail: systemAuditLog.actorUserEmail,
          eventType: systemAuditLog.eventType,
          createdAt: systemAuditLog.createdAt,
        })
        .from(systemAuditLog)
        .where(and(...conditions))
        .orderBy(systemAuditLog.createdAt);

      // Aggregate per user
      const userMap: Record<string, {
        actorUserId: string;
        actorUserEmail: string | null;
        paymentsCreated: number;
        adjustments: number;
        reversals: number;
        edits: number;
        batchActions: number;
        other: number;
        total: number;
        lastAction: string | null;
      }> = {};

      for (const row of rows) {
        if (!row.actorUserId) continue;
        if (!userMap[row.actorUserId]) {
          userMap[row.actorUserId] = {
            actorUserId: row.actorUserId,
            actorUserEmail: row.actorUserEmail,
            paymentsCreated: 0,
            adjustments: 0,
            reversals: 0,
            edits: 0,
            batchActions: 0,
            other: 0,
            total: 0,
            lastAction: null,
          };
        }
        const u = userMap[row.actorUserId];
        const et = row.eventType || "";
        u.total++;
        u.lastAction = row.createdAt ? row.createdAt.toISOString() : null;
        if (et === "financial.payment.created") u.paymentsCreated++;
        else if (et === "financial.payment.reversed") u.reversals++;
        else if (et.includes("payment.edited") || et.includes("payment.reassigned") || et.includes("payment.applied") || et.includes("payment.removed")) u.adjustments++;
        else if (et.includes("deposit_batch")) u.batchActions++;
        else if (et.includes("invoice.updated") || et.includes("invoice.status_changed") || et.includes("invoice.written_off") || et.includes("invoice.deleted") || et.includes("invoice.created")) u.edits++;
        else u.other++;
      }

      // Summary totals
      const users = Object.values(userMap).sort((a, b) => b.total - a.total);
      const summary = {
        totalEvents: rows.length,
        uniqueUsers: users.length,
        paymentsCreated: users.reduce((s, u) => s + u.paymentsCreated, 0),
        reversals: users.reduce((s, u) => s + u.reversals, 0),
        adjustments: users.reduce((s, u) => s + u.adjustments, 0),
        edits: users.reduce((s, u) => s + u.edits, 0),
        batchActions: users.reduce((s, u) => s + u.batchActions, 0),
      };

      res.json({ users, summary });
    } catch (error) {
      console.error("Error fetching user activity summary:", error);
      res.status(500).json({ message: "Failed to fetch user activity summary" });
    }
  });

