  // PATCH /api/corporate/invoicing/recon/settings — toggle restricted mode
  app.patch("/api/corporate/invoicing/recon/settings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { isReconAdmin } = await import("./services/invoicingPermissions");
      const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
      const user = await storage.getUser(req.user.claims.sub);
      if (!isReconAdmin(user?.role)) return res.status(403).json({ message: "Forbidden", error_code: "RECON_ACCESS_DENIED" });
      const { restrictedMode, requireDepositBatch } = req.body;
      const { upsertConfig } = await import("./services/platformConfigService");
      if (restrictedMode !== undefined) {
        await upsertConfig("recon.restricted_mode", restrictedMode === true ? "true" : "false");
      }
      if (requireDepositBatch !== undefined) {
        await upsertConfig("recon.require_deposit_batch", requireDepositBatch === true ? "true" : "false");
      }
      await writeFinancialAuditEvent({
        eventType: "financial.recon.settings_changed",
        actorUserId: user?.id ?? null,
        actorUserEmail: user?.email ?? null,
        targetEntityType: "reconciliation_settings",
        targetEntityId: "recon.settings",
        notes: `Settings updated: ${Object.keys(req.body).join(", ")}`,
        metadata: { restrictedMode, requireDepositBatch, changedBy: user?.email },
      });
      res.json({ success: true, restrictedMode: restrictedMode === true, requireDepositBatch: requireDepositBatch === true });
    } catch (error) {
      console.error("Error updating recon settings:", error);
      res.status(500).json({ message: "Failed to update settings" });
    }
  });

  // ==========================================
  // FINANCIAL EXCEPTION ENGINE API
  // ==========================================

  // GET /api/corporate/invoicing/financial-exceptions — list stored exceptions
  app.get("/api/corporate/invoicing/financial-exceptions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      const user = await storage.getUser(req.user.claims.sub);
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Billing team access required", error_code: "BILLING_TEAM_REQUIRED" });
      }
      const { status = "open", type, customerId, entityType, limit = "100", offset = "0" } = req.query as Record<string, string>;
      const clauses: string[] = [];
      if (status) clauses.push(`fe.status = '${status.replace(/'/g, "''")}'`);
      if (type) clauses.push(`fe.type = '${type.replace(/'/g, "''")}'`);
      if (customerId) clauses.push(`fe.customer_id = '${customerId.replace(/'/g, "''")}'`);
      if (entityType) clauses.push(`fe.entity_type = '${entityType.replace(/'/g, "''")}'`);
      const where = clauses.length ? `WHERE ${clauses.join(" AND ")}` : "";
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");

      const rows = await dbConn.execute(sqlFn.raw(`
        SELECT fe.*,
               COALESCE(c.name, fe.customer_id) AS customer_name,
               u.email AS resolved_by_email
        FROM financial_exceptions fe
        LEFT JOIN customers c ON c.id = fe.customer_id
        LEFT JOIN users u ON u.id = fe.resolved_by_user_id
        ${where}
        ORDER BY
          CASE fe.severity WHEN 'error' THEN 0 ELSE 1 END,
          fe.created_at DESC
        LIMIT ${parseInt(limit)} OFFSET ${parseInt(offset)}
      `)) as any[];

      const [countRow] = await dbConn.execute(sqlFn.raw(`
        SELECT COUNT(*)::int AS total FROM financial_exceptions fe ${where}
      `)) as any[];

      const [summaryRow] = await dbConn.execute(sqlFn.raw(`
        SELECT
          COUNT(*) FILTER (WHERE status = 'open')::int AS open_count,
          COUNT(*) FILTER (WHERE status = 'resolved')::int AS resolved_count,
          COUNT(*) FILTER (WHERE status = 'dismissed')::int AS dismissed_count,
          COUNT(*) FILTER (WHERE severity = 'error' AND status = 'open')::int AS open_errors,
          COUNT(*) FILTER (WHERE severity = 'warning' AND status = 'open')::int AS open_warnings
        FROM financial_exceptions
      `)) as any[];

      res.json({
        exceptions: rows,
        total: (countRow as any)?.total ?? 0,
        summary: summaryRow,
      });
    } catch (error) {
      console.error("Error fetching financial exceptions:", error);
      res.status(500).json({ message: "Failed to fetch financial exceptions" });
    }
  });

  // GET /api/corporate/invoicing/financial-exceptions/summary — counts by type for dashboard
  app.get("/api/corporate/invoicing/financial-exceptions/summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      const user = await storage.getUser(req.user.claims.sub);
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({ message: "Forbidden", error_code: "BILLING_TEAM_REQUIRED" });
      }
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const rows = await dbConn.execute(sqlFn.raw(`
        SELECT type, severity, COUNT(*)::int AS count
        FROM financial_exceptions
        WHERE status = 'open'
        GROUP BY type, severity
        ORDER BY severity, count DESC
      `)) as any[];
      res.json({ byType: rows });
    } catch (error) {
      console.error("Error fetching exception summary:", error);
      res.status(500).json({ message: "Failed to fetch exception summary" });
    }
  });

  // PATCH /api/corporate/invoicing/financial-exceptions/:id/resolve — resolve an exception
  app.patch("/api/corporate/invoicing/financial-exceptions/:id/resolve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { isDepositBillingTeam } = await import("./services/invoicingPermissions");
      const user = await storage.getUser(req.user.claims.sub);
      if (!isDepositBillingTeam(user?.role)) {
        return res.status(403).json({ message: "Forbidden", error_code: "BILLING_TEAM_REQUIRED" });
      }
      const { note } = req.body;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      await dbConn.execute(sqlFn.raw(`
        UPDATE financial_exceptions
        SET status = 'resolved',
            resolved_at = NOW(),
            resolved_by_user_id = '${req.user.claims.sub.replace(/'/g, "''")}',
            resolution_note = ${note ? `'${String(note).replace(/'/g, "''")}'` : "NULL"}
        WHERE id = '${req.params.id.replace(/'/g, "''")}'
          AND status = 'open'
      `));
      res.json({ success: true });
    } catch (error) {
      console.error("Error resolving exception:", error);
      res.status(500).json({ message: "Failed to resolve exception" });
    }
  });

