  // ==========================================
  // FRAUD PATTERN PLAYBOOK
  // Access: Owner only (super_user / super_admin / root_super_admin)
  // Optional Controller expansion via platform config flag:
  //   fraud.playbook.allow_controller = true
  // ==========================================

  /**
   * Shared guard: resolves allow_controller flag from platform config,
   * then asserts the requesting user has Fraud Playbook access.
   * Returns { user, allowController } on success, or sends 403 and returns null.
   */
  async function requireFraudPlaybookAccess(req: any, res: Response): Promise<{ user: any; allowController: boolean } | null> {
    const { isFraudPlaybookAllowed } = await import("./services/invoicingPermissions");
    const { resolveConfig } = await import("./services/platformConfigService");
    const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
    const user = await storage.getUser(req.user.claims.sub);
    const acRaw = await resolveConfig('fraud.playbook.allow_controller');
    const allowController = acRaw?.configValue === true || acRaw?.configValue === 'true';
    if (!isFraudPlaybookAllowed(user?.role, allowController)) {
      // Log the denied access attempt to the financial audit trail
      writeFinancialAuditEvent({
        eventType: 'fraud_playbook.access_denied',
        actorUserId: req.user.claims.sub,
        actorUserEmail: user?.email ?? null,
        actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
        targetEntityType: 'fraud_playbook',
        targetEntityId: 'global',
        newValue: { endpoint: req.path, method: req.method },
        ipAddress: req.ip,
      }).catch(() => {});
      res.status(403).json({
        message: "Forbidden: Owner role required to access Fraud Pattern Playbook.",
        error_code: "FRAUD_PLAYBOOK_ACCESS_DENIED",
        required_role: "Owner (super_user / super_admin)",
      });
      return null;
    }
    return { user, allowController };
  }

