  // GET /api/corporate/invoicing/fraud-playbook/patterns
  // Returns configured fraud detection patterns (Owner only)
  app.get("/api/corporate/invoicing/fraud-playbook/patterns", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { resolveConfig } = await import("./services/platformConfigService");
      const raw = await resolveConfig(FRAUD_PATTERNS_CONFIG_KEY);
      let patterns = DEFAULT_FRAUD_PATTERNS;
      if (raw?.configValue) {
        const cv = raw.configValue;
        patterns = typeof cv === 'string' ? JSON.parse(cv) : (Array.isArray(cv) ? cv : DEFAULT_FRAUD_PATTERNS);
      }
      res.json({ patterns, allowController: guard.allowController });
    } catch (error) {
      console.error("Error fetching fraud patterns:", error);
      res.status(500).json({ message: "Failed to fetch fraud patterns" });
    }
  });

  // PATCH /api/corporate/invoicing/fraud-playbook/patterns/:id
  // Update a single fraud pattern rule (Owner only)
  app.patch("/api/corporate/invoicing/fraud-playbook/patterns/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { resolveConfig, upsertConfig } = await import("./services/platformConfigService");
      const raw = await resolveConfig(FRAUD_PATTERNS_CONFIG_KEY);
      let patterns: any[] = [...DEFAULT_FRAUD_PATTERNS];
      if (raw?.configValue) {
        const cv = raw.configValue;
        patterns = typeof cv === 'string' ? JSON.parse(cv) : (Array.isArray(cv) ? cv : [...DEFAULT_FRAUD_PATTERNS]);
      }
      const idx = patterns.findIndex((p: any) => p.id === req.params.id);
      if (idx === -1) return res.status(404).json({ message: "Fraud pattern not found" });
      const allowed = ['enabled', 'threshold', 'timeWindowHours', 'action', 'severity', 'description', 'name'];
      const updates: any = {};
      for (const k of allowed) {
        if (k in req.body) updates[k] = req.body[k];
      }
      patterns[idx] = { ...patterns[idx], ...updates, updatedAt: new Date().toISOString() };
      await upsertConfig(FRAUD_PATTERNS_CONFIG_KEY, JSON.stringify(patterns));
      const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
      writeFinancialAuditEvent({
        eventType: 'fraud_playbook.pattern_updated',
        actorUserId: req.user.claims.sub,
        actorUserEmail: guard.user?.email ?? null,
        targetEntityType: 'fraud_pattern',
        targetEntityId: req.params.id,
        targetEntityLabel: patterns[idx].name,
        newValue: updates,
        ipAddress: req.ip,
      }).catch(() => {});
      res.json(patterns[idx]);
    } catch (error) {
      console.error("Error updating fraud pattern:", error);
      res.status(500).json({ message: "Failed to update fraud pattern" });
    }
  });

  // POST /api/corporate/invoicing/fraud-playbook/patterns/reset
  // Reset all patterns to system defaults (Owner only)
  app.post("/api/corporate/invoicing/fraud-playbook/patterns/reset", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { upsertConfig } = await import("./services/platformConfigService");
      await upsertConfig(FRAUD_PATTERNS_CONFIG_KEY, JSON.stringify(DEFAULT_FRAUD_PATTERNS));
      res.json({ patterns: DEFAULT_FRAUD_PATTERNS });
    } catch (error) {
      console.error("Error resetting fraud patterns:", error);
      res.status(500).json({ message: "Failed to reset fraud patterns" });
    }
  });

  // GET /api/corporate/invoicing/fraud-playbook/detections
  // Recent detections sourced from the financial_exceptions table (Owner only)
  app.get("/api/corporate/invoicing/fraud-playbook/detections", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { fromDate, toDate, status, patternType, limit = "100", offset = "0" } = req.query as Record<string, string>;

      const FRAUD_TYPES = ['duplicate_payment', 'payment_reversal', 'payment_edited_after_creation', 'manual_payment', 'invoice_adjusted_while_paid', 'payment_without_invoice'];
      const typeList = FRAUD_TYPES.map(t => `'${t}'`).join(', ');
      const clauses: string[] = [`fe.type IN (${typeList})`];
      if (fromDate) clauses.push(`fe.created_at >= '${fromDate}'`);
      if (toDate) clauses.push(`fe.created_at <= '${new Date(new Date(toDate).setHours(23,59,59,999)).toISOString()}'`);
      if (status && status !== 'all') clauses.push(`fe.status = '${status.replace(/'/g, "''")}'`);
      if (patternType && patternType !== 'all') clauses.push(`fe.type = '${patternType.replace(/'/g, "''")}'`);
      const where = `WHERE ${clauses.join(' AND ')}`;

      const rows = await dbConn.execute(sqlFn.raw(`
        SELECT fe.*,
               COALESCE(c.name, fe.customer_id) AS customer_name,
               u.email AS resolved_by_email,
               ur.email AS reviewed_by_email,
               ue.email AS escalated_by_email
        FROM financial_exceptions fe
        LEFT JOIN customers c ON c.id = fe.customer_id
        LEFT JOIN users u ON u.id = fe.resolved_by_user_id
        LEFT JOIN users ur ON ur.id = fe.reviewed_by_user_id
        LEFT JOIN users ue ON ue.id = fe.escalated_by_user_id
        ${where}
        ORDER BY
          CASE fe.severity WHEN 'critical' THEN 0 WHEN 'error' THEN 1 WHEN 'high' THEN 2 ELSE 3 END,
          fe.created_at DESC
        LIMIT ${parseInt(limit)} OFFSET ${parseInt(offset)}
      `)) as any[];

      const [countRow] = await dbConn.execute(sqlFn.raw(`
        SELECT COUNT(*)::int AS total FROM financial_exceptions fe ${where}
      `)) as any[];

      res.json({ detections: rows, total: (countRow as any)?.total ?? 0 });
    } catch (error) {
      console.error("Error fetching fraud detections:", error);
      res.status(500).json({ message: "Failed to fetch fraud detections" });
    }
  });

  // GET /api/corporate/invoicing/fraud-playbook/pattern-counts
  // Returns live exception count per pattern type (Owner only)
  app.get("/api/corporate/invoicing/fraud-playbook/pattern-counts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");

      const rows = await dbConn.execute(sqlFn.raw(`
        SELECT type, COUNT(*)::int AS open_count
        FROM financial_exceptions
        WHERE status = 'open'
        GROUP BY type
      `)) as any[];

      const counts: Record<string, number> = {};
      for (const row of rows) {
        counts[(row as any).type] = (row as any).open_count ?? 0;
      }
      res.json({ counts });
    } catch (error) {
      console.error("Error fetching pattern counts:", error);
      res.status(500).json({ message: "Failed to fetch pattern counts" });
    }
  });

  // PATCH /api/corporate/invoicing/fraud-playbook/detections/:id/review
  // Mark a detection as reviewed (Owner only)
  app.patch("/api/corporate/invoicing/fraud-playbook/detections/:id/review", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { id } = req.params;
      const userId = req.user.claims.sub;
      await dbConn.execute(sqlFn.raw(`
        UPDATE financial_exceptions
        SET reviewed_at = NOW(), reviewed_by_user_id = '${userId.replace(/'/g, "''")}'
        WHERE id = '${id.replace(/'/g, "''")}'
      `));
      const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
      writeFinancialAuditEvent({
        eventType: 'fraud_playbook.detection_reviewed',
        actorUserId: userId,
        actorUserEmail: guard.user?.email ?? null,
        targetEntityType: 'financial_exception',
        targetEntityId: id,
        ipAddress: req.ip,
      }).catch(() => {});
      res.json({ success: true, reviewedAt: new Date().toISOString(), reviewedByUserId: userId });
    } catch (error) {
      console.error("Error marking detection reviewed:", error);
      res.status(500).json({ message: "Failed to mark detection as reviewed" });
    }
  });

  // PATCH /api/corporate/invoicing/fraud-playbook/detections/:id/notes
  // Add or update investigation notes on a detection (Owner only)
  app.patch("/api/corporate/invoicing/fraud-playbook/detections/:id/notes", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { id } = req.params;
      const { notes } = req.body;
      if (typeof notes !== 'string') return res.status(400).json({ message: "notes must be a string" });
      await dbConn.execute(sqlFn.raw(`
        UPDATE financial_exceptions
        SET notes = '${notes.replace(/'/g, "''")}'
        WHERE id = '${id.replace(/'/g, "''")}'
      `));
      const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
      writeFinancialAuditEvent({
        eventType: 'fraud_playbook.detection_notes_updated',
        actorUserId: req.user.claims.sub,
        actorUserEmail: guard.user?.email ?? null,
        targetEntityType: 'financial_exception',
        targetEntityId: id,
        newValue: { notes },
        ipAddress: req.ip,
      }).catch(() => {});
      res.json({ success: true });
    } catch (error) {
      console.error("Error updating detection notes:", error);
      res.status(500).json({ message: "Failed to update notes" });
    }
  });

  // PATCH /api/corporate/invoicing/fraud-playbook/detections/:id/escalate
  // Flag a detection for escalation (Owner only)
  app.patch("/api/corporate/invoicing/fraud-playbook/detections/:id/escalate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const guard = await requireFraudPlaybookAccess(req, res);
      if (!guard) return;
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { id } = req.params;
      const userId = req.user.claims.sub;
      const { escalated = true } = req.body;
      await dbConn.execute(sqlFn.raw(`
        UPDATE financial_exceptions
        SET escalated = ${escalated ? 'TRUE' : 'FALSE'},
            escalated_at = ${escalated ? 'NOW()' : 'NULL'},
            escalated_by_user_id = ${escalated ? `'${userId.replace(/'/g, "''")}'` : 'NULL'}
        WHERE id = '${id.replace(/'/g, "''")}'
      `));
      const { writeFinancialAuditEvent } = await import("./services/financialIntegrityService");
      writeFinancialAuditEvent({
        eventType: escalated ? 'fraud_playbook.detection_escalated' : 'fraud_playbook.detection_deescalated',
        actorUserId: userId,
        actorUserEmail: guard.user?.email ?? null,
        targetEntityType: 'financial_exception',
        targetEntityId: id,
        ipAddress: req.ip,
      }).catch(() => {});
      res.json({ success: true, escalated, escalatedAt: escalated ? new Date().toISOString() : null });
    } catch (error) {
      console.error("Error escalating detection:", error);
      res.status(500).json({ message: "Failed to escalate detection" });
    }
  });

