  // POST /api/corporate/invoicing/billing-documents — upload new document
  app.post("/api/corporate/invoicing/billing-documents", isAuthenticated, async (req: any, res: Response) => {
    const multerLib = (await import("multer")).default;
    const billingDocUpload = multerLib({ storage: multerLib.memoryStorage(), limits: { fileSize: 20 * 1024 * 1024 } });
    await new Promise<void>((resolve, reject) => billingDocUpload.single("file")(req, res as any, (err: any) => err ? reject(err) : resolve()));
    {
      try {
        const user = await storage.getUser(req.user.claims.sub);
        if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
        if (!req.file) return res.status(400).json({ message: "No file provided" });
        if (!["application/pdf", "image/png", "image/jpeg"].includes(req.file.mimetype)) {
          return res.status(400).json({ message: "Only PDF, PNG, and JPEG files are allowed" });
        }

        const { billingDocuments } = await import("../shared/schema");
        const { eq: eqFn, and: andFn } = await import("drizzle-orm");
        const docType = (req.body.documentType || "w9").toLowerCase();
        const displayName = req.body.displayName || `W-9 — ${new Date().getFullYear()}`;
        const effectiveDate = req.body.effectiveDate || null;
        const notes = req.body.notes || null;

        // Archive any existing active documents of same type
        await db
          .update(billingDocuments)
          .set({ status: "archived", archivedAt: new Date(), archivedBy: user!.id })
          .where(andFn(eqFn(billingDocuments.documentType, docType), eqFn(billingDocuments.status, "active")));

        // Store file
        const storageKey = `.private/billing-documents/${docType}/${Date.now()}-${req.file.originalname}`;
        const provider = getStorageProvider();
        if (provider === "s3") {
          const s3 = getS3StorageService();
          await s3.uploadToKey(storageKey, req.file.buffer, req.file.mimetype);
        } else {
          const { Client: ReplClient } = await import("@replit/object-storage");
          const client = new ReplClient({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID! });
          const result = await client.uploadFromBytes(storageKey, req.file.buffer);
          if (!result.ok) {
            return res.status(500).json({ message: "Failed to upload file to storage" });
          }
        }

        const [doc] = await db
          .insert(billingDocuments)
          .values({
            documentType:  docType,
            displayName,
            fileName:      req.file.originalname,
            storageKey,
            contentType:   req.file.mimetype,
            fileSizeBytes: req.file.buffer.length,
            effectiveDate: effectiveDate || null,
            status:        "active",
            notes,
            uploadedBy:    user!.id,
          })
          .returning();

        writeFinancialAuditEvent({
          eventType: "billing_document.upload",
          actorUserId: user!.id,
          actorUserEmail: user?.email ?? null,
          actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
          targetEntityType: "billing_document",
          targetEntityId:   doc.id,
          targetEntityLabel: doc.fileName,
          notes: `Uploaded new active ${docType.toUpperCase()}: ${doc.fileName}`,
          metadata: { documentType: docType, displayName, effectiveDate },
          ipAddress: req.ip,
        }).catch(() => {});

        res.status(201).json(doc);
      } catch (err) {
        console.error("[BillingDocs] upload error:", err);
        res.status(500).json({ message: "Failed to upload billing document" });
      }
    }
  });

  // PATCH /api/corporate/invoicing/billing-documents/:id/archive — manually archive
  app.patch("/api/corporate/invoicing/billing-documents/:id/archive", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { billingDocuments } = await import("../shared/schema");
      const { eq: eqFn } = await import("drizzle-orm");
      const [doc] = await db
        .update(billingDocuments)
        .set({ status: "archived", archivedAt: new Date(), archivedBy: user!.id })
        .where(eqFn(billingDocuments.id, req.params.id))
        .returning();
      if (!doc) return res.status(404).json({ message: "Document not found" });

      writeFinancialAuditEvent({
        eventType: "billing_document.archive",
        actorUserId: user!.id,
        actorUserEmail: user?.email ?? null,
        actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
        targetEntityType: "billing_document",
        targetEntityId: doc.id,
        targetEntityLabel: doc.fileName,
        notes: `Archived billing document: ${doc.fileName}`,
        metadata: {},
        ipAddress: req.ip,
      }).catch(() => {});

      res.json(doc);
    } catch (err) {
      console.error("[BillingDocs] archive error:", err);
      res.status(500).json({ message: "Failed to archive document" });
    }
  });

  // GET /api/corporate/invoicing/billing-documents/:id/download — admin download
  app.get("/api/corporate/invoicing/billing-documents/:id/download", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { billingDocuments } = await import("../shared/schema");
      const { eq: eqFn } = await import("drizzle-orm");
      const [doc] = await db.select().from(billingDocuments).where(eqFn(billingDocuments.id, req.params.id)).limit(1);
      if (!doc) return res.status(404).json({ message: "Document not found" });

      const provider = getStorageProvider();
      let fileBuffer: Buffer;
      if (provider === "s3") {
        const s3 = getS3StorageService();
        fileBuffer = await s3.downloadByKey(doc.storageKey);
      } else {
        const { Client: ReplClient } = await import("@replit/object-storage");
        const client = new ReplClient({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID! });
        const result = await client.downloadAsBytes(doc.storageKey);
        if (!result.ok || !result.value) {
          return res.status(404).json({ message: "File not found in storage" });
        }
        fileBuffer = Buffer.from(result.value);
      }

      const safeFileName = doc.fileName.replace(/[^a-zA-Z0-9._-]/g, "_");
      res.set({
        "Content-Type":        doc.contentType ?? "application/pdf",
        "Content-Disposition": `attachment; filename="${safeFileName}"`,
        "Content-Length":      String(fileBuffer.length),
      });
      res.send(fileBuffer);
    } catch (err) {
      console.error("[BillingDocs] admin download error:", err);
      res.status(500).json({ message: "Failed to download document" });
    }
  });

  // ==========================================
  // ROLLOUT CONTROL CHECKLIST
  // ==========================================

  // Predefined checklist template items (seeded when a checklist is created)
  // Role definitions for checklist authorization
  const CHECKLIST_OWNER_ROLES      = ["super_user", "super_admin", "root_super_admin"];
  const CHECKLIST_CONTROLLER_ROLES = ["finance", "admin", "corporate_admin", ...CHECKLIST_OWNER_ROLES];
  const CHECKLIST_BILLING_ROLES    = ["billing", "finance", "admin", "corporate_admin", ...CHECKLIST_OWNER_ROLES];

  function checklistRoleAuthorized(userRole: string | undefined, requiredRole: string): boolean {
    if (!userRole) return false;
    if (CHECKLIST_OWNER_ROLES.includes(userRole)) return true; // Owner can do anything
    if (requiredRole === "billing_team") return CHECKLIST_BILLING_ROLES.includes(userRole);
    if (requiredRole === "controller")   return CHECKLIST_CONTROLLER_ROLES.includes(userRole);
    if (requiredRole === "owner")        return CHECKLIST_OWNER_ROLES.includes(userRole);
    return false;
  }

  // Ticket-specified items with role assignment per section
  const CHECKLIST_TEMPLATE = [
    // A. Invoice Accuracy Checks — Billing Team
    { section: "invoice_accuracy",     requiredRole: "billing_team", label: "Compare DriverHub vs legacy invoice",         description: "Side-by-side comparison of DriverHub-generated invoices against the legacy invoicing system to identify discrepancies.",         sortOrder: 1 },
    { section: "invoice_accuracy",     requiredRole: "billing_team", label: "Validate move counts",                        description: "Confirm the number of completed moves billed in DriverHub matches source dispatch records for the period.",                       sortOrder: 2 },
    { section: "invoice_accuracy",     requiredRole: "billing_team", label: "Validate labor hours",                        description: "Verify that labor hours captured in invoices align with time clock and scheduling records for each customer.",                      sortOrder: 3 },
    { section: "invoice_accuracy",     requiredRole: "billing_team", label: "Validate pricing and rates",                  description: "Confirm all pricing and rate structures applied match the contracted rates on file for each account.",                             sortOrder: 4 },
    // B. Revenue Completeness — Billing Team
    { section: "revenue_completeness", requiredRole: "billing_team", label: "Confirm all completed moves invoiced",        description: "Verify every move marked complete in the system has a corresponding invoice line item for the billing period.",                   sortOrder: 1 },
    { section: "revenue_completeness", requiredRole: "billing_team", label: "Confirm all labor accounted for",             description: "Ensure all worked hours from scheduling are included in invoiced labor charges — no missing time.",                               sortOrder: 2 },
    { section: "revenue_completeness", requiredRole: "billing_team", label: "Confirm all rideshare captured",              description: "Validate that all rideshare and ancillary service charges are included and correctly attributed in the billing run.",                sortOrder: 3 },
    // C. Payment & Posting — Billing Team
    { section: "payment_posting",      requiredRole: "billing_team", label: "Confirm payments tied to invoices",           description: "Ensure all received payments are applied to the correct invoice records with no orphaned payment entries.",                        sortOrder: 1 },
    { section: "payment_posting",      requiredRole: "billing_team", label: "Confirm no unapplied payments",               description: "Verify the unapplied payment balance is zero or all exceptions are documented and escalated.",                                    sortOrder: 2 },
    { section: "payment_posting",      requiredRole: "billing_team", label: "Confirm no duplicate payments",               description: "Run the duplicate payment detection check and confirm no duplicate payment entries exist for the period.",                          sortOrder: 3 },
    // D. Deposit Validation — Controller
    { section: "deposit_validation",   requiredRole: "controller",   label: "Confirm payments match deposit batches",      description: "Verify every received payment is assigned to a deposit batch and no payments are undeposited.",                                  sortOrder: 1 },
    { section: "deposit_validation",   requiredRole: "controller",   label: "Confirm deposit totals match expected",       description: "Reconcile each deposit batch total against the expected deposit amount and bank statement entries for the period.",                sortOrder: 2 },
    // E. Exception Review — Controller
    { section: "exception_review",     requiredRole: "controller",   label: "Review manual payments",                      description: "Inspect every manual/offline payment entry for proper documentation, approval, and application.",                                  sortOrder: 1 },
    { section: "exception_review",     requiredRole: "controller",   label: "Review adjustments",                          description: "Evaluate all payment and invoice adjustment entries for legitimacy, documentation, and authorization.",                             sortOrder: 2 },
    { section: "exception_review",     requiredRole: "controller",   label: "Review reversals",                            description: "Examine all payment reversals for appropriate justification, documentation, and management sign-off.",                             sortOrder: 3 },
  ];

  // GET /api/corporate/invoicing/rollout-checklist
  // Returns most recent checklist (or empty if none exist)
  app.get("/api/corporate/invoicing/rollout-checklist", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");

      // Get the most recent checklist with its items
      const [checklist] = await dbConn.execute(sqlFn.raw(`
        SELECT rc.*, 
               u_created.name AS created_by_name,
               u_cert.name    AS certified_by_name,
               u_reopen.name  AS reopened_by_name
        FROM rollout_checklists rc
        LEFT JOIN users u_created ON u_created.id = rc.created_by
        LEFT JOIN users u_cert    ON u_cert.id    = rc.certified_by
        LEFT JOIN users u_reopen  ON u_reopen.id  = rc.reopened_by
        ORDER BY rc.created_at DESC
        LIMIT 1
      `)) as any[];

      if (!checklist) return res.json({ checklist: null, items: [], audit: [] });

      const items = await dbConn.execute(sqlFn.raw(`
        SELECT rci.*,
               u.name AS completed_by_name
        FROM rollout_checklist_items rci
        LEFT JOIN users u ON u.id = rci.completed_by
        WHERE rci.checklist_id = '${checklist.id}'
        ORDER BY rci.section, rci.sort_order
      `)) as any[];

      const audit = await dbConn.execute(sqlFn.raw(`
        SELECT rca.*, u.name AS actor_name
        FROM rollout_checklist_audit rca
        LEFT JOIN users u ON u.id = rca.actor_id
        WHERE rca.checklist_id = '${checklist.id}'
        ORDER BY rca.created_at DESC
        LIMIT 50
      `)) as any[];

      res.json({ checklist, items, audit });
    } catch (err) {
      console.error("Error fetching rollout checklist:", err);
      res.status(500).json({ message: "Failed to fetch rollout checklist" });
    }
  });

  // POST /api/corporate/invoicing/rollout-checklist
  // Create a new checklist for a period (seeds all template items)
  app.post("/api/corporate/invoicing/rollout-checklist", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { periodLabel } = req.body;
      if (!periodLabel?.trim()) return res.status(400).json({ message: "periodLabel is required" });

      // Create the checklist
      const [newChecklist] = await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklists (period_label, status, created_by)
        VALUES ('${periodLabel.trim().replace(/'/g, "''")}', 'in_progress', '${user!.id}')
        RETURNING *
      `)) as any[];

      // Seed template items (includes required_role)
      const valueRows = CHECKLIST_TEMPLATE.map(t =>
        `('${newChecklist.id}', '${t.section}', '${t.label.replace(/'/g, "''")}', '${(t.description || "").replace(/'/g, "''")}', ${t.sortOrder}, 'not_started', '${(t as any).requiredRole ?? "billing_team"}')`
      ).join(", ");
      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_items (checklist_id, section, label, description, sort_order, status, required_role)
        VALUES ${valueRows}
      `));

      // Audit
      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_audit (checklist_id, action, actor_id, actor_name, notes)
        VALUES ('${newChecklist.id}', 'checklist_created', '${user!.id}', '${(user!.name || user!.email || "").replace(/'/g, "''")}', 'Checklist created for period: ${periodLabel.trim().replace(/'/g, "''")}')
      `));

      res.status(201).json({ checklist: newChecklist });
    } catch (err) {
      console.error("Error creating rollout checklist:", err);
      res.status(500).json({ message: "Failed to create rollout checklist" });
    }
  });

  // PATCH /api/corporate/invoicing/rollout-checklist/items/:itemId/complete
  // Mark an item complete — enforces required_role, captures user + timestamp
  app.patch("/api/corporate/invoicing/rollout-checklist/items/:itemId/complete", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { itemId } = req.params;
      const { notes } = req.body;

      // Load item + checklist state + required role
      const [item] = await dbConn.execute(sqlFn.raw(`
        SELECT rci.*, rc.status AS checklist_status
        FROM rollout_checklist_items rci
        JOIN rollout_checklists rc ON rc.id = rci.checklist_id
        WHERE rci.id = '${itemId}'
      `)) as any[];
      if (!item) return res.status(404).json({ message: "Item not found" });
      if (item.checklist_status === "certified") {
        return res.status(400).json({ message: "Checklist is certified and read-only. Only an Owner can reopen it.", error_code: "CHECKLIST_CERTIFIED" });
      }

      // ── Role enforcement ──────────────────────────────────────────────────
      const requiredRole = item.required_role ?? "billing_team";
      if (!checklistRoleAuthorized(user?.role, requiredRole)) {
        const roleLabel = requiredRole === "billing_team" ? "Billing Team" : requiredRole === "controller" ? "Controller" : "Owner";
        return res.status(403).json({
          message: `This item requires ${roleLabel} access to complete.`,
          error_code: "CHECKLIST_ROLE_REQUIRED",
          required_role: requiredRole,
        });
      }

      const prevStatus = item.status;
      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklist_items
        SET status = 'completed',
            completed_by = '${user!.id}',
            completed_at = NOW(),
            notes = ${notes ? `'${notes.replace(/'/g, "''")}'` : 'NULL'},
            reopen_reason = NULL,
            updated_at = NOW()
        WHERE id = '${itemId}'
      `));
      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklists SET updated_at = NOW() WHERE id = '${item.checklist_id}'
      `));

      // Enhanced audit log with before/after status + section
      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_audit (checklist_id, item_id, action, actor_id, actor_name, notes, metadata, before_status, after_status, checklist_section)
        VALUES ('${item.checklist_id}', '${itemId}', 'item_completed', '${user!.id}',
                '${(user!.name || user!.email || "").replace(/'/g, "''")}',
                ${notes ? `'${notes.replace(/'/g, "''")}'` : 'NULL'},
                '{"label":"${item.label.replace(/"/g, '\\"')}","required_role":"${requiredRole}"}',
                '${prevStatus}', 'completed', '${item.section}')
      `));

      res.json({ ok: true });
    } catch (err) {
      console.error("Error completing checklist item:", err);
      res.status(500).json({ message: "Failed to complete item" });
    }
  });

  // PATCH /api/corporate/invoicing/rollout-checklist/items/:itemId/reopen
  // Reopen an item — requires a reason
  app.patch("/api/corporate/invoicing/rollout-checklist/items/:itemId/reopen", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { itemId } = req.params;
      const { reason } = req.body;
      if (!reason?.trim()) return res.status(400).json({ message: "A reason is required to reopen an item." });

      const [item] = await dbConn.execute(sqlFn.raw(`
        SELECT rci.*, rc.status AS checklist_status
        FROM rollout_checklist_items rci
        JOIN rollout_checklists rc ON rc.id = rci.checklist_id
        WHERE rci.id = '${itemId}'
      `)) as any[];
      if (!item) return res.status(404).json({ message: "Item not found" });
      if (item.checklist_status === "certified") return res.status(400).json({ message: "Checklist is certified. Only an Owner can reopen the entire checklist.", error_code: "CHECKLIST_CERTIFIED" });

      // Role enforcement for reopen — same required role or Owner
      const requiredRole = item.required_role ?? "billing_team";
      if (!checklistRoleAuthorized(user?.role, requiredRole)) {
        const roleLabel = requiredRole === "billing_team" ? "Billing Team" : requiredRole === "controller" ? "Controller" : "Owner";
        return res.status(403).json({ message: `This item requires ${roleLabel} access to reopen.`, error_code: "CHECKLIST_ROLE_REQUIRED", required_role: requiredRole });
      }

      const prevStatus = item.status;
      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklist_items
        SET status = 'reopened',
            completed_by = NULL,
            completed_at = NULL,
            reopen_reason = '${reason.trim().replace(/'/g, "''")}',
            updated_at = NOW()
        WHERE id = '${itemId}'
      `));
      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklists SET updated_at = NOW() WHERE id = '${item.checklist_id}'
      `));

      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_audit (checklist_id, item_id, action, actor_id, actor_name, notes, metadata, before_status, after_status, checklist_section)
        VALUES ('${item.checklist_id}', '${itemId}', 'item_reopened', '${user!.id}',
                '${(user!.name || user!.email || "").replace(/'/g, "''")}',
                '${reason.trim().replace(/'/g, "''")}',
                '{"label":"${item.label.replace(/"/g, '\\"')}","required_role":"${requiredRole}"}',
                '${prevStatus}', 'reopened', '${item.section}')
      `));

      res.json({ ok: true });
    } catch (err) {
      console.error("Error reopening checklist item:", err);
      res.status(500).json({ message: "Failed to reopen item" });
    }
  });

  // PATCH /api/corporate/invoicing/rollout-checklist/items/:itemId/notes
  // Update notes on a completed item without changing status
  app.patch("/api/corporate/invoicing/rollout-checklist/items/:itemId/notes", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { itemId } = req.params;
      const { notes } = req.body;

      const [item] = await dbConn.execute(sqlFn.raw(`
        SELECT rci.*, rc.status AS checklist_status
        FROM rollout_checklist_items rci
        JOIN rollout_checklists rc ON rc.id = rci.checklist_id
        WHERE rci.id = '${itemId}'
      `)) as any[];
      if (!item) return res.status(404).json({ message: "Item not found" });
      if (item.checklist_status === "certified") return res.status(400).json({ message: "Checklist is certified and read-only." });

      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklist_items
        SET notes = ${notes ? `'${notes.replace(/'/g, "''")}'` : 'NULL'},
            updated_at = NOW()
        WHERE id = '${itemId}'
      `));

      res.json({ ok: true });
    } catch (err) {
      console.error("Error updating item notes:", err);
      res.status(500).json({ message: "Failed to update notes" });
    }
  });

  // POST /api/corporate/invoicing/rollout-checklist/:id/certify
  // Submit checklist for certification — OWNER ONLY, requires all items complete
  app.post("/api/corporate/invoicing/rollout-checklist/:id/certify", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      // Only Owner can certify
      if (!CHECKLIST_OWNER_ROLES.includes(user?.role ?? "")) {
        return res.status(403).json({ message: "Only an Owner (super_user, super_admin, root_super_admin) can submit final certification.", error_code: "OWNER_REQUIRED" });
      }
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { id } = req.params;
      const { notes, confirmed } = req.body;
      if (!confirmed) return res.status(400).json({ message: "Certification requires explicit confirmation." });

      // Validate all items complete
      const [incomplete] = await dbConn.execute(sqlFn.raw(`
        SELECT COUNT(*) AS cnt
        FROM rollout_checklist_items
        WHERE checklist_id = '${id}' AND status != 'completed'
      `)) as any[];
      if (parseInt(incomplete?.cnt ?? "1") > 0) {
        return res.status(400).json({ message: "All checklist items must be completed before certification.", incompleteCount: parseInt(incomplete?.cnt ?? "0") });
      }

      const [checklist] = await dbConn.execute(sqlFn.raw(`
        SELECT * FROM rollout_checklists WHERE id = '${id}'
      `)) as any[];
      if (!checklist) return res.status(404).json({ message: "Checklist not found" });
      if (checklist.status === "certified") return res.status(400).json({ message: "Checklist is already certified." });

      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklists
        SET status = 'certified',
            certified_by = '${user!.id}',
            certified_at = NOW(),
            certification_notes = ${notes ? `'${notes.replace(/'/g, "''")}'` : 'NULL'},
            updated_at = NOW()
        WHERE id = '${id}'
      `));

      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_audit (checklist_id, action, actor_id, actor_name, notes)
        VALUES ('${id}', 'checklist_certified', '${user!.id}', '${(user!.name || user!.email || "").replace(/'/g, "''")}', ${notes ? `'${notes.replace(/'/g, "''")}'` : 'NULL'})
      `));

      res.json({ ok: true });
    } catch (err) {
      console.error("Error certifying checklist:", err);
      res.status(500).json({ message: "Failed to certify checklist" });
    }
  });

  // POST /api/corporate/invoicing/rollout-checklist/:id/reopen
  // Reopen a certified checklist — Owner only
  app.post("/api/corporate/invoicing/rollout-checklist/:id/reopen", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const OWNER_ROLES = ["super_user", "super_admin", "root_super_admin"];
      if (!OWNER_ROLES.includes(user?.role ?? "")) {
        return res.status(403).json({ message: "Only Owners can reopen a certified checklist." });
      }
      const { db: dbConn } = await import("./db");
      const { sql: sqlFn } = await import("drizzle-orm");
      const { id } = req.params;
      const { reason } = req.body;
      if (!reason?.trim()) return res.status(400).json({ message: "A reason is required to reopen a certified checklist." });

      const [checklist] = await dbConn.execute(sqlFn.raw(`SELECT * FROM rollout_checklists WHERE id = '${id}'`)) as any[];
      if (!checklist) return res.status(404).json({ message: "Checklist not found" });
      if (checklist.status !== "certified") return res.status(400).json({ message: "Checklist is not in certified state." });

      await dbConn.execute(sqlFn.raw(`
        UPDATE rollout_checklists
        SET status = 'reopened',
            reopened_by = '${user!.id}',
            reopened_at = NOW(),
            reopen_reason = '${reason.trim().replace(/'/g, "''")}',
            updated_at = NOW()
        WHERE id = '${id}'
      `));

      await dbConn.execute(sqlFn.raw(`
        INSERT INTO rollout_checklist_audit (checklist_id, action, actor_id, actor_name, notes)
        VALUES ('${id}', 'checklist_reopened', '${user!.id}', '${(user!.name || user!.email || "").replace(/'/g, "''")}', '${reason.trim().replace(/'/g, "''")}')
      `));

      res.json({ ok: true });
    } catch (err) {
      console.error("Error reopening checklist:", err);
      res.status(500).json({ message: "Failed to reopen checklist" });
    }
  });

  // GET /api/corporate/invoicing/rollout-checklist/:id/audit
