  // Create credit memo
  app.post("/api/corporate/invoicing/credit-memos", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const invUser = { id: req.user.claims.sub, email: user?.email || "", role: user?.role };
      assertInvoicingPermission(invUser, 'invoice:issue_credit', 'credit_memo_create');
      const creditMemoNumber = await storage.generateCreditMemoNumber();
      const memo = await storage.createCreditMemo({
        ...req.body,
        creditMemoNumber,
        createdBy: req.user.claims.sub,
      });
      await storage.logInvoicingAction({
        userId: req.user.claims.sub,
        action: "credit_memo_create",
        resourceType: "credit_memo",
        resourceId: memo.id,
        details: { creditMemoNumber, amount: req.body.amount },
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] || null,
      });
      writeFinancialAuditEvent({
        eventType: 'credit_memo.created',
        actorUserId: req.user.claims.sub,
        actorUserEmail: user?.email ?? null,
        actorUserName: user ? `${user.firstName || ''} ${user.lastName || ''}`.trim() || user.email || null : null,
        targetEntityType: 'credit_memo',
        targetEntityId: memo.id,
        targetEntityLabel: creditMemoNumber,
        newValue: { creditMemoNumber, amount: req.body.amount, customerId: req.body.customerId, reason: req.body.reason },
        ipAddress: req.ip,
      }).catch(() => {});
      res.json(memo);
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error creating credit memo:", error);
      res.status(500).json({ message: "Failed to create credit memo" });
    }
  });

