  // ============================================
  // STRIPE WEBHOOK ENDPOINT
  // ============================================

  // POST /api/webhooks/stripe - Handle Stripe webhook events
  // Handles: payment_intent.succeeded/processing/payment_failed/canceled,
  //          charge.refunded, charge.dispute.created
  // Every event is logged to stripe_webhook_events (idempotent).
  app.post("/api/webhooks/stripe", async (req: Request, res: Response) => {
    const webhookSecret = process.env.STRIPE_WEBHOOK_SECRET;

    if (!webhookSecret) {
      console.warn('[Stripe Webhook] STRIPE_WEBHOOK_SECRET not configured');
      return res.status(500).json({ error: 'Webhook secret not configured' });
    }

    const signature = req.headers['stripe-signature'] as string;
    if (!signature) {
      return res.status(400).json({ error: 'Missing stripe-signature header' });
    }

    let event: any;
    try {
      const rawBody = (req as any).rawBody;
      event = constructWebhookEvent(rawBody, signature, webhookSecret);
    } catch (err: any) {
      console.error('[Stripe Webhook] Signature verification failed:', err.message);
      return res.status(400).json({ error: 'Webhook signature verification failed' });
    }

    // ── Idempotency guard: check if we've already processed this event ──────
    const [existingLog] = await db.select()
      .from(stripeWebhookEvents)
      .where(eq(stripeWebhookEvents.stripeEventId, event.id))
      .limit(1);

    if (existingLog && existingLog.status === 'processed') {
      console.log('[Stripe Webhook] Duplicate event — already processed:', event.id);
      return res.json({ received: true, status: 'already_processed' });
    }

    // ── Create or update the event log entry ─────────────────────────────────
    const obj: any = event.data.object;
    const stripeObjectId = obj?.id ?? null;
    const rawAmount = obj?.amount ?? obj?.amount_captured ?? null;
    const currency  = obj?.currency ?? null;

    let logId: string;
    if (existingLog) {
      logId = existingLog.id;
    } else {
      const [logRow] = await db.insert(stripeWebhookEvents).values({
        stripeEventId:  event.id,
        eventType:      event.type,
        status:         'received',
        stripeObjectId,
        amount:         rawAmount != null ? String(rawAmount / 100) : null,
        currency:       currency ?? null,
        invoiceId:      obj?.metadata?.invoiceId ?? null,
        rawPayload:     JSON.stringify({ type: event.type, objectId: stripeObjectId }),
      }).returning();
      logId = logRow.id;
    }

    // ── Helper: finalize the log row ─────────────────────────────────────────
    const finalizeLog = async (status: 'processed' | 'failed' | 'skipped', extra?: { paymentId?: string; processingError?: string }) => {
      await db.update(stripeWebhookEvents)
        .set({ status, processedAt: new Date(), ...extra })
        .where(eq(stripeWebhookEvents.id, logId));
    };

    console.log('[Stripe Webhook] Processing event:', event.type, event.id);

    try {
      switch (event.type) {

        // ─────────────────────────────────────────────────────────────────────
        // PAYMENT SUCCEEDED
        // ─────────────────────────────────────────────────────────────────────
        case 'payment_intent.succeeded': {
          const pi = event.data.object as any;
          const invoiceId = pi.metadata?.invoiceId;

          if (!invoiceId) {
            await finalizeLog('skipped');
            break;
          }

          // Idempotency: has this PI already been recorded as a payment?
          const [existingPmt] = await db.select()
            .from(payments)
            .where(eq(payments.stripePaymentIntentId, pi.id))
            .limit(1);

          if (existingPmt) {
            console.log('[Stripe Webhook] Payment already recorded — skipping duplicate');
            await finalizeLog('skipped', { paymentId: existingPmt.id });
            break;
          }

          const [invoice] = await db.select().from(invoices)
            .where(eq(invoices.id, invoiceId)).limit(1);

          if (!invoice) {
            console.error('[Stripe Webhook] Invoice not found:', invoiceId);
            await finalizeLog('failed', { processingError: `Invoice ${invoiceId} not found` });
            break;
          }

          const paymentAmount = pi.amount / 100;
          const currentPaid  = parseFloat(invoice.paidAmount || '0');
          const newPaidAmount = currentPaid + paymentAmount;
          const totalAmount   = parseFloat(invoice.totalAmount);
          const newBalanceDue = Math.max(0, totalAmount - newPaidAmount);

          // Extract card / ACH details from charges
          const chargeDetails = pi.charges?.data?.[0]?.payment_method_details;
          const cardLast4  = chargeDetails?.card?.last4 ?? null;
          const cardBrand  = chargeDetails?.card?.brand ?? null;
          const achLast4   = chargeDetails?.us_bank_account?.last4 ?? null;
          const payMethod  = pi.payment_method_types?.[0] === 'us_bank_account' ? 'us_bank_account' : (pi.payment_method_types?.[0] || 'card');

          const newStatus = newBalanceDue <= 0 ? 'paid' : newPaidAmount > 0 ? 'partially_paid' : invoice.status;

          const [payCountRow] = await db.select({ count: sql<number>`count(*)` }).from(payments);
          const payNumber = `PAY-${String((payCountRow?.count || 0) + 1).padStart(6, '0')}`;

          const [payment] = await db.insert(payments).values({
            paymentNumber: payNumber,
            customerId:    invoice.customerId || '',
            paymentDate:   new Date().toISOString().split('T')[0],
            amount:        String(paymentAmount),
            paymentMethod: payMethod,
            status:        'completed',
            stripePaymentIntentId: pi.id,
            stripeChargeId: pi.latest_charge ?? null,
            cardLast4,
            cardBrand,
            achAccountLast4: achLast4,
            processorFee: pi.application_fee_amount ? String(pi.application_fee_amount / 100) : null,
            netAmount:    String(paymentAmount - (pi.application_fee_amount || 0) / 100),
            appliedAmount: String(paymentAmount),
            unappliedAmount: '0',
            referenceNumber: invoice.invoiceNumber,
            memo: `Online payment for Invoice #${invoice.invoiceNumber}`,
          }).returning();

          await db.insert(paymentApplications).values({
            paymentId:       payment.id,
            invoiceId:       invoice.id,
            amount:          String(paymentAmount),
            matchMethod:     'stripe_webhook',
            matchConfidence: '100',
          });

          await db.update(invoices).set({
            paidAmount:  String(newPaidAmount),
            balanceDue:  String(newBalanceDue),
            status:      newStatus,
            updatedAt:   new Date(),
          }).where(eq(invoices.id, invoice.id));

          await db.insert(arLedgerEntries).values({
            customerId:   invoice.customerId || '',
            entryType:    'payment',
            referenceType: 'payment',
            referenceId:  payment.id,
            entryDate:    new Date().toISOString().split('T')[0],
            description:  `Online payment for Invoice #${invoice.invoiceNumber}`,
            amount:       String(-paymentAmount),
            invoiceId:    invoice.id,
          });

          await finalizeLog('processed', { paymentId: payment.id, processingError: undefined });
          console.log('[Stripe Webhook] Payment recorded:', payment.paymentNumber, '— Invoice now:', newStatus);

          // ── Send receipt email ─────────────────────────────────────────────
          try {
            const [customer] = await db.select().from(customers)
              .where(eq(customers.id, invoice.customerId || '')).limit(1);
            const toEmail = (customer as any)?.billingContactEmail || (customer as any)?.primaryContactEmail || (customer as any)?.customerEmail;
            if (toEmail) {
              const { sendPaymentReceiptEmail } = await import("./emailService");
              await sendPaymentReceiptEmail({
                to:              toEmail,
                customerName:    (customer as any)?.customerName || 'Valued Customer',
                paymentNumber:   payment.paymentNumber,
                invoiceNumber:   invoice.invoiceNumber,
                paymentDate:     new Date().toLocaleDateString('en-US', { month: 'long', day: 'numeric', year: 'numeric' }),
                paymentMethod:   payMethod,
                amount:          String(paymentAmount),
                cardLast4,
                achAccountLast4: achLast4,
                remainingBalance: String(newBalanceDue),
              });
            }
          } catch (emailErr: any) {
            console.error('[Stripe Webhook] Receipt email failed (non-fatal):', emailErr.message);
          }
          break;
        }

        // ─────────────────────────────────────────────────────────────────────
        // PAYMENT PROCESSING (ACH — async settlement, typically 1-4 days)
        // ─────────────────────────────────────────────────────────────────────
        case 'payment_intent.processing': {
          const pi = event.data.object as any;
          const invoiceId = pi.metadata?.invoiceId;

          if (invoiceId) {
            await db.update(invoices).set({
              status:    'payment_processing',
              updatedAt: new Date(),
            }).where(eq(invoices.id, invoiceId));
            console.log('[Stripe Webhook] Invoice marked payment_processing (ACH pending):', invoiceId);
          }
          await finalizeLog('processed');
          break;
        }

        // ─────────────────────────────────────────────────────────────────────
        // PAYMENT FAILED
        // ─────────────────────────────────────────────────────────────────────
        case 'payment_intent.payment_failed': {
          const pi = event.data.object as any;
          const invoiceId = pi.metadata?.invoiceId;
          const failureMsg = pi.last_payment_error?.message || 'Payment was declined';
          const failureCode = pi.last_payment_error?.code || 'payment_failed';

          console.log('[Stripe Webhook] Payment failed for invoice:', invoiceId, '—', failureMsg);

          if (invoiceId) {
            // If invoice was in payment_processing (ACH), revert it to sent
            const [invoice] = await db.select().from(invoices)
              .where(eq(invoices.id, invoiceId)).limit(1);

            if (invoice) {
              const shouldRevertStatus = invoice.status === 'payment_processing';
              if (shouldRevertStatus) {
                await db.update(invoices).set({
                  status:    'sent',
                  updatedAt: new Date(),
                }).where(eq(invoices.id, invoiceId));
              }

              // ── Send failure email ───────────────────────────────────────
              try {
                const [customer] = await db.select().from(customers)
                  .where(eq(customers.id, invoice.customerId || '')).limit(1);
                const toEmail = (customer as any)?.billingContactEmail || (customer as any)?.primaryContactEmail || (customer as any)?.customerEmail;
                if (toEmail) {
                  const baseUrl = process.env.REPL_SLUG
                    ? `https://${process.env.REPL_SLUG}.repl.co`
                    : 'https://app.driverondemand.co';
                  const payLink = (invoice as any).publicToken
                    ? `${baseUrl}/pay/${(invoice as any).publicToken}`
                    : `${baseUrl}/pay`;
                  const { sendPaymentFailureEmail } = await import("./emailService");
                  await sendPaymentFailureEmail({
                    to:            toEmail,
                    customerName:  (customer as any)?.customerName || 'Valued Customer',
                    invoiceNumber: invoice.invoiceNumber,
                    amount:        (invoice as any).balanceDue || invoice.totalAmount,
                    failureReason: failureMsg,
                    paymentLink:   payLink,
                  });
                }
              } catch (emailErr: any) {
                console.error('[Stripe Webhook] Failure email failed (non-fatal):', emailErr.message);
              }
            }
          }

          await finalizeLog('processed', { processingError: `${failureCode}: ${failureMsg}` });
          break;
        }

        // ─────────────────────────────────────────────────────────────────────
        // PAYMENT CANCELED
        // ─────────────────────────────────────────────────────────────────────
        case 'payment_intent.canceled': {
          const pi = event.data.object as any;
          const invoiceId = pi.metadata?.invoiceId;
          console.log('[Stripe Webhook] PaymentIntent canceled:', pi.id, 'reason:', pi.cancellation_reason);

          if (invoiceId) {
            const [invoice] = await db.select().from(invoices)
              .where(eq(invoices.id, invoiceId)).limit(1);
            if (invoice && invoice.status === 'payment_processing') {
              await db.update(invoices).set({ status: 'sent', updatedAt: new Date() })
                .where(eq(invoices.id, invoiceId));
            }
          }
          await finalizeLog('processed');
          break;
        }

        // ─────────────────────────────────────────────────────────────────────
        // CHARGE REFUNDED
        // ─────────────────────────────────────────────────────────────────────
        case 'charge.refunded': {
          const charge = event.data.object as any;
          const piId    = charge.payment_intent;
          const refundTotal = charge.amount_refunded / 100; // total refunded on this charge

          if (!piId) { await finalizeLog('skipped'); break; }

          // Find the matching payment record
          const [payment] = await db.select().from(payments)
            .where(eq(payments.stripePaymentIntentId, piId)).limit(1);

          if (!payment) {
            console.warn('[Stripe Webhook] charge.refunded — payment not found for PI:', piId);
            await finalizeLog('skipped', { processingError: `Payment for PI ${piId} not found` });
            break;
          }

          // Get the invoice linked via payment application
          const [pmtApp] = await db.select().from(paymentApplications)
            .where(eq(paymentApplications.paymentId, payment.id)).limit(1);

          if (pmtApp?.invoiceId) {
            const [invoice] = await db.select().from(invoices)
              .where(eq(invoices.id, pmtApp.invoiceId)).limit(1);

            if (invoice) {
              const origPaid    = parseFloat(invoice.paidAmount || '0');
              const newPaid     = Math.max(0, origPaid - refundTotal);
              const totalAmount = parseFloat(invoice.totalAmount);
              const newBalance  = Math.max(0, totalAmount - newPaid);
              const newStatus   = newPaid <= 0 ? 'sent' : 'partially_paid';

              await db.update(invoices).set({
                paidAmount:  String(newPaid),
                balanceDue:  String(newBalance),
                status:      newStatus,
                updatedAt:   new Date(),
              }).where(eq(invoices.id, invoice.id));

              // AR ledger: debit back
              await db.insert(arLedgerEntries).values({
                customerId:    invoice.customerId || '',
                entryType:     'refund',
                referenceType: 'payment',
                referenceId:   payment.id,
                entryDate:     new Date().toISOString().split('T')[0],
                description:   `Refund of online payment for Invoice #${invoice.invoiceNumber}`,
                amount:        String(refundTotal), // positive = money owed again
                invoiceId:     invoice.id,
              });

              console.log('[Stripe Webhook] Refund processed — Invoice', invoice.invoiceNumber, 'reverted to', newStatus);
            }
          }

          await finalizeLog('processed', { paymentId: payment.id });
          break;
        }

        // ─────────────────────────────────────────────────────────────────────
        // DISPUTE CREATED
        // ─────────────────────────────────────────────────────────────────────
        case 'charge.dispute.created': {
          const dispute = event.data.object as any;
          const piId = dispute.payment_intent;
          console.warn('[Stripe Webhook] Dispute created for PI:', piId, '— amount:', dispute.amount / 100, dispute.currency);

          if (piId) {
            const [payment] = await db.select().from(payments)
              .where(eq(payments.stripePaymentIntentId, piId)).limit(1);
            if (payment) {
              // Flag payment status as disputed
              await db.update(payments).set({
                status:     'disputed',
                failureMessage: `Dispute filed: ${dispute.reason || 'unknown reason'} — $${(dispute.amount / 100).toFixed(2)}`,
              } as any).where(eq(payments.id, payment.id));
              await finalizeLog('processed', { paymentId: payment.id });
              break;
            }
          }
          await finalizeLog('processed');
          break;
        }

        default:
          console.log('[Stripe Webhook] Unhandled event type:', event.type);
          await finalizeLog('skipped');
      }

      res.json({ received: true });
    } catch (error: any) {
      console.error('[Stripe Webhook] Error processing event:', error);
      try {
        await db.update(stripeWebhookEvents).set({
          status: 'failed',
          processingError: error?.message || 'Unknown error',
          processedAt: new Date(),
        }).where(eq(stripeWebhookEvents.id, logId));
      } catch { /* ignore secondary failure */ }
      res.status(500).json({ error: 'Webhook processing failed' });
    }
  });

