      await logVendorAudit("vendor", req.params.id, "delete", { userId: user!.id, userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id, userRole: user!.role || undefined }, { deletedRecord: existing[0] });
      res.json(vendor);
