  const vendorLogoUpload = (await import("multer")).default({ storage: (await import("multer")).default.memoryStorage(), limits: { fileSize: 5 * 1024 * 1024 } });

  // POST /api/vendors/:id/logo — upload / replace logo
  app.post("/api/vendors/:id/logo", isAuthenticated, vendorLogoUpload.single("logo"), async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:update")) {
        return res.status(403).json({ message: "Access denied" });
      }
      const [existing] = await db.select({ id: vendors.id, logoStorageKey: vendors.logoStorageKey }).from(vendors).where(and(eq(vendors.id, req.params.id), isNull(vendors.deletedAt))).limit(1);
      if (!existing) return res.status(404).json({ message: "Vendor not found" });
      if (!req.file) return res.status(400).json({ message: "No file provided" });

      const allowed = ["image/png", "image/jpeg", "image/webp", "image/gif", "image/svg+xml"];
      if (!allowed.includes(req.file.mimetype)) {
        return res.status(400).json({ message: "Only PNG, JPG, WebP, GIF, and SVG files are accepted" });
      }

      const storageKey = `.private/vendor-logos/${req.params.id}`;
      const svc = new ObjectStorageService();
      await svc.uploadFileWithKey(storageKey, req.file.buffer, req.file.mimetype);

      const [updated] = await db.update(vendors).set({ logoStorageKey: storageKey, updatedAt: new Date() }).where(eq(vendors.id, req.params.id)).returning();
      res.json(updated);
    } catch (err: any) {
      console.error("[VendorLogo] Upload error:", err?.message);
      res.status(500).json({ message: "Failed to upload vendor logo" });
    }
  });

  // GET /api/vendors/:id/logo — serve the logo image
  app.get("/api/vendors/:id/logo", isAuthenticated, async (req: any, res: Response) => {
    try {
      const [v] = await db.select({ logoStorageKey: vendors.logoStorageKey }).from(vendors).where(eq(vendors.id, req.params.id)).limit(1);
      if (!v?.logoStorageKey) return res.status(404).json({ message: "No logo" });

      const result = await getVendorDocBuffer(v.logoStorageKey);
      if ("error" in result) return res.status(result.status).json({ message: result.error });

      const key = v.logoStorageKey.toLowerCase();
      const mime = key.endsWith(".svg") ? "image/svg+xml" : key.endsWith(".png") ? "image/png" : key.endsWith(".webp") ? "image/webp" : key.endsWith(".gif") ? "image/gif" : "image/jpeg";
      res.set({ "Content-Type": mime, "Cache-Control": "private, max-age=300", "Content-Length": String(result.buffer.length) });
      res.send(result.buffer);
    } catch (err: any) {
      console.error("[VendorLogo] Serve error:", err?.message);
      res.status(500).json({ message: "Failed to serve logo" });
    }
  });

  // DELETE /api/vendors/:id/logo — remove logo
  app.delete("/api/vendors/:id/logo", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:update")) {
        return res.status(403).json({ message: "Access denied" });
      }
      const [v] = await db.select({ id: vendors.id, logoStorageKey: vendors.logoStorageKey }).from(vendors).where(eq(vendors.id, req.params.id)).limit(1);
      if (!v) return res.status(404).json({ message: "Vendor not found" });

      if (v.logoStorageKey) {
        try {
          const { Client: ReplClient } = await import("@replit/object-storage");
          const client = new ReplClient({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID });
          await (client as any).delete(v.logoStorageKey);
        } catch { /* non-fatal — storage cleanup best-effort */ }
        await db.update(vendors).set({ logoStorageKey: null, updatedAt: new Date() }).where(eq(vendors.id, req.params.id));
      }
      res.json({ success: true });
    } catch (err: any) {
      console.error("[VendorLogo] Delete error:", err?.message);
      res.status(500).json({ message: "Failed to remove vendor logo" });
    }
  });

