  app.post("/api/vendors/:id/contracts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!user) {
        return res.status(401).json({ message: "User session not found" });
      }
      if (!await resolveVendorAccess(user!.id, user.role, "contract:create")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("contract:create") });
      }
      const vendor = await db.select({ id: vendors.id }).from(vendors).where(and(eq(vendors.id, req.params.id), isNull(vendors.deletedAt))).limit(1);
      if (vendor.length === 0) {
        return res.status(404).json({ message: "Vendor not found" });
      }
      let validated: any;
      try {
        validated = insertVendorContractSchema.parse({ ...req.body, vendorId: req.params.id });
      } catch (zodErr: any) {
        if (zodErr instanceof z.ZodError) {
          console.error("[VendorContracts] Zod validation failed:", JSON.stringify(zodErr.errors));
          return res.status(400).json({ message: "Validation error", errors: zodErr.errors });
        }
        throw zodErr;
      }
      const [contract] = await db.insert(vendorContracts).values(validated).returning();
      await logVendorAudit("vendor_contract", contract.id, "create", { userId: user.id, userName: user.firstName ? `${user.firstName} ${user.lastName || ''}`.trim() : user.email || user.id, userRole: user.role || undefined }, { ...validated });
      res.status(201).json(contract);
    } catch (error: any) {
      console.error("[VendorContracts] Error creating contract — message:", error?.message);
      console.error("[VendorContracts] Error creating contract — stack:", error?.stack);
      console.error("[VendorContracts] Request body was:", JSON.stringify(req.body));
      res.status(500).json({ message: "Failed to create contract", detail: error?.message });
    }
  });

