  app.post("/api/contracts/:contractId/ai-extract", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:read")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:read") });
      }

      const { contractId } = req.params;
      const [contract] = await db.select().from(vendorContracts).where(eq(vendorContracts.id, contractId)).limit(1);
      if (!contract) return res.status(404).json({ message: "Contract not found" });

      // Find a linked document (prefer PDF/DOCX)
      const docs = await db.select().from(vendorDocuments)
        .where(eq(vendorDocuments.contractId, contractId))
        .orderBy(desc(vendorDocuments.uploadedAt));

      const parseable = docs.find(d => {
        const ext = d.fileName.split('.').pop()?.toLowerCase() ?? '';
        return ['pdf', 'doc', 'docx'].includes(ext);
      });
      if (!parseable) {
        return res.status(422).json({ message: "No readable document (PDF or Word) is linked to this contract. Upload one in the Documents tab first." });
      }

      // Download from object storage
      const fetchResult = await getVendorDocBuffer(parseable.storageKey);
      if ("error" in fetchResult) {
        return res.status(fetchResult.status).json({ message: fetchResult.error });
      }
      const fileBuffer = fetchResult.buffer;

      // Parse text
      let documentText = "";
      let pdfIsScanned = false;
      const ext = parseable.fileName.split('.').pop()?.toLowerCase() ?? '';
      try {
        if (ext === 'pdf') {
          const pdfResult = await extractPdfText(fileBuffer);
          documentText = pdfResult.text;
          pdfIsScanned = pdfResult.isScanned;
        } else {
          const mammoth = await import("mammoth");
          const result = await mammoth.extractRawText({ buffer: fileBuffer });
          documentText = result.value;
        }
      } catch (parseErr: any) {
        const errMsg: string = parseErr?.message ?? "";
        console.error("[ContractExtract] Text extraction failed — docId:", parseable.id, "file:", parseable.fileName, "ext:", ext, "bufSize:", fileBuffer.length, "err:", errMsg, parseErr?.stack);
        if (errMsg.startsWith("PASSWORD:")) {
          return res.status(422).json({ message: "This PDF is password-protected. Please remove the password and re-upload." });
        }
        return res.status(422).json({ message: "Could not read this PDF. The file may be corrupt, in an unsupported format, or encrypted." });
      }

      if (!documentText || documentText.trim().length < 50) {
        if (pdfIsScanned) {
          return res.status(422).json({ message: "This PDF contains only scanned images — no text could be extracted. OCR is not yet supported. Please upload a text-based PDF or a Word document." });
        }
        return res.status(422).json({ message: "This PDF has very little readable text. Please ensure it is a text-based PDF, not a scanned image." });
      }

      const truncatedText = documentText.slice(0, 60000);

      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      });

      const systemPrompt = `You are a legal contract analyst. Extract specific structured fields from the provided contract document with precision. Return only valid JSON. Use null for any field you cannot find. Never fabricate values.`;

      const userPrompt = `Extract the following fields from this vendor/supplier contract and return ONLY a valid JSON object with no markdown.

Document:
${truncatedText}

Required JSON structure:
{
  "contractName": "the formal name or title of this agreement as stated in the document, or null",
  "contractType": "one of: MSA | SOW | NDA | Service Agreement | Subscription | Amendment | Other — or null",
  "effectiveDate": "YYYY-MM-DD or null",
  "startDate": "YYYY-MM-DD or null",
  "endDate": "YYYY-MM-DD or null",
  "autoRenewalLanguage": "exact or paraphrased language describing the auto-renewal clause, or null if no auto-renewal",
  "noticePeriod": "string describing the required notice period and method (e.g. '60 days written notice prior to expiration') or null",
  "paymentTerms": "string describing payment terms (e.g. 'Net 30 days from invoice date') or null"
}`;

      let extracted: Record<string, any> = {};
      try {
        const response = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ],
          response_format: { type: "json_object" },
          max_completion_tokens: 800,
        });
        extracted = JSON.parse(response.choices[0]?.message?.content || "{}");
      } catch (aiErr: any) {
        console.error("[ContractExtract] AI call failed:", aiErr?.message);
        return res.status(502).json({ message: "AI extraction failed. Please try again." });
      }

      const [extraction] = await db.insert(contractAiReviews).values({
        vendorId: contract.vendorId,
        contractId,
        documentId: parseable.id,
        extractionType: "field_extraction",
        fileName: parseable.fileName,
        extractedJson: extracted,
        reviewedByAiModel: "gpt-4o",
        reviewedBy: user!.id,
        isEdited: false,
      }).returning();

      res.json(extraction);
    } catch (error: any) {
      console.error("[ContractExtract] Unexpected error:", error?.message, error?.stack);
      res.status(500).json({ message: "Failed to run AI extraction" });
    }
  });

