  app.post("/api/contracts/:contractId/obligations/discover", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "contract:update")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("contract:update") });
      }
      const { contractId } = req.params;
      const [contract] = await db.select().from(vendorContracts).where(eq(vendorContracts.id, contractId)).limit(1);
      if (!contract) return res.status(404).json({ message: "Contract not found" });

      // Find a parseable document linked to this contract
      const allDocs = await db.select().from(vendorDocuments)
        .where(eq(vendorDocuments.contractId, contractId));
      const PARSEABLE_EXTS = ["pdf", "doc", "docx"];
      const parseable = allDocs.find(d => {
        const ext = d.fileName.split(".").pop()?.toLowerCase() ?? "";
        return PARSEABLE_EXTS.includes(ext);
      });
      if (!parseable) {
        return res.status(400).json({ message: "No parseable document (PDF or Word) is linked to this contract. Link a document first." });
      }

      // Extract text
      const fetchResult = await getVendorDocBuffer(parseable.storageKey);
      if ("error" in fetchResult) {
        return res.status(fetchResult.status).json({ message: fetchResult.error });
      }
      const { buffer: fileBuffer } = fetchResult;
      let contractText: string;
      const ext = parseable.fileName.split(".").pop()?.toLowerCase() ?? "";
      if (ext === "pdf") {
        const pdfResult = await extractPdfText(fileBuffer);
        if (pdfResult.isScanned) {
          return res.status(422).json({ message: "This PDF appears to be a scanned image. AI obligation discovery requires a text-based PDF." });
        }
        contractText = pdfResult.text;
      } else {
        const mammoth = await import("mammoth");
        contractText = (await mammoth.extractRawText({ buffer: fileBuffer })).value;
      }
      if (!contractText || contractText.trim().length < 50) {
        return res.status(422).json({ message: "Not enough readable text could be extracted from the linked document. Try uploading a text-based PDF or a .docx file." });
      }

      // Call OpenAI
      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      });
      const systemPrompt = `You are a contract analysis assistant. Carefully read the contract text and identify ALL explicit contractual obligations, requirements, deadlines, or commitments that must be tracked and fulfilled.

Return ONLY a valid JSON object with a single key "obligations" containing an array. Each obligation must have:
- obligationType: one of "insurance", "reporting", "notice", "payment", "sla"
- title: a short, clear title (max 80 chars)
- description: a concise explanation of the obligation (1-2 sentences)
- dueDate: ISO date string (YYYY-MM-DD) if a specific date or deadline is mentioned, otherwise null
- recurrence: one of "none", "monthly", "quarterly", "annually" — based on how often it repeats

Rules:
- Focus on actionable obligations, not general statements
- If a date is relative (e.g. "within 30 days of signing") set dueDate to null
- If the contract has renewal provisions, certificate requirements, reporting duties, SLA commitments, or payment schedules, capture each as a separate obligation
- Return between 1 and 15 obligations
- Return ONLY the JSON object, no other text`;

      const response = await openai.chat.completions.create({
        model: "gpt-4o",
        temperature: 0.1,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: systemPrompt },
          { role: "user", content: `Contract text:\n\n${contractText.slice(0, 40000)}` },
        ],
      });

      const raw = response.choices[0]?.message?.content ?? "{}";
      let parsed: any;
      try {
        parsed = JSON.parse(raw);
      } catch {
        return res.status(500).json({ message: "AI returned malformed JSON. Please try again." });
      }

      // Accept either { obligations: [...] } or [...] directly
      const suggestions: any[] = Array.isArray(parsed) ? parsed : (Array.isArray(parsed.obligations) ? parsed.obligations : []);
      const VALID_TYPES = ["insurance", "reporting", "notice", "payment", "sla"];
      const VALID_RECURRENCE = ["none", "monthly", "quarterly", "annually"];
      const cleaned = suggestions
        .filter(s => s && typeof s.title === "string" && s.title.trim())
        .map(s => ({
          obligationType: VALID_TYPES.includes(s.obligationType) ? s.obligationType : "reporting",
          title: String(s.title).trim().slice(0, 80),
          description: typeof s.description === "string" ? s.description.trim() : null,
          dueDate: typeof s.dueDate === "string" && /^\d{4}-\d{2}-\d{2}$/.test(s.dueDate) ? s.dueDate : null,
          recurrence: VALID_RECURRENCE.includes(s.recurrence) ? s.recurrence : "none",
        }))
        .slice(0, 15);

      res.json({ suggestions: cleaned, documentName: parseable.fileName });
    } catch (error: any) {
      console.error("[ObligationsDiscover] Error:", error?.message, error?.stack);
      const msg = error?.status === 401 || error?.message?.includes("401")
        ? "AI service authentication failed. Please contact support."
        : error?.status === 429 || error?.message?.includes("429")
        ? "AI service rate limit reached. Please wait a moment and try again."
        : error?.message?.includes("timeout") || error?.message?.includes("ETIMEDOUT")
        ? "AI service timed out. Please try again."
        : error?.message || "Obligation discovery failed. Please try again.";
      res.status(500).json({ message: msg });
    }
  });

