  /**
   * Download a vendor document to a Buffer.
   * - Validates the storage key has the correct prefix for the active provider.
   * - Uses ObjectStorageService.downloadToBuffer (stream-based, with existence
   *   check + retries) instead of the broken downloadAsBytes SDK call.
   * Returns { buffer } on success or { error, status } on failure.
   */
  // ── PDF text extraction helper ───────────────────────────────────────────────
  // pdf-parse is broken in this environment (exports pdfjs internals, not a callable).
  // Use pdfjs-dist/legacy directly — tested and confirmed working in Node.js v20.
  //
  // Returns { text, isScanned }:
  //   text      — extracted text, empty string if none found
  //   isScanned — true when the PDF parsed successfully but contained zero text items
  //               (typical of image-only scanned PDFs)
  //
  // Throws for hard failures: invalid structure, password-protected, or timeout.
  // The special message prefix "PASSWORD:" lets callers detect that case.
  let _cachedPdfjsLib: any = null;
  async function extractPdfText(buffer: Buffer): Promise<{ text: string; isScanned: boolean }> {
    if (!_cachedPdfjsLib) {
      _cachedPdfjsLib = await import("pdfjs-dist/legacy/build/pdf.mjs");
    }
    const pdfjsLib = _cachedPdfjsLib;

    // Use a proper view of the underlying ArrayBuffer (handles Buffer byteOffset correctly)
    const uint8 = new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.byteLength);

    const task = pdfjsLib.getDocument({ data: uint8, disableFontFace: true, verbosity: 0 });

    let pdfDoc: any;
    try {
      pdfDoc = await Promise.race([
        task.promise,
        new Promise<never>((_, reject) =>
          setTimeout(() => reject(new Error("PDF processing timed out after 20 seconds")), 20000)
        ),
      ]);
    } catch (loadErr: any) {
      // Re-throw with a recognisable prefix for password-protected PDFs
      const msg: string = loadErr?.message ?? String(loadErr);
      if (/password/i.test(msg) || /PasswordException/.test(msg)) {
        throw new Error("PASSWORD: " + msg);
      }
      throw loadErr;
    }

    let text = "";
    let totalTextItems = 0;
    for (let pageNum = 1; pageNum <= pdfDoc.numPages; pageNum++) {
      const page = await pdfDoc.getPage(pageNum);
      const content = await page.getTextContent();
      totalTextItems += content.items.length;
      const pageText = content.items.map((item: any) => item.str ?? "").join(" ");
      text += pageText + "\n";
    }

    // A PDF with pages but zero text items is almost certainly a scanned image PDF
    const isScanned = pdfDoc.numPages > 0 && totalTextItems === 0;
    return { text: text.trim(), isScanned };
  }

  async function getVendorDocBuffer(storageKey: string): Promise<{ buffer: Buffer } | { error: string; status: number }> {
    const provider = getStorageProvider();
    if (provider === "s3") {
      try {
        const s3 = getS3StorageService();
        const buf = await s3.downloadByKey(storageKey);
        return { buffer: buf };
      } catch {
        return { error: "File not found in storage", status: 404 };
      }
    }
    // Replit Object Storage — key must start with ".private/"
    if (!storageKey.startsWith(".private/")) {
      console.error(`[VendorDocs] Invalid storage key — missing .private/ prefix: "${storageKey}"`);
      return {
        error: "Storage key is invalid. The document may have been uploaded with an old version of the software and needs to be re-uploaded.",
        status: 422,
      };
    }
    const svc = new ObjectStorageService();
    const buf = await svc.downloadToBuffer(storageKey);
    if (!buf) {
      console.error(`[VendorDocs] File not found in storage for key: "${storageKey}"`);
      return { error: "File not found in storage", status: 404 };
    }
    return { buffer: buf };
  }

