  app.patch("/api/vendor-documents/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:upload")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:upload") });
      }
      const [doc] = await db.select().from(vendorDocuments).where(and(eq(vendorDocuments.id, req.params.id), eq(vendorDocuments.isDeleted, false))).limit(1);
      if (!doc) return res.status(404).json({ message: "Document not found" });

      const { documentType, contractId, notes } = req.body;
      const updates: Record<string, any> = {};
      const VALID_TYPES = ["MSA","SOW","W9","COI","Invoice","Contract","PricingSheet","RenewalNotice","TerminationNotice","Other"];
      if (documentType !== undefined) {
        if (!VALID_TYPES.includes(documentType)) return res.status(400).json({ message: "Invalid document type" });
        updates.documentType = documentType;
      }
      if ("contractId" in req.body) {
        if (contractId) {
          const [c] = await db.select({ id: vendorContracts.id }).from(vendorContracts).where(and(eq(vendorContracts.id, contractId), eq(vendorContracts.vendorId, doc.vendorId))).limit(1);
          if (!c) return res.status(400).json({ message: "Contract not found on this vendor" });
        }
        updates.contractId = contractId || null;
      }
      if ("notes" in req.body) updates.notes = notes?.trim() || null;

      if (Object.keys(updates).length === 0) return res.status(400).json({ message: "No valid fields to update" });

      const [updated] = await db.update(vendorDocuments).set(updates).where(eq(vendorDocuments.id, req.params.id)).returning();

      await logVendorAudit('vendor_document', req.params.id, 'update',
        { userId: user!.id, userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id, userRole: user!.role || undefined },
        { changes: updates }
      );
      import("./services/vendorDocAuditService").then(m => m.logDocumentAudit({ vendorId: doc.vendorId, documentId: doc.id, documentName: doc.fileName, documentType: doc.documentType, action: "metadata_update", userId: user!.id, userEmail: (user as any)?.email ?? null, userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ""}`.trim() : null, userRole: user?.role ?? null, ipAddress: req.ip ?? null, metadata: { changes: updates } })).catch(() => {});

      res.json(updated);
    } catch (error: any) {
      console.error("[VendorDocs] Error updating:", error?.message);
      res.status(500).json({ message: "Failed to update document" });
    }
  });

  app.delete("/api/vendor-documents/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:delete")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:delete") });
      }
      const [doc] = await db.select().from(vendorDocuments).where(eq(vendorDocuments.id, req.params.id)).limit(1);
      if (!doc) {
        return res.status(404).json({ message: "Document not found" });
      }
      try {
        const provider = getStorageProvider();
        if (provider === "s3") {
          const s3Service = getS3StorageService();
          await s3Service.deleteByKey(doc.storageKey);
        } else {
          const client = new (await import("@replit/object-storage")).Client({
            bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID!,
          });
          await client.delete(doc.storageKey);
        }
      } catch (storageErr) {
        console.warn("[VendorDocs] Could not delete file from storage:", storageErr);
      }
      // Only Super Admins can delete vendor documents
      const isSuperAdmin = user?.role === 'super_user' || !!(user as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete documents and attachments' });
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      await db.update(vendorDocuments)
        .set({ isDeleted: true, deletedAt: new Date(), deletedByUserId: user!.id, deletionReason: String(deletionReason).trim() })
        .where(eq(vendorDocuments.id, req.params.id));

      if (doc.documentType === "W9") {
        const remainingW9 = await db.select({ id: vendorDocuments.id }).from(vendorDocuments)
          .where(and(eq(vendorDocuments.vendorId, doc.vendorId), eq(vendorDocuments.documentType, "W9"), eq(vendorDocuments.isDeleted, false)))
          .limit(1);
        if (remainingW9.length === 0) {
          await db.update(vendors).set({ w9OnFile: false, updatedAt: new Date() }).where(eq(vendors.id, doc.vendorId));
        }
      }

      await logVendorAudit('vendor_document', req.params.id, 'delete', { userId: user!.id, userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id, userRole: user!.role || undefined }, { deletedRecord: doc, softDelete: true, deletionReason: String(deletionReason).trim() });
      import("./services/vendorDocAuditService").then(m => m.logDocumentAudit({ vendorId: doc.vendorId, documentId: doc.id, documentName: doc.fileName, documentType: doc.documentType, action: "delete", userId: user!.id, userEmail: (user as any)?.email ?? null, userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ""}`.trim() : null, userRole: user?.role ?? null, ipAddress: req.ip ?? null, metadata: { deletionReason: String(deletionReason).trim() } })).catch(() => {});

      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: user!.id,
        actorUserEmail: (user as any)?.email,
        targetEntityType: 'vendor_document',
        targetEntityId: req.params.id,
        targetEntityLabel: doc.fileName,
        reason: String(deletionReason).trim(),
        metadata: { vendorId: doc.vendorId, fileName: doc.fileName, documentType: doc.documentType, restrictedAction: true },
        ipAddress: req.ip,
      });

      res.json({ success: true });
    } catch (error: any) {
      console.error('[VendorDocs] Error deleting document:', error?.message);
      res.status(500).json({ message: 'Failed to delete document' });
    }
  });

