  app.get("/api/vendors/compliance-summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:read")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("vendor:read") });
      }
      const allRecords = await db.select({
        vendorId: vendorCompliance.vendorId,
        expirationDate: vendorCompliance.expirationDate,
        reminderDaysBefore: vendorCompliance.reminderDaysBefore,
        complianceType: vendorCompliance.complianceType,
      }).from(vendorCompliance);

      const summary: Record<string, { expired: number; expiringSoon: number; valid: number; worstStatus: string }> = {};
      for (const r of allRecords) {
        const status = computeComplianceStatus(r.expirationDate, r.reminderDaysBefore);
        if (!summary[r.vendorId]) {
          summary[r.vendorId] = { expired: 0, expiringSoon: 0, valid: 0, worstStatus: "valid" };
        }
        const s = summary[r.vendorId];
        if (status === "expired") { s.expired++; s.worstStatus = "expired"; }
        else if (status === "expiring_soon") { s.expiringSoon++; if (s.worstStatus !== "expired") s.worstStatus = "expiring_soon"; }
        else { s.valid++; }
      }
      res.json(summary);
    } catch (error: any) {
      console.error("[VendorCompliance] Error fetching summary:", error?.message);
      res.status(500).json({ message: "Failed to fetch compliance summary" });
    }
  });

