  // VENDOR SCORECARD ROUTES
  // ========================================

  function calculateOverallScore(quality: number, timeliness: number, support: number, costControl: number): number {
    const weights = { quality: 0.30, timeliness: 0.30, support: 0.20, costControl: 0.20 };
    const weighted = (quality * weights.quality) + (timeliness * weights.timeliness) + (support * weights.support) + (costControl * weights.costControl);
    return Math.round((weighted / 5) * 100);
  }

