  // ── AI Contract Review from Existing Document ────────────────────────────────

  app.post("/api/vendors/:vendorId/contract-ai-review-from-doc", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:read")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:read") });
      }
      const { vendorId } = req.params;
      const { documentId } = req.body;
      if (!documentId) return res.status(400).json({ message: "documentId is required" });

      const [vendor] = await db.select().from(vendors).where(eq(vendors.id, vendorId)).limit(1);
      if (!vendor) return res.status(404).json({ message: "Vendor not found" });

      const [doc] = await db.select().from(vendorDocuments)
        .where(and(eq(vendorDocuments.id, documentId), eq(vendorDocuments.vendorId, vendorId)))
        .limit(1);
      if (!doc) return res.status(404).json({ message: "Document not found or does not belong to this vendor" });

      const ext = doc.fileName.split('.').pop()?.toLowerCase() ?? '';
      if (!['pdf', 'doc', 'docx'].includes(ext)) {
        return res.status(422).json({ message: "Only PDF and Word documents are supported for AI review" });
      }

      const fetchResult = await getVendorDocBuffer(doc.storageKey);
      if ("error" in fetchResult) {
        return res.status(fetchResult.status).json({ message: fetchResult.error });
      }
      const fileBuffer = fetchResult.buffer;

      let documentText = "";
      let pdfIsScanned = false;
      try {
        if (ext === 'pdf') {
          const pdfResult = await extractPdfText(fileBuffer);
          documentText = pdfResult.text;
          pdfIsScanned = pdfResult.isScanned;
        } else {
          const mammoth = await import("mammoth");
          const result = await mammoth.extractRawText({ buffer: fileBuffer });
          documentText = result.value;
        }
      } catch (parseErr: any) {
        const errMsg: string = parseErr?.message ?? "";
        console.error("[AIContractReviewFromDoc] Text extraction failed — docId:", documentId, "file:", doc.fileName, "ext:", ext, "bufSize:", fileBuffer.length, "err:", errMsg, parseErr?.stack);
        if (errMsg.startsWith("PASSWORD:")) {
          return res.status(422).json({ message: "This PDF is password-protected. Please remove the password and re-upload." });
        }
        return res.status(422).json({ message: "Could not read this PDF. The file may be corrupt, in an unsupported format, or encrypted." });
      }

      if (!documentText || documentText.trim().length < 100) {
        if (pdfIsScanned) {
          return res.status(422).json({ message: "This PDF contains only scanned images — no text could be extracted. OCR is not yet supported. Please upload a text-based PDF or a Word document." });
        }
        return res.status(422).json({ message: "This PDF has very little readable text. Please ensure it is a text-based PDF, not a scanned image." });
      }

      const truncatedText = documentText.slice(0, 60000);

      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      });

      const systemPrompt = `You are a legal and business contract analyst specializing in vendor agreements. Your job is to carefully read the provided contract document and extract structured information with high accuracy. Always respond with valid JSON only. If a field cannot be found, use null. Never fabricate values.`;

      const userPrompt = `Analyze the following vendor/supplier agreement and extract the information below. Return ONLY a valid JSON object with no markdown, no code fences.

Document text:
${truncatedText}

Required JSON structure:
{
  "vendorName": "string or null",
  "contractType": "MSA | SOW | Subscription | NDA | Service Agreement | Other | null",
  "effectiveDate": "YYYY-MM-DD or null",
  "startDate": "YYYY-MM-DD or null",
  "endDate": "YYYY-MM-DD or null",
  "autoRenewalClause": "Yes | No | Unclear | null",
  "renewalTerm": "string describing renewal duration or null",
  "noticeOfNonRenewalDeadline": "string describing notice deadline or null",
  "terminationRights": "string summarizing termination rights or null",
  "pricingTerms": "string summarizing pricing or null",
  "invoicingTerms": "string summarizing billing or null",
  "userLicenseCounts": "string or null",
  "serviceLevels": "string summarizing SLA commitments or null",
  "supportTerms": "string summarizing support coverage or null",
  "dataPrivacyTerms": "string summarizing data handling obligations or null",
  "insuranceRequirements": "string summarizing required insurance or null",
  "liabilityCap": "string describing liability limitations or null",
  "indemnification": "string describing indemnification obligations or null",
  "governingLaw": "state or jurisdiction or null",
  "disputeResolution": "string describing dispute resolution mechanism or null",
  "keyRisks": ["array of up to 5 brief risk descriptions, or empty array"],
  "executiveSummary": "2-3 sentence plain-English summary of this agreement",
  "riskSummary": "1-2 sentence assessment of overall risk level and key concerns",
  "actionItems": [{"item": "string", "priority": "high|medium|low"}]
}`;

      let parsed: Record<string, any> = {};
      let executiveSummary = "";
      let riskSummary = "";
      let actionItems: any[] = [];

      try {
        const response = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ],
          response_format: { type: "json_object" },
          max_completion_tokens: 2000,
        });
        const raw = JSON.parse(response.choices[0]?.message?.content || "{}");
        executiveSummary = typeof raw.executiveSummary === "string" ? raw.executiveSummary : "";
        riskSummary = typeof raw.riskSummary === "string" ? raw.riskSummary : "";
        actionItems = Array.isArray(raw.actionItems) ? raw.actionItems : [];
        const { executiveSummary: _es, riskSummary: _rs, actionItems: _ai, ...rest } = raw;
        parsed = rest;
      } catch (aiErr: any) {
        console.error("[AIContractReviewFromDoc] AI call failed:", aiErr?.message);
        return res.status(502).json({ message: "AI analysis failed. Please try again." });
      }

      const [review] = await db.insert(contractAiReviews).values({
        vendorId,
        documentId: doc.id,
        contractId: doc.contractId ?? undefined,
        fileName: doc.fileName,
        extractedJson: parsed,
        executiveSummary,
        riskSummary,
        actionItems,
        reviewedByAiModel: "gpt-4o",
        reviewedBy: user!.id,
        isEdited: false,
      }).returning();

      await logVendorAudit("vendor_document", review.id, "create", {
        userId: user!.id,
        userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id,
        userRole: user!.role || undefined,
      }, { fileName: doc.fileName, type: "ai_contract_review_from_doc" });

      res.json(review);
    } catch (error: any) {
      console.error("[AIContractReviewFromDoc] Unexpected error:", error?.message, error?.stack);
      res.status(500).json({ message: "Failed to process AI contract review" });
    }
  });

