  // GET variance summary across all audits for a vendor
  app.get("/api/vendors/:vendorId/invoice-audits-summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:read")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("vendor:read") });
      }
      const audits = await db.select().from(vendorInvoiceAudit)
        .where(eq(vendorInvoiceAudit.vendorId, req.params.vendorId));
      const total = audits.length;
      const matches = audits.filter(a => a.auditStatus === "match").length;
      const warnings = audits.filter(a => a.auditStatus === "warning").length;
      const exceptions = audits.filter(a => a.auditStatus === "exception").length;
      const totalVariance = audits.reduce((sum, a) => sum + (parseFloat(a.varianceAmount as string || "0") || 0), 0);
      const totalInvoiced = audits.reduce((sum, a) => sum + (parseFloat(a.invoiceTotal as string || "0") || 0), 0);
      const totalExpected = audits.reduce((sum, a) => sum + (parseFloat(a.expectedTotal as string || "0") || 0), 0);
      res.json({ total, matches, warnings, exceptions, totalVariance, totalInvoiced, totalExpected });
    } catch (error: any) {
      console.error("[InvoiceAudit] Error fetching summary:", error?.message);
      res.status(500).json({ message: "Failed to fetch invoice audit summary" });
    }
  });

  app.post("/api/vendors/:vendorId/invoice-audit", isAuthenticated, vendorDocUpload.single("file"), async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:upload")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:upload") });
      }
      const vendorId = req.params.vendorId;
      const [vendor] = await db.select().from(vendors).where(eq(vendors.id, vendorId)).limit(1);
      if (!vendor) return res.status(404).json({ message: "Vendor not found" });
      if (!req.file) return res.status(400).json({ message: "No file provided" });

      const allowedTypes = [
        'application/pdf',
        'application/msword',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
      ];
      if (!allowedTypes.includes(req.file.mimetype)) {
        return res.status(400).json({ message: "Only PDF and Word documents are supported" });
      }

      // Extract text
      let documentText = "";
      let pdfIsScanned = false;
      try {
        if (req.file.mimetype === 'application/pdf') {
          const pdfResult = await extractPdfText(req.file.buffer);
          documentText = pdfResult.text;
          pdfIsScanned = pdfResult.isScanned;
        } else {
          const mammoth = await import("mammoth");
          const result = await mammoth.extractRawText({ buffer: req.file.buffer });
          documentText = result.value;
        }
      } catch (parseErr: any) {
        const errMsg: string = parseErr?.message ?? "";
        console.error("[AIContractReview2] Text extraction failed — file:", req.file.originalname, "mime:", req.file.mimetype, "size:", req.file.size, "err:", errMsg, parseErr?.stack);
        if (errMsg.startsWith("PASSWORD:")) {
          return res.status(422).json({ message: "This PDF is password-protected. Please remove the password and re-upload." });
        }
        return res.status(422).json({ message: "Could not read this PDF. The file may be corrupt, in an unsupported format, or encrypted." });
      }

      if (!documentText || documentText.trim().length < 50) {
        if (pdfIsScanned) {
          return res.status(422).json({ message: "This PDF contains only scanned images — no text could be extracted. OCR is not yet supported. Please upload a text-based PDF or a Word document." });
        }
        return res.status(422).json({ message: "This PDF has very little readable text. Please ensure it is a text-based PDF, not a scanned image." });
      }

      // Fetch contract & pricing context for the vendor
      const contractId = req.body.contractId || null;
      let contractContext = "";
      let pricingContext = "";

      let contractsForVendor = await db.select().from(vendorContracts)
        .where(eq(vendorContracts.vendorId, vendorId))
        .orderBy(desc(vendorContracts.startDate));

      if (contractId) {
        contractsForVendor = contractsForVendor.filter(c => c.id === contractId);
      }

      const activeContracts = contractsForVendor.filter(c => c.contractStatus === "active");
      const contractsToUse = activeContracts.length > 0 ? activeContracts : contractsForVendor.slice(0, 2);

      if (contractsToUse.length > 0) {
        contractContext = contractsToUse.map(c =>
          `Contract: ${c.contractName} | Type: ${c.contractType} | Status: ${c.contractStatus} | Start: ${c.startDate || "N/A"} | End: ${c.endDate || "N/A"} | Payment Terms: ${c.paymentTerms || "N/A"} | Pricing Terms: ${c.pricingTerms || "N/A"} | Auto-Renew: ${c.autoRenew}`
        ).join("\n");
      }

      const pricingRecords = await db.select().from(vendorPricing)
        .where(eq(vendorPricing.vendorId, vendorId));

      if (pricingRecords.length > 0) {
        pricingContext = pricingRecords.map(p =>
          `Pricing: ${p.unitDescription} | Type: ${p.pricingType} | Rate: $${p.unitRate} per unit | Min Commitment: ${p.minimumCommitment ? `$${p.minimumCommitment}` : "None"} | Effective: ${p.effectiveStart} to ${p.effectiveEnd || "ongoing"}${p.contractId ? ` (Contract: ${p.contractId})` : ""}`
        ).join("\n");
      }

      const truncatedText = documentText.slice(0, 55000);

      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      });

      const systemPrompt = `You are a forensic accounts payable auditor specializing in vendor invoice compliance. You extract invoice data and compare it to contract terms to identify discrepancies. Always respond with valid JSON only. Never fabricate values — if something isn't present, use null.`;

      const userPrompt = `Analyze this vendor invoice document and compare it against the contract/pricing data below. Return ONLY a valid JSON object, no markdown.

INVOICE DOCUMENT:
${truncatedText}

${contractContext ? `CONTRACT TERMS:\n${contractContext}\n` : ""}
${pricingContext ? `AGREED PRICING:\n${pricingContext}\n` : ""}
VENDOR NAME: ${vendor.name}

Required JSON structure:
{
  "invoiceNumber": "string or null",
  "invoiceDate": "YYYY-MM-DD or null",
  "dueDate": "YYYY-MM-DD or null",
  "billingPeriod": "string describing period (e.g. 'January 2025' or '2025-01-01 to 2025-01-31') or null",
  "invoiceTotal": number or null,
  "lineItems": [
    {
      "description": "string",
      "quantity": number or null,
      "unitRate": number or null,
      "amount": number or null,
      "contractedRate": number or null,
      "rateVariance": number or null,
      "flag": "none | rate_above_contract | extra_units | unknown_fee | duplicate_fee | outside_contract_dates | exceeds_run_rate | null",
      "flagNote": "string or null"
    }
  ],
  "taxes": number or null,
  "fees": number or null,
  "surcharges": number or null,
  "expectedTotal": number or null,
  "varianceAmount": number or null,
  "variancePercent": number or null,
  "flaggedItems": [
    {
      "type": "rate_above_contract | extra_users_licenses | duplicate_fee | outside_contract_dates | unknown_surcharge | exceeds_run_rate",
      "severity": "warning | exception",
      "description": "string explaining the specific issue",
      "invoicedValue": "string or null",
      "contractedValue": "string or null"
    }
  ],
  "contractComparison": {
    "pricing": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of pricing alignment",
      "discrepancies": [{ "item": "string", "invoicedRate": "string", "contractedRate": "string", "delta": "string" }]
    },
    "dates": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of date alignment",
      "discrepancies": [{ "description": "string" }]
    },
    "paymentTerms": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of payment terms alignment",
      "discrepancies": [{ "description": "string", "invoiced": "string", "contracted": "string" }]
    },
    "userLicenseLimits": {
      "status": "match | warning | exception | not_applicable",
      "summary": "1-2 sentence explanation of quantity/license alignment",
      "discrepancies": [{ "item": "string", "invoicedQty": "string", "contractedLimit": "string" }]
    }
  },
  "auditStatus": "match | warning | exception",
  "auditSummary": "2-3 sentence plain English summary of the audit findings"
}

Rules for flagging:
- If any line item rate exceeds contracted rate by more than 1%: flag as 'rate_above_contract' (exception)
- If quantity exceeds committed user/license counts: flag as 'extra_units' (warning)
- If duplicate line items found: flag as 'duplicate_fee' (exception)
- If invoice date is outside contract effective dates: flag as 'outside_contract_dates' (exception)
- If a fee/surcharge has no matching contract term: flag as 'unknown_surcharge' (warning)
- If total exceeds expected monthly run rate by more than 10%: flag as 'exceeds_run_rate' (warning)
- If no pricing data provided, compare line items internally for consistency
- auditStatus: 'match' if no flags, 'warning' if only warnings, 'exception' if any exceptions
- contractComparison.pricing: compare each invoice line rate vs contracted rate in AGREED PRICING
- contractComparison.dates: confirm invoice date and billing period fall within contract Start/End dates
- contractComparison.paymentTerms: compare payment terms stated on invoice vs CONTRACT TERMS Payment Terms field
- contractComparison.userLicenseLimits: compare invoiced quantities vs minimumCommitment/contracted volumes; use 'not_applicable' if contract has no quantity limits
- For each dimension, status='match' if fully aligned, 'warning' if minor deviation (<5%), 'exception' if significant deviation or explicit violation`;

      let extracted: any = {};
      try {
        const response = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt },
          ],
          response_format: { type: "json_object" },
          max_completion_tokens: 2500,
        });
        extracted = JSON.parse(response.choices[0]?.message?.content || "{}");
      } catch (aiErr: any) {
        console.error("[InvoiceAudit] AI call failed:", aiErr?.message);
        return res.status(502).json({ message: "AI analysis failed. Please try again." });
      }

      // Save as vendor document
      let invoiceDocumentId: string | null = null;
      try {
        const auditBaseKey = `vendor-documents/${vendorId}/invoice-audit/${Date.now()}-${req.file.originalname}`;
        const auditProvider = getStorageProvider();
        let auditStorageKey: string;
        if (auditProvider === "s3") {
          const s3Service = getS3StorageService();
          await s3Service.uploadToKey(auditBaseKey, req.file.buffer, req.file.mimetype);
          auditStorageKey = auditBaseKey;
        } else {
          auditStorageKey = `.private/${auditBaseKey}`;
          const client = new (await import("@replit/object-storage")).Client({
            bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID!,
          });
          await client.uploadFromBytes(auditStorageKey, req.file.buffer);
        }
        // Storage key validation guard
        if (auditProvider !== "s3" && !auditStorageKey.startsWith(".private/")) {
          throw new Error(`[InvoiceAudit] ASSERTION FAILED — auditStorageKey missing .private/ prefix: "${auditStorageKey}"`);
        }
        const [doc] = await db.insert(vendorDocuments).values({
          vendorId,
          documentType: "Invoice",
          fileName: req.file.originalname,
          storageKey: auditStorageKey,
          uploadedBy: user!.id,
          notes: "Uploaded for invoice audit",
        }).returning();
        invoiceDocumentId = doc.id;
      } catch (storageErr: any) {
        console.warn("[InvoiceAudit] File storage failed (non-fatal):", storageErr?.message);
      }

      const usedContractId = contractId || (contractsToUse[0]?.id ?? null);
      const [audit] = await db.insert(vendorInvoiceAudit).values({
        vendorId,
        invoiceDocumentId,
        contractId: usedContractId,
        invoiceNumber: extracted.invoiceNumber ?? null,
        invoiceDate: extracted.invoiceDate ?? null,
        dueDate: extracted.dueDate ?? null,
        billingPeriod: extracted.billingPeriod ?? null,
        invoiceTotal: extracted.invoiceTotal != null ? String(extracted.invoiceTotal) : null,
        expectedTotal: extracted.expectedTotal != null ? String(extracted.expectedTotal) : null,
        varianceAmount: extracted.varianceAmount != null ? String(extracted.varianceAmount) : null,
        variancePercent: extracted.variancePercent != null ? String(extracted.variancePercent) : null,
        auditStatus: (["match", "warning", "exception"].includes(extracted.auditStatus) ? extracted.auditStatus : "match") as "match" | "warning" | "exception",
        exceptionNotes: extracted.auditSummary ?? null,
        extractedInvoiceJson: extracted,
        contractComparison: extracted.contractComparison ?? null,
        flaggedItems: extracted.flaggedItems ?? [],
        auditedBy: user!.id,
      }).returning();

      await logVendorAudit("vendor_document", audit.id, "create", {
        userId: user!.id,
        userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id,
        userRole: user!.role || undefined,
      }, { fileName: req.file.originalname, type: "invoice_audit", auditStatus: audit.auditStatus });

      res.json(audit);
    } catch (error: any) {
      console.error("[InvoiceAudit] Unexpected error:", error?.message, error?.stack);
      res.status(500).json({ message: "Failed to process invoice audit" });
    }
  });

  app.post("/api/vendors/:vendorId/invoice-audit-text", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "document:upload")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("document:upload") });
      }
      const vendorId = req.params.vendorId;
      const [vendor] = await db.select().from(vendors).where(eq(vendors.id, vendorId)).limit(1);
      if (!vendor) return res.status(404).json({ message: "Vendor not found" });

      const { invoiceText, contractId } = req.body;
      if (!invoiceText || typeof invoiceText !== "string" || invoiceText.trim().length < 30) {
        return res.status(400).json({ message: "Invoice text must be at least 30 characters." });
      }
      const documentText = invoiceText.trim();

      // Fetch contract & pricing context (same logic as file route)
      let contractsForVendor = await db.select().from(vendorContracts)
        .where(eq(vendorContracts.vendorId, vendorId))
        .orderBy(desc(vendorContracts.startDate));
      if (contractId) contractsForVendor = contractsForVendor.filter(c => c.id === contractId);
      const activeContracts = contractsForVendor.filter(c => c.contractStatus === "active");
      const contractsToUse = activeContracts.length > 0 ? activeContracts : contractsForVendor.slice(0, 2);
      const contractContext = contractsToUse.map(c =>
        `Contract: ${c.contractName} | Type: ${c.contractType} | Status: ${c.contractStatus} | Start: ${c.startDate || "N/A"} | End: ${c.endDate || "N/A"} | Payment Terms: ${c.paymentTerms || "N/A"} | Pricing Terms: ${c.pricingTerms || "N/A"} | Auto-Renew: ${c.autoRenew}`
      ).join("\n");
      const pricingRecords = await db.select().from(vendorPricing).where(eq(vendorPricing.vendorId, vendorId));
      const pricingContext = pricingRecords.map(p =>
        `Pricing: ${p.unitDescription} | Type: ${p.pricingType} | Rate: $${p.unitRate}/unit | Min Commitment: ${p.minimumCommitment ? `$${p.minimumCommitment}` : "None"} | Effective: ${p.effectiveStart} to ${p.effectiveEnd || "ongoing"}`
      ).join("\n");

      const truncatedText = documentText.slice(0, 55000);
      const OpenAI = (await import("openai")).default;
      const openai = new OpenAI({
        apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY,
        baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL,
      });
      const systemPrompt = `You are a forensic accounts payable auditor specializing in vendor invoice compliance. You extract invoice data and compare it to contract terms to identify discrepancies. Always respond with valid JSON only. Never fabricate values — if something isn't present, use null.`;
      const userPrompt = `Analyze this vendor invoice document and compare it against the contract/pricing data below. Return ONLY a valid JSON object, no markdown.

INVOICE DOCUMENT:
${truncatedText}

${contractContext ? `CONTRACT TERMS:\n${contractContext}\n` : ""}
${pricingContext ? `AGREED PRICING:\n${pricingContext}\n` : ""}
VENDOR NAME: ${vendor.name}

Required JSON structure:
{
  "invoiceNumber": "string or null",
  "invoiceDate": "YYYY-MM-DD or null",
  "dueDate": "YYYY-MM-DD or null",
  "billingPeriod": "string describing period or null",
  "invoiceTotal": number or null,
  "lineItems": [
    { "description": "string", "quantity": number or null, "unitRate": number or null, "amount": number or null, "contractedRate": number or null, "rateVariance": number or null, "flag": "none | rate_above_contract | extra_units | unknown_fee | duplicate_fee | outside_contract_dates | exceeds_run_rate | null", "flagNote": "string or null" }
  ],
  "taxes": number or null, "fees": number or null, "surcharges": number or null,
  "expectedTotal": number or null, "varianceAmount": number or null, "variancePercent": number or null,
  "flaggedItems": [
    { "type": "rate_above_contract | extra_users_licenses | duplicate_fee | outside_contract_dates | unknown_surcharge | exceeds_run_rate", "severity": "warning | exception", "description": "string", "invoicedValue": "string or null", "contractedValue": "string or null" }
  ],
  "contractComparison": {
    "pricing": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of pricing alignment",
      "discrepancies": [{ "item": "string", "invoicedRate": "string", "contractedRate": "string", "delta": "string" }]
    },
    "dates": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of date alignment",
      "discrepancies": [{ "description": "string" }]
    },
    "paymentTerms": {
      "status": "match | warning | exception",
      "summary": "1-2 sentence explanation of payment terms alignment",
      "discrepancies": [{ "description": "string", "invoiced": "string", "contracted": "string" }]
    },
    "userLicenseLimits": {
      "status": "match | warning | exception | not_applicable",
      "summary": "1-2 sentence explanation of quantity/license alignment",
      "discrepancies": [{ "item": "string", "invoicedQty": "string", "contractedLimit": "string" }]
    }
  },
  "auditStatus": "match | warning | exception",
  "auditSummary": "2-3 sentence plain English summary of the audit findings"
}

Rules: flag rate_above_contract (exception) if >1% over contracted rate; flag extra_units (warning) if quantity exceeds committed; flag duplicate_fee (exception) for duplicates; flag outside_contract_dates (exception) if outside dates; flag unknown_surcharge (warning) for unknown fees; flag exceeds_run_rate (warning) if total >10% over run rate; auditStatus: match=no flags, warning=only warnings, exception=any exceptions.
contractComparison.pricing: compare each invoice line rate vs contracted rate in AGREED PRICING.
contractComparison.dates: confirm invoice date and billing period fall within contract Start/End dates.
contractComparison.paymentTerms: compare payment terms stated on invoice vs CONTRACT TERMS Payment Terms field.
contractComparison.userLicenseLimits: compare invoiced quantities vs minimumCommitment; use 'not_applicable' if no quantity limits exist.
For each dimension: status='match' if aligned, 'warning' if minor deviation (<5%), 'exception' if significant violation.`;

      let extracted: any = {};
      try {
        const response = await openai.chat.completions.create({
          model: "gpt-4o",
          messages: [{ role: "system", content: systemPrompt }, { role: "user", content: userPrompt }],
          response_format: { type: "json_object" },
          max_completion_tokens: 2500,
        });
        extracted = JSON.parse(response.choices[0]?.message?.content || "{}");
      } catch (aiErr: any) {
        console.error("[InvoiceAuditText] AI call failed:", aiErr?.message);
        return res.status(502).json({ message: "AI analysis failed. Please try again." });
      }

      // Store text as a .txt vendor document
      let invoiceDocumentId: string | null = null;
      try {
        const textBuffer = Buffer.from(documentText, "utf-8");
        const fileName = `invoice-text-${Date.now()}.txt`;
        const auditBaseKey = `vendor-documents/${vendorId}/invoice-audit/${fileName}`;
        const auditProvider = getStorageProvider();
        let auditStorageKey: string;
        if (auditProvider === "s3") {
          const s3Service = getS3StorageService();
          await s3Service.uploadToKey(auditBaseKey, textBuffer, "text/plain");
          auditStorageKey = auditBaseKey;
        } else {
          auditStorageKey = `.private/${auditBaseKey}`;
          const client = new (await import("@replit/object-storage")).Client({ bucketId: process.env.DEFAULT_OBJECT_STORAGE_BUCKET_ID! });
          await client.uploadFromBytes(auditStorageKey, textBuffer);
        }
        if (auditProvider !== "s3" && !auditStorageKey.startsWith(".private/")) {
          throw new Error(`[InvoiceAuditText] Storage key missing .private/ prefix: "${auditStorageKey}"`);
        }
        const [doc] = await db.insert(vendorDocuments).values({
          vendorId,
          documentType: "Invoice",
          fileName,
          storageKey: auditStorageKey,
          uploadedBy: user!.id,
          notes: "Pasted invoice text — uploaded for invoice audit",
        }).returning();
        invoiceDocumentId = doc.id;
      } catch (storageErr: any) {
        console.warn("[InvoiceAuditText] File storage failed (non-fatal):", storageErr?.message);
      }

      const usedContractId = contractId || (contractsToUse[0]?.id ?? null);
      const [audit] = await db.insert(vendorInvoiceAudit).values({
        vendorId,
        invoiceDocumentId,
        contractId: usedContractId,
        invoiceNumber: extracted.invoiceNumber ?? null,
        invoiceDate: extracted.invoiceDate ?? null,
        dueDate: extracted.dueDate ?? null,
        billingPeriod: extracted.billingPeriod ?? null,
        invoiceTotal: extracted.invoiceTotal != null ? String(extracted.invoiceTotal) : null,
        expectedTotal: extracted.expectedTotal != null ? String(extracted.expectedTotal) : null,
        varianceAmount: extracted.varianceAmount != null ? String(extracted.varianceAmount) : null,
        variancePercent: extracted.variancePercent != null ? String(extracted.variancePercent) : null,
        auditStatus: (["match","warning","exception"].includes(extracted.auditStatus) ? extracted.auditStatus : "match") as "match"|"warning"|"exception",
        exceptionNotes: extracted.auditSummary ?? null,
        extractedInvoiceJson: extracted,
        contractComparison: extracted.contractComparison ?? null,
        flaggedItems: extracted.flaggedItems ?? [],
        auditedBy: user!.id,
      }).returning();

      await logVendorAudit("vendor_document", audit.id, "create", {
        userId: user!.id,
        userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ""}`.trim() : user!.email || user!.id,
        userRole: user!.role || undefined,
      }, { type: "invoice_audit_text", auditStatus: audit.auditStatus });

      res.json(audit);
    } catch (error: any) {
      console.error("[InvoiceAuditText] Unexpected error:", error?.message, error?.stack);
      res.status(500).json({ message: "Failed to process invoice audit" });
    }
  });

