  app.post("/api/vendors/:id/license-utilization", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:update")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("vendor:update") });
      }
      const body = req.body;
      // Auto-calculate utilization percent and estimated unused cost if not provided
      let utilizationPercent = body.utilizationPercent;
      let estimatedUnusedCost = body.estimatedUnusedCost;
      if (body.purchasedSeats && body.activeUsers30d && !utilizationPercent) {
        utilizationPercent = ((body.activeUsers30d / body.purchasedSeats) * 100).toFixed(2);
      }
      if (body.purchasedSeats && body.activeUsers30d && body.monthlyCost && !estimatedUnusedCost) {
        const unusedSeats = Math.max(0, body.purchasedSeats - body.activeUsers30d);
        const costPerSeat = body.monthlyCost / body.purchasedSeats;
        estimatedUnusedCost = (unusedSeats * costPerSeat).toFixed(2);
      }
      const [row] = await db.insert(vendorLicenseUtilization).values({
        vendorId: req.params.id,
        contractId: body.contractId || null,
        measurementDate: body.measurementDate || new Date().toISOString().split("T")[0],
        purchasedSeats: body.purchasedSeats ? parseInt(body.purchasedSeats) : null,
        assignedSeats: body.assignedSeats ? parseInt(body.assignedSeats) : null,
        activeUsers30d: body.activeUsers30d ? parseInt(body.activeUsers30d) : null,
        activeUsers60d: body.activeUsers60d ? parseInt(body.activeUsers60d) : null,
        activeUsers90d: body.activeUsers90d ? parseInt(body.activeUsers90d) : null,
        monthlyCost: body.monthlyCost || null,
        estimatedUnusedCost: estimatedUnusedCost || null,
        utilizationPercent: utilizationPercent || null,
        notes: body.notes || null,
        recordedBy: req.user.claims.sub,
      }).returning();
      res.status(201).json(row);
    } catch (error: any) {
      console.error("[LicenseUtil] Error creating:", error?.message);
      res.status(500).json({ message: "Failed to record license utilization" });
    }
  });

