  // ========================================
  // VENDOR RISK ASSESSMENT ROUTES
  // ========================================

  app.get("/api/vendors/:id/risk-assessment", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:read")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("vendor:read") });
      }
      const existing = await db.select().from(vendors).where(and(eq(vendors.id, req.params.id), isNull(vendors.deletedAt))).limit(1);
      if (existing.length === 0) return res.status(404).json({ message: "Vendor not found" });
      const vendor = existing[0];

      const reasons: string[] = [];
      let suggestedLevel: "low" | "medium" | "high" | "critical" = "low";

      const complianceRecords = await db.select().from(vendorCompliance).where(eq(vendorCompliance.vendorId, vendor.id));
      const now = new Date();
      const hasExpiredCompliance = complianceRecords.some(c => {
        const expDate = new Date(c.expirationDate);
        return expDate < now;
      });
      const hasExpiringSoonCompliance = complianceRecords.some(c => {
        const expDate = new Date(c.expirationDate);
        const reminderDate = new Date(expDate);
        reminderDate.setDate(reminderDate.getDate() - (c.reminderDaysBefore || 30));
        return expDate >= now && reminderDate <= now;
      });
      if (hasExpiredCompliance) {
        reasons.push("Expired compliance record(s)");
        suggestedLevel = "critical";
      } else if (hasExpiringSoonCompliance) {
        reasons.push("Compliance record(s) expiring soon");
        if (suggestedLevel === "low") suggestedLevel = "medium";
      }

      const notes = await db.select().from(vendorNotes).where(eq(vendorNotes.vendorId, vendor.id));
      const hasHighSeverityNote = notes.some(n => n.severity === "high");
      if (hasHighSeverityNote) {
        reasons.push("High severity unresolved note(s)");
        if (suggestedLevel !== "critical") suggestedLevel = "high";
      }

      const contracts = await db.select().from(vendorContracts).where(
        and(eq(vendorContracts.vendorId, vendor.id), eq(vendorContracts.contractStatus, "active"))
      );
      const hasContractInNoticeWindow = contracts.some(c => {
        const endDate = new Date(c.endDate);
        const noticeDays = c.noticePeriodDays || 0;
        const noticeStart = new Date(endDate);
        noticeStart.setDate(noticeStart.getDate() - noticeDays);
        return noticeStart <= now && endDate >= now;
      });
      const hasContractExpiringSoon = contracts.some(c => {
        const endDate = new Date(c.endDate);
        const thresholdDays = vendor.renewalThresholdDays || 60;
        const daysUntil = Math.ceil((endDate.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
        return daysUntil >= 0 && daysUntil <= thresholdDays;
      });
      if (hasContractInNoticeWindow) {
        reasons.push("Contract within cancellation notice window");
        if (suggestedLevel === "low" || suggestedLevel === "medium") suggestedLevel = "high";
      } else if (hasContractExpiringSoon) {
        reasons.push("Contract expiring within renewal threshold");
        if (suggestedLevel === "low") suggestedLevel = "medium";
      }

      res.json({
        currentRiskLevel: vendor.riskLevel,
        currentRiskReason: vendor.riskReason,
        suggestedRiskLevel: suggestedLevel,
        suggestedReasons: reasons,
        isEscalation: ["low", "medium", "high", "critical"].indexOf(suggestedLevel) > ["low", "medium", "high", "critical"].indexOf(vendor.riskLevel),
      });
    } catch (error: any) {
      console.error("[VendorRisk] Error assessing risk:", error?.message, error?.stack || error);
      res.status(500).json({ message: "Failed to assess vendor risk" });
    }
  });

  app.put("/api/vendors/:id/risk", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await resolveVendorAccess(user!.id, user?.role, "vendor:update")) {
        return res.status(403).json({ message: getPermissionDeniedMessage("vendor:update") });
      }
      const existing = await db.select().from(vendors).where(and(eq(vendors.id, req.params.id), isNull(vendors.deletedAt))).limit(1);
      if (existing.length === 0) return res.status(404).json({ message: "Vendor not found" });

      const { riskLevel, riskReason } = req.body;
      if (!riskLevel || !["low", "medium", "high", "critical"].includes(riskLevel)) {
        return res.status(400).json({ message: "Invalid risk level. Must be one of: low, medium, high, critical" });
      }

      const [updated] = await db.update(vendors).set({
        riskLevel,
        riskReason: riskReason || null,
        updatedAt: new Date(),
      }).where(eq(vendors.id, req.params.id)).returning();

      const changes = computeChanges(existing[0], updated, ["riskLevel", "riskReason"]);
      await logVendorAudit("vendor", updated.id, "update", {
        userId: user!.id,
        userName: user!.firstName ? `${user!.firstName} ${user!.lastName || ''}`.trim() : user!.email || user!.id,
        userRole: user!.role || undefined,
      }, changes);

      res.json(updated);
    } catch (error: any) {
      console.error("[VendorRisk] Error updating risk:", error?.message, error?.stack || error);
      res.status(500).json({ message: "Failed to update vendor risk" });
    }
  });

