  // Create offer - Uses canOpenHiring gate (INCREMENT 25B)
  app.post("/api/corporate/recruiting/offers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      // Check hiring gate for market (INCREMENT 25B)
      // If marketId is provided, enforce canOpenHiring gate using real market data
      const marketId = req.body.marketId;
      if (marketId) {
        const { canOpenHiring, buildHiringError } = await import('./services/eligibility');
        
        // Fetch real market data from database
        let market = await storage.getMarket(marketId);
        if (!market) {
          market = await storage.getMarketByCode(marketId);
        }
        
        // Get driver counts for this market
        const drivers = await storage.getAllDriversWithUsers();
        const marketDrivers = drivers.filter((d: any) => 
          d.market === marketId || d.market === market?.code
        );
        
        // Use real market data or defaults
        const maxCapacity = market?.maxCapacity ?? 100;
        const hiringGateStatus = (market?.hiringGateStatus as 'OPEN' | 'LIMITED' | 'FROZEN' | 'CLOSED') ?? 'OPEN';
        const throttleActive = market?.throttleActive ?? false;
        
        const hiringGate = {
          marketId: market?.id || marketId,
          hiringGateStatus,
          throttleActive,
          currentCapacity: marketDrivers.length,
          maxCapacity,
          utilizationRate: maxCapacity > 0 ? marketDrivers.length / maxCapacity : 0,
        };
        
        const hiringCheck = canOpenHiring(marketId, hiringGate);
        
        if (!hiringCheck.allowed) {
          const errorResponse = buildHiringError(hiringCheck);
          return res.status(errorResponse.statusCode).json(errorResponse.body);
        }
      }

      const validatedData = insertOfferSchema.parse({ ...req.body, createdBy: userId });
      const offer = await storage.createOffer(validatedData);

      // Log activity
      await storage.createApplicationActivity({
        applicationId: offer.applicationId,
        activityType: "offer_created",
        description: `Offer created for ${offer.title}`,
        newValue: offer.id,
        performedBy: userId,
      });

      res.json(offer);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error creating offer:", error);
      res.status(500).json({ message: "Failed to create offer" });
    }
  });

