  // Convert hired candidate to driver/employee
  app.post("/api/corporate/recruiting/applications/:id/convert", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user.claims.sub;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const application = await storage.getApplicationWithDetails(req.params.id);
      if (!application) {
        return res.status(404).json({ message: "Application not found" });
      }

      if (application.status !== "hired") {
        return res.status(400).json({ message: "Only hired candidates can be converted" });
      }

      const { convertTo } = req.body; // convertTo: 'driver' | 'employee'

      // Generate invite code
      const inviteCode = `HIRE-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`.toUpperCase();

      // Create user invitation for the candidate
      const invitation = await storage.createUserInvitation({
        email: application.candidate.email,
        role: convertTo === "driver" ? "driver" : "employee",
        invitedBy: userId,
        inviteCode,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
      });

      // Log activity
      await storage.createApplicationActivity({
        applicationId: application.id,
        activityType: "converted",
        description: `Converted to ${convertTo} - invitation sent to ${application.candidate.email}`,
        performedBy: userId,
      });

      res.json({
        success: true,
        invitationId: invitation.id,
        message: `Invitation sent to ${application.candidate.email}`,
      });
    } catch (error) {
      console.error("Error converting candidate:", error);
      res.status(500).json({ message: "Failed to convert candidate" });
    }
  });

