  // Save field mappings (admin/super_user with lock enforcement)
  // Admin (NexCopy team): Can modify any mapping, can lock/unlock
  // Super User (Customer team): Can only modify unlocked mappings
  app.post("/api/hubspot/field-mappings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!user || (user.role !== "super_user" && user.role !== "admin")) {
        return res.status(403).json({ message: "Forbidden: Admin access only" });
      }

      const mappings = req.body.mappings;
      if (!Array.isArray(mappings)) {
        return res.status(400).json({ message: "Invalid request: mappings must be an array" });
      }

      const isNexCopyAdmin = user.role === "admin";
      
      // If Super User, check that they're not trying to modify locked mappings
      if (!isNexCopyAdmin) {
        const existingMappings = await storage.getAllHubspotFieldMappings();
        const lockedFields = existingMappings
          .filter(m => m.isLocked)
          .map(m => m.driverHubField);
        
        // Check if any submitted mapping tries to change a locked field
        for (const mapping of mappings) {
          if (lockedFields.includes(mapping.driverHubField)) {
            const existingMapping = existingMappings.find(m => m.driverHubField === mapping.driverHubField);
            // If the mapping value changed for a locked field, reject
            if (existingMapping && existingMapping.hubspotProperty !== mapping.hubspotProperty) {
              return res.status(403).json({ 
                message: `Cannot modify locked mapping: ${mapping.driverHubField}. Contact NexCopy administrator.` 
              });
            }
          }
          // Super Users cannot lock/unlock mappings
          if (mapping.isLocked !== undefined) {
            return res.status(403).json({ 
              message: "Only NexCopy administrators can lock/unlock field mappings." 
            });
          }
        }
      }

      // Add created/updated by and handle locking metadata
      const mappingsWithMeta = mappings.map((m: any) => {
        const result: any = {
          ...m,
          updatedBy: req.user.claims.sub,
          createdBy: m.createdBy || req.user.claims.sub,
        };
        
        // If admin is locking, add lock metadata
        if (isNexCopyAdmin && m.isLocked === true) {
          result.lockedBy = req.user.claims.sub;
          result.lockedAt = new Date();
        } else if (isNexCopyAdmin && m.isLocked === false) {
          result.lockedBy = null;
          result.lockedAt = null;
        }
        
        return result;
      });

      const result = await storage.upsertHubspotFieldMappings(mappingsWithMeta);
      res.json({ success: true, mappings: result });
    } catch (error) {
      console.error("Error saving field mappings:", error);
      res.status(500).json({ message: "Failed to save field mappings" });
    }
  });

