  // Get pay periods summary
  app.get("/api/corporate/pay-periods", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      // Get all drivers and their pay records
      const drivers = await storage.getAllDrivers();
      const periodMap = new Map<string, any>();
      
      for (const driver of drivers) {
        const payRecords = await storage.getPayRecordsByDriverId(driver.id);
        
        for (const record of payRecords) {
          const periodKey = `${record.payPeriodStart}_${record.payPeriodEnd}`;
          
          if (!periodMap.has(periodKey)) {
            periodMap.set(periodKey, {
              id: periodKey,
              startDate: record.payPeriodStart,
              endDate: record.payPeriodEnd,
              status: record.status || 'open',
              driverCount: 0,
              totalGrossPay: 0,
              totalNetPay: 0,
              totalTrips: 0,
            });
          }
          
          const period = periodMap.get(periodKey);
          period.driverCount++;
          period.totalGrossPay += parseFloat(record.grossPay || '0');
          period.totalNetPay += parseFloat(record.netPay || '0');
          period.totalTrips += record.totalTrips || 0;
        }
      }
      
      const periods = Array.from(periodMap.values())
        .sort((a, b) => new Date(b.startDate).getTime() - new Date(a.startDate).getTime());
      
      res.json(periods);
    } catch (error) {
      console.error("Error fetching pay periods:", error);
      res.status(500).json({ message: "Failed to fetch pay periods" });
    }
  });

  // Authorized users for pay period lock actions (Will Walton + David Forman)
  const PAYROLL_LOCK_AUTHORIZED_USERS = [
    { firstName: 'Will', lastName: 'Walton' },
    { firstName: 'David', lastName: 'Forman' },
  ];

  function isPayrollLockAuthorized(user: any): boolean {
    if (!user) return false;
    const firstName = user.firstName?.toLowerCase() || '';
    const lastName = user.lastName?.toLowerCase() || '';
    return PAYROLL_LOCK_AUTHORIZED_USERS.some(
      auth => firstName.includes(auth.firstName.toLowerCase()) && lastName.includes(auth.lastName.toLowerCase())
    );
  }

  // Lock Pay Period: PROCESSING -> LOCKED (restricted to Will Walton + David Forman)
  // Uses canLockPayPeriod gate from eligibility service (INCREMENT 25B)
  app.post("/api/corporate/pay-periods/:id/lock", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      
      // Check if user is authorized to lock pay periods
      if (!isPayrollLockAuthorized(currentUser)) {
        return res.status(403).json({ 
          message: "Access denied", 
          reason: "Only Will Walton and David Forman can lock pay periods" 
        });
      }
      
      const payPeriodId = req.params.id; // UUID string, not numeric
      if (!payPeriodId) {
        return res.status(400).json({ message: "Invalid pay period ID" });
      }
      
      // Get the pay period
      const allPayPeriods = await storage.getAllPayPeriods();
      const payPeriod = allPayPeriods.find((p: any) => p.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ message: "Pay period not found" });
      }
      
      // Use eligibility service to check lock preconditions (INCREMENT 25B)
      const { canLockPayPeriod, buildPayrollError } = await import('./services/eligibility');
      const lockCheck = canLockPayPeriod({
        id: payPeriod.id,
        status: payPeriod.status,
        lockedAt: payPeriod.lockedAt,
        exportedAt: payPeriod.exportedAt,
        exportStatus: payPeriod.exportStatus,
        // TODO: Add actual reconciliation checks
        movesReconciled: true, // Placeholder - wire to actual data
        expensesApproved: true, // Placeholder - wire to actual data
      });
      
      if (!lockCheck.allowed) {
        const errorResponse = buildPayrollError(lockCheck);
        return res.status(errorResponse.statusCode).json(errorResponse.body);
      }
      
      // Update pay period status to LOCKED (uppercase to match enum)
      await storage.updatePayPeriod(payPeriodId, { status: 'LOCKED', lockedAt: new Date() });
      
      res.json({ 
        success: true, 
        message: "Pay period locked successfully",
        payPeriodId 
      });
    } catch (error: any) {
      console.error("Error locking pay period:", error);
      const errorCode = error.message?.includes("already locked") ? 'PAY_PERIOD_ALREADY_LOCKED' : 'UNKNOWN_ERROR';
      res.status(500).json({ 
        message: "Failed to lock pay period",
        code: errorCode
      });
    }
  });

  // Generate Export: Create export package for ADP/OpenForce (restricted to Will Walton + David Forman)
  // Uses canExportPayroll gate from eligibility service (INCREMENT 25B)
  app.post("/api/corporate/pay-periods/:id/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      
      // Check if user is authorized to generate exports
      if (!isPayrollLockAuthorized(currentUser)) {
        return res.status(403).json({ 
          message: "Access denied", 
          reason: "Only Will Walton and David Forman can generate payroll exports" 
        });
      }
      
      const payPeriodId = req.params.id; // UUID string, not numeric
      if (!payPeriodId) {
        return res.status(400).json({ message: "Invalid pay period ID" });
      }
      
      // Get the pay period
      const allPayPeriods = await storage.getAllPayPeriods();
      const payPeriod = allPayPeriods.find((p: any) => p.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ message: "Pay period not found" });
      }
      
      // Use eligibility service to check export preconditions (INCREMENT 25B)
      const { canExportPayroll, buildPayrollError } = await import('./services/eligibility');
      const exportCheck = canExportPayroll({
        id: payPeriod.id,
        status: payPeriod.status,
        lockedAt: payPeriod.lockedAt,
        exportedAt: payPeriod.exportedAt,
        exportStatus: payPeriod.exportStatus,
      });
      
      if (!exportCheck.allowed) {
        const errorResponse = buildPayrollError(exportCheck);
        return res.status(errorResponse.statusCode).json(errorResponse.body);
      }
      
      const exportType = req.body.exportType || 'ADP'; // ADP or OpenForce
      
      // Generate export data
      const drivers = await storage.getAllDriversWithUsers();
      const payRecords = [];
      
      for (const driver of drivers) {
        const records = await storage.getPayRecordsByDriverId(driver.id);
        const periodRecords = records.filter((r: any) => {
          const recordStart = new Date(r.payPeriodStart);
          const periodStart = new Date(payPeriod.periodStart);
          const periodEnd = new Date(payPeriod.periodEnd);
          return recordStart >= periodStart && recordStart <= periodEnd;
        });
        payRecords.push(...periodRecords.map((r: any) => ({
          ...r,
          driverName: `${driver.firstName || ''} ${driver.lastName || ''}`.trim(),
          driverNumber: driver.driverNumber,
          market: driver.market,
        })));
      }
      
      // Create export record (in production, this would generate actual files)
      const exportData = {
        payPeriodId,
        exportType,
        generatedAt: new Date().toISOString(),
        generatedBy: `${currentUser?.firstName || ''} ${currentUser?.lastName || ''}`.trim(),
        recordCount: payRecords.length,
        totalGrossPay: payRecords.reduce((sum: number, r: any) => sum + parseFloat(r.grossPay || '0'), 0),
        status: 'EXPORTED',
      };
      
      // Update pay period with export info
      await storage.updatePayPeriod(payPeriodId, { 
        exportedAt: new Date(),
        exportType,
        exportStatus: 'EXPORTED',
      });
      
      res.json({ 
        success: true, 
        message: `Export package generated for ${exportType}`,
        export: exportData,
        recordCount: payRecords.length,
      });
    } catch (error: any) {
      console.error("Error generating export:", error);
      const errorCode = error.message?.includes("No moves") ? 'PAY_PERIOD_EMPTY' : 'UNKNOWN_ERROR';
      res.status(500).json({ 
        message: "Failed to generate export",
        code: errorCode 
      });
    }
  });

