  // Assign driver to move - Uses canAssignWork gate
  // Returns 409 Conflict with {allowed: false, code, reasons[]} if ineligible
  app.post("/api/corporate/moves/:moveId/assign", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      const moveId = req.params.moveId;
      const { driverId } = req.body;
      
      if (!moveId || !driverId) {
        return res.status(400).json({ message: "Both moveId and driverId are required" });
      }
      
      // Get driver info for eligibility check
      const driver = await storage.getDriver(driverId);
      if (!driver) {
        return res.status(404).json({ 
          allowed: false,
          code: 'DRIVER_NOT_FOUND',
          reasons: ['Driver not found'],
          driverId,
          moveId,
        });
      }
      
      // Build driver eligibility info
      // In production, this would be populated from driver qualification tables
      const { canAssignWork, buildWorkAssignmentError } = await import('./services/eligibility');
      
      const driverEligibility = {
        driverId: driver.id,
        safetyState: driver.safetyState || 'ACTIVE',
        eligibleMarkets: [driver.market].filter(Boolean) as string[],
        eligibleZones: [], // Would be populated from qualification tables
        eligibleWorkTypes: ['ON_DEMAND', 'SCHEDULED', 'MANUAL'], // Default eligible for all
        eligibleExecutionModes: ['COMPANY_VEHICLE', 'DRIVER_VEHICLE', 'CUSTOMER_VEHICLE'],
        blocks: [], // Would be populated from active blocks table
      };
      
      // Build move details (in production, would fetch from moves table)
      const moveDetails = {
        id: moveId,
        marketId: driver.market || 'unknown',
        workType: req.body.workType || 'ON_DEMAND',
        executionMode: req.body.executionMode || 'COMPANY_VEHICLE',
      };
      
      // Check eligibility using hard enforcement gate
      const assignmentCheck = canAssignWork(driverEligibility, moveDetails);
      
      if (!assignmentCheck.allowed) {
        const errorResponse = buildWorkAssignmentError(assignmentCheck);
        return res.status(errorResponse.statusCode).json(errorResponse.body);
      }
      
      // All checks passed - proceed with assignment
      // In production, this would update the moves table
      res.json({
        success: true,
        message: "Driver assigned to move successfully",
        assignment: {
          driverId,
          moveId,
          assignedAt: new Date().toISOString(),
          assignedBy: `${currentUser?.firstName || ''} ${currentUser?.lastName || ''}`.trim(),
        },
      });
    } catch (error) {
      console.error("Error assigning driver to move:", error);
      res.status(500).json({ message: "Failed to assign driver to move" });
    }
  });

