  // Roster export - excludes non-eligible drivers (GATE 2) with real data enforcement
  app.get("/api/corporate/roster/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      const { filterRosterExport } = await import('./services/eligibility');
      type DriverRosterInfo = { driverId: string; safetyState: string; eligibilityState?: string; hasActiveBlock: boolean; marketHiringGateStatus?: string; };
      
      const drivers = await storage.getAllDriversWithUsers();
      
      // Get all markets to build a lookup map for hiring gate status
      // Map by id, name, and code since driver.market could be any of these
      const allMarkets = await storage.getAllMarkets();
      const marketHiringGates = new Map<string, string>();
      for (const market of allMarkets) {
        const hiringStatus = market.hiringGateStatus || 'OPEN';
        // Map by all possible identifiers
        marketHiringGates.set(market.id, hiringStatus);
        marketHiringGates.set(market.name, hiringStatus);
        if (market.code) {
          marketHiringGates.set(market.code, hiringStatus);
        }
      }
      
      // Build roster info for each driver using REAL data
      const rosterInfos: DriverRosterInfo[] = drivers.map((d: any) => {
        const safetyState = d.safetyState || 'ACTIVE';
        // SUSPENDED or DISQUALIFIED safety states indicate an active block
        const hasActiveBlock = safetyState === 'SUSPENDED' || safetyState === 'DISQUALIFIED';
        // Get hiring gate status from driver's market
        const marketHiringGateStatus = d.market ? (marketHiringGates.get(d.market) || 'OPEN') : 'OPEN';
        
        return {
          driverId: d.id,
          safetyState,
          eligibilityState: d.status === 'active' ? 'ACTIVE' : 'INACTIVE',
          hasActiveBlock,
          marketHiringGateStatus,
        };
      });
      
      const result = filterRosterExport(rosterInfos);
      
      // Get full driver data for included drivers
      const includedDriverIds = new Set(result.included.map(d => d.driverId));
      const includedDrivers = drivers.filter((d: any) => includedDriverIds.has(d.id));
      
      res.json({
        exportedAt: new Date().toISOString(),
        totalDrivers: drivers.length,
        includedCount: result.included.length,
        excludedCount: result.excluded.length,
        drivers: includedDrivers.map((d: any) => ({
          id: d.id,
          name: d.user?.firstName + ' ' + d.user?.lastName,
          market: d.market,
          status: d.status,
          safetyState: d.safetyState || 'ACTIVE',
        })),
        exclusions: result.excluded,
      });
    } catch (error) {
      console.error("Error exporting roster:", error);
      res.status(500).json({ message: "Failed to export roster" });
    }
  });

