  // Override payroll exception (ONLY Will Walton or David Forman)
  app.post("/api/corporate/payroll/exceptions/:exceptionId/override", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      const { reason } = req.body;
      const exceptionId = req.params.exceptionId;
      
      if (!reason || reason.trim().length < 10) {
        return res.status(400).json({ 
          message: "Override reason is required and must be at least 10 characters" 
        });
      }
      
      const { approvePayrollException } = await import('./services/eligibility');
      
      // Get user email for authorization check
      const userEmail = currentUser?.email || '';
      
      const approvalResult = approvePayrollException(exceptionId, userEmail, reason);
      
      if (!approvalResult.allowed) {
        return res.status(403).json({
          allowed: false,
          code: approvalResult.code,
          message: approvalResult.message,
        });
      }
      
      // Update the exception in database
      const updatedException = await storage.updatePayrollException(exceptionId, {
        status: 'OVERRIDE_APPROVED',
        overrideApprovedBy: currentUserId,
        overrideReason: reason.trim(),
        overrideApprovedAt: new Date(),
      });
      
      if (!updatedException) {
        return res.status(404).json({ message: "Exception not found" });
      }
      
      res.json({
        message: "Override approved successfully",
        exception: updatedException,
        approvedBy: userEmail,
        approvedAt: approvalResult.approvedAt,
      });
    } catch (error) {
      console.error("Error approving payroll exception:", error);
      res.status(500).json({ message: "Failed to approve exception" });
    }
  });

  // Payroll export with eligibility enforcement (GATE 3)
  app.post("/api/corporate/payroll/:payPeriodId/export", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      // Only Will Walton and David Forman can export payroll
      const userEmail = currentUser?.email || '';
      const authorizedEmails = ['will.walton@driverhub360.com', 'david.forman@driverhub360.com'];
      if (!authorizedEmails.some(e => e.toLowerCase() === userEmail.toLowerCase())) {
        return res.status(403).json({ 
          message: "Only Will Walton or David Forman can export payroll" 
        });
      }
      
      const payPeriodId = req.params.payPeriodId;
      const payPeriods = await storage.getAllPayPeriods();
      const payPeriod = payPeriods.find((pp: any) => pp.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ message: "Pay period not found" });
      }
      
      const { filterMovesForPayrollExport } = await import('./services/eligibility');
      type MoveForPayroll = { tripId: string; moveNumber: string; driverId: string; eligibilityStatus: 'PASS' | 'WARN' | 'FAIL' | null; eligibilityReasons: string[] | null; payRate?: string | number; };
      
      // Get trips for this pay period
      const trips = await storage.getTripsByPayPeriodWithEligibility(
        new Date(payPeriod.periodStart),
        new Date(payPeriod.periodEnd)
      );
      
      if (trips.length === 0) {
        return res.status(400).json({
          message: "No moves found for this pay period. Cannot generate export.",
          code: 'PAY_PERIOD_EMPTY',
        });
      }
      
      // Map to MoveForPayroll format
      const movesForPayroll: MoveForPayroll[] = trips.map((t: any) => ({
        tripId: t.id,
        moveNumber: t.moveNumber,
        driverId: t.driverId,
        eligibilityStatus: t.eligibilityStatus || null,
        eligibilityReasons: t.eligibilityReasons || null,
        payRate: t.payRate,
      }));
      
      // Filter moves using eligibility gate
      const exportResult = filterMovesForPayrollExport(
        { id: payPeriodId, status: payPeriod.status },
        movesForPayroll
      );
      
      if (!exportResult.allowed) {
        return res.status(409).json({
          allowed: false,
          code: exportResult.code,
          reasons: exportResult.reasons,
          payPeriodStatus: exportResult.payPeriodStatus,
        });
      }
      
      // Create payroll exceptions for excluded moves
      for (const exception of exportResult.exceptions) {
        await storage.createPayrollException({
          tripId: exception.tripId,
          payPeriodId,
          driverId: exception.driverId,
          moveNumber: exception.moveNumber,
          exceptionType: exception.exceptionType,
          eligibilityReasons: exception.eligibilityReasons,
          originalEligibilityStatus: exception.originalEligibilityStatus,
          status: 'PENDING',
        });
      }
      
      res.json({
        exportedAt: new Date().toISOString(),
        payPeriodId,
        payPeriodStatus: exportResult.payPeriodStatus,
        includedMoves: exportResult.includedMoves.length,
        exceptionsCreated: exportResult.exceptions.length,
        moves: exportResult.includedMoves,
        exceptions: exportResult.exceptions,
      });
    } catch (error) {
      console.error("Error exporting payroll:", error);
      res.status(500).json({ message: "Failed to export payroll" });
    }
  });

