  // List pay periods with optional filters
  app.get("/api/payroll/pay-periods", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { workerType, periodType } = req.query;
      
      let payPeriods = await storage.getAllPayPeriods();
      
      if (periodType) {
        payPeriods = payPeriods.filter((pp: any) => {
          // Direct match against periodType field (DRIVERS_WEEKLY or DRIVERS_BIWEEKLY)
          if (pp.periodType === periodType) return true;
          
          // Legacy support: check by date range if periodType field not set
          const start = new Date(pp.periodStart);
          const end = new Date(pp.periodEnd);
          const daysDiff = Math.ceil((end.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
          
          if (periodType === 'DRIVERS_WEEKLY' && daysDiff >= 6 && daysDiff <= 8) return true;
          if (periodType === 'DRIVERS_BIWEEKLY' && daysDiff >= 13 && daysDiff <= 15) return true;
          return false;
        });
      }
      
      if (workerType) {
        payPeriods = payPeriods.filter((pp: any) => 
          pp.payGroup?.toLowerCase().includes(workerType.toLowerCase())
        );
      }
      
      const payPeriodsWithCounts = await Promise.all(
        payPeriods.map(async (pp: any) => {
          const trips = await storage.getTripsByPayPeriodWithEligibility(
            new Date(pp.periodStart),
            new Date(pp.periodEnd)
          );
          
          const totalMoves = trips.length;
          const includedMoves = trips.filter((t: any) => 
            t.eligibilityStatus === 'PASS' || t.eligibilityStatus === null
          ).length;
          const excludedMoves = totalMoves - includedMoves;
          
          return {
            ...pp,
            summary: {
              totalMoves,
              includedMoves,
              excludedMoves,
            },
          };
        })
      );
      
      res.json({
        payPeriods: payPeriodsWithCounts,
        count: payPeriodsWithCounts.length,
      });
    } catch (error) {
      console.error("Error fetching pay periods:", error);
      res.status(500).json({ message: "Failed to fetch pay periods" });
    }
  });

  // Create a manual trip entry
  app.post("/api/corporate/trips/manual", async (req: any, res: Response) => {
    try {
      // Support both session-based (password) and OIDC auth
      const currentUserId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!currentUserId) {
        return res.status(401).json({ error: "UNAUTHORIZED", message: "Not authenticated" });
      }
      const currentUser = await storage.getUser(currentUserId);
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      const userEmail = currentUser?.email || req.user?.claims?.email || '';

      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { 
        tripDate, 
        marketId, 
        estimatedMinutes, 
        notes, 
        driverId,
        customerId,
        referenceNumber
      } = req.body;

      if (!tripDate || !marketId || !notes || !estimatedMinutes) {
        return res.status(400).json({ message: "Missing required fields: tripDate, marketId, estimatedMinutes, notes" });
      }

      if (!driverId) {
        return res.status(400).json({ message: "Driver is required for manual move entry" });
      }

      if (!customerId) {
        return res.status(400).json({ message: "Customer is required for manual move entry" });
      }

      const moveNumber = referenceNumber || `MANUAL-${Date.now()}`;
      const moveData = {
        moveNumber,
        driverId: driverId,
        customerId: customerId,
        tripDate,
        origin: req.body.origin || 'Manual Entry',
        destination: req.body.destination || 'Manual Entry',
        marketId,
        notes,
        status: 'completed',
        estimatedMinutes: parseInt(estimatedMinutes, 10) || 0,
        duration: `${estimatedMinutes} min`
      };

      const { importMoves } = await import("./imports/importMoves");
      const context = {
        source: 'MANUAL' as const,
        ingestedBy: userEmail,
        storage: {
          getDriver: (id: string) => storage.getDriver(id),
          createTrip: (tripData: any) => storage.createTrip(tripData),
          getActivePolicyVersion: () => storage.getActivePolicyVersion ? storage.getActivePolicyVersion() : Promise.resolve(null),
        }
      };
      const results = await importMoves([moveData], context);

      // Find applicable pay period for this move's date
      const moveDate = new Date(tripDate);
      const allPayPeriods = await storage.getAllPayPeriods();
      const applicablePayPeriod = allPayPeriods.find((pp: any) => {
        const start = new Date(pp.periodStart);
        const end = new Date(pp.periodEnd);
        end.setHours(23, 59, 59, 999);
        return moveDate >= start && moveDate <= end;
      });

      // Log audit event with move_id and pay_period_id
      await storage.createPayPeriodAuditEvent({
        action: 'MOVE_CREATED_MANUAL' as any,
        userId: userEmail,
        payPeriodId: applicablePayPeriod?.id || null,
        metadata: {
          moveId: results.results[0]?.tripId,
          moveNumber: results.results[0]?.moveNumber,
          referenceNumber: moveNumber,
          marketId,
          driverId,
          customerId,
          serviceDate: tripDate,
          eligibilityStatus: results.results[0]?.eligibilityStatus,
          eligibilityReasons: results.results[0]?.eligibilityReasons,
        },
      });

      res.status(201).json({
        message: "Manual move created successfully",
        move: results.results[0],
        eligibility: {
          status: results.results[0]?.eligibilityStatus,
          reasons: results.results[0]?.eligibilityReasons
        }
      });
    } catch (error: any) {
      console.error("Error creating manual trip:", error);
      res.status(500).json({ message: error.message || "Failed to create manual trip" });
    }
  });

