  // Update pay period status (PATCH /api/payroll/pay-periods/:id/status)
  // State machine: OPEN → PROCESSING → LOCKED (LOCKED is permanent)
  app.patch("/api/payroll/pay-periods/:id/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const userEmail = currentUser?.email || req.user?.claims?.email || '';
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const payPeriodId = req.params.id;
      const { status: newStatus } = req.body;
      
      if (!newStatus || !['OPEN', 'PROCESSING', 'LOCKED'].includes(newStatus)) {
        return res.status(400).json({ 
          message: "Invalid status. Must be OPEN, PROCESSING, or LOCKED",
          code: 'INVALID_STATUS',
        });
      }

      const payPeriods = await storage.getAllPayPeriods();
      const payPeriod = payPeriods.find((pp: any) => pp.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ message: "Pay period not found" });
      }

      // State machine validation
      const validTransitions: Record<string, string[]> = {
        'OPEN': ['PROCESSING'],
        'PROCESSING': ['LOCKED'],
        'LOCKED': [], // No transitions allowed from LOCKED
      };

      if (!validTransitions[payPeriod.status]?.includes(newStatus)) {
        return res.status(400).json({ 
          message: `Cannot transition from ${payPeriod.status} to ${newStatus}`,
          code: 'INVALID_TRANSITION',
          currentStatus: payPeriod.status,
          requestedStatus: newStatus,
        });
      }

      // Authorization checks based on transition
      if (newStatus === 'PROCESSING') {
        // Will, David, or Luis can move to PROCESSING
        if (!canStartProcessing({ email: userEmail }, payPeriod)) {
          return res.status(403).json({ 
            message: "Only Will Walton, David Forman, or Luis Valdez can start processing",
            code: 'UNAUTHORIZED_PROCESSOR',
          });
        }

        // Enforcement: Start Processing requires included moves
        const trips = await storage.getTripsByPayPeriodWithEligibility(
          new Date(payPeriod.periodStart),
          new Date(payPeriod.periodEnd)
        );
        const includedMoveCount = trips.filter((t: any) => 
          t.eligibilityStatus === 'PASS' || t.eligibilityStatus === null
        ).length;

        if (includedMoveCount === 0) {
          return res.status(400).json({
            message: "At least 1 included move is required to start processing.",
            code: 'PAY_PERIOD_EMPTY',
          });
        }
      }

      if (newStatus === 'LOCKED') {
        // Only Will or David can lock
        if (!canLockPayPeriod({ email: userEmail }, payPeriod)) {
          return res.status(403).json({ 
            message: "Only Will Walton or David Forman can lock pay periods",
            code: 'UNAUTHORIZED_LOCKER',
          });
        }

        // Pre-lock validation: Check moves reconciled and expenses approved
        // (Placeholder for actual validation - would query moves and expenses)
        // For now, we allow locking and can add validation later
      }

      const updateData: any = { status: newStatus };
      if (newStatus === 'LOCKED') {
        updateData.lockedAt = new Date();
        updateData.lockedBy = userEmail;
      }
      
      const updated = await storage.updatePayPeriod(payPeriodId, updateData);
      
      // Log audit event for status transitions
      const auditAction = newStatus === 'PROCESSING' ? 'START_PROCESSING' : 
                          newStatus === 'LOCKED' ? 'PAY_PERIOD_LOCKED' : null;
      if (auditAction) {
        await storage.createPayPeriodAuditEvent({
          action: auditAction,
          userId: userEmail,
          payPeriodId: payPeriodId,
          metadata: {
            previousStatus: payPeriod.status,
            newStatus: newStatus,
            payGroup: payPeriod.payGroup,
          },
        });
      }
      
      res.json({
        payPeriod: updated,
        message: `Pay period status updated to ${newStatus}`,
      });
    } catch (error: any) {
      console.error("Error updating pay period status:", error);
      const errorCode = error.message.includes("Transition") ? 'PAY_PERIOD_INVALID_TRANSITION' : 'UNKNOWN_ERROR';
      res.status(400).json({ 
        message: error.message || "Failed to update pay period status",
        code: errorCode
      });
    }
  });

  // Lock a pay period (shortcut endpoint - for backwards compatibility)
  app.post("/api/payroll/pay-periods/:id/lock", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const userEmail = currentUser?.email || req.user?.claims?.email || '';
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      // Authorization check for locking
      if (!canLockPayPeriod({ email: userEmail }, payPeriod)) {
        return res.status(403).json({ 
          message: "Only Will Walton or David Forman can lock pay periods",
          code: 'UNAUTHORIZED_LOCKER',
        });
      }

      const payPeriodId = req.params.id;
      
      const payPeriods = await storage.getAllPayPeriods();
      const payPeriod = payPeriods.find((pp: any) => pp.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ message: "Pay period not found" });
      }
      
      if (payPeriod.status === 'LOCKED') {
        return res.status(400).json({ 
          message: "Pay period is already locked",
          code: 'ALREADY_LOCKED',
        });
      }
      
      const updated = await storage.updatePayPeriod(payPeriodId, {
        status: 'LOCKED',
        lockedAt: new Date(),
        lockedBy: userEmail,
      });
      
      res.json({
        payPeriod: updated,
        message: "Pay period locked successfully",
      });
    } catch (error: any) {
      console.error("Error locking pay period:", error);
      const errorCode = error.message?.includes("already locked") ? 'PAY_PERIOD_ALREADY_LOCKED' : 'UNKNOWN_ERROR';
      res.status(500).json({ 
        message: "Failed to lock pay period",
        code: errorCode
      });
    }
  });

  // Generate export for a pay period (CSV download)
  app.post("/api/payroll/exports/:payPeriodId/generate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const payPeriodId = req.params.payPeriodId;
      const exportType = (req.query.type as string) || 'ADP_CSV';
      const dryRun = req.query.dryRun === 'true';
      
      if (exportType !== 'ADP_CSV' && exportType !== 'OPENFORCE_CSV') {
        return res.status(400).json({ 
          message: "Invalid export type. Use ADP_CSV or OPENFORCE_CSV" 
        });
      }
      
      const payPeriodsList = await storage.getAllPayPeriods();
      const payPeriod = payPeriodsList.find((pp: any) => pp.id === payPeriodId);
      
      if (!payPeriod) {
        return res.status(404).json({ 
          message: "Pay period not found",
          code: 'PAY_PERIOD_NOT_FOUND',
        });
      }
      
      if (payPeriod.status !== 'LOCKED' && !dryRun) {
        if (!canExportPayroll({ email: currentUser?.email || req.user?.claims?.email || '' }, payPeriod)) {
           return res.status(403).json({ message: "Unauthorized: Only authorized lockers can export payroll" });
        }
        return res.status(400).json({
          message: `Pay period must be LOCKED before export. Current status: ${payPeriod.status}`,
          code: 'PAY_PERIOD_NOT_LOCKED',
          currentStatus: payPeriod.status,
        });
      }
      
      const trips = await storage.getTripsByPayPeriodWithEligibility(
        new Date(payPeriod.periodStart),
        new Date(payPeriod.periodEnd)
      );
      
      if (trips.length === 0) {
        return res.status(400).json({
          message: "No moves found for this pay period. Cannot generate export.",
          code: 'PAY_PERIOD_EMPTY',
        });
      }

      // Preview logic for dryRun
      if (dryRun) {
        const stats = {
          totalMoves: trips.length,
          includedMoves: trips.filter((t: any) => t.eligibilityStatus === 'PASS').length,
          excludedMoves: trips.filter((t: any) => t.eligibilityStatus !== 'PASS').length,
          exclusionReasons: {} as Record<string, number>,
          estimatedTotalCents: 0
        };

        trips.forEach((t: any) => {
          if (t.eligibilityStatus !== 'PASS') {
            const reason = t.eligibilityReasons?.[0] || 'Unknown';
            stats.exclusionReasons[reason] = (stats.exclusionReasons[reason] || 0) + 1;
          }
          stats.estimatedTotalCents += parseInt(t.payRate || '0') * 100;
        });

        return res.json({
          success: true,
          dryRun: true,
          message: "Dry run preview generated",
          stats
        });
      }
      
      if (trips.length === 0) {
        return res.status(400).json({
          message: "No moves found for this pay period. Cannot generate export.",
          code: 'PAY_PERIOD_EMPTY',
        });
      }
      
      const driversMap = new Map();
      const drivers = await storage.getAllDriversWithUsers();
      drivers.forEach((d: any) => {
        driversMap.set(d.id, d.fullName || d.user?.firstName + ' ' + d.user?.lastName || 'Unknown');
      });
      
      const { generatePayPeriodExport } = await import('./services/payrollExport');
      
      const moves: any[] = trips.map((t: any) => ({
        tripId: t.id,
        moveNumber: t.moveNumber,
        driverId: t.driverId,
        driverName: driversMap.get(t.driverId) || 'Unknown',
        tripDate: t.tripDate,
        origin: t.origin,
        destination: t.destination,
        distance: t.distance,
        duration: t.duration,
        payRate: t.payRate,
        eligibilityStatus: t.eligibilityStatus || null,
        eligibilityReasons: t.eligibilityReasons || null,
        workType: t.workType,
        executionMode: t.executionMode,
      }));
      
      const result = generatePayPeriodExport(
        {
          id: payPeriod.id,
          payGroup: payPeriod.payGroup,
          periodStart: payPeriod.periodStart,
          periodEnd: payPeriod.periodEnd,
          status: payPeriod.status as 'OPEN' | 'PROCESSING' | 'LOCKED',
          createdAt: new Date(payPeriod.createdAt),
          lockedAt: payPeriod.lockedAt ? new Date(payPeriod.lockedAt) : null,
        },
        moves,
        exportType as 'ADP_CSV' | 'OPENFORCE_CSV'
      );
      
      if (!result.allowed) {
        return res.status(400).json({
          message: result.errorMessage,
          code: result.errorCode,
        });
      }
      
      await storage.createExportAuditLog({
        payPeriodId,
        exportType: exportType as 'ADP_CSV' | 'OPENFORCE_CSV',
        fileName: result.fileName!,
        fileHash: result.fileHash!,
        rowCount: result.summary!.includedMoves,
        totalAmountCents: result.summary!.totalPayCents,
        createdBy: currentUserId,
      });
      
      // Log audit event for export generation
      const userEmail = currentUser?.email || req.user?.claims?.email || '';
      await storage.createPayPeriodAuditEvent({
        action: 'EXPORT_GENERATED',
        userId: userEmail,
        payPeriodId: payPeriodId,
        metadata: {
          exportType,
          fileName: result.fileName!,
          rowCount: result.summary!.includedMoves,
          totalPayCents: result.summary!.totalPayCents,
          payGroup: payPeriod.payGroup,
        },
      });
      
      await storage.updatePayPeriod(payPeriodId, {
        exportedAt: new Date(),
        exportType,
        exportStatus: 'EXPORTED',
      });
      
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="${result.fileName}"`);
      res.send(result.csvContent);
    } catch (error: any) {
      console.error("Error generating export:", error);
      const errorCode = error.message?.includes("No moves") ? 'PAY_PERIOD_EMPTY' : 'UNKNOWN_ERROR';
      res.status(500).json({ 
        message: "Failed to generate export",
        code: errorCode 
      });
    }
  });

