  // GET /api/payroll/timecards - List time entries with filters
  app.get("/api/payroll/timecards", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { driverId, startDate, endDate, payrollStatus, limit = '100', offset = '0' } = req.query;
      
      let query = db.select().from(timeEntries);
      const conditions = [];

      if (driverId) {
        conditions.push(eq(timeEntries.driverId, driverId as string));
      }
      if (startDate) {
        conditions.push(gte(timeEntries.startAt, new Date(startDate as string)));
      }
      if (endDate) {
        conditions.push(lte(timeEntries.startAt, new Date(endDate as string)));
      }
      if (payrollStatus) {
        conditions.push(eq(timeEntries.payrollStatus, payrollStatus as string));
      }

      const entries = await db.select()
        .from(timeEntries)
        .where(conditions.length > 0 ? and(...conditions) : undefined)
        .orderBy(desc(timeEntries.startAt))
        .limit(parseInt(limit as string))
        .offset(parseInt(offset as string));

      // Get total count
      const [countResult] = await db.select({ count: sql<number>`count(*)` })
        .from(timeEntries)
        .where(conditions.length > 0 ? and(...conditions) : undefined);

      res.json({
        entries,
        total: countResult?.count || 0,
        limit: parseInt(limit as string),
        offset: parseInt(offset as string),
      });
    } catch (error) {
      console.error("Error fetching timecards:", error);
      res.status(500).json({ message: "Failed to fetch timecards" });
    }
  });

