  // PATCH /api/payroll/exceptions/:id - Resolve an exception
  app.patch("/api/payroll/exceptions/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { status, resolutionNote } = req.body;

      if (!status || !['resolved', 'dismissed'].includes(status)) {
        return res.status(400).json({ message: "Invalid status. Must be 'resolved' or 'dismissed'" });
      }

      const [updated] = await db.update(timecardExceptions)
        .set({
          status,
          resolvedAt: new Date(),
          resolvedByUserId: currentUserId,
          resolutionNote: resolutionNote || null,
          updatedAt: new Date(),
        })
        .where(eq(timecardExceptions.id, parseInt(req.params.id)))
        .returning();

      if (!updated) {
        return res.status(404).json({ message: "Exception not found" });
      }

      res.json(updated);
    } catch (error) {
      console.error("Error updating exception:", error);
      res.status(500).json({ message: "Failed to update exception" });
    }
  });

  // GET /api/payroll/payable-hours - Get payable hours summary for a driver/period
  app.get("/api/payroll/payable-hours", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { driverId, startDate, endDate } = req.query;

      if (!driverId || !startDate || !endDate) {
        return res.status(400).json({ 
          message: "driverId, startDate, and endDate are required" 
        });
      }

      // Get all completed time entries for the driver in the period
      const entries = await db.select()
        .from(timeEntries)
        .where(and(
          eq(timeEntries.driverId, driverId as string),
          isNotNull(timeEntries.endAt),
          gte(timeEntries.startAt, new Date(startDate as string)),
          lte(timeEntries.startAt, new Date(endDate as string))
        ))
        .orderBy(timeEntries.startAt);

      // Calculate raw hours
      let totalMinutes = 0;
      let regularMinutes = 0;
      let overtimeMinutes = 0;
      const weeklyMinutes: Record<string, number> = {};

      for (const entry of entries) {
        const duration = entry.durationMinutes || 0;
        totalMinutes += duration;

        // Group by week for OT calculation
        const weekStart = getWeekStart(new Date(entry.startAt));
        const weekKey = weekStart.toISOString().split('T')[0];
        weeklyMinutes[weekKey] = (weeklyMinutes[weekKey] || 0) + duration;
      }

      // Calculate OT by week (40 hours = 2400 minutes threshold)
      for (const weekKey of Object.keys(weeklyMinutes)) {
        const weekTotal = weeklyMinutes[weekKey];
        if (weekTotal > 2400) {
          overtimeMinutes += weekTotal - 2400;
          regularMinutes += 2400;
        } else {
          regularMinutes += weekTotal;
        }
      }

      res.json({
        driverId,
        periodStart: startDate,
        periodEnd: endDate,
        rawHours: Math.round(totalMinutes / 60 * 100) / 100,
        rawMinutes: totalMinutes,
        regularHours: Math.round(regularMinutes / 60 * 100) / 100,
        regularMinutes,
        overtimeHours: Math.round(overtimeMinutes / 60 * 100) / 100,
        overtimeMinutes,
        otEligible: overtimeMinutes > 0,
        entryCount: entries.length,
        weeklyBreakdown: Object.entries(weeklyMinutes).map(([week, minutes]) => ({
          weekStart: week,
          hours: Math.round(minutes / 60 * 100) / 100,
          minutes,
        })),
      });
    } catch (error) {
      console.error("Error calculating payable hours:", error);
      res.status(500).json({ message: "Failed to calculate payable hours" });
    }
  });

  // Helper function to get week start (Monday)
  function getWeekStart(date: Date): Date {
    const d = new Date(date);
    const day = d.getDay();
    const diff = d.getDate() - day + (day === 0 ? -6 : 1); // Adjust to Monday
    return new Date(d.setDate(diff));
  }

  // GET /api/drivers/:id/time-summary - Get driver's time summary
  app.get("/api/drivers/:id/time-summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const driverId = req.params.id;

      // Get recent time entries (last 30 days)
      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);

      const recentEntries = await db.select()
        .from(timeEntries)
        .where(and(
          eq(timeEntries.driverId, driverId),
          gte(timeEntries.startAt, thirtyDaysAgo)
        ))
        .orderBy(desc(timeEntries.startAt))
        .limit(50);

      // Calculate summary
      let totalMinutes = 0;
      let openShiftCount = 0;
      for (const entry of recentEntries) {
        if (entry.durationMinutes) {
          totalMinutes += entry.durationMinutes;
        }
        if (!entry.endAt) {
          openShiftCount++;
        }
      }

      // Get open exceptions count
      const [exceptionCount] = await db.select({ count: sql<number>`count(*)` })
        .from(timecardExceptions)
        .where(and(
          eq(timecardExceptions.driverId, driverId),
          eq(timecardExceptions.status, 'open')
        ));

      res.json({
        driverId,
        periodDays: 30,
        totalHours: Math.round(totalMinutes / 60 * 100) / 100,
        totalMinutes,
        entryCount: recentEntries.length,
        openShiftCount,
        openExceptionCount: exceptionCount?.count || 0,
        recentEntries: recentEntries.slice(0, 10), // Last 10 entries
      });
    } catch (error) {
      console.error("Error fetching driver time summary:", error);
      res.status(500).json({ message: "Failed to fetch driver time summary" });
    }
  });

