  // ITEM 13: Eligibility Snapshot Backfill (Idempotent)
  // Admin-only endpoint to backfill eligibility snapshots for existing moves
  app.post("/api/admin/backfill-eligibility", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role;
      
      if (!currentUser || (role !== "super_user" && role !== "admin")) {
        return res.status(403).json({ 
          message: "Admin access required for eligibility backfill",
          code: 'ADMIN_REQUIRED',
        });
      }

      console.log("[BackfillEligibility] Starting eligibility snapshot backfill...");
      
      // Import required functions
      const { evaluateMoveEligibility } = await import('./services/eligibility');
      const { buildDriverEligibilityFromDriver } = await import('./imports/importMoves');
      
      // Get all trips without eligibility snapshots
      const tripsToBackfill = await storage.getTripsWithoutEligibility();
      const totalScanned = tripsToBackfill.length;
      let backfilled = 0;
      let skipped = 0;
      const errors: string[] = [];
      
      console.log(`[BackfillEligibility] Found ${totalScanned} trips without eligibility snapshots`);
      
      for (const trip of tripsToBackfill) {
        try {
          // Double-check eligibility status is null (idempotent check)
          if (trip.eligibilityStatus) {
            skipped++;
            continue;
          }
          
          // Build driver eligibility if driver exists
          let driverEligibility = null;
          if (trip.driverId) {
            const driver = await storage.getDriver(trip.driverId);
            driverEligibility = buildDriverEligibilityFromDriver(driver);
          }
          
          // Build move context from trip
          const moveContext: any = {
            moveNumber: trip.moveNumber,
            marketId: trip.marketId || undefined,
            zoneId: trip.zoneId || undefined,
            workType: trip.workType || undefined,
            executionMode: trip.executionMode || undefined,
          };
          
          // Evaluate eligibility using current policy
          const snapshot = evaluateMoveEligibility(driverEligibility, moveContext);
          
          // Write the eligibility snapshot
          await storage.updateTripEligibility(trip.id, {
            eligibilityStatus: snapshot.eligibilityStatus,
            eligibilityReasons: snapshot.eligibilityReasons,
            eligibilityCheckedAt: new Date(snapshot.eligibilityCheckedAt),
            eligibilityPolicyVersionId: snapshot.eligibilityPolicyVersionId,
            marketId: trip.marketId || undefined,
            zoneId: trip.zoneId || undefined,
            workType: trip.workType || undefined,
            executionMode: trip.executionMode || undefined,
          });
          
          backfilled++;
        } catch (tripError: any) {
          errors.push(`Trip ${trip.id}: ${tripError.message}`);
        }
      }
      
      console.log(`[BackfillEligibility] Complete: scanned=${totalScanned}, backfilled=${backfilled}, skipped=${skipped}`);
      if (errors.length > 0) {
        console.log(`[BackfillEligibility] Errors: ${errors.length}`);
      }
      
      res.json({ 
        success: true,
        message: "Eligibility snapshot backfill completed",
        triggeredBy: currentUser.email,
        triggeredAt: new Date().toISOString(),
        stats: {
          totalScanned,
          backfilled,
          skipped,
          errors: errors.length,
        },
        errorDetails: errors.length > 0 ? errors : undefined,
      });
    } catch (error: any) {
      console.error("[BackfillEligibility] Error:", error);
      res.status(500).json({ message: "Failed to run eligibility backfill", error: error.message });
    }
  });

