  // Admin: Link a user to a driver profile
  const linkDriverSchema = z.object({
    userId: z.string().min(1, "userId is required"),
    driverId: z.string().min(1, "driverId is required"),
  });

  app.post("/api/admin/drivers/link", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role;
      
      if (!currentUser || (role !== "super_user" && role !== "admin")) {
        return res.status(403).json({ 
          error: "ADMIN_REQUIRED",
          message: "Admin access required to link driver profiles",
        });
      }

      const parseResult = linkDriverSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          error: "VALIDATION_ERROR",
          message: "Invalid request data",
          details: parseResult.error.flatten().fieldErrors,
        });
      }

      const { userId, driverId } = parseResult.data;

      // Verify user exists
      const targetUser = await storage.getUser(userId);
      if (!targetUser) {
        return res.status(404).json({ 
          error: "USER_NOT_FOUND",
          message: "Target user not found",
        });
      }

      // Verify driver exists
      const driver = await storage.getDriver(driverId);
      if (!driver) {
        return res.status(404).json({ 
          error: "DRIVER_NOT_FOUND",
          message: "Driver profile not found",
        });
      }

      // Link driverId to user — intentionally does NOT change the user's role.
      // Role changes may only be made manually by Super Admin or Corporate Admin.
      await db.update(users)
        .set({ 
          driverId: driverId,
          updatedAt: new Date(),
        })
        .where(eq(users.id, userId));

      console.log(`[Driver Link] Linked user ${userId} (role: ${targetUser.role}) to driver ${driverId} — role unchanged.`);

      // Update driver's userId
      await db.update(drivers)
        .set({ 
          userId: userId,
          updatedAt: new Date(),
        })
        .where(eq(drivers.id, driverId));

      // Fetch updated records
      const updatedUser = await storage.getUser(userId);
      const updatedDriver = await storage.getDriver(driverId);

      console.log(`[Admin] Linked user ${userId} to driver ${driverId} by admin ${currentUserId}`);

      res.json({
        success: true,
        message: "User linked to driver profile successfully",
        user: {
          id: updatedUser?.id,
          email: updatedUser?.email,
          driverId: updatedUser?.driverId,
          role: updatedUser?.role,
        },
        driver: {
          id: updatedDriver?.id,
          firstName: updatedDriver?.firstName,
          lastName: updatedDriver?.lastName,
          userId: updatedDriver?.userId,
        },
      });
    } catch (error: any) {
      console.error("[Admin] Link driver error:", error);
      res.status(500).json({ 
        error: "INTERNAL_ERROR",
        message: "Failed to link driver profile",
      });
    }
  });

