  // Admin: Update feedback ticket (status, priority, assignment)
  app.patch("/api/admin/feedback/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await storage.getUser(userId);
      if (!user || !hasCorporateAccess(user)) {
        return res.status(403).json({ message: "Corporate access required" });
      }

      const ticket = await storage.getFeedbackTicket(req.params.id);
      if (!ticket) {
        return res.status(404).json({ message: "Ticket not found" });
      }

      const { status, priority, assignedToUserId } = req.body;
      const updates: any = {};
      
      if (status && status !== ticket.status) {
        updates.status = status;
        await storage.createFeedbackAuditLog({
          ticketId: ticket.id,
          actorUserId: userId,
          actorName: user.email || 'Unknown',
          action: 'STATUS_CHANGED',
          fromValue: ticket.status,
          toValue: status,
        });
      }
      
      if (priority && priority !== ticket.priority) {
        updates.priority = priority;
        await storage.createFeedbackAuditLog({
          ticketId: ticket.id,
          actorUserId: userId,
          actorName: user.email || 'Unknown',
          action: 'PRIORITY_CHANGED',
          fromValue: ticket.priority,
          toValue: priority,
        });
      }
      
      if (assignedToUserId !== undefined && assignedToUserId !== ticket.assignedToUserId) {
        updates.assignedToUserId = assignedToUserId;
        await storage.createFeedbackAuditLog({
          ticketId: ticket.id,
          actorUserId: userId,
          actorName: user.email || 'Unknown',
          action: 'ASSIGNED',
          fromValue: ticket.assignedToUserId || 'Unassigned',
          toValue: assignedToUserId || 'Unassigned',
        });
      }

      if (Object.keys(updates).length === 0) {
        return res.json(ticket);
      }

      const updated = await storage.updateFeedbackTicket(req.params.id, updates);
      res.json(updated);
    } catch (error) {
      console.error("Error updating feedback ticket:", error);
      res.status(500).json({ message: "Failed to update ticket" });
    }
  });

