  // GET /api/documents — List documents by owner
  app.get("/api/documents", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!currentUserId) return res.status(401).json({ error_code: "UNAUTHORIZED", message: "Authentication required" });

      const ownerType = (req.query.owner_type || req.query.entityType) as string;
      const ownerId = (req.query.owner_id || req.query.entityId) as string;

      if (!ownerType) {
        return res.status(400).json({ error_code: "BAD_REQUEST", message: "owner_type query parameter is required" });
      }

      const { getDocuments } = await import("./services/documentService");
      const docs = await getDocuments(ownerType, ownerId || null);

      const now = new Date();
      const thirtyDays = 30 * 24 * 60 * 60 * 1000;
      const enriched = docs.map((d: any) => {
        const exp = d.expirationDate ? new Date(d.expirationDate) : null;
        return {
          ...d,
          isExpired: exp ? exp < now : false,
          isExpiringSoon: exp ? (!((exp < now)) && exp.getTime() - now.getTime() < thirtyDays) : false,
        };
      });

      res.json(enriched);
    } catch (error: any) {
      console.error("[DocumentService] List error:", error);
      res.status(500).json({ error_code: "INTERNAL_ERROR", message: error.message || "Failed to list documents" });
    }
  });

