      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!currentUserId) return res.status(401).json({ error_code: "UNAUTHORIZED", message: "Authentication required" });

      const { getDocument, isPreviewable, generateSignedDownloadUrl } = await import("./services/documentService");
