  app.patch("/api/documents/:documentId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { documentId } = req.params;
      const { label, docType, issueDate, expirationDate, status, notes } = req.body;

      let existing = await storage.getAccountDocument(documentId);
      let isUnifiedOnly = false;
      if (!existing) {
        // Check unified documents table
        const { getDocument: getUnifiedDoc } = await import("./services/documentService");
        const unifiedDoc = await getUnifiedDoc(documentId);
        if (!unifiedDoc || unifiedDoc.status === "deleted") {
          return res.status(404).json({ message: "Document not found" });
        }
        isUnifiedOnly = true;
        // Map unified doc fields for compatibility
        existing = {
          id: unifiedDoc.id,
          customerId: unifiedDoc.ownerId || "",
          filename: unifiedDoc.fileName,
          originalFilename: unifiedDoc.fileName,
          fileUrl: unifiedDoc.storageKey,
          fileSize: unifiedDoc.fileSizeBytes || 0,
          mimeType: unifiedDoc.contentType,
          category: unifiedDoc.category || "Other",
          label: unifiedDoc.title,
          docType: null,
          issueDate: null,
          expirationDate: null,
          status: unifiedDoc.status === "active" ? "pending" : unifiedDoc.status,
          notes: null,
          verifiedBy: null,
          verifiedAt: null,
          uploadedByUserId: unifiedDoc.uploadedByUserId,
          updatedBy: null,
          uploadedAt: unifiedDoc.uploadedAt,
          createdAt: unifiedDoc.createdAt,
          updatedAt: unifiedDoc.updatedAt,
        } as any;
      }

      const validStatuses = ["pending", "approved", "rejected"];
      if (status !== undefined && !validStatuses.includes(status)) {
        return res.status(400).json({ message: `Invalid status. Must be one of: ${validStatuses.join(", ")}` });
      }

      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (issueDate !== undefined && issueDate !== null && !dateRegex.test(issueDate)) {
        return res.status(400).json({ message: "Invalid issueDate format. Use YYYY-MM-DD" });
      }
      if (expirationDate !== undefined && expirationDate !== null && !dateRegex.test(expirationDate)) {
        return res.status(400).json({ message: "Invalid expirationDate format. Use YYYY-MM-DD" });
      }

      const updates: Record<string, any> = { updatedBy: currentUserId };

      if (label !== undefined) updates.label = label;
      if (docType !== undefined) updates.docType = docType;
      if (issueDate !== undefined) updates.issueDate = issueDate || null;
      if (expirationDate !== undefined) updates.expirationDate = expirationDate || null;
      if (notes !== undefined) updates.notes = notes;

      if (status !== undefined) {
        updates.status = status;
        if (status === "approved") {
          updates.verifiedBy = currentUserId;
          updates.verifiedAt = new Date();
        } else if (existing.status === "approved") {
          updates.verifiedBy = null;
          updates.verifiedAt = null;
        }
      }

      let updated: any;
      if (isUnifiedOnly) {
        const { updateDocumentMetadata } = await import("./services/documentService");
        const unifiedUpdates: any = {};
        if (label !== undefined) unifiedUpdates.title = label;
        if (status !== undefined) unifiedUpdates.status = status === "approved" ? "active" : status === "rejected" ? "archived" : "active";
        updated = await updateDocumentMetadata(documentId, unifiedUpdates, currentUserId);
      } else {
        updated = await storage.updateAccountDocument(documentId, updates);
      }

      try {
        const { db } = await import("./db");
        const { documentEvents: docEventsTable } = await import("@shared/schema");
        const changedFields: Record<string, { before: any; after: any }> = {};
        if (label !== undefined && label !== existing.label) changedFields.label = { before: existing.label, after: label };
        if (docType !== undefined && docType !== existing.docType) changedFields.docType = { before: existing.docType, after: docType };
        if (issueDate !== undefined && issueDate !== (existing.issueDate || null)) changedFields.issueDate = { before: existing.issueDate || null, after: issueDate || null };
        if (expirationDate !== undefined && expirationDate !== (existing.expirationDate || null)) changedFields.expirationDate = { before: existing.expirationDate || null, after: expirationDate || null };
        if (status !== undefined && status !== existing.status) changedFields.status = { before: existing.status, after: status };
        if (notes !== undefined && notes !== existing.notes) changedFields.notes = { before: existing.notes || null, after: notes || null };

        if (Object.keys(changedFields).length > 0) {
          await db.insert(docEventsTable).values({
            documentId,
            ownerType: "account",
            ownerId: existing.customerId,
            eventType: "document.updated",
            performedByUserId: currentUserId,
            metadata: { changes: changedFields, fieldNames: Object.keys(changedFields) },
          });
        }
      } catch (auditErr) {
        console.error("[DocumentService] Non-blocking audit log error:", auditErr);
      }

      res.json({ document: updated });
    } catch (error: any) {
      console.error("Error updating document metadata:", error);
      res.status(500).json({ message: "Failed to update document metadata" });
    }
  });

