  // Log a touch activity (creates activity + updates customer dates)
  app.post("/api/corporate/customers/:customerId/log-touch", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      // If user not found by sub, try by email (handles OIDC sub mismatch with pre-seeded users)
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      // Validate request body
      const TOUCH_TYPE_LABELS: Record<string, string> = {
        call: 'Call',
        email: 'Email',
        meeting: 'Virtual Meeting',       // legacy value — still accepted for compat
        virtual_meeting: 'Virtual Meeting',
        text: 'Text',
        marketing_campaign: 'Marketing Campaign',
        bulk_email: 'Bulk Email',
        in_person: 'In-Person',
        trade_event: 'Trade Event',
      };
      const logTouchSchema = z.object({
        activityType: z.enum([
          'call', 'email',
          'meeting',           // legacy — keep for any cached client sessions
          'virtual_meeting', 'text', 'marketing_campaign', 'bulk_email', 'in_person', 'trade_event',
        ]),
        notes: z.string().nullable().optional(),
      });

      const { activityType, notes } = logTouchSchema.parse(req.body);

      // Use database user ID for FK constraint compliance
      const dbUserId = currentUser?.id || currentUserId;

      const result = await storage.logTouchActivity(
        req.params.customerId,
        activityType,
        notes || null,
        dbUserId
      );

      // Also create an activity event for the touch
      await storage.createAccountActivityEvent({
        accountId: req.params.customerId,
        category: 'touch',
        eventType: 'touch_logged',
        summary: `Touch logged: ${TOUCH_TYPE_LABELS[activityType] ?? activityType}`,
        createdByUserId: dbUserId,
        metadata: notes ? JSON.stringify({ notes }) : null,
      });

      // Recalculate health after touch (touch updates nextRequiredTouchDate)
      await storage.calculateAccountHealth(req.params.customerId);

      res.json(result);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error logging touch activity:", error);
      res.status(500).json({ message: "Failed to log touch activity" });
    }
  });

