  // Delete a standard document (admin only)
  app.delete("/api/corporate/standard-documents/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;

      // Only Super Admins can delete standard documents
      const isSuperAdmin = currentUser?.role === 'super_user' || !!(currentUser as any)?.isRootSuperAdmin;
      if (!isSuperAdmin) {
        return res.status(403).json({ error_code: 'SUPER_ADMIN_REQUIRED', message: 'Only Super Administrators can delete documents and attachments' });
      }

      const { deletionReason } = req.body || {};
      if (!deletionReason || String(deletionReason).trim().length < 10) {
        return res.status(400).json({ error_code: 'REASON_REQUIRED', message: 'A deletion reason of at least 10 characters is required' });
      }

      const { standardDocuments: stdDocsTable } = await import('../shared/schema');
      const { eq } = await import('drizzle-orm');
      const { db } = await import('./db');
      const [doc] = await db.select().from(stdDocsTable).where(eq(stdDocsTable.id, req.params.id)).limit(1);
      if (!doc || doc.isDeleted) {
        return res.status(404).json({ message: 'Standard document not found' });
      }

      await db.update(stdDocsTable)
        .set({ isDeleted: true, deletedAt: new Date(), deletedByUserId: currentUserId, deletionReason: String(deletionReason).trim() })
        .where(eq(stdDocsTable.id, req.params.id));

      const { writeSystemAuditEvent } = await import('./services/systemAuditLogService');
      await writeSystemAuditEvent({
        eventType: 'document.deleted',
        actorUserId: currentUserId!,
        actorUserEmail: (currentUser as any)?.email,
        targetEntityType: 'standard_document',
        targetEntityId: req.params.id,
        targetEntityLabel: doc.name,
        reason: String(deletionReason).trim(),
        metadata: { filename: doc.filename, restrictedAction: true },
        ipAddress: req.ip,
      });

      res.json({ ok: true });
    } catch (error) {
      console.error('Error deleting standard document:', error);
      res.status(500).json({ message: 'Failed to delete standard document' });
    }
  });
  
