  app.get("/api/insurance-cards", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user   = userId ? await storage.getUser(userId) : null;
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Access denied" });
      const { state, batchId, includeArchived } = req.query;
      let q = `SELECT ic.*, icb.batch_name, icb.policy_year, icb.status AS batch_status
               FROM insurance_cards ic
               LEFT JOIN insurance_card_batches icb ON ic.batch_id = icb.id
               WHERE 1=1`;
      const p: any[] = [];
      let n = 1;
      if (state)   { q += ` AND ic.state = $${n++}`;    p.push(String(state).toUpperCase()); }
      if (batchId) { q += ` AND ic.batch_id = $${n++}`; p.push(parseInt(String(batchId))); }
      if (includeArchived !== "true") q += " AND ic.archived_at IS NULL";
      q += " ORDER BY ic.state, ic.uploaded_at DESC";
      const { rows } = await pool.query(q, p);
      res.json(rows);
    } catch (e: any) {
      console.error("[InsuranceCards] list:", e.message);
      res.status(500).json({ message: "Failed to fetch insurance cards" });
    }
  });

