  app.post("/api/insurance-cards/batches/:batchId/activate", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId  = req.user?.claims?.sub || (req.session as any)?.userId;
      const user    = userId ? await storage.getUser(userId) : null;
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Access denied" });
      const batchId = parseInt(req.params.batchId);
      const { rows: prevActive } = await pool.query(`SELECT id FROM insurance_card_batches WHERE status = 'active'`);
      for (const prev of prevActive) {
        await pool.query(`UPDATE insurance_cards SET active = false, archived_at = NOW(), archived_by = $1 WHERE batch_id = $2 AND archived_at IS NULL`, [userId, prev.id]);
        await pool.query(`UPDATE insurance_card_batches SET status = 'archived', archived_at = NOW(), archived_by = $1 WHERE id = $2`, [userId, prev.id]);
        await pool.query(`INSERT INTO insurance_card_audit_log (batch_id, action, performed_by, details) VALUES ($1,'batch_archived',$2,'{}')`, [prev.id, userId]);
      }
      await pool.query(`UPDATE insurance_cards SET active = true WHERE batch_id = $1 AND archived_at IS NULL`, [batchId]);
      const { rows } = await pool.query(
        `UPDATE insurance_card_batches SET status = 'active', activated_at = NOW(), activated_by = $1 WHERE id = $2 RETURNING *`,
        [userId, batchId]
      );
      if (!rows.length) return res.status(404).json({ message: "Batch not found" });
      await pool.query(`INSERT INTO insurance_card_audit_log (batch_id, action, performed_by, details) VALUES ($1,'batch_activated',$2,'{}')`, [batchId, userId]);
      res.json(rows[0]);
    } catch (e: any) {
      console.error("[InsuranceCards] activate batch:", e.message);
      res.status(500).json({ message: "Failed to activate batch" });
    }
  });

