  // ============================================
  // Send Document Packet
  // ============================================
  
  // Send a document packet to recipients
  app.post("/api/corporate/customers/:customerId/send-document-packet", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      
      const sendSchema = z.object({
        standardDocumentIds: z.array(z.string()).min(1),
        recipientEmails: z.array(z.string().email()).min(1),
      });
      
      const parseResult = sendSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ message: "Validation failed", errors: parseResult.error.errors });
      }
      
      const { standardDocumentIds, recipientEmails } = parseResult.data;
      
      // Get customer info
      const customer = await storage.getCustomer(req.params.customerId);
      if (!customer) {
        return res.status(404).json({ message: "Customer not found" });
      }
      
      // Get standard documents
      const documents = await Promise.all(
        standardDocumentIds.map(id => storage.getStandardDocument(id))
      );
      
      const validDocuments = documents.filter((doc): doc is NonNullable<typeof doc> => doc !== undefined);
      if (validDocuments.length === 0) {
        return res.status(400).json({ message: "No valid documents found" });
      }
      
      const documentNames = validDocuments.map(d => d.name);
      const documentUrls = validDocuments.map(d => ({ name: d.name, url: d.fileUrl }));
      
      // Send emails to all recipients
      const { sendDocumentPacketEmail } = await import("./emailService");
      const senderName = currentUser ? `${currentUser.firstName} ${currentUser.lastName}` : 'DriverHub 360';
      
      let allSuccess = true;
      let lastError: string | undefined;
      
      for (const email of recipientEmails) {
        const result = await sendDocumentPacketEmail({
          to: email,
          customerName: customer.customerName,
          senderName,
          documentNames,
          documentUrls,
        });
        
        if (!result.success) {
          allSuccess = false;
          lastError = result.error;
        }
      }
      
      // Log the activity
      await storage.createDocumentPacketLog({
        customerId: req.params.customerId,
        standardDocumentIds: JSON.stringify(standardDocumentIds),
        documentNames: JSON.stringify(documentNames),
        recipientEmails: JSON.stringify(recipientEmails),
        status: allSuccess ? 'sent' : 'failed',
        errorMessage: lastError,
        sentByUserId: currentUserId,
      });
      
      if (allSuccess) {
        res.json({ 
          message: "Document packet sent successfully",
          documentsSent: documentNames,
          recipientCount: recipientEmails.length,
        });
      } else {
        res.status(207).json({ 
          message: "Some emails failed to send",
          error: lastError,
          documentsSent: documentNames,
        });
      }
    } catch (error) {
      console.error("Error sending document packet:", error);
      res.status(500).json({ message: "Failed to send document packet" });
    }
  });

