      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser || currentUser.role !== 'admin') {
        return res.status(403).json({ message: "Admin access required" });
      }

      const createSchema = z.object({
        name: z.string().min(1),
        description: z.string().optional(),
        triggerType: z.enum(['volume_drop', 'ar_past_due', 'health_red', 'sla_breach']),
        triggerConfig: z.string(),
        actions: z.string(),
        enabled: z.boolean().optional().default(true),
        priority: z.number().optional().default(100),
      });

      const parseResult = createSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ message: "Validation failed", errors: parseResult.error.errors });
      }

      const playbook = await storage.createPlaybook({
        ...parseResult.data,
        createdByUserId: currentUserId,
      });

