  // Add an addendum to a decision (immutable - no editing original)
  app.post("/api/decisions/:id/addendum", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { content } = req.body;
      if (!content || !content.trim()) {
        return res.status(400).json({ message: "Addendum content is required" });
      }

      // Verify decision exists
      const decision = await storage.getAccountDecisionById(req.params.id);
      if (!decision) {
        return res.status(404).json({ message: "Decision not found" });
      }

      const addendum = await storage.createDecisionAddendum({
        decisionId: req.params.id,
        content: content.trim(),
        addedBy: currentUser?.id || null,
        addedByName: currentUser ? `${currentUser.firstName || ''} ${currentUser.lastName || ''}`.trim() || currentUser.email : 'Unknown',
      });

      // Log addendum to Activity Timeline
      await storage.createAccountActivityEvent({
        accountId: decision.accountId,
        category: 'status',
        eventType: 'decision_addendum',
        summary: `Addendum added to ${decision.decisionType} decision: ${content.substring(0, 80)}${content.length > 80 ? '...' : ''}`,
        triggeredBy: currentUser?.id || 'system',
      });

      res.status(201).json(addendum);
    } catch (error) {
      console.error("Error creating decision addendum:", error);
      res.status(500).json({ message: "Failed to create decision addendum" });
    }
  });

