  app.post("/api/accounts/:id/notes", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = await storage.getUser(currentUserId);
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      const { noteType, content, noteDate, tripId, zendeskId, attachmentDocumentId, attachmentFileName } = req.body;
      if (!noteType || !content?.trim()) {
        return res.status(400).json({ message: "noteType and content are required" });
      }
      const submittedByName = currentUser?.firstName && currentUser?.lastName
        ? `${currentUser.firstName} ${currentUser.lastName}`
        : currentUser?.email || "Unknown";
      const note = await storage.createAccountNote({
        customerId: req.params.id,
        noteDate: noteDate || new Date().toISOString().split('T')[0],
        submittedByUserId: currentUserId,
        submittedByName,
        noteType,
        content: content.trim(),
        tripId: tripId || null,
        zendeskId: zendeskId || null,
        attachmentDocumentId: attachmentDocumentId || null,
        attachmentFileName: attachmentFileName || null,
      });

      // Route note attachment into account_documents for visibility and access
      if (attachmentDocumentId && attachmentFileName) {
        try {
          const { documents: docsTable } = await import('../shared/schema');
          const [unifiedDoc] = await db.select().from(docsTable).where(eq(docsTable.id, attachmentDocumentId)).limit(1);
          if (unifiedDoc) {
            await storage.createAccountDocument({
              customerId: req.params.id,
              filename: unifiedDoc.fileName,
              originalFilename: attachmentFileName,
              fileUrl: unifiedDoc.storageKey,
              fileSize: unifiedDoc.fileSizeBytes ?? undefined,
              mimeType: unifiedDoc.contentType,
              category: "Other",
              notes: `Source: Account Note | Note ID: ${note.id} | Note Type: ${noteType}`,
              unifiedDocumentId: attachmentDocumentId,
              uploadedByUserId: currentUserId,
            });
          }
        } catch (docErr) {
          console.error("[Notes] Non-blocking: failed to register attachment in account_documents:", docErr);
        }
      }

      // Write to activity timeline
      try {
        await storage.createAccountActivityEvent({
          accountId: req.params.id,
          eventType: 'note_added',
          category: 'note',
          summary: `Note added (${noteType}): ${content.trim().substring(0, 100)}`,
          createdByUserId: currentUserId,
          metadata: JSON.stringify({ noteId: note.id, noteType }),
        });
      } catch {}
      res.status(201).json(note);
    } catch (error) {
      console.error("Error creating account note:", error);
      res.status(500).json({ message: "Failed to create account note" });
    }
  });

