  // PATCH /api/accounts/:id/notes/:noteId — Edit note (all corporate users)
  app.patch("/api/accounts/:id/notes/:noteId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = await storage.getUser(currentUserId);
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      if (!hasCorporateAccess(role)) {
        return res.status(403).json({ message: "Access denied" });
      }
      const { content, noteType, noteDate, tripId, zendeskId, reason } = req.body;
      if (!reason || reason.trim().length < 10) {
        return res.status(400).json({ message: "A reason of at least 10 characters is required to edit a note" });
      }
      if (content !== undefined && !content.trim()) {
        return res.status(400).json({ message: "Note content cannot be blank" });
      }
      const note = await storage.getAccountNote(req.params.noteId);
      if (!note || note.customerId !== req.params.id || note.deletedAt) {
        return res.status(404).json({ message: "Note not found" });
      }
      const updated = await storage.updateAccountNote(
        req.params.noteId,
        currentUserId,
        { content: content?.trim(), noteType, noteDate, tripId, zendeskId },
        reason.trim()
      );
      if (!updated) {
        return res.status(404).json({ message: "Note not found or already deleted" });
      }
      // Write to activity timeline
      try {
        await storage.createAccountActivityEvent({
          accountId: req.params.id,
          eventType: 'note_edited',
          category: 'note',
          summary: `Note edited (${updated.noteType}): ${updated.content.substring(0, 100)}`,
          createdByUserId: currentUserId,
          metadata: JSON.stringify({ noteId: updated.id, noteType: updated.noteType, reason: reason.trim() }),
        });
      } catch {}
      res.json(updated);
    } catch (error) {
      console.error("Error editing account note:", error);
      res.status(500).json({ message: "Failed to edit note" });
    }
  });

  // DELETE /api/accounts/:id/notes/:noteId — Soft delete (all corporate users)
  app.delete("/api/accounts/:id/notes/:noteId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const { reason, deleteAttachment } = req.body;
      if (!reason || reason.trim().length < 10) {
        return res.status(400).json({ message: "A reason of at least 10 characters is required to delete a note" });
      }
      const note = await storage.getAccountNote(req.params.noteId);
      if (!note || note.customerId !== req.params.id) {
        return res.status(404).json({ message: "Note not found" });
      }
      const deleted = await storage.softDeleteAccountNote(req.params.noteId, currentUserId, reason.trim());
      if (!deleted) {
        return res.status(404).json({ message: "Note not found or already deleted" });
      }

      // Optionally delete the attached document when requested
      let attachmentDeleteError: string | null = null;
      if (deleteAttachment && note.attachmentDocumentId) {
        try {
          const { softDeleteDocument } = await import('./services/documentService');
          await softDeleteDocument(note.attachmentDocumentId, currentUserId, reason.trim());
        } catch (attachErr: any) {
          console.error("[NoteDelete] Failed to delete attached document:", attachErr);
          attachmentDeleteError = attachErr?.message || "Failed to delete attached document";
        }
      }

      res.json({ ok: true, attachmentDeleteError });
    } catch (error) {
      console.error("Error deleting account note:", error);
      res.status(500).json({ message: "Failed to delete note" });
    }
  });

