  // ============================================
  // DRIVERCONNECT INTEGRATION - EXECUTION EVENT INGESTION API
  // ============================================

  // Service-to-service authentication middleware for integration endpoints
  async function integrationAuth(req: any, res: Response, next: Function) {
    try {
      const authHeader = req.headers['authorization'];
      if (!authHeader || !authHeader.startsWith('Bearer ')) {
        // Log unauthorized attempt
        await logIngestionAudit({
          requestId: `req_${Date.now()}_${Math.random().toString(36).substring(7)}`,
          keyId: 'unknown',
          keyPrefix: null,
          sourceIp: req.ip || req.connection?.remoteAddress,
          userAgent: req.headers['user-agent'],
          endpoint: req.path,
          method: req.method,
          eventCount: 0,
          acceptedCount: 0,
          rejectedCount: 0,
          duplicateCount: 0,
          responseStatus: 401,
          errorCode: 'UNAUTHORIZED',
          errorMessage: 'Missing or invalid Authorization header'
        });
        return res.status(401).json({ 
          error: 'UNAUTHORIZED',
          message: 'Missing or invalid Authorization header. Use Bearer token.'
        });
      }

      const token = authHeader.substring(7);
      const tokenPrefix = token.substring(0, 8);
      
      // Check if it's the configured API key from environment
      const configuredKey = process.env.DRIVERHUB_API_KEY;
      if (configuredKey && token === configuredKey) {
        req.integrationSource = 'execution_layer';
        req.integrationKeyId = 'env_configured';
        req.integrationKeyPrefix = 'env_****';
        return next();
      }

      // Otherwise, check database for API key
      const crypto = await import('crypto');
      const keyHash = crypto.createHash('sha256').update(token).digest('hex');
      
      const [apiKey] = await db.select()
        .from(integrationApiKeys)
        .where(and(
          eq(integrationApiKeys.keyHash, keyHash),
          eq(integrationApiKeys.isActive, true)
        ))
        .limit(1);

      if (!apiKey) {
        // Log invalid key attempt
        await logIngestionAudit({
          requestId: `req_${Date.now()}_${Math.random().toString(36).substring(7)}`,
          keyId: 'invalid',
          keyPrefix: tokenPrefix,
          sourceIp: req.ip || req.connection?.remoteAddress,
          userAgent: req.headers['user-agent'],
          endpoint: req.path,
          method: req.method,
          eventCount: 0,
          acceptedCount: 0,
          rejectedCount: 0,
          duplicateCount: 0,
          responseStatus: 401,
          errorCode: 'UNAUTHORIZED',
          errorMessage: 'Invalid API key'
        });
        return res.status(401).json({ 
          error: 'UNAUTHORIZED',
          message: 'Invalid API key'
        });
      }

      // Check expiration
      if (apiKey.expiresAt && new Date(apiKey.expiresAt) < new Date()) {
        // Log expired key attempt
        await logIngestionAudit({
          requestId: `req_${Date.now()}_${Math.random().toString(36).substring(7)}`,
          keyId: apiKey.id,
          keyPrefix: apiKey.keyPrefix,
          sourceIp: req.ip || req.connection?.remoteAddress,
          userAgent: req.headers['user-agent'],
          endpoint: req.path,
          method: req.method,
          eventCount: 0,
          acceptedCount: 0,
          rejectedCount: 0,
          duplicateCount: 0,
          responseStatus: 401,
          errorCode: 'KEY_EXPIRED',
          errorMessage: 'API key has expired'
        });
        return res.status(401).json({ 
          error: 'KEY_EXPIRED',
          message: 'API key has expired'
        });
      }

      // Update usage stats
      await db.update(integrationApiKeys)
        .set({ 
          lastUsedAt: new Date(),
          usageCount: sql`${integrationApiKeys.usageCount} + 1`
        })
        .where(eq(integrationApiKeys.id, apiKey.id));

      req.integrationSource = apiKey.sourceSystem;
      req.integrationKeyId = apiKey.id;
      req.integrationKeyPrefix = apiKey.keyPrefix;
      next();
    } catch (error) {
      console.error('[Integration Auth] Error:', error);
      return res.status(500).json({ 
        error: 'AUTH_ERROR',
        message: 'Authentication error'
      });
    }
  }

  // Audit logging helper for ingestion requests
  async function logIngestionAudit(params: {
    requestId: string;
    keyId: string;
    keyPrefix: string | null;
    sourceIp: string | null;
    userAgent: string | null;
    endpoint: string;
    method: string;
    eventCount: number;
    acceptedCount: number;
    rejectedCount: number;
    duplicateCount: number;
    responseStatus: number;
    responseTimeMs?: number;
    errorCode?: string;
    errorMessage?: string;
  }) {
    try {
      await db.insert(ingestionAuditLogs).values({
        requestId: params.requestId,
        keyId: params.keyId,
        keyPrefix: params.keyPrefix,
        sourceIp: params.sourceIp,
        userAgent: params.userAgent,
        endpoint: params.endpoint,
        method: params.method,
        eventCount: params.eventCount,
        acceptedCount: params.acceptedCount,
        rejectedCount: params.rejectedCount,
        duplicateCount: params.duplicateCount,
        responseStatus: params.responseStatus,
        responseTimeMs: params.responseTimeMs,
        errorCode: params.errorCode,
        errorMessage: params.errorMessage,
      });
    } catch (error) {
      console.error('[Audit Log] Error logging ingestion audit:', error);
    }
  }

  // =====================================
  // REFERENCE DATA MAPPING (Ticket 22)
  // =====================================

  // Event types that require move_id validation
  const moveRequiredEventTypes = [
    'move.assigned', 'move.started', 'move.completed', 'move.cancelled',
    'move.state_changed', 'move.exception', 'move.updated',
    'proof.captured', 'proof.submitted',
    'location.update', 'eta.update'
  ];

  // Validate driver and move mapping for ingested events
  async function validateEventMapping(
    eventType: string,
    driverId: string | null,
    moveId: string | null
  ): Promise<{ mappingStatus: string; mappingError: string | null }> {
    // All events must have driver_id
    if (!driverId) {
      return {
        mappingStatus: 'failed_driver',
        mappingError: 'Event missing required driver_id field'
      };
    }

    // Validate driver exists in DriverHub 360
    const [existingDriver] = await db.select({ id: drivers.id })
      .from(drivers)
      .where(eq(drivers.id, driverId))
      .limit(1);

    if (!existingDriver) {
      return {
        mappingStatus: 'failed_driver',
        mappingError: `Unknown driver_id: ${driverId} - driver not found in DriverHub 360`
      };
    }

    // Move-related events must have move_id
    const requiresMove = moveRequiredEventTypes.some(type => 
      eventType === type || eventType.startsWith('move.')
    );

    if (requiresMove) {
      if (!moveId) {
        return {
          mappingStatus: 'failed_move',
          mappingError: `Event type ${eventType} requires move_id but none provided`
        };
      }

      // Validate move exists in DriverHub 360
      const [existingMove] = await db.select({ id: moves.id })
        .from(moves)
        .where(eq(moves.id, moveId))
        .limit(1);

      if (!existingMove) {
        return {
          mappingStatus: 'failed_move',
          mappingError: `Unknown move_id: ${moveId} - move not found in DriverHub 360`
        };
      }
    }

    // All validations passed
    return {
      mappingStatus: 'ok',
      mappingError: null
    };
  }

  // =====================================
  // EXECUTION LEDGER PROCESSING (Ticket 17)
  // =====================================
  
  // Event types that represent state changes
  const stateChangeEventTypes = [
    'move.state_changed', 'move.assigned', 'move.started', 
    'move.completed', 'move.cancelled', 'move.exception'
  ];
  
  // Event types that represent proofs
  const proofEventTypes = ['proof.captured', 'proof.submitted'];

  // =====================================
  // W-2 TIMEKEEPING PROCESSING (Ticket 18)
  // =====================================

  // Process a ClockIn event - creates a new time entry
  async function processClockIn(eventId: string, occurredAt: Date, payload: any, driverId: string | null) {
    if (!driverId) {
      console.log(`[Timekeeping] Skipping clock-in ${eventId} - no driver_id`);
      return;
    }

    try {
      // Check if already processed (idempotency)
      const [existing] = await db.select({ id: timeEntries.id })
        .from(timeEntries)
        .where(eq(timeEntries.clockInEventId, eventId))
        .limit(1);
      
      if (existing) {
        console.log(`[Timekeeping] Clock-in ${eventId} already processed`);
        return;
      }

      // Check for open shifts (missing clock-out) for this driver
      const [openShift] = await db.select()
        .from(timeEntries)
        .where(and(
          eq(timeEntries.driverId, driverId),
          isNull(timeEntries.endAt)
        ))
        .orderBy(desc(timeEntries.startAt))
        .limit(1);

      if (openShift) {
        // Auto-close the open shift and create an exception
        const autoCloseTime = new Date(occurredAt.getTime() - 60000); // 1 minute before new clock-in
        const durationMinutes = Math.round((autoCloseTime.getTime() - new Date(openShift.startAt).getTime()) / 60000);
        
        await db.update(timeEntries)
          .set({
            endAt: autoCloseTime,
            durationMinutes: Math.max(0, durationMinutes),
            flags: sql`${timeEntries.flags} || '["auto_closed", "open_shift"]'::jsonb`,
            updatedAt: new Date(),
          })
          .where(eq(timeEntries.id, openShift.id));

        // Create exception for missing clock-out
        await db.insert(timecardExceptions).values({
          driverId,
          exceptionType: 'missing_clock_out',
          status: 'open',
          relatedTimeEntryId: openShift.id,
          description: `Driver clocked in again at ${occurredAt.toISOString()} without clocking out from previous shift started at ${openShift.startAt}`,
          sourceEventId: eventId,
        });

        console.log(`[Timekeeping] Auto-closed open shift ${openShift.id} for driver ${driverId}`);
      }

      // Check for overlapping shifts
      const [overlapping] = await db.select()
        .from(timeEntries)
        .where(and(
          eq(timeEntries.driverId, driverId),
          lte(timeEntries.startAt, occurredAt),
          or(
            isNull(timeEntries.endAt),
            gte(timeEntries.endAt, occurredAt)
          )
        ))
        .limit(1);

      const flags: string[] = [];
      if (overlapping) {
        flags.push('overlap');
        // Create exception for overlap
        await db.insert(timecardExceptions).values({
          driverId,
          exceptionType: 'overlap',
          status: 'open',
          description: `Clock-in at ${occurredAt.toISOString()} overlaps with existing shift starting at ${overlapping.startAt}`,
          sourceEventId: eventId,
        });
      }

      // Extract geo data from payload
      const geo = payload.geo || payload.location || {};
      
      // Create new time entry
      const [newEntry] = await db.insert(timeEntries).values({
        driverId,
        startAt: occurredAt,
        marketId: payload.market_id || payload.marketId || null,
        payPolicyId: payload.pay_policy_id || payload.payPolicyId || null,
        flags: flags.length > 0 ? flags : [],
        clockInEventId: eventId,
        clockInLat: geo.lat || geo.latitude || null,
        clockInLng: geo.lng || geo.longitude || null,
      }).returning();

      console.log(`[Timekeeping] Created time entry ${newEntry.id} for driver ${driverId} clock-in at ${occurredAt.toISOString()}`);
    } catch (error: any) {
      console.error(`[Timekeeping] Error processing clock-in ${eventId}:`, error.message);
      throw error;
    }
  }

  // Process a ClockOut event - closes an open time entry
  async function processClockOut(eventId: string, occurredAt: Date, payload: any, driverId: string | null) {
    if (!driverId) {
      console.log(`[Timekeeping] Skipping clock-out ${eventId} - no driver_id`);
      return;
    }

    try {
      // Check if already processed (idempotency)
      const [existing] = await db.select({ id: timeEntries.id })
        .from(timeEntries)
        .where(eq(timeEntries.clockOutEventId, eventId))
        .limit(1);
      
      if (existing) {
        console.log(`[Timekeeping] Clock-out ${eventId} already processed`);
        return;
      }

      // Find the most recent open shift for this driver
      const [openShift] = await db.select()
        .from(timeEntries)
        .where(and(
          eq(timeEntries.driverId, driverId),
          isNull(timeEntries.endAt)
        ))
        .orderBy(desc(timeEntries.startAt))
        .limit(1);

      if (!openShift) {
        // No open shift - create exception for clock-out without clock-in
        await db.insert(timecardExceptions).values({
          driverId,
          exceptionType: 'missing_clock_in',
          status: 'open',
          description: `Driver clocked out at ${occurredAt.toISOString()} without an open clock-in`,
          sourceEventId: eventId,
        });

        console.log(`[Timekeeping] Clock-out ${eventId} without open shift for driver ${driverId}`);
        return;
      }

      // Calculate duration
      const durationMinutes = Math.round((occurredAt.getTime() - new Date(openShift.startAt).getTime()) / 60000);
      
      // Extract geo data from payload
      const geo = payload.geo || payload.location || {};

      // Check for excessive duration (more than 16 hours)
      const existingFlags = Array.isArray(openShift.flags) ? openShift.flags : [];
      const newFlags = [...existingFlags];
      
      if (durationMinutes > 960) { // 16 hours
        newFlags.push('manual_review');
        await db.insert(timecardExceptions).values({
          driverId,
          exceptionType: 'excessive_duration',
          status: 'open',
          relatedTimeEntryId: openShift.id,
          description: `Shift duration of ${Math.round(durationMinutes / 60)} hours exceeds 16 hour limit`,
          sourceEventId: eventId,
        });
      }

      // Update the time entry
      await db.update(timeEntries)
        .set({
          endAt: occurredAt,
          durationMinutes: Math.max(0, durationMinutes),
          clockOutEventId: eventId,
          clockOutLat: geo.lat || geo.latitude || null,
          clockOutLng: geo.lng || geo.longitude || null,
          flags: newFlags,
          updatedAt: new Date(),
        })
        .where(eq(timeEntries.id, openShift.id));

      console.log(`[Timekeeping] Closed time entry ${openShift.id} for driver ${driverId} - duration: ${durationMinutes} minutes`);
    } catch (error: any) {
      console.error(`[Timekeeping] Error processing clock-out ${eventId}:`, error.message);
      throw error;
    }
  }

  // Billing trigger - create invoice line candidate when move completes (Ticket 19)
  async function processBillingTrigger(eventId: string, moveId: string, driverId: string | null, occurredAt: Date, payload: any) {
    try {
      // Check for existing candidate (idempotency via moveId)
      const [existingCandidate] = await db.select({ id: invoiceLineCandidates.id })
        .from(invoiceLineCandidates)
        .where(eq(invoiceLineCandidates.moveId, moveId))
        .limit(1);
      
      if (existingCandidate) {
        console.log(`[Billing] Candidate already exists for move ${moveId}, skipping`);
        return;
      }

      // Get the trip/move to get customer and pricing data
      const [trip] = await db.select()
        .from(trips)
        .where(eq(trips.id, moveId))
        .limit(1);
      
      if (!trip) {
        console.log(`[Billing] No trip found for moveId ${moveId}, skipping billing trigger`);
        return;
      }

      const customerId = trip.customerId;
      if (!customerId) {
        console.log(`[Billing] No customer assigned to move ${moveId}, skipping billing trigger`);
        return;
      }

      // Gather all ledger events for this move to link as supporting evidence
      const ledgerEvents = await db.select({ eventId: moveExecutionLedger.eventId })
        .from(moveExecutionLedger)
        .where(eq(moveExecutionLedger.moveId, moveId));
      
      const supportingEventIds = ledgerEvents.map(e => e.eventId);

      // Gather any proofs for this move
      const proofs = await db.select()
        .from(moveProofsIndex)
        .where(eq(moveProofsIndex.moveId, moveId));
      
      const proofRefs = proofs.map(p => ({
        type: p.proofType,
        eventId: p.eventId,
        mediaRef: p.mediaRef,
      }));

      // Calculate billable amount (use trip rates or payload data)
      const baseRate = payload.billable_amount || payload.billableAmount || 
                       payload.amount || trip.estimatedCost || 0;
      
      // Build description from move details
      const description = `Move ${trip.moveNumber || moveId} - ${trip.origin || 'Origin'} to ${trip.destination || 'Destination'}`;

      // Create invoice line candidate
      await db.insert(invoiceLineCandidates).values({
        customerId,
        moveId,
        driverId,
        serviceType: trip.vehicleType || payload.service_type || 'standard',
        description,
        amount: String(baseRate),
        currency: 'USD',
        status: 'draft',
        supportingEventIds: JSON.stringify(supportingEventIds),
        proofRefs: JSON.stringify(proofRefs),
        baseRate: String(baseRate),
      });

      console.log(`[Billing] Created invoice candidate for move ${moveId} - amount: ${baseRate}`);
    } catch (error: any) {
      console.error(`[Billing] Error processing billing trigger for move ${moveId}:`, error.message);
      throw error;
    }
  }

  // ========================================
  // TICKET 20: Case Creation Trigger
  // ========================================
  
  // Determine severity based on exception type and payload
  function determineCaseSeverity(exceptionType: string, payload: any): 'low' | 'medium' | 'high' {
    // Damage events are always high severity
    if (exceptionType === 'damage_found' || payload.damage_reported) {
      return 'high';
    }
    // No-show is medium severity
    if (exceptionType === 'no_show') {
      return 'medium';
    }
    // Key/address issues are low severity
    if (exceptionType === 'cannot_access_keys' || exceptionType === 'wrong_address') {
      return 'low';
    }
    return 'medium';
  }

  // Determine queue assignment based on case type and market/customer
  function determineCaseQueue(caseType: string, exceptionType: string | null, customerId: string | null): string {
    if (caseType === 'CLAIMS') {
      return 'claims_team';
    }
    if (exceptionType === 'damage_found') {
      return 'damage_review';
    }
    if (exceptionType === 'no_show') {
      return 'operations_team';
    }
    return 'qa_team';
  }

  // Process case creation trigger for ExceptionLogged and damage ProofSubmitted events
  async function processCaseTrigger(
    eventId: string, 
    eventType: string, 
    moveId: string | null, 
    driverId: string | null, 
    occurredAt: Date, 
    payload: any
  ) {
    try {
      // Check if this event should trigger a case
      let shouldCreateCase = false;
      let caseType: 'QA' | 'CLAIMS' = 'QA';
      let exceptionType: string | null = null;
      let title = '';
      let description = '';

      // Check for ExceptionLogged events with specific exception types
      const isExceptionEvent = eventType.toLowerCase().includes('exception') || 
                               eventType === 'move.exception' || 
                               eventType === 'EXCEPTION_LOGGED';
      
      if (isExceptionEvent) {
        exceptionType = payload.exception_type || payload.exceptionType;
        
        // Check if this exception type should trigger a case
        const triggerExceptionTypes = ['damage_found', 'no_show', 'cannot_access_keys', 'wrong_address'];
        if (exceptionType && triggerExceptionTypes.includes(exceptionType)) {
          shouldCreateCase = true;
          
          // Damage exceptions go to Claims, others go to QA
          if (exceptionType === 'damage_found') {
            caseType = 'CLAIMS';
            title = `Damage Reported - Move ${moveId || 'Unknown'}`;
            description = payload.description || payload.notes || 'Damage was found during move execution';
          } else {
            caseType = 'QA';
            title = `${exceptionType.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase())} - Move ${moveId || 'Unknown'}`;
            description = payload.description || payload.notes || `Exception: ${exceptionType}`;
          }
        }
      }

      // Check for ProofSubmitted events with DAMAGE_PHOTO type
      const isProofEvent = eventType.toLowerCase().includes('proof') || 
                           eventType === 'proof.submitted' || 
                           eventType === 'PROOF_SUBMITTED';
      
      if (isProofEvent) {
        const proofType = payload.proof_type || payload.proofType;
        
        if (proofType === 'DAMAGE_PHOTO' || proofType === 'damage_photo') {
          shouldCreateCase = true;
          caseType = 'CLAIMS';
          exceptionType = 'damage_found';
          title = `Damage Photo Submitted - Move ${moveId || 'Unknown'}`;
          description = payload.description || 'Damage photo was submitted during move execution';
        }
      }

      if (!shouldCreateCase) {
        return; // Not a case-triggering event
      }

      // Check for existing case with same trigger event (idempotency)
      const [existingCase] = await db.select({ id: cases.id })
        .from(cases)
        .where(eq(cases.triggerEventId, eventId))
        .limit(1);
      
      if (existingCase) {
        console.log(`[Cases] Case already exists for event ${eventId}, skipping`);
        return;
      }

      // Get customer info from the trip/move
      let customerId: string | null = null;
      if (moveId) {
        const [trip] = await db.select({ customerId: trips.customerId })
          .from(trips)
          .where(eq(trips.id, moveId))
          .limit(1);
        customerId = trip?.customerId || null;
      }

      // Gather supporting event IDs from ledger
      const supportingEventIds: string[] = [eventId];
      if (moveId) {
        const ledgerEvents = await db.select({ eventId: moveExecutionLedger.eventId })
          .from(moveExecutionLedger)
          .where(eq(moveExecutionLedger.moveId, moveId));
        supportingEventIds.push(...ledgerEvents.map(e => e.eventId).filter(id => id !== eventId));
      }

      // Gather any proofs for this move
      const proofRefs: any[] = [];
      if (moveId) {
        const proofs = await db.select()
          .from(moveProofsIndex)
          .where(eq(moveProofsIndex.moveId, moveId));
        proofRefs.push(...proofs.map(p => ({
          proofId: p.id,
          proofType: p.proofType,
          mediaRef: p.mediaRef,
          eventId: p.eventId,
        })));
      }

      const severity = determineCaseSeverity(exceptionType || '', payload);
      const assignedQueue = determineCaseQueue(caseType, exceptionType, customerId);

      // Create the case
      const [newCase] = await db.insert(cases).values({
        caseType,
        severity,
        status: 'open',
        moveId,
        driverId,
        customerId,
        assignedQueue,
        title,
        description,
        supportingEventIds: JSON.stringify(supportingEventIds),
        proofRefs: JSON.stringify(proofRefs),
        triggerEventId: eventId,
        triggerType: isExceptionEvent ? 'exception_logged' : 'proof_submitted',
        exceptionType,
      }).returning({ id: cases.id });

      // Create initial case activity (system action)
      await db.insert(caseActivity).values({
        caseId: newCase.id,
        action: 'case_created',
        actorType: 'system',
        notes: `Case auto-created from ${isExceptionEvent ? 'exception' : 'proof'} event: ${eventType}`,
        newValue: 'open',
      });

      console.log(`[Cases] Created ${caseType} case ${newCase.id} for event ${eventId} - severity: ${severity}, queue: ${assignedQueue}`);
    } catch (error: any) {
      console.error(`[Cases] Error processing case trigger for event ${eventId}:`, error.message);
      // Don't rethrow - case creation failure shouldn't block event processing
    }
  }
  
  // Process an ingested event into the execution ledger and derived tables
  async function processEventToLedger(eventId: string, eventType: string, occurredAt: Date, payload: any, moveId: string | null, driverId: string | null) {
    if (!moveId) {
      // Skip events without move_id - they can't be added to move ledger
      console.log(`[Ledger Processing] Skipping event ${eventId} - no move_id`);
      return;
    }

    try {
      // 1. Always add to execution ledger (append-only)
      const [existingLedgerEntry] = await db.select({ id: moveExecutionLedger.id })
        .from(moveExecutionLedger)
        .where(eq(moveExecutionLedger.eventId, eventId))
        .limit(1);
      
      if (!existingLedgerEntry) {
        await db.insert(moveExecutionLedger).values({
          moveId,
          driverId,
          eventId,
          eventType,
          occurredAt,
          payloadJson: payload,
        });
        console.log(`[Ledger Processing] Added ledger entry for event ${eventId}`);
      }

      // 2. Update current state if this is a state change event
      if (stateChangeEventTypes.some(t => eventType.toLowerCase().includes(t.replace('move.', '')))) {
        // Extract state from payload - try various possible fields
        const newState = payload.state || payload.status || payload.current_state || 
                        payload.new_state || eventType.replace('move.', '');
        
        // Check if this event is newer than current state
        const [currentState] = await db.select()
          .from(moveCurrentState)
          .where(eq(moveCurrentState.moveId, moveId))
          .limit(1);
        
        if (!currentState || new Date(occurredAt) >= new Date(currentState.stateChangedAt)) {
          // Upsert current state
          await db.insert(moveCurrentState)
            .values({
              moveId,
              driverId,
              currentState: newState,
              stateChangedAt: occurredAt,
              sourceEventId: eventId,
            })
            .onConflictDoUpdate({
              target: moveCurrentState.moveId,
              set: {
                driverId,
                currentState: newState,
                stateChangedAt: occurredAt,
                sourceEventId: eventId,
                lastUpdatedAt: new Date(),
              },
            });
          console.log(`[Ledger Processing] Updated current state for move ${moveId}: ${newState}`);
        }
      }

      // 3. Index proofs if this is a proof event
      if (proofEventTypes.some(t => eventType.toLowerCase().includes('proof'))) {
        const [existingProof] = await db.select({ id: moveProofsIndex.id })
          .from(moveProofsIndex)
          .where(eq(moveProofsIndex.eventId, eventId))
          .limit(1);
        
        if (!existingProof) {
          // Extract proof data from payload
          const proofType = payload.proof_type || payload.proofType || payload.type || 'unknown';
          const mediaRef = payload.media_ref || payload.mediaRef || payload.media_url || payload.url || null;
          const geo = payload.geo || payload.location || {};
          
          await db.insert(moveProofsIndex).values({
            moveId,
            driverId,
            proofType,
            mediaRef,
            occurredAt,
            geoLat: geo.lat || geo.latitude || null,
            geoLng: geo.lng || geo.longitude || null,
            geoAccuracy: geo.accuracy || null,
            eventId,
            metadata: payload,
          });
          console.log(`[Ledger Processing] Indexed proof for move ${moveId}: ${proofType}`);
        }
      }

      // 4. Process timekeeping events (ClockIn/ClockOut) - Ticket 18
      if (eventType.toLowerCase().includes('clock_in') || eventType.toLowerCase().includes('clockin') || eventType === 'timekeeping.clock_in') {
        await processClockIn(eventId, occurredAt, payload, driverId);
      } else if (eventType.toLowerCase().includes('clock_out') || eventType.toLowerCase().includes('clockout') || eventType === 'timekeeping.clock_out') {
        await processClockOut(eventId, occurredAt, payload, driverId);
      }

      // 5. Process billing trigger for MOVE_COMPLETED events - Ticket 19
      if (eventType.toLowerCase().includes('completed') || eventType === 'move.completed' || eventType === 'MOVE_COMPLETED') {
        await processBillingTrigger(eventId, moveId, driverId, occurredAt, payload);
      }

      // 6. Process case creation trigger for exceptions and damage proofs - Ticket 20
      await processCaseTrigger(eventId, eventType, moveId, driverId, occurredAt, payload);

      // 7. Update the ingested event status to 'processed'
      await db.update(ingestedEvents)
        .set({ 
          processingStatus: 'processed',
          processedAt: new Date(),
        })
        .where(eq(ingestedEvents.eventId, eventId));

    } catch (error: any) {
      console.error(`[Ledger Processing] Error processing event ${eventId}:`, error.message);
      // Update status to failed
      await db.update(ingestedEvents)
        .set({ 
          processingStatus: 'failed',
          lastError: error.message,
          retryCount: sql`${ingestedEvents.retryCount} + 1`,
        })
        .where(eq(ingestedEvents.eventId, eventId));
    }
  }

  // POST /integrations/execution/events - Main event ingestion endpoint
  app.post("/integrations/execution/events", integrationAuth, async (req: any, res: Response) => {
    const startTime = Date.now();
    const requestId = `req_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    
    try {
      // Validate event envelope
      const validationResult = eventEnvelopeSchema.safeParse(req.body);
      if (!validationResult.success) {
        console.log(`[Event Ingestion] ${requestId} - Invalid envelope: ${JSON.stringify(validationResult.error.issues)}`);
        return res.status(400).json({
          error: 'INVALID_ENVELOPE',
          message: 'Invalid event envelope format',
          details: validationResult.error.issues
        });
      }

      const envelope = validationResult.data;

      // Check for duplicate (idempotency)
      const [existing] = await db.select({ eventId: ingestedEvents.eventId })
        .from(ingestedEvents)
        .where(eq(ingestedEvents.eventId, envelope.event_id))
        .limit(1);

      if (existing) {
        // Idempotent response - duplicate detected, return success without re-processing
        console.log(`[Event Ingestion] ${requestId} - Duplicate event: ${envelope.event_id}`);
        return res.status(200).json({
          status: 'DUPLICATE',
          message: 'Event already received',
          event_id: envelope.event_id
        });
      }

      // Validate against schema registry (Ticket 26)
      const [registeredSchema] = await db.select()
        .from(eventSchemas)
        .where(and(
          eq(eventSchemas.eventType, envelope.event_type),
          eq(eventSchemas.schemaVersion, envelope.schema_version)
        ))
        .limit(1);

      // Determine schema support status
      let schemaStatus: 'supported' | 'deprecated' | 'unsupported' = 'unsupported';
      let schemaValidationError: string | null = null;
      
      if (!registeredSchema) {
        // Unknown schema - mark as unsupported but still store
        schemaStatus = 'unsupported';
        schemaValidationError = `Unknown schema: ${envelope.event_type} v${envelope.schema_version}`;
      } else if (registeredSchema.status === 'unsupported') {
        schemaStatus = 'unsupported';
        schemaValidationError = `Schema marked as unsupported: ${envelope.event_type} v${envelope.schema_version}`;
      } else if (registeredSchema.status === 'deprecated') {
        // Check if within deprecation window
        if (registeredSchema.deprecatedAt) {
          const windowDays = registeredSchema.deprecationWindowDays || 30;
          const windowEnd = new Date(registeredSchema.deprecatedAt);
          windowEnd.setDate(windowEnd.getDate() + windowDays);
          if (new Date() < windowEnd) {
            schemaStatus = 'deprecated'; // Still acceptable within window
          } else {
            schemaStatus = 'unsupported';
            schemaValidationError = `Schema deprecation window expired: ${envelope.event_type} v${envelope.schema_version}`;
          }
        } else {
          schemaStatus = 'deprecated';
        }
      } else {
        schemaStatus = 'supported';
      }

      // Extract driver_id and move_id from payload if present
      const payload = envelope.payload || {};

      // Validate required fields if schema is supported or deprecated
      if ((schemaStatus === 'supported' || schemaStatus === 'deprecated') && registeredSchema?.requiredFields?.length) {
        for (const field of registeredSchema.requiredFields) {
          const fieldValue = field.split('.').reduce((obj: any, key: string) => obj?.[key], payload);
          if (fieldValue === undefined || fieldValue === null) {
            schemaValidationError = `Missing required field: ${field}`;
            // Don't change status - still accept but log the validation warning
            console.warn(`[Schema Validation] ${requestId} - Required field missing: ${field} in ${envelope.event_type} v${envelope.schema_version}`);
          }
        }
      }

      const isSupported = schemaStatus === 'supported' || schemaStatus === 'deprecated';
      const driverId = payload.driver_id || payload.driverId || null;
      const moveId = payload.move_id || payload.moveId || null;

      // Validate mapping (Ticket 22) - ensure driver/move exist in DriverHub 360
      const { mappingStatus, mappingError } = await validateEventMapping(
        envelope.event_type,
        driverId,
        moveId
      );

      // If mapping failed, set processing status to failed_mapping (quarantine)
      // If schema unsupported, mark as unsupported_version
      const processingStatus = schemaStatus === 'unsupported' ? 'unsupported_version' 
        : mappingStatus !== 'ok' ? 'failed_mapping' 
        : 'received';

      // Persist to append-only store (never discard events)
      await db.insert(ingestedEvents).values({
        eventId: envelope.event_id,
        eventType: envelope.event_type,
        schemaVersion: envelope.schema_version,
        occurredAt: new Date(envelope.occurred_at),
        sourceSystem: envelope.source_system || 'execution_layer',
        payloadJson: envelope.payload,
        processingStatus,
        driverId,
        moveId,
        mappingStatus,
        mappingError,
      });

      // Log mapping failure for alerting
      if (mappingStatus !== 'ok') {
        console.warn(`[Event Mapping] ${requestId} - QUARANTINED: ${envelope.event_id} - ${mappingError}`);
      }

      // Only process to ledger if supported AND mapping succeeded
      if (isSupported && mappingStatus === 'ok') {
        processEventToLedger(
          envelope.event_id,
          envelope.event_type,
          new Date(envelope.occurred_at),
          envelope.payload,
          moveId,
          driverId
        ).catch(err => console.error(`[Ledger Processing] Async error: ${err.message}`));
      }

      const latency = Date.now() - startTime;
      console.log(`[Event Ingestion] ${requestId} - Ingested: ${envelope.event_id} (${envelope.event_type}) - ${latency}ms`);

      // Log successful ingestion
      await logIngestionAudit({
        requestId,
        keyId: req.integrationKeyId || 'unknown',
        keyPrefix: req.integrationKeyPrefix || null,
        sourceIp: req.ip || req.connection?.remoteAddress,
        userAgent: req.headers['user-agent'],
        endpoint: '/integrations/execution/events',
        method: 'POST',
        eventCount: 1,
        acceptedCount: 1,
        rejectedCount: 0,
        duplicateCount: 0,
        responseStatus: 201,
        responseTimeMs: latency,
      });

      return res.status(201).json({
        status: mappingStatus === 'ok' ? 'RECEIVED' : 'QUARANTINED',
        event_id: envelope.event_id,
        processing_status: processingStatus,
        mapping_status: mappingStatus,
        mapping_error: mappingError,
        schema_supported: isSupported
      });

    } catch (error: any) {
      const latency = Date.now() - startTime;
      console.error(`[Event Ingestion] ${requestId} - Error: ${error.message} - ${latency}ms`);
      
      // Log error
      await logIngestionAudit({
        requestId,
        keyId: req.integrationKeyId || 'unknown',
        keyPrefix: req.integrationKeyPrefix || null,
        sourceIp: req.ip || req.connection?.remoteAddress,
        userAgent: req.headers['user-agent'],
        endpoint: '/integrations/execution/events',
        method: 'POST',
        eventCount: 1,
        acceptedCount: 0,
        rejectedCount: 1,
        duplicateCount: 0,
        responseStatus: 500,
        responseTimeMs: latency,
        errorCode: 'INGESTION_FAILED',
        errorMessage: error.message,
      });
      
      return res.status(500).json({
        error: 'INGESTION_FAILED',
        message: 'Failed to ingest event',
        request_id: requestId
      });
    }
  });

  // POST /integrations/execution/events/batch - Batch event ingestion
  app.post("/integrations/execution/events/batch", integrationAuth, async (req: any, res: Response) => {
    const startTime = Date.now();
    const requestId = `req_batch_${Date.now()}_${Math.random().toString(36).substring(7)}`;
    
    try {
      const { events } = req.body;
      
      if (!Array.isArray(events) || events.length === 0) {
        return res.status(400).json({
          error: 'INVALID_REQUEST',
          message: 'Request must contain a non-empty events array'
        });
      }

      if (events.length > 100) {
        return res.status(400).json({
          error: 'BATCH_TOO_LARGE',
          message: 'Maximum 100 events per batch'
        });
      }

      const results: { event_id: string; status: string; error?: string }[] = [];
      const supportedVersions = [1];

      for (const event of events) {
        const validationResult = eventEnvelopeSchema.safeParse(event);
        
        if (!validationResult.success) {
          results.push({
            event_id: event.event_id || 'unknown',
            status: 'REJECTED',
            error: 'Invalid envelope format'
          });
          continue;
        }

        const envelope = validationResult.data;

        // Check for duplicate
        const [existing] = await db.select({ eventId: ingestedEvents.eventId })
          .from(ingestedEvents)
          .where(eq(ingestedEvents.eventId, envelope.event_id))
          .limit(1);

        if (existing) {
          results.push({
            event_id: envelope.event_id,
            status: 'DUPLICATE'
          });
          continue;
        }

        try {
          const isSupported = supportedVersions.includes(envelope.schema_version);
          const payload = envelope.payload || {};

          const moveId = payload.move_id || payload.moveId || null;
          const driverId = payload.driver_id || payload.driverId || null;

          // Validate mapping (Ticket 22)
          const { mappingStatus, mappingError } = await validateEventMapping(
            envelope.event_type,
            driverId,
            moveId
          );

          // Determine processing status
          const processingStatus = !isSupported ? 'unsupported' 
            : mappingStatus !== 'ok' ? 'failed_mapping' 
            : 'received';

          await db.insert(ingestedEvents).values({
            eventId: envelope.event_id,
            eventType: envelope.event_type,
            schemaVersion: envelope.schema_version,
            occurredAt: new Date(envelope.occurred_at),
            sourceSystem: envelope.source_system || 'execution_layer',
            payloadJson: envelope.payload,
            processingStatus,
            driverId,
            moveId,
            mappingStatus,
            mappingError,
          });

          // Log quarantined events
          if (mappingStatus !== 'ok') {
            console.warn(`[Event Mapping] Batch - QUARANTINED: ${envelope.event_id} - ${mappingError}`);
          }

          // Only process to ledger if supported AND mapping succeeded
          if (isSupported && mappingStatus === 'ok') {
            processEventToLedger(
              envelope.event_id,
              envelope.event_type,
              new Date(envelope.occurred_at),
              envelope.payload,
              moveId,
              driverId
            ).catch(err => console.error(`[Ledger Processing] Batch async error: ${err.message}`));
          }

          results.push({
            event_id: envelope.event_id,
            status: mappingStatus === 'ok' ? 'RECEIVED' : 'QUARANTINED',
            mapping_status: mappingStatus,
            mapping_error: mappingError
          });
        } catch (err: any) {
          results.push({
            event_id: envelope.event_id,
            status: 'FAILED',
            error: err.message
          });
        }
      }

      const latency = Date.now() - startTime;
      const accepted = results.filter(r => r.status === 'RECEIVED').length;
      const quarantined = results.filter(r => r.status === 'QUARANTINED').length;
      const duplicates = results.filter(r => r.status === 'DUPLICATE').length;
      const rejected = results.filter(r => r.status === 'REJECTED').length;
      const failed = results.filter(r => r.status === 'FAILED').length;
      
      console.log(`[Event Ingestion Batch] ${requestId} - Processed ${events.length} events - ${latency}ms`);

      // Log batch ingestion
      await logIngestionAudit({
        requestId,
        keyId: req.integrationKeyId || 'unknown',
        keyPrefix: req.integrationKeyPrefix || null,
        sourceIp: req.ip || req.connection?.remoteAddress,
        userAgent: req.headers['user-agent'],
        endpoint: '/integrations/execution/events/batch',
        method: 'POST',
        eventCount: events.length,
        acceptedCount: accepted,
        rejectedCount: rejected + failed,
        duplicateCount: duplicates,
        responseStatus: 200,
        responseTimeMs: latency,
      });

      return res.status(200).json({
        total: events.length,
        received: accepted,
        quarantined,
        duplicates,
        rejected,
        failed,
        results
      });

    } catch (error: any) {
      const latency = Date.now() - startTime;
      console.error(`[Event Ingestion Batch] ${requestId} - Error: ${error.message}`);
      
      // Log error
      await logIngestionAudit({
        requestId,
        keyId: req.integrationKeyId || 'unknown',
        keyPrefix: req.integrationKeyPrefix || null,
        sourceIp: req.ip || req.connection?.remoteAddress,
        userAgent: req.headers['user-agent'],
        endpoint: '/integrations/execution/events/batch',
        method: 'POST',
        eventCount: 0,
        acceptedCount: 0,
        rejectedCount: 0,
        duplicateCount: 0,
        responseStatus: 500,
        responseTimeMs: latency,
        errorCode: 'BATCH_INGESTION_FAILED',
        errorMessage: error.message,
      });
      
      return res.status(500).json({
        error: 'BATCH_INGESTION_FAILED',
        message: 'Failed to process batch',
        request_id: requestId
      });
    }
  });

