  // ========================================
  // TICKET 23: Proof Media Access Proxy
  // ========================================

  // GET /api/proofs/:proofId/media - Get signed URL for proof media with access logging
  app.get("/api/proofs/:proofId/media", async (req: any, res: Response) => {
    try {
      const { proofId } = req.params;
      const { context = 'move_detail' } = req.query;

      // Support both session-based auth (password login) and OIDC auth
      let currentUserId: string | null = null;
      if ((req.session as any)?.userId) {
        currentUserId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        currentUserId = req.user.claims.sub;
      }

      if (!currentUserId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Look up user by ID, then fall back to email lookup (for OIDC linking)
      const userEmail = req.user?.claims?.email;
      let currentUser = await storage.getUser(currentUserId);
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;

      // Validate role - billing, claims, qa, admin, super_user, corporate can access
      const allowedRoles = ['admin', 'super_user', 'corporate', 'billing', 'claims', 'qa'];
      if (!role || !allowedRoles.includes(role)) {
        return res.status(403).json({ message: "Access denied - insufficient permissions to view proof media" });
      }

      // Validate context
      const validContexts = ['billing', 'claims', 'qa', 'move_detail', 'admin'];
      if (!validContexts.includes(context as string)) {
        return res.status(400).json({ error: 'Invalid context' });
      }

      // Get the proof record
      const [proof] = await db.select()
        .from(moveProofsIndex)
        .where(eq(moveProofsIndex.id, parseInt(proofId)))
        .limit(1);

      if (!proof) {
        return res.status(404).json({ error: 'Proof not found' });
      }

      if (!proof.mediaRef) {
        return res.status(404).json({ error: 'Proof has no media reference' });
      }

      // For claims/qa contexts, verify user has access to a related case
      // This adds an additional layer of authorization beyond role-based access
      if ((context === 'claims' || context === 'qa') && proof.moveId) {
        const { caseId } = req.query;
        if (caseId) {
          // If a caseId is provided, verify it matches the proof's move
          const [relatedCase] = await db.select({ id: cases.id, moveId: cases.moveId })
            .from(cases)
            .where(eq(cases.id, caseId as string))
            .limit(1);
          
          if (!relatedCase || relatedCase.moveId !== proof.moveId) {
            console.warn(`[Proof Access] Case ${caseId} does not match proof moveId ${proof.moveId}`);
            return res.status(403).json({ error: 'Case does not match proof' });
          }
        } else {
          // Verify there's at least one case for this move that justifies access
          const [relatedCase] = await db.select({ id: cases.id })
            .from(cases)
            .where(eq(cases.moveId, proof.moveId))
            .limit(1);
          
          if (!relatedCase) {
            console.log(`[Proof Access] No case found for move ${proof.moveId}, context ${context}`);
            // Allow access if admin/super_user, otherwise deny for claims/qa without a case
            if (role !== 'admin' && role !== 'super_user') {
              return res.status(403).json({ error: 'No case associated with this move for claims/qa access' });
            }
          }
        }
      }

      // Log the access for audit trail
      const ipAddress = req.ip || req.connection?.remoteAddress || 'unknown';
      const userAgent = req.headers['user-agent'] || 'unknown';

      await db.insert(proofAccessLog).values({
        userId: currentUserId,
        moveId: proof.moveId,
        proofId: proof.id,
        mediaRef: proof.mediaRef,
        context: context as string,
        ipAddress,
        userAgent,
      });

      console.log(`[Proof Access] User ${currentUserId} accessed proof ${proofId} (${proof.proofType}) in context: ${context}`);

      // Check if mediaRef is a full URL or an object storage path
      if (proof.mediaRef.startsWith('http://') || proof.mediaRef.startsWith('https://')) {
        // External URL - redirect to it
        return res.json({
          proofId: proof.id,
          proofType: proof.proofType,
          mediaUrl: proof.mediaRef,
          accessedAt: new Date().toISOString(),
          expiresIn: null, // External URLs don't expire
        });
      }

      // For object storage paths, always return JSON with the stream endpoint URL
      // This normalizes the response format to always be JSON
      // Only /objects/ paths and http URLs are supported
      if (!proof.mediaRef.startsWith('/objects/')) {
        console.warn(`[Proof Access] Unsupported mediaRef format: ${proof.mediaRef}`);
        return res.status(400).json({ error: 'Unsupported media reference format' });
      }
      
      return res.json({
        proofId: proof.id,
        proofType: proof.proofType,
        mediaRef: proof.mediaRef,
        mediaUrl: `/api/proofs/${proof.id}/stream?context=${context}`,
        accessedAt: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error('[Proof Access] Error:', error.message);
      res.status(500).json({ error: 'Failed to access proof media' });
    }
  });

  // GET /api/proofs/:proofId/stream - Stream the actual proof media with full authorization
  app.get("/api/proofs/:proofId/stream", async (req: any, res: Response) => {
    try {
      const { proofId } = req.params;
      const { context = 'move_detail' } = req.query;

      // Full auth check - same as /media endpoint
      let currentUserId: string | null = null;
      if ((req.session as any)?.userId) {
        currentUserId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        currentUserId = req.user.claims.sub;
      }

      if (!currentUserId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      // Get user role
      const userEmail = req.user?.claims?.email;
      let currentUser = await storage.getUser(currentUserId);
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      const allowedRoles = ['admin', 'super_user', 'corporate', 'billing', 'claims', 'qa'];
      if (!role || !allowedRoles.includes(role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      // Get the proof record
      const [proof] = await db.select()
        .from(moveProofsIndex)
        .where(eq(moveProofsIndex.id, parseInt(proofId)))
        .limit(1);

      if (!proof || !proof.mediaRef) {
        return res.status(404).json({ error: 'Proof not found' });
      }

      // Apply same case association check as /media endpoint
      // For claims/qa contexts, verify user has access to a related case
      if ((context === 'claims' || context === 'qa') && proof.moveId) {
        const { caseId } = req.query;
        if (caseId) {
          const [relatedCase] = await db.select({ id: cases.id, moveId: cases.moveId })
            .from(cases)
            .where(eq(cases.id, caseId as string))
            .limit(1);
          
          if (!relatedCase || relatedCase.moveId !== proof.moveId) {
            return res.status(403).json({ error: 'Case does not match proof' });
          }
        } else {
          const [relatedCase] = await db.select({ id: cases.id })
            .from(cases)
            .where(eq(cases.moveId, proof.moveId))
            .limit(1);
          
          if (!relatedCase && role !== 'admin' && role !== 'super_user') {
            return res.status(403).json({ error: 'No case associated with this move for claims/qa access' });
          }
        }
      }

      // Log access
      const ipAddress = req.ip || req.connection?.remoteAddress || 'unknown';
      const userAgent = req.headers['user-agent'] || 'unknown';
      await db.insert(proofAccessLog).values({
        userId: currentUserId,
        moveId: proof.moveId,
        proofId: proof.id,
        mediaRef: proof.mediaRef,
        context: `${context}_stream`,
        ipAddress,
        userAgent,
      });

      // Stream the file from object storage
      if (proof.mediaRef.startsWith('/objects/')) {
        const objectStorage = new ObjectStorageService();
        try {
          const file = await objectStorage.getObjectEntityFile(proof.mediaRef);
          return objectStorage.downloadObject(file, res);
        } catch (storageError: any) {
          if (storageError instanceof ObjectNotFoundError) {
            return res.status(404).json({ error: 'Media file not found in storage' });
          }
          throw storageError;
        }
      }

      // External URL - redirect
      if (proof.mediaRef.startsWith('http')) {
        return res.redirect(proof.mediaRef);
      }

      return res.status(404).json({ error: 'Unknown media reference format' });
    } catch (error: any) {
      console.error('[Proof Stream] Error:', error.message);
      res.status(500).json({ error: 'Failed to stream proof media' });
    }
  });

