  // POST /api/admin/execution/rebuild-derived - Rebuild derived views for a move (late event handling)
  app.post("/api/admin/execution/rebuild-derived", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!['admin', 'super_user'].includes(role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { moveId } = req.body;
      if (!moveId) {
        return res.status(400).json({ error: 'moveId is required' });
      }

      // Get all ledger entries for this move, sorted by occurred_at
      const ledgerEntries = await db.select()
        .from(moveExecutionLedger)
        .where(eq(moveExecutionLedger.moveId, moveId))
        .orderBy(moveExecutionLedger.occurredAt);

      if (ledgerEntries.length === 0) {
        return res.status(404).json({ error: 'No ledger entries found for this move' });
      }

      // Find the latest state change event
      let latestStateEntry = null;
      for (const entry of ledgerEntries) {
        if (stateChangeEventTypes.some(t => entry.eventType.toLowerCase().includes(t.replace('move.', '')))) {
          if (!latestStateEntry || new Date(entry.occurredAt) > new Date(latestStateEntry.occurredAt)) {
            latestStateEntry = entry;
          }
        }
      }

      // Rebuild current state if found
      if (latestStateEntry) {
        const payload = latestStateEntry.payloadJson as any;
        const newState = payload.state || payload.status || payload.current_state || 
                        payload.new_state || latestStateEntry.eventType.replace('move.', '');
        
        await db.insert(moveCurrentState)
          .values({
            moveId,
            driverId: latestStateEntry.driverId,
            currentState: newState,
            stateChangedAt: latestStateEntry.occurredAt,
            sourceEventId: latestStateEntry.eventId,
          })
          .onConflictDoUpdate({
            target: moveCurrentState.moveId,
            set: {
              driverId: latestStateEntry.driverId,
              currentState: newState,
              stateChangedAt: latestStateEntry.occurredAt,
              sourceEventId: latestStateEntry.eventId,
              lastUpdatedAt: new Date(),
            },
          });
      }

      res.json({
        success: true,
        moveId,
        ledgerEntriesCount: ledgerEntries.length,
        latestState: latestStateEntry ? {
          eventType: latestStateEntry.eventType,
          occurredAt: latestStateEntry.occurredAt,
        } : null,
      });
    } catch (error: any) {
      console.error('[Rebuild Derived] Error:', error.message);
      res.status(500).json({ error: 'Failed to rebuild derived views' });
    }
  });

