  // POST /api/admin/integrations/replay - Create and start a replay job
  app.post("/api/admin/integrations/replay", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const userId = currentUser?.id || currentUserId;
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!['admin', 'super_user'].includes(role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { from_timestamp, to_timestamp, event_type, move_id, driver_id, dry_run = false } = req.body;

      if (!from_timestamp || !to_timestamp) {
        return res.status(400).json({ message: "from_timestamp and to_timestamp are required" });
      }

      const fromDate = new Date(from_timestamp);
      const toDate = new Date(to_timestamp);

      if (isNaN(fromDate.getTime()) || isNaN(toDate.getTime())) {
        return res.status(400).json({ message: "Invalid timestamp format" });
      }

      if (fromDate >= toDate) {
        return res.status(400).json({ message: "from_timestamp must be before to_timestamp" });
      }

      // Build filters object
      const filters: Record<string, string> = {};
      if (event_type) filters.event_type = event_type;
      if (move_id) filters.move_id = move_id;
      if (driver_id) filters.driver_id = driver_id;

      // Create the replay job
      const [newJob] = await db.insert(replayJobs)
        .values({
          createdBy: user.id,
          fromTimestamp: fromDate,
          toTimestamp: toDate,
          filters,
          dryRun: dry_run,
          status: 'pending',
        })
        .returning();

      console.log(`[Replay Jobs] Created job ${newJob.id} by ${userId}`);

      // Start processing asynchronously
      processReplayJob(newJob.id).catch(err => {
        console.error(`[Replay Jobs] Error processing job ${newJob.id}:`, err);
      });

      res.status(201).json({
        message: "Replay job created and started",
        job: newJob,
      });

    } catch (error) {
      console.error("[Replay Jobs] Error creating job:", error);
      res.status(500).json({ message: "Failed to create replay job" });
    }
  });

