  // Replay job processor - processes events asynchronously
  async function processReplayJob(jobId: string) {
    console.log(`[Replay Processor] Starting job ${jobId}`);

    try {
      // Mark job as running
      await db.update(replayJobs)
        .set({
          status: 'running',
          startedAt: new Date(),
        })
        .where(eq(replayJobs.id, jobId));

      // Get job details
      const [job] = await db.select()
        .from(replayJobs)
        .where(eq(replayJobs.id, jobId))
        .limit(1);

      if (!job) {
        console.error(`[Replay Processor] Job ${jobId} not found`);
        return;
      }

      const filters = job.filters as Record<string, string>;

      // Build query conditions for events to replay
      const conditions = [
        sql`${ingestedEvents.occurredAt} >= ${job.fromTimestamp}`,
        sql`${ingestedEvents.occurredAt} <= ${job.toTimestamp}`,
        eq(ingestedEvents.mappingStatus, 'ok'), // Only replay mapped events
      ];

      if (filters.event_type) {
        conditions.push(eq(ingestedEvents.eventType, filters.event_type));
      }
      if (filters.move_id) {
        conditions.push(eq(ingestedEvents.moveId, filters.move_id));
      }
      if (filters.driver_id) {
        conditions.push(eq(ingestedEvents.driverId, filters.driver_id));
      }

      // Get total count
      const [countResult] = await db.select({
        count: sql<number>`COUNT(*)::int`
      })
        .from(ingestedEvents)
        .where(and(...conditions));

      const totalEvents = countResult?.count || 0;

      await db.update(replayJobs)
        .set({ totalEvents })
        .where(eq(replayJobs.id, jobId));

      console.log(`[Replay Processor] Job ${jobId} - ${totalEvents} events to process`);

      // Process events in batches
      const batchSize = 100;
      let processed = 0;
      let skipped = 0;
      let failed = 0;
      let lastEventId: string | null = null;
      const errors: string[] = [];

      // Fetch events in batches ordered by occurred_at
      let hasMore = true;
      while (hasMore) {
        // Check if job was cancelled
        const [currentJob] = await db.select({ status: replayJobs.status })
          .from(replayJobs)
          .where(eq(replayJobs.id, jobId))
          .limit(1);

        if (currentJob?.status === 'cancelled') {
          console.log(`[Replay Processor] Job ${jobId} was cancelled`);
          return;
        }

        // Fetch next batch
        const events = await db.select()
          .from(ingestedEvents)
          .where(and(...conditions))
          .orderBy(ingestedEvents.occurredAt)
          .limit(batchSize)
          .offset(processed + skipped);

        if (events.length === 0) {
          hasMore = false;
          break;
        }

        for (const event of events) {
          try {
            lastEventId = event.eventId;

            // Check idempotency - has this event already been processed to ledger?
            const [existingLedgerEntry] = await db.select({ id: moveExecutionLedger.id })
              .from(moveExecutionLedger)
              .where(eq(moveExecutionLedger.eventId, event.eventId))
              .limit(1);

            if (existingLedgerEntry) {
              // Already processed, skip but still run derived state updates
              skipped++;
            } else {
              processed++;
            }

            // In dry-run mode, don't actually process
            if (job.dryRun) {
              continue;
            }

            // Reprocess the event through the ledger processor
            // This is idempotent - it will skip if already in ledger, but update derived state
            if (event.moveId) {
              const payload = event.payloadJson as Record<string, any>;
              
              // 1. Add to execution ledger if not exists (idempotent)
              if (!existingLedgerEntry) {
                await db.insert(moveExecutionLedger).values({
                  moveId: event.moveId,
                  driverId: event.driverId,
                  eventId: event.eventId,
                  eventType: event.eventType,
                  occurredAt: event.occurredAt,
                  payloadJson: payload,
                });
              }

              // 2. Update current state if this is a state change event
              const stateChangeTypes = ['assigned', 'accepted', 'arrived', 'started', 'completed', 'cancelled', 'reassigned'];
              if (stateChangeTypes.some(t => event.eventType.toLowerCase().includes(t))) {
                const newState = payload.state || payload.status || payload.current_state || 
                                payload.new_state || event.eventType.replace('move.', '');
                
                const [currentState] = await db.select()
                  .from(moveCurrentState)
                  .where(eq(moveCurrentState.moveId, event.moveId))
                  .limit(1);
                
                if (!currentState || new Date(event.occurredAt) >= new Date(currentState.stateChangedAt)) {
                  await db.insert(moveCurrentState)
                    .values({
                      moveId: event.moveId,
                      driverId: event.driverId,
                      currentState: newState,
                      stateChangedAt: event.occurredAt,
                      sourceEventId: event.eventId,
                    })
                    .onConflictDoUpdate({
                      target: moveCurrentState.moveId,
                      set: {
                        driverId: event.driverId,
                        currentState: newState,
                        stateChangedAt: event.occurredAt,
                        sourceEventId: event.eventId,
                        lastUpdatedAt: new Date(),
                      },
                    });
                }
              }

              // 3. Index proofs if this is a proof event
              if (event.eventType.toLowerCase().includes('proof') || 
                  event.eventType.toLowerCase().includes('photo') ||
                  event.eventType.toLowerCase().includes('signature')) {
                
                // Check if proof already indexed (idempotent)
                const [existingProof] = await db.select({ id: moveProofsIndex.id })
                  .from(moveProofsIndex)
                  .where(eq(moveProofsIndex.eventId, event.eventId))
                  .limit(1);

                if (!existingProof) {
                  await db.insert(moveProofsIndex).values({
                    moveId: event.moveId,
                    driverId: event.driverId,
                    proofType: payload.proof_type || payload.type || 'photo',
                    mediaRef: payload.media_ref || payload.url || payload.media_url,
                    occurredAt: event.occurredAt,
                    geoLat: payload.geo?.lat || payload.latitude,
                    geoLng: payload.geo?.lng || payload.longitude,
                    geoAccuracy: payload.geo?.accuracy,
                    eventId: event.eventId,
                    metadata: payload,
                  });
                }
              }
            }

          } catch (eventError: any) {
            failed++;
            errors.push(`${event.eventId}: ${eventError.message}`);
            console.error(`[Replay Processor] Error processing event ${event.eventId}:`, eventError.message);
          }
        }

        // Update progress
        const totalProcessed = processed + skipped + failed;
        const progressPercent = Math.round((totalProcessed / totalEvents) * 100);

        await db.update(replayJobs)
          .set({
            processedCount: processed,
            skippedCount: skipped,
            failedCount: failed,
            currentEventId: lastEventId,
            progressPercent,
            errorSummary: errors.length > 0 ? errors.slice(-10).join('\n') : null,
          })
          .where(eq(replayJobs.id, jobId));

        console.log(`[Replay Processor] Job ${jobId} progress: ${progressPercent}% (${processed} processed, ${skipped} skipped, ${failed} failed)`);
      }

      // Mark job as completed
      await db.update(replayJobs)
        .set({
          status: failed > 0 && processed === 0 ? 'failed' : 'completed',
          completedAt: new Date(),
          processedCount: processed,
          skippedCount: skipped,
          failedCount: failed,
          progressPercent: 100,
          errorSummary: errors.length > 0 ? errors.slice(-10).join('\n') : null,
          lastError: errors.length > 0 ? errors[errors.length - 1] : null,
        })
        .where(eq(replayJobs.id, jobId));

      console.log(`[Replay Processor] Job ${jobId} completed: ${processed} processed, ${skipped} skipped, ${failed} failed`);

    } catch (error: any) {
      console.error(`[Replay Processor] Job ${jobId} failed:`, error);
      
      await db.update(replayJobs)
        .set({
          status: 'failed',
          completedAt: new Date(),
          lastError: error.message,
          errorSummary: error.message,
        })
        .where(eq(replayJobs.id, jobId));
    }
  }

  // GET /api/admin/integrations/health - Integration health overview
  app.get("/api/admin/integrations/health", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!['admin', 'super_user'].includes(role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const now = new Date();
      const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
      const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

      // Events in last hour
      const [hourlyStats] = await db.select({
        received: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.receivedAt} >= ${oneHourAgo})::int`,
        failed: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.processingStatus} = 'failed' AND ${ingestedEvents.receivedAt} >= ${oneHourAgo})::int`,
      }).from(ingestedEvents);

      // Events in last 24 hours
      const [dailyStats] = await db.select({
        total: sql<number>`COUNT(*)::int`,
        received: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.processingStatus} = 'received')::int`,
        processed: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.processingStatus} = 'processed')::int`,
        failed: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.processingStatus} = 'failed')::int`,
        unsupported: sql<number>`COUNT(*) FILTER (WHERE ${ingestedEvents.processingStatus} = 'unsupported')::int`,
      })
      .from(ingestedEvents)
      .where(sql`${ingestedEvents.receivedAt} >= ${twentyFourHoursAgo}`);

      // Last event received
      const [lastEvent] = await db.select({
        eventId: ingestedEvents.eventId,
        eventType: ingestedEvents.eventType,
        receivedAt: ingestedEvents.receivedAt
      })
      .from(ingestedEvents)
      .orderBy(desc(ingestedEvents.receivedAt))
      .limit(1);

      // Determine health status
      const failureRate = dailyStats?.total > 0 
        ? (dailyStats.failed / dailyStats.total) * 100 
        : 0;
      
      let healthStatus = 'healthy';
      if (failureRate > 10) healthStatus = 'degraded';
      if (failureRate > 25) healthStatus = 'critical';

      res.json({
        status: healthStatus,
        lastEventAt: lastEvent?.receivedAt || null,
        lastHour: {
          eventsReceived: hourlyStats?.received || 0,
          failedEvents: hourlyStats?.failed || 0
        },
        last24Hours: {
          total: dailyStats?.total || 0,
          received: dailyStats?.received || 0,
          processed: dailyStats?.processed || 0,
          failed: dailyStats?.failed || 0,
          unsupported: dailyStats?.unsupported || 0,
          failureRate: Math.round(failureRate * 100) / 100
        }
      });

    } catch (error) {
      console.error("[Admin Integrations] Error fetching health:", error);
      res.status(500).json({ message: "Failed to fetch integration health" });
    }
  });

