  // POST /api/admin/integrations/api-keys - Create new API key
  app.post("/api/admin/integrations/api-keys", isAuthenticated, async (req: any, res: Response) => {
    try {
      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const userEmail = req.user?.claims?.email;
      let currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      if (!currentUser && userEmail) {
        currentUser = await storage.getUserByEmail(userEmail);
      }
      const role = currentUser?.role || req.user?.claims?.metadata?.role;
      
      if (!['admin', 'super_user'].includes(role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { keyName, sourceSystem, expiresAt } = req.body;
      
      if (!keyName || !sourceSystem) {
        return res.status(400).json({ message: "keyName and sourceSystem are required" });
      }

      // Generate secure API key
      const crypto = await import('crypto');
      const rawKey = crypto.randomBytes(32).toString('hex');
      const keyHash = crypto.createHash('sha256').update(rawKey).digest('hex');
      const keyPrefix = rawKey.substring(0, 8);

      const [newKey] = await db.insert(integrationApiKeys).values({
        keyName,
        keyHash,
        keyPrefix,
        sourceSystem,
        permissions: ['events:write'],
        expiresAt: expiresAt ? new Date(expiresAt) : null,
        createdByUserId: currentUser?.id,
      }).returning();

      // Return the raw key ONCE - it cannot be retrieved later
      res.status(201).json({
        id: newKey.id,
        keyName: newKey.keyName,
        keyPrefix: newKey.keyPrefix,
        sourceSystem: newKey.sourceSystem,
        apiKey: rawKey, // Only returned on creation
        expiresAt: newKey.expiresAt,
        message: "Store this API key securely - it cannot be retrieved again"
      });

    } catch (error) {
      console.error("[Admin Integrations] Error creating API key:", error);
      res.status(500).json({ message: "Failed to create API key" });
    }
  });

