    try {
      if (req.user?.role !== 'admin' && req.user?.role !== 'corporate') {
        return res.status(403).json({ message: "Access denied" });
      }

      const { keyId, status, limit = 100, offset = 0 } = req.query;

      let query = db.select().from(ingestionAuditLogs);
      const conditions = [];

      if (keyId) {
        conditions.push(eq(ingestionAuditLogs.keyId, keyId as string));
      }
      if (status) {
        conditions.push(eq(ingestionAuditLogs.responseStatus, parseInt(status as string)));
      }

      if (conditions.length > 0) {
        query = query.where(and(...conditions)) as typeof query;
      }

      const logs = await query
        .orderBy(desc(ingestionAuditLogs.occurredAt))
        .limit(parseInt(limit as string))
        .offset(parseInt(offset as string));

      res.json(logs);
    } catch (error) {
      console.error("[Ingestion Audit] Error fetching audit logs:", error);
      res.status(500).json({ message: "Failed to fetch ingestion audit logs" });
    }
