  // POST /api/schemas - Create a new schema
  app.post("/api/schemas", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Check for admin access
      let adminUser: any = null;
      const [user] = await db.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!user) {
        const [userByEmail] = await db.select().from(users)
          .where(eq(users.email, (req as any).user?.claims?.email || ''))
          .limit(1);
        if (!userByEmail || !['admin', 'super_user'].includes(userByEmail.role || '')) {
          return res.status(403).json({ message: "Admin access required" });
        }
        adminUser = userByEmail;
      } else if (!['admin', 'super_user'].includes(user.role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      } else {
        adminUser = user;
      }

      const { eventType, schemaVersion, schemaJson, description, requiredFields, deprecationWindowDays } = req.body;

      if (!eventType || !schemaVersion || !schemaJson) {
        return res.status(400).json({ message: "eventType, schemaVersion, and schemaJson are required" });
      }

      // Check for existing schema with same type and version
      const [existing] = await db.select()
        .from(eventSchemas)
        .where(and(
          eq(eventSchemas.eventType, eventType),
          eq(eventSchemas.schemaVersion, schemaVersion)
        ))
        .limit(1);

      if (existing) {
        return res.status(409).json({ 
          message: "Schema already exists for this event type and version",
          existingId: existing.id
        });
      }

      const [newSchema] = await db.insert(eventSchemas).values({
        eventType,
        schemaVersion,
        schemaJson,
        description,
        requiredFields: requiredFields || [],
        deprecationWindowDays: deprecationWindowDays || 30,
        createdBy: adminUser.id,
        status: 'active',
      }).returning();

      res.status(201).json({ schema: newSchema });
    } catch (error) {
      console.error("[Schemas] Error creating schema:", error);
      res.status(500).json({ message: "Failed to create schema" });
    }
  });

  // PATCH /api/schemas/:id/deprecate - Deprecate a schema
  app.patch("/api/schemas/:id/deprecate", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Check for admin access
      let adminUser: any = null;
      const [user] = await db.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!user) {
        const [userByEmail] = await db.select().from(users)
          .where(eq(users.email, (req as any).user?.claims?.email || ''))
          .limit(1);
        if (!userByEmail || !['admin', 'super_user'].includes(userByEmail.role || '')) {
          return res.status(403).json({ message: "Admin access required" });
        }
        adminUser = userByEmail;
      } else if (!['admin', 'super_user'].includes(user.role || '')) {
        return res.status(403).json({ message: "Admin access required" });
      } else {
        adminUser = user;
      }

      const { id } = req.params;
      const { deprecationWindowDays } = req.body;

      const [schema] = await db.select().from(eventSchemas).where(eq(eventSchemas.id, id)).limit(1);
      if (!schema) {
        return res.status(404).json({ message: "Schema not found" });
      }

      if (schema.status !== 'active') {
        return res.status(400).json({ message: "Only active schemas can be deprecated" });
      }

      const [updated] = await db.update(eventSchemas)
        .set({
          status: 'deprecated',
          deprecatedAt: new Date(),
          deprecatedBy: adminUser.id,
          deprecationWindowDays: deprecationWindowDays || schema.deprecationWindowDays,
        })
        .where(eq(eventSchemas.id, id))
        .returning();

      res.json({ schema: updated });
    } catch (error) {
      console.error("[Schemas] Error deprecating schema:", error);
      res.status(500).json({ message: "Failed to deprecate schema" });
    }
  });

