  // GET /api/schemas/lookup/:eventType/:version - Lookup schema by event type and version
  app.get("/api/schemas/lookup/:eventType/:version", async (req: Request, res: Response) => {
    try {
      const { eventType, version } = req.params;
      const schemaVersion = parseInt(version, 10);

      if (isNaN(schemaVersion)) {
        return res.status(400).json({ message: "Invalid version number" });
      }

      const [schema] = await db.select()
        .from(eventSchemas)
        .where(and(
          eq(eventSchemas.eventType, eventType),
          eq(eventSchemas.schemaVersion, schemaVersion)
        ))
        .limit(1);

      if (!schema) {
        return res.json({ 
          found: false,
          status: 'unknown',
          message: `No schema registered for ${eventType} v${schemaVersion}`
        });
      }

      // Check if deprecated schema is within deprecation window
      let isWithinWindow = true;
      if (schema.status === 'deprecated' && schema.deprecatedAt) {
        const windowDays = schema.deprecationWindowDays || 30;
        const windowEnd = new Date(schema.deprecatedAt);
        windowEnd.setDate(windowEnd.getDate() + windowDays);
        isWithinWindow = new Date() < windowEnd;
      }

      res.json({
        found: true,
        status: schema.status,
        isWithinWindow,
        schema: {
          id: schema.id,
          eventType: schema.eventType,
          schemaVersion: schema.schemaVersion,
          requiredFields: schema.requiredFields,
          deprecatedAt: schema.deprecatedAt,
          deprecationWindowDays: schema.deprecationWindowDays,
        }
      });
    } catch (error) {
      console.error("[Schemas] Error looking up schema:", error);
      res.status(500).json({ message: "Failed to lookup schema" });
    }
  });

  // GET /api/schemas/event-types - List all unique event types with their versions
  app.get("/api/schemas/event-types", async (req: Request, res: Response) => {
    try {
      const schemas = await db.select({
        eventType: eventSchemas.eventType,
        schemaVersion: eventSchemas.schemaVersion,
        status: eventSchemas.status,
      })
        .from(eventSchemas)
        .orderBy(eventSchemas.eventType, desc(eventSchemas.schemaVersion));

      // Group by event type
      const eventTypes: Record<string, { versions: { version: number; status: string }[] }> = {};
      for (const schema of schemas) {
        if (!eventTypes[schema.eventType]) {
          eventTypes[schema.eventType] = { versions: [] };
        }
        eventTypes[schema.eventType].versions.push({
          version: schema.schemaVersion,
          status: schema.status,
        });
      }

      res.json({ eventTypes });
    } catch (error) {
      console.error("[Schemas] Error listing event types:", error);
      res.status(500).json({ message: "Failed to list event types" });
    }
  });

