  // POST /api/external-access/grants - Create a new access grant (admin only)
  app.post("/api/external-access/grants", async (req: Request, res: Response) => {
    try {
      let authUserId: string | null = (req as any).session?.userId || null;
      if (!authUserId && (req as any).user?.claims?.sub) {
        authUserId = (req as any).user.claims.sub;
      }
      if (!authUserId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      let user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, authUserId!),
      });
      if (!user && (req as any).user?.claims?.email) {
        user = await db.query.users.findFirst({
          where: (users, { eq }) => eq(users.email, (req as any).user.claims.email),
        });
      }
      if (!user || (user.role !== 'admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { 
        role, 
        grantedToEmail, 
        grantedToName, 
        grantedToOrg, 
        allowedScopes, 
        customerId, 
        claimId, 
        expiresAt, 
        notes 
      } = req.body;

      if (!role || !grantedToEmail || !allowedScopes || !expiresAt) {
        return res.status(400).json({ message: "Missing required fields" });
      }

      if (!['carrier_viewer', 'broker_viewer', 'insurer_viewer', 'auditor_viewer', 'oem_viewer', 'partner_viewer'].includes(role)) {
        return res.status(400).json({ message: "Invalid role" });
      }

      const { createAccessGrant } = await import("./externalAccessService");
      const grant = await createAccessGrant({
        role,
        grantedToEmail,
        grantedToName,
        grantedToOrg,
        allowedScopes,
        customerId,
        claimId,
        expiresAt: new Date(expiresAt),
        notes,
        createdBy: user.id,
      });

      res.status(201).json(grant);
    } catch (error) {
      console.error("[External Access] Error creating grant:", error);
      res.status(500).json({ message: "Failed to create access grant" });
    }
  });

