  // GET /api/external/validate - Validate external access token
  app.get("/api/external/validate", async (req: Request, res: Response) => {
    try {
      const token = req.headers["x-access-token"] as string;
      if (!token) {
        return res.status(401).json({ message: "Access token required" });
      }

      const { validateAccessToken, logExternalAccess } = await import("./externalAccessService");
      const grant = await validateAccessToken(token);

      if (!grant) {
        return res.status(401).json({ message: "Invalid or expired access token" });
      }

      await logExternalAccess({
        grant,
        accessedResource: "validate_token",
        requestMethod: "GET",
        requestPath: "/api/external/validate",
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"],
      }, 200);

      res.json({
        valid: true,
        grantId: grant.id,
        granteeEmail: grant.grantedToEmail,
        granteeName: grant.grantedToName || grant.grantedToEmail,
        granteeOrganization: grant.grantedToOrg || "Unknown",
        role: grant.role,
        scopes: grant.allowedScopes || [],
        expiresAt: grant.expiresAt,
        customerRestriction: grant.customerId || null,
        claimRestriction: grant.claimId || null,
      });
    } catch (error) {
      console.error("[External Portal] Error validating token:", error);
      res.status(500).json({ message: "Token validation failed" });
    }
  });

