      if (!checkScopeAccess(grant, 'evidence_chain')) {
        await logExternalAccess({
          grant,
          accessedResource: "evidence_chain",
          resourceScope: `claim:${req.params.claimId}`,
          requestMethod: "GET",
          requestPath: `/api/external/evidence-chain/${req.params.claimId}`,
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"],
        }, 403);
        return res.status(403).json({ message: "Access to this resource not permitted" });
      }

      if (grant.claimId && grant.claimId !== req.params.claimId) {
        await logExternalAccess({
          grant,
          accessedResource: "evidence_chain",
          resourceScope: `claim:${req.params.claimId}`,
          requestMethod: "GET",
          requestPath: `/api/external/evidence-chain/${req.params.claimId}`,
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"],
        }, 403);
        return res.status(403).json({ message: "Access limited to specific claim" });
      }

      const { getEvidenceChainForClaim } = await import("./evidenceChainService");
      const chain = await getEvidenceChainForClaim(req.params.claimId);

      if (!chain) {
        await logExternalAccess({
          grant,
          accessedResource: "evidence_chain",
          resourceScope: `claim:${req.params.claimId}`,
          requestMethod: "GET",
          requestPath: `/api/external/evidence-chain/${req.params.claimId}`,
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"],
        }, 404);
        return res.status(404).json({ message: "No evidence chain found for this claim" });
      }

      const sanitizedChain = {
        ...chain,
        entries: chain.entries.map(entry => ({
          ...entry,
          actor: {
            type: entry.actor.type,
            id: null,
            name: entry.actor.type === 'driver' ? 'Driver' : entry.actor.name,
          },
        })),
      };

      await logExternalAccess({
        grant,
        accessedResource: "evidence_chain",
        resourceScope: `claim:${req.params.claimId}`,
        requestMethod: "GET",
        requestPath: `/api/external/evidence-chain/${req.params.claimId}`,
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"],
      }, 200);

      res.json(sanitizedChain);
