  app.get("/api/external/scheduling/controls", async (req: Request, res: Response) => {
    try {
      const token = req.headers["x-access-token"] as string;
      if (!token) return res.status(401).json({ message: "Access token required" });
      const { validateAccessToken, checkScopeAccess, logExternalAccess } = await import("./externalAccessService");
      const grant = await validateAccessToken(token);
      if (!grant) return res.status(401).json({ message: "Invalid or expired access token" });
      if (!checkScopeAccess(grant, 'scheduling_controls')) {
        await logExternalAccess({ grant, accessedResource: "scheduling_controls", requestMethod: "GET", requestPath: "/api/external/scheduling/controls", ipAddress: req.ip, userAgent: req.headers["user-agent"] }, 403);
        return res.status(403).json({ message: "Access to this resource not permitted" });
      }
      const { getGrantOrgContext } = await import("./externalAccessService");
      const orgId = await getGrantOrgContext(grant);
      const orgUsers = orgId ? await db.select({ id: users.id }).from(users).where(eq(users.orgId, orgId)) : [];
      const orgUserIds = orgUsers.map(u => u.id);
      const { schedulingEntities, crossLocationMobilityConfigs } = await import("@shared/schema");
      const entities = orgUserIds.length > 0
        ? await db.select({ id: schedulingEntities.id }).from(schedulingEntities).where(inArray(schedulingEntities.createdBy, orgUserIds))
        : [];
      const allowedEntityIds = entities.map(e => e.id);
      const mobilityConfigs = await db.select().from(crossLocationMobilityConfigs);
      const scopedConfigs = allowedEntityIds.length > 0
        ? mobilityConfigs.filter((c: any) => c.entityId && allowedEntityIds.includes(c.entityId))
        : [];
      const controlsOverview = {
        schedulingControls: {
          mobilityConfigurations: scopedConfigs.map((c: any) => ({
            entityId: c.entityId, maxTravelDistanceMiles: c.maxTravelDistanceMiles,
            maxTravelTimeMinutes: c.maxTravelTimeMinutes,
            minRestBetweenCrossLocationMinutes: c.minRestBetweenCrossLocationMinutes,
            maxCrossLocationShiftsPerWeek: c.maxCrossLocationShiftsPerWeek,
            maxCrossLocationShiftsPerDay: c.maxCrossLocationShiftsPerDay, isActive: c.isActive,
          })),
          totalConfigurations: scopedConfigs.length,
          activeConfigurations: scopedConfigs.filter((c: any) => c.isActive).length,
        },
        accessedAt: new Date().toISOString(), grantId: grant.id,
      };
      await logExternalAccess({ grant, accessedResource: "scheduling_controls", requestMethod: "GET", requestPath: "/api/external/scheduling/controls", ipAddress: req.ip, userAgent: req.headers["user-agent"] }, 200);
      res.json(controlsOverview);
    } catch (error) {
      console.error("[External Scheduling] Error fetching controls:", error);
      res.status(500).json({ message: "Failed to fetch scheduling controls" });
    }
  });

  app.get("/api/external/scheduling/sla", async (req: Request, res: Response) => {
    try {
      const token = req.headers["x-access-token"] as string;
      if (!token) return res.status(401).json({ message: "Access token required" });
      const { validateAccessToken, checkScopeAccess, logExternalAccess } = await import("./externalAccessService");
      const grant = await validateAccessToken(token);
      if (!grant) return res.status(401).json({ message: "Invalid or expired access token" });
      if (!checkScopeAccess(grant, 'scheduling_sla')) {
        await logExternalAccess({ grant, accessedResource: "scheduling_sla", requestMethod: "GET", requestPath: "/api/external/scheduling/sla", ipAddress: req.ip, userAgent: req.headers["user-agent"] }, 403);
        return res.status(403).json({ message: "Access to this resource not permitted" });
      }
      const { getGrantOrgContext: getOrgCtxSla } = await import("./externalAccessService");
      const slaOrgId = await getOrgCtxSla(grant);
      const slaOrgUsers = slaOrgId ? await db.select({ id: users.id }).from(users).where(eq(users.orgId, slaOrgId)) : [];
      const slaOrgUserIds = slaOrgUsers.map(u => u.id);
      const { schedulingEntities: slaEntitiesTable, schedulingSlaDefinitions, schedulingSlaEvents } = await import("@shared/schema");
      const slaEntities = slaOrgUserIds.length > 0
        ? await db.select({ id: slaEntitiesTable.id }).from(slaEntitiesTable).where(inArray(slaEntitiesTable.createdBy, slaOrgUserIds))
        : [];
      const slaAllowedEntityIds = slaEntities.map(e => e.id);
      const definitions = await db.select().from(schedulingSlaDefinitions);
      const scopedDefinitions = slaAllowedEntityIds.length > 0
        ? definitions.filter((d: any) => d.entityId && slaAllowedEntityIds.includes(d.entityId))
        : [];
      const scopedDefIds = scopedDefinitions.map((d: any) => d.id);
      const events = await db.select().from(schedulingSlaEvents).limit(500);
      const scopedEvents = scopedDefIds.length > 0
        ? events.filter((e: any) => scopedDefIds.includes(e.slaDefinitionId))
        : [];
      const totalEvents = scopedEvents.length;
      const metEvents = scopedEvents.filter((e: any) => e.status === 'met').length;
      const warningEvents = scopedEvents.filter((e: any) => e.status === 'warning').length;
      const breachedEvents = scopedEvents.filter((e: any) => e.status === 'breached').length;
      const slaOverview = {
        slaCompliance: {
          definitions: scopedDefinitions.map((d: any) => ({
            id: d.id, name: d.name, metricType: d.metricType,
            targetValue: d.targetValue, warningThreshold: d.warningThreshold, isActive: d.isActive,
          })),
          metrics: { totalEvents, met: metEvents, warning: warningEvents, breached: breachedEvents,
            complianceRate: totalEvents > 0 ? Math.round((metEvents / totalEvents) * 100) : 100,
          },
        },
        accessedAt: new Date().toISOString(), grantId: grant.id,
      };
      await logExternalAccess({ grant, accessedResource: "scheduling_sla", requestMethod: "GET", requestPath: "/api/external/scheduling/sla", ipAddress: req.ip, userAgent: req.headers["user-agent"] }, 200);
      res.json(slaOverview);
    } catch (error) {
      console.error("[External Scheduling] Error fetching SLA data:", error);
      res.status(500).json({ message: "Failed to fetch SLA compliance data" });
    }
  });

