  // POST /api/legal-holds - Apply a new legal hold
  app.post("/api/legal-holds", async (req: Request, res: Response) => {
    try {
      let authUserId: string | null = (req as any).session?.userId || null;
      if (!authUserId && (req as any).user?.claims?.sub) {
        authUserId = (req as any).user.claims.sub;
      }
      if (!authUserId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      let user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, authUserId!),
      });
      if (!user && (req as any).user?.claims?.email) {
        user = await db.query.users.findFirst({
          where: (users, { eq }) => eq(users.email, (req as any).user.claims.email),
        });
      }
      if (!user || (user.role !== 'admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { scopeType, scopeId, reason, matterReference, notes } = req.body;

      if (!scopeType || !scopeId || !reason) {
        return res.status(400).json({ message: "scopeType, scopeId, and reason are required" });
      }

      const validScopeTypes = ["move", "case", "driver"];
      if (!validScopeTypes.includes(scopeType)) {
        return res.status(400).json({ 
          message: `Invalid scopeType. Must be one of: ${validScopeTypes.join(", ")}` 
        });
      }

      const { applyLegalHold } = await import("./legalHoldService");
      const hold = await applyLegalHold({
        scopeType,
        scopeId,
        reason,
        matterReference,
        notes,
        appliedBy: userId,
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"] as string,
      });

      res.status(201).json(hold);
    } catch (error) {
      console.error("[Legal Hold] Error applying hold:", error);
      if (error instanceof Error && error.message.includes("already exists")) {
        return res.status(409).json({ message: error.message });
      }
      res.status(500).json({ message: "Failed to apply legal hold" });
    }
  });

