  // ============================================================================
  // MOVE EVENT REPLAY / BACKFILL - Integration Resilience
  // ============================================================================

  // POST /api/move-events/replay - Replay events for a time range (Ops Console recovery)
  app.post("/api/move-events/replay", async (req: Request, res: Response) => {
    try {
      let authUserId: string | null = (req as any).session?.userId || null;
      if (!authUserId && (req as any).user?.claims?.sub) {
        authUserId = (req as any).user.claims.sub;
      }
      if (!authUserId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      let user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, authUserId!),
      });
      if (!user && (req as any).user?.claims?.email) {
        user = await db.query.users.findFirst({
          where: (users, { eq }) => eq(users.email, (req as any).user.claims.email),
        });
      }
      if (!user || (user.role !== 'admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { startTime, endTime, eventTypes, moveIds } = req.body;

      if (!startTime || !endTime) {
        return res.status(400).json({ message: "startTime and endTime are required (ISO format)" });
      }

      const start = new Date(startTime);
      const end = new Date(endTime);

      if (isNaN(start.getTime()) || isNaN(end.getTime())) {
        return res.status(400).json({ message: "Invalid date format. Use ISO 8601 format." });
      }

      if (start >= end) {
        return res.status(400).json({ message: "startTime must be before endTime" });
      }

      const { replayEventsForTimeRange } = await import("./moveEventService");
      const result = await replayEventsForTimeRange({
        startTime: start,
        endTime: end,
        eventTypes,
        moveIds,
        requestedBy: userId,
      });

      console.log(`[Move Events] Replay completed by ${userId}: ${result.eventsReplayed} events`);
      res.json(result);
    } catch (error) {
      console.error("[Move Events] Error replaying events:", error);
      res.status(500).json({ message: "Failed to replay events" });
    }
  });

