  // POST /api/driver-master-data/resolve - Resolve multiple drivers by IDs
  app.post("/api/driver-master-data/resolve", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { driverIds } = req.body;
      if (!Array.isArray(driverIds) || driverIds.length === 0) {
        return res.status(400).json({ message: "driverIds array is required" });
      }

      if (driverIds.length > 100) {
        return res.status(400).json({ message: "Maximum 100 drivers per request" });
      }

      const { queryDriverMasterData } = await import("./driverMasterDataService");
      const result = await queryDriverMasterData({
        driverIds,
        includeInactive: true,
        limit: 100,
      });

      const driverMap = new Map(result.drivers.map(d => [d.driverId, d]));
      const resolved = driverIds.map(id => ({
        driverId: id,
        found: driverMap.has(id),
        data: driverMap.get(id) || null,
      }));

      res.json({
        resolved,
        totalFound: result.drivers.length,
        totalRequested: driverIds.length,
      });
    } catch (error) {
      console.error("[Driver Master Data] Error resolving drivers:", error);
      res.status(500).json({ message: "Failed to resolve driver identities" });
    }
  });

