  const canAccessCandidateRecord = async (
    context: any,
    candidate: any,
    permission: "read" | "write",
  ): Promise<boolean> => {
    if (!hasPermission(context, permission)) return false;
    if (context.isAdmin) return true;

    const preferredMarkets = candidate.preferredMarkets || [];
    if (preferredMarkets.some((market: string) => context.authorizedMarkets.includes(market))) {
      return true;
    }

    const applicationMarkets = await db
      .select({ market: recruitingRequisitions.market })
      .from(recruitingApplications)
      .innerJoin(recruitingRequisitions, eq(recruitingApplications.requisitionId, recruitingRequisitions.id))
      .where(eq(recruitingApplications.candidateId, candidate.id));

    return applicationMarkets.some(({ market }) => context.authorizedMarkets.includes(market));
  };

  // Candidate screens use this read-only capability payload to keep write controls
  // aligned with the same Recruiting permission model enforced by mutation routes.
  app.get("/api/recruiting/candidates/access", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });
      const context = await getUserRecruitingContext(userId, user?.role || "");
      return res.json({
        canRead: hasPermission(context, "read"),
        canWrite: hasPermission(context, "write"),
        isAdmin: context.isAdmin,
        authorizedMarkets: context.authorizedMarkets,
      });
    } catch (error) {
      console.error("[Recruiting] Error fetching Candidate access:", error);
      return res.status(500).json({ message: "Failed to retrieve Candidate access" });
    }
  });


  // GET /api/recruiting/candidates/search - Global candidate search with fuzzy matching
  app.get("/api/recruiting/candidates/search", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      
      if (!hasPermission(recruitingContext, "read")) {
        return res.status(403).json({ message: "No permission to search candidates" });
      }

      const { q, limit, offset, includeArchived } = req.query;
      
      if (!q || typeof q !== 'string' || q.trim().length < 2) {
        return res.json({ candidates: [], total: 0, query: q || '' });
      }

      const { searchCandidatesGlobal } = await import("./recruitingService");
      
      // Pass authorized markets for market isolation (null = admin access)
      const authorizedMarkets = recruitingContext.isAdmin ? null : recruitingContext.authorizedMarkets;
      
      const result = await searchCandidatesGlobal({
        query: q.trim(),
        authorizedMarkets,
        limit: limit ? parseInt(limit as string, 10) : 20,
        offset: offset ? parseInt(offset as string, 10) : 0,
        includeArchived: includeArchived === "true",
      });

      res.json(result);
    } catch (error) {
      console.error("[Recruiting] Error searching candidates:", error);
      res.status(500).json({ message: "Failed to search candidates" });
    }
  });
