  // POST /api/recruiting/candidates - Create a new candidate
  app.post("/api/recruiting/candidates", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasPermission(recruitingContext, "write")) {
        return res.status(403).json({ message: "No permission to create candidates" });
      }

      const { insertRecruitingCandidateSchema } = await import("@shared/schema");
      const candidateInput = insertRecruitingCandidateSchema.parse(req.body);
      if (
        !recruitingContext.isAdmin
        && (!candidateInput.preferredMarkets?.length
          || candidateInput.preferredMarkets.some(market => !recruitingContext.authorizedMarkets.includes(market)))
      ) {
        return res.status(403).json({ message: "Candidates must be assigned only to markets you are authorized to manage" });
      }

      const { createCandidate } = await import("./recruitingService");
      const candidate = await createCandidate(candidateInput, userId, user?.email || null);

      res.status(201).json(candidate);
    } catch (error: any) {
      console.error("[Recruiting] Error creating candidate:", error);
      if (error.code === "DUPLICATE_CANDIDATE") {
        return res.status(409).json({
          message: "A candidate with this contact information already exists",
          code: "DUPLICATE_CANDIDATE",
          existingCandidate: error.existingCandidate,
          matchedOn: error.matchedOn,
        });
      }
      if (
        error.message?.startsWith("Invalid authorization type")
        || error.message?.startsWith("Invalid endorsement")
        || error.message?.startsWith("Other source details are required")
      ) {
        return res.status(400).json({ message: error.message });
      }
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      res.status(500).json({ message: "Failed to create candidate" });
    }


  });

