  // PUT /api/recruiting/requisitions/:id/stage-rules — Upsert stage rules for a requisition
  app.put("/api/recruiting/requisitions/:id/stage-rules", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const dbUser = await storage.getUser(userId);
      const role = dbUser?.role || "employee";
      if (!hasCorporateAccess(role)) return res.status(403).json({ message: "Access denied" });

      const rulesSchema = z.array(z.object({
        stageName: z.string().min(1),
        requiresReadiness: z.boolean(),
      }));
      const parsed = rulesSchema.safeParse(req.body);
      if (!parsed.success) return res.status(400).json({ message: "Validation failed", errors: parsed.error.errors });

      await db.delete(requisitionStageRules).where(eq(requisitionStageRules.requisitionId, req.params.id));

      const rulesToInsert = parsed.data.filter(r => r.requiresReadiness);
      if (rulesToInsert.length > 0) {
        await db.insert(requisitionStageRules).values(
          rulesToInsert.map(r => ({
            requisitionId: req.params.id,
            stageName: r.stageName,
            requiresReadiness: r.requiresReadiness,
          }))
        );
      }

      const rules = await db.select().from(requisitionStageRules).where(eq(requisitionStageRules.requisitionId, req.params.id)).orderBy(requisitionStageRules.stageName);
      res.json(rules);
    } catch (error) {
      console.error("[Recruiting] Error upserting stage rules:", error);
      res.status(500).json({ message: "Failed to update stage rules" });
    }
  });

