  // POST /api/recruiting/applications/:id/check-conflict - Check for concurrency conflict
  app.post("/api/recruiting/applications/:id/check-conflict", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { lastKnownUpdatedAt } = req.body;
      const { checkConcurrencyConflict } = await import("./recruitingService");
      const result = await checkConcurrencyConflict(req.params.id, lastKnownUpdatedAt);

      if (result.conflict) {
        return res.status(409).json({
          message: "Application has been modified since your last load",
          currentUpdatedAt: result.currentUpdatedAt,
        });
      }

      res.json({ conflict: false });
    } catch (error) {
      console.error("[Recruiting] Error checking conflict:", error);
      res.status(500).json({ message: "Failed to check conflict" });
    }
  });


  // GET /api/recruiting/applications/:id/available-transitions - Get available transitions for current stage
  app.get("/api/recruiting/applications/:id/available-transitions", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const application = await db.query.recruitingApplications.findFirst({
        where: eq(recruitingApplications.id, req.params.id),
      });
      if (!application) {
        return res.status(404).json({ message: "Application not found" });
      }

      const requisition = await db.query.recruitingRequisitions.findFirst({
        where: eq(recruitingRequisitions.id, application.requisitionId),
      });
      if (!requisition || !requisition.workflowId) {
        return res.json({ transitions: [], stages: [] });
      }

      const currentStageRecord = await db.query.recruitingWorkflowStages.findFirst({
        where: and(
          eq(recruitingWorkflowStages.workflowId, requisition.workflowId),
          eq(recruitingWorkflowStages.stageKey, application.currentStage)
        ),
      });
      if (!currentStageRecord) {
        return res.json({ transitions: [], stages: [] });
      }

      const allStages = await db.query.recruitingWorkflowStages.findMany({
        where: eq(recruitingWorkflowStages.workflowId, requisition.workflowId),
        orderBy: [recruitingWorkflowStages.sortOrder],
      });

      const transitions = await db.query.recruitingWorkflowTransitions.findMany({
        where: and(
          eq(recruitingWorkflowTransitions.workflowId, requisition.workflowId),
          eq(recruitingWorkflowTransitions.fromStageId, currentStageRecord.id)
        ),
      });

      const availableTransitions = transitions.map((t: any) => {
        const toStage = allStages.find((s: any) => s.id === t.toStageId);
        return {
          id: t.id,
          toStageKey: toStage?.stageKey || "",
          toStageDisplayName: toStage?.displayName || "",
          name: t.name || toStage?.displayName || "",
          requiresReason: t.requiresReason || false,
          toStageColor: toStage?.color || null,
          toStageIcon: toStage?.icon || null,
        };
      }).filter((t: any) => t.toStageKey);

      const stagesInfo = allStages.map((s: any) => ({
        stageKey: s.stageKey,
        displayName: s.displayName,
        sortOrder: s.sortOrder,
        isInitial: s.isInitial,
        isTerminal: s.isTerminal,
        color: s.color,
        icon: s.icon,
      }));

      res.json({ transitions: availableTransitions, stages: stagesInfo, currentStage: application.currentStage });
    } catch (error) {
      console.error("[Recruiting] Error fetching available transitions:", error);
      res.status(500).json({ message: "Failed to fetch available transitions" });
    }
  });


  // POST /api/recruiting/applications/:id/transition - Transition application stage
  app.post("/api/recruiting/applications/:id/transition", async (req: Request, res: Response) => {
    try {
      const _obsStart = Date.now();
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });

      const { toStage, reason, lastKnownUpdatedAt, adminOverride } = req.body;
      if (!toStage) {
        return res.status(400).json({ message: "toStage is required" });
      }

      const { enforceApplicationLock } = await import("./recruitingService");
      const lockResult = await enforceApplicationLock(req.params.id, userId);
      if (!lockResult.allowed) {
        return res.status(409).json({
          message: "Application is locked by another user",
          conflict: lockResult.conflict,
        });
      }

      if (lastKnownUpdatedAt) {
        const { checkConcurrencyConflict } = await import("./recruitingService");
        const conflictResult = await checkConcurrencyConflict(req.params.id, lastKnownUpdatedAt);
        if (conflictResult.conflict) {
          return res.status(409).json({
            message: "Application has been modified since your last load. Please refresh and try again.",
            currentUpdatedAt: conflictResult.currentUpdatedAt,
          });
        }
      }

      // Check compliance before allowing stage transition
      const complianceCheck = await checkStageTransitionAllowed(req.params.id, toStage);
      if (!complianceCheck.allowed) {
        return res.status(400).json({ 
          message: complianceCheck.blockedReason || "Stage transition blocked by compliance rules",
          complianceBlocked: true,
          failedChecks: complianceCheck.failedChecks
        });
      }

      // Check data quality validation rules before allowing stage transition
      const dataQuality = await evaluateDataQuality(req.params.id, toStage, userId);
      if (!dataQuality.passed) {
        return res.status(400).json({
          message: dataQuality.blockingFailures[0]?.message || "Stage transition blocked by data quality rules",
          dataQualityBlocked: true,
          dataQualityScore: dataQuality.score,
          blockingFailures: dataQuality.blockingFailures,
          warnings: dataQuality.warnings,
        });
      }

      const isAdmin = user?.role === 'admin' || user?.role === 'super_admin' || user?.role === 'super_user' || user?.role === 'recruiting_admin';
      const allowOverride = adminOverride && isAdmin;

      // Check required document completeness before allowing stage transition
      if (!allowOverride) {
        const appForDocCheck = await db.query.recruitingApplications.findFirst({
          where: eq(recruitingApplications.id, req.params.id),
          with: { requisition: true },
        });
        if (appForDocCheck?.requisition?.blockStageIfDocsIncomplete) {
          const reqTypes: string[] = (appForDocCheck.requisition.requiredDocumentTypes as string[]) || [];
          if (reqTypes.length > 0) {
            const docReqs = await db.select()
              .from(candidateDocumentRequests)
              .where(eq(candidateDocumentRequests.applicationId, req.params.id));
            const uploadedTypes = new Set(
              docReqs
                .filter(d => d.uploadedFileName && d.status !== 'rejected')
                .map(d => d.documentType)
            );
            const missingDocs = reqTypes.filter(t => !uploadedTypes.has(t));
            if (missingDocs.length > 0) {
              return res.status(400).json({
                message: `Required documents incomplete: missing ${missingDocs.join(', ')}`,
                docsIncomplete: true,
                missingDocuments: missingDocs,
                totalRequired: reqTypes.length,
                totalUploaded: reqTypes.length - missingDocs.length,
              });
            }
          }
        }
      }

      // Check requisition stage rules — readiness gate
      if (!allowOverride) {
        try {
          const appForGate = await db.query.recruitingApplications.findFirst({
            where: eq(recruitingApplications.id, req.params.id),
          });
          if (appForGate) {
            const stageRule = await db.query.requisitionStageRules.findFirst({
              where: and(
                eq(requisitionStageRules.requisitionId, appForGate.requisitionId),
                eq(requisitionStageRules.stageName, toStage)
              ),
            });
            if (stageRule?.requiresReadiness && appForGate.readinessStatus !== "ready") {
              return res.status(400).json({
                message: "Application is not Ready. Missing required documents.",
                readinessBlocked: true,
                readinessStatus: appForGate.readinessStatus,
                targetStage: toStage,
              });
            }
          }
        } catch (gateErr) {
          console.error("[Recruiting] Error checking stage readiness gate:", gateErr);
        }
      }

      // PRE-OFFER GATE (Ticket 15) — block advance to approved/ready_to_work without explicit pre-offer approval
      const PRE_OFFER_GUARDED_STAGES = ["approved", "ready_to_work"];
      if (!allowOverride && PRE_OFFER_GUARDED_STAGES.includes(toStage)) {
        try {
          const [appForOfferGate] = await db.select({
            preOfferDecision: (recruitingApplications as any).preOfferDecision,
          }).from(recruitingApplications).where(eq(recruitingApplications.id, req.params.id)).limit(1);
          if (!appForOfferGate || (appForOfferGate as any).preOfferDecision !== "approved_for_offer") {
            return res.status(400).json({
              message: "Pre-offer approval is required before advancing to this stage. A recruiter must record an Approve for Offer decision first.",
              preOfferGateBlocked: true,
              targetStage: toStage,
            });
          }
        } catch (offerGateErr) {
          console.error("[Recruiting] Error checking pre-offer gate:", offerGateErr);
        }
      }

      const { transitionApplicationStage } = await import("./recruitingService");
      const application = await transitionApplicationStage(
        req.params.id,
        toStage,
        userId,
        user?.email || null,
        reason,
        allowOverride
      );

      // Re-evaluate compliance after transition
      await evaluateComplianceChecks(req.params.id);


      // Auto-generate recruiter tasks for this transition
      try {
        const { generateAutoTasksForTransition } = await import("./services/recruitingTaskService");
        await generateAutoTasksForTransition(
          req.params.id,
          toStage,
          application.ownerId || null,
          userId,
        );
      } catch (taskErr) {
        console.error("[Recruiting] Error generating auto tasks:", taskErr);
      }
      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "stage_transition",
        status: "success",
        userId,
        applicationId: req.params.id,
        latencyMs: Date.now() - _obsStart,
        route: req.path,
        method: req.method,
        metadata: { fromStage: application.stage, toStage },
      });
      res.json(application);
    } catch (error: any) {
      console.error("[Recruiting] Error transitioning application:", error);
      if (error.message?.includes("Invalid stage transition")) {
        return res.status(400).json({ message: error.message });
      }
      if (error.message?.includes("Reason is required")) {
        return res.status(400).json({ message: error.message, reasonRequired: true });
      }
      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "stage_transition",
        status: "error",
        severity: "error",
        applicationId: req.params.id,
        latencyMs: Date.now() - _obsStart,
        errorCode: error.code || "TRANSITION_ERROR",
        errorMessage: error.message?.slice(0, 500),
        route: req.path,
        method: req.method,
        metadata: { toStage: req.body?.toStage },
      });
      res.status(500).json({ message: "Failed to transition application" });
    }
  });

