  // POST /api/recruiting/applications/:id/override-red-flag
  app.post("/api/recruiting/applications/:applicationId/override-red-flag", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { applicationId } = req.params;
      const { flagType, overrideNote } = req.body;
      if (!flagType || typeof flagType !== "string") return res.status(400).json({ message: "flagType is required" });
      const { recruitingApplications: rApps } = await import("../shared/schema");
      const [app] = await db.select({ redFlagOverrides: rApps.redFlagOverrides }).from(rApps).where(eq(rApps.id, applicationId)).limit(1);
      if (!app) return res.status(404).json({ message: "Application not found" });
      const existing = Array.isArray(app.redFlagOverrides) ? (app.redFlagOverrides as any[]) : [];
      const filtered = existing.filter((o: any) => o.flagType !== flagType);
      filtered.push({ flagType, overriddenBy: userId, overrideNote: overrideNote || "", overriddenAt: new Date().toISOString() });
      await db.update(rApps).set({ redFlagOverrides: filtered as any } as any).where(eq(rApps.id, applicationId));
      res.json({ success: true, overrides: filtered });
    } catch (error: any) {
      res.status(500).json({ message: "Failed to save red flag override" });
    }
  });

