  // PUT /api/recruiting/candidates/:id/availability - Create or update availability
  app.put("/api/recruiting/candidates/:id/availability", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });

      if (!user || !['admin', 'recruiter', 'corporate'].includes(user.role || '')) {
        return res.status(403).json({ message: "Only recruiters and admins can update availability" });
      }

      const candidateId = req.params.id;
      const { daysOfWeek, timeWindows, preferredShiftType, maxHoursPerWeek, minHoursPerWeek, preferredStartTime, notes } = req.body;

      // Check if candidate exists
      const candidate = await db.query.recruitingCandidates.findFirst({
        where: (t, { eq }) => eq(t.id, candidateId),
      });

      if (!candidate) {
        return res.status(404).json({ message: "Candidate not found" });
      }

      // Check if availability record exists
      const existing = await db.query.recruitingAvailability.findFirst({
        where: (t, { eq }) => eq(t.candidateId, candidateId),
      });

      const availabilityData = {
        daysOfWeek: daysOfWeek || [],
        timeWindows: timeWindows || [],
        preferredShiftType: preferredShiftType || 'both',
        maxHoursPerWeek: maxHoursPerWeek || null,
        minHoursPerWeek: minHoursPerWeek || null,
        preferredStartTime: preferredStartTime || null,
        notes: notes || null,
        lastUpdatedBy: userId,
        lastUpdatedByEmail: user.email,
        updatedAt: new Date(),
      };

      // Detect availability changes for alert generation
      const availFieldsToCompare = ['daysOfWeek', 'timeWindows', 'preferredShiftType', 'maxHoursPerWeek', 'minHoursPerWeek', 'preferredStartTime', 'notes'];
      const changedAvailFields = [];
      if (existing) {
        for (const field of availFieldsToCompare) {
          const oldVal = JSON.stringify(existing[field] ?? null);
          const newVal = JSON.stringify(availabilityData[field] ?? null);
          if (oldVal !== newVal) {
            changedAvailFields.push(field);
          }
        }
      }

      let result;
      if (existing) {
        [result] = await db.update(recruitingAvailability)
          .set(availabilityData)
          .where(eq(recruitingAvailability.candidateId, candidateId))
          .returning();
      } else {
        [result] = await db.insert(recruitingAvailability)
          .values({ ...availabilityData, candidateId })
          .returning();
      }

      // If availability changed on existing record, check for ready applications and create alerts
      if (existing && changedAvailFields.length > 0) {
        try {
          const readyApps = await db.query.recruitingApplications.findMany({
            where: (t, { eq: eq2, and: and2 }) => and2(
              eq2(t.candidateId, candidateId),
              eq2(t.readinessStatus, 'ready')
            ),
          });

          const previousSnapshot = {
            daysOfWeek: existing.daysOfWeek,
            timeWindows: existing.timeWindows,
            preferredShiftType: existing.preferredShiftType,
            maxHoursPerWeek: existing.maxHoursPerWeek,
            minHoursPerWeek: existing.minHoursPerWeek,
            preferredStartTime: existing.preferredStartTime,
            notes: existing.notes,
          };
          const newSnapshot = {
            daysOfWeek: availabilityData.daysOfWeek,
            timeWindows: availabilityData.timeWindows,
            preferredShiftType: availabilityData.preferredShiftType,
            maxHoursPerWeek: availabilityData.maxHoursPerWeek,
            minHoursPerWeek: availabilityData.minHoursPerWeek,
            preferredStartTime: availabilityData.preferredStartTime,
            notes: availabilityData.notes,
          };

          for (const app of readyApps) {
            await db.update(recruitingApplications)
              .set({ readinessStatus: 'in_review' })
              .where(eq(recruitingApplications.id, app.id));

            await db.insert(recruitingAvailabilityAlerts).values({
              candidateId,
              applicationId: app.id,
              previousAvailability: previousSnapshot,
              newAvailability: newSnapshot,
              changedFields: changedAvailFields,
              previousReadinessStatus: 'ready',
              newReadinessStatus: 'in_review',
              status: 'open',
              triggeredBy: userId,
              triggeredByEmail: user.email || null,
            });

            await db.insert(recruitingAuditEvents).values({
              actionType: 'AVAILABILITY_CHANGED',
              entityType: 'application',
              entityId: app.id,
              userId,
              userEmail: user.email,
              actorRole: user.role || 'unknown',
              source: 'ui',
              previousValue: JSON.stringify(previousSnapshot),
              newValue: JSON.stringify(newSnapshot),
              changedFields: changedAvailFields,
              reason: 'Availability updated on ready candidate; readiness downgraded to in_review',
              metadata: { candidateId, applicationId: app.id, alertGenerated: true },
            });

            await db.insert(recruitingAuditEvents).values({
              actionType: 'readiness.changed',
              entityType: 'application',
              entityId: app.id,
              userId,
              userEmail: user.email,
              actorRole: user.role || 'unknown',
              source: 'system',
              previousValue: JSON.stringify({ readinessStatus: 'ready' }),
              newValue: JSON.stringify({ readinessStatus: 'in_review' }),
              changedFields: ['readinessStatus'],
              reason: 'Availability change triggered readiness downgrade',
              metadata: { previous_status: 'ready', new_status: 'in_review', reason_summary: 'Candidate availability changed while in Ready status' },
            });
          }

          if (readyApps.length > 0) {
            console.log(`[Recruiting] Availability change alerts created for ${readyApps.length} ready application(s) of candidate ${candidateId}`);
          }
        } catch (alertError) {
          console.error("[Recruiting] Error creating availability change alerts:", alertError);
        }
      }

      res.json(result);
    } catch (error) {
      console.error("[Recruiting] Error updating availability:", error);
      res.status(500).json({ message: "Failed to update availability" });
    }
  });

