  // GET /api/recruiting/availability-alerts - Get all open alerts
  app.get("/api/recruiting/availability-alerts", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const user = await db.query.users.findFirst({ where: (u, { eq: eq2 }) => eq2(u.id, userId) });
      if (!user || !['admin', 'recruiter', 'corporate'].includes(user.role || '')) {
        return res.status(403).json({ message: "Not authorized" });
      }

      const statusFilter = (req.query.status as string) || 'open';
      const alerts = await db.query.recruitingAvailabilityAlerts.findMany({
        where: (t, { eq: eq2 }) => eq2(t.status, statusFilter),
        orderBy: (t, { desc: desc2 }) => [desc2(t.createdAt)],
      });

      res.json(alerts);
    } catch (error) {
      console.error("[Recruiting] Error fetching availability alerts:", error);
      res.status(500).json({ message: "Failed to fetch availability alerts" });
    }
  });

