  // PATCH /api/recruiting/availability-alerts/:id/resolve - Resolve an alert
  app.patch("/api/recruiting/availability-alerts/:id/resolve", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const user = await db.query.users.findFirst({ where: (u, { eq: eq2 }) => eq2(u.id, userId) });
      if (!user || !['admin', 'recruiter', 'corporate'].includes(user.role || '')) {
        return res.status(403).json({ message: "Not authorized" });
      }

      const { resolutionNote, restoreReadiness } = req.body;

      const alert = await db.query.recruitingAvailabilityAlerts.findFirst({
        where: (t, { eq: eq2 }) => eq2(t.id, req.params.id),
      });

      if (!alert) return res.status(404).json({ message: "Alert not found" });
      if (alert.status === 'resolved') return res.status(400).json({ message: "Alert already resolved" });

      const [updated] = await db.update(recruitingAvailabilityAlerts)
        .set({
          status: 'resolved',
          resolvedAt: new Date(),
          resolvedBy: userId,
          resolvedByEmail: user.email || null,
          resolutionNote: resolutionNote || null,
        })
        .where(eq(recruitingAvailabilityAlerts.id, req.params.id))
        .returning();

      // Optionally restore readiness to ready
      if (restoreReadiness) {
        await db.update(recruitingApplications)
          .set({ readinessStatus: 'ready' })
          .where(eq(recruitingApplications.id, alert.applicationId));
      }

      // Audit the resolution
      await db.insert(recruitingAuditEvents).values({
        actionType: 'AVAILABILITY_ALERT_RESOLVED',
        entityType: 'application',
        entityId: alert.applicationId,
        userId,
        userEmail: user.email,
        actorRole: user.role || 'unknown',
        source: 'ui',
        previousValue: JSON.stringify({ status: 'open' }),
        newValue: JSON.stringify({ status: 'resolved', restoreReadiness: !!restoreReadiness }),
        changedFields: ['alertStatus'],
        reason: resolutionNote || 'Alert resolved by recruiter',
        metadata: { alertId: alert.id, candidateId: alert.candidateId, restoreReadiness: !!restoreReadiness },
      });

      if (restoreReadiness) {
        await db.insert(recruitingAuditEvents).values({
          actionType: 'readiness.changed',
          entityType: 'application',
          entityId: alert.applicationId,
          userId,
          userEmail: user.email,
          actorRole: user.role || 'unknown',
          source: 'ui',
          previousValue: JSON.stringify({ readinessStatus: 'in_review' }),
          newValue: JSON.stringify({ readinessStatus: 'ready' }),
          changedFields: ['readinessStatus'],
          reason: resolutionNote || 'Readiness restored after availability alert resolution',
          metadata: { previous_status: 'in_review', new_status: 'ready', reason_summary: 'Availability alert resolved; readiness restored by recruiter' },
        });
      }

      res.json(updated);
    } catch (error) {
      console.error("[Recruiting] Error resolving availability alert:", error);
      res.status(500).json({ message: "Failed to resolve alert" });
    }
  });

