  // POST /api/recruiting/apply/:requisitionId - Public apply endpoint
  app.post("/api/recruiting/apply/:requisitionId", async (req: Request, res: Response) => {
    try {
      const _obsStart = Date.now();
      const { requisitionId } = req.params;
      const { firstName, lastName, email, phone, city, state, notes, consentSms, consentEmail } = req.body;

      if (!firstName || !lastName || !email) {
        return res.status(400).json({ message: "firstName, lastName, and email are required" });
      }

      const { 
        createCandidate, 
        findCandidateByEmailOrPhone, 
        createApplication, 
        getRequisition 
      } = await import("./recruitingService");

      const requisition = await getRequisition(requisitionId);
      if (!requisition) {
        return res.status(404).json({ message: "Requisition not found" });
      }

      if (requisition.status !== 'open') {
        return res.status(400).json({ message: "This position is not currently accepting applications" });
      }

      let candidate = await findCandidateByEmailOrPhone(email, phone);
      
      if (!candidate) {
        candidate = await createCandidate({
          firstName,
          lastName,
          email,
          phone,
          city,
          state,
          notes,
          source: 'website',
        }, null, null);
      }

      const application = await createApplication({
        candidateId: candidate.id,
        requisitionId,
        internalNotes: consentSms ? 'Consented to SMS' : undefined,
      }, null, null);

      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "apply_submit",
        status: "success",
        requisitionId,
        candidateId: candidate.id,
        applicationId: application.id,
        latencyMs: Date.now() - _obsStart,
        route: req.path,
        method: req.method,
      });
      res.status(201).json({ 
        success: true, 
        applicationId: application.id,
        message: "Application submitted successfully" 
      });
    } catch (error: any) {
      console.error("[Recruiting] Error processing application:", error);
      if (error.message?.includes("already exists")) {
        return res.status(400).json({ message: "You have already applied for this position" });
      }
      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "apply_submit",
        status: "error",
        severity: "error",
        requisitionId: req.params.requisitionId,
        latencyMs: Date.now() - _obsStart,
        errorCode: error.code || "APPLY_ERROR",
        errorMessage: error.message?.slice(0, 500),
        route: req.path,
        method: req.method,
      });
      res.status(500).json({ message: "Failed to submit application" });
    }
  });

