  // PATCH /api/recruiting/applications/:id/source — Update source attribution (Ticket 23)
  app.patch("/api/recruiting/applications/:id/source", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { recruitingApplications } = await import("../shared/schema");
      const { source, sourceDetails } = req.body;
      const updates: Record<string, any> = {};
      if (source !== undefined) updates.source = source || null;
      if (sourceDetails !== undefined) updates.sourceDetails = sourceDetails || null;
      if (Object.keys(updates).length === 0) return res.status(400).json({ message: "No update fields provided" });

      await db.update(recruitingApplications).set(updates).where(eq(recruitingApplications.id, req.params.id));
      const [updated] = await db.select({ source: recruitingApplications.source, sourceDetails: recruitingApplications.sourceDetails })
        .from(recruitingApplications).where(eq(recruitingApplications.id, req.params.id)).limit(1);
      res.json(updated);
    } catch (err: any) {
      console.error("[PATCH application source]", err);
      res.status(500).json({ message: "Failed to update source", detail: err?.message });
    }
  });

  // PATCH /api/recruiting/applications/:id/readiness - Update readiness inputs
  app.patch("/api/recruiting/applications/:id/readiness", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });

      const { enforceApplicationLock: enforceReadinessLock } = await import("./recruitingService");
      const readinessLockResult = await enforceReadinessLock(req.params.id, userId);
      if (!readinessLockResult.allowed) {
        return res.status(409).json({
          message: "Application is locked by another user",
          conflict: readinessLockResult.conflict,
        });
      }

      const { consentCaptured, docsComplete, backgroundCheckStatus, lastContactedAt, lastResponseAt } = req.body;

      const { updateReadinessInputs } = await import("./recruitingService");
      const application = await updateReadinessInputs(
        req.params.id,
        {
          consentCaptured,
          docsComplete,
          backgroundCheckStatus,
          lastContactedAt: lastContactedAt ? new Date(lastContactedAt) : undefined,
          lastResponseAt: lastResponseAt ? new Date(lastResponseAt) : undefined,
        },
        userId,
        user?.email || null
      );

      if (!application) {
        return res.status(404).json({ message: "Application not found" });
      }

      // Trigger readiness regression check for background status changes
      if (backgroundCheckStatus && (backgroundCheckStatus === "failed" || backgroundCheckStatus === "expired")) {
        try {
          const { onBackgroundStatusChanged } = await import("./services/readinessRegressionService");
          await onBackgroundStatusChanged(req.params.id, backgroundCheckStatus, userId, user?.email || "");
        } catch (regressionErr) {
          console.error("[Regression] Error triggering background regression:", regressionErr);
        }
      }

      res.json(application);
    } catch (error) {
      console.error("[Recruiting] Error updating readiness inputs:", error);
      res.status(500).json({ message: "Failed to update readiness inputs" });
    }
  });

