  // GET /api/recruiting/screening-requests/overdue — Identify applications with stalled screenings (Ticket 13)
  app.get("/api/recruiting/screening-requests/overdue", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      // SLA thresholds (calendar days from triggered_at for non-terminal statuses)
      const SLA_WARN: Record<string, number> = { mvr: 3, background_check: 5, drug_test: 2 };
      const SLA_OVERDUE: Record<string, number> = { mvr: 5, background_check: 7, drug_test: 4 };
      const TERMINAL = ["clear", "completed", "flagged", "failed", "waived", "not_started"];

      // Fetch all active (non-terminal) screening requests with age data
      const rawResult = await db.execute(sql`
        SELECT
          id,
          application_id,
          screening_type,
          status,
          triggered_at,
          updated_at,
          EXTRACT(EPOCH FROM (NOW() - triggered_at)) / 86400 AS days_since_triggered,
          EXTRACT(EPOCH FROM (NOW() - COALESCE(updated_at, triggered_at))) / 86400 AS days_since_updated
        FROM recruiting_screening_requests
        WHERE status NOT IN ('clear', 'completed', 'flagged', 'failed', 'waived', 'not_started')
        ORDER BY triggered_at ASC
      `);
      const rows = ((rawResult as any).rows ?? rawResult) as any[];

      const details: any[] = [];
      const overdueAppIds = new Set<string>();
      const warningAppIds = new Set<string>();

      for (const row of rows) {
        const type = row.screening_type as string;
        const daysSince = Math.floor(parseFloat(row.days_since_triggered));
        const daysSinceUpdate = Math.floor(parseFloat(row.days_since_updated));
        const warnDays = SLA_WARN[type] ?? 3;
        const overdueDays = SLA_OVERDUE[type] ?? 5;
        const isOverdue = daysSince >= overdueDays;
        const isWarning = !isOverdue && daysSince >= warnDays;

        details.push({
          id: row.id,
          applicationId: row.application_id,
          screeningType: type,
          status: row.status,
          triggeredAt: row.triggered_at,
          daysSince,
          daysSinceUpdate,
          warnDays,
          overdueDays,
          isOverdue,
          isWarning,
        });

        if (isOverdue) overdueAppIds.add(row.application_id);
        else if (isWarning) warningAppIds.add(row.application_id);
      }

      res.json({
        overdueApplicationIds: Array.from(overdueAppIds),
        warningApplicationIds: Array.from(warningAppIds),
        details,
        thresholds: {
          mvr: { warnDays: SLA_WARN.mvr, overdueDays: SLA_OVERDUE.mvr },
          background_check: { warnDays: SLA_WARN.background_check, overdueDays: SLA_OVERDUE.background_check },
          drug_test: { warnDays: SLA_WARN.drug_test, overdueDays: SLA_OVERDUE.drug_test },
        },
        generatedAt: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error("[ScreeningSLA] Error:", error);
      res.status(500).json({ message: "Failed to fetch overdue screening requests" });
    }
  });

  // GET /api/recruiting/applications/:applicationId/screening-requests — List screening requests
