  // POST /api/recruiting/applications/:applicationId/screening-requests/start — Manually create/upsert a screening request (Ticket 12)
  app.post("/api/recruiting/applications/:applicationId/screening-requests/start", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { screeningType } = req.body;
      const VALID_TYPES = ["mvr", "background_check", "drug_test"];
      if (!screeningType || !VALID_TYPES.includes(screeningType)) {
        return res.status(400).json({ message: `screeningType must be one of: ${VALID_TYPES.join(", ")}` });
      }
      // Check if a non-failed record already exists
      const existing = await db.select()
        .from(recruitingScreeningRequests)
        .where(eq(recruitingScreeningRequests.applicationId, req.params.applicationId))
        .then(rows => rows.find(r => r.screeningType === screeningType && r.status !== "failed"));
      if (existing) return res.json(existing); // Idempotent — return existing
      const initialStatus = screeningType === "drug_test" ? "scheduled" : "pending";
      const [created] = await db.insert(recruitingScreeningRequests).values({
        applicationId: req.params.applicationId,
        screeningType,
        status: initialStatus,
        triggeredAt: new Date(),
        triggeredBy: userId,
        triggeredByDecision: "manual",
        notes: "Manually started by recruiter.",
      } as any).returning();
      await db.insert(recruitingAuditEvents).values({
        actionType: "screening_manually_started",
        entityType: "application",
        entityId: req.params.applicationId,
        userId,
        source: "ui",
        newValue: JSON.stringify({ screeningType, status: initialStatus }),
        changedFields: ["status"],
        metadata: { screeningRequestId: created.id, screeningType },
      });
      res.status(201).json(created);
    } catch (error: any) {
      console.error("[ScreeningRequests] Manual start error:", error);
      res.status(500).json({ message: "Failed to create screening request" });
    }
  });

  // PATCH /api/recruiting/screening-requests/:id/status — Update status/result of a screening request
  app.patch("/api/recruiting/screening-requests/:id/status", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      // Expanded taxonomy: generic + type-specific statuses (Ticket 12)
      const VALID_STATUSES = [
        "not_started", "pending", "requested", "scheduled",
        "in_progress", "clear", "completed", "failed", "flagged", "waived",
      ];
      const VALID_RESULTS = ["pass", "fail", "clear", "flagged", "pending", "waived"];
      const { status, result, resultNotes, notes } = req.body;
      if (!status || !VALID_STATUSES.includes(status)) {
        return res.status(400).json({ message: `status must be one of: ${VALID_STATUSES.join(", ")}` });
      }
      if (result && !VALID_RESULTS.includes(result)) {
        return res.status(400).json({ message: `result must be one of: ${VALID_RESULTS.join(", ")}` });
      }
      const now = new Date();
      const isCompleted = ["completed", "failed", "flagged", "clear", "waived"].includes(status);
      const [updated] = await db.update(recruitingScreeningRequests).set({
        status,
        ...(result ? { result } : {}),
        ...(resultNotes ? { resultNotes } : {}),
        ...(notes ? { notes } : {}),
        ...(isCompleted ? { completedAt: now, completedBy: userId } : {}),
        updatedAt: now,
      } as any).where(eq(recruitingScreeningRequests.id, req.params.id)).returning();
      if (!updated) return res.status(404).json({ message: "Screening request not found" });
      // Audit the update
      await db.insert(recruitingAuditEvents).values({
        actionType: "screening_status_updated",
        entityType: "application",
        entityId: updated.applicationId,
        userId,
        source: "ui",
        newValue: JSON.stringify({ status, result, screeningType: updated.screeningType }),
        changedFields: ["status", ...(result ? ["result"] : [])],
        metadata: { screeningRequestId: req.params.id, screeningType: updated.screeningType },
      });

      // ── Auto-trigger AI Screening Review (Ticket 14) ──────────────────────
      // Fire-and-forget: if all 3 screening types now have terminal results,
      // generate the AI review summary for recruiter decision support.
      const TERMINAL = new Set(["clear", "completed", "failed", "flagged", "waived"]);
      if (TERMINAL.has(status)) {
        try {
          const { allScreeningsHaveResults, runScreeningReview } = await import("./services/screeningReviewService");
          const allRequests = await db
            .select({ screeningType: recruitingScreeningRequests.screeningType, status: recruitingScreeningRequests.status })
            .from(recruitingScreeningRequests)
            .where(eq(recruitingScreeningRequests.applicationId, updated.applicationId));
          if (allScreeningsHaveResults(allRequests)) {
            console.log(`[ScreeningReview] All screenings done for ${updated.applicationId} — triggering AI review`);
            runScreeningReview(updated.applicationId).catch((e) =>
              console.error("[ScreeningReview] Auto-trigger error:", e)
            );
          }
        } catch (importErr) {
          console.error("[ScreeningReview] Import error:", importErr);
        }
      }

      res.json(updated);
    } catch (error: any) {
      console.error("[ScreeningRequests] Update error:", error);
      res.status(500).json({ message: "Failed to update screening request" });
    }
  });

  // POST /api/recruiting/applications/:applicationId/screening-review/generate — Manually trigger AI review (Ticket 14)
  app.post("/api/recruiting/applications/:applicationId/screening-review/generate", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const { applicationId } = req.params;

      // Verify application exists
      const [app] = await db
        .select({ id: recruitingApplications.id, aiScreeningReviewGenerating: recruitingApplications.aiScreeningReviewGenerating } as any)
        .from(recruitingApplications)
        .where(eq(recruitingApplications.id, applicationId))
        .limit(1);

      if (!app) return res.status(404).json({ message: "Application not found" });
      if ((app as any).aiScreeningReviewGenerating) {
        return res.status(409).json({ message: "AI review is already generating for this application" });
      }

      // Fire-and-forget
      const { runScreeningReview } = await import("./services/screeningReviewService");
      runScreeningReview(applicationId).catch((e) =>
        console.error("[ScreeningReview] Manual generate error:", e)
      );

      res.json({ message: "AI screening review generation started", applicationId });
    } catch (error: any) {
      console.error("[ScreeningReview] Generate endpoint error:", error);
      res.status(500).json({ message: "Failed to start AI screening review" });
    }
  });

