  // ── CHANNEL DISTRIBUTION PLANNER ENDPOINTS (Ticket 18) ───────────────────

  // Channel postings are Recruiting job postings. Resolve their requisition from
  // server-owned records before checking the established permission + market scope;
  // never trust a client-supplied requisition, campaign, role, or permission.
  async function authorizeChannelPostingRequest(
    req: Request,
    permission: "read" | "write",
    target: { requisitionId?: string; postingId?: string },
  ) {
    const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
    if (!userId) {
      return { allowed: false as const, status: 401, message: "Not authenticated" };
    }
    const user = await storage.getUser(userId);
    if (!user) {
      return { allowed: false as const, status: 401, message: "Not authenticated" };
    }

    const { recruitingChannelPostings, recruitingRequisitions } = await import("../shared/schema");
    let posting: any = null;
    let requisitionId = target.requisitionId;
    if (target.postingId) {
      [posting] = await db.select()
        .from(recruitingChannelPostings)
        .where(eq(recruitingChannelPostings.id, target.postingId))
        .limit(1);
      if (!posting) {
        return { allowed: false as const, status: 404, message: "Posting not found" };
      }
      requisitionId = posting.requisitionId;
    }

    if (!requisitionId) {
      return { allowed: false as const, status: 404, message: "Requisition not found" };
    }
    const [requisition] = await db.select({
      id: recruitingRequisitions.id,
      market: recruitingRequisitions.market,
    })
      .from(recruitingRequisitions)
      .where(eq(recruitingRequisitions.id, requisitionId))
      .limit(1);
    if (!requisition) {
      return { allowed: false as const, status: 404, message: "Requisition not found" };
    }

    const recruitingContext = await getUserRecruitingContext(user.id, user.role || "");
    if (!hasRecruitingRecordAccess(recruitingContext, permission, requisition.market)) {
      return { allowed: false as const, status: 403, message: "Forbidden: insufficient Recruiting permissions" };
    }
    return { allowed: true as const, user, requisition, posting };
  }

  // GET /api/recruiting/requisitions/:id/channel-postings
  app.get("/api/recruiting/requisitions/:id/channel-postings", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const authorization = await authorizeChannelPostingRequest(req, "read", { requisitionId: req.params.id });
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const { recruitingChannelPostings } = await import("../shared/schema");
      const postings = await db
        .select()
        .from(recruitingChannelPostings)
        .where(eq(recruitingChannelPostings.requisitionId, req.params.id))
        .orderBy(asc(recruitingChannelPostings.createdAt));
      res.json(postings);
    } catch (error: any) {
      console.error("[ChannelPostings] GET error:", error);
      res.status(500).json({ message: "Failed to fetch channel postings" });
    }
  });

  // POST /api/recruiting/requisitions/:id/channel-postings — add channel
  app.post("/api/recruiting/requisitions/:id/channel-postings", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeChannelPostingRequest(req, "write", { requisitionId: req.params.id });
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const { channel, status = "planned", launchDate, endDate, postingUrl, notes, budgetAmount } = req.body;
      if (!channel) return res.status(400).json({ message: "channel is required" });
      const { recruitingChannelPostings } = await import("../shared/schema");
      const now = new Date();
      const [posting] = await db.insert(recruitingChannelPostings).values({
        requisitionId: req.params.id,
        channel,
        status,
        launchDate: launchDate || null,
        endDate: endDate || null,
        postingUrl: postingUrl || null,
        notes: notes || null,
        budgetAmount: budgetAmount ? String(budgetAmount) : null,
        createdBy: userId,
        updatedBy: userId,
        createdAt: now,
        updatedAt: now,
      } as any).returning();
      res.status(201).json(posting);
    } catch (error: any) {
      if (error.code === "23505") {
        return res.status(409).json({ message: "This channel is already added to the plan." });
      }
      console.error("[ChannelPostings] POST error:", error);
      res.status(500).json({ message: "Failed to add channel posting" });
    }
  });

  // PATCH /api/recruiting/channel-postings/:postingId — update status/details/ad
  app.patch("/api/recruiting/channel-postings/:postingId", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeChannelPostingRequest(req, "write", { postingId: req.params.postingId });
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const { recruitingChannelPostings } = await import("../shared/schema");
      const { status, launchDate, endDate, postingUrl, notes, budgetAmount, adBody, markReviewed } = req.body;
      const now = new Date();
      const updates: Record<string, any> = { updatedAt: now, updatedBy: userId };
      if (status !== undefined) updates.status = status;
      if (launchDate !== undefined) updates.launchDate = launchDate || null;
      if (endDate !== undefined) updates.endDate = endDate || null;
      if (postingUrl !== undefined) updates.postingUrl = postingUrl || null;
      if (notes !== undefined) updates.notes = notes || null;
      if (budgetAmount !== undefined) updates.budgetAmount = budgetAmount ? String(budgetAmount) : null;
      if (adBody !== undefined) updates.adBody = adBody || null;
      if (markReviewed === true) {
        updates.adReviewedAt = now;
        updates.adReviewedBy = userId;
      } else if (markReviewed === false) {
        updates.adReviewedAt = null;
        updates.adReviewedBy = null;
      }
      const [updated] = await db
        .update(recruitingChannelPostings)
        .set(updates)
        .where(eq(recruitingChannelPostings.id, req.params.postingId))
        .returning();
      if (!updated) return res.status(404).json({ message: "Posting not found" });
      res.json(updated);
    } catch (error: any) {
      console.error("[ChannelPostings] PATCH error:", error);
      res.status(500).json({ message: "Failed to update channel posting" });
    }
  });

