  app.post("/api/recruiting/requisitions/:id/channel-postings/bulk", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeChannelPostingRequest(req, "write", { requisitionId: req.params.id });
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const { recruitingChannelPostings } = await import("../shared/schema");
      const { channels } = req.body as { channels: string[] };
      if (!Array.isArray(channels) || channels.length === 0) {
        return res.status(400).json({ message: "channels array is required" });
      }
      const now = new Date();
      const inserted: any[] = [];
      for (const channel of channels) {
        try {
          const [row] = await db
            .insert(recruitingChannelPostings)
            .values({ requisitionId: req.params.id, channel, status: "planned", createdBy: userId, updatedAt: now, updatedBy: userId })
            .onConflictDoNothing()
            .returning();
          if (row) inserted.push(row);
        } catch (_) { /* skip duplicate */ }
      }
      res.json({ inserted, count: inserted.length });
    } catch (error: any) {
      console.error("[ChannelPostings] bulk POST error:", error);
      res.status(500).json({ message: "Failed to add channels" });
    }
  });

  // POST /api/recruiting/channel-postings/:id/auto-populate-ad — fill ad_body from draft
  app.post("/api/recruiting/channel-postings/:id/auto-populate-ad", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeChannelPostingRequest(req, "write", { postingId: req.params.id });
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const { recruitingChannelPostings, jobAdDrafts } = await import("../shared/schema");

      // Fetch the channel posting
      const [posting] = await db
        .select()
        .from(recruitingChannelPostings)
        .where(eq(recruitingChannelPostings.id, req.params.id));
      if (!posting) return res.status(404).json({ message: "Posting not found" });

      // Fetch the finalized/draft job ad for this requisition
      const [draft] = await db
        .select()
        .from(jobAdDrafts)
        .where(eq(jobAdDrafts.requisitionId, posting.requisitionId));

      let baseBody = draft?.body ?? "";

      // Channel-specific intro prepend
      const channelIntros: Record<string, string> = {
        "Indeed": "📋 APPLY ON INDEED — ",
        "Craigslist": "CRAIGSLIST JOB POSTING\n\n",
        "Facebook": "👋 Hey Facebook! We're Hiring!\n\n",
        "Facebook Groups": "📣 Posted to our local driver community groups:\n\n",
        "Monster": "NOW ON MONSTER.COM\n\n",
        "Instagram": "✨ Tap to apply — Instagram story link in bio.\n\n",
        "LinkedIn": "🔗 LinkedIn Opportunity:\n\n",
        "ZipRecruiter": "📌 Found on ZipRecruiter:\n\n",
        "Company Website": "Apply directly on our website:\n\n",
      };
      const intro = channelIntros[posting.channel] ?? "";
      const adBody = intro + baseBody;

      // Save back to posting
      const now = new Date();
      const [updated] = await db
        .update(recruitingChannelPostings)
        .set({ adBody, updatedAt: now, updatedBy: userId })
        .where(eq(recruitingChannelPostings.id, req.params.id))
        .returning();
      res.json(updated);
    } catch (error: any) {
      console.error("[ChannelPostings] auto-populate error:", error);
      res.status(500).json({ message: "Failed to auto-populate ad" });
    }
  });

