  // POST /api/recruiting/launch-plans — create + generate plan
  app.post("/api/recruiting/launch-plans", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const { name, market, customerName, customerId, customerStartDate, roleType, roleCounts, hoursRequirements } = req.body;
      if (!name || !market || !roleType) return res.status(400).json({ message: "name, market, and roleType are required" });

      const { marketLaunchPlans } = await import("../shared/schema");
      const { generateLaunchPlan } = await import("./services/launchPlannerService");

      // Insert draft record first
      const [plan] = await db.insert(marketLaunchPlans).values({
        name,
        market,
        customerId: customerId || null,
        customerName: customerName || null,
        customerStartDate: customerStartDate || null,
        roleType,
        roleCounts: roleCounts || {},
        hoursRequirements: hoursRequirements || {},
        status: "generating",
        createdBy: userId,
      }).returning();

      // Generate the plan asynchronously (don't block response)
      generateLaunchPlan({
        market,
        customerName: customerName || "New Customer",
        customerStartDate: customerStartDate || new Date().toISOString().split("T")[0],
        roleType,
        roleCounts: roleCounts || {},
        hoursRequirements: hoursRequirements || {},
      }).then(async (generatedPlan) => {
        await db.update(marketLaunchPlans)
          .set({ generatedPlan, status: "active", updatedAt: new Date() })
          .where(eq(marketLaunchPlans.id, plan.id));
      }).catch((err) => {
        console.error("[LaunchPlanner] Plan generation failed:", err);
        db.update(marketLaunchPlans)
          .set({ status: "draft", updatedAt: new Date() })
          .where(eq(marketLaunchPlans.id, plan.id));
      });

      res.status(201).json(plan);
    } catch (err) {
      console.error("[LaunchPlanner] Create error:", err);
      res.status(500).json({ message: "Failed to create launch plan" });
    }
  });

