  app.post("/api/recruiting/launch-plans/:id/forecast", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { marketLaunchPlans } = await import("../shared/schema");
      const [plan] = await db.select().from(marketLaunchPlans).where(eq(marketLaunchPlans.id, req.params.id)).limit(1);
      if (!plan) return res.status(404).json({ message: "Plan not found" });

      const { computeGoLiveForecast } = await import("./services/goLiveForecastService");
      const totalHeadcount = Object.values((plan.roleCounts as Record<string, number>) || {}).reduce((s, v) => s + v, 0);
      const forecast = await computeGoLiveForecast({
        market: plan.market,
        headcountTarget: totalHeadcount || 1,
        customerStartDate: plan.customerStartDate ?? null,
        roleType: plan.roleType,
      });

      await db.update(marketLaunchPlans)
        .set({ goLiveForecast: forecast as any, forecastComputedAt: new Date(), updatedAt: new Date() })
        .where(eq(marketLaunchPlans.id, req.params.id));

      res.json({ forecast });
    } catch (err: any) {
      console.error("[GoLiveForecast]", err);
      res.status(500).json({ message: "Failed to compute forecast", detail: err?.message });
    }
  });

