  // PATCH /api/scheduling/wheniwork/users/:id/integration-status — set ACTIVE_DRIVER | EXCLUDED_NON_DRIVER | PENDING_REVIEW
  app.patch("/api/scheduling/wheniwork/users/:id/integration-status", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const wiwUserId        = req.params.id;
      const { status: newStatus } = req.body as { status: string };
      const allowed = ["ACTIVE_DRIVER", "EXCLUDED_NON_DRIVER", "PENDING_REVIEW"];
      if (!allowed.includes(newStatus)) {
        return res.status(400).json({ message: `Invalid status. Must be one of: ${allowed.join(", ")}` });
      }
      await pool.query(
        `UPDATE wiw_users SET wiw_integration_status = $1, updated_at = NOW() WHERE id = $2`,
        [newStatus, wiwUserId]
      );
      res.json({ id: wiwUserId, wiwIntegrationStatus: newStatus });
    } catch (err: any) {
      console.error("[WIW] integration-status error:", err);
      res.status(500).json({ message: "Failed to update integration status", detail: err?.message });
    }
  });

