  // GET /api/scheduling/wheniwork/drivers-without-wiw
  // Returns active DriverHub drivers that have no WIW user linked (the "no WIW match" exception list)
  app.get("/api/scheduling/wheniwork/drivers-without-wiw", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const rows = await pool.query(`
        SELECT
          d.id                                          AS driver_id,
          d.driver_number,
          d.driver_classification,
          d.market,
          d.status,
          d.wiw_sync_status,
          d.wiw_last_seen_at,
          u.first_name,
          u.last_name,
          u.email,
          d.phone_number,
          c.customer_name                               AS account_name
        FROM drivers d
        LEFT JOIN users     u ON u.id = d.user_id
        LEFT JOIN customers c ON c.id = d.drivershift_customer_id
        WHERE d.status NOT IN ('terminated', 'inactive', 'rejected')
          AND (d.wiw_sync_status IS NULL OR d.wiw_sync_status = 'unmatched')
          AND NOT EXISTS (
            SELECT 1 FROM wiw_users wu
            WHERE wu.driver_id = d.id
              AND wu.wiw_status = 'active'
              AND wu.is_active = true
          )
        ORDER BY d.driver_classification, u.last_name, u.first_name
      `);

      const drivers = rows.rows.map((r: any) => ({
        driverId:             r.driver_id,
        driverNumber:         r.driver_number ?? null,
        driverName:           [r.first_name, r.last_name].filter(Boolean).join(" ") || r.driver_number || "—",
        driverClassification: r.driver_classification ?? "Unknown",
        market:               r.market ?? "—",
        status:               r.status ?? "unknown",
        email:                r.email ?? null,
        phone:                r.phone_number ?? null,
        accountName:          r.account_name ?? null,
        wiwSyncStatus:        r.wiw_sync_status ?? "unmatched",
        wiwLastSeenAt:        r.wiw_last_seen_at ?? null,
      }));

      res.json({
        total:           drivers.length,
        employeeCount:   drivers.filter((d: any) => d.driverClassification === "Employee").length,
        icCount:         drivers.filter((d: any) => d.driverClassification !== "Employee").length,
        drivers,
      });
    } catch (err: any) {
      console.error("[WIW] drivers-without-wiw error:", err);
      res.status(500).json({ message: "Failed to load unlinked drivers", detail: err?.message });
    }
  });

  // POST /api/scheduling/wheniwork/full-sync
  // Runs a complete "users sync → auto-match" pipeline in one shot.
  // This is the recommended path for the "Expand to Full Active Driver Sync" ticket.
  app.post("/api/scheduling/wheniwork/full-sync", isAuthenticated, async (req: Request, res: Response) => {
    try {
      // Step 1: sync all users from all WIW workplaces
      const { runEntitySync } = await import("./services/wiwSyncService");
      const userSync = await runEntitySync("users", "manual");

      // Step 2: auto-match is already called inside syncUsers(), but re-run to
      // ensure any pre-existing unmatched users also get a fresh pass.
      const { autoMatchWiwUsers } = await import("./services/wiwUserMatcher");
      const matchResult = await autoMatchWiwUsers();

      // Step 3: summary for the UI
      const { getWiwMappingSummary } = await import("./services/wiwUserMatcher");
      const summary = await getWiwMappingSummary();

      console.log(`[WIW] full-sync complete: synced=${userSync.fetched} matched=${matchResult.matched} unmatched=${matchResult.unmatched} ambiguous=${matchResult.ambiguous}`);
      res.json({
        userSync: {
          fetched:  userSync.fetched,
          inserted: userSync.inserted,
          updated:  userSync.updated,
          errors:   userSync.errors,
          errorMessages: userSync.errorMessages ?? [],
        },
        matchResult: {
          attempted:     matchResult.attempted,
          matched:       matchResult.matched,
          alreadyMatched: matchResult.alreadyMatched,
          unmatched:     matchResult.unmatched,
          ambiguous:     matchResult.ambiguous,
        },
        summary,
      });
    } catch (err: any) {
      console.error("[WIW] full-sync error:", err);
      res.status(500).json({ message: "Full sync failed", detail: err?.message });
    }
  });

  // GET /api/scheduling/wheniwork/sync-validation
  // Returns data-flow validation counts to confirm the sync is working end-to-end:
  // drivers with shifts, drivers with clock-in activity, accounts with coverage, etc.
  app.get("/api/scheduling/wheniwork/sync-validation", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const cutoff = "2026-02-09";
      const [driversResult, shiftsResult, timesResult, accountsResult, unlinkedResult] = await Promise.all([
        // Active drivers linked to WIW
        pool.query(`
          SELECT
            COUNT(*) FILTER (WHERE wiw_sync_status = 'synced')                       AS linked_drivers,
            COUNT(*) FILTER (WHERE status NOT IN ('terminated','inactive','rejected')) AS total_active_drivers
          FROM drivers
        `),
        // Drivers with upcoming shifts (next 14 days)
        pool.query(`
          SELECT COUNT(DISTINCT wu.driver_id) AS drivers_with_upcoming_shifts
          FROM wiw_shifts s
          JOIN wiw_users wu ON wu.id = s.wiw_user_id
          WHERE wu.driver_id IS NOT NULL
            AND wu.wiw_status = 'active'
            AND s.start_time >= now()
            AND s.start_time <= now() + interval '14 days'
            AND s.status NOT IN ('cancelled','deleted')
            AND s.start_time::date >= $1
        `, [cutoff]),
        // Drivers with clock-in activity (last 14 days)
        pool.query(`
          SELECT COUNT(DISTINCT wu.driver_id) AS drivers_with_clock_activity
          FROM wiw_times t
          JOIN wiw_users wu ON wu.id = t.wiw_user_id
          WHERE wu.driver_id IS NOT NULL
            AND wu.wiw_status = 'active'
            AND t.clock_in IS NOT NULL
            AND t.clock_in >= now() - interval '14 days'
            AND t.clock_in::date >= $1
        `, [cutoff]),
        // Accounts with ≥1 mapped WIW location (Account → Scheduling)
        pool.query(`
          SELECT COUNT(DISTINCT driverhub_account_id) AS accounts_with_wiw
          FROM wiw_location_account_map
          WHERE mapping_status = 'mapped'
        `),
        // Drivers with no WIW link (for the exception count)
        pool.query(`
          SELECT COUNT(*) AS unlinked_drivers
          FROM drivers d
          WHERE d.status NOT IN ('terminated','inactive','rejected')
            AND (d.wiw_sync_status IS NULL OR d.wiw_sync_status = 'unmatched')
            AND NOT EXISTS (
              SELECT 1 FROM wiw_users wu WHERE wu.driver_id = d.id AND wu.wiw_status = 'active' AND wu.is_active = true
            )
        `),
      ]);

      const d = driversResult.rows[0] ?? {};
      const s = shiftsResult.rows[0] ?? {};
      const t = timesResult.rows[0] ?? {};
      const a = accountsResult.rows[0] ?? {};
      const u = unlinkedResult.rows[0] ?? {};

      const linkedDrivers       = Number(d.linked_drivers ?? 0);
      const totalActiveDrivers  = Number(d.total_active_drivers ?? 0);
      const driversWithShifts   = Number(s.drivers_with_upcoming_shifts ?? 0);
      const driversWithClock    = Number(t.drivers_with_clock_activity ?? 0);
      const accountsWithWiw     = Number(a.accounts_with_wiw ?? 0);
      const unlinkedDrivers     = Number(u.unlinked_drivers ?? 0);

      res.json({
        linkedDrivers,
        totalActiveDrivers,
        unlinkedDrivers,
        linkRate: totalActiveDrivers > 0 ? Math.round((linkedDrivers / totalActiveDrivers) * 100) : 0,
        driversWithUpcomingShifts: driversWithShifts,
        driversWithClockActivity:  driversWithClock,
        accountsWithWiwCoverage:   accountsWithWiw,
        dataCutoff: cutoff,
      });
    } catch (err: any) {
      console.error("[WIW] sync-validation error:", err);
      res.status(500).json({ message: "Validation check failed", detail: err?.message });
    }
  });

  // POST /api/scheduling/wheniwork/create-and-link — create a new DriverHub driver from WIW user data and link them
  app.post("/api/scheduling/wheniwork/create-and-link", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { wiwUserId, firstName, lastName, email, phone, driverClassification, market } = req.body;
      if (!wiwUserId) return res.status(400).json({ message: "wiwUserId is required" });
      if (!firstName && !lastName) return res.status(400).json({ message: "At least one of firstName or lastName is required" });

      // Verify the WIW user exists and is unmatched
      const wiwRow = await pool.query(
        `SELECT id, external_user_id, name, email, phone, match_status FROM wiw_users WHERE id = $1`,
        [wiwUserId]
      );
      if (!wiwRow.rows.length) return res.status(404).json({ message: "WIW user not found" });
      const wiwUser = wiwRow.rows[0];
      if (wiwUser.match_status === "matched") return res.status(409).json({ message: "WIW user is already matched to a driver" });

      const userId = (req.user as any)?.id;
      const orgId = (req.user as any)?.orgId;

      // Check for duplicate email in users table
      const resolvedEmail = email || wiwUser.email || null;
      if (resolvedEmail) {
        const existing = await pool.query(`SELECT id FROM users WHERE email = $1 LIMIT 1`, [resolvedEmail.toLowerCase()]);
        if (existing.rows.length) {
          return res.status(409).json({ message: `A user with email ${resolvedEmail} already exists. Use 'Assign to Driver' to link the existing driver instead.` });
        }
      }

      // Create a minimal user record
      const newUserId = `driver-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;
      await pool.query(
        `INSERT INTO users (id, first_name, last_name, email, role, status, created_at, updated_at)
         VALUES ($1, $2, $3, $4, 'driver', 'INVITED', now(), now())
         ON CONFLICT (email) DO NOTHING`,
        [newUserId, firstName || "", lastName || "", resolvedEmail]
      );

      // Get the actual user id (in case of conflict skip)
      let actualUserId = newUserId;
      if (resolvedEmail) {
        const userRow = await pool.query(`SELECT id FROM users WHERE email = $1 LIMIT 1`, [resolvedEmail.toLowerCase()]);
        if (userRow.rows.length) actualUserId = userRow.rows[0].id;
      }

      // Create driver record
      const driverNumber = `WIW-${wiwUser.external_user_id}`;
      const driverResult = await pool.query(
        `INSERT INTO drivers (user_id, driver_number, phone_number, driver_classification, market, status, created_at, updated_at)
         VALUES ($1, $2, $3, $4, $5, 'active', now(), now())
         RETURNING id, driver_number, status`,
        [
          actualUserId,
          driverNumber,
          phone || wiwUser.phone || null,
          driverClassification || "Independent Contractor",
          market || null,
        ]
      );
      const newDriver = driverResult.rows[0];

      // Link user → driver
      await pool.query(
        `UPDATE users SET driver_id = $1, updated_at = now() WHERE id = $2`,
        [newDriver.id, actualUserId]
      );

      // Link WIW user → new driver (mark matched)
      await pool.query(
        `UPDATE wiw_users
         SET driver_id = $1, match_status = 'matched', match_method = 'manual', updated_at = now()
         WHERE id = $2`,
        [newDriver.id, wiwUserId]
      );

      // Write initial driver status history
      try {
        await pool.query(
          `INSERT INTO driver_status_history (driver_id, event_type, prior_status, new_status, effective_date, changed_by_user_id, source_type)
           VALUES ($1, 'driver_created', NULL, 'active', CURRENT_DATE, $2, 'wiw_reconciliation')`,
          [newDriver.id, userId]
        );
      } catch (_) {}

      console.log(`[WIW] create-and-link: created driver ${newDriver.id} (${driverNumber}) linked to WIW user ${wiwUser.external_user_id}`);
      res.json({
        driverId: newDriver.id,
        driverNumber: newDriver.driver_number,
        wiwUserId,
        wiwExternalId: wiwUser.external_user_id,
        message: `Driver created and linked to WIW user ${wiwUser.name}`,
      });
    } catch (err: any) {
      console.error("[WIW] create-and-link error:", err);
      res.status(500).json({ message: "Failed to create and link driver", detail: err?.message });
    }
  });

  // GET /api/drivers/:driverId/wiw-integration — WIW integration summary for a driver profile
