  // GET /api/scheduling/wheniwork/sync/audit — sync exclusion audit log
  app.get("/api/scheduling/wheniwork/sync/audit", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { reason, limit = "200", offset = "0" } = req.query as Record<string, string>;
      const conditions: string[] = [];
      const params: any[] = [];
      if (reason && reason !== "all") {
        params.push(reason);
        conditions.push(`reason = $${params.length}`);
      }
      const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";
      const rows = await (await import("./db")).pool.query(
        `SELECT id, sync_run_id, account_id, external_user_id, name, email,
                wiw_status, reason, primary_external_user_id, notes, created_at
         FROM wiw_sync_audit
         ${where}
         ORDER BY created_at DESC
         LIMIT $${params.length + 1} OFFSET $${params.length + 2}`,
        [...params, parseInt(limit), parseInt(offset)]
      );
      const countRes = await (await import("./db")).pool.query(
        `SELECT count(*)::int AS total FROM wiw_sync_audit ${where}`,
        params
      );
      res.json({ rows: rows.rows, total: countRes.rows[0]?.total ?? 0 });
    } catch (err: any) {
      console.error("[WIW] sync audit error:", err);
      res.status(500).json({ message: "Failed to fetch sync audit", detail: err?.message });
    }
  });

