  // POST /api/scheduling/wheniwork/sync/reconcile-shifts
  // Full reconcile: upserts all WIW shifts for the window, then soft-deletes
  // any DB shifts whose external_shift_id was NOT returned by WIW (i.e. cancelled/removed).
  // This is a true reconcile — not an append-only sync.
  app.post("/api/scheduling/wheniwork/sync/reconcile-shifts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user?.claims?.sub || (req.session as any)?.userId);
      if (!["super_admin", "platform_admin", "admin"].includes(user?.role ?? "")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { start, end } = req.body ?? {};
      const { reconcileShifts } = await import("./services/wiwSyncService");
      const result = await reconcileShifts({ start, end });
      res.json(result);
    } catch (err: any) {
      console.error("[WIW] reconcile-shifts error:", err);
      res.status(500).json({ message: "Shift reconciliation failed", detail: err?.message });
    }
  });

