  // POST /api/scheduling/wheniwork/webhook — ingest inbound WIW webhook (public, no auth)
  app.post("/api/scheduling/wheniwork/webhook", express.raw({ type: 'application/json' }), async (req: Request, res: Response) => {
    try {
      const { ingestWebhook } = await import("./services/wiwWebhookService");
      const rawBody = req.body instanceof Buffer ? req.body.toString('utf8') : JSON.stringify(req.body);
      const parsed = JSON.parse(rawBody);
      const signature = (req.headers['x-wiw-signature'] as string) ?? null;
      const result = await ingestWebhook(rawBody, parsed, signature);
      res.status(result.status === 'failed' ? 422 : 200).json(result);
    } catch (err: any) {
      console.error('[WIW] webhook ingest error:', err);
      res.status(500).json({ message: 'Webhook processing failed', detail: err?.message });
    }
  });

