  // GET /api/scheduling/wheniwork/shifts — paginated shift list with driver/location/position
  app.get("/api/scheduling/wheniwork/shifts", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const start    = (req.query.start    as string) || "";
      const end      = (req.query.end      as string) || "";
      const status   = (req.query.status   as string) || "all";
      const page     = Math.max(1, parseInt((req.query.page     as string) || "1", 10));
      const pageSize = Math.min(100, Math.max(1, parseInt((req.query.pageSize as string) || "25", 10)));
      const offset   = (page - 1) * pageSize;

      const conditions: string[] = [];
      const params: any[] = [];
      let pi = 1;

      const driverId  = (req.query.driverId  as string) || "";
      const accountId = (req.query.accountId as string) || "";

      // Data Governance Rule 1: hard acquisition date floor — no pre-acquisition data in any view
      conditions.push(`s.start_time >= '2026-02-09'`);

      // By default, hide reconcile-soft-deleted shifts unless the caller explicitly asks for them.
      if (status === "deleted") {
        conditions.push(`s.status = $${pi++}`);
        params.push("deleted");
      } else if (status !== "all") {
        conditions.push(`s.status = $${pi++}`);
        params.push(status);
      } else {
        // status === "all" — still exclude soft-deleted shifts from the normal list
        conditions.push(`s.status != 'deleted'`);
      }
      if (start)            { conditions.push(`s.start_time >= $${pi++}`); params.push(start); }
      if (end)              { conditions.push(`s.start_time < ($${pi++}::date + interval '1 day')`); params.push(end); }
      if (driverId)         { conditions.push(`u.driver_id = $${pi++}`);  params.push(driverId); }
      if (accountId)        { conditions.push(`l.account_id = $${pi++}`); params.push(accountId); }

      const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";

      const [rowsQ, countQ] = await Promise.all([
        pool.query(`
          SELECT
            s.id, s.external_shift_id,
            s.start_time, s.end_time, s.scheduled_minutes,
            s.status, s.is_open, s.notes,
            u.name        AS wiw_user_name,
            u.driver_id,
            u.name        AS driver_name,
            l.name        AS location_name,
            l.timezone    AS location_timezone,
            p.name        AS position_name
          FROM wiw_shifts s
          LEFT JOIN wiw_users     u ON u.id = s.wiw_user_id AND u.wiw_status = 'active'
          LEFT JOIN wiw_locations l ON l.id = s.wiw_location_id
          LEFT JOIN wiw_positions p ON p.id = s.wiw_position_id
          ${where}
          ORDER BY s.start_time DESC NULLS LAST
          LIMIT $${pi} OFFSET $${pi + 1}
        `, [...params, pageSize, offset]),
        pool.query(`
          SELECT count(*)::int AS total FROM wiw_shifts s
          LEFT JOIN wiw_users     u ON u.id = s.wiw_user_id AND u.wiw_status = 'active'
          LEFT JOIN wiw_locations l ON l.id = s.wiw_location_id
          ${where}
        `, params),
      ]);

      res.json({ records: rowsQ.rows, total: countQ.rows[0]?.total ?? 0, page, pageSize });
    } catch (err: any) {
      console.error("[WIW] shifts list error:", err);
      res.status(500).json({ message: "Failed to load shifts", detail: err?.message });
    }
  });

  // GET /api/scheduling/wheniwork/absences — paginated absence list
  app.get("/api/scheduling/wheniwork/absences", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const start    = (req.query.start    as string) || "";
      const end      = (req.query.end      as string) || "";
      const status   = (req.query.status   as string) || "all";
      const page     = Math.max(1, parseInt((req.query.page     as string) || "1", 10));
      const pageSize = Math.min(100, Math.max(1, parseInt((req.query.pageSize as string) || "25", 10)));
      const offset   = (page - 1) * pageSize;

      const conditions: string[] = [];
      const params: any[] = [];
      let pi = 1;

      const driverId  = (req.query.driverId  as string) || "";
      const accountId = (req.query.accountId as string) || "";

      // Data Governance Rule 1: hard acquisition date floor — no pre-acquisition data in any view
      conditions.push(`a.date >= '2026-02-09'`);

      if (status !== "all") { conditions.push(`a.status = $${pi++}`);    params.push(status); }
      if (start)            { conditions.push(`a.date >= $${pi++}`);       params.push(start); }
      if (end)              { conditions.push(`a.date <= $${pi++}`);        params.push(end);   }
      if (driverId)         { conditions.push(`u.driver_id = $${pi++}`);   params.push(driverId); }
      if (accountId)        {
        conditions.push(`a.wiw_user_id IN (
          SELECT DISTINCT s2.wiw_user_id FROM wiw_shifts s2
          JOIN wiw_locations l2 ON l2.id = s2.wiw_location_id
          WHERE l2.account_id = $${pi++} AND s2.wiw_user_id IS NOT NULL
        )`);
        params.push(accountId);
      }

      const where = conditions.length ? `WHERE ${conditions.join(" AND ")}` : "";

      const [rowsQ, countQ] = await Promise.all([
        pool.query(`
          SELECT
            a.id, a.date, a.reason, a.duration_minutes, a.status, a.notes,
            u.name      AS wiw_user_name,
            u.driver_id,
            u.name      AS driver_name
          FROM wiw_absences a
          LEFT JOIN wiw_users u ON u.id = a.wiw_user_id AND u.wiw_status = 'active'
          ${where}
          ORDER BY a.date DESC NULLS LAST
          LIMIT $${pi} OFFSET $${pi + 1}
        `, [...params, pageSize, offset]),
        pool.query(`SELECT count(*)::int AS total FROM wiw_absences a LEFT JOIN wiw_users u ON u.id = a.wiw_user_id AND u.wiw_status = 'active' ${where}`, params),
      ]);

      res.json({ records: rowsQ.rows, total: countQ.rows[0]?.total ?? 0, page, pageSize });
    } catch (err: any) {
      console.error("[WIW] absences list error:", err);
      res.status(500).json({ message: "Failed to load absences", detail: err?.message });
    }
  });

