  // GET /api/scheduling/wheniwork/times/export — CSV of approved records only
  app.get("/api/scheduling/wheniwork/times/export", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const start = (req.query.start as string) || "";
      const end   = (req.query.end   as string) || "";

      const conditions = ["t.approval_status = 'approved'"];
      const params: any[] = [];
      let pi = 1;
      if (start) { conditions.push(`t.clock_in >= $${pi++}`); params.push(start); }
      if (end)   { conditions.push(`t.clock_in  < ($${pi++}::date + interval '1 day')`); params.push(end); }

      const { rows } = await pool.query(`
        SELECT
          t.external_time_id,
          u.name AS driver_name,
          u.driver_id,
          t.clock_in, t.clock_out,
          t.total_minutes,
          t.auto_clock_out,
          t.notes,
          t.approved_by,
          t.approved_at
        FROM wiw_times t
        LEFT JOIN wiw_users  u ON u.id = t.wiw_user_id
        WHERE ${conditions.join(" AND ")}
        ORDER BY t.clock_in ASC
      `, params);

      const header = "external_time_id,driver_name,driver_id,clock_in,clock_out,total_minutes,auto_clock_out,notes,approved_by,approved_at";
      const escape = (v: any) => v == null ? "" : `"${String(v).replace(/"/g, '""')}"`;
      const csv = [header, ...rows.map((r) => [
        escape(r.external_time_id), escape(r.driver_name), escape(r.driver_id),
        escape(r.clock_in), escape(r.clock_out), escape(r.total_minutes),
        escape(r.auto_clock_out), escape(r.notes),
        escape(r.approved_by), escape(r.approved_at),
      ].join(","))].join("\n");

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="wiw_approved_times.csv"`);
      res.send(csv);
    } catch (err: any) {
      console.error("[WIW] export error:", err);
      res.status(500).json({ message: "Export failed", detail: err?.message });
    }
  });

  // GET /api/scheduling/wheniwork/wiw-locations — list WIW locations (optionally by account) + unmapped
  app.get("/api/scheduling/wheniwork/wiw-locations", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const accountId = (req.query.accountId as string) || "";
      const [allQ] = await Promise.all([
        pool.query(`
          SELECT id, external_location_id, name, address, timezone, account_id,
                 c.customer_name AS account_name
          FROM wiw_locations l
          LEFT JOIN customers c ON c.id = l.account_id
          ORDER BY l.name
        `),
      ]);
      const mapped   = allQ.rows.filter((r: any) => r.account_id === accountId && accountId);
      const unmapped = allQ.rows.filter((r: any) => !r.account_id);
      const all      = allQ.rows;
      res.json({ all, mapped: accountId ? mapped : [], unmapped, total: all.length });
    } catch (err: any) {
      console.error("[WIW] wiw-locations error:", err);
      res.status(500).json({ message: "Failed to load WIW locations", detail: err?.message });
    }
  });

  // PATCH /api/scheduling/wheniwork/wiw-locations/:id/timezone — admin override for location timezone
  app.patch("/api/scheduling/wheniwork/wiw-locations/:id/timezone", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { timezone } = req.body;
      if (typeof timezone !== "string" && timezone !== null) {
        return res.status(400).json({ message: "timezone must be an IANA string or null" });
      }
      await pool.query(
        `UPDATE wiw_locations SET timezone = $1, updated_at = now() WHERE id = $2`,
        [timezone || null, req.params.id]
      );
      res.json({ success: true });
    } catch (err: any) {
      console.error("[WIW] wiw-location timezone patch error:", err);
      res.status(500).json({ message: "Failed to update timezone", detail: err?.message });
    }
  });

