  // ── WIW Location Governance ──────────────────────────────────────────────────
  // GET /api/scheduling/wiw-governance — full governance console list with filters
  app.get("/api/scheduling/wiw-governance", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const govStatus  = (req.query.status    as string) || "all";
      const workplaceId = req.query.workplaceId ? parseInt(req.query.workplaceId as string) : null;
      const accountId  = req.query.accountId   as string | undefined;
      const search     = req.query.search      as string | undefined;
      const limit      = Math.min(parseInt(req.query.limit  as string) || 100, 500);
      const offset     = parseInt(req.query.offset as string) || 0;

      const whereClauses: string[] = ["1=1"];
      const params: any[]          = [];
      let p = 1;

      if (govStatus === "missing_timezone") {
        whereClauses.push(`(wl.timezone IS NULL OR wl.timezone = '')`);
      } else if (govStatus !== "all") {
        whereClauses.push(`lam.wiw_location_status = $${p++}`);
        params.push(govStatus);
      }
      if (workplaceId) {
        whereClauses.push(`lam.wiw_workplace_id = $${p++}`);
        params.push(workplaceId);
      }
      if (accountId) {
        whereClauses.push(`lam.driverhub_account_id = $${p++}`);
        params.push(accountId);
      }
      if (search) {
        whereClauses.push(`(lam.wiw_location_name ILIKE $${p} OR wl.external_location_id ILIKE $${p})`);
        params.push(`%${search}%`); p++;
      }

      const whereStr = whereClauses.join(" AND ");

      const countQ = await pool.query(
        `SELECT COUNT(*) AS n
         FROM wiw_location_account_map lam
         LEFT JOIN wiw_locations wl ON wl.id = lam.wiw_location_id
         WHERE ${whereStr}`,
        params
      );
      const total = parseInt(countQ.rows[0]?.n ?? "0");

      const rowsQ = await pool.query(
        `SELECT
           lam.id, lam.wiw_workplace_id, lam.wiw_location_id, lam.wiw_location_name,
           lam.driverhub_account_id, lam.mapping_status, lam.confidence_score,
           lam.match_reason, lam.wiw_location_status, lam.status_reason,
           lam.last_activity_at, lam.last_reviewed_at, lam.reviewed_by_user_id,
           lam.updated_at,
           wl.external_location_id, wl.timezone AS location_timezone,
           c.customer_name AS account_name, c.customer_number,
           u.username AS reviewed_by_name
         FROM wiw_location_account_map lam
         LEFT JOIN wiw_locations wl      ON wl.id = lam.wiw_location_id
         LEFT JOIN customers c           ON c.id  = lam.driverhub_account_id
         LEFT JOIN users u               ON u.id  = lam.reviewed_by_user_id
         WHERE ${whereStr}
         ORDER BY lam.wiw_location_name
         LIMIT $${p} OFFSET $${p+1}`,
        [...params, limit, offset]
      );

      const workplaceLabel = (id: number | null) => {
        if (!id) return "—";
        const m: Record<number, string> = { 3725440: "Main", 4244009: "IL & NY", 4280572: "CA" };
        return m[id] ?? `WP ${id}`;
      };

      res.json({
        total,
        records: rowsQ.rows.map(r => ({
          id:                  r.id,
          wiwWorkplaceId:      r.wiw_workplace_id,
          wiwWorkplaceName:    workplaceLabel(r.wiw_workplace_id),
          wiwLocationId:       r.wiw_location_id,
          wiwExternalId:       r.external_location_id,
          wiwLocationName:     r.wiw_location_name,
          driverHubAccountId:  r.driverhub_account_id,
          accountName:         r.account_name,
          customerNumber:      r.customer_number,
          mappingStatus:       r.mapping_status,
          wiwLocationStatus:   r.wiw_location_status,
          statusReason:        r.status_reason,
          locationTimezone:    r.location_timezone ?? null,
          lastActivityAt:      r.last_activity_at,
          lastReviewedAt:      r.last_reviewed_at,
          reviewedByName:      r.reviewed_by_name,
          updatedAt:           r.updated_at,
        })),
      });
    } catch (err: any) {
      console.error("[WIW] governance list error:", err);
      res.status(500).json({ message: "Failed to load governance list", detail: err?.message });
    }
  });

  // PATCH /api/scheduling/wiw-governance/:mapId — update governance status
  app.patch("/api/scheduling/wiw-governance/:mapId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { withTenantContext } = await import("./services/tenantService");
      const ctx  = await withTenantContext(req);
      const user = await storage.getUser(ctx.userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { mapId } = req.params;
      const { wiwLocationStatus, statusReason, driverHubAccountId } = req.body;

      if (!wiwLocationStatus) return res.status(400).json({ message: "wiwLocationStatus is required" });

      const VALID = ["unmapped", "pending_mapping", "active_mapped", "test_location", "cancelled_inactive"];
      if (!VALID.includes(wiwLocationStatus)) {
        return res.status(400).json({ message: `Invalid wiwLocationStatus. Must be one of: ${VALID.join(", ")}` });
      }

      const { setGovernanceStatus } = await import("./services/wiwLocationMatcher");
      await setGovernanceStatus(
        mapId,
        wiwLocationStatus,
        statusReason ?? null,
        driverHubAccountId !== undefined ? (driverHubAccountId || null) : undefined,
        ctx.userId
      );

      res.json({ success: true });
    } catch (err: any) {
      console.error("[WIW] governance patch error:", err);
      res.status(500).json({ message: "Failed to update governance status", detail: err?.message });
    }
  });

  // GET /api/accounts/:id/wiw-governance-summary — per-account WIW governance summary
  app.get("/api/accounts/:id/wiw-governance-summary", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const accountId = req.params.id;

      // All locations currently mapped to this account OR candidates with any governance status
      // We show: (1) locations mapped to this account, plus (2) all unmapped/pending that might be for this account
      const mappedQ = await pool.query(`
        SELECT
          lam.id, lam.wiw_workplace_id, lam.wiw_location_id, lam.wiw_location_name,
          lam.driverhub_account_id, lam.wiw_location_status, lam.status_reason,
          lam.last_activity_at, lam.last_reviewed_at, lam.mapping_status,
          lam.updated_at,
          wl.external_location_id
        FROM wiw_location_account_map lam
        LEFT JOIN wiw_locations wl ON wl.id = lam.wiw_location_id
        WHERE lam.driverhub_account_id = $1
        ORDER BY lam.wiw_location_name
      `, [accountId]);

      // Unmapped and pending (system-wide) for governance visibility
      const pendingQ = await pool.query(`
        SELECT
          lam.id, lam.wiw_workplace_id, lam.wiw_location_id, lam.wiw_location_name,
          lam.driverhub_account_id, lam.wiw_location_status, lam.status_reason,
          lam.last_activity_at, lam.updated_at,
          wl.external_location_id
        FROM wiw_location_account_map lam
        LEFT JOIN wiw_locations wl ON wl.id = lam.wiw_location_id
        WHERE lam.driverhub_account_id IS NULL
          AND lam.wiw_location_status IN ('unmapped', 'pending_mapping')
        ORDER BY lam.wiw_location_name
      `);

      const wpLabel = (id: number | null) => {
        if (!id) return "—";
        const m: Record<number, string> = { 3725440: "Main", 4244009: "IL & NY", 4280572: "CA" };
        return m[id] ?? `WP ${id}`;
      };

      const mapRow = (r: any) => ({
        mapId:             r.id,
        wiwWorkplaceId:    r.wiw_workplace_id,
        wiwWorkplaceName:  wpLabel(r.wiw_workplace_id),
        wiwLocationId:     r.wiw_location_id,
        wiwExternalId:     r.external_location_id,
        wiwLocationName:   r.wiw_location_name,
        driverHubAccountId: r.driverhub_account_id,
        wiwLocationStatus: r.wiw_location_status,
        statusReason:      r.status_reason,
        lastActivityAt:    r.last_activity_at,
        lastReviewedAt:    r.last_reviewed_at,
        mappingStatus:     r.mapping_status,
        updatedAt:         r.updated_at,
      });

      const locations = mappedQ.rows.map(mapRow);
      const counts = {
        activeMapped:      locations.filter(l => l.wiwLocationStatus === "active_mapped").length,
        pendingMapping:    locations.filter(l => l.wiwLocationStatus === "pending_mapping").length,
        unmapped:          locations.filter(l => l.wiwLocationStatus === "unmapped").length,
        testLocation:      locations.filter(l => l.wiwLocationStatus === "test_location").length,
        cancelledInactive: locations.filter(l => l.wiwLocationStatus === "cancelled_inactive").length,
      };

      // System-wide unmapped/pending counts (for badge display in UI)
      const syswidePendingQ = await pool.query(
        `SELECT wiw_location_status, COUNT(*) AS n FROM wiw_location_account_map WHERE wiw_location_status IN ('unmapped', 'pending_mapping') AND driverhub_account_id IS NULL GROUP BY 1`
      );
      const syswideUnmapped  = parseInt(syswidePendingQ.rows.find(r => r.wiw_location_status === "unmapped")?.n ?? "0");
      const syswidePending   = parseInt(syswidePendingQ.rows.find(r => r.wiw_location_status === "pending_mapping")?.n ?? "0");

      res.json({
        counts,
        locations,
        unclaimedLocations: pendingQ.rows.map(mapRow),
        syswideUnmapped,
        syswidePending,
      });
    } catch (err: any) {
      console.error("[WIW] account governance summary error:", err);
      res.status(500).json({ message: "Failed to load account governance summary", detail: err?.message });
    }
  });

