  // GET /api/scheduling/wheniwork/account-summary — aggregate metrics for an account
  app.get("/api/scheduling/wheniwork/account-summary", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const accountId = (req.query.accountId as string) || "";
      const start     = (req.query.start     as string) || "";
      const end       = (req.query.end       as string) || "";
      if (!accountId) return res.status(400).json({ message: "accountId required" });

      const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0);
      const todayEnd   = new Date(); todayEnd.setHours(23, 59, 59, 999);

      const dateClause = (alias: string, col: string) => {
        const parts: string[] = [];
        if (start) parts.push(`${alias}.${col} >= '${start}'`);
        if (end)   parts.push(`${alias}.${col} < ('${end}'::date + interval '1 day')`);
        return parts.join(" AND ");
      };
      const shiftDateFilter = dateClause("s", "start_time");
      const timeeDateFilter = dateClause("t", "clock_in");

      const [schedQ, workedQ, approvedQ, exceptionsQ, driversTodayQ, clockedInQ, locationsQ, accountTzQ] = await Promise.all([
        // Scheduled hours in window (exclude deleted/cancelled shifts)
        pool.query(`
          SELECT COALESCE(SUM(s.scheduled_minutes), 0)::float / 60.0 AS hours
          FROM wiw_shifts s
          JOIN wiw_locations l ON l.id = s.wiw_location_id
          WHERE l.account_id = $1
            AND s.status NOT IN ('deleted', 'cancelled')
            ${shiftDateFilter ? `AND ${shiftDateFilter}` : ""}
        `, [accountId]),
        // Worked hours in window
        pool.query(`
          SELECT COALESCE(SUM(t.total_minutes), 0)::float / 60.0 AS hours
          FROM wiw_times t
          JOIN wiw_shifts s ON s.id = t.wiw_shift_id
          JOIN wiw_locations l ON l.id = s.wiw_location_id
          WHERE l.account_id = $1 ${timeeDateFilter ? `AND ${timeeDateFilter}` : ""}
        `, [accountId]),
        // Approved hours in window
        pool.query(`
          SELECT COALESCE(SUM(t.total_minutes), 0)::float / 60.0 AS hours
          FROM wiw_times t
          JOIN wiw_shifts s ON s.id = t.wiw_shift_id
          JOIN wiw_locations l ON l.id = s.wiw_location_id
          WHERE l.account_id = $1 AND t.approval_status = 'approved'
            ${timeeDateFilter ? `AND ${timeeDateFilter}` : ""}
        `, [accountId]),
        // Attendance exceptions (absences + notices) for drivers at this account
        pool.query(`
          SELECT
            (SELECT count(*)::int FROM wiw_absences a
               WHERE ${start ? `a.date >= '${start}' AND` : ""} ${end ? `a.date <= '${end}' AND` : ""}
               a.wiw_user_id IN (
                 SELECT DISTINCT s2.wiw_user_id FROM wiw_shifts s2
                 JOIN wiw_locations l2 ON l2.id = s2.wiw_location_id
                 WHERE l2.account_id = $1 AND s2.wiw_user_id IS NOT NULL
                   AND s2.status != 'deleted'
               ))
            +
            (SELECT count(*)::int FROM wiw_attendance_notices n
               WHERE ${start ? `n.occurred_at >= '${start}' AND` : ""} ${end ? `n.occurred_at < ('${end}'::date + interval '1 day') AND` : ""}
               n.wiw_user_id IN (
                 SELECT DISTINCT s2.wiw_user_id FROM wiw_shifts s2
                 JOIN wiw_locations l2 ON l2.id = s2.wiw_location_id
                 WHERE l2.account_id = $1 AND s2.wiw_user_id IS NOT NULL
                   AND s2.status != 'deleted'
               ))
            AS count
        `, [accountId]),
        // Drivers with shifts today at this account (exclude deleted/cancelled)
        pool.query(`
          SELECT count(DISTINCT u.driver_id)::int AS count
          FROM wiw_shifts s
          JOIN wiw_locations l ON l.id = s.wiw_location_id
          LEFT JOIN wiw_users u ON u.id = s.wiw_user_id
          WHERE l.account_id = $1
            AND s.start_time >= $2 AND s.start_time <= $3
            AND u.driver_id IS NOT NULL
            AND s.status NOT IN ('deleted', 'cancelled')
        `, [accountId, todayStart.toISOString(), todayEnd.toISOString()]),
        // Drivers currently clocked in (clock_in today, no clock_out yet)
        pool.query(`
          SELECT count(DISTINCT u.driver_id)::int AS count
          FROM wiw_times t
          JOIN wiw_shifts s ON s.id = t.wiw_shift_id
          JOIN wiw_locations l ON l.id = s.wiw_location_id
          LEFT JOIN wiw_users u ON u.id = t.wiw_user_id
          WHERE l.account_id = $1
            AND t.clock_in >= $2 AND t.clock_out IS NULL
            AND u.driver_id IS NOT NULL
        `, [accountId, todayStart.toISOString()]),
        // Location mapping status
        pool.query(`
          SELECT id, name, external_location_id, account_id
          FROM wiw_locations
          WHERE account_id IS NULL OR account_id = $1
          ORDER BY name
        `, [accountId]),
        // Account timezone: WIW location → explicit customer tz → state-derived → Eastern
        pool.query(`
          SELECT COALESCE(
            (SELECT wl.timezone FROM wiw_locations wl
             WHERE wl.account_id = $1 AND wl.timezone IS NOT NULL
             ORDER BY wl.created_at LIMIT 1),
            (SELECT NULLIF(TRIM(c.timezone), '') FROM customers c WHERE c.id = $1 LIMIT 1),
            (SELECT CASE UPPER(COALESCE(c2.customer_state,''))
               WHEN 'AK' THEN 'America/Anchorage' WHEN 'HI' THEN 'Pacific/Honolulu'
               WHEN 'CA' THEN 'America/Los_Angeles' WHEN 'OR' THEN 'America/Los_Angeles'
               WHEN 'WA' THEN 'America/Los_Angeles' WHEN 'NV' THEN 'America/Los_Angeles'
               WHEN 'MT' THEN 'America/Denver' WHEN 'ID' THEN 'America/Denver'
               WHEN 'WY' THEN 'America/Denver' WHEN 'CO' THEN 'America/Denver'
               WHEN 'UT' THEN 'America/Denver' WHEN 'NM' THEN 'America/Denver'
               WHEN 'AZ' THEN 'America/Phoenix'
               WHEN 'ND' THEN 'America/Chicago' WHEN 'SD' THEN 'America/Chicago'
               WHEN 'NE' THEN 'America/Chicago' WHEN 'KS' THEN 'America/Chicago'
               WHEN 'OK' THEN 'America/Chicago' WHEN 'TX' THEN 'America/Chicago'
               WHEN 'MN' THEN 'America/Chicago' WHEN 'IA' THEN 'America/Chicago'
               WHEN 'MO' THEN 'America/Chicago' WHEN 'AR' THEN 'America/Chicago'
               WHEN 'LA' THEN 'America/Chicago' WHEN 'WI' THEN 'America/Chicago'
               WHEN 'IL' THEN 'America/Chicago' WHEN 'MS' THEN 'America/Chicago'
               WHEN 'AL' THEN 'America/Chicago' WHEN 'TN' THEN 'America/Chicago'
               WHEN 'IN' THEN 'America/Indiana/Indianapolis'
               ELSE 'America/New_York'
             END FROM customers c2 WHERE c2.id = $1 LIMIT 1)
          ) AS timezone
        `, [accountId]),
      ]);

      const mappedLocations   = locationsQ.rows.filter((r: any) => r.account_id === accountId);
      const unmappedLocations = locationsQ.rows.filter((r: any) => !r.account_id);

      res.json({
        scheduledHours:        Math.round((schedQ.rows[0]?.hours ?? 0) * 100) / 100,
        workedHours:           Math.round((workedQ.rows[0]?.hours ?? 0) * 100) / 100,
        approvedHours:         Math.round((approvedQ.rows[0]?.hours ?? 0) * 100) / 100,
        attendanceExceptions:  exceptionsQ.rows[0]?.count ?? 0,
        driversScheduledToday: driversTodayQ.rows[0]?.count ?? 0,
        driversClockInNow:     clockedInQ.rows[0]?.count ?? 0,
        mappedLocations,
        unmappedLocations,
        timezone: accountTzQ.rows[0]?.timezone ?? "America/New_York",
      });
    } catch (err: any) {
      console.error("[WIW] account-summary error:", err);
      res.status(500).json({ message: "Failed to load account summary", detail: err?.message });
    }
  });

  // GET /api/scheduling/wheniwork/driver-summary — summary metrics for a single driver
  app.get("/api/scheduling/wheniwork/driver-summary", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const driverId = (req.query.driverId as string) || "";
      if (!driverId) return res.status(400).json({ message: "driverId required" });

      const [schedQ, workedQ, approvedQ, issuesQ, upcomingQ] = await Promise.all([
        // Scheduled hours this week (Mon–Sun)
        pool.query(`
          SELECT COALESCE(SUM(s.scheduled_minutes), 0)::float / 60.0 AS hours
          FROM wiw_shifts s
          LEFT JOIN wiw_users u ON u.id = s.wiw_user_id
          WHERE u.driver_id = $1
            AND s.start_time >= date_trunc('week', now())
            AND s.start_time <  date_trunc('week', now()) + interval '7 days'
        `, [driverId]),
        // Worked hours this week
        pool.query(`
          SELECT COALESCE(SUM(t.total_minutes), 0)::float / 60.0 AS hours
          FROM wiw_times t
          LEFT JOIN wiw_users u ON u.id = t.wiw_user_id
          WHERE u.driver_id = $1
            AND t.clock_in >= date_trunc('week', now())
            AND t.clock_in <  date_trunc('week', now()) + interval '7 days'
        `, [driverId]),
        // Approved hours — total all time
        pool.query(`
          SELECT COALESCE(SUM(t.total_minutes), 0)::float / 60.0 AS hours
          FROM wiw_times t
          LEFT JOIN wiw_users u ON u.id = t.wiw_user_id
          WHERE u.driver_id = $1 AND t.approval_status = 'approved'
        `, [driverId]),
        // Attendance issues last 30 days (absences + notices combined)
        pool.query(`
          SELECT
            (SELECT count(*)::int FROM wiw_absences a
               LEFT JOIN wiw_users u ON u.id = a.wiw_user_id
               WHERE u.driver_id = $1 AND a.date >= now() - interval '30 days')
            +
            (SELECT count(*)::int FROM wiw_attendance_notices n
               LEFT JOIN wiw_users u ON u.id = n.wiw_user_id
               WHERE u.driver_id = $1 AND n.occurred_at >= now() - interval '30 days')
            AS count
        `, [driverId]),
        // Next upcoming shift
        pool.query(`
          SELECT s.start_time, s.end_time, l.name AS location_name, p.name AS position_name, s.status
          FROM wiw_shifts s
          LEFT JOIN wiw_users     u ON u.id = s.wiw_user_id
          LEFT JOIN wiw_locations l ON l.id = s.wiw_location_id
          LEFT JOIN wiw_positions p ON p.id = s.wiw_position_id
          WHERE u.driver_id = $1 AND s.start_time > now()
          ORDER BY s.start_time ASC
          LIMIT 1
        `, [driverId]),
      ]);

      res.json({
        scheduledHoursThisWeek: Math.round((schedQ.rows[0]?.hours ?? 0) * 100) / 100,
        workedHoursThisWeek:    Math.round((workedQ.rows[0]?.hours ?? 0) * 100) / 100,
        approvedHours:          Math.round((approvedQ.rows[0]?.hours ?? 0) * 100) / 100,
        attendanceIssues30d:    issuesQ.rows[0]?.count ?? 0,
        nextShift:              upcomingQ.rows[0] ?? null,
      });
    } catch (err: any) {
      console.error("[WIW] driver-summary error:", err);
      res.status(500).json({ message: "Failed to load driver summary", detail: err?.message });
    }
  });

