  // POST /api/admin/driver-scores/compute-all — admin bulk recompute
  app.post("/api/admin/driver-scores/compute-all", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !["super_user", "super_admin"].includes(user.role ?? "")) {
        return res.status(403).json({ message: "Super admin access required" });
      }
      const { computeAllDriverScores } = await import("./services/driverScoringService");
      const result = await computeAllDriverScores();
      res.json({ message: "Score computation complete", ...result });
    } catch (err: any) {
      console.error("[DriverScoring] bulk compute error:", err);
      res.status(500).json({ message: "Failed to compute all scores", detail: err?.message });
    }
  });

  // ── Driver OT Watch ──────────────────────────────────────────────────────
  // GET /api/scheduling/wheniwork/driver-ot-watch
  // Returns current-week OT projection for all active employee drivers (and WIW-linked drivers)
  app.get("/api/scheduling/wheniwork/driver-ot-watch", isAuthenticated, async (req: Request, res: Response) => {
    try {
      // ── Week bounds (Monday–Sunday, America/Chicago) ─────────────────────
      const now = new Date();
      const chicagoDate = new Date(now.toLocaleString("en-US", { timeZone: "America/Chicago" }));
      const dow = chicagoDate.getDay(); // 0=Sun
      const daysToMonday = dow === 0 ? -6 : 1 - dow;
      const weekStart = new Date(chicagoDate);
      weekStart.setDate(chicagoDate.getDate() + daysToMonday);
      weekStart.setHours(0, 0, 0, 0);
      const weekEnd = new Date(weekStart);
      weekEnd.setDate(weekStart.getDate() + 6);
      weekEnd.setHours(23, 59, 59, 999);
      const weekStartStr = weekStart.toISOString().split("T")[0];

      const OT_THRESHOLD = 40.0;
      // When true, include inactive/deleted WIW user records in the view (opt-in)
      const includeInactiveWiw = req.query.include_inactive_wiw === "true";

      // ── Get all WIW-linked active drivers ────────────────────────────────
      // Uses CTEs to avoid the fan-out problem: directly JOINing wiw_times and
      // wiw_shifts in the same query creates a cross-product that inflates both sums.
      const weekEndStr = new Date(new Date(weekStartStr + "T00:00:00Z").getTime() + 7 * 86_400_000)
        .toISOString().split("T")[0];
      const ACQUISITION_CUTOFF_OT = "2026-02-09";

      const linkedDriversRaw = await db.execute(sql`
        WITH
        worked AS (
          SELECT
            wu.driver_id,
            ROUND(COALESCE(SUM(t.total_minutes), 0) / 60.0, 2) AS worked_hours
          FROM wiw_users wu
          JOIN wiw_times t ON t.wiw_user_id = wu.id
          WHERE (${includeInactiveWiw} OR wu.wiw_status = 'active')
            AND t.clock_in >= ${weekStartStr}::date
            AND t.clock_in <  ${weekEndStr}::date
            AND t.clock_in >= ${ACQUISITION_CUTOFF_OT}::date
          GROUP BY wu.driver_id
        ),
        remaining AS (
          SELECT
            wu.driver_id,
            ROUND(COALESCE(SUM(s.scheduled_minutes), 0) / 60.0, 2) AS remaining_sched_hours
          FROM wiw_users wu
          JOIN wiw_shifts s ON s.wiw_user_id = wu.id
          WHERE (${includeInactiveWiw} OR wu.wiw_status = 'active')
            AND s.start_time >  NOW()
            AND s.start_time <  ${weekEndStr}::date + INTERVAL '1 day'
            AND s.status NOT IN ('absent', 'cancelled', 'deleted')
          GROUP BY wu.driver_id
        )
        SELECT
          d.id           AS driver_id,
          u.first_name,
          u.last_name,
          d.driver_classification,
          d.market,
          d.status,
          d.direct_manager AS manager_name,
          wu.id          AS wiw_user_id,
          wu.name        AS wiw_name,
          c.customer_name AS account_name,
          COALESCE(w.worked_hours,         0) AS worked_hours,
          COALESCE(r.remaining_sched_hours, 0) AS remaining_sched_hours
        FROM drivers d
        JOIN  users    u   ON u.id  = d.user_id
        JOIN  wiw_users wu ON wu.driver_id = d.id
          AND (${includeInactiveWiw} OR wu.wiw_status = 'active')
        LEFT  JOIN worked    w  ON w.driver_id = d.id
        LEFT  JOIN remaining r  ON r.driver_id = d.id
        LEFT  JOIN customers c  ON c.id = d.drivershift_customer_id
        WHERE d.status = 'active'
        ORDER BY d.id
      `);

      // ── Also include employee-classified drivers WITHOUT WIW links ────────
      const unlinkedEmployeesRaw = await db.execute(sql`
        SELECT
          d.id AS driver_id,
          u.first_name,
          u.last_name,
          d.driver_classification,
          d.market,
          d.status,
          d.direct_manager AS manager_name,
          NULL::text AS wiw_user_id,
          NULL::text AS wiw_name,
          c.customer_name AS account_name,
          0.0        AS worked_hours,
          0.0        AS remaining_sched_hours
        FROM drivers d
        JOIN users u ON u.id = d.user_id
        LEFT JOIN customers c ON c.id = d.drivershift_customer_id
        WHERE d.status = 'active'
          AND d.driver_classification = 'Employee'
          AND NOT EXISTS (
            SELECT 1 FROM wiw_users wu2
            WHERE wu2.driver_id = d.id
              AND (${includeInactiveWiw} OR wu2.wiw_status = 'active')
          )
      `);

      const linkedDrivers: any[] = linkedDriversRaw.rows ?? [];
      const unlinkedEmployees: any[] = unlinkedEmployeesRaw.rows ?? [];
      const allRows = [...linkedDrivers, ...unlinkedEmployees];

      // ── Compute OT projections ────────────────────────────────────────────
      function statusTier(projected: number): string {
        if (projected >= OT_THRESHOLD) return "overtime";
        if (projected >= 36) return "warning";
        if (projected >= 32) return "watch";
        return "normal";
      }

      const drivers = allRows.map((row: any) => {
        const worked = parseFloat(row.worked_hours ?? "0");
        const remaining = parseFloat(row.remaining_sched_hours ?? "0");
        const projectedTotal = Math.round((worked + remaining) * 10) / 10;
        const projectedOt = Math.max(0, Math.round((projectedTotal - OT_THRESHOLD) * 10) / 10);
        const hoursToOt = Math.max(0, Math.round((OT_THRESHOLD - worked) * 10) / 10);
        const tier = statusTier(projectedTotal);
        const isEmployee = (row.driver_classification ?? "").toLowerCase() === "employee";
        // ICs are included in the table for hours/utilization reporting
        // but OT fields are zeroed out and status forced to "normal"
        const effectiveOt   = isEmployee ? projectedOt  : 0;
        const effectiveHoursToOt = isEmployee ? hoursToOt : 0;
        const effectiveTier = isEmployee ? tier : "normal";

        return {
          driverId:               row.driver_id,
          driverName:             `${row.first_name} ${row.last_name}`.trim(),
          driverClassification:   row.driver_classification ?? "Unknown",
          accountName:            row.account_name ?? null,
          market:                 row.market ?? "—",
          managerName:            row.manager_name ?? null,
          wiwLinked:              !!row.wiw_user_id,
          isEmployee,
          workedHours:            Math.round(worked * 10) / 10,
          remainingScheduledHours: Math.round(remaining * 10) / 10,
          projectedTotalHours:    projectedTotal,
          projectedOtHours:       effectiveOt,
          hoursToOt:              effectiveHoursToOt,
          status:                 effectiveTier as "normal" | "watch" | "warning" | "overtime",
          weekStart:              weekStartStr,
        };
      });

      // Sort: overtime first → warning → watch → normal, then by projectedTotal desc
      const tierOrder: Record<string, number> = { overtime: 0, warning: 1, watch: 2, normal: 3 };
      drivers.sort((a, b) =>
        tierOrder[a.status] !== tierOrder[b.status]
          ? tierOrder[a.status] - tierOrder[b.status]
          : b.projectedTotalHours - a.projectedTotalHours
      );

      // ── Summary KPIs — employees ONLY per business rule ──────────────────
      // ICs are included in table data but excluded from all OT KPIs and alerts
      const empDrivers = drivers.filter(d => d.isEmployee);
      const summary = {
        inOvertime:            empDrivers.filter(d => d.status === "overtime").length,
        within4HrsOfOt:        empDrivers.filter(d => d.status !== "overtime" && d.hoursToOt <= 4 && d.hoursToOt > 0).length,
        within8HrsOfOt:        empDrivers.filter(d => d.status !== "overtime" && d.hoursToOt <= 8 && d.hoursToOt > 0).length,
        totalProjectedOtHours: Math.round(empDrivers.reduce((acc, d) => acc + d.projectedOtHours, 0) * 10) / 10,
        totalEmployeeDrivers:  empDrivers.length,
        totalDrivers:          drivers.length,
        weekStart: weekStartStr,
        weekEnd: weekEnd.toISOString().split("T")[0],
        computedAt: now.toISOString(),
      };

      res.json({ summary, drivers });
    } catch (err: any) {
      console.error("[WIW] driver-ot-watch error:", err);
      res.status(500).json({ message: "Failed to compute OT watch data", detail: err?.message });
    }
  });

