  // GET /api/schedule/:token — Public endpoint: get scheduling link by token (no auth)
  app.get("/api/schedule/:token", async (req: Request, res: Response) => {
    try {
      const { recruitingSchedulingLinks, recruitingSchedulingBookings, recruitingCandidates, recruitingRequisitions, users } = await import("../shared/schema");
      const [link] = await db.select().from(recruitingSchedulingLinks).where(eq(recruitingSchedulingLinks.token, req.params.token)).limit(1);
      if (!link) return res.status(404).json({ message: "Scheduling link not found" });
      // Check expiry and status
      if (link.status === "cancelled") return res.status(410).json({ message: "This scheduling link has been cancelled.", code: "cancelled" });
      if (new Date(link.expiresAt) < new Date()) return res.status(410).json({ message: "This scheduling link has expired.", code: "expired" });
      // Fetch candidate and requisition for display
      const [candidate] = await db.select({ firstName: recruitingCandidates.firstName, lastName: recruitingCandidates.lastName, email: recruitingCandidates.email }).from(recruitingCandidates).where(eq(recruitingCandidates.id, link.candidateId)).limit(1);
      const [requisition] = await db.select({ title: recruitingRequisitions.title, market: recruitingRequisitions.market }).from(recruitingRequisitions).where(eq(recruitingRequisitions.id, link.requisitionId)).limit(1);
      const [organizer] = await db.select({ firstName: users.firstName, lastName: users.lastName, email: users.email }).from(users).where(eq(users.id, link.organizerId || ""  )).limit(1);
      // Get existing bookings to exclude slots
      const bookings = await db.select({ selectedSlot: recruitingSchedulingBookings.selectedSlot, cancelledAt: recruitingSchedulingBookings.cancelledAt }).from(recruitingSchedulingBookings).where(eq(recruitingSchedulingBookings.linkId, link.id));
      const bookedSlots = bookings.filter((b: any) => !b.cancelledAt).map((b: any) => new Date(b.selectedSlot).toISOString());
      // Never expose tokens in the response
      const { token: _t, ...safeLink } = link as any;
      res.json({ ...safeLink, candidate, requisition, organizer, bookedSlots, isBooked: link.status === "booked" });
    } catch (error: any) {
      console.error("[Scheduling] Get link error:", error);
      res.status(500).json({ message: "Failed to load scheduling link" });
    }
  });

  // POST /api/schedule/:token/book — Public endpoint: book a slot (no auth)
  app.post("/api/schedule/:token/book", async (req: Request, res: Response) => {
    try {
      const { recruitingSchedulingLinks, recruitingSchedulingBookings, recruitingInterviews } = await import("../shared/schema");
      const [link] = await db.select().from(recruitingSchedulingLinks).where(eq(recruitingSchedulingLinks.token, req.params.token)).limit(1);
      if (!link) return res.status(404).json({ message: "Scheduling link not found" });
      if (link.status === "cancelled") return res.status(410).json({ message: "This link has been cancelled.", code: "cancelled" });
      if (new Date(link.expiresAt) < new Date()) return res.status(410).json({ message: "This link has expired.", code: "expired" });
      if (link.status === "booked") return res.status(409).json({ message: "This slot has already been booked.", code: "already_booked" });
      const { selectedSlot, candidateName, candidateEmail, candidatePhone, notes } = req.body;
      if (!selectedSlot || !candidateName || !candidateEmail) {
        return res.status(400).json({ message: "selectedSlot, candidateName, and candidateEmail are required" });
      }
      // Validate slot is in availableSlots
      const slots = Array.isArray(link.availableSlots) ? link.availableSlots as string[] : [];
      const slotTime = new Date(selectedSlot).toISOString();
      const validSlot = slots.some((s: string) => new Date(s).toISOString() === slotTime);
      if (!validSlot) return res.status(400).json({ message: "Selected slot is not available." });
      // Check not already booked
      const existing = await db.select({ id: recruitingSchedulingBookings.id }).from(recruitingSchedulingBookings).where(eq(recruitingSchedulingBookings.linkId, link.id)).limit(1);
      if (existing.length > 0) return res.status(409).json({ message: "This link has already been booked.", code: "already_booked" });
      // Generate confirmation code
      const { randomBytes } = await import("crypto");
      const confirmationCode = randomBytes(4).toString("hex").toUpperCase();
      // Create interview record
      const slotDate = new Date(selectedSlot);
      const endDate = new Date(slotDate.getTime() + (link.durationMinutes * 60000));
      const [interview] = await db.insert(recruitingInterviews).values({
        applicationId: link.applicationId,
        title: link.title,
        interviewType: (link.interviewType as any) || "phone",
        status: "scheduled",
        startTime: slotDate,
        endTime: endDate,
        durationMinutes: link.durationMinutes,
        meetingLink: link.meetingLink || null,
        organizerId: link.organizerId || null,
        notes: notes || null,
        createdBy: link.organizerId || null,
      } as any).returning();
      // Create booking record
      const [booking] = await db.insert(recruitingSchedulingBookings).values({
        linkId: link.id,
        selectedSlot: slotDate,
        candidateName: candidateName.trim(),
        candidateEmail: candidateEmail.trim().toLowerCase(),
        candidatePhone: candidatePhone?.trim() || null,
        confirmationCode,
        interviewId: interview?.id || null,
        notes: notes || null,
      } as any).returning();
      // Mark link as booked
      await db.update(recruitingSchedulingLinks).set({ status: "booked", updatedAt: new Date() } as any).where(eq(recruitingSchedulingLinks.id, link.id));
      res.status(201).json({ success: true, confirmationCode, booking, interviewId: interview?.id || null });
    } catch (error: any) {
      console.error("[Scheduling] Book slot error:", error);
      res.status(500).json({ message: "Failed to book slot" });
    }
  });

