  // POST /api/recruiting/interviews/:interviewId/scorecards - Submit a scorecard
  app.post("/api/recruiting/interviews/:interviewId/scorecards", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Check if interview exists
      const interview = await db.query.interviews.findFirst({
        where: eq(interviews.id, req.params.interviewId),
      });
      if (!interview) {
        return res.status(404).json({ message: "Interview not found" });
      }

      // Check if user already submitted a scorecard for this interview
      const existing = await db.query.interviewScorecards.findFirst({
        where: and(
          eq(interviewScorecards.interviewId, req.params.interviewId),
          eq(interviewScorecards.interviewerId, userId)
        ),
      });

      if (existing && existing.submittedAt) {
        return res.status(400).json({ message: "Scorecard already submitted and locked" });
      }

      const { overallRating, recommendation, notes } = req.body;

      // Validate
      if (!overallRating || overallRating < 1 || overallRating > 5) {
        return res.status(400).json({ message: "Overall rating must be between 1 and 5" });
      }
      if (!['proceed', 'hold', 'reject'].includes(recommendation)) {
        return res.status(400).json({ message: "Recommendation must be proceed, hold, or reject" });
      }

      const scorecardData = {
        interviewId: req.params.interviewId,
        interviewerId: userId,
        overallRating,
        recommendation,
        notes: notes || null,
        submittedAt: new Date(),
      };

      const [scorecard] = await db.insert(interviewScorecards).values(scorecardData).returning();

      res.json(scorecard);
    } catch (error) {
      console.error("[Recruiting] Error submitting scorecard:", error);
      res.status(500).json({ message: "Failed to submit scorecard" });
    }
  });

  // GET /api/recruiting/applications/:id/scorecards - Get all scorecards for an application (across all interviews)
  app.get("/api/recruiting/applications/:id/scorecards", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Get all interviews for this application
      const { getInterviewsForApplication } = await import("./recruitingService");
      const interviews = await getInterviewsForApplication(req.params.id);

      // Get scorecards for all interviews
      const allScorecards = [];
      for (const interview of interviews) {
        const scorecards = await db.query.interviewScorecards.findMany({
          where: eq(interviewScorecards.interviewId, interview.id),
        });
        for (const sc of scorecards) {
          allScorecards.push({
            ...sc,
            interviewTitle: interview.title,
            interviewType: interview.interviewType,
            interviewDate: interview.startTime,
          });
        }
      }

      res.json(allScorecards);
    } catch (error) {
      console.error("[Recruiting] Error fetching application scorecards:", error);
      res.status(500).json({ message: "Failed to fetch scorecards" });
    }
  });

