  // GET /api/screening/:token - Public route to get screening form for candidate (NO AUTH)
  app.get("/api/screening/:token", async (req: Request, res: Response) => {
    try {
      const { getScreeningTokenByToken, getScreeningFormTemplate } = await import("./recruitingService");
      const tokenRecord = await getScreeningTokenByToken(req.params.token);
      
      if (!tokenRecord) {
        return res.status(404).json({ message: "Invalid or expired screening link" });
      }

      if (tokenRecord.status !== 'pending') {
        return res.status(400).json({ message: "This screening form has already been completed" });
      }

      if (tokenRecord.expiresAt && new Date(tokenRecord.expiresAt) < new Date()) {
        return res.status(400).json({ message: "This screening link has expired" });
      }

      const template = await getScreeningFormTemplate(tokenRecord.formTemplateId);
      if (!template) {
        return res.status(404).json({ message: "Screening form not found" });
      }

      res.json({
        formTemplate: template,
        applicationId: tokenRecord.applicationId,
        expiresAt: tokenRecord.expiresAt,
      });
    } catch (error) {
      console.error("[Recruiting] Error getting screening form:", error);
      res.status(500).json({ message: "Failed to get screening form" });
    }
  });

