  // POST /api/recruiting/referrals - Submit a new referral
  app.post("/api/recruiting/referrals", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });

      const { createReferral } = await import("./recruitingService");
      
      const { referral, isDuplicate } = await createReferral({
        referrerId: userId,
        referredFirstName: req.body.referredFirstName,
        referredLastName: req.body.referredLastName,
        referredEmail: req.body.referredEmail,
        referredPhone: req.body.referredPhone,
        requisitionId: req.body.requisitionId,
        market: req.body.market,
        roleType: req.body.roleType,
        notes: req.body.notes,
        relationship: req.body.relationship,
      }, userId, user?.email || null);

      if (isDuplicate) {
        return res.status(409).json({
          message: "A referral for this candidate already exists in the current period",
          referral,
          isDuplicate: true,
        });
      }

      res.status(201).json({ referral, isDuplicate: false });
    } catch (error) {
      console.error("[Recruiting] Error creating referral:", error);
      res.status(500).json({ message: "Failed to create referral" });
    }
  });

  // GET /api/recruiting/referrals - Get referrals (my referrals or all for admin)
  app.get("/api/recruiting/referrals", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });

      const { getReferralsByReferrer, getAllReferrals } = await import("./recruitingService");
      
      const { status, market, all, limit, offset, includeArchived } = req.query;
      
      if (all === 'true' && user?.role === 'admin') {
        const result = await getAllReferrals({
          status: status as any,
          market: market as string,
          limit: limit ? parseInt(limit as string) : undefined,
          offset: offset ? parseInt(offset as string) : undefined,
        includeArchived: includeArchived === 'true',
        });
        res.json(result);
      } else {
        const result = await getReferralsByReferrer(userId, {
          limit: limit ? parseInt(limit as string) : undefined,
          offset: offset ? parseInt(offset as string) : undefined,
        includeArchived: includeArchived === 'true',
        });
        res.json(result);
      }
    } catch (error) {
      console.error("[Recruiting] Error fetching referrals:", error);
      res.status(500).json({ message: "Failed to fetch referrals" });
    }
  });

