  // ============================================================================

  // POST /api/v1/referrals - External referral submission (MoveNow Mobile / Driver on Demand)
  app.post("/api/v1/referrals", async (req: Request, res: Response) => {
    try {
      // Validate API key via DRIVERHUB_API_KEY secret
      const apiKey = req.headers['x-api-key'] || req.headers['authorization']?.replace('Bearer ', '');
      const validKey = process.env.DRIVERHUB_API_KEY;
      if (!validKey || apiKey !== validKey) {
        return res.status(401).json({ error: "Invalid or missing API key" });
      }

      const {
        referrerDriverId, referredFirstName, referredLastName, referredEmail,
        referredPhone, referredCity, referredState, referredDriverType,
        referredYearsExp, referredHasCdl, consentToShare,
        sourceSystem = 'mnm', market, roleType, notes, relationship,
      } = req.body;

      if (!referrerDriverId || !referredFirstName || !referredLastName || !referredEmail) {
        return res.status(400).json({
          error: "Missing required fields",
          required: ["referrerDriverId", "referredFirstName", "referredLastName", "referredEmail"],
        });
      }

      const { submitExternalReferral } = await import("./recruitingService");
      const result = await submitExternalReferral({
        referrerDriverId, referredFirstName, referredLastName, referredEmail,
        referredPhone, referredCity, referredState, referredDriverType,
        referredYearsExp, referredHasCdl, consentToShare,
        sourceSystem: sourceSystem as 'mnm' | 'dod' | 'direct',
        market, roleType, notes, relationship,
      });

      if (result.isDuplicate) {
        return res.status(409).json({
          status: "duplicate",
          message: "A referral for this candidate already exists in the current period",
          referralId: result.referral.id,
        });
      }

      res.status(201).json({
        status: "accepted",
        referralId: result.referral.id,
        candidateId: result.candidateId || null,
        periodKey: result.referral.referralPeriodKey,
      });
    } catch (error) {
      console.error("[API v1] Error submitting referral:", error);
      res.status(500).json({ error: "Failed to submit referral" });
    }
  });

  // GET /api/v1/referrals/status/:referralId - Get referral status (for driver apps)
  app.get("/api/v1/referrals/status/:referralId", async (req: Request, res: Response) => {
    try {
      const apiKey = req.headers['x-api-key'] || req.headers['authorization']?.replace('Bearer ', '');
      const validKey = process.env.DRIVERHUB_API_KEY;
      if (!validKey || apiKey !== validKey) {
        return res.status(401).json({ error: "Invalid or missing API key" });
      }

      const { getReferral, getReferralStatusHistory } = await import("./recruitingService");
      const referral = await getReferral(req.params.referralId);
      if (!referral) return res.status(404).json({ error: "Referral not found" });

      const history = await getReferralStatusHistory(req.params.referralId);
      res.json({
        referralId: referral.id,
        status: referral.status,
        milestoneReached: referral.milestoneReached,
        candidateId: referral.candidateId,
        periodKey: referral.referralPeriodKey,
        submittedAt: referral.createdAt,
        statusHistory: history.map(h => ({
          fromStatus: h.fromStatus,
          toStatus: h.toStatus,
          reason: h.reason,
          changedAt: h.changedAt,
        })),
      });
    } catch (error) {
      console.error("[API v1] Error fetching referral status:", error);
      res.status(500).json({ error: "Failed to fetch status" });
    }
  });

  // GET /api/v1/referrals/by-driver/:driverDriverId - Get referrals submitted by a driver
  app.get("/api/v1/referrals/by-driver/:driverDriverId", async (req: Request, res: Response) => {
    try {
      const apiKey = req.headers['x-api-key'] || req.headers['authorization']?.replace('Bearer ', '');
      const validKey = process.env.DRIVERHUB_API_KEY;
      if (!validKey || apiKey !== validKey) {
        return res.status(401).json({ error: "Invalid or missing API key" });
      }

      const result = await db.execute(sql`
        SELECT
          r.id, r.status, r.referred_first_name, r.referred_last_name,
          r.referred_email, r.market, r.role_type, r.milestone_reached,
          r.referral_period_key, r.created_at, r.expires_at,
          COALESCE(SUM(rl.amount::numeric), 0) AS total_rewards_earned,
          COALESCE(SUM(CASE WHEN rl.status = 'paid' THEN rl.amount::numeric ELSE 0 END), 0) AS rewards_paid
        FROM recruiting_referrals r
        LEFT JOIN referral_rewards_ledger rl ON rl.referral_id = r.id
        WHERE r.referrer_driver_id = ${req.params.driverDriverId}
        GROUP BY r.id
        ORDER BY r.created_at DESC
        LIMIT 50
      `);

      res.json({
        referrals: result.rows,
        count: result.rows.length,
      });
    } catch (error) {
      console.error("[API v1] Error fetching driver referrals:", error);
      res.status(500).json({ error: "Failed to fetch referrals" });
    }
  });

