      const consumer = (req.query.consumer as string) === 'dod' ? 'dod' : 'mnm';
      const limit = Math.min(parseInt(req.query.limit as string || '100'), 500);

      const { getPendingOutboundEvents } = await import("./recruitingService");
      const events = await getPendingOutboundEvents(consumer, limit);
      res.json({ events, consumer });
