  // POST /api/v1/referrals/events/acknowledge - Mark events consumed
  app.post("/api/v1/referrals/events/acknowledge", async (req: Request, res: Response) => {
    try {
      const apiKey = req.headers['x-api-key'] || req.headers['authorization']?.replace('Bearer ', '');
      const validKey = process.env.DRIVERHUB_API_KEY;
      if (!validKey || apiKey !== validKey) {
        return res.status(401).json({ error: "Invalid or missing API key" });
      }

      const { ids, consumer } = req.body;
      if (!Array.isArray(ids) || !ids.length) {
        return res.status(400).json({ error: "ids array required" });
      }
      if (!['mnm', 'dod'].includes(consumer)) {
        return res.status(400).json({ error: "consumer must be 'mnm' or 'dod'" });
      }

      const { markOutboundEventsConsumed } = await import("./recruitingService");
      await markOutboundEventsConsumed(ids, consumer);
      res.json({ acknowledged: ids.length });
    } catch (error) {
      console.error("[API v1] Error acknowledging events:", error);
      res.status(500).json({ error: "Failed to acknowledge" });
    }
  });

