  app.post("/api/scheduling/assignments/:id/clock-in", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      const userEmail = (req as any).session?.userEmail || (req as any).user?.claims?.email;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { latitude, longitude, overrideReason } = req.body;
      const { clockInWithGeofence, validateGeofence, recordGeofenceAudit } = await import("./schedulingService");
      
      // Get assignment to find shift
      const { db } = await import("./db");
      const { schedulingAssignments } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");
      const assignment = await db.select().from(schedulingAssignments).where(eq(schedulingAssignments.id, req.params.id)).limit(1);
      
      if (!assignment[0]) {
        return res.status(404).json({ message: "Assignment not found" });
      }
      
      // Validate geofence if coordinates provided
      let geofenceResult = null;
      let isWithinGeofence = true;
      
      if (latitude !== undefined && longitude !== undefined) {
        geofenceResult = await validateGeofence(assignment[0].shiftId, parseFloat(latitude), parseFloat(longitude));
        isWithinGeofence = geofenceResult.isWithinGeofence;
        
        // Block if outside geofence and no override provided
        if (!isWithinGeofence && !overrideReason) {
          return res.status(400).json({ 
            message: "Clock-in blocked: outside allowed location zone",
            geofenceViolation: true,
            distance: geofenceResult.distanceFromLocation,
            allowedRadius: geofenceResult.geofenceRadius,
            locationName: geofenceResult.locationName,
          });
        }
      }
      
      const { clockIn } = await import("./schedulingService");
      const result = await clockIn(
        req.params.id, 
        userId, 
        userEmail,
        latitude ? parseFloat(latitude) : undefined,
        longitude ? parseFloat(longitude) : undefined,
        isWithinGeofence,
        !!overrideReason
      );
      
      if (!result) {
        return res.status(404).json({ message: "Assignment not found" });
      }
      
      // Record geofence audit if coordinates were provided
      if (geofenceResult) {
        await recordGeofenceAudit(
          req.params.id,
          assignment[0].shiftId,
          'clock_in',
          latitude ? parseFloat(latitude) : null,
          longitude ? parseFloat(longitude) : null,
          geofenceResult,
          !!overrideReason,
          overrideReason || null,
          userId
        );
      }

      res.json({ ...result, geofenceViolation: !isWithinGeofence, wasOverridden: !!overrideReason });
    } catch (error) {
      console.error("[Scheduling] Error clocking in:", error);
      res.status(500).json({ message: "Failed to clock in" });
    }
  });

