  // Send SMS to candidate
  app.post("/api/recruiting/candidates/:id/sms", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { sendSms } = await import("./services/twilioSmsService");
      const { message, applicationId, overrideThrottle, overrideJustification } = req.body;
      
      if (!message || message.trim().length === 0) {
        return res.status(400).json({ message: "Message is required" });
      }

      const user = await db.query.users.findFirst({ where: (users: any, { eq }: any) => eq(users.id, userId) });

      if (overrideThrottle) {
        if (!user?.role || !['admin', 'super_user', 'recruiting_admin'].includes(user.role)) {
          return res.status(403).json({ message: "Only admins can override throttle limits" });
        }
        if (!overrideJustification || overrideJustification.trim().length === 0) {
          return res.status(400).json({ message: "Override justification is required" });
        }
      }

      const result = await sendSms(req.params.id, message, userId, applicationId, { overrideThrottle, overrideJustification, senderEmail: user?.email || null });
      
      if (!result.success) {
        return res.status(400).json({ 
          message: result.error,
          blockedReason: result.blockedReason,
          nextAllowedAt: result.nextAllowedAt,
          dailyCount: result.dailyCount,
          maxPerDay: result.maxPerDay,
        });
      }

      res.json({ 
        success: true, 
        messageSid: result.messageSid,
      });
    } catch (error: any) {
      console.error("[Communications] Error sending SMS:", error);
      res.status(500).json({ message: "Failed to send SMS" });
    }
  });

  // Send email to candidate
  app.post("/api/recruiting/candidates/:id/email", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { sendEmail, sendTemplatedEmail, sendLocalizedEmail, getEmailTemplate } = await import("./services/sendgridEmailService");
      const { subject, htmlContent, textContent, templateId, templateVariables, applicationId, useLocalized, localizedTemplateKey, overrideThrottle, overrideJustification } = req.body;

      const user = await db.query.users.findFirst({ where: (users: any, { eq }: any) => eq(users.id, userId) });

      if (overrideThrottle) {
        if (!user?.role || !['admin', 'super_user', 'recruiting_admin'].includes(user.role)) {
          return res.status(403).json({ message: "Only admins can override throttle limits" });
        }
        if (!overrideJustification || overrideJustification.trim().length === 0) {
          return res.status(400).json({ message: "Override justification is required" });
        }
      }
      
      let result;
      
      if (useLocalized && localizedTemplateKey) {
        const localizedResult = await sendLocalizedEmail(
          req.params.id,
          localizedTemplateKey,
          templateVariables || {},
          userId,
          applicationId
        );
        
        if (localizedResult.success) {
          return res.json({ 
            success: true, 
            messageId: localizedResult.messageId,
            languageUsed: localizedResult.languageUsed,
            usedFallback: localizedResult.usedFallback,
          });
        }
        
        return res.status(400).json({ 
          message: localizedResult.error,
          blockedReason: localizedResult.blockedReason,
          nextAllowedAt: (localizedResult as any).nextAllowedAt,
          dailyCount: (localizedResult as any).dailyCount,
          maxPerDay: (localizedResult as any).maxPerDay,
        });
      } else if (templateId) {
        const template = getEmailTemplate(templateId);
        if (!template) {
          return res.status(400).json({ message: "Email template not found" });
        }
        result = await sendTemplatedEmail(
          req.params.id,
          template,
          templateVariables || {},
          userId,
          applicationId
        );
      } else {
        if (!subject || !htmlContent) {
          return res.status(400).json({ message: "Subject and content are required" });
        }
        result = await sendEmail(
          req.params.id,
          subject,
          htmlContent,
          textContent || '',
          userId,
          applicationId,
          undefined,
          { overrideThrottle, overrideJustification, senderEmail: user?.email || null }
        );
      }
      
      if (!result.success) {
        return res.status(400).json({ 
          message: result.error,
          blockedReason: result.blockedReason,
          nextAllowedAt: result.nextAllowedAt,
          dailyCount: result.dailyCount,
          maxPerDay: result.maxPerDay,
        });
      }

      res.json({ 
        success: true, 
        messageId: result.messageId,
      });
    } catch (error: any) {
      console.error("[Communications] Error sending email:", error);
      res.status(500).json({ message: "Failed to send email" });
    }
  });

