  // Twilio inbound SMS webhook
  app.post("/webhooks/twilio/sms", async (req: Request, res: Response) => {
    try {
      const { handleInboundSms, validateTwilioWebhook } = await import("./services/twilioSmsService");
      
      // Validate Twilio signature in production
      const authToken = process.env.TWILIO_AUTH_TOKEN;
      if (authToken && process.env.NODE_ENV === 'production') {
        const signature = req.headers['x-twilio-signature'] as string;
        const url = `${req.protocol}://${req.get("host")}${req.originalUrl}`;
        if (!validateTwilioWebhook(authToken, signature, url, req.body)) {
          console.log('[Twilio] Invalid webhook signature');
          return res.status(403).send('Forbidden');
        }
      }

      await handleInboundSms({
        from: req.body.From,
        to: req.body.To,
        body: req.body.Body,
        messageSid: req.body.MessageSid,
        accountSid: req.body.AccountSid,
        numMedia: req.body.NumMedia,
      });

      // Respond with empty TwiML
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
    } catch (error) {
      console.error("[Twilio] Webhook error:", error);
      res.type('text/xml');
      res.send('<?xml version="1.0" encoding="UTF-8"?><Response></Response>');
    }
  });

