  // Provider webhook endpoint (generic)
  app.post("/webhooks/background-check/:provider", async (req: Request, res: Response) => {
    try {
      const { handleProviderWebhook } = await import("./services/backgroundCheckService");
      const provider = req.params.provider;
      
      // Parse webhook based on provider format
      let providerCheckId: string;
      let status: 'in_progress' | 'completed' | 'failed';
      let result: any;

      if (provider === 'checkr') {
        // Checkr webhook format
        const { id, status: checkrStatus, result: checkrResult } = req.body;
        providerCheckId = id;
        status = checkrStatus === 'complete' ? 'completed' : 
                 checkrStatus === 'pending' ? 'in_progress' : 'failed';
        if (checkrResult) {
          result = {
            status: checkrResult === 'clear' ? 'clear' : 'consider',
            summary: checkrResult === 'clear' 
              ? 'Background check completed with no issues.'
              : 'Background check requires review.',
            completedAt: new Date(),
          };
        }
      } else {
        // Generic webhook format
        providerCheckId = req.body.check_id || req.body.checkId;
        status = req.body.status;
        result = req.body.result;
      }

      if (!providerCheckId || !status) {
        return res.status(400).json({ message: "Invalid webhook payload" });
      }

      await handleProviderWebhook(provider, providerCheckId, status, result);
      res.status(200).send('OK');
    } catch (error) {
      console.error("[BackgroundCheck] Webhook error:", error);
      res.status(200).send('OK'); // Return 200 to prevent retries
    }
  });

