  // GET /api/recruiting/reports/export - Export report data as CSV (market-restricted)
  app.get("/api/recruiting/reports/export", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Authentication required" });
    }
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: (users, { eq }) => eq(users.id, userId),
      });
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      
      // Check read permission (required for export)
      if (!hasPermission(recruitingContext, "read")) {
        return res.status(403).json({ message: "No permission to export data" });
      }

      // Check export permission (may require higher permissions or admin for cross-market exports)
      const requestedMarket = req.query.market as string | undefined;
      const exportCheck = checkExportPermission(recruitingContext, requestedMarket);
      if (!exportCheck.allowed) {
        return res.status(403).json({ message: exportCheck.reason });
      }

      const { getReportDataForExport } = await import("./services/recruitingReportingService");
      const filters = {
        startDate: req.query.startDate ? new Date(req.query.startDate as string) : undefined,
        endDate: req.query.endDate ? new Date(req.query.endDate as string) : undefined,
        market: requestedMarket,
        requisitionId: req.query.requisitionId as string | undefined,
        // Apply market restrictions for non-admin users
        authorizedMarkets: recruitingContext.isAdmin ? null : recruitingContext.authorizedMarkets,
      };
      
      const data = await getReportDataForExport(filters);
      
      if (data.length === 0) {
        return res.status(404).json({ message: "No data to export" });
      }
      
      const headers = Object.keys(data[0]);
      const csvRows = [headers.join(',')];
      
      for (const row of data) {
        const values = headers.map(h => {
          const val = row[h];
          if (val === null || val === undefined) return '';
          const str = String(val);
          return str.includes(',') || str.includes('"') || str.includes('\n') 
            ? `"${str.replace(/"/g, '""')}"` 
            : str;
        });
        csvRows.push(values.join(','));
      }
      
      const csv = csvRows.join('\n');
      
      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', `attachment; filename="recruiting-report-${new Date().toISOString().split('T')[0]}.csv"`);
      res.send(csv);
    } catch (error: any) {
      console.error("[Reporting] Export error:", error);
      res.status(500).json({ message: "Failed to export data" });
    }
  });


