  // GET /api/recruiting/candidate/:id/summary - Get candidate summary for scheduling
  app.get("/api/recruiting/candidate/:id/summary", async (req: Request, res: Response) => {
    // System-to-system authentication via API key
    const apiKey = req.headers['x-api-key'] || req.query.apiKey;
    const isSystemAuth = apiKey === process.env.DRIVERHUB_API_KEY;
    
    if (!isSystemAuth && !req.isAuthenticated()) {
      return res.status(401).json({ 
        error: "UNAUTHORIZED",
        message: "Valid API key or authentication required" 
      });
    }
    
    try {
      const { getCandidateSummary } = await import("./services/schedulingIntegrationService");
      const summary = await getCandidateSummary(req.params.id);
      
      if (!summary) {
        return res.status(404).json({ 
          error: "NOT_FOUND",
          message: "Candidate not found or not in ready status" 
        });
      }
      
      res.json({
        success: true,
        data: summary,
      });
    } catch (error: any) {
      console.error("[Scheduling] Candidate summary error:", error);
      res.status(500).json({ 
        error: "INTERNAL_ERROR",
        message: "Failed to retrieve candidate summary" 
      });
    }
  });

