  // POST /api/recruiting/documents/:id/send-for-signature - Send document for e-signature
  app.post("/api/recruiting/documents/:id/send-for-signature", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Authentication required" });
    }
    const user = req.user as any;
    if (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'recruiter') {
      return res.status(403).json({ message: "Permission denied. Recruiting Admin or Recruiter role required." });
    }
    try {
      const { sendDocumentForSignature } = await import("./services/esignService");
      const { provider, recipientEmail, recipientName, subject, message } = req.body;
      
      if (!provider || !recipientEmail || !recipientName || !subject) {
        return res.status(400).json({ message: "provider, recipientEmail, recipientName, and subject are required" });
      }
      
      const result = await sendDocumentForSignature(
        req.params.id,
        provider,
        recipientEmail,
        recipientName,
        subject,
        message,
        user.id
      );
      
      if (!result.success) {
        return res.status(400).json({ message: result.error });
      }
      
      res.json(result);
    } catch (error: any) {
      console.error("[Esign] Send error:", error);
      res.status(500).json({ message: error.message || "Failed to send for signature" });
    }
  });

