  // PATCH /api/recruiting/documents/:id/esign/status - Manually update e-sign status (v1)
  app.patch("/api/recruiting/documents/:id/esign/status", async (req: Request, res: Response) => {
    if (!req.isAuthenticated()) {
      return res.status(401).json({ message: "Authentication required" });
    }
    const user = req.user as any;
    if (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'recruiter') {
      return res.status(403).json({ message: "Permission denied" });
    }
    try {
      const { updateEsignStatusManually } = await import("./services/esignService");
      const { status, declineReason, signedDocumentUrl } = req.body;
      
      if (!status || !['viewed', 'signed', 'declined'].includes(status)) {
        return res.status(400).json({ message: "status must be 'viewed', 'signed', or 'declined'" });
      }
      
      const result = await updateEsignStatusManually(req.params.id, status, user.id, {
        declineReason,
        signedDocumentUrl,
      });
      
      if (!result.success) {
        return res.status(400).json({ message: result.error });
      }

      // Trigger readiness regression check if document was declined
      if (status === "declined") {
        try {
          const [docRecord] = await db.select({ applicationId: recruitingDocuments.applicationId }).from(recruitingDocuments).where(eq(recruitingDocuments.id, req.params.id)).limit(1);
          if (docRecord?.applicationId) {
            const { handleReadinessRegression } = await import("./services/readinessRegressionService");
            await handleReadinessRegression(docRecord.applicationId, {
              reason: "docs_incomplete",
              details: `Document "${req.params.id}" was declined by signer`,
              triggerEntityType: "document",
              triggerEntityId: req.params.id,
            }, user.id, user.email || "");
          }
        } catch (regressionErr) {
          console.error("[Regression] Error triggering document regression:", regressionErr);
        }
      }
      
      res.json({ success: true });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Failed to update status" });
    }
  });

  // POST /webhooks/esign/:provider - E-sign provider webhook
  app.post("/webhooks/esign/:provider", async (req: Request, res: Response) => {
    try {
      const { handleEsignWebhook } = await import("./services/esignService");
      const provider = req.params.provider;
      
      // Parse webhook based on provider format
      let envelopeId: string;
      let event: string;
      let data: Record<string, any> = {};

      if (provider === 'docusign') {
        // DocuSign Connect webhook format
        envelopeId = req.body.envelopeId || req.body.data?.envelopeId;
        event = req.body.event || 'envelope-completed';
        data = req.body;
      } else if (provider === 'signeasy') {
        // Signeasy webhook format
        envelopeId = req.body.envelope_id;
        event = req.body.event;
        data = req.body;
      } else {
        // Generic format
        envelopeId = req.body.envelope_id || req.body.envelopeId;
        event = req.body.event || req.body.status;
        data = req.body;
      }

      if (!envelopeId || !event) {
        return res.status(400).json({ message: "Invalid webhook payload" });
      }

      await handleEsignWebhook(provider, envelopeId, event, data);
      res.status(200).send('OK');
    } catch (error) {
      console.error("[Esign] Webhook error:", error);
      res.status(200).send('OK'); // Return 200 to prevent retries
    }
  });

