  // GET /api/recruiting/applications/:id/timeline - Get application activity timeline
  app.get("/api/recruiting/applications/:id/timeline", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const { id } = req.params;
      const { eventTypes, limit, offset } = req.query;

      const filters: {
        eventTypes?: string[];
        limit?: number;
        offset?: number;
      } = {};

      if (eventTypes) {
        filters.eventTypes = Array.isArray(eventTypes) 
          ? eventTypes as string[] 
          : (eventTypes as string).split(",");
      }
      if (limit) filters.limit = parseInt(limit as string);
      if (offset) filters.offset = parseInt(offset as string);

      const { getApplicationTimeline } = await import("./recruitingService");
      const result = await getApplicationTimeline(id, filters);
      res.json(result);
    } catch (error) {
      console.error("[Recruiting] Error fetching application timeline:", error);
      res.status(500).json({ message: "Failed to fetch timeline" });
    }
  });

