  // ============================================================================
  // CANDIDATE TIMELINE EXPORT - PDF/CSV export for legal/insurer evidence
  // ============================================================================

  app.post("/api/recruiting/applications/:id/timeline/export", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated && req.isAuthenticated() && (req.user as any)?.claims?.sub) {
        userId = (req.user as any).claims.sub;
      }

      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const user = await db.query.users.findFirst({
        where: eq(users.id, userId),
      });

      if (!user) {
        return res.status(401).json({ message: "User not found" });
      }

      const allowedRoles = ["admin", "super_user", "recruiting_admin"];
      if (!user.role || !allowedRoles.includes(user.role)) {
        return res.status(403).json({ message: "Admin access required for timeline exports" });
      }

      const { id } = req.params;
      const { format: exportFormat = "pdf" } = req.body || {};

      if (!["pdf", "csv"].includes(exportFormat)) {
        return res.status(400).json({ message: "Invalid format. Use 'pdf' or 'csv'." });
      }

      const { exportTimelineCsv, exportTimelinePdf, logExport } = await import("./services/recruitingExportService");

      const result = exportFormat === "pdf"
        ? await exportTimelinePdf(id, user.email)
        : await exportTimelineCsv(id, user.email);

      await logExport({
        exportType: "candidate_timeline",
        exportFormat: exportFormat as any,
        exportedBy: user.id,
        exportedByEmail: user.email,
        filters: { applicationId: id } as any,
        recordCount: result.recordCount,
        watermark: result.watermark,
        fileSizeBytes: result.fileSizeBytes,
        ipAddress: req.ip,
        userAgent: req.headers["user-agent"],
        reason: `Timeline export for application ${id}`,
      });

      res.setHeader("Content-Type", result.contentType);
      res.setHeader("Content-Disposition", `attachment; filename="${result.filename}"`);
      res.setHeader("X-Export-Watermark", result.watermark);
      res.setHeader("X-Export-Record-Count", String(result.recordCount));
      res.send(result.data);
    } catch (error) {
      console.error("[Recruiting] Error exporting timeline:", error);
      res.status(500).json({ message: "Failed to export timeline" });
    }
  });

