  // POST /api/recruiting/candidates/:id/reactivate - Reactivate an archived candidate
  app.post("/api/recruiting/candidates/:id/reactivate", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const user = await storage.getUser(userId);
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user' && user.role !== 'recruiter')) {
        return res.status(403).json({ message: "Forbidden: Recruiter or Admin access required" });
      }

      const { candidateReactivationService } = await import("./services/candidateReactivationService");
      const { id: candidateId } = req.params;
      const { reason } = req.body;

      if (!reason) {
        return res.status(400).json({ message: "Reactivation reason is required" });
      }

      // Check DNR status before reactivation
      const { checkCandidateDnrStatus } = await import("./recruitingService");
      const dnrStatus = await checkCandidateDnrStatus(candidateId);
      if (dnrStatus.isDnr && !dnrStatus.hasOverride) {
        return res.status(403).json({
          message: "This candidate is flagged as Do-Not-Rehire and cannot be reactivated.",
          dnr: true,
          dnrReasonCode: dnrStatus.dnrReasonCode,
        });
      }

      const result = await candidateReactivationService.reactivateCandidate(candidateId, userId, reason);
      
      if (!result.success) {
        return res.status(400).json({ message: result.message });
      }

      res.json(result);
    } catch (error) {
      console.error("[Recruiting] Error reactivating candidate:", error);
      res.status(500).json({ message: "Failed to reactivate candidate" });
    }
  });

  // POST /api/recruiting/candidates/:id/rehire-application - Create rehire application
  app.post("/api/recruiting/candidates/:id/rehire-application", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const user = await storage.getUser(userId);
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user' && user.role !== 'recruiter')) {
        return res.status(403).json({ message: "Forbidden: Recruiter or Admin access required" });
      }

      const { candidateReactivationService } = await import("./services/candidateReactivationService");
      const { id: candidateId } = req.params;
      const { requisitionId, reason, preserveOwner, runComplianceCheck, autoTagRehire, previousApplicationId } = req.body;

      if (!requisitionId) {
        return res.status(400).json({ message: "Requisition ID is required" });
      }

      // Check DNR status before rehire
      const { checkCandidateDnrStatus: checkDnr } = await import("./recruitingService");
      const dnrCheck = await checkDnr(candidateId);
      if (dnrCheck.isDnr && !dnrCheck.hasOverride) {
        return res.status(403).json({
          message: "This candidate is flagged as Do-Not-Rehire and cannot have rehire applications created.",
          dnr: true,
          dnrReasonCode: dnrCheck.dnrReasonCode,
        });
      }

      const result = await candidateReactivationService.createRehireApplication(
        candidateId, 
        requisitionId, 
        userId,
        reason || "Rehire application",
        {
          preserveOwner: preserveOwner ?? true,
          runComplianceCheck: runComplianceCheck ?? true,
          autoTagRehire: autoTagRehire ?? true,
          previousApplicationId
        }
      );
      
      if (!result.success) {
        return res.status(400).json({ message: result.message, complianceIssues: result.complianceIssues });
      }

      res.json(result);
    } catch (error: any) {
      console.error("[Recruiting] Error creating rehire application:", error);
      if (error?.message?.includes("already attached") || error?.message?.includes("already exists")) {
        return res.status(409).json({ message: "Candidate is already attached to this job posting." });
      }
      if (error?.code === '23505') {
        return res.status(409).json({ message: "Candidate is already attached to this job posting." });
      }
      res.status(500).json({ message: "Failed to create rehire application" });
    }
  });

