  // POST /api/recruiting/bulk/archive - Bulk archive applications
  app.post("/api/recruiting/bulk/archive", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      const { applicationIds, reason } = req.body;

      if (!applicationIds || !Array.isArray(applicationIds) || applicationIds.length === 0) {
        return res.status(400).json({ message: "Application IDs required" });
      }

      const { enforceApplicationLock: enforceBulkArchiveLock } = await import("./recruitingService");
      const lockedArchiveIds: string[] = [];
      for (const appId of applicationIds) {
        const lr = await enforceBulkArchiveLock(appId, userId);
        if (!lr.allowed) lockedArchiveIds.push(appId);
      }
      if (lockedArchiveIds.length > 0) {
        return res.status(409).json({
          message: `${lockedArchiveIds.length} application(s) are locked by other users`,
          lockedApplicationIds: lockedArchiveIds,
        });
      }

      const { bulkArchiveApplications } = await import("./recruitingService");
      const result = await bulkArchiveApplications(applicationIds, userId, reason);
      res.json(result);
    } catch (error) {
      console.error("[Recruiting] Error bulk archiving applications:", error);
      res.status(500).json({ message: "Failed to bulk archive applications" });
    }
  });

