  app.post("/api/recruiting/retention/rules", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Use shared schema for validation to maintain consistency with DB constraints
      const parseResult = insertRecruitingRetentionRuleSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          message: "Invalid request body", 
          errors: parseResult.error.flatten().fieldErrors 
        });
      }

      // Normalize state (uppercase) and market (trim) before saving
      const normalizedData = {
        ...parseResult.data,
        state: parseResult.data.state?.toUpperCase()?.trim() || null,
        market: parseResult.data.market?.trim() || null,
      };

      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      const { createRecruitingRetentionRule } = await import("./recruitingService");
      const rule = await createRecruitingRetentionRule(normalizedData, userId);
      res.status(201).json(rule);
    } catch (error) {
      console.error("[Recruiting] Error creating retention rule:", error);
      res.status(500).json({ message: "Failed to create retention rule" });
    }
  });

  // PATCH /api/recruiting/retention/rules/:id - Update a retention rule
  app.patch("/api/recruiting/retention/rules/:id", async (req: Request, res: Response) => {
    try {
      if (!req.isAuthenticated()) {
        return res.status(401).json({ message: "Not authenticated" });
      }

      // Use partial shared schema for update validation
      const updateSchema = insertRecruitingRetentionRuleSchema.partial();
      const parseResult = updateSchema.safeParse(req.body);
      if (!parseResult.success) {
        return res.status(400).json({ 
          message: "Invalid request body", 
          errors: parseResult.error.flatten().fieldErrors 
        });
      }

      // Normalize state (uppercase) and market (trim) if provided
      const normalizedData: any = { ...parseResult.data };
      if ('state' in normalizedData && normalizedData.state) {
        normalizedData.state = normalizedData.state.toUpperCase().trim();
      }
      if ('market' in normalizedData && normalizedData.market) {
        normalizedData.market = normalizedData.market.trim();
      }

      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      const { updateRecruitingRetentionRule } = await import("./recruitingService");
      const rule = await updateRecruitingRetentionRule(req.params.id, normalizedData, userId);
      
      if (!rule) {
        return res.status(404).json({ message: "Retention rule not found" });
      }
      
      res.json(rule);
    } catch (error) {
      console.error("[Recruiting] Error updating retention rule:", error);
      res.status(500).json({ message: "Failed to update retention rule" });
    }
  });
