  // Sync single invoice to QuickBooks
  app.post("/api/corporate/invoicing/invoices/:id/sync-quickbooks", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const invUser = { id: req.user.claims.sub, email: user?.email || "", role: user?.role };
      assertInvoicingPermission(invUser, 'integration:quickbooks', 'quickbooks_sync');
      
      const settings = await storage.getQuickbooksSettings();
      if (!settings?.isConnected) {
        return res.status(400).json({ message: "QuickBooks is not connected" });
      }
      
      const invoice = await storage.getInvoice(req.params.id);
      if (!invoice) {
        return res.status(404).json({ message: "Invoice not found" });
      }

      const qbIdempKey = req.headers['x-idempotency-key'] || req.headers['idempotency-key'];
      if (qbIdempKey) {
        const qbHash = hashRequestBody({ invoiceId: req.params.id, action: 'qb_sync' });
        const qbIdempResult = await checkIdempotency('qb_invoice_sync', qbIdempKey, qbHash, req.user.claims.sub);
        if (!qbIdempResult.isNew && qbIdempResult.cachedResponse) {
          console.log('[Idempotency] Returning cached response for QB sync key:', qbIdempKey);
          return res.status(qbIdempResult.cachedResponse.status).json(qbIdempResult.cachedResponse.body);
        }
      }

      const existingSyncStatus = (invoice as any).qbSyncStatus;
      if (existingSyncStatus === 'processing') {
        if (qbIdempKey) {
          await storage.finalizeIdempotencyKey('qb_invoice_sync', qbIdempKey, 409, { message: 'QuickBooks sync is already in progress for this invoice' });
        }
        return res.status(409).json({ message: "QuickBooks sync is already in progress for this invoice" });
      }
      
      await storage.updateQuickbooksSyncStatus('invoice', req.params.id, 'processing');
      
      try {
        const qbInvoiceId = `QB_INV_${Date.now()}`;
        await storage.updateQuickbooksSyncStatus('invoice', req.params.id, 'synced', undefined, qbInvoiceId);
        
        const responseBody = { 
          success: true, 
          qbInvoiceId,
          message: "Invoice synced to QuickBooks successfully" 
        };

        await storage.logInvoicingAction({
          userId: req.user.claims.sub,
          action: "quickbooks_sync",
          resourceType: "invoice",
          resourceId: req.params.id,
          details: { qbInvoiceId, syncType: 'invoice' },
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"] || null,
        });

        if (qbIdempKey) {
          await storage.finalizeIdempotencyKey('qb_invoice_sync', qbIdempKey, 200, responseBody, req.params.id);
        }

        res.json(responseBody);
      } catch (syncError: any) {
        await storage.updateQuickbooksSyncStatus('invoice', req.params.id, 'failed', syncError.message);
        throw syncError;
      }
    } catch (error: any) {
      if (error instanceof InvoicingPermissionError) {
        return res.status(403).json({ message: error.message });
      }
      console.error("Error syncing invoice to QuickBooks:", error);
      const qbIdempKeyErr = req.headers['x-idempotency-key'] || req.headers['idempotency-key'];
      if (qbIdempKeyErr) {
        try { await storage.finalizeIdempotencyKey('qb_invoice_sync', qbIdempKeyErr, 500, { message: 'Failed to sync' }); } catch (e) {}
      }
      if (error.message?.includes('already in progress')) {
        return res.status(409).json({ message: error.message });
      }
      res.status(500).json({ message: error.message || "Failed to sync invoice to QuickBooks" });
    }
  });

