  // ── QuickBooks Web Connector (QBWC) SOAP Endpoint ────────────────────────────
  // QBWC calls this endpoint directly — no session auth middleware.
  // Authentication is handled via SOAP authenticate() using stored QBWC credentials.

  // POST /api/qbwc — primary SOAP endpoint for QB Web Connector
  app.post("/api/qbwc", express.text({ type: "text/xml", limit: "10mb" }), async (req: any, res: Response) => {
    try {
      const xmlBody = req.body ?? "";
      const { handleSoapRequest } = await import("./services/qbwcService");
      const soapResponse = await handleSoapRequest(xmlBody);
      res.set("Content-Type", "text/xml; charset=utf-8");
      res.send(soapResponse);
    } catch (error: any) {
      console.error("[QBWC] SOAP handler error:", error.message);
      res.status(500).set("Content-Type", "text/xml").send(
        `<?xml version="1.0"?><soap:Envelope xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/"><soap:Body><soap:Fault><faultcode>soap:Server</faultcode><faultstring>${error.message}</faultstring></soap:Fault></soap:Body></soap:Envelope>`
      );
    }
  });

  // GET /api/qbwc/qwc — download the .qwc config file for QB Web Connector setup
  app.get("/api/qbwc/qwc", async (req: any, res: Response) => {
    try {
      const { getQbwcSettings } = await import("./services/qbwcService");
      const settings = await getQbwcSettings();
      const host = req.headers["x-forwarded-host"] ?? req.headers.host ?? "localhost:5000";
      const proto = req.headers["x-forwarded-proto"] ?? (req.secure ? "https" : "http");
      const appUrl = `${proto}://${host}/api/qbwc`;
      const ownerGuid = `{${settings.ownerGuid}}`;
      const fileGuid  = `{${settings.fileGuid}}`;
      const username  = settings.username ?? "driverhub-sync";
      const qwc = `<?xml version="1.0"?>
<QBWCXML>
  <AppName>DriverHub 360</AppName>
  <AppID></AppID>
  <AppURL>${appUrl}</AppURL>
  <AppDescription>DriverHub 360 QuickBooks Desktop Sync</AppDescription>
  <AppSupport>${proto}://${host}/support</AppSupport>
  <UserName>${username}</UserName>
  <OwnerID>${ownerGuid}</OwnerID>
  <FileID>${fileGuid}</FileID>
  <QBType>QBFS</QBType>
  <Scheduler>
    <RunEveryNMinutes>60</RunEveryNMinutes>
  </Scheduler>
  <IsReadOnly>true</IsReadOnly>
</QBWCXML>`;
      res.set("Content-Type", "application/xml");
      res.set("Content-Disposition", 'attachment; filename="DriverHub360.qwc"');
      res.send(qwc);
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

