  // GET /api/finance/qb/ar/aging — AR aging buckets (current, 1-30, 31-60, 61-90, 91+)
  app.get("/api/finance/qb/ar/aging", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasFinanceModuleAccess } = await import("./services/financePermissionsService");
      if (!await hasFinanceModuleAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_ACCESS_DENIED", message: "Finance module access required" });
      }
      const { db } = await import("./db");
      const { sql } = await import("drizzle-orm");
      const result = await db.execute(sql`
        SELECT
          COUNT(*) FILTER (WHERE balance > 0 AND (due_date IS NULL OR due_date >= CURRENT_DATE))                        AS current_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0 AND (due_date IS NULL OR due_date >= CURRENT_DATE)), 0)       AS current_amount,

          COUNT(*) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date <= 30)            AS days_1_30_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date <= 30), 0) AS days_1_30_amount,

          COUNT(*) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date BETWEEN 31 AND 60)  AS days_31_60_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date BETWEEN 31 AND 60), 0) AS days_31_60_amount,

          COUNT(*) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date BETWEEN 61 AND 90)  AS days_61_90_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date BETWEEN 61 AND 90), 0) AS days_61_90_amount,

          COUNT(*) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date > 90)              AS days_91_plus_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0 AND due_date < CURRENT_DATE AND CURRENT_DATE - due_date > 90), 0) AS days_91_plus_amount,

          COUNT(*) FILTER (WHERE balance > 0)                                                                            AS total_open_count,
          COALESCE(SUM(balance) FILTER (WHERE balance > 0), 0)                                                           AS total_open_amount
        FROM qbo_ar_transactions
        WHERE qbo_txn_type = 'Invoice'
          AND is_voided = false
          AND sync_status = 'ok'
      `);
      const row = ((result.rows ?? result) as any[])[0] ?? {};
      res.json({
        asOf: new Date().toISOString().slice(0, 10),
        buckets: [
          { label: "Current",   days: "0",   count: Number(row.current_count    ?? 0), amount: parseFloat(row.current_amount    ?? "0") },
          { label: "1–30 days", days: "1-30", count: Number(row.days_1_30_count  ?? 0), amount: parseFloat(row.days_1_30_amount  ?? "0") },
          { label: "31–60 days",days: "31-60",count: Number(row.days_31_60_count ?? 0), amount: parseFloat(row.days_31_60_amount ?? "0") },
          { label: "61–90 days",days: "61-90",count: Number(row.days_61_90_count ?? 0), amount: parseFloat(row.days_61_90_amount ?? "0") },
          { label: "91+ days",  days: "91+",  count: Number(row.days_91_plus_count ?? 0), amount: parseFloat(row.days_91_plus_amount ?? "0") },
        ],
        totalOpenCount:  Number(row.total_open_count  ?? 0),
        totalOpenAmount: parseFloat(row.total_open_amount ?? "0"),
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // ── Finance Local Data API — queries local tables, NEVER hits QB API ─────────
  // These endpoints serve Finance dashboards from the local QB mirror.
  // No live QB connectivity required for dashboard loads.

  // GET /api/finance/local/customers — QB customer list with DH mapping status
  app.get("/api/finance/local/customers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasFinanceModuleAccess } = await import("./services/financePermissionsService");
      if (!await hasFinanceModuleAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_ACCESS_DENIED", message: "Finance module access required" });
      }
      const { getLocalCustomers } = await import("./services/qboImportService");
      const search        = req.query.search        ? String(req.query.search)        : undefined;
      const mappingStatus = req.query.mappingStatus  ? String(req.query.mappingStatus)  : undefined;
      const limit         = Math.min(parseInt(String(req.query.limit  ?? "100")), 500);
      const offset        = parseInt(String(req.query.offset ?? "0"));
      const data = await getLocalCustomers({ search, mappingStatus, limit, offset });
      res.json({ data, limit, offset });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // PUT /api/finance/local/customers/:qboCustomerId/map — map QB customer to DH account
  app.put("/api/finance/local/customers/:qboCustomerId/map", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasQbSyncManageAccess } = await import("./services/financePermissionsService");
      if (!await hasQbSyncManageAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_QBSYNC_DENIED", message: "QuickBooks sync management access required" });
      }
      const { db } = await import("./db");
      const { qboCustomers } = await import("../shared/schema");
      const { eq } = await import("drizzle-orm");
      const { dhAccountId, mappingStatus, mappingNote } = req.body ?? {};
      await db.update(qboCustomers)
        .set({
          dhAccountId:    dhAccountId ?? null,
          mappingStatus:  mappingStatus ?? (dhAccountId ? "mapped" : "unmapped"),
          mappingNote:    mappingNote ?? null,
          mappedBy:       user?.id ?? null,
          mappedAt:       new Date(),
          updatedAt:      new Date(),
        })
        .where(eq(qboCustomers.qboCustomerId, req.params.qboCustomerId));
      res.json({ message: "Customer mapping updated" });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // GET /api/finance/local/ar-transactions — AR transactions from local mirror
  app.get("/api/finance/local/ar-transactions", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasFinanceModuleAccess } = await import("./services/financePermissionsService");
      if (!await hasFinanceModuleAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_ACCESS_DENIED", message: "Finance module access required" });
      }
      const { getLocalARTransactions } = await import("./services/qboImportService");
      const now   = new Date();
      const since = req.query.since  ? String(req.query.since)  : new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
      const until = req.query.until  ? String(req.query.until)  : now.toISOString().slice(0, 10);
      const txnType   = req.query.txnType    ? String(req.query.txnType)   : undefined;
      const customerId = req.query.customerId ? String(req.query.customerId): undefined;
      const isPaid    = req.query.isPaid !== undefined ? req.query.isPaid === "true" : undefined;
      const limit     = Math.min(parseInt(String(req.query.limit  ?? "100")), 500);
      const offset    = parseInt(String(req.query.offset ?? "0"));
      const data = await getLocalARTransactions({ since, until, txnType, customerId, isPaid, limit, offset });
      res.json({ data, since, until, limit, offset });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

