  // GET /api/finance/local/vendors — QB vendor list with mapping status
  app.get("/api/finance/local/vendors", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasFinanceModuleAccess } = await import("./services/financePermissionsService");
      if (!await hasFinanceModuleAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_ACCESS_DENIED", message: "Finance module access required" });
      }
      const { db } = await import("./db");
      const { sql: drizzleSql2 } = await import("drizzle-orm");
      const search   = req.query.search ? String(req.query.search) : null;
      const isMapped = req.query.isMapped !== undefined ? req.query.isMapped === "true" : null;
      const limit    = Math.min(parseInt(String(req.query.limit  ?? "100")), 500);
      const offset   = parseInt(String(req.query.offset ?? "0"));
      const result = await db.execute(drizzleSql2`
        SELECT
          qbo_vendor_id, display_name, company_name, email, phone,
          is_active, expense_category, is_mapped, sync_status, last_sync_at,
          source_system
        FROM qbo_vendors
        WHERE (${search} IS NULL OR display_name ILIKE ${'%' + (search ?? '') + '%'})
          AND (${isMapped} IS NULL OR is_mapped = ${isMapped})
        ORDER BY display_name
        LIMIT ${limit} OFFSET ${offset}
      `);
      res.json({ data: result.rows, limit, offset });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

  // GET /api/finance/local/summary — aggregate summary for Finance dashboard
  app.get("/api/finance/local/summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      const { hasFinanceModuleAccess } = await import("./services/financePermissionsService");
      if (!await hasFinanceModuleAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ error_code: "FINANCE_ACCESS_DENIED", message: "Finance module access required" });
      }
      const { db } = await import("./db");
      const { sql: drizzleSql3 } = await import("drizzle-orm");
      const result = await db.execute(drizzleSql3`
        SELECT
          (SELECT COUNT(*) FROM qbo_customers WHERE sync_status = 'ok') AS total_customers,
          (SELECT COUNT(*) FROM qbo_customers WHERE mapping_status = 'unmapped') AS unmapped_customers,
          (SELECT COUNT(*) FROM qbo_vendors WHERE is_active = true) AS active_vendors,
          (SELECT COUNT(*) FROM qbo_vendors WHERE is_mapped = false AND is_active = true) AS unmapped_vendors,
          (SELECT COALESCE(SUM(balance), 0) FROM qbo_ar_transactions WHERE qbo_txn_type = 'Invoice' AND is_voided = false) AS total_ar_balance,
          (SELECT COALESCE(SUM(total_amount), 0) FROM qbo_ar_transactions WHERE qbo_txn_type = 'Invoice' AND txn_date >= CURRENT_DATE - INTERVAL '30 days') AS invoiced_30d,
          (SELECT COALESCE(SUM(total_amount), 0) FROM qbo_ar_transactions WHERE qbo_txn_type = 'Payment' AND txn_date >= CURRENT_DATE - INTERVAL '30 days') AS paid_30d,
          (SELECT COALESCE(SUM(total_amount), 0) FROM qbo_expense_transactions WHERE txn_date >= CURRENT_DATE - INTERVAL '30 days' AND sync_status != 'excluded') AS expenses_30d,
          (SELECT MAX(last_sync_at) FROM qbo_expense_transactions) AS last_expense_sync,
          (SELECT MAX(last_sync_at) FROM qbo_ar_transactions) AS last_ar_sync,
          (SELECT MAX(last_sync_at) FROM qbo_customers) AS last_customer_sync
      `);
      const row = (result.rows ?? result as any[])[0] ?? {};
      res.json({
        customers: {
          total: Number(row.total_customers ?? 0),
          unmapped: Number(row.unmapped_customers ?? 0),
          lastSyncAt: row.last_customer_sync ?? null,
        },
        vendors: {
          active: Number(row.active_vendors ?? 0),
          unmapped: Number(row.unmapped_vendors ?? 0),
        },
        ar: {
          totalBalance: parseFloat(String(row.total_ar_balance ?? 0)),
          invoiced30d: parseFloat(String(row.invoiced_30d ?? 0)),
          paid30d: parseFloat(String(row.paid_30d ?? 0)),
          lastSyncAt: row.last_ar_sync ?? null,
        },
        ap: {
          expenses30d: parseFloat(String(row.expenses_30d ?? 0)),
          lastSyncAt: row.last_expense_sync ?? null,
        },
        sourceSystem: "quickbooks",
        dataMode: "local_mirror",
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message });
    }
  });

