  const requireSuperUser = async (req: any, res: Response, next: Function) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!user || user.role !== "super_user") {
        return res.status(403).json({ error_code: "SUPER_USER_REQUIRED", message: "Super Admin access required" });
      }
      req.adminUser = user;
      next();
    } catch (e) {
      res.status(500).json({ message: "Failed to verify super admin" });
    }
  };

