  // Record payment failure and schedule retries based on config
  app.post("/api/corporate/invoicing/payments/:paymentId/record-failure", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ message: "Forbidden: Finance/Admin access only" });
      }
      
      const { paymentId } = req.params;
      const { failureCode, failureMessage, paymentMethod } = req.body;
      
      // Update payment with failure details
      const payment = await storage.updatePayment(paymentId, {
        status: 'failed',
        failureCode,
        failureMessage,
        failedAt: new Date(),
      });
      
      if (!payment) {
        return res.status(404).json({ message: "Payment not found" });
      }
      
      // Get retry config for this payment method
      const retryConfig = await storage.getPaymentRetryConfigByMethod(paymentMethod || 'credit_card');
      
      let scheduledRetries: any[] = [];
      
      if (retryConfig?.autoRetry && retryConfig.retryScheduleDays?.length > 0) {
        const currentRetryCount = (payment as any).retryCount || 0;
        
        if (currentRetryCount < retryConfig.maxRetries) {
          const now = new Date();
          for (let i = currentRetryCount; i < Math.min(retryConfig.maxRetries, retryConfig.retryScheduleDays.length); i++) {
            const daysToAdd = retryConfig.retryScheduleDays[i];
            const retryAt = new Date(now);
            retryAt.setDate(retryAt.getDate() + daysToAdd);
            
            const attempt = await storage.schedulePaymentRetry(paymentId, retryAt, i + 1);
            scheduledRetries.push(attempt);
          }
          
          // Update payment with retry tracking
          await storage.updatePayment(paymentId, {
            retryCount: currentRetryCount,
            maxRetries: retryConfig.maxRetries,
            nextRetryAt: scheduledRetries[0]?.scheduledAt,
          });
        }
      }
      
      res.json({
        payment,
        scheduledRetries,
        config: retryConfig,
      });
    } catch (error) {
      console.error("Error recording payment failure:", error);
      res.status(500).json({ message: "Failed to record payment failure" });
    }
  });


