  // Batch recalculate AI scores for all customers
  app.post("/api/customers/ai-scores/recalculate-all", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!user || user.role !== 'admin') {
        return res.status(403).json({ message: "Forbidden: Admin access only" });
      }
      
      const customers = await storage.getCustomers();
      const results = {
        total: customers.length,
        success: 0,
        failed: 0,
        errors: [] as string[],
      };
      
      for (const customer of customers) {
        try {
          await storage.updateCustomerAIScore(customer.id);
          results.success++;
        } catch (err) {
          results.failed++;
          results.errors.push(`Customer ${customer.id}: ${(err as Error).message}`);
        }
      }
      
      res.json({
        message: `Recalculated scores for ${results.success}/${results.total} customers`,
        ...results,
      });
    } catch (error) {
      console.error("Error batch recalculating AI scores:", error);
      res.status(500).json({ message: "Failed to recalculate AI scores" });
    }
  });

