  // ==========================================
  // PAYMENT COMMITMENT TRACKING ROUTES
  // ==========================================

  // List payment commitments (with filters)
  app.get("/api/corporate/invoicing/commitments", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const { customerId, status, invoiceId } = req.query;
      let query = db.select().from(paymentCommitments).orderBy(desc(paymentCommitments.createdAt));
      
      const conditions: any[] = [];
      if (customerId) conditions.push(eq(paymentCommitments.customerId, customerId as string));
      if (status && status !== 'all') conditions.push(eq(paymentCommitments.status, status as string));
      
      let commitments;
      if (conditions.length > 0) {
        commitments = await db.select().from(paymentCommitments).where(and(...conditions)).orderBy(desc(paymentCommitments.createdAt));
      } else {
        commitments = await db.select().from(paymentCommitments).orderBy(desc(paymentCommitments.createdAt));
      }

      // If filtering by invoiceId, get commitment IDs linked to that invoice
      if (invoiceId) {
        const linkedCommitmentIds = await db.select({ commitmentId: paymentCommitmentInvoices.commitmentId })
          .from(paymentCommitmentInvoices)
          .where(eq(paymentCommitmentInvoices.invoiceId, invoiceId as string));
        const idSet = new Set(linkedCommitmentIds.map(l => l.commitmentId));
        commitments = commitments.filter(c => idSet.has(c.id));
      }

      // Batch enrich to avoid N+1 queries
      const commitmentIds = commitments.map(c => c.id);
      const customerIds = [...new Set(commitments.map(c => c.customerId))];
      const userIds = [...new Set(commitments.map(c => c.committedBy))];

      const allLinkedInvoices = commitmentIds.length > 0
        ? await db.select({
            commitmentId: paymentCommitmentInvoices.commitmentId,
            invoiceId: paymentCommitmentInvoices.invoiceId,
            allocatedAmount: paymentCommitmentInvoices.allocatedAmount,
            invoiceNumber: invoices.invoiceNumber,
            totalAmount: invoices.totalAmount,
            balanceDue: invoices.balanceDue,
          }).from(paymentCommitmentInvoices)
            .innerJoin(invoices, eq(paymentCommitmentInvoices.invoiceId, invoices.id))
        : [];

      const allCustomers = customerIds.length > 0
        ? await db.select({ id: customers.id, name: customers.customerName }).from(customers)
        : [];
      const customerMap = new Map(allCustomers.map(c => [c.id, c.name]));

      const allUsers = await Promise.all(userIds.map(uid => storage.getUser(uid)));
      const userMap = new Map(userIds.map((uid, i) => [uid, allUsers[i]]));

      const enriched = commitments.map(c => {
        const linked = allLinkedInvoices.filter(li => li.commitmentId === c.id);
        const committedByUser = userMap.get(c.committedBy);
        return {
          ...c,
          committedByName: committedByUser ? `${committedByUser.firstName} ${committedByUser.lastName}` : 'Unknown',
          customerName: customerMap.get(c.customerId) || 'Unknown',
          linkedInvoices: linked,
        };
      });

      res.json(enriched);
    } catch (error) {
      console.error("Error fetching commitments:", error);
      res.status(500).json({ message: "Failed to fetch commitments" });
    }
  });

