  // Create payment commitment
  app.post("/api/corporate/invoicing/commitments", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const bodySchema = z.object({
        customerId: z.string().min(1),
        promisedAmount: z.string().min(1),
        promisedDate: z.string().min(1),
        commitmentNotes: z.string().optional(),
        invoiceIds: z.array(z.string()).optional(),
        allocations: z.array(z.object({
          invoiceId: z.string(),
          allocatedAmount: z.string().optional(),
        })).optional(),
      });

      const validated = bodySchema.parse(req.body);
      const userId = req.user.claims.sub;

      const [commitment] = await db.insert(paymentCommitments).values({
        customerId: validated.customerId,
        promisedAmount: validated.promisedAmount,
        promisedDate: validated.promisedDate,
        commitmentNotes: validated.commitmentNotes || null,
        committedBy: userId,
        status: 'pending',
      }).returning();

      // Link invoices if provided
      const invoiceLinks = validated.allocations || (validated.invoiceIds || []).map(id => ({ invoiceId: id }));
      if (invoiceLinks.length > 0) {
        await db.insert(paymentCommitmentInvoices).values(
          invoiceLinks.map(link => ({
            commitmentId: commitment.id,
            invoiceId: link.invoiceId,
            allocatedAmount: ('allocatedAmount' in link && link.allocatedAmount) ? link.allocatedAmount : null,
          }))
        );
      }

      res.status(201).json(commitment);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error creating commitment:", error);
      res.status(500).json({ message: "Failed to create commitment" });
    }
  });

  // Update commitment (resolve: mark as kept/missed/partial/cancelled)
  app.patch("/api/corporate/invoicing/commitments/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const bodySchema = z.object({
        status: z.enum(['pending', 'kept', 'missed', 'partial', 'cancelled']).optional(),
        actualAmountReceived: z.string().optional(),
        actualPaymentDate: z.string().optional(),
        commitmentNotes: z.string().optional(),
      });

      const validated = bodySchema.parse(req.body);
      const userId = req.user.claims.sub;
      const now = new Date();

      const [existing] = await db.select().from(paymentCommitments).where(eq(paymentCommitments.id, req.params.id));
      if (!existing) return res.status(404).json({ message: "Commitment not found" });

      const updates: any = { updatedAt: now };
      if (validated.commitmentNotes !== undefined) updates.commitmentNotes = validated.commitmentNotes;
      if (validated.actualAmountReceived) updates.actualAmountReceived = validated.actualAmountReceived;
      if (validated.actualPaymentDate) updates.actualPaymentDate = validated.actualPaymentDate;
      
      if (validated.status && validated.status !== 'pending') {
        updates.status = validated.status;
        updates.resolvedAt = now;
        updates.resolvedBy = userId;

        // Calculate SLA metrics
        const promisedDate = new Date(existing.promisedDate);
        const actualDate = validated.actualPaymentDate ? new Date(validated.actualPaymentDate) : now;
        const diffDays = Math.floor((actualDate.getTime() - promisedDate.getTime()) / (1000 * 60 * 60 * 24));
        
        updates.committedOnTime = diffDays <= 0;
        updates.daysLateVsCommitment = Math.max(0, diffDays);
      } else if (validated.status === 'pending') {
        updates.status = 'pending';
        updates.resolvedAt = null;
        updates.resolvedBy = null;
        updates.committedOnTime = null;
        updates.daysLateVsCommitment = null;
      }

      const [updated] = await db.update(paymentCommitments)
        .set(updates)
        .where(eq(paymentCommitments.id, req.params.id))
        .returning();

      res.json(updated);
    } catch (error) {
      if (error instanceof z.ZodError) {
        return res.status(400).json({ message: "Validation error", errors: error.errors });
      }
      console.error("Error updating commitment:", error);
      res.status(500).json({ message: "Failed to update commitment" });
    }
  });

  // Get commitment performance stats for a customer
  app.get("/api/corporate/invoicing/commitments/customer/:customerId/stats", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!await hasFinanceAccess(user?.id ?? "", user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }

      const allCommitments = await db.select().from(paymentCommitments)
        .where(eq(paymentCommitments.customerId, req.params.customerId))
        .orderBy(desc(paymentCommitments.createdAt));

      const total = allCommitments.length;
      const kept = allCommitments.filter(c => c.status === 'kept').length;
      const missed = allCommitments.filter(c => c.status === 'missed').length;
      const partial = allCommitments.filter(c => c.status === 'partial').length;
      const pending = allCommitments.filter(c => c.status === 'pending').length;
      const cancelled = allCommitments.filter(c => c.status === 'cancelled').length;
      const resolved = allCommitments.filter(c => ['kept', 'missed', 'partial'].includes(c.status));
      const onTimeCount = resolved.filter(c => c.committedOnTime).length;
      const onTimeRate = resolved.length > 0 ? Math.round((onTimeCount / resolved.length) * 100) : null;
      const avgDaysLate = resolved.length > 0
        ? Math.round(resolved.reduce((sum, c) => sum + (c.daysLateVsCommitment || 0), 0) / resolved.length)
        : null;
      const totalPromised = allCommitments.reduce((sum, c) => sum + parseFloat(c.promisedAmount || '0'), 0);
      const totalReceived = resolved.reduce((sum, c) => sum + parseFloat(c.actualAmountReceived || '0'), 0);

      // Check for overdue pending commitments (missed SLA)
      const today = new Date();
      const overdueCommitments = allCommitments.filter(c => {
        return c.status === 'pending' && new Date(c.promisedDate) < today;
      });

      res.json({
        total, kept, missed, partial, pending, cancelled,
        onTimeRate, avgDaysLate,
        totalPromised: totalPromised.toFixed(2),
        totalReceived: totalReceived.toFixed(2),
        overdueCount: overdueCommitments.length,
        commitments: allCommitments,
      });
    } catch (error) {
      console.error("Error fetching commitment stats:", error);
      res.status(500).json({ message: "Failed to fetch commitment stats" });
    }
  });

