  // POST /api/recruiting/export - Export recruiting data (admin-only)
  // Supports both OIDC and session-based (password) authentication
  app.post("/api/recruiting/export", async (req: any, res: Response) => {
    try {
      // Support both session-based (password) and OIDC auth
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      const user = await storage.getUser(userId);
      console.log("[Export] User check:", { id: user?.id, role: user?.role, email: user?.email, userId });
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Admin access required for data exports" });
      }

      const { performExport } = await import("./services/recruitingExportService");
      
      const { exportType, filters, reason, exportFormat } = req.body;
      
      if (!exportType || !["candidates", "applications", "audit_log", "document_metadata"].includes(exportType)) {
        return res.status(400).json({ message: "Invalid export type" });
      }

      if (exportFormat === 'json' && exportType === 'audit_log') {
        const { exportAuditLogJson, logExport } = await import("./services/recruitingExportService");
        const result = await exportAuditLogJson(filters || {}, user.email || (req.user?.claims?.email as string) || "unknown");
        await logExport({
          exportType,
          exportFormat: "json",
          exportedBy: user.id,
          exportedByEmail: user.email || (req.user?.claims?.email as string) || "unknown",
          filters: filters || {},
          recordCount: result.recordCount,
          watermark: result.watermark,
          fileSizeBytes: result.fileSizeBytes,
          ipAddress: req.ip,
          userAgent: req.headers["user-agent"],
          reason,
        });
        res.setHeader("Content-Type", "application/json");
        res.setHeader("Content-Disposition", `attachment; filename="${exportType}_export_${new Date().toISOString().split('T')[0]}.json"`);
        return res.send(result.json);
      }

      const result = await performExport(
        exportType,
        filters || {},
        { id: user.id, email: user.email || (req.user?.claims?.email as string) || "unknown" },
        req.ip,
        req.headers["user-agent"],
        reason
      );

      res.setHeader("Content-Type", "text/csv");
      res.setHeader("Content-Disposition", `attachment; filename="${exportType}_export_${new Date().toISOString().split('T')[0]}.csv"`);
      res.send(result.csv);
    } catch (error) {
      console.error("Error exporting recruiting data:", error);
      res.status(500).json({ message: "Failed to export data" });
    }
  });

