  // POST /api/recruiting/merge - Perform a merge operation
  app.post("/api/recruiting/merge", async (req: any, res: Response) => {
    try {
      // Support both session-based (password) and OIDC auth
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      const user = await storage.getUser(userId);
      // Admin or Recruiter can perform merges
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user' && user.role !== 'recruiter')) {
        return res.status(403).json({ message: "Forbidden: Recruiter or Admin access required" });
      }

      const { mergeCandidates } = await import("./services/recruitingMergeService");
      const { sourceId, targetId, matchType, matchConfidence, matchReasons, notes } = req.body;
      
      if (!sourceId || !targetId) {
        return res.status(400).json({ message: "Both sourceId and targetId are required" });
      }
      
      if (!matchType) {
        return res.status(400).json({ message: "matchType is required" });
      }

      const result = await mergeCandidates(
        sourceId,
        targetId,
        matchType,
        matchConfidence || 100,
        matchReasons || [],
        { id: user.id, email: user.email || 'unknown' },
        notes
      );

      if (!result.success) {
        return res.status(400).json({ message: result.message });
      }

      res.json(result);
    } catch (error) {
      console.error("Error merging candidates:", error);
      res.status(500).json({ message: "Failed to merge candidates" });
    }
  });

