  // POST /api/recruiting/notes - Create a new note
  app.post("/api/recruiting/notes", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      const user = await storage.getUser(userId);
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user' && user.role !== 'recruiter' && user.role !== 'hiring_manager')) {
        return res.status(403).json({ message: "Forbidden: Recruiter, Hiring Manager, or Admin access required" });
      }

      const { recruitingNotesService } = await import("./services/recruitingNotesService");
      const { entityType, entityId, body, mentionedUserIds, visibility } = req.body;
      
      if (!entityType || !entityId || !body) {
        return res.status(400).json({ message: "Entity type, entity ID, and body are required" });
      }

      if (!['candidate', 'application', 'requisition'].includes(entityType)) {
        return res.status(400).json({ message: "Invalid entity type" });
      }

      const userName = user.firstName && user.lastName 
        ? `${user.firstName} ${user.lastName}` 
        : user.email;

      const note = await recruitingNotesService.createNote(
        { entityType, entityId, body, mentionedUserIds, visibility },
        userId,
        user.email || '',
        userName || undefined
      );

      res.status(201).json(note);
    } catch (error) {
      console.error("Error creating note:", error);
      res.status(500).json({ message: "Failed to create note" });
    }
  });

