  // POST /api/recruiting/applications/:id/assign - Assign an application to a recruiter
  app.post("/api/recruiting/applications/:id/assign", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      const user = await storage.getUser(userId);
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user' && user.role !== 'recruiter' && user.role !== 'hiring_manager')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }

      const { recruitingAssignmentService } = await import("./services/recruitingAssignmentService");
      const { id } = req.params;
      const { newOwnerId, reason, lastKnownUpdatedAt } = req.body;

      const { enforceApplicationLock: enforceAssignLock } = await import("./recruitingService");
      const lockResult = await enforceAssignLock(id, userId);
      if (!lockResult.allowed) {
        return res.status(409).json({
          message: "Application is locked by another user",
          conflict: lockResult.conflict,
        });
      }

      if (lastKnownUpdatedAt) {
        const { checkConcurrencyConflict } = await import("./recruitingService");
        const conflictResult = await checkConcurrencyConflict(id, lastKnownUpdatedAt);
        if (conflictResult.conflict) {
          return res.status(409).json({
            message: "Application has been modified since your last load. Please refresh and try again.",
            currentUpdatedAt: conflictResult.currentUpdatedAt,
          });
        }
      }

      const result = await recruitingAssignmentService.assignApplication(
        id,
        newOwnerId || null,
        userId,
        reason,
        "manual"
      );

      if (!result.success) {
        return res.status(400).json({ message: result.error });
      }

      res.json(result);
    } catch (error: any) {
      console.error("Error assigning application:", error);
      res.status(500).json({ message: "Failed to assign application" });
    }
  });

