  // PATCH /api/recruiting/demand-signals/:id - Update a demand signal (admin only)
  app.patch("/api/recruiting/demand-signals/:id", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && typeof userEmail !== "undefined") {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Admin access required" });
      }

      const { id } = req.params;
      
      const [existing] = await db.select().from(marketDemandSignals).where(eq(marketDemandSignals.id, id));
      
      if (!existing) {
        return res.status(404).json({ message: "Demand signal not found" });
      }

      const { market, workerType, workType, expectedHeadcount, effectiveFrom, effectiveTo, notes, priority, isActive } = req.body;
      
      const updateData: any = {
        updatedAt: new Date(),
        updatedBy: user.id,
        updatedByEmail: user.email,
      };
      
      const changedFields: string[] = [];
      
      if (market !== undefined && market !== existing.market) {
        updateData.market = market;
        changedFields.push("market");
      }
      if (workerType !== undefined && workerType !== existing.workerType) {
        updateData.workerType = workerType;
        changedFields.push("workerType");
      }
      if (workType !== undefined && workType !== existing.workType) {
        updateData.workType = workType;
        changedFields.push("workType");
      }
      if (expectedHeadcount !== undefined && expectedHeadcount !== existing.expectedHeadcount) {
        updateData.expectedHeadcount = parseInt(expectedHeadcount);
        changedFields.push("expectedHeadcount");
      }
      if (effectiveFrom !== undefined && effectiveFrom !== existing.effectiveFrom) {
        updateData.effectiveFrom = effectiveFrom;
        changedFields.push("effectiveFrom");
      }
      if (effectiveTo !== undefined && effectiveTo !== existing.effectiveTo) {
        updateData.effectiveTo = effectiveTo;
        changedFields.push("effectiveTo");
      }
      if (notes !== undefined && notes !== existing.notes) {
        updateData.notes = notes;
        changedFields.push("notes");
      }
      if (priority !== undefined && priority !== existing.priority) {
        updateData.priority = priority;
        changedFields.push("priority");
      }
      if (isActive !== undefined && isActive !== existing.isActive) {
        updateData.isActive = isActive;
        changedFields.push("isActive");
      }

      const [updated] = await db.update(marketDemandSignals)
        .set(updateData)
        .where(eq(marketDemandSignals.id, id))
        .returning();

      // Log audit event
      await db.insert(recruitingAuditEvents).values({
        actionType: "DEMAND_SIGNAL_UPDATED",
        entityType: "demand_signal",
        entityId: id,
        userId: user.id,
        userEmail: user.email,
        actorRole: user?.role || undefined,
        source: 'ui',
        previousValue: JSON.stringify(existing),
        newValue: JSON.stringify(updated),
        changedFields,
      });

      res.json(updated);
    } catch (error: any) {
      console.error("Error updating demand signal:", error);
      res.status(500).json({ message: "Failed to update demand signal" });
    }
  });

