  // GET /api/recruiting/demand-gap - Get demand vs pipeline gap analysis
  app.get("/api/recruiting/demand-gap", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      const user = await storage.getUser(userId);
      if (!user || (user.role !== 'admin' && user.role !== 'recruiter' && user.role !== 'corporate' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }

      const { market, effectiveDate } = req.query;
      const checkDate = effectiveDate ? new Date(effectiveDate as string) : new Date();
      const checkDateStr = checkDate.toISOString().split('T')[0];

      // Get active demand signals for the date
      let signalsQuery = db.select().from(marketDemandSignals)
        .where(eq(marketDemandSignals.isActive, true));
      
      if (market) {
        signalsQuery = db.select().from(marketDemandSignals)
          .where(and(
            eq(marketDemandSignals.isActive, true),
            eq(marketDemandSignals.market, market as string)
          ));
      }
      
      const signals = await signalsQuery;
      
      // Filter to signals effective for the date
      const effectiveSignals = signals.filter(s => {
        const from = new Date(s.effectiveFrom);
        const to = new Date(s.effectiveTo);
        return checkDate >= from && checkDate <= to;
      });

      // Get pipeline counts per market from ready applications
      const pipelineCounts: Record<string, { ready: number; inProgress: number; total: number }> = {};
      
      // Query applications with readiness status
      const applications = await db.select({
        market: recruitingRequisitions.market,
        readinessStatus: recruitingApplications.readinessStatus,
        currentStage: recruitingApplications.currentStage,
      })
      .from(recruitingApplications)
      .innerJoin(recruitingRequisitions, eq(recruitingApplications.requisitionId, recruitingRequisitions.id))
      .where(
        and(
          isNull(recruitingApplications.disposition),
          eq(recruitingRequisitions.isArchived, false)
        )
      );

      // Aggregate by market
      for (const app of applications) {
        const appMarket = app.market || 'Unknown';
        if (!pipelineCounts[appMarket]) {
          pipelineCounts[appMarket] = { ready: 0, inProgress: 0, total: 0 };
        }
        pipelineCounts[appMarket].total++;
        if (app.readinessStatus === 'ready') {
          pipelineCounts[appMarket].ready++;
        } else {
          pipelineCounts[appMarket].inProgress++;
        }
      }

      // Build gap analysis
      const gapAnalysis = effectiveSignals.map(signal => {
        const pipeline = pipelineCounts[signal.market] || { ready: 0, inProgress: 0, total: 0 };
        const gap = signal.expectedHeadcount - pipeline.ready;
        
        return {
          signalId: signal.id,
          market: signal.market,
          workerType: signal.workerType,
          workType: signal.workType,
          expectedHeadcount: signal.expectedHeadcount,
          effectiveFrom: signal.effectiveFrom,
          effectiveTo: signal.effectiveTo,
          priority: signal.priority,
          notes: signal.notes,
          pipeline: {
            ready: pipeline.ready,
            inProgress: pipeline.inProgress,
            total: pipeline.total,
          },
          gap: gap,
          gapPercentage: signal.expectedHeadcount > 0 
            ? Math.round((gap / signal.expectedHeadcount) * 100) 
            : 0,
          status: gap <= 0 ? 'met' : gap <= signal.expectedHeadcount * 0.2 ? 'close' : 'gap',
        };
      });

      // Sort by gap (largest gaps first)
      gapAnalysis.sort((a, b) => b.gap - a.gap);

      res.json({
        checkDate: checkDateStr,
        signals: gapAnalysis,
        summary: {
          totalDemand: effectiveSignals.reduce((sum, s) => sum + s.expectedHeadcount, 0),
          totalReady: Object.values(pipelineCounts).reduce((sum, p) => sum + p.ready, 0),
          totalInProgress: Object.values(pipelineCounts).reduce((sum, p) => sum + p.inProgress, 0),
          marketsWithGap: gapAnalysis.filter(g => g.status === 'gap').length,
          marketsNearTarget: gapAnalysis.filter(g => g.status === 'close').length,
          marketsMet: gapAnalysis.filter(g => g.status === 'met').length,
        },
      });
    } catch (error: any) {
      console.error("Error calculating demand gap:", error);
      res.status(500).json({ message: "Failed to calculate demand gap" });
    }
  });


