  // GET /api/recruiting/feature-flags/:key/check - Check if a feature is enabled
  app.get("/api/recruiting/feature-flags/:key/check", async (req: any, res: Response) => {
    try {
      const { key } = req.params;
      const { market } = req.query;

      // Check for market-specific flag first, then global
      let flag = null;
      
      if (market) {
        const [marketFlag] = await db.select()
          .from(recruitingFeatureFlags)
          .where(and(
            eq(recruitingFeatureFlags.flagKey, key),
            eq(recruitingFeatureFlags.market, market as string)
          ));
        flag = marketFlag;
      }
      
      // If no market-specific flag, check global
      if (!flag) {
        const [globalFlag] = await db.select()
          .from(recruitingFeatureFlags)
          .where(and(
            eq(recruitingFeatureFlags.flagKey, key),
            eq(recruitingFeatureFlags.scope, 'global')
          ));
        flag = globalFlag;
      }

      res.json({
        flagKey: key,
        market: market || null,
        isEnabled: flag?.isEnabled || false,
        requiresExplicitEnable: flag?.requiresExplicitEnable ?? true,
        exists: !!flag,
      });
    } catch (error: any) {
      console.error("Error checking feature flag:", error);
      res.status(500).json({ message: "Failed to check feature flag" });
    }
  });

