  // POST /api/recruiting/kill-switches/toggle - Toggle a kill switch (admin only)
  app.post("/api/recruiting/kill-switches/toggle", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      if (!user || !["admin", "super_user", "recruiting_admin"].includes(user.role || "")) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { key, isActive, scope, market } = req.body;

      const { KILL_SWITCH_KEYS, KILL_SWITCH_DEFAULTS } = await import("./services/recruitingKillSwitch");
      const validKeys = Object.values(KILL_SWITCH_KEYS);
      if (!validKeys.includes(key)) {
        return res.status(400).json({ message: `Invalid kill switch key. Must be one of: ${validKeys.join(', ')}` });
      }
      if (!["global", "market"].includes(scope)) {
        return res.status(400).json({ message: "Scope must be 'global' or 'market'" });
      }
      if (scope === "market" && !market) {
        return res.status(400).json({ message: "Market is required for market-scoped kill switches" });
      }

      const defaults = KILL_SWITCH_DEFAULTS[key];
      const flagMarket = scope === "market" ? market : null;

      const [existing] = await db.select()
        .from(recruitingFeatureFlags)
        .where(and(
          eq(recruitingFeatureFlags.flagKey, key),
          scope === "global" 
            ? eq(recruitingFeatureFlags.scope, "global")
            : and(eq(recruitingFeatureFlags.scope, "market"), eq(recruitingFeatureFlags.market, flagMarket!))
        ));

      if (existing) {
        const [updated] = await db.update(recruitingFeatureFlags)
          .set({
            isEnabled: isActive,
            updatedAt: new Date(),
            updatedByEmail: user.email,
          })
          .where(eq(recruitingFeatureFlags.id, existing.id))
          .returning();
        
        console.log(`[KillSwitch] ${isActive ? 'ACTIVATED' : 'DEACTIVATED'} ${key} (${scope}${flagMarket ? ': ' + flagMarket : ''}) by ${user.email}`);
        res.json({ success: true, flag: updated, action: isActive ? "activated" : "deactivated" });
      } else {
        const [created] = await db.insert(recruitingFeatureFlags)
          .values({
            flagKey: key,
            name: defaults.name,
            description: defaults.description,
            warningMessage: defaults.warningMessage,
            scope: scope as "global" | "market",
            market: flagMarket,
            isEnabled: isActive,
            isMvpFeature: false,
            requiresExplicitEnable: false,
            createdByEmail: user.email,
            updatedByEmail: user.email,
          })
          .returning();
        
        console.log(`[KillSwitch] CREATED and ${isActive ? 'ACTIVATED' : 'DEACTIVATED'} ${key} (${scope}${flagMarket ? ': ' + flagMarket : ''}) by ${user.email}`);
        res.json({ success: true, flag: created, action: isActive ? "activated" : "deactivated" });
      }
    } catch (error: any) {
      console.error("Error toggling kill switch:", error);
      res.status(500).json({ message: "Failed to toggle kill switch" });
    }
  });

