  // PATCH /api/recruiting/candidates/:id/language-preference - Update candidate language preference
  app.patch("/api/recruiting/candidates/:id/language-preference", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      
      if (!user || (user.role !== 'admin' && user.role !== 'recruiter' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }

      const { id } = req.params;
      const { languagePreference } = req.body;
      
      if (!languagePreference) {
        return res.status(400).json({ message: "Language preference is required" });
      }
      
      // Validate language is supported
      const { supportedLanguages } = await import("@shared/schema");
      if (!supportedLanguages.includes(languagePreference)) {
        return res.status(400).json({ 
          message: "Unsupported language",
          supportedLanguages: supportedLanguages,
        });
      }
      
      const [existing] = await db.select().from(recruitingCandidates).where(eq(recruitingCandidates.id, id));
      
      if (!existing) {
        return res.status(404).json({ message: "Candidate not found" });
      }

      const previousLanguage = existing.languagePreference || "en";
      
      // Skip update if same value
      if (previousLanguage === languagePreference) {
        return res.json(existing);
      }

      const [updated] = await db.update(recruitingCandidates)
        .set({
          languagePreference,
          languagePreferenceSetAt: new Date(),
          languagePreferenceSetBy: user.id,
          updatedAt: new Date(),
          updatedBy: user.id,
        })
        .where(eq(recruitingCandidates.id, id))
        .returning();

      // Log audit event
      await db.insert(recruitingAuditEvents).values({
        actionType: "LANGUAGE_PREFERENCE_CHANGED",
        entityType: "candidate",
        entityId: id,
        userId: user.id,
        userEmail: user.email,
        actorRole: user?.role || undefined,
        source: 'ui',
        previousValue: JSON.stringify({ languagePreference: previousLanguage }),
        newValue: JSON.stringify({ languagePreference: updated.languagePreference }),
      });

      res.json(updated);
    } catch (error: any) {
      console.error("Error updating language preference:", error);
      res.status(500).json({ message: "Failed to update language preference" });
    }
  });

