  app.post("/api/recruiting/reason-codes", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      
      if (!user || (user.role !== 'admin' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Admin access required" });
      }

      const { code, label, description, stage, isRequired, isActive, displayOrder, market } = req.body;
      
      if (!code || !label || !stage) {
        return res.status(400).json({ message: "Code, label, and stage are required" });
      }

      const [created] = await db.insert(recruitingReasonCodes).values({
        code,
        label,
        description: description || null,
        stage,
        isRequired: isRequired || false,
        isActive: isActive !== false,
        displayOrder: displayOrder || 0,
        market: market || null,
        createdBy: user.id,
        updatedBy: user.id,
      }).returning();

      // Log audit event
      await db.insert(recruitingAuditEvents).values({
        actionType: "REASON_CODE_CREATED",
        entityType: "reason_code",
        entityId: created.id,
        userId: user.id,
        userEmail: user.email,
        actorRole: user?.role || undefined,
        source: 'ui',
        newValue: JSON.stringify(created),
      });

      res.status(201).json(created);
    } catch (error: any) {
      console.error("Error creating reason code:", error);
      if (error.code === '23505') {
        res.status(409).json({ message: "Reason code with this code/stage/market combination already exists" });
      } else {
        res.status(500).json({ message: "Failed to create reason code" });
      }
    }
  });

