  app.post("/api/recruiting/applications/:id/reactivate", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      
      if (!user || (user.role !== 'admin' && user.role !== 'recruiter' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }

      const { id } = req.params;
      const { restoreToStage, notes } = req.body;
      
      // Verify application exists
      const [application] = await db.select().from(recruitingApplications).where(eq(recruitingApplications.id, id));
      
      if (!application) {
        return res.status(404).json({ message: "Application not found" });
      }
      
      if (!application.withdrawnAt && !application.noShowAt) {
        return res.status(400).json({ message: "Application is not withdrawn or marked no-show" });
      }

      const previousStage = application.currentStage;
      const targetStage = restoreToStage || "applied";

      // Clear withdrawal/no-show fields and restore
      const [updated] = await db.update(recruitingApplications)
        .set({
          currentStage: targetStage,
          withdrawnAt: null,
          withdrawnBy: null,
          withdrawnReason: null,
          withdrawnSource: null,
          noShowAt: null,
          noShowBy: null,
          noShowReason: null,
          noShowInterviewId: null,
          excludeFromMetrics: false,
          updatedAt: new Date(),
        })
        .where(eq(recruitingApplications.id, id))
        .returning();

      // Log audit event
      await db.insert(recruitingAuditEvents).values({
        actionType: "APPLICATION_REACTIVATED",
        entityType: "application",
        entityId: id,
        userId: user.id,
        userEmail: user.email,
        actorRole: user?.role || undefined,
        source: 'ui',
        previousValue: JSON.stringify({ stage: previousStage }),
        newValue: JSON.stringify({
          stage: targetStage,
          notes,
        }),
      });

      res.json(updated);
    } catch (error: any) {
      console.error("Error reactivating application:", error);
      res.status(500).json({ message: "Failed to reactivate application" });
    }
  });

