  // POST /api/recruiting/candidates/:candidateId/consents - Record a consent
  app.post("/api/recruiting/candidates/:candidateId/consents", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }

      // Require authentication for all consent recording
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }

      if (!user || (user.role !== 'admin' && user.role !== 'recruiter' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { candidateId } = req.params;
      const { 
        consentType,
        consentVersion,
        applicationId,
        source,
        consentGiven,
        ipAddress,
        userAgent,
        consentTextHash,
        stateCode,
        disclosureTextId,
        signatureData,
        metadata
      } = req.body;
      
      if (!consentType) {
        return res.status(400).json({ message: "consentType is required" });
      }

      // Verify candidate exists
      const [candidate] = await db.select().from(recruitingCandidates).where(eq(recruitingCandidates.id, candidateId));
      
      if (!candidate) {
        return res.status(404).json({ message: "Candidate not found" });
      }

      // Create immutable consent record
      const [consent] = await db.insert(recruitingConsents).values({
        candidateId,
        applicationId: applicationId || null,
        consentType,
        consentVersion: consentVersion || "1.0",
        consentGiven: consentGiven !== false,
        source: source || "web_form",
        capturedAt: new Date(),
        capturedBy: userId || null,
        ipAddress: ipAddress || null,
        userAgent: userAgent || null,
        consentTextHash: consentTextHash || null,
        stateCode: stateCode || null,
        disclosureTextId: disclosureTextId || null,
        signatureData: signatureData || null,
        metadata: metadata || null,
      }).returning();

      // Log audit event if user is authenticated
      if (userId) {
        await db.insert(recruitingAuditEvents).values({
          actionType: consentGiven !== false ? "CONSENT_RECORDED" : "CONSENT_REVOKED",
          entityType: "candidate",
          entityId: candidateId,
          userId,
          userEmail,
          newValue: JSON.stringify({
            consentId: consent.id,
            consentType,
            consentVersion: consentVersion || "1.0",
            consentGiven: consentGiven !== false,
            source: source || "web_form",
          }),
        });
      }

      res.status(201).json(consent);
    } catch (error: any) {
      console.error("Error recording consent:", error);
      res.status(500).json({ message: "Failed to record consent" });
    }
  });

  // GET /api/recruiting/candidates/:candidateId/consents - Get consent history for a candidate
  app.get("/api/recruiting/candidates/:candidateId/consents", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      
      if (!user) {
        return res.status(403).json({ message: "Forbidden" });
      }

      const { candidateId } = req.params;
      const { consentType, activeOnly } = req.query;
      
      const consents = await db.select()
        .from(recruitingConsents)
        .where(eq(recruitingConsents.candidateId, candidateId))
        .orderBy(desc(recruitingConsents.capturedAt));
      
      // Filter by consent type if specified
      let filtered = consents;
      if (consentType) {
        filtered = consents.filter(c => c.consentType === consentType);
      }
      
      // If activeOnly, get only the latest consent of each type
      if (activeOnly === 'true') {
        const latestByType = new Map<string, typeof consents[0]>();
        for (const consent of filtered) {
          if (!latestByType.has(consent.consentType) || 
              new Date(consent.capturedAt) > new Date(latestByType.get(consent.consentType)!.capturedAt)) {
            latestByType.set(consent.consentType, consent);
          }
        }
        filtered = Array.from(latestByType.values());
      }

      res.json(filtered);
    } catch (error: any) {
      console.error("Error fetching consents:", error);
      res.status(500).json({ message: "Failed to fetch consents" });
    }
  });

