  app.get("/api/recruiting/candidates/:candidateId/consents/summary", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const { candidateId } = req.params;
      
      const consents = await db.select()
        .from(recruitingConsents)
        .where(eq(recruitingConsents.candidateId, candidateId))
        .orderBy(desc(recruitingConsents.capturedAt));

      // Build summary by consent type
      const summary: Record<string, {
        latestConsent: typeof consents[0] | null;
        hasActiveConsent: boolean;
        totalRecords: number;
        versions: string[];
      }> = {};

      const consentTypes = [
        "background_check", "drug_test", "mvr_check", "employment_verification",
        "reference_check", "electronic_signature", "sms_communication", "email_communication",
        "data_retention", "fcra_disclosure", "state_specific_disclosure", "arbitration_agreement"
      ];

      for (const type of consentTypes) {
        const typeConsents = consents.filter(c => c.consentType === type);
        const latestConsent = typeConsents[0] || null;
        summary[type] = {
          latestConsent,
          hasActiveConsent: latestConsent?.consentGiven === true,
          totalRecords: typeConsents.length,
          versions: [...new Set(typeConsents.map(c => c.consentVersion))],
        };
      }

      res.json({
        candidateId,
        summary,
        totalConsents: consents.length,
        lastUpdated: consents[0]?.capturedAt || null,
      });
    } catch (error: any) {
      console.error("Error fetching consent summary:", error);
      res.status(500).json({ message: "Failed to fetch consent summary" });
    }
  });

