  app.post("/api/recruiting/candidates/:candidateId/consents/:consentType/revoke", async (req: any, res: Response) => {
    try {
      let userId: string | null = null;
      let userEmail: string | null = null;
      if ((req.session as any)?.userId) {
        userId = (req.session as any).userId;
      } else if (req.isAuthenticated?.() && req.user?.claims?.sub) {
        userId = req.user.claims.sub;
        userEmail = req.user.claims.email;
      }
      
      if (!userId) {
        return res.status(401).json({ message: "Unauthorized" });
      }
      
      let user = await storage.getUser(userId);
      if (!user && userEmail) {
        const [userByEmail] = await db.select().from(users).where(eq(users.email, userEmail));
        user = userByEmail;
      }
      
      if (!user || (user.role !== 'admin' && user.role !== 'recruiter' && user.role !== 'recruiting_admin' && user.role !== 'super_user')) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }

      const { candidateId, consentType } = req.params;
      const { reason, source } = req.body;
      
      // Verify candidate exists
      const [candidate] = await db.select().from(recruitingCandidates).where(eq(recruitingCandidates.id, candidateId));
      
      if (!candidate) {
        return res.status(404).json({ message: "Candidate not found" });
      }

      // Create new revocation record (immutable - no updates)
      const [consent] = await db.insert(recruitingConsents).values({
        candidateId,
        consentType,
        consentVersion: "revoked",
        consentGiven: false,
        source: source || "recruiter_action",
        capturedAt: new Date(),
        capturedBy: user.id,
        revokedAt: new Date(),
        revokedBy: user.id,
        revocationReason: reason || null,
      }).returning();

      // Log audit event
      await db.insert(recruitingAuditEvents).values({
        actionType: "CONSENT_REVOKED",
        entityType: "candidate",
        entityId: candidateId,
        userId: user.id,
        userEmail: user.email,
        actorRole: user?.role || undefined,
        source: 'ui',
        newValue: JSON.stringify({
          consentId: consent.id,
          consentType,
          reason,
        }),
      });

      // Trigger readiness regression check for consent revocation
      try {
        const apps = await db.select().from(recruitingApplications).where(eq(recruitingApplications.candidateId, candidateId));
        const { onConsentRevoked } = await import("./services/readinessRegressionService");
        for (const app of apps) {
          await onConsentRevoked(app.id, candidateId, consentType, user.id, user.email || "");
        }
      } catch (regressionErr) {
        console.error("[Regression] Error triggering consent regression:", regressionErr);
      }

      res.status(201).json(consent);
    } catch (error: any) {
      console.error("Error revoking consent:", error);
      res.status(500).json({ message: "Failed to revoke consent" });
    }
  });

