  // ============================================
  // CANDIDATE PORTAL - Token-Based Secure Access
  // ============================================

  // POST /api/recruiting/applications/:applicationId/portal-token - Generate portal token (recruiter action)
  app.post("/api/recruiting/applications/:applicationId/portal-token", async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });
      if (!userId) return res.status(401).json({ message: "Authentication required" });

      const { applicationId } = req.params;
      const { inactivityWindowDays = 30 } = req.body || {};

      const [application] = await db.select()
        .from(recruitingApplications)
        .where(eq(recruitingApplications.id, applicationId))
        .limit(1);
      if (!application) return res.status(404).json({ message: "Application not found" });

      const crypto = await import('crypto');
      const rawToken = crypto.randomBytes(32).toString('hex');
      const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

      const expiresAt = new Date();
      expiresAt.setDate(expiresAt.getDate() + Math.max(inactivityWindowDays, 7));

      await db.update(candidatePortalTokens)
        .set({ isRevoked: true, revokedAt: new Date(), revokedBy: userId })
        .where(and(
          eq(candidatePortalTokens.applicationId, applicationId),
          eq(candidatePortalTokens.isRevoked, false)
        ));

      const [token] = await db.insert(candidatePortalTokens).values({
        tokenHash,
        candidateId: application.candidateId,
        applicationId,
        expiresAt,
        inactivityWindowDays,
        createdBy: userId,
      }).returning();

      res.json({ token: rawToken, id: token.id, expiresAt: token.expiresAt });
    } catch (error: any) {
      console.error("Error generating portal token:", error);
      res.status(500).json({ message: "Failed to generate portal token" });
    }
  });

