  // GET /api/recruiting/applications/:applicationId/document-completion - Get document completion status
  app.get("/api/recruiting/applications/:applicationId/document-completion", async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });
      const { applicationId } = req.params;

      const application = await db.query.recruitingApplications.findFirst({
        where: eq(recruitingApplications.id, applicationId),
        with: { requisition: true },
      });
      if (!application) return res.status(404).json({ message: "Application not found" });

      const requisition = application.requisition;
      const requiredTypes: string[] = (requisition?.requiredDocumentTypes as string[]) || [];
      if (requiredTypes.length === 0) {
        return res.json({
          required: [],
          uploaded: [],
          missing: [],
          totalRequired: 0,
          totalUploaded: 0,
          complete: true,
          blockStageIfIncomplete: false,
        });
      }

      const docRequests = await db.select()
        .from(candidateDocumentRequests)
        .where(eq(candidateDocumentRequests.applicationId, applicationId));

      const uploadedTypes = new Set(
        docRequests
          .filter(d => d.uploadedFileName && d.status !== "rejected")
          .map(d => d.documentType)
      );

      const checklist = requiredTypes.map(docType => {
        const matchingDoc = docRequests.find(d => d.documentType === docType && d.uploadedFileName && d.status !== "rejected");
        const expDate = matchingDoc?.expirationDate || null;
        let expirationWarning: string | null = null;
        if (expDate) {
          const today = new Date();
          today.setHours(0, 0, 0, 0);
          const exp = new Date(expDate + "T00:00:00");
          const diffDays = Math.ceil((exp.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
          if (diffDays < 0) expirationWarning = "Expired";
          else if (diffDays <= 30) expirationWarning = `Expiring in ${diffDays} day${diffDays !== 1 ? 's' : ''}`;
        }
        return {
          documentType: docType,
          uploaded: uploadedTypes.has(docType),
          status: uploadedTypes.has(docType) ? (matchingDoc?.status || "uploaded") : "missing",
          expirationDate: expDate,
          expirationWarning,
        };
      });

      const missing = checklist.filter(c => !c.uploaded).map(c => c.documentType);

      res.json({
        required: checklist,
        uploaded: checklist.filter(c => c.uploaded).map(c => c.documentType),
        missing,
        totalRequired: requiredTypes.length,
        totalUploaded: requiredTypes.length - missing.length,
        complete: missing.length === 0,
        blockStageIfIncomplete: requisition?.blockStageIfDocsIncomplete ?? false,
      });
    } catch (error: any) {
      console.error("Error fetching document completion:", error);
      res.status(500).json({ message: "Failed to fetch document completion status" });
    }
  });

  // PATCH /api/recruiting/applications/:applicationId/document-requests/:id/review - Review uploaded doc (recruiter)
  app.patch("/api/recruiting/applications/:applicationId/document-requests/:id/review", async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });
      const { id } = req.params;
      const { status, reviewNotes } = req.body;

      if (!status || !['approved', 'rejected'].includes(status)) {
        return res.status(400).json({ message: "status must be 'approved' or 'rejected'" });
      }

      const [updated] = await db.update(candidateDocumentRequests)
        .set({ status, reviewNotes, reviewedBy: userId, reviewedAt: new Date(), updatedAt: new Date() })
        .where(eq(candidateDocumentRequests.id, id))
        .returning();

      res.json(updated);
    } catch (error: any) {
      console.error("Error reviewing document:", error);
      res.status(500).json({ message: "Failed to review document" });
    }
  });

  // PATCH /api/recruiting/documents/:id/metadata - Update document metadata (recruiter)
  app.patch("/api/recruiting/documents/:id/metadata", async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });
      const { id } = req.params;
      const { expirationDate, issueDate, status, notes, reviewNotes } = req.body;

      const [existing] = await db.select().from(candidateDocumentRequests).where(eq(candidateDocumentRequests.id, id));
      if (!existing) return res.status(404).json({ message: "Document not found" });

      const updates: any = { updatedAt: new Date() };
      const changes: string[] = [];

      if (expirationDate !== undefined) {
        changes.push(`expirationDate: ${existing.expirationDate || 'null'} -> ${expirationDate || 'null'}`);
        updates.expirationDate = expirationDate || null;
      }
      if (issueDate !== undefined) {
        changes.push(`issueDate: ${existing.issueDate || 'null'} -> ${issueDate || 'null'}`);
        updates.issueDate = issueDate || null;
      }
      if (notes !== undefined) {
        changes.push('notes updated');
        updates.notes = notes;
      }
      if (reviewNotes !== undefined) {
        changes.push('reviewNotes updated');
        updates.reviewNotes = reviewNotes;
      }
      if (status && ['pending', 'uploaded', 'approved', 'rejected'].includes(status)) {
        changes.push(`status: ${existing.status} -> ${status}`);
        updates.status = status;
        if (status === 'approved') {
          updates.verifiedBy = userId;
          updates.verifiedDate = new Date();
          updates.reviewedBy = userId;
          updates.reviewedAt = new Date();
          changes.push('verifiedBy set to current user, verifiedDate auto-set');
        } else if (existing.status === 'approved') {
          updates.verifiedBy = null;
          updates.verifiedDate = null;
          changes.push('verifiedBy/verifiedDate cleared (moved away from approved)');
        }
      }

      const [updated] = await db.update(candidateDocumentRequests)
        .set(updates)
        .where(eq(candidateDocumentRequests.id, id))
        .returning();

      if (changes.length > 0) {
        try {
          const { recruitingAuditLog } = await import("@shared/schema");
          await db.insert(recruitingAuditLog).values({
            entityType: "document",
            entityId: id,
            action: "metadata_updated",
            performedBy: userId,
            details: { changes, applicationId: existing.applicationId },
          });
        } catch (auditErr) {
          console.error("Audit log error (non-blocking):", auditErr);
        }

        try {
          const { documentEvents: docEventsTable } = await import("@shared/schema");
          const changedFields: Record<string, { before: any; after: any }> = {};
          if (expirationDate !== undefined) changedFields.expirationDate = { before: existing.expirationDate || null, after: expirationDate || null };
          if (issueDate !== undefined) changedFields.issueDate = { before: existing.issueDate || null, after: issueDate || null };
          if (status !== undefined) changedFields.status = { before: existing.status, after: status };
          if (notes !== undefined) changedFields.notes = { before: existing.notes || null, after: notes || null };
          if (reviewNotes !== undefined) changedFields.reviewNotes = { before: existing.reviewNotes || null, after: reviewNotes || null };

          await db.insert(docEventsTable).values({
            documentId: id,
            ownerType: "candidate",
            ownerId: existing.applicationId,
            eventType: "document.updated",
            performedByUserId: userId,
            metadata: { changes: changedFields, fieldNames: Object.keys(changedFields), source: "recruiting" },
          });
        } catch (docAuditErr) {
          console.error("Document event log error (non-blocking):", docAuditErr);
        }
      }

      try {
        if (updated?.applicationId) {
          const { recalculateReadiness } = await import("./recruitingService");
          await recalculateReadiness(updated.applicationId, userId, null);
        }
      } catch (recalcErr) {
        console.error("[Recruiting] Non-blocking readiness recalc on metadata update:", recalcErr);
      }

      res.json(updated);
    } catch (error: any) {
      console.error("Error updating document metadata:", error);
      res.status(500).json({ message: "Failed to update document metadata" });
    }
  });

  // GET /api/recruiting/documents/:id/events - Document audit events for recruiting docs
  app.get("/api/recruiting/documents/:id/events", async (req: any, res: Response) => {
    try {
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });
      const { id } = req.params;

      const { documentEvents: docEventsTable } = await import("@shared/schema");
      const events = await db.select()
        .from(docEventsTable)
        .where(eq(docEventsTable.documentId, id))
        .orderBy(desc(docEventsTable.createdAt));

      res.json(events);
    } catch (error: any) {
      console.error("Error fetching document events:", error);
      res.status(500).json({ message: "Failed to fetch document events" });
    }
  });

  // ============================================
  // CANDIDATE PORTAL - Public Routes (Token Auth)
  // ============================================

  // GET /api/portal/candidate/:token - Get candidate portal data (public, token auth)
  app.get("/api/portal/candidate/:token", PUBLIC_RATE_LIMITS.candidatePortal, TOKEN_THROTTLE, async (req: Request, res: Response) => {
    try {
      const { token } = req.params;
      const crypto = await import('crypto');
      const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

      const [portalToken] = await db.select()
        .from(candidatePortalTokens)
        .where(eq(candidatePortalTokens.tokenHash, tokenHash))
        .limit(1);

      if (!portalToken) return res.status(404).json({ message: "Invalid or expired portal link" });
      if (portalToken.isRevoked) return res.status(403).json({ message: "This portal link has been revoked" });
      if (new Date() > new Date(portalToken.expiresAt)) return res.status(403).json({ message: "This portal link has expired" });

      // One-time-use token enforcement
      if (portalToken.isOneTimeUse && portalToken.usedAt) {
        await logAbuseEvent({
          type: "ONE_TIME_TOKEN_REUSE",
          severity: "HIGH",
          ip: req.ip || null,
          userAgent: req.headers["user-agent"] || null,
          route: req.originalUrl,
          method: req.method,
          tokenHash: tokenHash,
          reason: "Attempted reuse of one-time portal token",
        });
        return res.status(403).json({ message: "This portal link has already been used" });
      }

      // Mark one-time-use tokens as used
      if (portalToken.isOneTimeUse && !portalToken.usedAt) {
        await db.update(candidatePortalTokens)
          .set({ usedAt: new Date() })
          .where(eq(candidatePortalTokens.id, portalToken.id));
      }

      if (portalToken.lastAccessedAt) {
        const lastAccess = new Date(portalToken.lastAccessedAt);
        const inactivityLimit = new Date(lastAccess.getTime() + portalToken.inactivityWindowDays * 24 * 60 * 60 * 1000);
        if (new Date() > inactivityLimit) {
          return res.status(403).json({ message: "This portal link has expired due to inactivity" });
        }
      }

      await db.update(candidatePortalTokens)
        .set({ lastAccessedAt: new Date() })
        .where(eq(candidatePortalTokens.id, portalToken.id));

      const [candidate] = await db.select({
        firstName: recruitingCandidates.firstName,
        lastName: recruitingCandidates.lastName,
        email: recruitingCandidates.email,
      })
        .from(recruitingCandidates)
        .where(eq(recruitingCandidates.id, portalToken.candidateId))
        .limit(1);

      const [application] = await db.select({
        id: recruitingApplications.id,
        currentStage: recruitingApplications.currentStage,
        currentStageEnteredAt: recruitingApplications.currentStageEnteredAt,
        appliedAt: recruitingApplications.appliedAt,
        docsComplete: recruitingApplications.docsComplete,
        backgroundCheckStatus: recruitingApplications.backgroundCheckStatus,
      })
        .from(recruitingApplications)
        .where(eq(recruitingApplications.id, portalToken.applicationId))
        .limit(1);

      let requisition = null;
      if (application) {
        const [req2] = await db.select({
          title: recruitingRequisitions.title,
          market: recruitingRequisitions.market,
        })
          .from(recruitingRequisitions)
          .innerJoin(recruitingApplications, eq(recruitingApplications.requisitionId, recruitingRequisitions.id))
          .where(eq(recruitingApplications.id, portalToken.applicationId))
          .limit(1);
        requisition = req2;
      }

      const upcomingInterviews = await db.select({
        id: recruitingInterviews.id,
        title: recruitingInterviews.title,
        interviewType: recruitingInterviews.interviewType,
        status: recruitingInterviews.status,
        startTime: recruitingInterviews.startTime,
        endTime: recruitingInterviews.endTime,
        durationMinutes: recruitingInterviews.durationMinutes,
        timezone: recruitingInterviews.timezone,
        location: recruitingInterviews.location,
        meetingLink: recruitingInterviews.meetingLink,
      })
        .from(recruitingInterviews)
        .where(and(
          eq(recruitingInterviews.applicationId, portalToken.applicationId),
          sql`${recruitingInterviews.status} IN ('scheduled', 'confirmed')`,
        ))
        .orderBy(recruitingInterviews.startTime);

      const documentRequests = await db.select({
        id: candidateDocumentRequests.id,
        documentType: candidateDocumentRequests.documentType,
        label: candidateDocumentRequests.label,
        description: candidateDocumentRequests.description,
        required: candidateDocumentRequests.required,
        status: candidateDocumentRequests.status,
        uploadedFileName: candidateDocumentRequests.uploadedFileName,
        uploadedAt: candidateDocumentRequests.uploadedAt,
        reviewNotes: candidateDocumentRequests.reviewNotes,
      })
        .from(candidateDocumentRequests)
        .where(eq(candidateDocumentRequests.applicationId, portalToken.applicationId))
        .orderBy(candidateDocumentRequests.createdAt);

      res.json({
        candidate: candidate || null,
        application: application || null,
        requisition: requisition || null,
        interviews: upcomingInterviews,
        documentRequests,
      });
    } catch (error: any) {
      console.error("Error fetching portal data:", error);
      res.status(500).json({ message: "Failed to load portal data" });
    }
  });

  // POST /api/portal/candidate/:token/documents/:docRequestId/upload - Upload document (candidate action)
  app.post("/api/portal/candidate/:token/documents/:docRequestId/upload", PUBLIC_RATE_LIMITS.candidateDocUpload, TOKEN_THROTTLE, async (req: Request, res: Response) => {
    try {
      const { token, docRequestId } = req.params;
      const crypto = await import('crypto');
      const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

      const [portalToken] = await db.select()
        .from(candidatePortalTokens)
        .where(eq(candidatePortalTokens.tokenHash, tokenHash))
        .limit(1);

      if (!portalToken) return res.status(404).json({ message: "Invalid or expired portal link" });
      if (portalToken.isRevoked) return res.status(403).json({ message: "This portal link has been revoked" });
      if (new Date() > new Date(portalToken.expiresAt)) return res.status(403).json({ message: "This portal link has expired" });

      if (portalToken.lastAccessedAt) {
        const lastAccess = new Date(portalToken.lastAccessedAt);
        const inactivityLimit = new Date(lastAccess.getTime() + portalToken.inactivityWindowDays * 24 * 60 * 60 * 1000);
        if (new Date() > inactivityLimit) {
          return res.status(403).json({ message: "This portal link has expired due to inactivity" });
        }
      }

      const [docRequest] = await db.select()
        .from(candidateDocumentRequests)
        .where(and(
          eq(candidateDocumentRequests.id, docRequestId),
          eq(candidateDocumentRequests.applicationId, portalToken.applicationId)
        ))
        .limit(1);

      if (!docRequest) return res.status(404).json({ message: "Document request not found" });
      if (docRequest.status === 'approved') return res.status(400).json({ message: "This document has already been approved" });

      const { fileName, fileSize, mimeType, fileData } = req.body;
      if (!fileName || !fileData || !mimeType) {
        return res.status(400).json({ message: "fileName, mimeType, and fileData are required" });
      }

      const [updated] = await db.update(candidateDocumentRequests)
        .set({
          status: 'uploaded',
          uploadedFileName: fileName,
          uploadedFileSize: fileSize || '0',
          uploadedFileMimeType: mimeType,
          uploadedFileData: fileData,
          uploadedAt: new Date(),
          updatedAt: new Date(),
        })
        .where(eq(candidateDocumentRequests.id, docRequestId))
        .returning();

      await db.update(candidatePortalTokens)
        .set({ lastAccessedAt: new Date() })
        .where(eq(candidatePortalTokens.id, portalToken.id));

      res.json({
        id: updated.id,
        status: updated.status,
        uploadedFileName: updated.uploadedFileName,
        uploadedAt: updated.uploadedAt,
      });
    } catch (error: any) {
      console.error("Error uploading document:", error);
      res.status(500).json({ message: "Failed to upload document" });
    }
  });

