  // POST /api/recruiting/documents/:docRequestId/upload-init - Recruiter/admin: get signed upload URL
  app.post("/api/recruiting/documents/:docRequestId/upload-init", async (req: any, res: Response) => {
    try {
      const _obsStart = Date.now();
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });

      const { docRequestId } = req.params;
      const { fileName, mimeType, fileSizeBytes } = req.body;

      if (!fileName || !mimeType || !fileSizeBytes) {
        return res.status(400).json({ message: "fileName, mimeType, and fileSizeBytes are required" });
      }

      const dbUser = await storage.getUser(userId);
      const userRole = dbUser?.role || (req.user as any)?.role || "employee";

      const rbacCheck = await checkDocumentRbacAccess(
        userId,
        userRole,
        docRequestId,
        req.ip,
        req.headers["user-agent"]
      );
      if (!rbacCheck.allowed) {
        return res.status(403).json({ message: rbacCheck.reason });
      }

      const result = await initiateUpload({
        docRequestId,
        applicationId: rbacCheck.docRequest.applicationId,
        fileName,
        mimeType,
        fileSizeBytes: Number(fileSizeBytes),
        userId: userId,
        userRole: userRole,
        isPortalAccess: false,
        ip: req.ip,
        userAgent: req.headers["user-agent"],
      });

      if (!result.success) {
        const isStorageError = (result.error || "").includes("Storage") || (result.error || "").includes("storage") || (result.error || "").includes("configured");
        const statusCode = isStorageError ? 500 : 400;
        return res.status(statusCode).json({ message: result.error });
      }

      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "doc_upload_init",
        status: "success",
        userId: req.user?.id,
        docRequestId,
        latencyMs: Date.now() - _obsStart,
        route: req.path,
        method: req.method,
        metadata: { fileName, mimeType },
      });
      res.json(result.result);
    } catch (error: any) {
      console.error("Error initiating upload:", error);
      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "doc_upload_init",
        status: "error",
        severity: "error",
        docRequestId: req.params.docRequestId,
        userId: req.user?.id,
        latencyMs: Date.now() - _obsStart,
        errorCode: error.code || "UPLOAD_INIT_ERROR",
        errorMessage: error.message?.slice(0, 500),
        route: req.path,
        method: req.method,
      });
      res.status(500).json({ message: "Failed to initiate upload" });
    }
  });

  // POST /api/recruiting/documents/:docRequestId/upload-finalize - Recruiter/admin: confirm upload complete
  app.post("/api/recruiting/documents/:docRequestId/upload-finalize", async (req: any, res: Response) => {
    try {
      const _obsStart = Date.now();
      const userId = (req.session as any)?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Authentication required" });

      const { docRequestId } = req.params;
      const { storagePath, fileName, mimeType, fileSizeBytes } = req.body;

      if (!storagePath || !fileName || !mimeType || !fileSizeBytes) {
        return res.status(400).json({ message: "storagePath, fileName, mimeType, and fileSizeBytes are required" });
      }

      const finalizeDbUser = await storage.getUser(userId);
      const finalizeUserRole = finalizeDbUser?.role || (req.user as any)?.role || "employee";

      const rbacCheck = await checkDocumentRbacAccess(
        userId,
        finalizeUserRole,
        docRequestId,
        req.ip,
        req.headers["user-agent"]
      );
      if (!rbacCheck.allowed) {
        return res.status(403).json({ message: rbacCheck.reason });
      }

      const result = await finalizeUpload({
        docRequestId,
        storagePath,
        fileName,
        mimeType,
        fileSizeBytes: Number(fileSizeBytes),
        userId: userId,
        userRole: finalizeUserRole,
        isPortalAccess: false,
        ip: req.ip,
        userAgent: req.headers["user-agent"],
      });

      if (!result.success) {
        return res.status(400).json({ message: result.error });
      }

      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "doc_upload_finalize",
        status: "success",
        userId: req.user?.id,
        docRequestId,
        latencyMs: Date.now() - _obsStart,
        route: req.path,
        method: req.method,
        metadata: { fileName, mimeType },
      });

      try {
        const docReq = await db.select().from(candidateDocumentRequests).where(eq(candidateDocumentRequests.id, docRequestId)).limit(1);
        if (docReq[0]?.applicationId) {
          const { recalculateReadiness } = await import("./recruitingService");
          await recalculateReadiness(docReq[0].applicationId, userId, null);
        }
      } catch (recalcErr) {
        console.error("[Recruiting] Non-blocking readiness recalc on upload:", recalcErr);
      }

      res.json({ success: true, message: "Upload finalized" });
    } catch (error: any) {
      console.error("Error finalizing upload:", error);
      logRecruitingEvent({
        traceId: (req as any).traceId,
        eventType: "doc_upload_finalize",
        status: "error",
        severity: "error",
        docRequestId: req.params.docRequestId,
        userId: req.user?.id,
        latencyMs: Date.now() - _obsStart,
        errorCode: error.code || "UPLOAD_FINALIZE_ERROR",
        errorMessage: error.message?.slice(0, 500),
        route: req.path,
        method: req.method,
      });
      res.status(500).json({ message: "Failed to finalize upload" });
    }
  });

