  // ============================================
  // BACKUP / ON-CALL DRIVER POOL
  // ============================================

  app.get('/api/corporate/scheduling/backup-pool', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });

      const [adminUser] = await db.select({ role: users.role }).from(users).where(eq(users.id, resolvedId)).limit(1);
      if (!adminUser || (adminUser.role !== 'admin' && adminUser.role !== 'super_user')) {
        return res.status(403).json({ message: 'Admin access required' });
      }

      const { shiftId, locationId, date: dateFilter, roleFilter } = req.query;

      const conditions: any[] = [
        sql`sa.status IN ('assigned', 'confirmed')`,
        sql`s.status IN ('draft', 'published')`,
      ];

      if (roleFilter && roleFilter !== 'all') {
        conditions.push(sql`sa.assignment_role = ${roleFilter}`);
      } else {
        conditions.push(sql`sa.assignment_role IN ('backup', 'on_call')`);
      }

      if (shiftId) conditions.push(sql`sa.shift_id = ${shiftId}`);
      if (locationId) conditions.push(sql`s.location_id = ${locationId}`);
      if (dateFilter) conditions.push(sql`s.date = ${dateFilter}`);

      const whereClause = sql.join(conditions, sql` AND `);

      const results = await db.execute(sql`
        SELECT sa.id, sa.shift_id, sa.user_id, sa.assignment_role, sa.status,
          s.date AS shift_date, s.start_time AS shift_start_time, s.end_time AS shift_end_time, s.location_id AS shift_location_id,
          COALESCE(u.first_name || ' ' || u.last_name, u.email) AS user_name
        FROM shift_assignments sa
        JOIN shifts s ON sa.shift_id = s.id
        JOIN users u ON sa.user_id = u.id
        WHERE ${whereClause}
        ORDER BY s.date ASC, s.start_time ASC
      `);

      const assignments = (results.rows || []).map((r: any) => ({
        id: r.id,
        shiftId: r.shift_id,
        userId: r.user_id,
        assignmentRole: r.assignment_role,
        status: r.status,
        shiftDate: r.shift_date,
        shiftStartTime: r.shift_start_time,
        shiftEndTime: r.shift_end_time,
        shiftLocationId: r.shift_location_id,
        userName: r.user_name,
      }));

      res.json({ assignments });
    } catch (error: any) {
      console.error('Error fetching backup pool:', error);
      res.status(500).json({ message: 'Failed to fetch backup pool' });
    }
  });

  app.post('/api/corporate/scheduling/backup-pool/:assignmentId/activate', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });

      const [adminUser] = await db.select({ role: users.role }).from(users).where(eq(users.id, resolvedId)).limit(1);
      if (!adminUser || (adminUser.role !== 'admin' && adminUser.role !== 'super_user')) {
        return res.status(403).json({ message: 'Admin access required' });
      }

      const { assignmentId } = req.params;
      const { reason } = req.body;

      const [assignment] = await db.select().from(shiftAssignments).where(eq(shiftAssignments.id, assignmentId)).limit(1);
      if (!assignment) {
        return res.status(404).json({ message: 'Assignment not found' });
      }

      if (assignment.assignmentRole !== 'backup' && assignment.assignmentRole !== 'on_call') {
        return res.status(400).json({ message: 'Assignment must have role backup or on_call to activate' });
      }

      const priorRole = assignment.assignmentRole;

      const [updatedAssignment] = await db.update(shiftAssignments)
        .set({ assignmentRole: 'primary', updatedAt: new Date() })
        .where(eq(shiftAssignments.id, assignmentId))
        .returning();

      const [activation] = await db.insert(schedulingBackupActivations).values({
        shiftId: assignment.shiftId,
        shiftAssignmentId: assignmentId,
        userId: assignment.userId,
        activatedBy: resolvedId,
        priorRole: priorRole!,
        newRole: 'primary',
        reason: reason || null,
      }).returning();

      res.json({ assignment: updatedAssignment, activation });
    } catch (error: any) {
      console.error('Error activating backup assignment:', error);
      res.status(500).json({ message: 'Failed to activate backup assignment' });
    }
  });

  app.get('/api/corporate/scheduling/backup-pool/usage-stats', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });

      const [adminUser] = await db.select({ role: users.role }).from(users).where(eq(users.id, resolvedId)).limit(1);
      if (!adminUser || (adminUser.role !== 'admin' && adminUser.role !== 'super_user')) {
        return res.status(403).json({ message: 'Admin access required' });
      }

      const { startDate, endDate, locationId } = req.query;

      const now = new Date();
      const defaultStart = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
      const defaultEnd = now.toISOString().split('T')[0];

      const start = (startDate as string) || defaultStart;
      const end = (endDate as string) || defaultEnd;

      const locationCondition = locationId
        ? sql` AND s.location_id = ${locationId}`
        : sql``;

      const byDriverResults = await db.execute(sql`
        SELECT sba.user_id, COUNT(*)::int AS activation_count,
          COALESCE(u.first_name || ' ' || u.last_name, u.email) AS user_name
        FROM scheduling_backup_activations sba
        JOIN users u ON sba.user_id = u.id
        WHERE sba.activated_at >= ${start}::timestamp AND sba.activated_at <= ${end}::timestamp
        GROUP BY sba.user_id, u.first_name, u.last_name, u.email
        ORDER BY activation_count DESC
      `);

      const recentResults = await db.execute(sql`
        SELECT sba.*, 
          COALESCE(u.first_name || ' ' || u.last_name, u.email) AS user_name,
          s.date AS shift_date, s.location_id AS shift_location_id
        FROM scheduling_backup_activations sba
        JOIN users u ON sba.user_id = u.id
        JOIN shifts s ON sba.shift_id = s.id
        WHERE sba.activated_at >= ${start}::timestamp AND sba.activated_at <= ${end}::timestamp
        ${locationCondition}
        ORDER BY sba.activated_at DESC
        LIMIT 50
      `);

      const totalCountResult = await db.execute(sql`
        SELECT COUNT(*)::int AS total
        FROM scheduling_backup_activations sba
        WHERE sba.activated_at >= ${start}::timestamp AND sba.activated_at <= ${end}::timestamp
      `);

      const totalActivations = (totalCountResult.rows[0] as any)?.total || 0;

      const byDriver = (byDriverResults.rows || []).map((r: any) => ({
        userId: r.user_id,
        userName: r.user_name,
        activationCount: r.activation_count,
      }));

      res.json({
        stats: {
          totalActivations,
          byDriver,
          recentActivations: recentResults.rows || [],
        },
      });
    } catch (error: any) {
      console.error('Error fetching backup usage stats:', error);
      res.status(500).json({ message: 'Failed to fetch backup usage stats' });
    }
  });

  // ============================================
  // SCHEDULE CHANGE IMPACT ANALYSIS
  // ============================================

  app.post('/api/corporate/scheduling/impact-analysis', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });

      const [adminUser] = await db.select({ role: users.role }).from(users).where(eq(users.id, resolvedId)).limit(1);
      if (!adminUser || (adminUser.role !== 'admin' && adminUser.role !== 'super_user')) {
        return res.status(403).json({ message: 'Admin access required' });
      }

      const { shiftId, changeType, proposed } = req.body;

      if (!shiftId || !changeType) {
        return res.status(400).json({ message: 'shiftId and changeType are required' });
      }

      const validChangeTypes = ['time_change', 'staff_change', 'assignment_add', 'assignment_remove'];
      if (!validChangeTypes.includes(changeType)) {
        return res.status(400).json({ message: 'Invalid changeType' });
      }

      const [shift] = await db.select().from(shifts).where(eq(shifts.id, shiftId)).limit(1);
      if (!shift) {
        return res.status(404).json({ message: 'Shift not found' });
      }

      const currentAssignments = await db.select().from(shiftAssignments)
        .where(and(
          eq(shiftAssignments.shiftId, shiftId),
          sql`${shiftAssignments.status} IN ('assigned', 'confirmed')`
        ));

      const beforeCost = currentAssignments.reduce((sum, a) => sum + parseFloat(a.estimatedCost || '0'), 0);
      const beforeAssigned = shift.assignedStaff || 0;
      const beforeRequired = shift.requiredStaff || 1;
      const beforeCoverageGap = Math.max(0, beforeRequired - beforeAssigned);

      let afterCost = beforeCost;
      let afterAssigned = beforeAssigned;
      let afterRequired = beforeRequired;
      const reasons: string[] = [];
      let affectedUserIds: string[] = currentAssignments.map(a => a.userId);

      if (changeType === 'time_change') {
        const newStart = proposed?.startTime ? new Date(proposed.startTime) : shift.startTime;
        const newEnd = proposed?.endTime ? new Date(proposed.endTime) : shift.endTime;
        const newDurationHours = (newEnd.getTime() - newStart.getTime()) / (1000 * 60 * 60);
        const oldDurationHours = (shift.endTime.getTime() - shift.startTime.getTime()) / (1000 * 60 * 60);

        afterCost = 0;
        for (const a of currentAssignments) {
          const rate = parseFloat(a.hourlyRate || '0');
          afterCost += rate * newDurationHours;
        }

        if (newDurationHours !== oldDurationHours) {
          reasons.push(`Shift duration changes from ${oldDurationHours.toFixed(1)}h to ${newDurationHours.toFixed(1)}h`);
        }
      } else if (changeType === 'staff_change') {
        afterRequired = proposed?.requiredStaff ?? beforeRequired;
        if (afterRequired !== beforeRequired) {
          reasons.push(`Required staff changes from ${beforeRequired} to ${afterRequired}`);
        }
      } else if (changeType === 'assignment_add') {
        afterAssigned = beforeAssigned + 1;
        const newUserId = proposed?.userId;
        if (newUserId) {
          affectedUserIds.push(newUserId);
          const avgRate = currentAssignments.length > 0
            ? currentAssignments.reduce((s, a) => s + parseFloat(a.hourlyRate || '0'), 0) / currentAssignments.length
            : 0;
          const shiftDuration = (shift.endTime.getTime() - shift.startTime.getTime()) / (1000 * 60 * 60);
          afterCost = beforeCost + (avgRate * shiftDuration);
        }
        reasons.push(`Adding 1 staff member (${beforeAssigned} -> ${afterAssigned})`);
      } else if (changeType === 'assignment_remove') {
        afterAssigned = Math.max(0, beforeAssigned - 1);
        if (proposed?.userId && currentAssignments.length > 0) {
          const removedAssignment = currentAssignments.find(a => a.userId === proposed.userId);
          if (removedAssignment) {
            afterCost = beforeCost - parseFloat(removedAssignment.estimatedCost || '0');
          }
        } else if (currentAssignments.length > 0) {
          const avgCost = beforeCost / currentAssignments.length;
          afterCost = beforeCost - avgCost;
        }
        reasons.push(`Removing 1 staff member (${beforeAssigned} -> ${afterAssigned})`);
      }

      const afterCoverageGap = Math.max(0, afterRequired - afterAssigned);
      const costDelta = afterCost - beforeCost;
      const costDeltaPct = beforeCost > 0 ? (costDelta / beforeCost) * 100 : 0;
      const staffDelta = afterAssigned - beforeAssigned;
      const gapDelta = afterCoverageGap - beforeCoverageGap;

      const uniqueUserIds = [...new Set(affectedUserIds)];
      const otImpact: any[] = [];
      const beforeWeeklyHours: Record<string, number> = {};
      const afterWeeklyHours: Record<string, number> = {};

      if (uniqueUserIds.length > 0 && shift.date) {
        const shiftDate = new Date(shift.date);
        const dayOfWeek = shiftDate.getDay();
        const weekStart = new Date(shiftDate);
        weekStart.setDate(weekStart.getDate() - dayOfWeek);
        const weekEnd = new Date(weekStart);
        weekEnd.setDate(weekEnd.getDate() + 6);

        const weekStartStr = weekStart.toISOString().split('T')[0];
        const weekEndStr = weekEnd.toISOString().split('T')[0];

        const weeklyHoursResult = await db.execute(sql`
          SELECT sa.user_id, SUM(COALESCE(sa.scheduled_hours::numeric, 0)) AS weekly_hours
          FROM shift_assignments sa
          JOIN shifts s ON sa.shift_id = s.id
          WHERE sa.user_id = ANY(${uniqueUserIds})
            AND s.date >= ${weekStartStr}
            AND s.date <= ${weekEndStr}
            AND sa.status IN ('assigned', 'confirmed')
          GROUP BY sa.user_id
        `);

        const weeklyMap: Record<string, number> = {};
        for (const row of (weeklyHoursResult.rows || []) as any[]) {
          weeklyMap[row.user_id] = parseFloat(row.weekly_hours || '0');
        }

        const shiftDuration = (shift.endTime.getTime() - shift.startTime.getTime()) / (1000 * 60 * 60);
        let newShiftDuration = shiftDuration;
        if (changeType === 'time_change') {
          const newStart = proposed?.startTime ? new Date(proposed.startTime) : shift.startTime;
          const newEnd = proposed?.endTime ? new Date(proposed.endTime) : shift.endTime;
          newShiftDuration = (newEnd.getTime() - newStart.getTime()) / (1000 * 60 * 60);
        }

        const durationDelta = newShiftDuration - shiftDuration;

        for (const uid of uniqueUserIds) {
          const currentHours = weeklyMap[uid] || 0;
          let projectedHours = currentHours;

          if (changeType === 'time_change') {
            projectedHours = currentHours + durationDelta;
          } else if (changeType === 'assignment_add' && !currentAssignments.find(a => a.userId === uid)) {
            projectedHours = currentHours + newShiftDuration;
          } else if (changeType === 'assignment_remove' && uid === proposed?.userId) {
            projectedHours = currentHours - shiftDuration;
          }

          beforeWeeklyHours[uid] = currentHours;
          afterWeeklyHours[uid] = projectedHours;

          if (projectedHours > 40) {
            const [userInfo] = await db.select({ firstName: users.firstName, lastName: users.lastName, email: users.email })
              .from(users).where(eq(users.id, uid)).limit(1);
            const userName = userInfo
              ? (userInfo.firstName && userInfo.lastName ? `${userInfo.firstName} ${userInfo.lastName}` : userInfo.email || uid)
              : uid;

            otImpact.push({
              userId: uid,
              userName,
              currentWeeklyHours: currentHours,
              projectedWeeklyHours: projectedHours,
              overtimeHours: projectedHours - 40,
            });
          }
        }
      }

      let riskLevel: 'low' | 'medium' | 'high' = 'low';
      if ((otImpact.length > 0 && costDeltaPct > 20) || gapDelta > 0) {
        riskLevel = 'high';
      } else if (otImpact.length > 0 || costDeltaPct > 10) {
        riskLevel = 'medium';
      }

      if (otImpact.length > 0) {
        reasons.push(`${otImpact.length} driver(s) would exceed 40h weekly overtime threshold`);
      }
      if (gapDelta > 0) {
        reasons.push(`Coverage gap increases by ${gapDelta}`);
      }
      if (Math.abs(costDeltaPct) > 5) {
        reasons.push(`Cost ${costDelta > 0 ? 'increases' : 'decreases'} by ${Math.abs(costDeltaPct).toFixed(1)}%`);
      }

      const requiresConfirmation = riskLevel === 'high' || riskLevel === 'medium';

      res.json({
        before: {
          totalCost: Math.round(beforeCost * 100) / 100,
          assignedStaff: beforeAssigned,
          requiredStaff: beforeRequired,
          coverageGap: beforeCoverageGap,
          weeklyHours: beforeWeeklyHours,
        },
        after: {
          totalCost: Math.round(afterCost * 100) / 100,
          assignedStaff: afterAssigned,
          requiredStaff: afterRequired,
          coverageGap: afterCoverageGap,
          weeklyHours: afterWeeklyHours,
        },
        deltas: {
          costDelta: Math.round(costDelta * 100) / 100,
          costDeltaPct: Math.round(costDeltaPct * 100) / 100,
          staffDelta,
          gapDelta,
        },
        otImpact,
        riskLevel,
        reasons,
        requiresConfirmation,
      });
    } catch (error: any) {
      console.error('Error computing impact analysis:', error);
      res.status(500).json({ message: 'Failed to compute impact analysis' });
    }
  });

  // ── Scheduling Compliance Evidence Pack ──

  app.post('/api/corporate/scheduling/compliance-evidence/generate', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin'].includes(user.role)) {
        return res.status(403).json({ message: 'Only admins can generate compliance evidence' });
      }

      const { reportType, startDate, endDate, locationId } = req.body;
      if (!reportType || !startDate || !endDate) {
        return res.status(400).json({ message: 'reportType, startDate, and endDate are required' });
      }

      const validTypes = ['ot_alerts', 'break_compliance', 'missed_shift_handling', 'override_justifications'];
      if (!validTypes.includes(reportType)) {
        return res.status(400).json({ message: 'Invalid reportType. Valid: ' + validTypes.join(', ') });
      }

      const packId = `CEP-${Date.now()}-${Math.random().toString(36).substring(2, 8)}`;
      const rows: any[] = [];

      if (reportType === 'ot_alerts') {
        const otResult = await db.execute(sql`
          SELECT ts.id, ts.user_id, ts.period_start, ts.period_end,
            ts.regular_hours, ts.overtime_hours, ts.double_time_hours, ts.total_hours,
            ts.status, ts.submitted_at, ts.reviewed_by, ts.review_notes,
            u.first_name, u.last_name, u.email
          FROM timesheets ts
          JOIN users u ON ts.user_id = u.id
          WHERE ts.period_start >= ${startDate}
            AND ts.period_end <= ${endDate}
            AND (ts.overtime_hours::numeric > 0 OR ts.double_time_hours::numeric > 0)
          ORDER BY ts.period_start, u.last_name
        `);
        for (const row of (otResult.rows || []) as any[]) {
          rows.push({
            evidenceType: 'OT Alert',
            employeeName: (row.first_name || '') + ' ' + (row.last_name || ''),
            employeeEmail: row.email || '',
            periodStart: row.period_start,
            periodEnd: row.period_end,
            regularHours: row.regular_hours || '0',
            overtimeHours: row.overtime_hours || '0',
            doubleTimeHours: row.double_time_hours || '0',
            totalHours: row.total_hours || '0',
            timesheetStatus: row.status || '',
            reviewedBy: row.reviewed_by || '',
            reviewNotes: row.review_notes || '',
            submittedAt: row.submitted_at || '',
          });
        }
      } else if (reportType === 'break_compliance') {
        const breakResult = await db.execute(sql`
          SELECT tce.id, tce.user_id, tce.event_type, tce.event_time,
            tce.shift_assignment_id, tce.is_within_geofence, tce.latitude, tce.longitude,
            u.first_name, u.last_name, u.email,
            s.date as shift_date, s.start_time as shift_start, s.end_time as shift_end,
            s.break_duration as required_break_minutes
          FROM time_clock_events tce
          JOIN users u ON tce.user_id = u.id
          LEFT JOIN shift_assignments sa ON tce.shift_assignment_id = sa.id
          LEFT JOIN shifts s ON sa.shift_id = s.id
          WHERE tce.event_type IN ('break_start', 'break_end')
            AND tce.event_time >= ${startDate}::date
            AND tce.event_time <= (${endDate}::date + interval '1 day')
          ORDER BY tce.event_time
        `);

        const breakPairs: Record<string, any> = {};
        for (const evt of (breakResult.rows || []) as any[]) {
          const key = (evt.shift_assignment_id || 'manual') + ':' + evt.user_id;
          if (!breakPairs[key]) {
            breakPairs[key] = { starts: [], ends: [], user: evt };
          }
          if (evt.event_type === 'break_start') breakPairs[key].starts.push(evt);
          else breakPairs[key].ends.push(evt);
        }

        for (const [, pair] of Object.entries(breakPairs)) {
          const u = (pair as any).user;
          const breakCount = Math.max((pair as any).starts.length, (pair as any).ends.length);
          let totalBreakMinutes = 0;
          for (let i = 0; i < Math.min((pair as any).starts.length, (pair as any).ends.length); i++) {
            const start = new Date((pair as any).starts[i].event_time);
            const end = new Date((pair as any).ends[i].event_time);
            totalBreakMinutes += (end.getTime() - start.getTime()) / (1000 * 60);
          }
          const requiredBreak = u.required_break_minutes || 30;
          const compliant = totalBreakMinutes >= requiredBreak;
          rows.push({
            evidenceType: 'Break Compliance',
            employeeName: (u.first_name || '') + ' ' + (u.last_name || ''),
            employeeEmail: u.email || '',
            shiftDate: u.shift_date || '',
            breaksTaken: breakCount,
            totalBreakMinutes: Math.round(totalBreakMinutes),
            requiredBreakMinutes: requiredBreak,
            compliant: compliant ? 'Yes' : 'No',
            withinGeofence: u.is_within_geofence != null ? (u.is_within_geofence ? 'Yes' : 'No') : 'N/A',
          });
        }
      } else if (reportType === 'missed_shift_handling') {
        const noShowResult = await db.execute(sql`
          SELECT sa.id as assignment_id, sa.user_id, sa.shift_id, sa.status as assignment_status,
            sa.notes as assignment_notes, sa.assignment_role,
            s.date as shift_date, s.start_time, s.end_time,
            u.first_name, u.last_name, u.email,
            wl.name as location_name
          FROM shift_assignments sa
          JOIN shifts s ON sa.shift_id = s.id
          JOIN users u ON sa.user_id = u.id
          LEFT JOIN work_locations wl ON s.location_id = wl.id
          WHERE sa.status IN ('no_show', 'declined')
            AND s.date >= ${startDate}
            AND s.date <= ${endDate}
          ORDER BY s.date, s.start_time
        `);

        const backupResult = await db.execute(sql`
          SELECT sba.shift_id, sba.user_id, sba.activated_by, sba.prior_role,
            sba.new_role, sba.reason, sba.activated_at,
            u.first_name as backup_first, u.last_name as backup_last,
            u2.first_name as activated_by_first, u2.last_name as activated_by_last
          FROM scheduling_backup_activations sba
          JOIN users u ON sba.user_id = u.id
          JOIN users u2 ON sba.activated_by = u2.id
          JOIN shifts s ON sba.shift_id = s.id
          WHERE s.date >= ${startDate} AND s.date <= ${endDate}
        `);

        const backupsByShift: Record<string, any[]> = {};
        for (const b of (backupResult.rows || []) as any[]) {
          if (!backupsByShift[b.shift_id]) backupsByShift[b.shift_id] = [];
          backupsByShift[b.shift_id].push(b);
        }

        for (const row of (noShowResult.rows || []) as any[]) {
          const backups = backupsByShift[row.shift_id] || [];
          const backupInfo = backups.map((b: any) =>
            (b.backup_first || '') + ' ' + (b.backup_last || '') + ' (activated by ' + (b.activated_by_first || '') + ' ' + (b.activated_by_last || '') + ')'
          ).join('; ');
          rows.push({
            evidenceType: 'Missed Shift',
            employeeName: (row.first_name || '') + ' ' + (row.last_name || ''),
            employeeEmail: row.email || '',
            shiftDate: row.shift_date || '',
            shiftStart: row.start_time || '',
            shiftEnd: row.end_time || '',
            location: row.location_name || '',
            status: row.assignment_status || '',
            role: row.assignment_role || '',
            notes: row.assignment_notes || '',
            backupActivation: backupInfo || 'None',
          });
        }
      } else if (reportType === 'override_justifications') {
        const overrideResult = await db.execute(sql`
          SELECT sal.id, sal.actor_user_id, sal.action_type, sal.entity_type,
            sal.entity_id, sal.previous_data, sal.new_data, sal.metadata,
            sal.created_at,
            u.first_name, u.last_name, u.email
          FROM scheduling_audit_log sal
          JOIN users u ON sal.actor_user_id = u.id
          WHERE sal.action_type IN ('override', 'manual_edit', 'force_approve', 'role_change', 'manual_clock', 'time_adjustment', 'schedule_override')
            AND sal.created_at >= ${startDate}::date
            AND sal.created_at <= (${endDate}::date + interval '1 day')
          ORDER BY sal.created_at DESC
        `);

        for (const row of (overrideResult.rows || []) as any[]) {
          const meta = (row.metadata || {}) as any;
          rows.push({
            evidenceType: 'Override',
            timestamp: row.created_at || '',
            actorName: (row.first_name || '') + ' ' + (row.last_name || ''),
            actorEmail: row.email || '',
            actionType: row.action_type || '',
            entityType: row.entity_type || '',
            entityId: row.entity_id || '',
            justification: meta.reason || meta.justification || meta.notes || '',
            previousValue: JSON.stringify(row.previous_data || {}),
            newValue: JSON.stringify(row.new_data || {}),
          });
        }
      }

      const crypto = require('crypto');
      const evidenceRecords = rows.map(row => ({
        packId,
        reportType,
        sourceEntityType: row.entityType || reportType,
        sourceEntityId: row.entityId || row.assignment_id || null,
        snapshotData: row,
        contentHash: crypto.createHash('sha256').update(JSON.stringify(row)).digest('hex'),
        generatedBy: resolvedId,
        dateRangeStart: startDate,
        dateRangeEnd: endDate,
        locationId: locationId || null,
      }));

      if (evidenceRecords.length > 0) {
        for (let i = 0; i < evidenceRecords.length; i += 100) {
          const batch = evidenceRecords.slice(i, i + 100);
          await db.insert(schedulingComplianceEvidence).values(batch);
        }
      }

      res.json({
        packId,
        reportType,
        recordCount: rows.length,
        dateRange: { startDate, endDate },
        generatedAt: new Date().toISOString(),
        generatedBy: user.firstName + ' ' + user.lastName,
      });
    } catch (error: any) {
      console.error('Error generating compliance evidence:', error);
      res.status(500).json({ message: 'Failed to generate compliance evidence' });
    }
  });

