  app.get('/api/corporate/scheduling/compliance-evidence/:packId/download', isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedId = await resolveSchedulingUserId(req);
      if (!resolvedId) return res.status(401).json({ message: 'Unauthorized' });
      const user = await storage.getUser(resolvedId);
      if (!user || !['super_user', 'admin', 'auditor'].includes(user.role)) {
        return res.status(403).json({ message: 'Access denied' });
      }

      const { packId } = req.params;
      const records = await db.select()
        .from(schedulingComplianceEvidence)
        .where(eq(schedulingComplianceEvidence.packId, packId))
        .orderBy(asc(schedulingComplianceEvidence.createdAt));

      if (records.length === 0) {
        return res.status(404).json({ message: 'Evidence pack not found' });
      }

      const reportType = records[0].reportType;
      const snapshots = records.map(r => r.snapshotData as any);

      if (snapshots.length === 0) {
        return res.status(404).json({ message: 'No records in evidence pack' });
      }

      const headers = Object.keys(snapshots[0]);
      const csvLines = [headers.join(',')];
      for (const snap of snapshots) {
        const line = headers.map(h => {
          const val = String(snap[h] ?? '').replace(/"/g, '""');
          return '"' + val + '"';
        }).join(',');
        csvLines.push(line);
      }

      const csvContent = csvLines.join('\n');
      const filename = reportType + '_evidence_' + packId + '.csv';

      res.setHeader('Content-Type', 'text/csv');
      res.setHeader('Content-Disposition', 'attachment; filename="' + filename + '"');
      res.send(csvContent);
    } catch (error: any) {
      console.error('Error downloading compliance evidence:', error);
      res.status(500).json({ message: 'Failed to download compliance evidence' });
    }
  });

