  // POST /api/scheduling/offline-sync - Process queued offline clock actions with conflict resolution
  app.post("/api/scheduling/offline-sync", isAuthenticated, async (req: any, res: Response) => {
    try {
      const resolvedUserId = await resolveSchedulingUserId(req);
      if (!resolvedUserId) {
        return res.status(401).json({ message: "Unauthorized" });
      }

      const [user] = await db.select().from(users).where(eq(users.id, resolvedUserId)).limit(1);
      if (!user) {
        return res.status(401).json({ message: "User not found" });
      }

      const { actions } = req.body;
      if (!actions || !Array.isArray(actions)) {
        return res.status(400).json({ message: "Missing or invalid actions array" });
      }

      const results: Array<{ id: string; status: string; message?: string }> = [];
      let syncedCount = 0;
      let conflictCount = 0;
      let failedCount = 0;

      for (const action of actions) {
        try {
          const { id, assignmentId, actionType, timestamp, latitude, longitude, notes } = action;

          const [assignment] = await db.select()
            .from(shiftAssignments)
            .where(and(eq(shiftAssignments.id, assignmentId), eq(shiftAssignments.userId, resolvedUserId)))
            .limit(1);

          if (!assignment) {
            results.push({ id, status: 'failed', message: 'Assignment not found or unauthorized' });
            failedCount++;
            continue;
          }

          const conflictCheck = await db.select({ eventTime: timeClockEvents.eventTime })
            .from(timeClockEvents)
            .where(and(eq(timeClockEvents.shiftAssignmentId, assignmentId), eq(timeClockEvents.eventType, actionType)))
            .orderBy(desc(timeClockEvents.eventTime))
            .limit(1);

          if (conflictCheck.length > 0 && conflictCheck[0].eventTime && new Date(conflictCheck[0].eventTime) >= new Date(timestamp)) {
            results.push({ id, status: 'conflict', message: 'Server has newer event' });
            conflictCount++;
            continue;
          }

          await db.insert(timeClockEvents).values({
            userId: resolvedUserId,
            shiftAssignmentId: assignmentId,
            eventType: actionType,
            eventTime: new Date(timestamp),
            latitude: latitude?.toString() ?? null,
            longitude: longitude?.toString() ?? null,
            notes: notes || null,
            deviceInfo: 'offline-sync',
          });

          if (actionType === 'clock_in') {
            await db.update(shiftAssignments).set({ status: 'in_progress' }).where(eq(shiftAssignments.id, assignmentId));
          } else if (actionType === 'clock_out') {
            await db.update(shiftAssignments).set({ status: 'completed' }).where(eq(shiftAssignments.id, assignmentId));
          }

          results.push({ id, status: 'synced' });
          syncedCount++;
        } catch (actionError: any) {
          results.push({ id: action.id, status: 'failed', message: actionError.message || 'Processing error' });
          failedCount++;
        }
      }

      res.json({
        results,
        syncedCount,
        conflictCount,
        failedCount,
        syncedAt: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error('Error processing offline sync:', error);
      res.status(500).json({ message: 'Failed to process offline sync' });
    }
  });

