  app.get("/api/recruiting/metrics/recruiter-productivity", async (req: any, res: Response) => {
    const userId = (req.session as any)?.userId || req.user?.claims?.sub;
    if (!userId) return res.status(401).json({ message: "Authentication required" });
    try {
      const userRecord = await db.query.users.findFirst({ where: eq(users.id, userId) });
      if (!userRecord || !["admin", "super_user"].includes(userRecord.role || "")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { startDate, endDate } = req.query;

      const metrics = await db.execute(sql`
        WITH recruiter_apps AS (
          SELECT
            ra.owner_id,
            u.first_name || ' ' || u.last_name AS recruiter_name,
            u.email AS recruiter_email,
            COUNT(*) AS total_applications,
            COUNT(*) FILTER (WHERE ra.current_stage = 'hired') AS hired_count,
            COUNT(*) FILTER (WHERE ra.current_stage = 'rejected') AS rejected_count,
            COUNT(*) FILTER (WHERE ra.current_stage = 'withdrawn') AS withdrawn_count,
            COUNT(*) FILTER (WHERE ra.readiness_status = 'ready') AS ready_count,
            COUNT(*) FILTER (WHERE ra.current_stage NOT IN ('hired','rejected','withdrawn','archived')) AS active_count
          FROM recruiting_applications ra
          JOIN users u ON ra.owner_id = u.id
          WHERE ra.owner_id IS NOT NULL
            AND ra.is_archived = false
            ${startDate ? sql`AND ra.created_at >= ${startDate}` : sql``}
            ${endDate ? sql`AND ra.created_at <= ${endDate}` : sql``}
          GROUP BY ra.owner_id, u.first_name, u.last_name, u.email
        ),
        avg_stage_time AS (
          SELECT
            ra.owner_id,
            COALESCE(AVG(rsh.time_in_previous_stage_minutes), 0) AS avg_time_in_stage_minutes
          FROM recruiting_applications ra
          JOIN recruiting_stage_history rsh ON ra.id = rsh.application_id
          WHERE ra.owner_id IS NOT NULL
            AND ra.is_archived = false
            ${startDate ? sql`AND ra.created_at >= ${startDate}` : sql``}
            ${endDate ? sql`AND ra.created_at <= ${endDate}` : sql``}
          GROUP BY ra.owner_id
        ),
        time_to_ready AS (
          SELECT
            ra.owner_id,
            AVG(EXTRACT(EPOCH FROM (
              CASE WHEN ra.readiness_status = 'ready' AND ra.readiness_last_calculated_at IS NOT NULL
                THEN ra.readiness_last_calculated_at - ra.created_at
                ELSE NULL END
            )) / 86400.0) AS avg_days_to_ready
          FROM recruiting_applications ra
          WHERE ra.owner_id IS NOT NULL
            AND ra.readiness_status = 'ready'
            AND ra.is_archived = false
            ${startDate ? sql`AND ra.created_at >= ${startDate}` : sql``}
            ${endDate ? sql`AND ra.created_at <= ${endDate}` : sql``}
          GROUP BY ra.owner_id
        )
        SELECT
          rap.owner_id,
          rap.recruiter_name,
          rap.recruiter_email,
          rap.total_applications,
          rap.hired_count,
          rap.rejected_count,
          rap.withdrawn_count,
          rap.ready_count,
          rap.active_count,
          COALESCE(ast.avg_time_in_stage_minutes, 0) AS avg_time_in_stage_minutes,
          COALESCE(ttr.avg_days_to_ready, 0) AS avg_days_to_ready
        FROM recruiter_apps rap
        LEFT JOIN avg_stage_time ast ON rap.owner_id = ast.owner_id
        LEFT JOIN time_to_ready ttr ON rap.owner_id = ttr.owner_id
        ORDER BY rap.total_applications DESC
      `);

      res.json(metrics.rows || []);
    } catch (error: any) {
      console.error("Error fetching recruiter productivity metrics:", error);
      res.status(500).json({ message: error.message || "Failed to fetch metrics" });
    }
  });


