  // GET /api/recruiting/requests/pending - Exec-only pending approval queue
  app.get("/api/recruiting/requests/pending", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      // Only exec/approval roles may access the pending queue
      const EXEC_ROLES = ["super_user","super_admin","root_super_admin","corporate_admin","admin","manager","recruiting_admin"];
      if (!user || !EXEC_ROLES.includes(user.role || "")) {
        return res.status(403).json({ message: "Insufficient permissions — exec role required" });
      }
      const { db }               = await import("./db");
      const { recruitingRequests } = await import("@shared/schema");
      const { or, eq, inArray }   = await import("drizzle-orm");
      const rows = await db.select()
        .from(recruitingRequests)
        .where(
          or(
            inArray(recruitingRequests.requestStatus, ["submitted", "under_review"]),
            eq(recruitingRequests.approvalStatus, "pending"),
          )
        )
        .orderBy(recruitingRequests.submittedAt);   // oldest first — approval queue priority
      res.json(rows);
    } catch (error: any) {
      console.error("[Recruiting Requests/Pending] GET error:", error);
      res.status(500).json({ message: "Failed to fetch pending requests" });
    }
  });

  // GET /api/recruiting/requests - List all requests (admin) or user's own (excludes archived)
  app.get("/api/recruiting/requests", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const recruitingContext = await getUserRecruitingContext(userId, user.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db } = await import("./db");
      const { recruitingRequests, recruitingRequisitions } = await import("@shared/schema");
      const { eq, and, desc, inArray } = await import("drizzle-orm");
      const isAdmin = ["corporate","admin","super_user","super_admin","root_super_admin","corporate_admin","manager","recruiter","recruiting_admin","hiring_manager"].includes(user.role || "");
      let rows: any[];
      if (isAdmin) {
        rows = await db.select().from(recruitingRequests)
          .where(eq(recruitingRequests.isArchived, false))
          .orderBy(desc(recruitingRequests.submittedAt));
      } else {
        rows = await db.select().from(recruitingRequests)
          .where(and(
            eq(recruitingRequests.submittedBy, userId),
            eq(recruitingRequests.isArchived, false),
          ))
          .orderBy(desc(recruitingRequests.submittedAt));
      }
      // Enrich with linked requisition status → campaignStatus
      const reqIds = rows.map((r: any) => r.campaignRequisitionId).filter(Boolean) as string[];
      let statusMap: Record<string, string> = {};
      if (reqIds.length > 0) {
        const statuses = await db
          .select({ id: recruitingRequisitions.id, status: recruitingRequisitions.status })
          .from(recruitingRequisitions)
          .where(inArray(recruitingRequisitions.id, reqIds));
        for (const s of statuses) { if (s.id) statusMap[s.id] = s.status ?? ""; }
      }
      res.json(rows.map((r: any) => ({
        ...r,
        campaignStatus: r.campaignRequisitionId ? (statusMap[r.campaignRequisitionId] ?? null) : null,
        canManageJobPostings: hasRecruitingJobPostingWriteAccess(recruitingContext),
      })));
    } catch (error: any) {
      console.error("[Recruiting Requests] GET error:", error);
      res.status(500).json({ message: "Failed to fetch recruiting requests" });
    }
  });

