  // POST /api/recruiting/requests/:id/archive - Archive (soft-delete) a campaign
  app.post("/api/recruiting/requests/:id/archive", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });

      const ARCHIVE_ROLES = ["super_user","super_admin","root_super_admin","corporate_admin"];
      const isRootSuperAdmin = (user as any)?.isRootSuperAdmin ?? false;
      if (!ARCHIVE_ROLES.includes(user.role || "") && !isRootSuperAdmin) {
        return res.status(403).json({ message: "Only Super Admins and Corporate Admins can archive campaigns." });
      }

      const { reason } = req.body;
      if (!reason?.trim()) {
        return res.status(400).json({ message: "An archive reason is required." });
      }

      const { db } = await import("./db");
      const { recruitingRequests, recruitingRequisitions, recruitingApplications, recruitingAuditEvents } = await import("@shared/schema");
      const { eq, and, inArray } = await import("drizzle-orm");

      const [existing] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, req.params.id));
      if (!existing) return res.status(404).json({ message: "Campaign not found" });
      if (existing.isArchived) return res.status(409).json({ message: "Campaign is already archived" });

      // Check for active applications (warn in response but allow archive)
      let activeApplicationCount = 0;
      if (existing.campaignRequisitionId) {
        const activeStages = ["new","screening","interview","offer"];
        const activeApps = await db.select({ id: recruitingApplications.id })
          .from(recruitingApplications)
          .where(and(
            eq(recruitingApplications.requisitionId, existing.campaignRequisitionId),
            inArray(recruitingApplications.currentStage, activeStages),
          ));
        activeApplicationCount = activeApps.length;
      }

      const now = new Date();
      const actorName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;

      const [updated] = await db.update(recruitingRequests)
        .set({
          isArchived:            true,
          archivedAt:            now,
          archivedBy:            actorName,
          archiveReason:         reason.trim(),
          archivePreviousStatus: existing.requestStatus,
          updatedAt:             now,
        })
        .where(eq(recruitingRequests.id, req.params.id))
        .returning();

      // Audit log
      try {
        await db.insert(recruitingAuditEvents).values({
          actionType:     "campaign_archived",
          entityType:     "recruiting_request",
          entityId:       req.params.id,
          userId,
          userEmail:      user.email || undefined,
          actorRole:      user.role || undefined,
          source:         "ui",
          previousValue:  JSON.stringify({ requestStatus: existing.requestStatus, isArchived: false }),
          newValue:       JSON.stringify({ requestStatus: existing.requestStatus, isArchived: true }),
          changedFields:  ["is_archived", "archived_at", "archived_by", "archive_reason"],
          reason:         reason.trim(),
          metadata:       { archivedBy: actorName, activeApplicationCount },
        });
      } catch (auditErr) {
        console.error("[Archive] Audit log failed (non-fatal):", auditErr);
      }

      res.json({ success: true, campaign: updated, activeApplicationCount });
    } catch (error: any) {
      console.error("[Recruiting Requests/:id/archive] POST error:", error);
      res.status(500).json({ message: "Failed to archive campaign" });
    }
  });

  // POST /api/recruiting/requests - Submit a new recruiting request
  app.post("/api/recruiting/requests", async (req: Request, res: Response) => {
    const idempotencyKey = req.get("x-idempotency-key") || req.get("idempotency-key");
    let idempotencyStarted = false;
    let idempotencyScope: string | null = null;
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json(recruitingSubmissionError(
          "NOT_AUTHENTICATED", "authentication", "Your session has expired. Please sign in and try again.",
        ));
      }
      const user = await storage.getUser(userId);
      if (!user) {
        return res.status(401).json(recruitingSubmissionError(
          "NOT_AUTHENTICATED", "authentication", "Your session has expired. Please sign in and try again.",
        ));
      }
      const { db } = await import("./db");
      const { recruitingRequests, isApprovedEmploymentType } = await import("@shared/schema");

      const orgId = (user as any).orgId || "26c087eb-0d86-4a4c-b48e-e2049323ccfd";
      const submittedByName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;
      // DH-002334: the staging database is shared by real Recruiting users and the
      // dedicated Gate 0 UAT identities (see server/scripts/provision_gate0_uat_users.ts),
      // which are always provisioned on the reserved @driverhub-staging.test domain.
      // Flag records created by those identities so operational reports/KPIs can
      // exclude them without deleting anything.
      const isTestDataSubmission = typeof user.email === "string"
        && user.email.toLowerCase().endsWith("@driverhub-staging.test");

      const {
        requestOrigin, accountId, location,
        campaignType, urgency, dealershipName,
        driverClassification, driverType, driverTypes,
        vehicleLicenseClass, programType, employmentType,
        targetDriverCount, payRate,
        signOnBonusOption, signOnBonusNotes, signOnBonus, signOnBonusAmount,
        targetDate, recruiter, certLiaison,
        driverSchedule, additionalComments,
        // legacy fields
        market, marketCode, address, city, state, zipCode, phoneInterviewContact,
        network,
        // clone linkage (set when request is cloned from a closed campaign)
        clonedFromCampaignId,
      } = req.body;

      const fieldErrors: Record<string, string> = {};
      if (!campaignType) fieldErrors.campaignType = "Campaign type is required.";
      if (urgency == null || !Number.isInteger(Number(urgency)) || Number(urgency) < 1 || Number(urgency) > 5) {
        fieldErrors.urgency = "Urgency must be a whole number from 1 to 5.";
      }
      if (Object.keys(fieldErrors).length > 0) {
        console.warn("[Recruiting Requests] Validation failed", { userId, fields: Object.keys(fieldErrors) });
        return res.status(400).json(recruitingSubmissionError(
          "VALIDATION_FAILED", "validation", "Review the highlighted fields and try again.", { fieldErrors },
        ));
      }
      if (employmentType != null && !isApprovedEmploymentType(employmentType)) {
        return res.status(400).json(recruitingSubmissionError(
          "INVALID_EMPLOYMENT_TYPE", "validation",
          "Employment Type must be Part-Time, Full-Time, or On-Call.",
          { fieldErrors: { employmentType: "Select Part-Time, Full-Time, or On-Call." } },
        ));
      }
      const canonicalCertLiaison = certLiaison === "Lisa Wickers" ? "Lisa Parkhurst" : certLiaison;
      if (canonicalCertLiaison) {
        const { CERT_LIAISON_VALUES } = await import("@shared/schema");
        if (!(CERT_LIAISON_VALUES as readonly string[]).includes(canonicalCertLiaison)) {
          return res.status(400).json(recruitingSubmissionError(
            "INVALID_CERT_LIAISON", "validation",
            "Cert Liaison must be selected from the approved liaison list.",
            { fieldErrors: { certLiaison: "Choose a liaison from the approved list." } },
          ));
        }
      }

      if (idempotencyKey) {
        if (idempotencyKey.length > 255) {
          return res.status(400).json(recruitingSubmissionError(
            "INVALID_IDEMPOTENCY_KEY", "validation", "The submission token is invalid. Refresh the form and try again.",
          ));
        }
        idempotencyScope = `recruiting_request_submit:${userId}`;
        const idempotencyResult = await checkIdempotency(
          idempotencyScope, idempotencyKey, hashRequestBody(req.body), userId,
        );
        if (!idempotencyResult.isNew && idempotencyResult.cachedResponse) {
          if (idempotencyResult.cachedResponse.status === 409) {
            return res.status(409).json(recruitingSubmissionError(
              "SUBMISSION_IN_PROGRESS", "conflict",
              "This request is still being submitted. Please wait a moment before trying again.",
              { retryable: true },
            ));
          }
          console.info("[Recruiting Requests] Replayed completed submission", { userId });
          return res.status(idempotencyResult.cachedResponse.status).json({
            ...(idempotencyResult.cachedResponse.body as object),
            idempotentReplay: true,
          });
        }
        idempotencyStarted = true;
      }

      // Auto-generate request number: WFR-YYYY-NNNN
      const { sql: sqlHelper } = await import("drizzle-orm");
      const seqRow = await db.execute(sqlHelper`SELECT nextval('recruiting_request_number_seq') AS seq`);
      const seq = (seqRow.rows?.[0] as any)?.seq ?? Date.now();
      const requestNumber = `WFR-${new Date().getFullYear()}-${String(seq).padStart(4, "0")}`;

      // Extract businessReason and asSavedDraft from body
      const { businessReason, asDraft } = req.body;
      const initialStatus = asDraft ? "draft" : "submitted";

      const [newRequest] = await db.insert(recruitingRequests).values({
        orgId,
        submittedBy: userId,
        submittedByName,
        requestNumber,
        requestOrigin: requestOrigin || null,
        accountId: accountId || null,
        location: location || null,
        campaignType,
        urgency: Number(urgency),
        dealershipName: dealershipName || null,
        driverClassification: driverClassification || null,
        driverType: driverType || null,
        vehicleLicenseClass: vehicleLicenseClass || null,
        programType: programType || null,
        employmentType: employmentType || null,
        driverTypes: Array.isArray(driverTypes) ? driverTypes : (driverType ? [driverType] : []),
        targetDriverCount: targetDriverCount ? Number(targetDriverCount) : null,
        payRate: payRate ? String(payRate) : null,
        signOnBonusOption: signOnBonusOption || null,
        signOnBonusNotes: signOnBonusNotes || null,
        signOnBonus: signOnBonusOption ? signOnBonusOption !== "no_bonus" : !!signOnBonus,
        signOnBonusAmount: signOnBonusAmount ? String(signOnBonusAmount) : null,
        // The Campaign Start Date is established only by Request approval.
        campaignStartDate: null,
        targetDate: targetDate || null,
        recruiter: recruiter || null,
        certLiaison: canonicalCertLiaison || null,
        driverSchedule: driverSchedule || null,
        additionalComments: additionalComments || null,
        businessReason: businessReason || null,
        // legacy
        market: market || null,
        marketCode: marketCode || null,
        address: address || null,
        city: city || null,
        state: state || null,
        zipCode: zipCode || null,
        network: network || null,
        phoneInterviewContact: phoneInterviewContact || null,
        requestStatus: initialStatus,
        approvalStatus: initialStatus === "draft" ? "pending" : "pending",
        // clone linkage
        clonedFromCampaignId: clonedFromCampaignId || null,
        clonedBy:             clonedFromCampaignId ? userId : null,
        clonedAt:             clonedFromCampaignId ? new Date() : null,
        isTestData: isTestDataSubmission,
      }).returning();

      // Log initial creation to activity table
      try {
        const { recruitingRequestActivity } = await import("@shared/schema");
        await db.insert(recruitingRequestActivity).values({
          orgId,
          requestId: (newRequest as any).id,
          userId,
          userName: submittedByName,
          action: "status_change",
          fromStatus: null,
          toStatus: initialStatus,
          notes: `Request ${requestNumber} created`,
        });
      } catch (_e) { /* non-fatal */ }

      // Notify fixed alert recipients (luis@, will@) on new request submission
      try {
        const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
        if (isMicrosoftGraphConfigured() || isRecruitingExternalDeliverySuppressed()) {
          const SUBMISSION_ALERT_RECIPIENTS = ["luis@driverondemand.co", "will@driverondemand.co"];
          {
            const urgencyLabels: Record<number, string> = {
              1: "1 – Maintenance / Back Up Role",
              2: "2 – Below Average",
              3: "3 – Normal",
              4: "4 – High",
              5: "5 – Critical",
            };
            const urgencyLabel = urgencyLabels[Number(urgency)] || `${urgency}`;
            const campaignLabel = (campaignType || "").charAt(0).toUpperCase() + (campaignType || "").slice(1);
            const classificationLabels: Record<string, string> = {
              w2_employee: "W-2 Employee",
              "1099_contractor": "1099 Contractor",
              temp_to_hire: "Temp-to-Hire",
              seasonal: "Seasonal",
            };
            const classificationLabel = classificationLabels[driverClassification || ""] || driverClassification || "—";
            const driverTypeLabels: Record<string, string> = {
              shift_driver: "Shift Driver",
              on_demand_driver: "On-Demand Driver",
              shuttle_driver: "Shuttle Driver",
              cdl_driver: "CDL Driver",
            };
            const driverTypeLabel = driverTypeLabels[driverType || ""] || driverType || "—";
            const bonusLabels: Record<string, string> = {
              no_bonus: "No Bonus",
              standard_500: "$500 Standard",
              standard_1000: "$1,000 Standard",
              standard_1500: "$1,500 Standard",
              standard_2000: "$2,000 Standard",
              other: "Other (see notes)",
            };
            const bonusLabel = bonusLabels[signOnBonusOption || ""] || signOnBonusOption || "—";
            const originLabels: Record<string, string> = {
              internal: "Internal Request",
              dealer_request: "Dealer / Client Request",
              growth_initiative: "Growth Initiative",
              backfill: "Backfill",
              other: "Other",
            };
            const originLabel = originLabels[requestOrigin || ""] || requestOrigin || "—";
            const row = (label: string, value: string) =>
              `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5;width:40%;white-space:nowrap">${label}</td><td style="padding:6px 12px">${value}</td></tr>`;
            const bodyHtml = `
              <div style="font-family:Arial,sans-serif;max-width:620px">
                <div style="background:#FF6B35;padding:16px 20px;border-radius:4px 4px 0 0">
                  <h2 style="color:#fff;margin:0;font-size:18px">New Recruiting Request — Approval Required</h2>
                  <p style="color:#ffe8dc;margin:4px 0 0;font-size:13px">Submitted by <strong>${submittedByName}</strong> · Pending Review</p>
                </div>
                <div style="border:1px solid #e5e7eb;border-top:none;padding:16px 20px 8px;border-radius:0 0 4px 4px">
                  <table style="width:100%;border-collapse:collapse;margin:0 0 16px">
                    <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Request Details</td></tr>
                    ${row("Request Origin", originLabel)}
                    ${row("Dealership / Account", dealershipName || "—")}
                    ${(() => { const parts = [address, [city && state ? `${city}, ${state}` : city || state, zipCode].filter(Boolean).join(" ")].filter(Boolean); return parts.length ? row("Account Address", parts.join(", ")) : ""; })()}
                    ${network ? row("Network", network) : ""}
                    ${row("Location", location || "—")}
                    ${row("Campaign Type", campaignLabel)}
                    ${row("Urgency", urgencyLabel)}
                    <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Driver Requirements</td></tr>
                    ${row("Driver Classification", classificationLabel)}
                    ${row("Driver Type", driverTypeLabel)}
                    ${row("Target # of Drivers", targetDriverCount ? String(targetDriverCount) : "—")}
                    ${row("Driver Pay Rate", payRate ? `$${Number(payRate).toFixed(2)}` : "—")}
                    ${row("Sign-On Bonus", bonusLabel)}
                    ${signOnBonusOption === "other" && signOnBonusNotes ? row("Bonus Details", signOnBonusNotes) : ""}
                    ${row("Driver Schedule", driverSchedule || "—")}
                    ${row("Target Fill Date", targetDate ? new Date(targetDate).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" }) : "—")}
                    <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Contacts</td></tr>
                    ${row("Recruiter", recruiter || "—")}
                    ${row("Cert Liaison", certLiaison || "—")}
                    ${additionalComments ? `<tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Comments</td></tr>${row("Additional Comments", additionalComments)}` : ""}
                  </table>
                  <p style="color:#6b7280;font-size:12px;border-top:1px solid #f3f4f6;padding-top:12px;margin:0">
                    Log in to <strong>DriverHub 360 → Recruiting → Requests</strong> to approve, request changes, or reject this request.
                  </p>
                </div>
              </div>`;
            let submissionAlertStatus = "success";
            let submissionAlertError: string | null = null;
            try {
              const deliveryResult = await sendEmail({
                to: SUBMISSION_ALERT_RECIPIENTS,
                subject: `[Action Required] Recruiting Request — ${campaignLabel} | ${dealershipName || location || "N/A"} | Urgency ${urgency}/5`,
                bodyHtml,
                recruitingAudit: {
                  actionType: "SUBMISSION_ALERT_SUPPRESSED",
                  entityType: "request",
                  entityId: newRequest.id,
                  userId,
                  userEmail: user.email || null,
                  actorRole: user.role || null,
                  trigger: "request_submission_alert",
                },
              });
              if (!deliveryResult.ok) {
                submissionAlertStatus = deliveryResult.skipped && deliveryResult.error === "RECRUITING_EXTERNAL_DELIVERY_SUPPRESSED"
                  ? "suppressed"
                  : "failed";
                submissionAlertError = deliveryResult.error || null;
              }
            } catch (sendErr: any) {
              submissionAlertStatus = "failed";
              submissionAlertError = sendErr?.message || String(sendErr);
            }
            console.log(`[Recruiting Requests] Submission alert — recipients: ${SUBMISSION_ALERT_RECIPIENTS.join(", ")} | status: ${submissionAlertStatus}${submissionAlertError ? ` | error: ${submissionAlertError}` : ""}`);
            try {
              const { recruitingAuditEvents: raeTable } = await import("@shared/schema");
              await db.insert(raeTable).values({
                actionType: "SUBMISSION_ALERT_SENT",
                entityType: "request",
                entityId: newRequest.id,
                userId,
                userEmail: user.email || null,
                actorRole: user.role || null,
                source: "system",
                newValue: JSON.stringify({ recipients: SUBMISSION_ALERT_RECIPIENTS, status: submissionAlertStatus, error: submissionAlertError }),
              });
            } catch { /* audit non-fatal */ }
          }
        }
      } catch (emailErr) {
        console.error("[Recruiting Requests] Submission alert failed:", emailErr);
        // Non-fatal — request already saved
      }

      // Route through the Notification Rules Engine — only the configured
      // approver(s) from recruiting_approval_settings receive this, not all exec users.
      try {
        const campaignLabel = (campaignType || "").charAt(0).toUpperCase() + (campaignType || "").slice(1);
        const shortDesc = [
          dealershipName || location || null,
          campaignLabel || null,
          driverType || null,
        ].filter(Boolean).join(" · ");
        await notify("RECRUITING_REQUEST_SUBMITTED", {
          actorUserId: userId,
          orgId,
          payload: {
            requestId: newRequest.id,
            positionTitle: shortDesc || campaignType || "a position",
            requestType: campaignType || null,
            submittedByUserId: userId,
            submittedByName: submittedByName,
            recruiterId: (newRequest as any).assignedRecruiterId || null,
            urgency,
          },
        });
      } catch (notifErr) {
        console.error("[Recruiting Requests] In-app notification failed:", notifErr);
        // Non-fatal
      }

      const responseBody = { ...newRequest, idempotentReplay: false };
      if (idempotencyKey && idempotencyScope) {
        await storage.finalizeIdempotencyKey(
          idempotencyScope, idempotencyKey, 201, responseBody, newRequest.id,
        ).catch((idempotencyError) => {
          // The request is already saved. Do not turn a durable submission into
          // a user-visible failure because the replay cache could not be updated.
          console.error("[Recruiting Requests] Idempotency finalization failed", {
            requestId: newRequest.id,
            error: idempotencyError,
          });
        });
      }
      console.info("[Recruiting Requests] Submitted", {
        requestId: newRequest.id,
        requestNumber,
        userId,
      });
      res.status(201).json(responseBody);
    } catch (error: any) {
      const referenceId = `REC-SUBMIT-${crypto.randomUUID()}`;
      console.error("[Recruiting Requests] POST error", { referenceId, error });
      if (idempotencyKey && idempotencyScope && idempotencyStarted) {
        await storage.finalizeIdempotencyKey(
          idempotencyScope,
          idempotencyKey,
          500,
          recruitingSubmissionError(
            "REQUEST_SUBMISSION_FAILED",
            "server",
            "We couldn't submit this request. Please contact support and provide the reference below.",
            { referenceId },
          ),
        ).catch(() => {});
      }
      res.status(500).json(recruitingSubmissionError(
        "REQUEST_SUBMISSION_FAILED",
        "server",
        "We couldn't submit this request. Please contact support and provide the reference below.",
        { referenceId },
      ));
    }
  });

  // GET /api/recruiting/requests/:id - Single request detail (authenticated)
  app.get("/api/recruiting/requests/:id", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db }                 = await import("./db");
      const { recruitingRequests } = await import("@shared/schema");
      const { eq }                 = await import("drizzle-orm");
      const [row] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, req.params.id));
      if (!row) return res.status(404).json({ message: "Request not found" });
      // Enrich with linked requisition status → campaignStatus
      let campaignStatus: string | null = null;
      if (row.campaignRequisitionId) {
        const { recruitingRequisitions } = await import("@shared/schema");
        const [linked] = await db
          .select({ status: recruitingRequisitions.status })
          .from(recruitingRequisitions)
          .where(eq(recruitingRequisitions.id, row.campaignRequisitionId));
        campaignStatus = linked?.status ?? null;
      }
      res.json({
        ...row,
        campaignStatus,
        canManageJobPostings: hasRecruitingJobPostingWriteAccess(recruitingContext),
      });
    } catch (error: any) {
      console.error("[Recruiting Requests/:id] GET error:", error);
      res.status(500).json({ message: "Failed to fetch request" });
    }
  });

  // PATCH /api/recruiting/requests/:id/details - Edit campaign details (COO, admin, recruiter)
  app.patch("/api/recruiting/requests/:id/details", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const { db } = await import("./db");
      const { recruitingRequests, recruitingRequisitions, recruitingAuditEvents, isApprovedEmploymentType, CERT_LIAISON_VALUES } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const user = await db.query.users.findFirst({ where: (u, { eq }) => eq(u.id, userId) });
      const role = user?.role || "";

      const EDIT_ALLOWED_ROLES = new Set([
        "super_user", "root_super_admin", "admin", "corporate_admin", "manager", "recruiter", "recruiting_admin",
      ]);

      const existing = await db.query.recruitingRequests.findFirst({
        where: (r, { eq }) => eq(r.id, req.params.id),
      });
      if (!existing) return res.status(404).json({ message: "Request not found" });

      const actorName = `${user?.firstName || ""} ${user?.lastName || ""}`.trim() || user?.email || userId;
      const isAssignedRecruiter = existing.recruiter === actorName || existing.recruiter === userId;

      if (!EDIT_ALLOWED_ROLES.has(role) && !isAssignedRecruiter) {
        return res.status(403).json({ message: "Insufficient permissions to edit this campaign" });
      }

      const EDITABLE_FIELDS = [
        "dealershipName", "accountId", "location", "campaignType", "urgency",
        "address", "city", "state", "zipCode",
        "driverClassification", "driverType", "vehicleLicenseClass", "programType", "employmentType",
        "targetDriverCount", "payRate",
        "targetDate", "recruiter", "certLiaison",
        "driverSchedule", "additionalComments",
      ] as const;
      if (
        "employmentType" in req.body &&
        req.body.employmentType != null &&
        !isApprovedEmploymentType(req.body.employmentType)
      ) {
        return res.status(400).json({ message: "Employment Type must be Part-Time, Full-Time, or On-Call." });
      }
      if ("certLiaison" in req.body && req.body.certLiaison != null) {
        if (req.body.certLiaison === "Lisa Wickers") {
          req.body.certLiaison = "Lisa Parkhurst";
        }
        if (!(CERT_LIAISON_VALUES as readonly string[]).includes(req.body.certLiaison)) {
          return res.status(400).json({ message: "Cert Liaison must be selected from the approved liaison list." });
        }
      }

      // Build the update payload — only allow editable fields
      const updatePayload: Record<string, unknown> = { updatedAt: new Date() };
      const changedFields: string[] = [];
      const previousSnapshot: Record<string, unknown> = {};
      const newSnapshot: Record<string, unknown> = {};

      for (const field of EDITABLE_FIELDS) {
        if (field in req.body) {
          const oldVal = (existing as any)[field];
          const newVal = req.body[field];
          const oldStr = oldVal === null || oldVal === undefined ? null : String(oldVal);
          const newStr = newVal === null || newVal === undefined ? null : String(newVal);
          if (oldStr !== newStr) {
            changedFields.push(field);
            previousSnapshot[field] = oldVal ?? null;
            newSnapshot[field] = newVal ?? null;
          }
          updatePayload[field] = newVal ?? null;
        }
      }

      // DH-002168: Validate actualClosingDate before committing if closing a campaign
      if (req.body.campaignStatus === "closed") {
        const { actualClosingDate } = req.body;
        if (!actualClosingDate) {
          return res.status(400).json({ message: "Actual Closing Date is required when closing a campaign." });
        }
        const todayStr = new Date().toISOString().split("T")[0];
        if (actualClosingDate > todayStr) {
          return res.status(400).json({ message: "Actual Closing Date cannot be in the future." });
        }
        // DH-002164: Write canonical actual_closing_date directly to recruiting_requests.
        // recruiting_campaigns table is empty — the request IS the authoritative campaign record.
        updatePayload.actualClosingDate = actualClosingDate;
      }

      const [updated] = await db.update(recruitingRequests)
        .set(updatePayload as any)
        .where(eq(recruitingRequests.id, req.params.id))
        .returning();

      // Write per-field audit events
      if (changedFields.length > 0) {
        await db.insert(recruitingAuditEvents).values({
          actionType: "CAMPAIGN_DETAILS_UPDATED",
          entityType: "request",
          entityId: req.params.id,
          userId,
          userEmail: user?.email || null,
          actorRole: role || null,
          source: "ui",
          previousValue: JSON.stringify(previousSnapshot),
          newValue: JSON.stringify(newSnapshot),
          changedFields,
        });
      }

      // Handle campaign status update on the linked requisition
      const { campaignStatus } = req.body;
      // Reject "completed" — it is no longer a valid campaign status (DH-002085)
      if (campaignStatus === "completed") {
        return res.status(400).json({ message: "\"completed\" is not a valid campaign status. Use \"closed\" instead." });
      }
      if (campaignStatus && (updated as any).campaignRequisitionId) {
        const requisitionId = (updated as any).campaignRequisitionId;
        const [reqExisting] = await db.select().from(recruitingRequisitions)
          .where(eq(recruitingRequisitions.id, requisitionId));
        if (reqExisting && reqExisting.status !== campaignStatus) {
          await db.update(recruitingRequisitions)
            .set({ status: campaignStatus as any, updatedAt: new Date(), updatedBy: userId })
            .where(eq(recruitingRequisitions.id, requisitionId));
          await db.insert(recruitingAuditEvents).values({
            actionType: "CAMPAIGN_STATUS_UPDATED",
            entityType: "requisition",
            entityId: requisitionId,
            userId,
            userEmail: user?.email || null,
            actorRole: role || null,
            source: "ui",
            previousValue: JSON.stringify({ status: reqExisting.status }),
            newValue: JSON.stringify({ status: campaignStatus }),
            changedFields: ["status"],
          });
        }
      }

      // DH-002168: Stamp actual_closing_date + audit on the linked recruiting_campaign
      if (campaignStatus === "closed") {
        const { recruitingCampaigns: rCampaigns, recruitingCampaignActivity } = await import("@shared/schema");
        const { actualClosingDate } = req.body;
        const [linkedCampaign] = await db
          .select({ id: rCampaigns.id, closedAt: rCampaigns.closedAt })
          .from(rCampaigns)
          .where(eq(rCampaigns.requestId, req.params.id))
          .limit(1);
        if (linkedCampaign) {
          const campUpdate: Record<string, any> = {
            status: "closed",
            updatedAt: new Date(),
            updatedBy: userId,
            closedByUserId: userId,
            closedByName: actorName,
          };
          if (!linkedCampaign.closedAt) campUpdate.closedAt = new Date();
          if (actualClosingDate) campUpdate.actualClosingDate = actualClosingDate;
          await db.update(rCampaigns).set(campUpdate).where(eq(rCampaigns.id, linkedCampaign.id));
          await db.insert(recruitingCampaignActivity).values({
            campaignId: linkedCampaign.id,
            eventType: "campaign_closed",
            message: `Campaign closed. Actual closing date: ${actualClosingDate}.`,
            actorId: userId,
            actorName: actorName,
          });
        }
      }

      res.json({ ...updated, _changedFields: changedFields });
    } catch (error) {
      console.error("[Recruiting] Error updating campaign details:", error);
      res.status(500).json({ message: "Failed to update campaign details" });
    }
  });

  // ── DH-002142: Recruiting Campaign Activated Drivers ──────────────────────────

  // GET /api/recruiting/requests/:id/activated-drivers
  app.get("/api/recruiting/requests/:id/activated-drivers", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { pool: pgPool } = await import("./db");
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      const requestScope = await pgPool.query(
        `SELECT market FROM recruiting_requests WHERE id = $1 LIMIT 1`,
        [req.params.id],
      );
      if (requestScope.rows.length === 0) return res.status(404).json({ message: "Campaign not found" });
      // DH-002336: Campaign records frequently have no market value populated (see
      // Gate 0 evidence: market data is unreliable for scoping Driver discovery/linking).
      // Use the same module-level read gate as the sibling link/unlink routes on this
      // resource instead of a market-scoped check that denies marketless campaigns.
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: insufficient Recruiting permissions" });
      }
      const rows = await pgPool.query(
        `SELECT
           rcad.id,
           rcad.driver_id            AS "driverId",
           rcad.activation_date      AS "activationDate",
           rcad.driver_classification_at_activation AS "driverClassificationAtActivation",
           rcad.driver_type_at_activation           AS "driverTypeAtActivation",
           rcad.employment_type_at_activation       AS "employmentTypeAtActivation",
           rcad.linked_at            AS "linkedAt",
           rcad.linked_by_user_id    AS "linkedByUserId",
           COALESCE(
             NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '),
             'Driver ' || d.id
           )                         AS "displayName",
           d.employee_id             AS "employeeId",
           d.status                  AS "currentStatus",
           d.driver_classification   AS "driverClassification",
           d.driver_type             AS "driverType",
           d.employment_type         AS "employmentType",
           d.hire_date               AS "hireDate"
         FROM recruiting_campaign_activated_drivers rcad
         JOIN drivers d ON d.id = rcad.driver_id
         LEFT JOIN users u ON u.id = d.user_id
         WHERE rcad.campaign_id = $1
         ORDER BY rcad.linked_at`,
        [req.params.id]
      );
      res.json(rows.rows);
    } catch (error) {
      console.error("[Recruiting] Error fetching activated drivers:", error);
      res.status(500).json({ message: "Failed to fetch activated drivers" });
    }
  });

  // POST /api/recruiting/requests/:id/activated-drivers
  app.post("/api/recruiting/requests/:id/activated-drivers", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db } = await import("./db");
      const { pool: pgPool } = await import("./db");
      const role = user?.role || "";
      const LINK_ROLES = new Set(["super_user", "root_super_admin", "admin", "corporate_admin", "manager", "recruiter", "recruiting_admin"]);
      if (!LINK_ROLES.has(role)) return res.status(403).json({ message: "Insufficient permissions" });

      const { driverIds, reason } = req.body as { driverIds: string[]; reason?: string };
      if (!Array.isArray(driverIds) || driverIds.length === 0) {
        return res.status(400).json({ message: "driverIds must be a non-empty array" });
      }

      // Preserve the profile values at linking as historical recruiting context.
      // Current profile data is always resolved from drivers when displayed.
      const driverRows = await pgPool.query(
        `SELECT id, driver_classification, driver_type, employment_type, hire_date
         FROM drivers WHERE id = ANY($1::varchar[]) AND is_deleted = false`,
        [driverIds]
      );
      const driverMap = new Map(driverRows.rows.map((d: any) => [d.id, d]));

      const linked: string[] = [];
      const duplicates: string[] = [];
      for (const driverId of driverIds) {
        const d = driverMap.get(driverId);
        if (!d) continue;
        const result = await pgPool.query(
          `INSERT INTO recruiting_campaign_activated_drivers
             (campaign_id, driver_id, activation_date,
              driver_classification_at_activation, driver_type_at_activation,
              employment_type_at_activation, linked_by_user_id)
           VALUES ($1,$2,$3,$4,$5,$6,$7)
           ON CONFLICT (campaign_id, driver_id) DO NOTHING
           RETURNING id`,
          [req.params.id, driverId, d.hire_date || null,
           d.driver_classification || null, d.driver_type || null,
           d.employment_type || null, userId]
        );
        if (result.rowCount && result.rowCount > 0) linked.push(driverId);
        else duplicates.push(driverId);
      }

      if (linked.length > 0) {
        const { recruitingAuditEvents } = await import("@shared/schema");
        const actorName = `${user?.firstName || ""} ${user?.lastName || ""}`.trim() || user?.email || userId;
        await db.insert(recruitingAuditEvents).values({
          actionType: "CAMPAIGN_DRIVERS_LINKED",
          entityType: "request",
          entityId:   req.params.id,
          userId,
          userEmail:  user?.email || null,
          actorRole:  role,
          source:     reason === "closure" ? "closure" : "ui",
          newValue:   JSON.stringify({ driverIds: linked, count: linked.length }),
          notes:      `${linked.length} driver${linked.length === 1 ? "" : "s"} linked to campaign${reason === "closure" ? " at closure" : ""} by ${actorName}.`,
        });
      }

      res.json({ linked, duplicates, skipped: driverIds.length - linked.length - duplicates.length });
    } catch (error) {
      console.error("[Recruiting] Error linking activated drivers:", error);
      res.status(500).json({ message: "Failed to link activated drivers" });
    }
  });

  // DELETE /api/recruiting/requests/:id/activated-drivers/:driverId
  app.delete("/api/recruiting/requests/:id/activated-drivers/:driverId", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db } = await import("./db");
      const { pool: pgPool } = await import("./db");
      const role = user?.role || "";
      const EDIT_ROLES = new Set(["super_user", "root_super_admin", "admin", "corporate_admin", "manager", "recruiter", "recruiting_admin"]);
      if (!EDIT_ROLES.has(role)) return res.status(403).json({ message: "Insufficient permissions" });

      const { reason } = req.body as { reason?: string };
      if (!reason?.trim()) {
        return res.status(400).json({ message: "A reason is required when removing a linked driver." });
      }

      const del = await pgPool.query(
        `DELETE FROM recruiting_campaign_activated_drivers
         WHERE campaign_id = $1 AND driver_id = $2 RETURNING id`,
        [req.params.id, req.params.driverId]
      );
      if (!del.rowCount) return res.status(404).json({ message: "Driver not linked to this campaign." });

      const { recruitingAuditEvents } = await import("@shared/schema");
      const actorName = `${user?.firstName || ""} ${user?.lastName || ""}`.trim() || user?.email || userId;
      await db.insert(recruitingAuditEvents).values({
        actionType: "CAMPAIGN_DRIVER_REMOVED",
        entityType: "request",
        entityId:   req.params.id,
        userId,
        userEmail:  user?.email || null,
        actorRole:  role,
        source:     "ui",
        previousValue: JSON.stringify({ driverId: req.params.driverId, reason }),
        notes: `Driver removed from campaign by ${actorName}. Reason: ${reason}`,
      });

      res.json({ ok: true });
    } catch (error) {
      console.error("[Recruiting] Error removing activated driver:", error);
      res.status(500).json({ message: "Failed to remove activated driver" });
    }
  });

  // GET /api/recruiting/requests/:id/suggested-drivers
  // Returns up to 20 drivers scored by match against campaign criteria.
  app.get("/api/recruiting/requests/:id/suggested-drivers", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { db } = await import("./db");
      const { pool: pgPool } = await import("./db");
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingDiscoveryAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting discovery access required" });
      }

      const campaign = await db.query.recruitingRequests.findFirst({
        where: (r, { eq }) => eq(r.id, req.params.id),
      });
      if (!campaign) return res.status(404).json({ message: "Campaign not found" });
      // DH-002336: Same rationale as /api/drivers/search — Driver/Campaign market data
      // is unreliable, so scoping this advisory selector by campaign.market denies
      // legitimate discovery for the majority of campaigns that have no market set.
      // Require the same base Recruiting discovery permission used by /api/drivers/search.
      if (!hasRecruitingDiscoveryAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: insufficient Recruiting permissions" });
      }

      const classif    = (campaign as any).driverClassification || null;
      const progType   = (campaign as any).programType          || null;
      const driverType = (campaign as any).driverType           || null;
      const empType    = (campaign as any).employmentType       || null;
      const market     = (campaign as any).market               || null;
      const startDate  = (campaign as any).campaignStartDate    || null;
      const endDate    = new Date().toISOString().slice(0, 10);

      // Score each driver by how many campaign criteria they match; only include score >= 1.
      // Note: the campaign id (req.params.id) is only used above to look up the campaign
      // record — it is not a column filter here, so it must not be passed as a bind
      // parameter (an unbound, unreferenced $N leaves Postgres unable to infer its type).
      const rows = await pgPool.query(
        `SELECT
           d.id,
           COALESCE(
             NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '),
             'Driver ' || d.id
           )                       AS "displayName",
           d.employee_id           AS "employeeId",
           d.status,
           d.driver_classification AS "driverClassification",
           d.driver_type           AS "driverType",
           d.employment_type       AS "employmentType",
           d.hire_date             AS "hireDate",
           d.market,
           (
             CASE WHEN $1::varchar IS NOT NULL AND d.driver_classification = $1 THEN 3 ELSE 0 END +
             CASE WHEN ($2::varchar IS NOT NULL AND d.driver_type = $2)
                    OR ($3::varchar IS NOT NULL AND d.driver_type = $3) THEN 2 ELSE 0 END +
             CASE WHEN $4::varchar IS NOT NULL AND d.employment_type = $4 THEN 2 ELSE 0 END +
             CASE WHEN $5::varchar IS NOT NULL AND d.market ILIKE $5 THEN 1 ELSE 0 END +
             CASE WHEN $6::date IS NOT NULL AND d.hire_date IS NOT NULL
                   AND d.hire_date BETWEEN $6::date AND $7::date THEN 1 ELSE 0 END
           ) AS score
         FROM drivers d
         LEFT JOIN users u ON u.id = d.user_id
         WHERE d.is_deleted = false
           AND d.status IN ('active', 'inactive')
           AND (
             ($1::varchar IS NOT NULL AND d.driver_classification = $1) OR
             ($2::varchar IS NOT NULL AND d.driver_type            = $2) OR
             ($3::varchar IS NOT NULL AND d.driver_type            = $3) OR
             ($4::varchar IS NOT NULL AND d.employment_type        = $4) OR
             ($5::varchar IS NOT NULL AND d.market ILIKE $5) OR
             ($6::date IS NOT NULL AND d.hire_date IS NOT NULL AND d.hire_date BETWEEN $6::date AND $7::date)
           )
         ORDER BY score DESC, d.status, u.last_name, u.first_name
         LIMIT 20`,
        [classif, progType, driverType, empType,
         market ? `%${market}%` : null, startDate, endDate]
      );

      res.json(rows.rows.filter((r: any) => Number(r.score) > 0));
    } catch (error) {
      console.error("[Recruiting] Error fetching suggested drivers:", error);
      res.status(500).json({ message: "Failed to fetch suggested drivers" });
    }
  });

  // GET /api/recruiting/requests/:id/activity - Activity log for a request
  app.get("/api/recruiting/requests/:id/activity", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { db } = await import("./db");
      const { recruitingRequestActivity } = await import("@shared/schema");
      const { eq, desc } = await import("drizzle-orm");
      const events = await db.select()
        .from(recruitingRequestActivity)
        .where(eq(recruitingRequestActivity.requestId, req.params.id))
        .orderBy(desc(recruitingRequestActivity.createdAt));
      res.json(events);
    } catch (error: any) {
      console.error("[Recruiting Requests/:id/activity] GET error:", error);
      res.status(500).json({ message: "Failed to fetch activity log" });
    }
  });

  // PATCH /api/recruiting/requests/:id/status - Update request status + approval
  app.patch("/api/recruiting/requests/:id/status", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const isRootSuperAdmin = (user as any)?.isRootSuperAdmin ?? false;
      // Expanded roles: recruiting admins can manage approvals
      const APPROVAL_ROLES = ["super_user","super_admin","root_super_admin","corporate_admin","admin","manager","recruiting_admin","hiring_manager"];
      if (!user || (!APPROVAL_ROLES.includes(user.role || "") && !isRootSuperAdmin)) {
        return res.status(403).json({ message: "Insufficient permissions to update request status." });
      }
      const { id } = req.params;
      const { requestStatus, reviewNotes } = req.body;
      if (!requestStatus) return res.status(400).json({ message: "requestStatus is required" });

      // Validate status is a known value
      const VALID_STATUSES = ["draft","submitted","needs_review","approved","rejected","on_hold","recruiting_active","completed","under_review","in_progress","ads_live"];
      if (!VALID_STATUSES.includes(requestStatus)) {
        return res.status(400).json({ message: `Invalid requestStatus. Must be one of: ${VALID_STATUSES.join(", ")}` });
      }

      // Rejection requires a reason
      if (requestStatus === "rejected" && !reviewNotes?.trim()) {
        return res.status(400).json({ message: "A reason is required when rejecting a request." });
      }

      const { db } = await import("./db");
      const { recruitingRequests, recruitingCampaigns } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");
      const reviewerName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;
      const now = new Date();

      const existing = await db.query.recruitingRequests.findFirst({
        where: (r, { eq }) => eq(r.id, id),
      });
      if (!existing) return res.status(404).json({ message: "Request not found" });

      // Terminal approval decisions: approved / rejected
      const isApprovalDecision = requestStatus === "approved" || requestStatus === "rejected";
      const preservesExistingApproval =
        requestStatus === "approved"
        && existing.approvalStatus === "approved"
        && existing.approvedAt != null;
      const approvalTimestamp = preservesExistingApproval ? existing.approvedAt! : now;

      const [updated] = await db.update(recruitingRequests)
        .set({
          requestStatus,
          reviewedBy:   reviewerName,
          reviewedAt:   now,
          reviewNotes:  reviewNotes?.trim() || null,
          // Only overwrite approvalStatus on a final decision — non-terminal
          // transitions (e.g. under_review) leave approvalStatus as "pending"
          ...(isApprovalDecision ? {
            approvalStatus: requestStatus,   // "approved" | "rejected"
            approvedBy:     preservesExistingApproval ? existing.approvedBy : reviewerName,
            approvedAt:     approvalTimestamp,
            approvalNotes:  preservesExistingApproval ? existing.approvalNotes : (reviewNotes?.trim() || null),
          } : {}),
          ...(requestStatus === "approved" ? {
            campaignStartDate: approvalTimestampToCampaignDate(approvalTimestamp),
          } : {}),
          updatedAt: now,
        })
        .where(eq(recruitingRequests.id, id))
        .returning();

      if (!updated) return res.status(404).json({ message: "Request not found" });

      if (requestStatus === "approved") {
        await db.update(recruitingCampaigns)
          .set({
            startDate: (updated as any).campaignStartDate,
            updatedAt: now,
            updatedBy: userId,
          })
          .where(eq(recruitingCampaigns.requestId, id));
      }

      // Log status change to activity table
      try {
        const { recruitingRequestActivity } = await import("@shared/schema");
        await db.insert(recruitingRequestActivity).values({
          orgId: (updated as any).orgId,
          requestId: id,
          userId,
          userName: reviewerName,
          action: "status_change",
          fromStatus: existing.requestStatus ?? null,
          toStatus: requestStatus,
          notes: reviewNotes?.trim() || null,
        });
      } catch (_e) { /* non-fatal */ }

      // Notify submitter on final decision (approved or rejected)
      if (isApprovalDecision) {
        try {
          const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
          if (isMicrosoftGraphConfigured() || isRecruitingExternalDeliverySuppressed()) {
            const submitter = await storage.getUser((updated as any).submittedBy);
            const submitterEmail = (submitter as any)?.email;
            if (submitterEmail) {
              const isApproved = requestStatus === "approved";
              const campaignLabel = ((updated as any).campaignType || "").charAt(0).toUpperCase() +
                ((updated as any).campaignType || "").slice(1);
              const dealerLabel = (updated as any).dealershipName || (updated as any).location || "N/A";
              const locationLabel = (updated as any).location || "—";
              const accentColor = isApproved ? "#22c55e" : "#ef4444";
              const statusLabel = isApproved ? "Approved" : "Rejected";
              const bodyHtml = `
                <div style="font-family:Arial,sans-serif;max-width:600px">
                  <div style="background:${accentColor};padding:16px 20px;border-radius:4px 4px 0 0">
                    <h2 style="color:#fff;margin:0;font-size:18px">Recruiting Request ${statusLabel}</h2>
                  </div>
                  <div style="border:1px solid #e5e7eb;border-top:none;padding:16px 20px 8px;border-radius:0 0 4px 4px">
                    <p>Your recruiting request has been <strong style="color:${accentColor}">${statusLabel.toLowerCase()}</strong> by <strong>${reviewerName}</strong>.</p>
                    <table style="width:100%;border-collapse:collapse;margin:16px 0">
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5;width:40%">Campaign Type</td><td style="padding:6px 12px;text-transform:capitalize">${campaignLabel}</td></tr>
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Dealership / Account</td><td style="padding:6px 12px">${dealerLabel}</td></tr>
                      ${(() => { const r_ = updated as any; const citySt = r_.city && r_.state ? `${r_.city}, ${r_.state}` : r_.city || r_.state || ""; const line2 = [citySt, r_.zipCode].filter(Boolean).join(" "); const parts = [r_.address, line2].filter(Boolean); return parts.length ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Account Address</td><td style="padding:6px 12px">${parts.join(", ")}</td></tr>` : ""; })()}
                      ${(updated as any).network ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Network</td><td style="padding:6px 12px">${(updated as any).network}</td></tr>` : ""}
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Location</td><td style="padding:6px 12px">${locationLabel}</td></tr>
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Decision</td><td style="padding:6px 12px;color:${accentColor};font-weight:bold">${statusLabel}</td></tr>
                      ${reviewNotes?.trim() ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">${isApproved ? "Notes" : "Reason for Rejection"}</td><td style="padding:6px 12px">${reviewNotes.trim()}</td></tr>` : ""}
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Decided By</td><td style="padding:6px 12px">${reviewerName}</td></tr>
                      <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Date</td><td style="padding:6px 12px">${now.toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}</td></tr>
                    </table>
                    ${isApproved
                      ? `<p style="color:#16a34a">Recruiting execution can now begin. The assigned recruiter will be in touch to coordinate next steps.</p>`
                      : `<p style="color:#dc2626">If you have questions about this decision, please follow up with your manager or the COO directly.</p>`}
                    <p style="color:#6b7280;font-size:12px;border-top:1px solid #f3f4f6;padding-top:12px;margin:0">
                      Log in to <strong>DriverHub 360 → Recruiting → Requests</strong> to view the full request details.
                    </p>
                  </div>
                </div>`;
              await sendEmail({
                to: [submitterEmail],
                subject: `Your Recruiting Request Has Been ${statusLabel} — ${campaignLabel} | ${dealerLabel}`,
                bodyHtml,
                recruitingAudit: {
                  actionType: "REQUEST_DECISION_ALERT_SUPPRESSED",
                  entityType: "request",
                  entityId: id,
                  userId,
                  userEmail: user?.email || null,
                  actorRole: user?.role || null,
                  trigger: "request_decision_alert",
                },
              });
            }
          }
        } catch (emailErr) {
          console.error("[Recruiting Requests] Submitter notification failed:", emailErr);
          // Non-fatal
        }

        // Notify ops team (support@, recruiting@, dispatch@) on request approval
        if (requestStatus === "approved") {
          try {
            const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
            if (isMicrosoftGraphConfigured() || isRecruitingExternalDeliverySuppressed()) {
              const OPS_APPROVAL_RECIPIENTS = [
                "support@driverondemand.co",
                "recruiting@driverondemand.co",
                "dispatch@driverondemand.co",
              ];
              const req2 = updated as any;
              const campaignLabel2 = (req2.campaignType || "").charAt(0).toUpperCase() + (req2.campaignType || "").slice(1);
              const urgencyLabels2: Record<number, string> = {
                1: "1 – Maintenance / Back Up Role",
                2: "2 – Below Average",
                3: "3 – Normal",
                4: "4 – High",
                5: "5 – Critical",
              };
              const urgencyLabel2 = urgencyLabels2[Number(req2.urgency)] || `${req2.urgency}`;
              const driverTypes2: string[] = Array.isArray(req2.driverTypes) ? req2.driverTypes : (req2.driverType ? [req2.driverType] : []);
              const dtLabel2 = driverTypes2.join(", ") || req2.driverType || "—";
              const classificationLabels2: Record<string, string> = {
                w2_employee: "W-2 Employee",
                "1099_contractor": "1099 Contractor",
                temp_to_hire: "Temp-to-Hire",
                seasonal: "Seasonal",
              };
              const classificationLabel2 = classificationLabels2[req2.driverClassification || ""] || req2.driverClassification || "—";
              const bonusLabels2: Record<string, string> = {
                no_bonus: "No Bonus",
                standard_500: "$500 Standard",
                standard_1000: "$1,000 Standard",
                standard_1500: "$1,500 Standard",
                standard_2000: "$2,000 Standard",
                other: "Other (see notes)",
              };
              const bonusLabel2 = bonusLabels2[req2.signOnBonusOption || ""] || req2.signOnBonusOption || "—";
              const originLabels2: Record<string, string> = {
                internal: "Internal Request",
                dealer_request: "Dealer / Client Request",
                growth_initiative: "Growth Initiative",
                backfill: "Backfill",
                other: "Other",
              };
              const originLabel2 = originLabels2[req2.requestOrigin || ""] || req2.requestOrigin || "—";
              const row2 = (label: string, value: string) =>
                `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5;width:40%;white-space:nowrap">${label}</td><td style="padding:6px 12px">${value}</td></tr>`;
              const approvalBodyHtml = `
                <div style="font-family:Arial,sans-serif;max-width:620px">
                  <div style="background:#22c55e;padding:16px 20px;border-radius:4px 4px 0 0">
                    <h2 style="color:#fff;margin:0;font-size:18px">Recruiting Request Approved — Campaign Active</h2>
                    <p style="color:#dcfce7;margin:4px 0 0;font-size:13px">Approved by <strong>${reviewerName}</strong> · ${now.toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})}</p>
                  </div>
                  <div style="border:1px solid #e5e7eb;border-top:none;padding:16px 20px 8px;border-radius:0 0 4px 4px">
                    <table style="width:100%;border-collapse:collapse;margin:0 0 16px">
                      <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Request Details</td></tr>
                      ${row2("Request Origin", originLabel2)}
                      ${row2("Submitted By", req2.submittedByName || "—")}
                      ${row2("Dealership / Account", req2.dealershipName || "—")}
                      ${(() => { const citySt = req2.city && req2.state ? `${req2.city}, ${req2.state}` : req2.city || req2.state || ""; const line2 = [citySt, req2.zipCode].filter(Boolean).join(" "); const parts = [req2.address, line2].filter(Boolean); return parts.length ? row2("Account Address", parts.join(", ")) : ""; })()}
                      ${req2.network ? row2("Network", req2.network) : ""}
                      ${row2("Location", req2.location || "—")}
                      ${row2("Campaign Type", campaignLabel2)}
                      ${row2("Urgency", urgencyLabel2)}
                      <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Driver Requirements</td></tr>
                      ${row2("Driver Classification", classificationLabel2)}
                      ${row2("Driver Type(s)", dtLabel2)}
                      ${row2("Target # of Drivers", req2.targetDriverCount ? String(req2.targetDriverCount) : "—")}
                      ${row2("Driver Pay Rate", req2.payRate ? `$${Number(req2.payRate).toFixed(2)}` : "—")}
                      ${row2("Sign-On Bonus", bonusLabel2)}
                      ${req2.signOnBonusOption === "other" && req2.signOnBonusNotes ? row2("Bonus Details", req2.signOnBonusNotes) : ""}
                      ${row2("Driver Schedule", req2.driverSchedule || "—")}
                      ${row2("Target Fill Date", req2.targetDate ? new Date(req2.targetDate).toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"}) : "—")}
                      <tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Contacts</td></tr>
                      ${row2("Recruiter", req2.recruiter || "—")}
                      ${row2("Cert Liaison", req2.certLiaison || "—")}
                      ${reviewNotes?.trim() ? `<tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Approval Notes</td></tr>${row2("Notes", reviewNotes.trim())}` : ""}
                      ${req2.additionalComments ? `<tr><td colspan="2" style="padding:6px 12px;font-weight:bold;font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:#9ca3af;background:#fafafa">Additional Comments</td></tr>${row2("Comments", req2.additionalComments)}` : ""}
                    </table>
                    <p style="color:#6b7280;font-size:12px;border-top:1px solid #f3f4f6;padding-top:12px;margin:0">
                      Log in to <strong>DriverHub 360 → Recruiting → Requests</strong> to view the campaign and track progress.
                    </p>
                  </div>
                </div>`;
              let approvalAlertStatus = "success";
              let approvalAlertError: string | null = null;
              try {
                const deliveryResult = await sendEmail({
                  to: OPS_APPROVAL_RECIPIENTS,
                  subject: `[Recruiting] Request Approved — ${campaignLabel2} | ${req2.dealershipName || req2.location || "N/A"} | Urgency ${req2.urgency}/5`,
                  bodyHtml: approvalBodyHtml,
                  recruitingAudit: {
                    actionType: "APPROVAL_ALERT_SUPPRESSED",
                    entityType: "request",
                    entityId: id,
                    userId,
                    userEmail: user?.email || null,
                    actorRole: user?.role || null,
                    trigger: "request_approval_ops_alert",
                  },
                });
                if (!deliveryResult.ok) {
                  approvalAlertStatus = deliveryResult.skipped && deliveryResult.error === "RECRUITING_EXTERNAL_DELIVERY_SUPPRESSED"
                    ? "suppressed"
                    : "failed";
                  approvalAlertError = deliveryResult.error || null;
                }
              } catch (sendErr: any) {
                approvalAlertStatus = "failed";
                approvalAlertError = sendErr?.message || String(sendErr);
              }
              console.log(`[Recruiting Requests] Approval ops alert — recipients: ${OPS_APPROVAL_RECIPIENTS.join(", ")} | status: ${approvalAlertStatus}${approvalAlertError ? ` | error: ${approvalAlertError}` : ""}`);
              try {
                const { recruitingAuditEvents: raeApproval } = await import("@shared/schema");
                await db.insert(raeApproval).values({
                  actionType: "APPROVAL_ALERT_SENT",
                  entityType: "request",
                  entityId: id,
                  userId,
                  userEmail: user?.email || null,
                  actorRole: user?.role || null,
                  source: "system",
                  newValue: JSON.stringify({ recipients: OPS_APPROVAL_RECIPIENTS, status: approvalAlertStatus, error: approvalAlertError }),
                });
              } catch { /* audit non-fatal */ }
            }
          } catch (opsEmailErr) {
            console.error("[Recruiting Requests] Approval ops alert failed:", opsEmailErr);
            // Non-fatal
          }
        }
      }

      // ── Auto-create requisition on approval ───────────────────────────────
      // The Recruiting Request is the operational Campaign record and owns the
      // detail URL. The linked requisition supplements the lifecycle; its ID is
      // not a recruiting_campaigns primary key and must never be used for the
      // Campaign Detail route.
      let autoCampaign: any = null;
      if (requestStatus === "approved" && !(updated as any).campaignRequisitionId) {
        try {
          const { recruitingRequisitions, users } = await import("@shared/schema");

          // Build requisition title + description from request fields
          const req2 = updated as any;
          const driverTypes: string[] = Array.isArray(req2.driverTypes) ? req2.driverTypes : [];
          const hasCdl      = driverTypes.includes("CDL");
          const workType    = driverTypes.includes("On-Demand") ? "ON_DEMAND" : "SHIFT";
          const ctLabel     = (req2.campaignType || "").charAt(0).toUpperCase() + (req2.campaignType || "").slice(1);
          const mktLabel    = req2.market || "N/A";
          const dtLabel     = driverTypes.join(" / ") || req2.driverType || "Driver";
          const reqTitle    = `${ctLabel} — ${dtLabel} | ${mktLabel}${req2.dealershipName ? ` — ${req2.dealershipName}` : ""}`;

          const descParts: string[] = [];
          if (req2.dealershipName)         descParts.push(`Dealership: ${req2.dealershipName}`);
          if (req2.address)                descParts.push(`Address: ${req2.address}`);
          if (req2.certLiaison)            descParts.push(`Cert Liaison: ${req2.certLiaison}`);
          if (req2.driverSchedule)         descParts.push(`Schedule: ${req2.driverSchedule}`);
          if (req2.additionalComments)     descParts.push(`Notes: ${req2.additionalComments}`);

          // Best-effort recruiter user lookup by display name
          let recruiterId: string | null = null;
          if (req2.recruiter?.trim()) {
            const nameParts = req2.recruiter.trim().split(/\s+/);
            const firstName = nameParts[0] || "";
            const lastName  = nameParts.slice(1).join(" ") || "";
            const allUsers = await db.select().from(users).limit(200);
            const match = allUsers.find((u: any) => {
              const full = `${u.firstName || ""} ${u.lastName || ""}`.trim().toLowerCase();
              return full === req2.recruiter.trim().toLowerCase()
                || u.email?.toLowerCase() === req2.recruiter.trim().toLowerCase();
            });
            if (match) recruiterId = match.id;
          }

          const [created] = await db.insert(recruitingRequisitions).values({
            title:            reqTitle,
            description:      descParts.join("\n") || null,
            workerType:       "W2_DRIVER" as any,
            workType:         workType as any,
            market:           req2.market || "Unknown",
            targetHires:      req2.targetDriverCount || 1,
            compensationMin:  req2.payRate || null,
            compensationMax:  req2.payRate || null,
            compensationType: req2.payRate ? "hourly" : null,
            recruiterId:      recruiterId,
            status:           "open_active" as any,
            targetFillDate:   req2.targetDate || null,
            cdlRequired:      hasCdl,
            createdBy:        userId,
            updatedBy:        userId,
            sourceRequestId:  id,
            location:         req2.location || null,
          } as any).returning();

          // Back-link request → requisition
          await db.update(recruitingRequests)
            .set({ campaignRequisitionId: created.id, updatedAt: new Date() })
            .where(eq(recruitingRequests.id, id));

          autoCampaign = created;

          // DH-002127: Notify recruiter + cert liaison with deep-link to campaign (best-effort)
          try {
            const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
            if (isMicrosoftGraphConfigured() || isRecruitingExternalDeliverySuppressed()) {
              const appBaseUrl = process.env.REPLIT_DEPLOYMENT_URL ||
                (process.env.REPLIT_DEV_DOMAIN ? `https://${process.env.REPLIT_DEV_DOMAIN}` : "");
              const campaignUrl = appBaseUrl ? `${appBaseUrl}/recruiting/campaigns/${id}` : null;
              const aName = reviewerName;

              // Build recipient set: assigned recruiter + cert liaison (looked up by name)
              const recipientIds = new Set<string>();
              if (recruiterId) recipientIds.add(recruiterId);
              if (req2.certLiaison?.trim()) {
                const { users: usersTable } = await import("@shared/schema");
                const allUsers = await db.select().from(usersTable).limit(300);
                const clMatch = allUsers.find((u: any) => {
                  const full = `${u.firstName || ""} ${u.lastName || ""}`.trim().toLowerCase();
                  return full === req2.certLiaison.trim().toLowerCase()
                    || u.email?.toLowerCase() === req2.certLiaison.trim().toLowerCase();
                });
                if (clMatch) recipientIds.add((clMatch as any).id);
              }

              for (const recipId of recipientIds) {
                try {
                  const recipUser = await storage.getUser(recipId);
                  const recipEmail = (recipUser as any)?.email;
                  if (!recipEmail) continue;
                  const rName = `${(recipUser as any).firstName || ""} ${(recipUser as any).lastName || ""}`.trim() || recipEmail;
                  const isAssignedRecruiter = recipId === recruiterId;
                  const bodyHtml = `
                    <div style="font-family:Arial,sans-serif;max-width:600px">
                      <div style="background:#FF6B35;padding:16px 20px;border-radius:4px 4px 0 0">
                        <h2 style="color:#fff;margin:0;font-size:18px">New Recruiting Campaign — Action Required</h2>
                      </div>
                      <div style="border:1px solid #e5e7eb;border-top:none;padding:16px 20px 8px;border-radius:0 0 4px 4px">
                        <p>Hi <strong>${rName}</strong>,</p>
                        <p>${isAssignedRecruiter
                          ? `You have been assigned a new recruiting campaign by <strong>${aName}</strong>. The campaign is now Open Active and requires job posting and source information.`
                          : `A recruiting campaign you are involved with has been approved by <strong>${aName}</strong>. The campaign is now Open Active and requires job posting and source information.`
                        }</p>
                        <table style="width:100%;border-collapse:collapse;margin:16px 0">
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5;width:40%">Campaign</td><td style="padding:6px 12px">${reqTitle}</td></tr>
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Market</td><td style="padding:6px 12px">${mktLabel}</td></tr>
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Account</td><td style="padding:6px 12px">${req2.dealershipName || "—"}</td></tr>
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Driver Type</td><td style="padding:6px 12px">${dtLabel}</td></tr>
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Target Drivers</td><td style="padding:6px 12px">${req2.targetDriverCount || "N/A"}</td></tr>
                          ${req2.payRate ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Pay Rate</td><td style="padding:6px 12px">$${Number(req2.payRate).toFixed(2)}</td></tr>` : ""}
                          ${req2.targetDate ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Target Fill Date</td><td style="padding:6px 12px">${new Date(req2.targetDate).toLocaleDateString("en-US",{month:"long",day:"numeric",year:"numeric"})}</td></tr>` : ""}
                          <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Status</td><td style="padding:6px 12px;color:#FF6B35;font-weight:bold">Open Active</td></tr>
                        </table>
                        ${campaignUrl
                          ? `<p style="text-align:center;margin:20px 0"><a href="${campaignUrl}" style="background:#FF6B35;color:#fff;padding:10px 24px;border-radius:4px;text-decoration:none;font-weight:bold;font-size:14px">Open Campaign →</a></p>`
                          : `<p>Log in to <strong>DriverHub 360 → Recruiting → Active Campaigns</strong> to open the campaign workspace and add job postings.</p>`
                        }
                      </div>
                    </div>`;
                  await sendEmail({
                    to: [recipEmail],
                    subject: `[Action Required] Campaign Approved — ${reqTitle}`,
                    bodyHtml,
                    recruitingAudit: {
                      actionType: "CAMPAIGN_ASSIGNMENT_ALERT_SUPPRESSED",
                      entityType: "request",
                      entityId: id,
                      userId,
                      userEmail: user?.email || null,
                      actorRole: user?.role || null,
                      trigger: "auto_campaign_assignment_alert",
                    },
                  });
                } catch (recipErr) {
                  console.error("[Auto-Campaign] Notification failed for recipient:", recipId, recipErr);
                }
              }
            }
          } catch (emailErr) {
            console.error("[Auto-Campaign] Recruiter email failed:", emailErr);
          }
        } catch (campaignErr) {
          console.error("[Auto-Campaign] Creation failed (non-fatal):", campaignErr);
          // Non-fatal — approval already saved
        }
      }

      // ── Auto-generate campaign market intelligence on approval ────────────
      let _marketIntel: any = null;
      if (requestStatus === "approved" && autoCampaign) {
        try {
          const { generateCampaignIntelligence } = await import("./services/campaignIntelligenceService");
          _marketIntel = await generateCampaignIntelligence(id, (autoCampaign as any).id, updated as any);
          console.log(`[CampaignIntel] Auto-generated for requisition ${(autoCampaign as any).id}`);
        } catch (intelErr) {
          console.error("[CampaignIntel] Auto-generation failed (non-fatal):", intelErr);
        }
      }

      // ── Auto-generate recruiting plan on approval ─────────────────────────
      if (requestStatus === "approved" && autoCampaign) {
        try {
          const { generateRecruitingPlan } = await import("./services/recruitingPlanService");
          await generateRecruitingPlan(id, (autoCampaign as any).id, updated as any, _marketIntel);
          console.log(`[RecruitingPlan] Auto-generated for requisition ${(autoCampaign as any).id}`);
        } catch (planErr) {
          console.error("[RecruitingPlan] Auto-generation failed (non-fatal):", planErr);
        }
      }

      const requisitionId = autoCampaign?.id ?? (updated as any).campaignRequisitionId ?? null;
      const operationalCampaign = requisitionId
        ? {
            requestId: id,
            requisitionId,
            detailPath: `/recruiting/campaigns/${id}`,
          }
        : null;

      // Preserve the existing _autoCampaign object for callers that display the
      // requisition title, while publishing an explicit, request-keyed detail
      // target for navigation. This keeps the Request → Requisition relation
      // intact without treating the requisition as a recruiting_campaigns row.
      res.json({
        ...updated,
        campaignRequisitionId: requisitionId,
        operationalCampaign,
        _autoCampaign: autoCampaign
          ? {
              ...autoCampaign,
              requestId: id,
              requisitionId: autoCampaign.id,
              detailPath: `/recruiting/campaigns/${id}`,
            }
          : null,
      });
    } catch (error: any) {
      console.error("[Recruiting Requests] PATCH status error:", error);
      res.status(500).json({ message: error.message || "Failed to update request status" });
    }
  });

  // PATCH /api/recruiting/requests/:id/progress — Advance request through post-approval lifecycle
  // (in_progress → ads_live → completed). Broader role access than /status.
  app.patch("/api/recruiting/requests/:id/progress", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const PROGRESS_ROLES = ["super_user", "super_admin", "root_super_admin", "admin", "corporate_admin", "manager", "recruiter", "recruiting_admin"];
      const isRootSuperAdmin = (user as any)?.isRootSuperAdmin ?? false;
      if (!user || (!PROGRESS_ROLES.includes(user.role || "") && !isRootSuperAdmin)) {
        return res.status(403).json({ message: "Insufficient permissions to advance request progress." });
      }
      const { id } = req.params;
      const { requestStatus, notes } = req.body;
      const VALID_PROGRESS = ["in_progress", "ads_live", "completed"];
      if (!requestStatus || !VALID_PROGRESS.includes(requestStatus)) {
        return res.status(400).json({ message: `requestStatus must be one of: ${VALID_PROGRESS.join(", ")}` });
      }
      const { db } = await import("./db");
      const { recruitingRequests, recruitingAuditEvents } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const [existing] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, id)).limit(1);
      if (!existing) return res.status(404).json({ message: "Request not found" });

      const actorName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;
      const now = new Date();
      const [updated] = await db.update(recruitingRequests)
        .set({ requestStatus, reviewNotes: notes?.trim() || null, updatedAt: now })
        .where(eq(recruitingRequests.id, id))
        .returning();

      // Audit
      try {
        await db.insert(recruitingAuditEvents).values({
          actionType: "PROGRESS_ADVANCED",
          entityType: "request",
          entityId: id,
          userId,
          userEmail: user.email || null,
          actorRole: user.role || null,
          source: "ui",
          previousValue: existing.requestStatus,
          newValue: requestStatus,
          changedFields: ["requestStatus"],
          reason: notes?.trim() || null,
        });
      } catch { /* audit non-fatal */ }

      res.json(updated);
    } catch (error: any) {
      console.error("[Recruiting Requests] PATCH progress error:", error);
      res.status(500).json({ message: error.message || "Failed to advance request progress" });
    }
  });

  // ── Ticket 43: Campaign Market Intelligence ──────────────────────────────

  // GET /api/recruiting/requisitions/:id/market-intelligence
  // Returns the latest intelligence record for a requisition.
  app.get("/api/recruiting/requisitions/:id/market-intelligence", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { db } = await import("./db");
      const { campaignMarketIntelligence } = await import("@shared/schema");
      const { eq, desc } = await import("drizzle-orm");

      const [record] = await db
        .select()
        .from(campaignMarketIntelligence)
        .where(eq(campaignMarketIntelligence.requisitionId, id))
        .orderBy(desc(campaignMarketIntelligence.createdAt))
        .limit(1);

      if (!record) return res.json(null);
      res.json(record);
    } catch (err: any) {
      console.error("[CampaignIntel] GET error:", err);
      res.status(500).json({ message: "Failed to load market intelligence", detail: err?.message });
    }
  });

  // POST /api/recruiting/requisitions/:id/market-intelligence/generate
  // Manually regenerate intelligence (e.g. if auto-generation failed on approval).
  app.post("/api/recruiting/requisitions/:id/market-intelligence/generate", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { db } = await import("./db");
      const { recruitingRequisitions } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      // Load requisition to get the sourceRequestId
      const [req2] = await db
        .select()
        .from(recruitingRequisitions)
        .where(eq(recruitingRequisitions.id, id))
        .limit(1);

      if (!req2) return res.status(404).json({ message: "Requisition not found" });

      // Load the originating recruiting request for context
      let requestData: any = { ...req2 };
      if (req2.sourceRequestId) {
        try {
          const { recruitingRequests } = await import("@shared/schema");
          const [rr] = await db
            .select()
            .from(recruitingRequests)
            .where(eq(recruitingRequests.id, req2.sourceRequestId))
            .limit(1);
          if (rr) requestData = { ...rr, ...req2 };
        } catch { /* non-fatal */ }
      }

      const { generateCampaignIntelligence } = await import("./services/campaignIntelligenceService");
      const record = await generateCampaignIntelligence(
        req2.sourceRequestId || "",
        id,
        requestData,
      );

      res.json(record);
    } catch (err: any) {
      console.error("[CampaignIntel] generate error:", err);
      res.status(500).json({ message: "Failed to generate market intelligence", detail: err?.message });
    }
  });

  // PATCH /api/recruiting/requisitions/:id/market-intelligence
  // Recruiter override — persists custom values and marks record as overridden.
  app.patch("/api/recruiting/requisitions/:id/market-intelligence", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const userId = (req.user as any)?.id || (req as any).session?.userId;
      const user = userId ? await storage.getUser(userId) : null;
      const actorName = user ? `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId : "Unknown";

      const { payRangeMin, payRangeMax, expectedTimeToFill, overrideNotes } = req.body as {
        payRangeMin?: number | null;
        payRangeMax?: number | null;
        expectedTimeToFill?: number | null;
        overrideNotes?: string | null;
      };

      const { db } = await import("./db");
      const { campaignMarketIntelligence } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const existing = await db
        .select()
        .from(campaignMarketIntelligence)
        .where(eq(campaignMarketIntelligence.requisitionId, id))
        .limit(1);

      const now = new Date();
      const updates: any = {
        isOverridden:  true,
        overrideNotes: overrideNotes ?? null,
        overriddenAt:  now,
        overriddenBy:  actorName,
        generatedBy:   "manual",
        updatedAt:     now,
      };

      if (payRangeMin != null)       updates.payRangeMin        = String(payRangeMin);
      if (payRangeMax != null)       updates.payRangeMax        = String(payRangeMax);
      if (expectedTimeToFill != null) updates.expectedTimeToFill = expectedTimeToFill;

      if (existing.length > 0) {
        const [updated] = await db
          .update(campaignMarketIntelligence)
          .set(updates)
          .where(eq(campaignMarketIntelligence.requisitionId, id))
          .returning();
        return res.json(updated);
      }

      // If no record exists yet, create one (override from scratch)
      const [created] = await db
        .insert(campaignMarketIntelligence)
        .values({ requisitionId: id, ...updates } as any)
        .returning();
      res.json(created);
    } catch (err: any) {
      console.error("[CampaignIntel] PATCH error:", err);
      res.status(500).json({ message: "Failed to save override", detail: err?.message });
    }
  });

  // ── Ticket 44: Recruiting Plans ──────────────────────────────────────────

  // GET /api/recruiting/requisitions/:id/recruiting-plan
  app.get("/api/recruiting/requisitions/:id/recruiting-plan", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { db } = await import("./db");
      const { recruitingPlans } = await import("@shared/schema");
      const { eq, desc } = await import("drizzle-orm");

      const [record] = await db
        .select()
        .from(recruitingPlans)
        .where(eq(recruitingPlans.requisitionId, id))
        .orderBy(desc(recruitingPlans.createdAt))
        .limit(1);

      if (!record) return res.json(null);
      res.json(record);
    } catch (err: any) {
      console.error("[RecruitingPlan] GET error:", err);
      res.status(500).json({ message: "Failed to load recruiting plan", detail: err?.message });
    }
  });

  // POST /api/recruiting/requisitions/:id/recruiting-plan/generate — manual regenerate
  app.post("/api/recruiting/requisitions/:id/recruiting-plan/generate", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { db } = await import("./db");
      const { recruitingRequisitions, campaignMarketIntelligence, recruitingRequests } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const [req2] = await db.select().from(recruitingRequisitions).where(eq(recruitingRequisitions.id, id)).limit(1);
      if (!req2) return res.status(404).json({ message: "Requisition not found" });

      let requestData: any = { ...req2 };
      if (req2.sourceRequestId) {
        try {
          const [rr] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, req2.sourceRequestId)).limit(1);
          if (rr) requestData = { ...rr, ...req2 };
        } catch { /* non-fatal */ }
      }

      // Load market intel for channel / pay context
      let marketIntel: any = null;
      try {
        const [mi] = await db.select().from(campaignMarketIntelligence).where(eq(campaignMarketIntelligence.requisitionId, id)).limit(1);
        marketIntel = mi || null;
      } catch { /* non-fatal */ }

      const { recomputePlan } = await import("./services/recruitingPlanService");

      // Create plan first if it doesn't exist
      const { recruitingPlans } = await import("@shared/schema");
      const existing = await db.select().from(recruitingPlans).where(eq(recruitingPlans.requisitionId, id)).limit(1);
      if (existing.length === 0) {
        const { generateRecruitingPlan } = await import("./services/recruitingPlanService");
        const record = await generateRecruitingPlan(req2.sourceRequestId || "", id, requestData, marketIntel);
        return res.json(record);
      }

      const record = await recomputePlan(id, requestData, marketIntel);
      res.json(record);
    } catch (err: any) {
      console.error("[RecruitingPlan] generate error:", err);
      res.status(500).json({ message: "Failed to generate recruiting plan", detail: err?.message });
    }
  });

  // PATCH /api/recruiting/requisitions/:id/recruiting-plan — update targets or status
  app.patch("/api/recruiting/requisitions/:id/recruiting-plan", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const { db } = await import("./db");
      const { recruitingPlans, campaignMarketIntelligence, recruitingRequisitions, recruitingRequests } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const { status, requiredHeadcount, applicantMultiplier, targetDate, revenuePerDriver, filledPositions } = req.body as {
        status?: string;
        requiredHeadcount?: number;
        applicantMultiplier?: number;
        targetDate?: string | null;
        revenuePerDriver?: number;
        filledPositions?: number;
      };

      const existing = await db.select().from(recruitingPlans).where(eq(recruitingPlans.requisitionId, id)).limit(1);

      // If inputs changed, recompute derived fields
      const needsRecompute = requiredHeadcount != null || applicantMultiplier != null || targetDate !== undefined;

      if (needsRecompute) {
        // Load context for recompute
        const [req2] = await db.select().from(recruitingRequisitions).where(eq(recruitingRequisitions.id, id)).limit(1);
        let requestData: any = { ...(req2 || {}) };
        if (req2?.sourceRequestId) {
          try {
            const [rr] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, req2.sourceRequestId)).limit(1);
            if (rr) requestData = { ...rr, ...req2 };
          } catch { /* non-fatal */ }
        }

        // Override with incoming values
        if (requiredHeadcount != null) requestData.targetDriverCount = requiredHeadcount;
        if (targetDate !== undefined)  requestData.targetDate         = targetDate;

        let marketIntel: any = null;
        try {
          const [mi] = await db.select().from(campaignMarketIntelligence).where(eq(campaignMarketIntelligence.requisitionId, id)).limit(1);
          marketIntel = mi || null;
        } catch { /* non-fatal */ }

        const { recomputePlan } = await import("./services/recruitingPlanService");

        if (existing.length === 0) {
          const { generateRecruitingPlan } = await import("./services/recruitingPlanService");
          const record = await generateRecruitingPlan("", id, requestData, marketIntel);
          return res.json(record);
        }

        const updates: any = {};
        if (applicantMultiplier != null) {
          updates.applicantMultiplier = String(applicantMultiplier);
          requestData.applicantMultiplier = applicantMultiplier;
        }
        if (status) updates.status = status;
        updates.generatedBy = "manual";

        // Merge updates then recompute from scratch with the new inputs
        await db.update(recruitingPlans).set(updates).where(eq(recruitingPlans.requisitionId, id));
        const record = await recomputePlan(id, { ...requestData, applicantMultiplier: applicantMultiplier ?? parseFloat(String(existing[0]?.applicantMultiplier ?? "10")) }, marketIntel);
        if (status) {
          const [final] = await db.update(recruitingPlans).set({ status: status as any, generatedBy: "manual" }).where(eq(recruitingPlans.requisitionId, id)).returning();
          return res.json(final);
        }
        return res.json(record);
      }

      // Simple field update (status / revenue fields)
      const simpleFields: any = {};
      if (status)                  simpleFields.status           = status;
      if (revenuePerDriver != null) simpleFields.revenuePerDriver = String(revenuePerDriver);
      if (filledPositions  != null) simpleFields.filledPositions  = filledPositions;

      if (Object.keys(simpleFields).length === 0) {
        return res.status(400).json({ message: "No fields to update" });
      }
      if (existing.length === 0) return res.status(404).json({ message: "Plan not found" });

      simpleFields.updatedAt = new Date();

      const [updated] = await db
        .update(recruitingPlans)
        .set(simpleFields)
        .where(eq(recruitingPlans.requisitionId, id))
        .returning();

      res.json(updated);
    } catch (err: any) {
      console.error("[RecruitingPlan] PATCH error:", err);
      res.status(500).json({ message: "Failed to update recruiting plan", detail: err?.message });
    }
  });

  // ── Ticket 46: Revenue Impact ──────────────────────────────────────────────

  // GET /api/recruiting/revenue-impact
  // Per-market aggregation of unfilled headcount × revenue_per_driver.
  app.get("/api/recruiting/revenue-impact", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { pool } = await import("./db");

      const result = await pool.query(`
        SELECT
          rr.market,
          SUM(rp.required_headcount)::int                                    AS "totalDemand",
          SUM(rp.filled_positions)::int                                      AS "totalFilled",
          SUM(GREATEST(rp.required_headcount - rp.filled_positions, 0))::int AS "totalGap",
          SUM(
            GREATEST(rp.required_headcount - rp.filled_positions, 0)
            * COALESCE(rp.revenue_per_driver, 1200)
          )::numeric(12,2)                                                   AS "weeklyAtRisk",
          COALESCE(
            json_agg(
              json_build_object(
                'requisitionId',    rp.requisition_id,
                'market',           rr.market,
                'requiredHeadcount', rp.required_headcount,
                'filledPositions',  rp.filled_positions,
                'gapCount',         GREATEST(rp.required_headcount - rp.filled_positions, 0),
                'revenuePerDriver', COALESCE(rp.revenue_per_driver, 1200),
                'weeklyAtRisk',     GREATEST(rp.required_headcount - rp.filled_positions, 0)
                                    * COALESCE(rp.revenue_per_driver, 1200),
                'targetDate',       rp.target_date,
                'daysUntilTarget',  rp.days_until_target
              ) ORDER BY rp.created_at DESC
            ) FILTER (WHERE rp.id IS NOT NULL),
            '[]'
          )                                                                  AS campaigns
        FROM recruiting_plans rp
        JOIN recruiting_requisitions rr ON rp.requisition_id = rr.id
        WHERE rp.status != 'completed'
          AND rr.market IS NOT NULL AND rr.market != ''
          AND rr.status NOT IN ('closed', 'cancelled')
          AND rp.required_headcount > rp.filled_positions
        GROUP BY rr.market
        ORDER BY "weeklyAtRisk" DESC
      `);

      res.json(result.rows);
    } catch (err: any) {
      console.error("[RevenueImpact] error:", err);
      res.status(500).json({ message: "Failed to load revenue impact", detail: err?.message });
    }
  });

  // ── Ticket 45: Supply Heatmap ─────────────────────────────────────────────

  // GET /api/recruiting/supply-heatmap
  // Returns per-market demand vs supply aggregation for the coverage heatmap.
  app.get("/api/recruiting/supply-heatmap", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { pool } = await import("./db");

      const result = await pool.query(`
        WITH demand AS (
          SELECT
            rr.market,
            COALESCE(SUM(rp.required_headcount), 0)::int AS demand_count,
            COALESCE(
              json_agg(
                json_build_object(
                  'requisitionId', rp.requisition_id,
                  'requestId',     rp.request_id,
                  'headcount',     rp.required_headcount,
                  'targetDate',    rp.target_date,
                  'status',        rp.status,
                  'riskFlags',     rp.risk_flags
                ) ORDER BY rp.created_at DESC
              ) FILTER (WHERE rp.id IS NOT NULL),
              '[]'
            ) AS campaigns
          FROM recruiting_plans rp
          JOIN recruiting_requisitions rr ON rp.requisition_id = rr.id
          WHERE rp.status != 'completed'
            AND rr.market IS NOT NULL AND rr.market != ''
            AND rr.status NOT IN ('closed', 'cancelled')
          GROUP BY rr.market
        ),
        supply_active AS (
          SELECT
            market,
            COUNT(*)::int AS active_count
          FROM drivers
          WHERE status = 'active'
            AND market IS NOT NULL AND market != ''
          GROUP BY market
        ),
        supply_pipeline AS (
          SELECT
            rr.market,
            COUNT(DISTINCT ra.candidate_id)::int AS pipeline_count,
            COUNT(DISTINCT ra.candidate_id) FILTER (
              WHERE ra.readiness_status = 'ready'
            )::int AS ready_count
          FROM recruiting_applications ra
          JOIN recruiting_requisitions rr ON ra.requisition_id = rr.id
          WHERE ra.current_stage NOT IN ('hired','rejected','withdrawn','declined','disqualified')
            AND ra.is_archived = false
            AND rr.market IS NOT NULL AND rr.market != ''
          GROUP BY rr.market
        )
        SELECT
          d.market,
          d.demand_count                                          AS "demandCount",
          COALESCE(sa.active_count, 0)                            AS "supplyActive",
          COALESCE(sp.pipeline_count, 0)                          AS "supplyPipeline",
          COALESCE(sp.ready_count, 0)                             AS "supplyReady",
          COALESCE(sa.active_count, 0) + COALESCE(sp.ready_count, 0)
                                                                  AS "supplyTotal",
          d.demand_count - (COALESCE(sa.active_count, 0) + COALESCE(sp.ready_count, 0))
                                                                  AS "gapCount",
          d.campaigns
        FROM demand d
        LEFT JOIN supply_active   sa ON sa.market = d.market
        LEFT JOIN supply_pipeline sp ON sp.market = d.market
        ORDER BY
          (d.demand_count - (COALESCE(sa.active_count, 0) + COALESCE(sp.ready_count, 0))) DESC,
          d.market ASC
      `);

      res.json(result.rows);
    } catch (err: any) {
      console.error("[SupplyHeatmap] error:", err);
      res.status(500).json({ message: "Failed to load supply heatmap", detail: err?.message });
    }
  });

  // ── Recruiting Campaign Manager routes ──────────────────────────────────────

  // GET /api/recruiting/campaigns/metrics — Dashboard summary
  app.get("/api/recruiting/campaigns/metrics", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
      const { sql: sqlHelper, eq } = await import("drizzle-orm");

      const joinedRows = await db
        .select({
          campaign: recruitingCampaigns,
          requestStartDate: recruitingRequests.campaignStartDate,
        })
        .from(recruitingCampaigns)
        .leftJoin(recruitingRequests, eq(recruitingCampaigns.requestId, recruitingRequests.id));
      const rows = joinedRows.map(({ campaign, requestStartDate }) => ({
        ...campaign,
        startDate: requestStartDate ?? campaign.startDate,
      }));
      const open   = rows.filter((r) => r.status === "active").length;
      const closed = rows.filter((r) => r.status === "closed").length;
      const totalHires= rows.reduce((s, r) => s + (r.hiresCount ?? 0), 0);
      const totalGoal = rows.reduce((s, r) => s + (r.hiringGoal ?? 0), 0);
      const totalApps = rows.reduce((s, r) => s + (r.applicantsCount ?? 0), 0);
      const totalInts = rows.reduce((s, r) => s + (r.interviewsCount ?? 0), 0);
      const totalOffs = rows.reduce((s, r) => s + (r.offersCount ?? 0), 0);
      const totalSpend= rows.reduce((s, r) => s + Number(r.totalSpend ?? 0), 0);
      const totalBudget = rows.reduce((s, r) => s + Number(r.budget ?? 0), 0);
      const fillRate  = totalGoal > 0 ? Math.round((totalHires / totalGoal) * 100) : 0;
      const costPerHire = totalHires > 0 && totalSpend > 0 ? Math.round(totalSpend / totalHires) : null;

      // Avg time to fill (days from the approval business date to now, per hire)
      const withDates = rows.filter((r) => r.startDate && r.hiresCount > 0);
      const todayBusinessDate = approvalTimestampToCampaignDate(new Date());
      const todayDayNumber = Date.parse(`${todayBusinessDate}T00:00:00Z`);
      const avgTtf = withDates.length > 0
        ? Math.round(withDates.reduce((s, r) => {
            const startDayNumber = Date.parse(`${String(r.startDate).slice(0, 10)}T00:00:00Z`);
            const days = Math.max(0, (todayDayNumber - startDayNumber) / 86400000);
            return s + days / Math.max(r.hiresCount, 1);
          }, 0) / withDates.length)
        : null;

      res.json({
        openCampaigns: open, closedCampaigns: closed,
        totalApplicants: totalApps, totalInterviews: totalInts, totalOffers: totalOffs,
        totalHires, totalGoal, fillRate, costPerHire,
        totalSpend, totalBudget,
        avgTimeToFill: avgTtf != null ? `${avgTtf}d` : "—",
      });
    } catch (e: any) {
      console.error("[campaigns/metrics]", e);
      res.status(500).json({ message: "Failed to load campaign metrics" });
    }
  });

  // GET /api/recruiting/campaigns — List all campaigns
  app.get("/api/recruiting/campaigns", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
      const { desc, eq } = await import("drizzle-orm");
      const joinedRows = await db
        .select({
          campaign: recruitingCampaigns,
          requestStartDate: recruitingRequests.campaignStartDate,
        })
        .from(recruitingCampaigns)
        .leftJoin(recruitingRequests, eq(recruitingCampaigns.requestId, recruitingRequests.id))
        .orderBy(desc(recruitingCampaigns.createdAt));
      const rows = joinedRows.map(({ campaign, requestStartDate }) => ({
        ...campaign,
        startDate: requestStartDate ?? campaign.startDate,
      }));
      // Augment each campaign with compact job-posting summaries (for card indicator)
      if (rows.length > 0) {
        const { pool } = await import("./db");
        const ids = rows.map((r: any) => r.id);
        const { rows: pRows } = await pool.query(
          `SELECT campaign_id, source, source_name, posting_url, posting_status
           FROM   recruiting_job_postings
           WHERE  campaign_id = ANY($1) AND posting_status != 'removed'
           ORDER  BY created_at`,
          [ids]
        );
        const pMap: Record<string, any[]> = {};
        for (const p of pRows) {
          if (!pMap[p.campaign_id]) pMap[p.campaign_id] = [];
          pMap[p.campaign_id].push({ source: p.source, sourceName: p.source_name, postingUrl: p.posting_url, postingStatus: p.posting_status });
        }
        return res.json(rows.map((r: any) => ({
          ...r,
          jobPostings: pMap[r.id] ?? [],
          canManageJobPostings: hasRecruitingJobPostingWriteAccess(recruitingContext),
        })));
      }
      res.json(rows.map((r: any) => ({
        ...r,
        canManageJobPostings: hasRecruitingJobPostingWriteAccess(recruitingContext),
      })));
    } catch (e: any) {
      console.error("[campaigns GET]", e);
      res.status(500).json({ message: "Failed to load campaigns" });
    }
  });

  // POST /api/recruiting/campaigns — Create a new campaign
  app.post("/api/recruiting/campaigns", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });

      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const orgId = (user as any).orgId || "26c087eb-0d86-4a4c-b48e-e2049323ccfd";
      const actorName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;

      const {
        campaignName, requestId, requisitionId, market, network,
        driverTypes, driversNeeded, hiringGoal, startDate, endDate,
        budget, priority, recruiterId, advertisingSources, referralBonus, notes, status,
      } = req.body;

      if (!campaignName?.trim()) return res.status(400).json({ message: "campaignName is required" });
      if (!driverTypes?.length) return res.status(400).json({ message: "At least one driverType is required" });

      // Linked Campaigns always inherit the authoritative Request approval date.
      let requestStartDate: string | null = null;
      if (requestId) {
        const [req2] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, requestId)).limit(1);
        if (!req2) return res.status(404).json({ message: "Linked request not found" });
        if (!req2.approvedAt || req2.approvalStatus !== "approved") {
          return res.status(409).json({ message: "Linked request must be approved before a Campaign can be created." });
        }
        requestStartDate = approvalTimestampToCampaignDate(req2.approvedAt);
      }

      // Resolve recruiter name
      let recruiterName: string | null = null;
      if (recruiterId) {
        const recruiter = await storage.getUser(recruiterId);
        if (recruiter) recruiterName = `${recruiter.firstName || ""} ${recruiter.lastName || ""}`.trim() || (recruiter as any).email || recruiterId;
      }

      const [created] = await db.insert(recruitingCampaigns).values({
        orgId,
        campaignName: campaignName.trim(),
        requestId: requestId || null,
        requisitionId: requisitionId || null,
        market: market || null,
        network: network || null,
        driverTypes: Array.isArray(driverTypes) ? driverTypes : [],
        driversNeeded: Number(driversNeeded) || 1,
        hiringGoal: Number(hiringGoal) || 1,
        startDate: requestId ? requestStartDate : (startDate || null),
        endDate: endDate || null,
        budget: budget ? String(budget) : null,
        priority: priority || "medium",
        recruiterId: recruiterId || null,
        recruiterName,
        advertisingSources: Array.isArray(advertisingSources) ? advertisingSources : [],
        referralBonus: referralBonus ? String(referralBonus) : null,
        notes: notes?.trim() || null,
        status: status || "active",
        createdBy: userId,
        updatedBy: userId,
      }).returning();

      // Back-link the request if provided
      if (requestId) {
        try {
          await db.update(recruitingRequests)
            .set({ requestStatus: "recruiting_active", updatedAt: new Date() } as any)
            .where(eq(recruitingRequests.id, requestId));
        } catch (_) { /* non-fatal */ }
      }

      res.status(201).json(created);
    } catch (e: any) {
      console.error("[campaigns POST]", e);
      res.status(500).json({ message: "Failed to create campaign" });
    }
  });

  // GET /api/recruiting/campaigns/closed — Closed Campaigns view (DH-002164)
  // Must be registered BEFORE the /:id wildcard route.
  app.get("/api/recruiting/campaigns/closed", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      const recruitingContext = await getUserRecruitingContext(userId, user?.role || "");
      if (!hasRecruitingModuleReadAccess(recruitingContext)) {
        return res.status(403).json({ message: "Forbidden: Recruiting access required" });
      }
      const { pool } = await import("./db");
      const { rows } = await pool.query(`
        SELECT
          rr.id,
          COALESCE(req.title, rr.dealership_name)  AS "campaignName",
          rr.id                                     AS "requestId",
          rr.campaign_start_date                    AS "startDate",
          rr.target_date                            AS "endDate",
          req.closed_at                             AS "closedAt",
          -- DH-002164/DH-002168: canonical business closing date from recruiting_requests
          rr.actual_closing_date                    AS "actualClosingDate",
          NULL::text                                AS "closedByName",
          (rr.actual_closing_date IS NULL)          AS "missingClosingDate",
          rr.target_driver_count                    AS "targetDriverCount",
          NULL::text                                AS "urgencyLevel",
          req.status,
          rr.dealership_name                        AS "dealershipName",
          rr.location,
          rr.additional_comments                    AS "additionalComments",
          rr.cert_liaison                           AS "certLiaison",
          rr.urgency,
          rr.campaign_type                          AS "campaignType",
          rr.driver_classification                  AS "driverClassification",
          rr.program_type                           AS "programType",
          rr.employment_type                        AS "employmentType",
          rr.account_id                             AS "accountId",
          -- Hired driver count (campaign_id on activated_drivers = recruiting_requests.id)
          COALESCE(hired.driver_count, 0)           AS "hiredDriversCount",
          -- WIW hours for linked drivers, trailing 30 days
          wiw.hours                                 AS "wiwHoursLast30",
          -- Open Days: actual_closing_date − campaign_start_date (fixed historical value, never uses today)
          CASE
            WHEN rr.actual_closing_date IS NOT NULL AND rr.campaign_start_date IS NOT NULL
            THEN GREATEST(0, (rr.actual_closing_date - rr.campaign_start_date))
            ELSE NULL
          END                                       AS "openDays",
          -- Schedule Variance: target_date − actual_closing_date (positive = early, negative = late)
          -- NULL when actual_closing_date unavailable; never substitute another date.
          CASE
            WHEN rr.target_date IS NOT NULL AND rr.actual_closing_date IS NOT NULL
            THEN (rr.target_date - rr.actual_closing_date)
            ELSE NULL
          END                                       AS "scheduleVariance"
        FROM recruiting_requests rr
        JOIN recruiting_requisitions req ON req.id = rr.campaign_requisition_id
        LEFT JOIN (
          SELECT campaign_id, COUNT(*)::int AS driver_count
          FROM   recruiting_campaign_activated_drivers
          GROUP  BY campaign_id
        ) hired ON hired.campaign_id = rr.id
        LEFT JOIN (
          SELECT
            rcad.campaign_id,
            ROUND(SUM(wt.total_minutes) / 60.0, 1) AS hours
          FROM   recruiting_campaign_activated_drivers rcad
          JOIN   drivers d  ON d.id = rcad.driver_id
          JOIN   wiw_times wt ON wt.wiw_user_id = d.wiw_user_id
          WHERE  wt.clock_in >= NOW() - INTERVAL '30 days'
            AND  wt.total_minutes IS NOT NULL
            AND  wt.total_minutes > 0
            AND  d.wiw_user_id IS NOT NULL
          GROUP  BY rcad.campaign_id
        ) wiw ON wiw.campaign_id = rr.id
        WHERE req.status::text IN ('closed', 'filled')
          AND rr.is_archived = false
          AND rr.is_test_data = false
        ORDER BY req.closed_at DESC NULLS LAST
      `);
      // pool.query() returns numeric columns as strings — coerce before sending
      const coerced = rows.map((r: any) => ({
        ...r,
        targetDriverCount: r.targetDriverCount != null ? Number(r.targetDriverCount) : 0,
        hiredDriversCount: r.hiredDriversCount != null ? Number(r.hiredDriversCount) : 0,
        wiwHoursLast30:    r.wiwHoursLast30    != null ? Number(r.wiwHoursLast30)    : null,
        urgency:           r.urgency           != null ? Number(r.urgency)           : null,
        openDays:          r.openDays          != null ? Number(r.openDays)          : null,
        scheduleVariance:  r.scheduleVariance  != null ? Number(r.scheduleVariance)  : null,
      }));
      res.json(coerced);
    } catch (e: any) {
      console.error("[campaigns/closed GET]", e);
      res.status(500).json({ message: "Failed to load closed campaigns" });
    }
  });

  // GET /api/recruiting/campaigns/hired-last-45 — DH-002165
  // Rolling 45-day Drivers Hired widget: aggregate + driver detail list.
  // Uses activation_date from recruiting_campaign_activated_drivers (NOT campaign closed date).
  // Must be registered BEFORE the /:id wildcard route.
  app.get("/api/recruiting/campaigns/hired-last-45", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { pool } = await import("./db");

      // Aggregate — unique driver count + IC/Employee split
      const aggResult = await pool.query(`
        SELECT
          COUNT(DISTINCT rcad.driver_id)::int AS total,
          COUNT(DISTINCT CASE
            WHEN LOWER(COALESCE(d.driver_classification, '')) LIKE '%employee%'
            THEN rcad.driver_id
          END)::int AS employee_count,
          COUNT(DISTINCT CASE
            WHEN LOWER(COALESCE(d.driver_classification, '')) NOT LIKE '%employee%'
              AND d.driver_classification IS NOT NULL
            THEN rcad.driver_id
          END)::int AS ic_count
        FROM recruiting_campaign_activated_drivers rcad
        JOIN drivers d ON d.id = rcad.driver_id
        LEFT JOIN recruiting_requests rr_test ON rr_test.id = rcad.campaign_id
        WHERE rcad.activation_date IS NOT NULL
          AND rcad.activation_date >= CURRENT_DATE - INTERVAL '44 days'
          AND rcad.activation_date <= CURRENT_DATE
          AND COALESCE(rr_test.is_test_data, false) = false
      `);
      const agg = aggResult.rows[0] ?? { total: 0, ic_count: 0, employee_count: 0 };

      // Detail list — one row per unique driver (most recent activation_date wins)
      const detailResult = await pool.query(`
        SELECT DISTINCT ON (rcad.driver_id)
          rcad.driver_id                              AS "driverId",
          rcad.activation_date                        AS "activationDate",
          rcad.campaign_id                            AS "campaignId",
          COALESCE(
            NULLIF(CONCAT(u.first_name, ' ', u.last_name), ' '),
            u.email,
            'Driver ' || d.id
          )                                           AS "displayName",
          d.employee_id                               AS "employeeId",
          d.status                                    AS "currentStatus",
          d.driver_classification                     AS "currentDriverClassification",
          d.driver_type                               AS "currentDriverType",
          d.employment_type                            AS "currentEmploymentType",
          rr.dealership_name                          AS "dealershipName",
          rr.market                                   AS "market",
          rc.campaign_name                            AS "campaignName",
          rc.id                                       AS "campaignDbId",
          (CURRENT_DATE - rcad.activation_date)::int  AS "daysSinceActivation"
        FROM recruiting_campaign_activated_drivers rcad
        JOIN drivers d ON d.id = rcad.driver_id
        LEFT JOIN users u ON u.id = d.user_id
        LEFT JOIN recruiting_requests rr ON rr.id = rcad.campaign_id
        LEFT JOIN recruiting_campaigns rc ON rc.request_id = rcad.campaign_id
        WHERE rcad.activation_date IS NOT NULL
          AND rcad.activation_date >= CURRENT_DATE - INTERVAL '44 days'
          AND rcad.activation_date <= CURRENT_DATE
          AND COALESCE(rr.is_test_data, false) = false
        ORDER BY rcad.driver_id, rcad.activation_date DESC
      `);

      res.json({
        total:         agg.total,
        icCount:       agg.ic_count,
        employeeCount: agg.employee_count,
        drivers:       detailResult.rows,
      });
    } catch (e: any) {
      console.error("[campaigns/hired-last-45 GET]", e);
      res.status(500).json({ message: "Failed to load hired-last-45 data" });
    }
  });

