  // PATCH /api/recruiting/campaigns/:id/closing-date — DH-002168
  // Edit actual closing date after campaign has been closed.
  // :id is the recruiting_request.id (the UI passes c.id which = rr.id from the closed query).
  // Requires a reason. Writes actual_closing_date to recruiting_requests (the canonical table).
  // Must be registered BEFORE the /:id wildcard route.
  app.patch("/api/recruiting/campaigns/:id/closing-date", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const ALLOWED = new Set(["super_user", "root_super_admin", "admin", "corporate_admin", "manager", "recruiter", "recruiting_admin"]);
      if (!ALLOWED.has(user.role ?? "")) return res.status(403).json({ message: "Insufficient permissions to edit closing date" });

      const { actualClosingDate, reason } = req.body;
      if (!actualClosingDate) return res.status(400).json({ message: "actualClosingDate is required" });
      if (!reason || !String(reason).trim()) return res.status(400).json({ message: "A reason is required when editing the closing date" });
      const todayStr = new Date().toISOString().split("T")[0];
      if (actualClosingDate > todayStr) return res.status(400).json({ message: "Actual Closing Date cannot be in the future" });

      const { db } = await import("./db");
      const { recruitingRequests, recruitingAuditEvents } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      // Look up by recruiting_requests.id (the Closed Campaign List returns rr.id as c.id)
      const [existing] = await db
        .select({ id: recruitingRequests.id, actualClosingDate: recruitingRequests.actualClosingDate })
        .from(recruitingRequests)
        .where(eq(recruitingRequests.id, req.params.id))
        .limit(1);
      if (!existing) return res.status(404).json({ message: "Campaign not found" });

      const actorName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;
      const previousDate = existing.actualClosingDate;

      const [updated] = await db
        .update(recruitingRequests)
        .set({ actualClosingDate, updatedAt: new Date() })
        .where(eq(recruitingRequests.id, req.params.id))
        .returning();

      // Audit trail — preserves both original and corrected values
      await db.insert(recruitingAuditEvents).values({
        actionType: "CLOSING_DATE_UPDATED",
        entityType: "request",
        entityId: req.params.id,
        userId,
        userEmail: user.email || null,
        actorRole: user.role || null,
        source: "ui",
        previousValue: JSON.stringify({ actualClosingDate: previousDate ?? null }),
        newValue: JSON.stringify({ actualClosingDate }),
        changedFields: ["actualClosingDate"],
        reason: reason.trim(),
      });

      res.json({ id: updated.id, actualClosingDate: updated.actualClosingDate });
    } catch (e: any) {
      console.error("[campaigns/closing-date PATCH]", e);
      res.status(500).json({ message: "Failed to update closing date" });
    }
  });

  // PATCH /api/recruiting/campaigns/:id — Update campaign
  app.patch("/api/recruiting/campaigns/:id", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });

      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const {
        campaignName, market, network, driverTypes, driversNeeded, hiringGoal,
        startDate, endDate, budget, priority, recruiterId, advertisingSources,
        referralBonus, notes, status,
      } = req.body;

      const [existingCampaign] = await db.select().from(recruitingCampaigns)
        .where(eq(recruitingCampaigns.id, req.params.id)).limit(1);
      if (!existingCampaign) return res.status(404).json({ message: "Campaign not found" });

      const updateData: Record<string, any> = { updatedAt: new Date(), updatedBy: userId };
      if (campaignName !== undefined)       updateData.campaignName = campaignName;
      if (market !== undefined)             updateData.market = market;
      if (network !== undefined)            updateData.network = network;
      if (driverTypes !== undefined)        updateData.driverTypes = driverTypes;
      if (driversNeeded !== undefined)      updateData.driversNeeded = Number(driversNeeded);
      if (hiringGoal !== undefined)         updateData.hiringGoal = Number(hiringGoal);
      if (existingCampaign.requestId) {
        const [linkedRequest] = await db.select({
          approvedAt: recruitingRequests.approvedAt,
          approvalStatus: recruitingRequests.approvalStatus,
        }).from(recruitingRequests)
          .where(eq(recruitingRequests.id, existingCampaign.requestId)).limit(1);
        if (linkedRequest?.approvedAt && linkedRequest.approvalStatus === "approved") {
          updateData.startDate = approvalTimestampToCampaignDate(linkedRequest.approvedAt);
        }
      } else if (startDate !== undefined) {
        updateData.startDate = startDate || null;
      }
      if (endDate !== undefined)            updateData.endDate = endDate || null;
      if (budget !== undefined)             updateData.budget = budget ? String(budget) : null;
      if (priority !== undefined)           updateData.priority = priority;
      if (advertisingSources !== undefined) updateData.advertisingSources = advertisingSources;
      if (referralBonus !== undefined)      updateData.referralBonus = referralBonus ? String(referralBonus) : null;
      if (notes !== undefined)              updateData.notes = notes?.trim() || null;
      if (status !== undefined) {
        updateData.status = status;
        // Stamp closedAt the first time a campaign is set to "closed"
        if (status === "closed") {
          if (!existingCampaign.closedAt) updateData.closedAt = new Date();
        }
      }
      if (recruiterId !== undefined) {
        updateData.recruiterId = recruiterId || null;
        if (recruiterId) {
          const rec = await storage.getUser(recruiterId);
          if (rec) updateData.recruiterName = `${rec.firstName || ""} ${rec.lastName || ""}`.trim() || (rec as any).email || recruiterId;
        } else {
          updateData.recruiterName = null;
        }
      }

      const [updated] = await db.update(recruitingCampaigns).set(updateData).where(eq(recruitingCampaigns.id, req.params.id)).returning();
      if (!updated) return res.status(404).json({ message: "Campaign not found" });
      res.json(updated);
    } catch (e: any) {
      console.error("[campaigns PATCH]", e);
      res.status(500).json({ message: "Failed to update campaign" });
    }
  });

  // POST /api/recruiting/campaigns/:id/clone-maintenance — Clone a closed campaign as a Maintenance/Back Up Role campaign
  app.post("/api/recruiting/campaigns/:id/clone-maintenance", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });

      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingCampaignActivity } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      const { targetCompletionDate, campaignName: overrideName } = req.body;
      if (!targetCompletionDate) {
        return res.status(400).json({ message: "targetCompletionDate is required" });
      }

      // Load source campaign
      const [source] = await db.select().from(recruitingCampaigns)
        .where(eq(recruitingCampaigns.id, req.params.id)).limit(1);
      if (!source) return res.status(404).json({ message: "Campaign not found" });

      // Must be in a terminal status
      const CLOSED_STATUSES = ["closed", "cancelled"];
      if (!CLOSED_STATUSES.includes(source.status)) {
        return res.status(400).json({
          message: "Campaign must be closed or cancelled before creating a maintenance clone",
        });
      }

      // Duplicate prevention
      if (source.maintenanceCloneId) {
        const [existing] = await db
          .select({ id: recruitingCampaigns.id, campaignName: recruitingCampaigns.campaignName })
          .from(recruitingCampaigns)
          .where(eq(recruitingCampaigns.id, source.maintenanceCloneId))
          .limit(1);
        return res.status(409).json({
          message: "A Maintenance / Back Up Role campaign has already been created from this campaign.",
          existingCloneId: source.maintenanceCloneId,
          existingCloneName: existing?.campaignName ?? null,
        });
      }

      const actorName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || (user as any).email || userId;
      const now = new Date();
      const todayIso = now.toISOString().slice(0, 10);
      const cloneName = overrideName?.trim() || `${source.campaignName} — Maintenance / Back Up Role`;
      const displayDate = now.toLocaleDateString("en-US", { year: "numeric", month: "long", day: "numeric" });

      // Create the maintenance clone
      const [clone] = await db.insert(recruitingCampaigns).values({
        orgId:              source.orgId,
        campaignName:       cloneName,
        requestId:          null,   // fresh record — not linked to original request
        requisitionId:      null,
        market:             source.market,
        network:            source.network,
        driverTypes:        source.driverTypes ?? [],
        driversNeeded:      source.driversNeeded ?? 1,
        hiringGoal:         source.hiringGoal ?? 1,
        startDate:          todayIso,
        endDate:            targetCompletionDate,
        budget:             source.budget,
        priority:           source.priority ?? "medium",
        urgencyLevel:       "Maintenance / Back Up Role",
        recruiterId:        source.recruiterId,
        recruiterName:      source.recruiterName,
        advertisingSources: source.advertisingSources ?? [],
        referralBonus:      source.referralBonus,
        notes:              source.notes,
        status:             "active",
        // Clone provenance
        clonedFromCampaignId: source.id,
        clonedAt:             now,
        clonedBy:             userId,
        // Fresh counters
        applicantsCount:  0,
        interviewsCount:  0,
        offersCount:      0,
        hiresCount:       0,
        totalSpend:       "0",
        createdBy:        userId,
        updatedBy:        userId,
      } as any).returning();

      // Back-link source campaign → new clone
      await db.update(recruitingCampaigns)
        .set({
          maintenanceCloneId:        clone.id,
          maintenanceCloneCreatedAt: now,
          updatedAt: now,
          updatedBy: userId,
        } as any)
        .where(eq(recruitingCampaigns.id, source.id));

      // Activity log — source campaign
      await db.insert(recruitingCampaignActivity).values({
        campaignId: source.id,
        eventType:  "maintenance_clone_created",
        message:    `Maintenance campaign "${cloneName}" created from this campaign by ${actorName} on ${displayDate}.`,
        actorId:    userId,
        actorName,
      } as any);

      // Activity log — new clone
      await db.insert(recruitingCampaignActivity).values({
        campaignId: clone.id,
        eventType:  "cloned_from",
        message:    `Campaign cloned from "${source.campaignName}" by ${actorName} on ${displayDate}.`,
        actorId:    userId,
        actorName,
      } as any);

      res.status(201).json(clone);
    } catch (e: any) {
      console.error("[campaigns clone-maintenance]", e);
      res.status(500).json({ message: "Failed to create maintenance clone" });
    }
  });

