  // POST /api/recruiting/campaigns/:id/record-hire — Record hires + spend; auto-updates linked request
  app.post("/api/recruiting/campaigns/:id/record-hire", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { db } = await import("./db");
      const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
      const { eq, sql: sqlHelper } = await import("drizzle-orm");

      const { count = 1, spend } = req.body;
      const hiresAdded = Math.max(1, Number(count));
      const spendAdded = spend ? Number(spend) : 0;

      const [existing] = await db.select().from(recruitingCampaigns).where(eq(recruitingCampaigns.id, req.params.id)).limit(1);
      if (!existing) return res.status(404).json({ message: "Campaign not found" });

      const newHires = (existing.hiresCount ?? 0) + hiresAdded;
      const newSpend = Number(existing.totalSpend ?? 0) + spendAdded;
      const isComplete = newHires >= (existing.hiringGoal ?? 1);

      const updateData: Record<string, any> = {
        hiresCount: newHires,
        totalSpend: String(newSpend),
        updatedAt: new Date(),
        updatedBy: userId,
      };
      if (isComplete) updateData.status = "completed";

      const [updated] = await db.update(recruitingCampaigns).set(updateData).where(eq(recruitingCampaigns.id, req.params.id)).returning();

      // Auto-update linked recruiting request to "completed" when hiring goal met
      if (isComplete && existing.requestId) {
        try {
          await db.update(recruitingRequests)
            .set({ requestStatus: "completed", updatedAt: new Date() } as any)
            .where(eq(recruitingRequests.id, existing.requestId));
          // Log activity
          const { recruitingRequestActivity } = await import("@shared/schema");
          await db.insert(recruitingRequestActivity).values({
            orgId: existing.orgId,
            requestId: existing.requestId,
            userId,
            action: "status_change",
            fromStatus: "recruiting_active",
            toStatus: "completed",
            notes: `Hiring goal met — ${newHires} hire(s) recorded via Campaign Manager`,
          });
        } catch (_) { /* non-fatal */ }
      }

      res.json({ updated, isComplete, newHires, newSpend });
    } catch (e: any) {
      console.error("[campaigns/record-hire]", e);
      res.status(500).json({ message: "Failed to record hire" });
    }
  });

  // ── Recruiting Job Postings (DH-002127) ──────────────────────────────────────
  // Read and write actions use the established Recruiting permission and market
  // scope model. A client-supplied campaign ID never grants access by itself.

  // Auto-expire: set posting_status='expired' for active postings whose expires_at has passed
  async function autoExpireCampaignPostings(campaignId: string) {
    try {
      const { pool } = await import("./db");
      await pool.query(
        `UPDATE recruiting_job_postings
         SET    posting_status = 'expired', updated_at = NOW()
         WHERE  campaign_id   = $1
         AND    posting_status = 'active'
         AND    expires_at IS NOT NULL
         AND    expires_at < CURRENT_DATE`,
        [campaignId]
      );
    } catch (_) { /* non-fatal */ }
  }

  async function authorizeJobPostingCampaign(
    user: { id: string; role: string | null },
    campaignReference: string,
    permission: "read" | "write",
  ) {
    const { recruitingCampaigns, recruitingRequests } = await import("@shared/schema");
    const { eq, or } = await import("drizzle-orm");

    // Campaign Detail routes are Request-ID based. Prefer a linked legacy
    // campaign when one exists so pre-existing Campaign-ID integrations keep
    // sharing the same postings; otherwise the Request is the posting owner.
    const [campaign] = await db.select({
      id: recruitingCampaigns.id,
      market: recruitingCampaigns.market,
    })
      .from(recruitingCampaigns)
      .where(or(
        eq(recruitingCampaigns.id, campaignReference),
        eq(recruitingCampaigns.requestId, campaignReference),
      ))
      .limit(1);

    const postingOwner = campaign ?? (await db.select({
      id: recruitingRequests.id,
      market: recruitingRequests.market,
    })
      .from(recruitingRequests)
      .where(eq(recruitingRequests.id, campaignReference))
      .limit(1))[0];

    if (!postingOwner) {
      return { allowed: false as const, status: 404, message: "Recruiting campaign not found" };
    }

    const recruitingContext = await getUserRecruitingContext(user.id, user.role || "");
    // Job Posting management is a dedicated Recruiting capability because legacy
    // Campaign records frequently have no authoritative market.
    const authorized = permission === "read"
      ? hasRecruitingModuleReadAccess(recruitingContext)
      : hasRecruitingJobPostingWriteAccess(recruitingContext);
    if (!authorized) {
      return { allowed: false as const, status: 403, message: "Forbidden: insufficient Recruiting permissions" };
    }

    return { allowed: true as const, campaign: postingOwner };
  }

  // GET /api/recruiting/campaigns/:id/postings
  app.get("/api/recruiting/campaigns/:id/postings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.session?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeJobPostingCampaign(user, req.params.id, "read");
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const campaignId = authorization.campaign.id;
      await autoExpireCampaignPostings(campaignId);
      const { db } = await import("./db");
      const { recruitingJobPostings } = await import("@shared/schema");
      const { eq, desc } = await import("drizzle-orm");
      const postings = await db.select().from(recruitingJobPostings)
        .where(eq(recruitingJobPostings.campaignId, campaignId))
        .orderBy(desc(recruitingJobPostings.createdAt));
      res.json(postings);
    } catch (e: any) {
      console.error("[job-postings/list]", e);
      res.status(500).json({ message: "Failed to fetch job postings" });
    }
  });

  // POST /api/recruiting/campaigns/:id/postings
  app.post("/api/recruiting/campaigns/:id/postings", isAuthenticated, async (req: any, res: Response) => {
    const userId = req.session?.userId || req.user?.claims?.sub;
    try {
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeJobPostingCampaign(user, req.params.id, "write");
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const campaignId = authorization.campaign.id;
      const { db } = await import("./db");
      const { recruitingJobPostings } = await import("@shared/schema");
      const { normalizeNewJobPosting } = await import("./services/recruitingJobPostings");
      const normalized = normalizeNewJobPosting(req.body);
      if (!normalized.ok) {
        return res.status(400).json({
          message: "Please correct the highlighted job posting fields.",
          fieldErrors: normalized.fieldErrors,
        });
      }
      const { source, sourceName, postingUrl, postingStatus, postedAt, expiresAt, notes } = normalized.data;
      const [posting] = await db.insert(recruitingJobPostings).values({
        campaignId,
        source,
        sourceName,
        postingUrl,
        postingStatus,
        postedAt,
        expiresAt,
        notes,
        createdBy:     user.id,
        updatedBy:     user.id,
      }).returning();
      res.status(201).json(posting);
    } catch (e: any) {
      const referenceId = `rjp-create-${crypto.randomUUID()}`;
      console.error("[job-postings/create] unexpected database failure", {
        referenceId,
        campaignId: req.params.id,
        actorUserId: userId ?? null,
        code: e?.code,
        constraint: e?.constraint,
        detail: e?.detail,
        message: e?.message,
        stack: e?.stack,
      });
      res.status(500).json({
        message: "DriverHub could not save this job posting due to a system error. Your information has been retained. Please try again.",
        referenceId,
        retryable: true,
      });
    }
  });

  // PATCH /api/recruiting/campaigns/:campaignId/postings/:postingId
  app.patch("/api/recruiting/campaigns/:campaignId/postings/:postingId", isAuthenticated, async (req: any, res: Response) => {
    const userId = req.session?.userId || req.user?.claims?.sub;
    try {
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user) return res.status(401).json({ message: "Not authenticated" });
      const authorization = await authorizeJobPostingCampaign(user, req.params.campaignId, "write");
      if (!authorization.allowed) return res.status(authorization.status).json({ message: authorization.message });
      const campaignId = authorization.campaign.id;
      const { db } = await import("./db");
      const { recruitingJobPostings } = await import("@shared/schema");
      const { eq, and } = await import("drizzle-orm");
      const { normalizeJobPostingUpdate } = await import("./services/recruitingJobPostings");
      const [existingPosting] = await db.select({
        postedAt: recruitingJobPostings.postedAt,
        expiresAt: recruitingJobPostings.expiresAt,
      }).from(recruitingJobPostings)
        .where(and(
          eq(recruitingJobPostings.id, req.params.postingId),
          eq(recruitingJobPostings.campaignId, campaignId),
        ))
        .limit(1);
      if (!existingPosting) return res.status(404).json({ message: "Posting not found" });
      const normalized = normalizeJobPostingUpdate(req.body, existingPosting);
      if (!normalized.ok) {
        return res.status(400).json({
          message: "Please correct the highlighted job posting fields.",
          fieldErrors: normalized.fieldErrors,
        });
      }
      const updateData: Record<string, any> = { updatedAt: new Date(), updatedBy: user.id };
      Object.assign(updateData, normalized.data);
      const [updated] = await db.update(recruitingJobPostings)
        .set(updateData)
        .where(and(eq(recruitingJobPostings.id, req.params.postingId), eq(recruitingJobPostings.campaignId, campaignId)))
        .returning();
      if (!updated) return res.status(404).json({ message: "Posting not found" });
      res.json(updated);
    } catch (e: any) {
      const referenceId = `rjp-update-${crypto.randomUUID()}`;
      console.error("[job-postings/update] unexpected database failure", {
        referenceId,
        campaignId: req.params.campaignId,
        postingId: req.params.postingId,
        actorUserId: userId ?? null,
        code: e?.code,
        constraint: e?.constraint,
        detail: e?.detail,
        message: e?.message,
        stack: e?.stack,
      });
      res.status(500).json({
        message: "DriverHub could not update this job posting due to a system error. Your information has been retained. Please try again.",
        referenceId,
        retryable: true,
      });
    }
  });

  // POST /api/recruiting/requests/:id/create-campaign — Convert approved request → recruiting campaign
  app.post("/api/recruiting/requests/:id/create-campaign", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !["admin","super_user","corporate_admin","manager","recruiting_admin"].includes(user.role || "")) {
        return res.status(403).json({ message: "Insufficient permissions" });
      }

      const { id } = req.params;
      const { recruiterId, notes } = req.body;
      if (!recruiterId) return res.status(400).json({ message: "recruiterId is required" });

      const { db } = await import("./db");
      const { recruitingRequests, recruitingRequisitions } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");

      // Load the source request
      const [request] = await db.select().from(recruitingRequests).where(eq(recruitingRequests.id, id)).limit(1);
      if (!request) return res.status(404).json({ message: "Request not found" });
      if (request.requestStatus !== "approved") {
        return res.status(400).json({ message: "Only approved requests can be converted to campaigns." });
      }
      if (request.campaignRequisitionId) {
        return res.status(409).json({ message: "A campaign has already been created for this request." });
      }

      // Resolve assigned recruiter
      const recruiter = await storage.getUser(recruiterId);
      if (!recruiter) return res.status(404).json({ message: "Recruiter not found" });

      // Map driver types to worker_type (use first for primary; all captured in title)
      const driverTypes: string[] = (request.driverTypes as string[]) || [];
      const hasCdl = driverTypes.includes("CDL");
      const workerType = "W2_DRIVER"; // All field driver types are W2 in this system
      const workType = driverTypes.includes("On-Demand") ? "ON_DEMAND" : "SHIFT";

      // Build descriptive title
      const campaignTypeLabel = ((request.campaignType || "").charAt(0).toUpperCase() + (request.campaignType || "").slice(1));
      const marketLabel = request.market || "N/A";
      const driverTypeLabel = driverTypes.join(" / ") || "Driver";
      const requisitionTitle = `${campaignTypeLabel} — ${driverTypeLabel} | ${marketLabel}${request.dealershipName ? ` — ${request.dealershipName}` : ""}`;

      // Description from request
      const descriptionParts: string[] = [];
      if (request.dealershipName) descriptionParts.push(`Dealership: ${request.dealershipName}`);
      if (request.address) descriptionParts.push(`Address: ${request.address}`);
      if (request.phoneInterviewContact) descriptionParts.push(`Phone Interview Contact: ${request.phoneInterviewContact}`);
      if (request.certLiaison) descriptionParts.push(`Cert Liaison: ${request.certLiaison}`);
      if (request.additionalComments) descriptionParts.push(`\nNotes: ${request.additionalComments}`);
      if (notes?.trim()) descriptionParts.push(`\nCampaign Notes: ${notes.trim()}`);

      // Create the requisition
      const [created] = await db.insert(recruitingRequisitions).values({
        title:          requisitionTitle,
        description:    descriptionParts.join("\n") || null,
        workerType:     workerType as any,
        workType:       workType as any,
        market:         request.market || "Unknown",
        targetHires:    request.targetDriverCount || 1,
        compensationMin: request.payRate || null,
        compensationMax: request.payRate || null,
        compensationType: request.payRate ? "hourly" : null,
        recruiterId,
        status:         "open_active" as any,
        targetFillDate: request.targetDate || null,
        cdlRequired:    hasCdl,
        createdBy:      userId,
        updatedBy:      userId,
        sourceRequestId: id,
      } as any).returning();

      // Back-link on the request
      await db.update(recruitingRequests)
        .set({ campaignRequisitionId: created.id, updatedAt: new Date() })
        .where(eq(recruitingRequests.id, id));

      // Notify assigned recruiter
      try {
        const { sendEmail, isMicrosoftGraphConfigured } = await import("./services/microsoftGraphService");
        if (isMicrosoftGraphConfigured() || isRecruitingExternalDeliverySuppressed()) {
          const recruiterEmail = (recruiter as any).email;
          if (recruiterEmail) {
            const recruiterName = `${(recruiter as any).firstName || ""} ${(recruiter as any).lastName || ""}`.trim() || recruiterEmail;
            const assignerName = `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || userId;
            const signOnLine = (request as any).signOnBonus && (request as any).signOnBonusAmount
              ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Sign-On Bonus</td><td style="padding:6px 12px">$${Number((request as any).signOnBonusAmount).toFixed(2)}</td></tr>`
              : "";
            const bodyHtml = `
              <div style="font-family:Arial,sans-serif;max-width:600px">
                <h2 style="color:#FF6B35">New Recruiting Campaign Assigned</h2>
                <p>Hi <strong>${recruiterName}</strong>,</p>
                <p>You have been assigned a new recruiting campaign by <strong>${assignerName}</strong>. The campaign is now Open Active and requires your immediate attention.</p>
                <table style="width:100%;border-collapse:collapse;margin:16px 0">
                  <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5;width:40%">Campaign</td><td style="padding:6px 12px">${requisitionTitle}</td></tr>
                  <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Market</td><td style="padding:6px 12px">${marketLabel}</td></tr>
                  <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Driver Types</td><td style="padding:6px 12px">${driverTypeLabel}</td></tr>
                  <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Target Count</td><td style="padding:6px 12px">${request.targetDriverCount || "N/A"} drivers</td></tr>
                  ${request.payRate ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Pay Rate</td><td style="padding:6px 12px">$${Number(request.payRate).toFixed(2)}</td></tr>` : ""}
                  ${signOnLine}
                  ${request.targetDate ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Target Fill Date</td><td style="padding:6px 12px">${new Date(request.targetDate).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })}</td></tr>` : ""}
                  ${request.dealershipName ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Dealership</td><td style="padding:6px 12px">${request.dealershipName}</td></tr>` : ""}
                  ${request.address ? `<tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Location</td><td style="padding:6px 12px">${request.address}</td></tr>` : ""}
                  <tr><td style="padding:6px 12px;font-weight:bold;background:#f5f5f5">Status</td><td style="padding:6px 12px;color:#FF6B35;font-weight:bold">Open Active</td></tr>
                </table>
                <p>Log in to DriverHub 360 → Recruiting to view and begin working this campaign.</p>
                <p style="color:#888;font-size:12px">Campaign ID: ${created.id}</p>
              </div>`;
            await sendEmail({
              to: [recruiterEmail],
              subject: `New Campaign Assigned — ${requisitionTitle}`,
              bodyHtml,
              recruitingAudit: {
                actionType: "MANUAL_CAMPAIGN_ASSIGNMENT_ALERT_SUPPRESSED",
                entityType: "request",
                entityId: id,
                userId,
                userEmail: user?.email || null,
                actorRole: user?.role || null,
                trigger: "manual_campaign_assignment_alert",
              },
            });
          }
        }
      } catch (emailErr) {
        console.error("[Recruiting Campaign] Recruiter notification failed:", emailErr);
        // Non-fatal
      }

      res.status(201).json({ campaign: created });
    } catch (error: any) {
      console.error("[Recruiting Campaign] Create error:", error);
      res.status(500).json({ message: error.message || "Failed to create campaign" });
    }
  });

