  // Utility: populate template body from a requisition's data
  function populateJobAdTemplate(body: string, req: Record<string, any>): string {
    const driverTypes: string[] = Array.isArray(req.driverTypes) ? req.driverTypes : [];
    const payRate = req.compensationMin
      ? `$${Number(req.compensationMin).toFixed(2)}${req.compensationMax && Number(req.compensationMax) !== Number(req.compensationMin) ? ` – $${Number(req.compensationMax).toFixed(2)}` : ""}`
      : req.payRate
      ? `$${Number(req.payRate).toFixed(2)}`
      : "Competitive";
    const targetDate = req.targetFillDate
      ? new Date(req.targetFillDate).toLocaleDateString("en-US", { month: "long", day: "numeric", year: "numeric" })
      : "";
    const signOnBonus = req.signOnBonus && req.signOnBonusAmount
      ? `$${Number(req.signOnBonusAmount).toFixed(2)} Sign-On Bonus`
      : "";
    const schedule = req.workType === "ON_DEMAND" ? "On-Demand (flexible)" : "Shift-based";

    return body
      .replace(/\{\{pay_rate\}\}/g,                payRate)
      .replace(/\{\{location\}\}/g,                req.address || req.market || "")
      .replace(/\{\{market\}\}/g,                  req.market || "")
      .replace(/\{\{dealership\}\}/g,              req.dealershipName || "")
      .replace(/\{\{address\}\}/g,                 req.address || "")
      .replace(/\{\{driver_types\}\}/g,            driverTypes.join(", ") || "")
      .replace(/\{\{target_date\}\}/g,             targetDate)
      .replace(/\{\{target_count\}\}/g,            req.targetHires?.toString() || req.targetDriverCount?.toString() || "")
      .replace(/\{\{schedule\}\}/g,                schedule)
      .replace(/\{\{sign_on_bonus\}\}/g,           signOnBonus)
      .replace(/\{\{campaign_type\}\}/g,           req.campaignType || "")
      .replace(/\{\{phone_interview_contact\}\}/g, req.phoneInterviewContact || "");
  }

