  // PUT /api/recruiting/requisitions/:id/job-ad-draft — save (upsert) draft
  app.put("/api/recruiting/requisitions/:id/job-ad-draft", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !["admin","super_user","corporate_admin","manager","recruiter","recruiting_admin"].includes(user.role || "")) {
        return res.status(403).json({ message: "Recruiter access required" });
      }
      const { draftBody, templateId, status } = req.body;
      if (!draftBody?.trim()) return res.status(400).json({ message: "draftBody is required" });
      const { db } = await import("./db");
      const { jobAdDrafts } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");
      const requisitionId = req.params.id;
      const [existing] = await db.select().from(jobAdDrafts).where(eq(jobAdDrafts.requisitionId, requisitionId)).limit(1);
      const now = new Date();
      let result: any;
      if (existing) {
        const finalizing = status === "finalized" && existing.status !== "finalized";
        [result] = await db.update(jobAdDrafts).set({
          draftBody:   draftBody.trim(),
          templateId:  templateId || existing.templateId || null,
          status:      status || existing.status,
          updatedBy:   userId,
          updatedAt:   now,
          ...(finalizing ? { finalizedBy: userId, finalizedAt: now } : {}),
        }).where(eq(jobAdDrafts.id, existing.id)).returning();
      } else {
        [result] = await db.insert(jobAdDrafts).values({
          requisitionId,
          draftBody:  draftBody.trim(),
          templateId: templateId || null,
          status:     status || "draft",
          createdBy:  userId,
          updatedBy:  userId,
        } as any).returning();
      }
      res.json(result);
    } catch (error: any) {
      console.error("[JobAdDraft] PUT error:", error);
      res.status(500).json({ message: "Failed to save draft" });
    }
  });

  // POST /api/recruiting/job-ad-templates/preview-body — populate arbitrary body text with requisition data
  app.post("/api/recruiting/job-ad-templates/preview-body", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const { templateBody, requisitionId } = req.body;
      if (!templateBody) return res.status(400).json({ message: "templateBody is required" });
      let populated = templateBody;
      if (requisitionId) {
        const { db } = await import("./db");
        const { recruitingRequisitions } = await import("@shared/schema");
        const { eq } = await import("drizzle-orm");
        const [reqRow] = await db.select().from(recruitingRequisitions)
          .where(eq(recruitingRequisitions.id, requisitionId)).limit(1);
        if (reqRow) populated = populateJobAdTemplate(templateBody, reqRow as any);
      }
      res.json({ populated });
    } catch (error: any) {
      console.error("[JobAdTemplates] preview-body error:", error);
      res.status(500).json({ message: "Failed to preview" });
    }
  });

