  // PUT /api/recruiting/health/thresholds/:metricKey - Update threshold configuration (admin-only)
  app.put("/api/recruiting/health/thresholds/:metricKey", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const user = await storage.getUser(userId);
      if (!user || (user.role !== "admin" && user.role !== "super_user")) {
        return res.status(403).json({ message: "Admin access required" });
      }

      const { metricKey } = req.params;
      const { warningValue, criticalValue, lookbackDays, stalledDays, isEnabled } = req.body;

      const updates: any = { updatedBy: userId };
      if (warningValue !== undefined) updates.warningValue = String(warningValue);
      if (criticalValue !== undefined) updates.criticalValue = String(criticalValue);
      if (lookbackDays !== undefined) updates.lookbackDays = lookbackDays;
      if (stalledDays !== undefined) updates.stalledDays = stalledDays;
      if (isEnabled !== undefined) updates.isEnabled = isEnabled;

      const updated = await storage.updateRecruitingHealthThreshold(metricKey, updates);
      if (!updated) return res.status(404).json({ message: "Threshold not found" });

      res.json(updated);
    } catch (error: any) {
      console.error("[Recruiting Health] Error updating threshold:", error);
      res.status(500).json({ message: "Failed to update threshold" });
    }
  });


