  app.post("/api/recruiting/candidates/:candidateId/trainings", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const parsed = insertCandidateTrainingRecordSchema.omit({ candidateId: true }).safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ message: "Validation failed", errors: parsed.error.flatten().fieldErrors });
      }
      const user = await storage.getUser(userId);
      const { createCandidateTraining } = await import("./recruitingService");
      const record = await createCandidateTraining(req.params.candidateId, parsed.data, userId, user?.email || null);
      res.status(201).json(record);
    } catch (error: any) {
      if (error.message.includes("Invalid training type") || error.message.includes("required")) {
        return res.status(400).json({ message: error.message });
      }
      console.error("[Training] Error creating training:", error);
      res.status(500).json({ message: "Failed to create training record" });
    }
  });

