  app.get("/api/recruiting/recruiters", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !["admin", "super_user", "recruiting_admin"].includes(user.role || "")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { users, recruitingApplications, recruiterSkills, recruiterSkillTags, userRecruitingMarkets } = await import("@shared/schema");
      const { inArray, eq, isNull, and, sql } = await import("drizzle-orm");
      const recruiters = await db.select({
        id: users.id,
        email: users.email,
        firstName: users.firstName,
        lastName: users.lastName,
        role: users.role,
      }).from(users).where(inArray(users.role, ["recruiter", "recruiting_admin", "admin", "super_user"]));

      const recruiterIds = recruiters.map(r => r.id);
      if (recruiterIds.length === 0) return res.json([]);

      const workloadCounts = await db.select({
        ownerId: recruitingApplications.ownerId,
        count: sql<number>`count(*)::int`,
      }).from(recruitingApplications).where(and(
        inArray(recruitingApplications.ownerId, recruiterIds),
        isNull(recruitingApplications.disposition),
        eq(recruitingApplications.isArchived, false),
      )).groupBy(recruitingApplications.ownerId);
      const workloadMap = new Map(workloadCounts.map(w => [w.ownerId, w.count]));

      const allSkills = await db.select({
        userId: recruiterSkills.userId,
        tagName: recruiterSkillTags.name,
        tagCategory: recruiterSkillTags.category,
      }).from(recruiterSkills)
        .innerJoin(recruiterSkillTags, eq(recruiterSkills.skillTagId, recruiterSkillTags.id))
        .where(inArray(recruiterSkills.userId, recruiterIds));
      const skillsMap = new Map<string, { name: string; category: string | null }[]>();
      for (const s of allSkills) {
        const existing = skillsMap.get(s.userId) || [];
        existing.push({ name: s.tagName, category: s.tagCategory });
        skillsMap.set(s.userId, existing);
      }

      const allMarkets = await db.select({
        userId: userRecruitingMarkets.userId,
        market: userRecruitingMarkets.market,
      }).from(userRecruitingMarkets).where(inArray(userRecruitingMarkets.userId, recruiterIds));
      const marketsMap = new Map<string, string[]>();
      for (const m of allMarkets) {
        const existing = marketsMap.get(m.userId) || [];
        existing.push(m.market);
        marketsMap.set(m.userId, existing);
      }

      const result = recruiters.map(r => ({
        ...r,
        activeApplications: workloadMap.get(r.id) || 0,
        skills: skillsMap.get(r.id) || [],
        markets: marketsMap.get(r.id) || [],
      }));

      res.json(result);
    } catch (error: any) {
      console.error("[Recruiters] Error listing:", error);
      res.status(500).json({ message: "Failed to list recruiters" });
    }
  });

  app.post("/api/recruiting/applications/:id/reassign", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !["admin", "super_user", "recruiting_admin"].includes(user.role || "")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { recruitingApplications, recruitingAssignmentLogs } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");
      const { newOwnerId, reason } = req.body;
      if (!newOwnerId) return res.status(400).json({ message: "New owner ID is required" });

      const application = await db.query.recruitingApplications.findFirst({
        where: eq(recruitingApplications.id, req.params.id),
      });
      if (!application) return res.status(404).json({ message: "Application not found" });

      const newOwner = await storage.getUser(newOwnerId);
      if (!newOwner) return res.status(404).json({ message: "Target recruiter not found" });

      let previousOwnerEmail: string | null = null;
      if (application.ownerId) {
        const prevOwner = await storage.getUser(application.ownerId);
        previousOwnerEmail = prevOwner?.email || null;
      }

      await db.update(recruitingApplications)
        .set({ ownerId: newOwnerId, updatedAt: new Date(), updatedBy: userId })
        .where(eq(recruitingApplications.id, req.params.id));

      await db.insert(recruitingAssignmentLogs).values({
        applicationId: req.params.id,
        previousOwnerId: application.ownerId || null,
        newOwnerId,
        previousOwnerEmail,
        newOwnerEmail: newOwner.email || null,
        assignmentType: "manual",
        reason: reason || "Manual override",
        performedBy: userId,
        performedByEmail: user.email || null,
      });

      res.json({ success: true, message: `Application reassigned to ${newOwner.email}` });
    } catch (error: any) {
      console.error("[Assignment] Error reassigning:", error);
      res.status(500).json({ message: "Failed to reassign application" });
    }
  });


