  app.post("/api/recruiting/consent-expiration-rules", async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) {
        return res.status(401).json({ message: "Not authenticated" });
      }
      const user = await storage.getUser(userId);
      if (!user || (user.role !== "admin" && user.role !== "super_user")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { consentType, expirationDays, isActive } = req.body || {};
      if (!consentType || !expirationDays || typeof expirationDays !== "number" || expirationDays < 1) {
        return res.status(400).json({ message: "consentType and expirationDays (positive number) are required" });
      }
      const { createExpirationRule } = await import("./services/recruitingConsentExpirationService");
      const rule = await createExpirationRule({ consentType, expirationDays, isActive }, userId, user?.email || null);
      res.status(201).json(rule);
    } catch (error: any) {
      console.error("[Recruiting] Error creating consent expiration rule:", error);
      if (error.message?.includes("duplicate") || error.code === "23505") {
        return res.status(409).json({ message: "A rule for this consent type already exists" });
      }
      res.status(500).json({ message: "Failed to create consent expiration rule" });
    }
  });

