  // PUT /api/recruiting/sla-thresholds - Upsert SLA thresholds (admin only)
  app.put("/api/recruiting/sla-thresholds", async (req: any, res: Response) => {
    try {
      const userId = req.session?.userId || req.user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const userRecord = await db.select().from(users).where(eq(users.id, userId)).limit(1);
      if (!userRecord.length || !["super_admin", "admin"].includes(userRecord[0].role || "")) {
        return res.status(403).json({ message: "Admin access required" });
      }
      const { thresholds } = req.body;
      if (!Array.isArray(thresholds)) {
        return res.status(400).json({ message: "thresholds must be an array" });
      }
      const { recruitingSlaThresholds } = await import("@shared/schema");
      const results = [];
      for (const t of thresholds) {
        if (!t.stageKey || typeof t.thresholdHours !== "number") continue;
        const existing = await db.select().from(recruitingSlaThresholds).where(eq(recruitingSlaThresholds.stageKey, t.stageKey)).limit(1);
        if (existing.length > 0) {
          const [updated] = await db.update(recruitingSlaThresholds)
            .set({ thresholdHours: t.thresholdHours, isEnabled: t.isEnabled !== false, updatedAt: new Date(), updatedBy: userId })
            .where(eq(recruitingSlaThresholds.stageKey, t.stageKey))
            .returning();
          results.push(updated);
        } else {
          const [created] = await db.insert(recruitingSlaThresholds)
            .values({ stageKey: t.stageKey, thresholdHours: t.thresholdHours, isEnabled: t.isEnabled !== false, updatedBy: userId })
            .returning();
          results.push(created);
        }
      }
      res.json(results);
    } catch (error: any) {
      console.error("[SLA Thresholds] Error updating:", error);
      res.status(500).json({ message: "Failed to update SLA thresholds" });
    }
  });

