  // GET /api/recruiting/applications/:id/phone-screens
  app.get("/api/recruiting/applications/:id/phone-screens", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const { id } = req.params;
      const rows = await pool.query(
        `SELECT ps.*, u.email AS conducted_by_email
         FROM recruiting_phone_screens ps
         LEFT JOIN users u ON u.id = ps.conducted_by
         WHERE ps.application_id = $1
         ORDER BY ps.conducted_at DESC`,
        [id]
      );
      res.json(rows.rows);
    } catch (err: any) {
      console.error("[PhoneScreens] GET error:", err);
      res.status(500).json({ message: "Failed to fetch phone screens" });
    }
  });

  // POST /api/recruiting/applications/:id/phone-screens
  app.post("/api/recruiting/applications/:id/phone-screens", isAuthenticated, async (req: Request, res: Response) => {
    try {
      const userId = (req as any).session?.userId || (req as any).user?.claims?.sub;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const { id: applicationId } = req.params;
      const {
        qDrivingExperience,
        qAvailability,
        qVehicleComfort,
        qScheduleFlexibility,
        result,
        notes,
      } = req.body as Record<string, string>;

      if (!["proceed", "hold", "reject"].includes(result)) {
        return res.status(400).json({ message: "result must be proceed, hold, or reject" });
      }

      // Resolve recruiter name for denormalization
      const userRow = await pool.query("SELECT email, first_name, last_name FROM users WHERE id = $1", [userId]);
      const userRec = userRow.rows[0];
      const conductedByName = userRec
        ? `${userRec.first_name || ""} ${userRec.last_name || ""}`.trim() || userRec.email
        : null;

      // Verify application exists
      const appRow = await pool.query("SELECT id, current_stage, disposition FROM recruiting_applications WHERE id = $1", [applicationId]);
      if (!appRow.rows[0]) return res.status(404).json({ message: "Application not found" });

      const currentStage = appRow.rows[0].current_stage;

      // Insert phone screen
      const psRow = await pool.query(
        `INSERT INTO recruiting_phone_screens
           (application_id, conducted_by, conducted_by_name,
            q_driving_experience, q_availability, q_vehicle_comfort, q_schedule_flexibility,
            result, notes)
         VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)
         RETURNING *`,
        [
          applicationId, userId, conductedByName,
          qDrivingExperience || null, qAvailability || null,
          qVehicleComfort || null, qScheduleFlexibility || null,
          result, notes || null,
        ]
      );
      const newScreen = psRow.rows[0];

      // ── Apply application status changes based on result ──
      const STAGE_ORDER = ["applied", "phone_screen", "screening", "interview", "docs_pending", "background_pending", "approved", "ready_to_work"];
      const currentIdx = STAGE_ORDER.indexOf(currentStage);

      if (result === "proceed") {
        // Advance to phone_screen stage if currently at applied; to interview if at phone_screen
        let targetStage: string | null = null;
        if (currentStage === "applied") targetStage = "phone_screen";
        else if (currentStage === "phone_screen") targetStage = "interview";

        if (targetStage) {
          const timeInStageMs = Date.now() - new Date(appRow.rows[0].current_stage_entered_at || Date.now()).getTime();
          const timeInStageMins = Math.round(timeInStageMs / 60000);

          // Insert stage history
          await pool.query(
            `INSERT INTO recruiting_stage_history (application_id, from_stage, to_stage, transitioned_by, reason, source_action, time_in_previous_stage_minutes)
             VALUES ($1,$2,$3,$4,$5,'manual',$6)`,
            [applicationId, currentStage, targetStage, userId, `Phone screen passed — proceeding to ${targetStage.replace("_", " ")}`, timeInStageMins]
          );

          await pool.query(
            `UPDATE recruiting_applications SET current_stage=$1, current_stage_entered_at=NOW(), updated_at=NOW(), updated_by=$2 WHERE id=$3`,
            [targetStage, userId, applicationId]
          );
        }
      } else if (result === "reject") {
        // Set disposition to rejected
        await pool.query(
          `UPDATE recruiting_applications SET disposition='rejected', disposed_at=NOW(), disposed_by=$1, disposition_reason=$2, updated_at=NOW(), updated_by=$1 WHERE id=$3`,
          [userId, notes ? `Phone screen reject: ${notes}` : "Phone screen: rejected", applicationId]
        );
      }
      // hold: no stage change

      // ── Append audit event ──
      const resultLabel = result === "proceed" ? "Proceed to Interview" : result === "hold" ? "Hold" : "Reject";
      await pool.query(
        `INSERT INTO recruiting_audit_events (action_type, entity_type, entity_id, user_id, user_email, source, reason)
         VALUES ('phone_screen_logged','application',$1,$2,$3,'ui',$4)`,
        [applicationId, userId, userRec?.email || null, `Phone screen logged — result: ${resultLabel}`]
      );

      res.status(201).json(newScreen);
    } catch (err: any) {
      console.error("[PhoneScreens] POST error:", err);
      res.status(500).json({ message: "Failed to log phone screen" });
    }
  });

