  // External insurer read-only access (token-based)
  app.get("/api/external/scheduling/insurance-report", async (req: any, res: Response) => {
    try {
      const token = req.query.token as string;
      if (!token) return res.status(401).json({ message: "Access token required" });
      
      const { db } = await import("./db");
      const { externalAccessGrants, externalAccessLogs } = await import("@shared/schema");
      const { eq } = await import("drizzle-orm");
      
      const [grant] = await db.select().from(externalAccessGrants).where(eq(externalAccessGrants.accessToken, token));
      if (!grant || !grant.isActive) return res.status(403).json({ message: "Invalid or expired access" });
      if (new Date(grant.expiresAt) < new Date()) return res.status(403).json({ message: "Access token expired" });
      if (!grant.allowedScopes.includes("scheduling_insurance")) {
        return res.status(403).json({ message: "Scope not authorized for scheduling insurance reports" });
      }
      
      const { periodType = "monthly", periodStart } = req.query as any;
      if (!periodStart) return res.status(400).json({ message: "periodStart is required (YYYY-MM-DD)" });
      
      const { generateFullInsuranceReport } = await import("./services/schedulingInsuranceService");
      const report = await generateFullInsuranceReport(null, periodType, periodStart);
      
      await db.insert(externalAccessLogs).values({
        grantId: grant.id,
        accessedResource: "scheduling_insurance",
        resourceScope: `${periodType}:${periodStart}`,
        requestMethod: "GET",
        requestPath: "/api/external/scheduling/insurance-report",
        ipAddress: req.ip || null,
        userAgent: req.headers["user-agent"] || null,
        responseStatus: 200,
      });
      
      res.json(report);
    } catch (error: any) {
      console.error("[External Insurance] Error:", error);
      res.status(500).json({ message: "Failed to generate report" });
    }
  });


