  app.get("/api/corporate/scheduling/sla-performance", isAuthenticated, async (req: any, res: Response) => {
    try {
      const user = await storage.getUser(req.user.claims.sub);
      if (!hasCorporateAccess(user?.role)) {
        return res.status(403).json({ message: "Forbidden: Corporate access only" });
      }
      const startDate = req.query.startDate as string || new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
      const endDate = req.query.endDate as string || new Date().toISOString().split('T')[0];
      const events = await storage.getSchedulingSlaEvents({ startDate, endDate });
      const defs = await storage.getSchedulingSlaDefinitions();

      const totalEvents = events.length;
      const metCount = events.filter(e => e.status === 'met').length;
      const warningCount = events.filter(e => e.status === 'warning').length;
      const breachedCount = events.filter(e => e.status === 'breached').length;
      const pendingCount = events.filter(e => e.status === 'pending').length;
      const complianceRate = totalEvents > 0 ? ((metCount / totalEvents) * 100).toFixed(1) : '100.0';

      const byDefinition = defs.map(def => {
        const defEvents = events.filter(e => e.slaDefinitionId === def.id);
        const defMet = defEvents.filter(e => e.status === 'met').length;
        const defBreached = defEvents.filter(e => e.status === 'breached').length;
        return {
          definitionId: def.id,
          name: def.name,
          metricType: def.metricType,
          totalEvents: defEvents.length,
          met: defMet,
          breached: defBreached,
          complianceRate: defEvents.length > 0 ? ((defMet / defEvents.length) * 100).toFixed(1) : '100.0',
        };
      });

      res.json({
        period: { startDate, endDate },
        summary: { totalEvents, met: metCount, warning: warningCount, breached: breachedCount, pending: pendingCount, complianceRate },
        byDefinition,
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Failed to get SLA performance" });
    }
  });


