  app.get("/api/corporate/scheduling/mobility-summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const startDate = req.query.startDate as string || new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];
      const endDate = req.query.endDate as string || new Date().toISOString().split('T')[0];
      const logs = await storage.getCrossLocationTravelLogs({ startDate, endDate });

      const totalTrips = logs.length;
      const highRiskTrips = logs.filter(l => l.riskLevel === 'high').length;
      const warningTrips = logs.filter(l => l.riskLevel === 'warning').length;
      const avgDistance = totalTrips > 0
        ? (logs.reduce((sum, l) => sum + parseFloat(l.travelDistanceMiles || '0'), 0) / totalTrips).toFixed(1)
        : '0';
      const avgTravelTime = totalTrips > 0
        ? Math.round(logs.reduce((sum, l) => sum + (l.travelTimeMinutes || 0), 0) / totalTrips)
        : 0;

      const uniqueDrivers = new Set(logs.map(l => l.driverId || l.userId).filter(Boolean));

      res.json({
        period: { startDate, endDate },
        summary: {
          totalTrips,
          highRiskTrips,
          warningTrips,
          safeTrips: totalTrips - highRiskTrips - warningTrips,
          avgDistanceMiles: avgDistance,
          avgTravelTimeMinutes: avgTravelTime,
          uniqueDrivers: uniqueDrivers.size,
        },
      });
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Failed to get mobility summary" });
    }
  });


