  app.post("/api/corporate/scheduling/justifications", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { category, narrative, scheduleId, shiftId, driverId, entityId, metadata } = req.body;
      if (!category || !narrative) {
        return res.status(400).json({ message: "Category and narrative are required" });
      }
      if (!["ot_override", "break_exception", "incident_mode"].includes(category)) {
        return res.status(400).json({ message: "Invalid category. Must be ot_override, break_exception, or incident_mode" });
      }
      if (narrative.trim().length < 10) {
        return res.status(400).json({ message: "Narrative must be at least 10 characters" });
      }
      const authId = req.user?.claims?.sub;
      if (!authId) return res.status(401).json({ message: "Not authenticated" });
      let dbUser = await storage.getUser(authId);
      if (!dbUser && req.user?.claims?.email) {
        dbUser = await storage.getUserByEmail(req.user.claims.email);
      }
      const actualUserId = dbUser?.id || authId;
      const userName = dbUser?.firstName && dbUser?.lastName
        ? `${dbUser.firstName} ${dbUser.lastName}`
        : dbUser?.email || req.user?.claims?.email || "Unknown";
      const justification = await storage.createSchedulingJustification({
        category,
        narrative: narrative.trim(),
        scheduleId: scheduleId || null,
        shiftId: shiftId || null,
        driverId: driverId || null,
        entityId: entityId || null,
        createdById: actualUserId,
        createdByName: userName,
        metadata: metadata || null,
      });
      res.status(201).json(justification);
    } catch (error: any) {
      res.status(500).json({ message: error.message || "Failed to create justification" });
    }
  });


