  app.post("/api/scheduling/wiw/seed-sample", isAuthenticated, async (req: any, res: Response) => {
    try {
      if (process.env.NODE_ENV === "production") {
        return res.status(403).json({ message: "Sample data import is not available in production" });
      }
      const authId = req.user?.claims?.sub;
      if (!authId) return res.status(401).json({ message: "Not authenticated" });
      let dbUser = await storage.getUser(authId);
      if (!dbUser && req.user?.claims?.email) {
        dbUser = await storage.getUserByEmail(req.user.claims.email);
      }
      if (!dbUser || dbUser.role !== "admin") return res.status(403).json({ message: "Admin access required" });
      const userId = dbUser.id;

      const { processScheduleImport, processAttendanceImport, reconcileTimePunchesToShifts } = await import("./services/wiwIngestion");
      const { generateSampleScheduleBuffer } = await import("./fixtures/generateSampleSchedule");
      const fs = await import("fs");
      const path = await import("path");

      const steps: any[] = [];

      const scheduleBuffer = generateSampleScheduleBuffer();
      const scheduleResult = await processScheduleImport(scheduleBuffer, "sample_schedule.xlsx", userId);
      steps.push({ step: "schedule_import", ...scheduleResult });

      const att1Path = path.resolve(process.cwd(), "server/fixtures/wiw_sample_attendance_week1.csv");
      const att1Buffer = fs.readFileSync(att1Path);
      const att1Result = await processAttendanceImport(att1Buffer, "sample_attendance_week1.csv", userId);
      steps.push({ step: "attendance_week1_import", ...att1Result });

      const att2Path = path.resolve(process.cwd(), "server/fixtures/wiw_sample_attendance_week2.csv");
      const att2Buffer = fs.readFileSync(att2Path);
      const att2Result = await processAttendanceImport(att2Buffer, "sample_attendance_week2.csv", userId);
      steps.push({ step: "attendance_week2_import", ...att2Result });

      const reconcileResult = await reconcileTimePunchesToShifts({
        dateFrom: "2025-01-06",
        dateTo: "2025-01-17",
      });
      steps.push({ step: "reconciliation", ...reconcileResult });

      res.json({
        success: true,
        message: "Sample When I Work data imported and reconciled successfully",
        steps,
      });
    } catch (error: any) {
      console.error("[WIW] Sample data seed error:", error);
      res.status(500).json({ message: error.message || "Failed to import sample data" });
    }
  });

