      if (name !== undefined)        upd.name        = name.trim();
      if (description !== undefined) upd.description = description || null;
      if (targetDate !== undefined)  upd.targetDate  = targetDate || null;
      if (status !== undefined)      upd.status      = status;
      if (ownerUserId !== undefined) upd.ownerUserId = ownerUserId || null;
      const [row] = await db.update(productMilestones).set(upd).where(eq(productMilestones.id, req.params.id)).returning();
      if (!row) return res.status(404).json({ message: 'Milestone not found' });
