      const [row] = await db.insert(milestoneDeliverables).values({
        milestoneId: req.params.milestoneId,
        name: name.trim(), targetDate: targetDate || null,
        status: status || 'not_started', notes: notes || null,
        epicId: epicId || null, sortOrder: nextSort,
        createdByUserId: userId,
      }).returning();
      res.status(201).json(row);
