      if (status !== undefined)        upd.status        = status;
      if (notes !== undefined)         upd.notes         = notes || null;
      if (epicId !== undefined)        upd.epicId        = epicId || null;
      if (sortOrder !== undefined)     upd.sortOrder     = sortOrder;
