  /**
   * AMR records reference persistent DriverHub user IDs, not external OIDC
   * subjects. Resolve the current session through its stored DriverHub ID, then
   * its explicitly linked OIDC subject, then its verified email. This keeps
   * imported/invited users connected to historical AMRs without name matching.
   */
  async function resolveAmrActor(req: any) {
    const sessionUserId = (req.session as any)?.userId;
    const driverHubUserId = req.user?.driverHubUserId || (req.session as any)?.driverHubUserId;
    if (driverHubUserId) {
      const user = await storage.getUser(driverHubUserId);
      if (user) return { userId: user.id, user };
    }

    const subject = req.user?.claims?.sub || (req.session as any)?.userId;
    const claimEmail = typeof req.user?.claims?.email === "string"
      ? req.user.claims.email.trim()
      : "";

    if (subject) {
      const [ssoMatch] = await db.select()
        .from(users)
        .where(eq(users.ssoSubjectId, subject))
        .limit(1);
      if (ssoMatch) return { userId: ssoMatch.id, user: ssoMatch };
    }

    if (claimEmail) {
      const [emailMatch] = await db.select()
        .from(users)
        .where(ilike(users.email, claimEmail))
        .limit(1);
      if (emailMatch) return { userId: emailMatch.id, user: emailMatch };
    }

    if (subject) {
      const user = await storage.getUser(subject);
      return { userId: user?.id || subject, user: user || null };
    }

    if (sessionUserId) {
      const user = await storage.getUser(sessionUserId);
      return { userId: user?.id || sessionUserId, user: user || null };
    }

    return { userId: null, user: null };
  }

  /**
   * AMR visibility is shared by the detail page and its collaboration actions.
   * The persistent DriverHub ID is the only ID compared to AMR relationships.
   */
  const getAmrAccess = async (ticket: any, userId: string, user: any) => {
    const admin = isTicketAdmin(user?.role);
    const isSubmitter = ticket.submittedByUserId === userId;
    const [ccRows, testerRows] = await Promise.all([
      db.select({ id: ticketCcUsers.id })
        .from(ticketCcUsers)
        .where(and(eq(ticketCcUsers.ticketId, ticket.id), eq(ticketCcUsers.userId, userId)))
        .limit(1),
      db.select({ id: ticketTesters.id })
        .from(ticketTesters)
        .where(and(eq(ticketTesters.ticketId, ticket.id), eq(ticketTesters.userId, userId)))
        .limit(1),
    ]);
    const isCcUser = ccRows.length > 0;
    const isTester = testerRows.length > 0;
    return {
      admin,
      isSubmitter,
      isCcUser,
      isTester,
      canAccess: admin || isSubmitter || isCcUser || isTester,
    };
  };

  app.get("/api/tickets/amr-metrics", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { userId } = await resolveAmrActor(req);
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      // mine=true → scope counts to: submitter OR CC'd OR assigned tester
      // mine=false (default) → enterprise-wide counts
      const mine = req.query.mine === 'true';

      const mineScope = mine ? or(
        eq(tickets.submittedByUserId, userId),
        sql`${tickets.id} IN (SELECT ticket_id FROM ticket_cc_users WHERE user_id = ${userId})`,
        sql`EXISTS (SELECT 1 FROM ticket_testers tt WHERE tt.ticket_id = ${tickets.id} AND tt.user_id = ${userId})`
      ) : undefined;

      // Builds a WHERE clause combining scope (when mine) + metric-specific conditions
      const s = (...extra: any[]): any => {
        const parts: any[] = [...(mineScope ? [mineScope] : []), ...extra];
        if (parts.length === 0) return undefined;
        return parts.length === 1 ? parts[0] : and(...parts);
      };

      const notDup = sql`${tickets.status}::text != 'duplicate'`;
      const activeOnly = sql`${tickets.status}::text NOT IN ('completed','cancelled','user_accepts','user_declines','complete','duplicate')`;

      // Primary workflow/planning and priority metrics — all scope-aware
      const [submitted, needMoreInfo, prioritizing, roadmap, inDev, needsTesting, userDeclines, completed,
             p0, p1, p2, p3, p4] = await Promise.all([
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'submitted'`)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'sent_back_for_info'`)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'prioritizing'`, notDup)),
        // Roadmapped is a Planning Status — never workflow status
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.planningStatus}::text = 'roadmapped'`, notDup)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text IN ('in_development','in_production')`, notDup)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'needs_testing'`)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'user_declines'`)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`${tickets.status}::text = 'completed'`)),
        // Priority counts: active (non-terminal, non-duplicate) AMRs within scope
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`UPPER(${tickets.priority}::text) = 'P0'`, activeOnly)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`UPPER(${tickets.priority}::text) = 'P1'`, activeOnly)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`UPPER(${tickets.priority}::text) = 'P2'`, activeOnly)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`UPPER(${tickets.priority}::text) = 'P3'`, activeOnly)),
        db.select({ c: sql<number>`count(distinct ${tickets.id})::int` }).from(tickets).where(s(sql`UPPER(${tickets.priority}::text) = 'P4'`, activeOnly)),
      ]);

      // Planning/Roadmap Dashboard counts — always enterprise-wide (Roadmap Dashboard reads these)
      const TERMINAL = `status::text NOT IN ('completed','cancelled','user_accepts','user_declines','complete','duplicate')`;
      const [planningBacklog, planningRoadmapped, planningUnscheduled, planningScheduled,
             planningStartingSoon, planningDeployDueSoon, planningAtRisk, planningOverdue, planningCompletedRoadmap,
             dueTodayAll, dueTodayRoadmap, dueThisWeekAll, dueThisWeekRoadmap] = await Promise.all([
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`planning_status::text = 'backlog' AND status::text != 'duplicate'`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`planning_status::text = 'roadmapped' AND status::text != 'duplicate'`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`planning_status::text = 'unscheduled' AND status::text != 'duplicate'`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`planning_status::text = 'scheduled' AND status::text != 'duplicate'`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`
          scheduled_development_date IS NOT NULL
          AND scheduled_development_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '7 days'
          AND ${sql.raw(TERMINAL)} AND status::text != 'in_development'`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`
          scheduled_deployment_date IS NOT NULL
          AND scheduled_deployment_date BETWEEN CURRENT_DATE AND CURRENT_DATE + INTERVAL '7 days'
          AND ${sql.raw(TERMINAL)}`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`
          scheduled_development_date IS NOT NULL
          AND scheduled_development_date < CURRENT_DATE
          AND status::text NOT IN ('in_development','in_production','needs_testing','completed','user_accepts','cancelled','duplicate','complete')`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`
          scheduled_deployment_date IS NOT NULL
          AND scheduled_deployment_date < CURRENT_DATE
          AND ${sql.raw(TERMINAL)}`),
        db.select({ c: sql<number>`count(*)::int` }).from(tickets).where(sql`
          status::text = 'completed' AND planning_status IS NOT NULL`),
        // Due Today — All: active AMRs where dev OR deploy date = today (deduplicated by OR)
        db.select({ c: sql<number>`count(DISTINCT id)::int` }).from(tickets).where(sql`
          ${sql.raw(TERMINAL)}
          AND (scheduled_development_date = CURRENT_DATE OR scheduled_deployment_date = CURRENT_DATE)`),
        // Due Today — Roadmap only
        db.select({ c: sql<number>`count(DISTINCT id)::int` }).from(tickets).where(sql`
          ${sql.raw(TERMINAL)} AND planning_status::text = 'roadmapped'
          AND (scheduled_development_date = CURRENT_DATE OR scheduled_deployment_date = CURRENT_DATE)`),
        // Due This Week — All: today through end of current week (Sunday, Mon-Sun definition).
        // TODAY is intentionally included so Due This Week is a superset of Due Today.
        db.select({ c: sql<number>`count(DISTINCT id)::int` }).from(tickets).where(sql`
          ${sql.raw(TERMINAL)}
          AND (
            (scheduled_development_date >= CURRENT_DATE AND scheduled_development_date <= date_trunc('week', CURRENT_DATE) + INTERVAL '6 days')
            OR
            (scheduled_deployment_date >= CURRENT_DATE AND scheduled_deployment_date <= date_trunc('week', CURRENT_DATE) + INTERVAL '6 days')
          )`),
        // Due This Week — Roadmap only
        db.select({ c: sql<number>`count(DISTINCT id)::int` }).from(tickets).where(sql`
          ${sql.raw(TERMINAL)} AND planning_status::text = 'roadmapped'
          AND (
            (scheduled_development_date >= CURRENT_DATE AND scheduled_development_date <= date_trunc('week', CURRENT_DATE) + INTERVAL '6 days')
            OR
            (scheduled_deployment_date >= CURRENT_DATE AND scheduled_deployment_date <= date_trunc('week', CURRENT_DATE) + INTERVAL '6 days')
          )`),
      ]);

      return res.json({
        // Primary workflow/planning metrics (scope-aware via mine param)
        submitted:      submitted[0]?.c ?? 0,
        needMoreInfo:   needMoreInfo[0]?.c ?? 0,
        prioritizing:   prioritizing[0]?.c ?? 0,
        roadmap:        roadmap[0]?.c ?? 0,
        inDevelopment:  inDev[0]?.c ?? 0,
        needsTesting:   needsTesting[0]?.c ?? 0,
        userDeclines:   userDeclines[0]?.c ?? 0,
        completedTotal: completed[0]?.c ?? 0,
        // Priority counts (scope-aware, active AMRs only)
        p0: p0[0]?.c ?? 0,
        p1: p1[0]?.c ?? 0,
        p2: p2[0]?.c ?? 0,
        p3: p3[0]?.c ?? 0,
        p4: p4[0]?.c ?? 0,
        // Legacy aliases kept for backward compat
        needsReview: submitted[0]?.c ?? 0,
        reviewed:    0,
        blocked:     needMoreInfo[0]?.c ?? 0,
        inQueue:     0,
        aging:       0,
        thirtyPlusDays: 0,
        recentCompleted: 0,
        productDecisionRequired: 0,
        distribution:  [],
        moduleActivity: [],
        copiedOn:    0,
        newUpdates:  0,
        isPersonalized: mine,
        // Planning/Roadmap Dashboard counts (always enterprise-wide)
        planningBacklog:          planningBacklog[0]?.c ?? 0,
        planningRoadmapped:       planningRoadmapped[0]?.c ?? 0,
        planningUnscheduled:      planningUnscheduled[0]?.c ?? 0,
        planningScheduled:        planningScheduled[0]?.c ?? 0,
        planningStartingSoon:     planningStartingSoon[0]?.c ?? 0,
        planningDeployDueSoon:    planningDeployDueSoon[0]?.c ?? 0,
        planningAtRisk:           planningAtRisk[0]?.c ?? 0,
        planningOverdue:          planningOverdue[0]?.c ?? 0,
        planningCompletedRoadmap: planningCompletedRoadmap[0]?.c ?? 0,
        dueTodayAll:              dueTodayAll[0]?.c ?? 0,
        dueTodayRoadmap:          dueTodayRoadmap[0]?.c ?? 0,
        dueThisWeekAll:           dueThisWeekAll[0]?.c ?? 0,
        dueThisWeekRoadmap:       dueThisWeekRoadmap[0]?.c ?? 0,
      });
    } catch (error) {
      console.error("Error fetching AMR metrics:", error);
      res.status(500).json({ message: "Failed to fetch AMR metrics" });
    }
  });

