  app.get("/api/tickets/contribution-metrics", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { user: requestingUser } = await resolveAmrActor(req);
      if (!requestingUser || !["super_user", "admin", "ops_manager", "corporate_admin"].includes(requestingUser.role || "")) {
        return res.status(403).json({ message: "Forbidden" });
      }

      const { dateFrom, dateTo, role } = req.query as Record<string, string | undefined>;

      const dateFromClause = dateFrom ? sql` AND t.submitted_at >= ${new Date(dateFrom)}` : sql``;
      const dateToClause = dateTo ? sql` AND t.submitted_at <= ${new Date(dateTo + "T23:59:59")}` : sql``;
      const roleClause = role ? sql` AND u.role = ${role}` : sql``;

      // Duplicate AMRs are excluded from all contribution metrics per policy
      const result = await db.execute(sql`
        SELECT
          u.id,
          TRIM(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) AS name,
          u.email,
          u.role,
          COUNT(t.id)::int AS ideas_submitted,
          COUNT(CASE WHEN t.status::text = 'completed' THEN 1 END)::int AS ideas_implemented,
          COUNT(CASE WHEN t.type::text IN ('enhancement', 'feature_request') AND t.status::text = 'completed' THEN 1 END)::int AS enhancements_accepted,
          CASE
            WHEN COUNT(t.id) = 0 THEN 0
            ELSE ROUND(COUNT(CASE WHEN t.status::text = 'completed' THEN 1 END)::numeric / COUNT(t.id) * 100, 0)::int
          END AS implementation_rate,
          ROUND(AVG(
            CASE WHEN t.status::text IN ('completed', 'user_accepts') AND t.completed_at IS NOT NULL THEN
              EXTRACT(EPOCH FROM (t.completed_at - t.submitted_at)) / 86400.0
            END
          )::numeric, 1) AS avg_completion_days
        FROM users u
        INNER JOIN tickets t ON t.submitted_by_user_id = u.id
          AND t.submitted_by_user_id IS NOT NULL
          AND t.status::text != 'duplicate'
          ${dateFromClause}
          ${dateToClause}
        WHERE 1=1
          ${roleClause}
        GROUP BY u.id, u.first_name, u.last_name, u.email, u.role
        ORDER BY ideas_submitted DESC
      `);

      const rows = (result.rows as any[]).map((r) => ({
        id: r.id,
        name: r.name || "",
        email: r.email || null,
        role: r.role || "",
        ideasSubmitted: Number(r.ideas_submitted) || 0,
        ideasImplemented: Number(r.ideas_implemented) || 0,
        enhancementsAccepted: Number(r.enhancements_accepted) || 0,
        implementationRate: Number(r.implementation_rate) || 0,
        avgCompletionDays: r.avg_completion_days != null ? Number(r.avg_completion_days) : null,
      }));

      res.json(rows);
    } catch (error) {
      console.error("Error fetching contribution metrics:", error);
      res.status(500).json({ message: "Failed to fetch contribution metrics" });
    }
  });

  // ── Team Activity: per-user AMR stats for the Executive Dashboard widget ──
  // Admins + Will Walton see all users; standard users see only their own row.
  app.get("/api/tickets/team-activity", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const requestingUser = await storage.getUser(userId);
      if (!requestingUser) return res.status(401).json({ message: "Not authenticated" });

      const AMR_ADMIN_ROLES = ["super_user", "admin", "ops_manager", "corporate_admin"];
      const WILL_WALTON_ID  = "0a520043-f7eb-4944-aefe-9a85de761950";
      const canSeeAll = AMR_ADMIN_ROLES.includes(requestingUser.role || "") || userId === WILL_WALTON_ID;

      const { period, dateFrom, dateTo } = req.query as Record<string, string | undefined>;

      // Resolve date window from period preset
      const now = new Date();
      let start: Date | null = null;
      let end:   Date | null = null;

      switch (period) {
        case "today":
          start = new Date(now.getFullYear(), now.getMonth(), now.getDate());
          end   = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
          break;
        case "this_week": {
          const dow        = now.getDay(); // 0=Sun … 6=Sat
          const toMonday   = dow === 0 ? 6 : dow - 1;
          start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - toMonday);
          end   = new Date(start.getTime() + 6 * 24 * 60 * 60 * 1000);
          end.setHours(23, 59, 59, 999);
          break;
        }
        case "this_month":
          start = new Date(now.getFullYear(), now.getMonth(), 1);
          end   = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
          break;
        case "this_year":
          start = new Date(now.getFullYear(), 0, 1);
          end   = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
          break;
        case "custom":
          if (dateFrom) start = new Date(dateFrom);
          if (dateTo)   end   = new Date(dateTo + "T23:59:59");
          break;
        // "all_time" / undefined: no date filter
      }

      const startClause = start ? sql` AND t.submitted_at >= ${start}` : sql``;
      const endClause   = end   ? sql` AND t.submitted_at <= ${end}`   : sql``;
      // Non-admins see only their own row
      const userClause  = canSeeAll ? sql`` : sql` AND u.id = ${userId}`;

      const result = await db.execute(sql`
        SELECT
          u.id,
          TRIM(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) AS name,
          u.role,
          COUNT(t.id)::int                                                                               AS ideas_submitted,
          COUNT(CASE WHEN t.status::text = 'completed'    THEN 1 END)::int                             AS ideas_implemented,
          COUNT(CASE WHEN t.status::text = 'user_accepts' THEN 1 END)::int                             AS user_accepts,
          COUNT(CASE WHEN t.status::text = 'user_declines' THEN 1 END)::int                            AS returned_for_rework,
          CASE
            WHEN COUNT(t.id) = 0 THEN 0
            ELSE ROUND(
              COUNT(CASE WHEN t.status::text = 'completed' THEN 1 END)::numeric / COUNT(t.id) * 100, 0
            )::int
          END                                                                                           AS implementation_pct,
          ROUND(AVG(
            CASE
              WHEN t.status::text IN ('completed', 'user_accepts') AND t.completed_at IS NOT NULL THEN
                EXTRACT(EPOCH FROM (t.completed_at - t.submitted_at)) / 86400.0
            END
          )::numeric, 1)                                                                                AS avg_completion_days
        FROM users u
        INNER JOIN tickets t
          ON  t.submitted_by_user_id = u.id
          AND t.status::text != 'duplicate'
          ${startClause}
          ${endClause}
        WHERE 1=1
          ${userClause}
        GROUP BY u.id, u.first_name, u.last_name, u.role
        HAVING COUNT(t.id) > 0
        ORDER BY ideas_submitted DESC
      `);

      const rows = (result.rows as any[]).map((r) => ({
        id:                  r.id,
        name:                r.name || "",
        role:                r.role || "",
        ideasSubmitted:      Number(r.ideas_submitted)      || 0,
        ideasImplemented:    Number(r.ideas_implemented)    || 0,
        userAccepts:         Number(r.user_accepts)         || 0,
        returnedForRework:   Number(r.returned_for_rework)  || 0,
        implementationPct:   Number(r.implementation_pct)   || 0,
        avgCompletionDays:   r.avg_completion_days != null ? Number(r.avg_completion_days) : null,
      }));

      res.json({ rows, canSeeAll });
    } catch (error) {
      console.error("Error fetching team activity:", error);
      res.status(500).json({ message: "Failed to fetch team activity" });
    }
  });

  // ── Achievement Badges: period winners for Recognition system ────────────
  app.get("/api/tickets/achievement-badges", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const requestingUser = await storage.getUser(userId);
      if (!requestingUser) return res.status(401).json({ message: "Not authenticated" });

      const AMR_ADMIN_ROLES = ["super_user", "admin", "ops_manager", "corporate_admin"];
      const WILL_WALTON_ID  = "0a520043-f7eb-4944-aefe-9a85de761950";
      const canSeeAll = AMR_ADMIN_ROLES.includes(requestingUser.role || "") || userId === WILL_WALTON_ID;

      const { period } = req.query as Record<string, string | undefined>;

      // Resolve calendar-aligned date window
      const now = new Date();
      let start: Date | null = null;
      switch (period) {
        case "monthly":
          start = new Date(now.getFullYear(), now.getMonth(), 1);
          break;
        case "quarterly": {
          const q = Math.floor(now.getMonth() / 3);
          start = new Date(now.getFullYear(), q * 3, 1);
          break;
        }
        case "yearly":
          start = new Date(now.getFullYear(), 0, 1);
          break;
        // all_time / undefined: no filter
      }
      const startClause = start ? sql` AND t.submitted_at >= ${start}` : sql``;

      // One query to get all user stats needed for all six badges
      const result = await db.execute(sql`
        SELECT
          u.id,
          TRIM(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) AS name,
          COUNT(t.id)::int                                                                                AS ideas_submitted,
          COUNT(CASE WHEN t.status::text = 'completed'    THEN 1 END)::int                             AS ideas_implemented,
          COUNT(CASE WHEN t.status::text = 'user_accepts' THEN 1 END)::int                             AS user_accepts,
          COUNT(CASE WHEN t.status::text = 'user_declines' THEN 1 END)::int                            AS user_declines,
          COUNT(CASE WHEN t.epic_id IS NOT NULL AND t.status::text = 'completed' THEN 1 END)::int      AS epic_completed,
          ROUND(AVG(
            CASE WHEN t.status::text IN ('completed','user_accepts') AND t.completed_at IS NOT NULL
              THEN EXTRACT(EPOCH FROM (t.completed_at - t.submitted_at)) / 86400.0
            END
          )::numeric, 1) AS avg_completion_days
        FROM users u
        INNER JOIN tickets t
          ON  t.submitted_by_user_id = u.id
          AND t.status::text != 'duplicate'
          ${startClause}
        GROUP BY u.id, u.first_name, u.last_name
        HAVING COUNT(t.id) > 0
      `);

      interface UStat {
        id: string; name: string;
        ideasSubmitted: number; ideasImplemented: number;
        userAccepts: number; userDeclines: number;
        epicCompleted: number;
        avgCompletionDays: number | null;
        qualityPct: number | null;   // user_accepts / ideas_submitted (min 3 submitted)
        firstPassPct: number | null; // user_accepts / (accepts+declines) (min 2 total)
      }
      const rows: UStat[] = (result.rows as any[]).map((r) => {
        const sub  = Number(r.ideas_submitted)    || 0;
        const impl = Number(r.ideas_implemented)  || 0;
        const acc  = Number(r.user_accepts)       || 0;
        const dec  = Number(r.user_declines)      || 0;
        const epic = Number(r.epic_completed)     || 0;
        const avg  = r.avg_completion_days != null ? Number(r.avg_completion_days) : null;
        const fpaTotal = acc + dec;
        return {
          id: r.id, name: r.name || "",
          ideasSubmitted: sub, ideasImplemented: impl,
          userAccepts: acc, userDeclines: dec, epicCompleted: epic,
          avgCompletionDays: avg,
          qualityPct:   sub    >= 3 ? Math.round(acc / sub      * 100) : null,
          firstPassPct: fpaTotal >= 2 ? Math.round(acc / fpaTotal * 100) : null,
        };
      });

      // Pick a single winner (highest/lowest) from eligible rows; ties go to more submissions
      function pickWinner(
        stat: keyof UStat,
        order: "max" | "min",
        filter: (r: UStat) => boolean
      ): UStat | null {
        const el = rows.filter(filter);
        if (!el.length) return null;
        return el.reduce((best, cur) => {
          const bv = best[stat] as number | null;
          const cv = cur[stat]  as number | null;
          if (bv == null) return cur;
          if (cv == null) return best;
          if (cv === bv) return cur.ideasSubmitted > best.ideasSubmitted ? cur : best;
          return order === "max" ? (cv > bv ? cur : best) : (cv < bv ? cur : best);
        });
      }

      const winners = {
        innovation_leader:  pickWinner("ideasImplemented",  "max", (r) => r.ideasImplemented > 0),
        idea_generator:     pickWinner("ideasSubmitted",    "max", (r) => r.ideasSubmitted   > 0),
        quality_champion:   pickWinner("qualityPct",        "max", (r) => r.qualityPct      != null),
        fast_resolver:      pickWinner("avgCompletionDays", "min", (r) => r.avgCompletionDays != null && r.ideasImplemented >= 3),
        epic_finisher:      pickWinner("epicCompleted",     "max", (r) => r.epicCompleted    > 0),
        first_pass_success: pickWinner("firstPassPct",      "max", (r) => r.firstPassPct    != null),
      };

      const fmt = (id: string, w: UStat | null) => {
        if (!w) return { id, winnerId: null, winnerName: null, isCurrentUser: false };
        const isMe = w.id === userId;
        return {
          id,
          winnerId:    w.id,
          winnerName:  canSeeAll || isMe ? w.name : null,
          isCurrentUser: isMe,
        };
      };

      res.json({
        period: period || "all_time",
        canSeeAll,
        badges: [
          fmt("innovation_leader",  winners.innovation_leader),
          fmt("idea_generator",     winners.idea_generator),
          fmt("quality_champion",   winners.quality_champion),
          fmt("fast_resolver",      winners.fast_resolver),
          fmt("epic_finisher",      winners.epic_finisher),
          fmt("first_pass_success", winners.first_pass_success),
        ],
      });
    } catch (error) {
      console.error("Error fetching achievement badges:", error);
      res.status(500).json({ message: "Failed to fetch achievement badges" });
    }
  });

  // ── Product Improvement Score: org-level funnel for executive leadership ──
  // Restricted to Will Walton, super_user, ops_manager, corporate_admin.
  app.get("/api/tickets/product-improvement-score", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });

      const requestingUser = await storage.getUser(userId);
      if (!requestingUser) return res.status(401).json({ message: "Not authenticated" });

      const PI_ROLES     = ["super_user", "ops_manager", "corporate_admin"];
      const WILL_WALTON  = "0a520043-f7eb-4944-aefe-9a85de761950";
      const isAuthorized = PI_ROLES.includes(requestingUser.role || "") || userId === WILL_WALTON;
      if (!isAuthorized) return res.status(403).json({ message: "Forbidden" });

      const { period, dateFrom, dateTo } = req.query as Record<string, string | undefined>;

      const now = new Date();
      let start: Date | null = null;
      let end:   Date | null = null;

      switch (period) {
        case "today":
          start = new Date(now.getFullYear(), now.getMonth(), now.getDate());
          end   = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
          break;
        case "this_week": {
          const dow      = now.getDay();
          const toMon    = dow === 0 ? 6 : dow - 1;
          start = new Date(now.getFullYear(), now.getMonth(), now.getDate() - toMon);
          end   = new Date(start.getTime() + 6 * 24 * 60 * 60 * 1000);
          end.setHours(23, 59, 59, 999);
          break;
        }
        case "this_month":
          start = new Date(now.getFullYear(), now.getMonth(), 1);
          end   = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
          break;
        case "this_year":
          start = new Date(now.getFullYear(), 0, 1);
          end   = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
          break;
        case "custom":
          if (dateFrom) start = new Date(dateFrom);
          if (dateTo)   end   = new Date(dateTo + "T23:59:59");
          break;
      }

      const startClause = start ? sql` AND submitted_at >= ${start}` : sql``;
      const endClause   = end   ? sql` AND submitted_at <= ${end}`   : sql``;

      const [counts] = await db.execute(sql`
        SELECT
          COUNT(*)                                                                    ::int AS ideas_submitted,
          COUNT(CASE WHEN status::text = 'completed'    THEN 1 END)                 ::int AS ideas_implemented,
          COUNT(CASE WHEN status::text = 'user_accepts' THEN 1 END)                 ::int AS user_accepts,
          COUNT(CASE WHEN status::text = 'user_declines' THEN 1 END)                ::int AS returned_for_rework
        FROM tickets
        WHERE status::text != 'duplicate'
          ${startClause}
          ${endClause}
      `);

      const r    = (counts as any).rows?.[0] ?? counts;
      const sub  = Number(r.ideas_submitted)    || 0;
      const impl = Number(r.ideas_implemented)  || 0;
      const acc  = Number(r.user_accepts)       || 0;
      const rew  = Number(r.returned_for_rework)|| 0;

      const pct = (n: number) => sub > 0 ? Math.round(n / sub * 100) : 0;

      res.json({
        ideasSubmitted:    sub,
        ideasImplemented:  impl,
        userAccepts:       acc,
        returnedForRework: rew,
        implPct:           pct(impl),
        acceptsPct:        pct(acc),
        reworkPct:         pct(rew),
      });
    } catch (error) {
      console.error("Error fetching product improvement score:", error);
      res.status(500).json({ message: "Failed to fetch product improvement score" });
    }
  });

  // ── Roadmap Reliability KPI ────────────────────────────────────────────────

  /** Shared period-bound helper — returns [start, end, label] for a named period. */
  function rrPeriodBounds(period: string | undefined, dateFrom: string | undefined, dateTo: string | undefined): [Date | null, Date | null, string] {
    const now = new Date();
    switch (period) {
      case "today": {
        const s = new Date(now.getFullYear(), now.getMonth(), now.getDate());
        const e = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 23, 59, 59, 999);
        return [s, e, "Today"];
      }
      case "this_week": {
        const dow = now.getDay(); const toMon = dow === 0 ? 6 : dow - 1;
        const s = new Date(now.getFullYear(), now.getMonth(), now.getDate() - toMon);
        const e = new Date(s.getTime() + 6 * 86400000); e.setHours(23, 59, 59, 999);
        return [s, e, "This Week"];
      }
      case "this_month": {
        const s = new Date(now.getFullYear(), now.getMonth(), 1);
        const e = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59, 999);
        return [s, e, "This Month"];
      }
      case "this_quarter": {
        const qStart = Math.floor(now.getMonth() / 3) * 3;
        const s = new Date(now.getFullYear(), qStart, 1);
        const e = new Date(now.getFullYear(), qStart + 3, 0, 23, 59, 59, 999);
        return [s, e, "This Quarter"];
      }
      case "this_year": {
        const s = new Date(now.getFullYear(), 0, 1);
        const e = new Date(now.getFullYear(), 11, 31, 23, 59, 59, 999);
        return [s, e, "This Year"];
      }
      case "custom": {
        const s = dateFrom ? new Date(dateFrom) : null;
        const e = dateTo   ? new Date(dateTo + "T23:59:59") : null;
        return [s, e, "Custom Range"];
      }
      default:
        return [null, null, "All Time"];
    }
  }

  function rrPrevBounds(period: string | undefined, start: Date | null, end: Date | null): [Date | null, Date | null, string] {
    const now = new Date();
    switch (period) {
      case "today": {
        const p = new Date(now.getFullYear(), now.getMonth(), now.getDate() - 1);
        return [p, new Date(p.getFullYear(), p.getMonth(), p.getDate(), 23, 59, 59, 999), "Yesterday"];
      }
      case "this_week": {
        const e2 = new Date(start!.getTime() - 1); e2.setHours(23, 59, 59, 999);
        const s2 = new Date(e2.getTime() - 6 * 86400000); s2.setHours(0, 0, 0, 0);
        return [s2, e2, "Last Week"];
      }
      case "this_month": {
        const e2 = new Date(now.getFullYear(), now.getMonth(), 0, 23, 59, 59, 999);
        const s2 = new Date(now.getFullYear(), now.getMonth() - 1, 1);
        return [s2, e2, "Last Month"];
      }
      case "this_quarter": {
        const qStart = Math.floor(now.getMonth() / 3) * 3;
        const pq = qStart - 3;
        if (pq < 0) {
          return [new Date(now.getFullYear() - 1, 9, 1), new Date(now.getFullYear() - 1, 11, 31, 23, 59, 59, 999), "Last Quarter"];
        }
        return [new Date(now.getFullYear(), pq, 1), new Date(now.getFullYear(), pq + 3, 0, 23, 59, 59, 999), "Last Quarter"];
      }
      case "this_year": {
        return [new Date(now.getFullYear() - 1, 0, 1), new Date(now.getFullYear() - 1, 11, 31, 23, 59, 59, 999), "Last Year"];
      }
      case "custom": {
        if (start && end) {
          const dur = end.getTime() - start.getTime();
          const e2  = new Date(start.getTime() - 1);
          const s2  = new Date(e2.getTime() - dur);
          return [s2, e2, "Previous Period"];
        }
        return [null, null, "Previous Period"];
      }
      default:
        return [null, null, "Previous Period"];
    }
  }

  app.get("/api/tickets/roadmap-reliability", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const requestingUser = await storage.getUser(userId);
      if (!requestingUser) return res.status(401).json({ message: "Not authenticated" });
      const PI_ROLES    = ["super_user", "ops_manager", "corporate_admin"];
      const WILL_WALTON = "0a520043-f7eb-4944-aefe-9a85de761950";
      if (!PI_ROLES.includes(requestingUser.role || "") && userId !== WILL_WALTON) {
        return res.status(403).json({ message: "Forbidden" });
      }

      const { period, dateFrom, dateTo } = req.query as Record<string, string | undefined>;
      const [start, end]         = rrPeriodBounds(period, dateFrom, dateTo);
      const [prevStart, prevEnd, prevPeriodLabel] = rrPrevBounds(period, start, end);

      async function rrCounts(s: Date | null, e: Date | null) {
        const sc = s ? sql` AND completed_at >= ${s}` : sql``;
        const ec = e ? sql` AND completed_at <= ${e}` : sql``;
        const rows = await db.execute(sql`
          SELECT
            COUNT(CASE WHEN first_scheduled_deployment_date IS NOT NULL
                        AND completed_at::date <= first_scheduled_deployment_date THEN 1 END)::int AS on_time,
            COUNT(CASE WHEN first_scheduled_deployment_date IS NOT NULL
                        AND completed_at::date >  first_scheduled_deployment_date THEN 1 END)::int AS late,
            COUNT(CASE WHEN first_scheduled_deployment_date IS NULL THEN 1 END)::int              AS unscheduled
          FROM tickets
          WHERE status::text != 'duplicate'
            AND completed_at IS NOT NULL
            ${sc}${ec}
        `);
        const r = ((rows as any).rows ?? [rows])[0] ?? {};
        return {
          onTime:      Number(r.on_time)      || 0,
          late:        Number(r.late)          || 0,
          unscheduled: Number(r.unscheduled)   || 0,
        };
      }

      const [curr, prev] = await Promise.all([rrCounts(start, end), rrCounts(prevStart, prevEnd)]);
      const total     = curr.onTime + curr.late;
      const prevTotal = prev.onTime + prev.late;

      res.json({
        pct:             total     > 0 ? Math.round((curr.onTime / total)     * 100) : null,
        onTime:          curr.onTime,
        late:            curr.late,
        total,
        unscheduled:     curr.unscheduled,
        prevPct:         prevTotal > 0 ? Math.round((prev.onTime / prevTotal) * 100) : null,
        prevPeriodLabel,
      });
    } catch (error) {
      console.error("Error fetching roadmap reliability:", error);
      res.status(500).json({ message: "Failed to fetch roadmap reliability" });
    }
  });

  app.get("/api/tickets/roadmap-reliability/drill", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const requestingUser = await storage.getUser(userId);
      if (!requestingUser) return res.status(401).json({ message: "Not authenticated" });
      const PI_ROLES    = ["super_user", "ops_manager", "corporate_admin"];
      const WILL_WALTON = "0a520043-f7eb-4944-aefe-9a85de761950";
      if (!PI_ROLES.includes(requestingUser.role || "") && userId !== WILL_WALTON) {
        return res.status(403).json({ message: "Forbidden" });
      }

      const { period, dateFrom, dateTo, filter } = req.query as Record<string, string | undefined>;
      const [start, end] = rrPeriodBounds(period, dateFrom, dateTo);

      const sc = start ? sql` AND t.completed_at >= ${start}` : sql``;
      const ec = end   ? sql` AND t.completed_at <= ${end}`   : sql``;
      const fc = filter === "on_time"     ? sql` AND t.first_scheduled_deployment_date IS NOT NULL AND t.completed_at::date <= t.first_scheduled_deployment_date`
               : filter === "late"        ? sql` AND t.first_scheduled_deployment_date IS NOT NULL AND t.completed_at::date >  t.first_scheduled_deployment_date`
               : filter === "unscheduled" ? sql` AND t.first_scheduled_deployment_date IS NULL`
               : sql``;

      const rows = await db.execute(sql`
        SELECT
          t.id,
          t.ticket_number,
          t.title,
          e.name                             AS epic_name,
          t.scheduled_development_date,
          t.first_scheduled_deployment_date,
          t.scheduled_deployment_date,
          t.completed_at,
          CASE
            WHEN t.first_scheduled_deployment_date IS NOT NULL
            THEN (t.completed_at::date - t.first_scheduled_deployment_date)::int
            ELSE NULL
          END                                AS days_early_late
        FROM tickets t
        LEFT JOIN epics e ON t.epic_id = e.id
        WHERE t.status::text != 'duplicate'
          AND t.completed_at IS NOT NULL
          ${sc}${ec}${fc}
        ORDER BY t.completed_at DESC
        LIMIT 500
      `);

      const data = ((rows as any).rows ?? rows).map((r: any) => ({
        id:                           r.id,
        ticketNumber:                 r.ticket_number,
        title:                        r.title,
        epicName:                     r.epic_name ?? null,
        scheduledDevelopmentDate:     r.scheduled_development_date ?? null,
        firstScheduledDeploymentDate: r.first_scheduled_deployment_date ?? null,
        scheduledDeploymentDate:      r.scheduled_deployment_date ?? null,
        completedAt:                  r.completed_at,
        daysEarlyLate:                r.days_early_late !== null && r.days_early_late !== undefined
                                        ? Number(r.days_early_late) : null,
      }));

      res.json(data);
    } catch (error) {
      console.error("Error fetching roadmap reliability drill:", error);
      res.status(500).json({ message: "Failed to fetch roadmap reliability drill" });
    }
  });

