  app.post("/api/tickets", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { userId, user } = await resolveAmrActor(req);
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      if (!user) return res.status(404).json({ message: "User not found" });

      const { type, module, title, desiredOutcome, businessImpact, priority, status, applicationScope, epicId, epicTicketId, isEpic, submissionToken } = req.body;

      // ── Idempotency check ────────────────────────────────────────────────────
      // If the client supplies a submission token, look for an existing ticket with
      // that token first.  This prevents duplicate AMRs from double-clicks, network
      // retries, browser retries, or mobile double-taps — the original ticket is
      // returned instead of creating a second one.
      if (submissionToken && typeof submissionToken === "string" && submissionToken.trim()) {
        const safeToken = submissionToken.trim().slice(0, 64);
        const existing = await db.select().from(tickets).where(eq(tickets.submissionToken, safeToken)).limit(1);
        if (existing.length > 0) {
          console.log(`[Tickets POST] Idempotent replay detected for token ${safeToken.slice(0, 8)}… — returning existing ${existing[0].ticketNumber}`);
          return res.status(200).json(existing[0]);
        }
      }

      // Validate required fields — return specific 400s so the client can show them
      const validationErrors: string[] = [];
      if (!type) validationErrors.push("Type is required");
      if (!module) validationErrors.push("Module is required");
      if (!title || !String(title).trim()) validationErrors.push("Issue / Idea is required");
      if (!priority) validationErrors.push("Priority is required");
      if (validationErrors.length > 0) {
        return res.status(400).json({ message: validationErrors[0], errors: validationErrors });
      }
      if (!TICKET_TYPES.includes(type)) {
        return res.status(400).json({ message: `Invalid ticket type: "${type}". Must be one of: ${TICKET_TYPES.join(', ')}` });
      }
      if (!TICKET_MODULES.includes(module)) {
        return res.status(400).json({ message: `Invalid module: "${module}". Must be one of: ${TICKET_MODULES.join(', ')}` });
      }
      if (priority && !TICKET_PRIORITIES.includes(priority)) {
        return res.status(400).json({ message: `Invalid priority: "${priority}". Must be one of: ${TICKET_PRIORITIES.join(', ')}` });
      }

      // Resilient sequence fetch — auto-recreates ticket_seq if dropped by schema migration
      let seq: number;
      try {
        const seqResult = await db.execute(sql`SELECT nextval('ticket_seq') as seq`);
        seq = Number((seqResult as any).rows?.[0]?.seq ?? (seqResult as any)[0]?.seq ?? 0);
        if (!seq || isNaN(seq)) throw new Error("Invalid sequence value");
      } catch (seqErr: any) {
        const errMsg = String(seqErr?.message || "").toLowerCase();
        if (errMsg.includes("does not exist") || errMsg.includes("invalid sequence") || errMsg.includes("undefined")) {
          console.warn("[Tickets] ticket_seq missing — recreating from current max");
          const maxResult = await db.execute(sql`SELECT COALESCE(MAX(ticket_sequence), 0) as max_seq FROM tickets`);
          const maxSeq = Number((maxResult as any).rows?.[0]?.max_seq ?? (maxResult as any)[0]?.max_seq ?? 0);
          const startAt = maxSeq + 1;
          await db.execute(sql`CREATE SEQUENCE IF NOT EXISTS ticket_seq START WITH ${sql.raw(String(startAt))} INCREMENT BY 1 NO MAXVALUE CACHE 1`);
          const retryResult = await db.execute(sql`SELECT nextval('ticket_seq') as seq`);
          seq = Number((retryResult as any).rows?.[0]?.seq ?? (retryResult as any)[0]?.seq ?? startAt);
        } else {
          throw seqErr;
        }
      }

      const ticketNumber = `DH-${String(seq).padStart(6, '0')}`;

      const username = user.firstName && user.lastName
        ? `${user.firstName} ${user.lastName}`
        : user.email || 'Unknown User';

      const [ticket] = await db.insert(tickets).values({
        ticketNumber,
        ticketSequence: seq,
        type,
        module,
        title: String(title).trim(),
        desiredOutcome: desiredOutcome || null,
        businessImpact: businessImpact || null,
        priority: priority || 'P2',
        status: status || 'submitted',
        submittedByUserId: userId,
        submittedByUsername: username,
        assignedToUserId: userId,
        productOwnerUserId: userId,
        orgId: user.orgId || null,
        applicationScope: AMR_APPLICATION_SCOPES.includes(applicationScope) ? applicationScope : "DriverHub",
        // If type is 'epic', auto-set isEpic=true and clear epicTicketId
        epicTicketId: (type === 'epic') ? null : (epicTicketId || epicId || null),
        isEpic: (type === 'epic') ? true : (isEpic === true || isEpic === 'true'),
        // Store idempotency token so repeated requests with the same token are
        // caught by the early-exit check above (or by the DB unique index on race).
        submissionToken: (submissionToken && typeof submissionToken === "string")
          ? submissionToken.trim().slice(0, 64) || null
          : null,
      }).returning();

      res.status(201).json(ticket);
    } catch (error: any) {
      const msg = String(error?.message || "");
      console.error("[Tickets POST] Error creating ticket:", {
        message: msg,
        code: error?.code,
        detail: error?.detail,
        constraint: error?.constraint,
        stack: error?.stack?.split('\n').slice(0, 5).join(' | '),
      });
      if (msg.includes("invalid input value for enum") || msg.includes("violates check constraint")) {
        return res.status(400).json({ message: `Validation error: ${msg}` });
      }
      if (msg.includes("unique constraint") || msg.includes("duplicate key")) {
        // If the unique constraint is on the submission_token (two concurrent requests
        // raced past the early-exit check), look up and return the winner's ticket.
        if (
          (error?.constraint && String(error.constraint).includes("submission_token")) ||
          msg.includes("submission_token")
        ) {
          if (submissionToken && typeof submissionToken === "string") {
            try {
              const raceWinner = await db.select().from(tickets)
                .where(eq(tickets.submissionToken, submissionToken.trim().slice(0, 64)))
                .limit(1);
              if (raceWinner.length > 0) {
                console.log(`[Tickets POST] Race condition resolved for token — returning ${raceWinner[0].ticketNumber}`);
                return res.status(200).json(raceWinner[0]);
              }
            } catch { /* fall through to 409 */ }
          }
        }
        return res.status(409).json({ message: "A ticket with that number already exists. Please try again." });
      }
      if (msg.includes("foreign key") || msg.includes("violates foreign key")) {
        return res.status(400).json({ message: "Invalid reference: your user account may not be fully set up. Please refresh and try again.", detail: msg });
      }
      res.status(500).json({ message: "Failed to create ticket", detail: msg });
    }
  });


