  app.post("/api/tickets/:id/testers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { userId, user: currentUser } = await resolveAmrActor(req);
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      if (!currentUser || !isTicketAdmin(currentUser.role)) return res.status(403).json({ message: "Only admins can assign testers" });
      const [ticket] = await db.select().from(tickets).where(eq(tickets.id, req.params.id));
      if (!ticket) return res.status(404).json({ message: "Ticket not found" });
      const { userId: targetUserId } = req.body;
      if (!targetUserId) return res.status(400).json({ message: "userId is required" });
      const targetUser = await storage.getUser(targetUserId);
      if (!targetUser || targetUser.status !== "ACTIVE" || targetUser.role === "driver") {
        return res.status(400).json({ message: "User is not eligible to be assigned as a tester" });
      }
      const existingRows = await db.select({ id: ticketTesters.id }).from(ticketTesters).where(and(eq(ticketTesters.ticketId, ticket.id), eq(ticketTesters.userId, targetUserId)));
      if (existingRows.length > 0) return res.status(409).json({ message: "User is already assigned as a tester" });
      await db.insert(ticketTesters).values({ ticketId: ticket.id, userId: targetUserId, assignedByUserId: userId });
      const actorName = [currentUser.firstName, currentUser.lastName].filter(Boolean).join(" ") || currentUser.email || "Admin";
      const targetName = [targetUser.firstName, targetUser.lastName].filter(Boolean).join(" ") || targetUser.email || targetUserId;
      await db.insert(ticketWorkLogs).values({
        ticketId: ticket.id,
        workDate: new Date().toISOString().split("T")[0],
        note: `${actorName} added ${targetName} as an Assigned Tester`,
        createdByUserId: userId,
        createdByUsername: actorName,
      });
      try {
        if (targetUser.email) await sendTesterAssignedEmail(targetUser.email, targetName, ticket.ticketNumber, ticket.title, ticket.status);
        await insertNotificationWithWPI({
          userId: targetUserId,
          type: "amr_tester_assigned",
          title: `You've been assigned to test AMR ${ticket.ticketNumber}`,
          message: `${actorName} has assigned you as an Assigned Tester for "${ticket.title}". Current status: ${TICKET_STATUS_LABELS[ticket.status] || ticket.status}.`,
          relatedEntityType: "ticket",
          relatedEntityId: ticket.id,
          actionUrl: `/corporate/amr`,
        });
      } catch (notifErr) { console.error("[AMR] Failed to notify tester on assignment:", notifErr); }

      // Notify CC'd users (fire-and-forget)
      try {
        const change = `Assigned Tester added: ${targetName}`;
        const ts = new Date().toLocaleString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: 'numeric', minute: '2-digit', hour12: true });
        const ccRowsTester = await db.select({ userId: ticketCcUsers.userId }).from(ticketCcUsers).where(eq(ticketCcUsers.ticketId, ticket.id));
        for (const cu of ccRowsTester) {
          if (cu.userId === userId) continue;
          const ccU = await storage.getUser(cu.userId);
          if (!ccU || ccU.status !== 'ACTIVE') continue;
          await insertNotificationWithWPI({ userId: cu.userId, type: "amr_cc_update", title: `${ticket.ticketNumber} Updated`, message: `${actorName} — ${change} on "${ticket.title}" (${ts})`, relatedEntityType: "ticket", relatedEntityId: ticket.id, actionUrl: `/corporate/amr` });
          if (ccU.email) await sendCcUpdateEmail(ccU.email, [ccU.firstName, ccU.lastName].filter(Boolean).join(' ') || ccU.email, ticket.ticketNumber, ticket.title, [change], actorName);
        }
      } catch (e) { console.error('[AMR] CC tester-add notification failed:', e); }

      res.json({ success: true });
    } catch (e: any) { console.error("[TicketTesters POST]", e); res.status(500).json({ message: "Failed to assign tester" }); }
  });

