  app.get("/api/user-sentiment/admin", isAuthenticated, async (req: any, res: Response) => {
    try {
      const admin = await requireUserFeedbackAdmin(req, res);
      if (!admin) return;

      const { sentiment, status, limit: rawLimit } = req.query;
      const queryLimit = Math.min(parseInt(rawLimit as string) || 50, 200);

      const conditions = [eq(userFeedback.dismissed, false)];
      if (sentiment && ['positive', 'neutral', 'negative'].includes(sentiment as string)) {
        conditions.push(eq(userFeedback.sentiment, sentiment as any));
      }
      if (status && ["new", "reviewed", "converted_to_quick_idea", "converted_to_amr", "no_action"].includes(status as string)) {
        conditions.push(eq(userFeedback.status, status as string));
      }

      const feedbackList = await db.select()
        .from(userFeedback)
        .where(and(...conditions))
        .orderBy(desc(userFeedback.createdAt))
        .limit(queryLimit);

      const negativeCount = await db.select({ count: sql<number>`count(*)` })
        .from(userFeedback)
        .where(and(
          eq(userFeedback.sentiment, 'negative'),
          eq(userFeedback.dismissed, false)
        ));

      res.json({
        feedback: feedbackList,
        negativeCount: Number(negativeCount[0]?.count || 0),
        total: feedbackList.length,
      });
    } catch (error) {
      console.error("Error fetching feedback:", error);
      res.status(500).json({ message: "Failed to fetch feedback" });
    }
  });

