  app.post("/api/releases", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: "Not authenticated" });
      const user = await storage.getUser(userId);
      if (!user || !isTicketAdmin(user.role)) {
        return res.status(403).json({ message: "Access denied" });
      }

      const { version, title, summary, ticketIds } = req.body;
      if (!version || !title) {
        return res.status(400).json({ message: "Version and title are required" });
      }

      const typeToGroup: Record<string, string> = {
        feature_request:        "New Features",
        enhancement:            "Improvements",
        bug:                    "Bug Fixes",
        architectural_changes:  "Improvements",
        artificial_intelligence:"New Features",
        performance:            "Improvements",
        security_compliance:    "Improvements",
        synchronization:        "Improvements",
        user_experience:        "Improvements",
      };

      const [newRelease] = await db.insert(releases).values({
        version,
        title,
        summary: summary || null,
        status: "draft",
        createdByUserId: userId,
        createdByUsername: user.firstName && user.lastName
          ? `${user.firstName} ${user.lastName}`
          : user.email || userId,
      }).returning();

      if (ticketIds && ticketIds.length > 0) {
        const selectedTickets = await db.select().from(tickets)
          .where(inArray(tickets.id, ticketIds));

        const groupOrder: Record<string, number> = {
          "New Features": 0,
          "Improvements": 1,
          "Bug Fixes": 2,
        };

        let sortIdx = 0;
        const sorted = selectedTickets.sort((a, b) => {
          const ga = groupOrder[typeToGroup[a.type] || "Improvements"] ?? 1;
          const gb = groupOrder[typeToGroup[b.type] || "Improvements"] ?? 1;
          return ga - gb;
        });

        for (const t of sorted) {
          await db.insert(releaseItems).values({
            releaseId: newRelease.id,
            ticketId: t.id,
            ticketNumber: t.ticketNumber,
            ticketTitle: t.title,
            ticketType: t.type,
            ticketModule: t.module,
            groupLabel: typeToGroup[t.type] || "Improvements",
            sortOrder: sortIdx++,
          });
        }
      }

      const items = await db.select().from(releaseItems)
        .where(eq(releaseItems.releaseId, newRelease.id))
        .orderBy(asc(releaseItems.sortOrder));

      res.json({ ...newRelease, items });
    } catch (error) {
      console.error("Error creating release:", error);
      res.status(500).json({ message: "Failed to create release" });
    }
  });

