  app.get("/api/dashboards/:moduleKey/config", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { moduleKey } = req.params;
      if (!(MODULE_KEYS as readonly string[]).includes(moduleKey)) {
        return res.status(400).json({ message: "Invalid module key" });
      }

      const currentUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const currentUser = currentUserId ? await storage.getUser(currentUserId) : null;
      const role = currentUser?.role || "driver";

      const defaultTemplate = await db.select()
        .from(dashboardLayoutTemplates)
        .where(and(
          eq(dashboardLayoutTemplates.moduleKey, moduleKey as any),
          eq(dashboardLayoutTemplates.isDefault, true)
        ))
        .limit(1);

      let defaultItems: any[] = [];
      if (defaultTemplate.length > 0) {
        defaultItems = await db.select({
          widgetId: dashboardLayoutTemplateItems.widgetId,
          position: dashboardLayoutTemplateItems.position,
          size: dashboardLayoutTemplateItems.size,
          isLocked: dashboardLayoutTemplateItems.isLocked,
          key: widgets.key,
          name: widgets.name,
          componentName: widgets.componentName,
          description: widgets.description,
        })
          .from(dashboardLayoutTemplateItems)
          .innerJoin(widgets, eq(dashboardLayoutTemplateItems.widgetId, widgets.id))
          .where(eq(dashboardLayoutTemplateItems.layoutTemplateId, defaultTemplate[0].id))
          .orderBy(asc(dashboardLayoutTemplateItems.position));

        const permittedWidgetIds = await db.select({ widgetId: widgetPermissions.widgetId })
          .from(widgetPermissions)
          .where(and(
            eq(widgetPermissions.roleKey, role),
            eq(widgetPermissions.canView, true)
          ));
        const permittedSet = new Set(permittedWidgetIds.map(p => p.widgetId));

        const allPermWidgets = await db.select({ widgetId: widgetPermissions.widgetId })
          .from(widgetPermissions);
        const widgetsWithPerms = new Set(allPermWidgets.map(p => p.widgetId));

        defaultItems = defaultItems.filter(item =>
          !widgetsWithPerms.has(item.widgetId) || permittedSet.has(item.widgetId)
        );
      }

      let userItems: any[] = [];
      if (currentUserId) {
        const userLayout = await db.select()
          .from(userDashboardLayouts)
          .where(and(
            eq(userDashboardLayouts.userId, currentUserId),
            eq(userDashboardLayouts.moduleKey, moduleKey as any)
          ))
          .limit(1);

        if (userLayout.length > 0) {
          userItems = await db.select({
            widgetId: userDashboardLayoutItems.widgetId,
            position: userDashboardLayoutItems.position,
            size: userDashboardLayoutItems.size,
            key: widgets.key,
            name: widgets.name,
            componentName: widgets.componentName,
            description: widgets.description,
          })
            .from(userDashboardLayoutItems)
            .innerJoin(widgets, eq(userDashboardLayoutItems.widgetId, widgets.id))
            .where(eq(userDashboardLayoutItems.userDashboardLayoutId, userLayout[0].id))
            .orderBy(asc(userDashboardLayoutItems.position));
        }
      }

      const merged = [
        ...defaultItems.map((item: any) => ({ ...item, isLocked: true, source: "default" as const })),
        ...userItems.map((item: any) => ({ ...item, isLocked: false, source: "user_added" as const })),
      ];

      res.json({ moduleKey, widgets: merged });
    } catch (error) {
      console.error("Error fetching dashboard config:", error);
      res.status(500).json({ message: "Failed to fetch dashboard config" });
    }
  });

