  // PATCH /api/work-plan-items/:id/update — general field update (priority, dueDate, reason)
  app.patch("/api/work-plan-items/:id/update", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const actorName = user ? `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || "Unknown" : "Unknown";

      const { priority, dueDate, reason, summary } = req.body;
      const patch: Record<string, any> = { updatedAt: new Date() };
      const changes: string[] = [];

      // Fetch existing item to compute diffs
      const [existing] = await db.select().from(workPlanItems).where(eq(workPlanItems.id, req.params.id)).limit(1);
      if (!existing) return res.status(404).json({ message: "Item not found" });

      if (priority !== undefined && priority !== existing.priority) {
        patch.priority = priority;
        changes.push(`priority changed from ${existing.priority} to ${priority}`);
      }
      if (dueDate !== undefined) {
        patch.dueDate = dueDate ? new Date(dueDate) : null;
        changes.push(dueDate ? `due date set to ${dueDate}` : "due date cleared");
      }
      if (reason !== undefined && reason !== existing.reason) {
        patch.reason = reason;
        changes.push("description updated");
      }
      if (summary !== undefined && summary !== existing.summary) {
        patch.summary = summary;
        changes.push("summary updated");
      }

      if (Object.keys(patch).length <= 1) return res.json(existing); // no real changes

      const [updated] = await db.update(workPlanItems)
        .set(patch)
        .where(eq(workPlanItems.id, req.params.id))
        .returning();

      // Log each change
      for (const change of changes) {
        try {
          await db.insert(taskActivityLog).values({
            taskId: updated.id,
            action: "task_updated",
            performedBy: userId,
            actorName,
            note: change,
          });
        } catch (_e) { /* non-critical */ }
      }

      return res.json(updated);
    } catch (error) {
      console.error("Error updating work plan item:", error);
      return res.status(500).json({ message: "Failed to update work plan item" });
    }
  });

  // PATCH /api/work-plan-items/:id/complete
  app.patch("/api/work-plan-items/:id/complete", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const [item] = await db.update(workPlanItems)
        .set({ status: "completed", completedBy: userId, completedAt: new Date(), updatedAt: new Date() })
        .where(eq(workPlanItems.id, req.params.id))
        .returning();

      if (!item) return res.status(404).json({ message: "Item not found" });

      // Activity log
      try {
        const actorName = user ? `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || "Unknown" : "Unknown";
        await db.insert(taskActivityLog).values({ taskId: item.id, action: "completed", performedBy: userId, actorName });
      } catch (_e) { /* non-critical */ }

      // If this item was derived from a notification, mark all related notifications as read
      // recordId is now the relatedEntityId (ticket UUID etc.), not the notification.id
      if (item.eventType === "notification" && item.recordId) {
        try {
          await db.update(notifications)
            .set({ isRead: true })
            .where(and(
              eq(notifications.userId, userId),
              or(
                eq(notifications.id, item.recordId),          // fallback: WPI keyed by notif.id
                eq(notifications.relatedEntityId, item.recordId) // primary: WPI keyed by entity
              )
            ));
        } catch (_e) { /* non-critical */ }
      }

      res.json(item);
    } catch (error) {
      console.error("Error completing work plan item:", error);
      res.status(500).json({ message: "Failed to complete item" });
    }
  });

  // PATCH /api/work-plan-items/:id/snooze
  app.patch("/api/work-plan-items/:id/snooze", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const [existing] = await db.select().from(workPlanItems).where(eq(workPlanItems.id, req.params.id)).limit(1);
      if (!existing) return res.status(404).json({ message: "Item not found" });
      if ((existing.snoozeCount || 0) >= 3) return res.status(400).json({ message: "Maximum snoozes (3) reached" });

      const { snoozeUntil } = req.body;
      if (!snoozeUntil) return res.status(400).json({ message: "snoozeUntil is required" });

      const [item] = await db.update(workPlanItems)
        .set({ status: "snoozed", snoozedBy: userId, snoozedAt: new Date(), snoozeUntil: new Date(snoozeUntil), snoozeCount: (existing.snoozeCount || 0) + 1, updatedAt: new Date() })
        .where(eq(workPlanItems.id, req.params.id))
        .returning();

      // Activity log
      try {
        const actorName = user ? `${user.firstName || ""} ${user.lastName || ""}`.trim() || user.email || "Unknown" : "Unknown";
        const until = new Date(snoozeUntil).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
        await db.insert(taskActivityLog).values({ taskId: item.id, action: "snoozed", performedBy: userId, actorName, note: `Snoozed until ${until}` });
      } catch (_e) { /* non-critical */ }

      res.json(item);
    } catch (error) {
      console.error("Error snoozing work plan item:", error);
      res.status(500).json({ message: "Failed to snooze item" });
    }
  });

