  // POST /api/corporate/accidents/:id/notes  — add a new note entry
  app.post('/api/corporate/accidents/:id/notes', isAuthenticated, async (req, res) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      if (!userId) return res.status(401).json({ message: 'Unauthorized' });
      const accidentId = req.params.id;
      const { noteText } = req.body;
      if (!noteText || !String(noteText).trim()) {
        return res.status(400).json({ message: 'noteText is required' });
      }
      // Verify claim exists
      const [accident] = await db.select({ id: accidents.id }).from(accidents).where(eq(accidents.id, accidentId)).limit(1);
      if (!accident) return res.status(404).json({ message: 'Claim not found' });

      const [inserted] = await db.insert(claimNotes).values({
        claimId: accidentId,
        userId,
        noteText: String(noteText).trim(),
      }).returning();

      // Also create a timeline entry in claim_audit_logs
      try {
        const userRecord = await storage.getUser(userId);
        const authorName = userRecord ? `${userRecord.firstName || ''} ${userRecord.lastName || ''}`.trim() : 'Unknown';
        await db.insert(claimAuditLogs).values({
          claimId: accidentId,
          userId,
          eventType: 'note_added',
          actionSummary: `${authorName} added a note`,
          metadata: JSON.stringify({ noteId: inserted.id, notePreview: String(noteText).trim().slice(0, 120) }),
        });
      } catch (timelineErr) {
        console.warn('[ClaimNotes] Timeline entry failed (non-fatal):', timelineErr);
      }

      // Fetch the note with author info to return
      const [full] = await db
        .select({
          id: claimNotes.id,
          claimId: claimNotes.claimId,
          noteText: claimNotes.noteText,
          createdAt: claimNotes.createdAt,
          userId: claimNotes.userId,
          authorFirstName: users.firstName,
          authorLastName: users.lastName,
        })
        .from(claimNotes)
        .leftJoin(users, eq(claimNotes.userId, users.id))
        .where(eq(claimNotes.id, inserted.id))
        .limit(1);

      res.status(201).json(full);
    } catch (e: any) {
      console.error('[ClaimNotes POST]', e);
      res.status(500).json({ error: e.message });
    }
  });

