  // DRIVER ↔ ACCOUNT ASSIGNMENT ROUTES (many-to-many)
  // ============================================================

  // GET all accounts assigned to a driver
  app.get("/api/corporate/drivers/:id/accounts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const driverId = req.params.id;
      const rows = await db
        .select({
          id: driverAccounts.id,
          accountId: driverAccounts.accountId,
          isPrimary: driverAccounts.isPrimary,
          createdAt: driverAccounts.createdAt,
          assignmentStartedAt: driverAccounts.assignmentStartedAt,
          customerName: customers.customerName,
          status: customers.status,
          customerType: customers.customerType,
        })
        .from(driverAccounts)
        .innerJoin(drivers, eq(driverAccounts.driverId, drivers.id))
        .innerJoin(customers, eq(driverAccounts.accountId, customers.id))
        .where(and(
          eq(driverAccounts.driverId, driverId),
          eq(drivers.status, "active"),
          isNull(driverAccounts.assignmentEndedAt),
          sql`lower(coalesce(${customers.status}, '')) IN ('active', 'pending', 'onboarding')`,
        ))
        .orderBy(desc(driverAccounts.isPrimary), asc(customers.customerName));
      res.json(rows);
    } catch (e: any) {
      console.error("[DriverAccounts GET]", e);
      res.status(500).json({ message: "Failed to fetch driver accounts" });
    }
  });

  // GET closed assignments for Driver Detail. This uses the same authoritative
