  // PUT /api/platform/sms/config — save inbox ID, creator ID, feature flag, and group creator IDs
  app.put("/api/platform/sms/config", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (user?.role !== "super_admin" && user?.role !== "root_super_admin") return res.status(403).json({ message: "Forbidden" });
      const { inboxId, creatorId, featureFlagEnabled, groupCreators } = req.body as {
        inboxId?: number;
        creatorId?: number | null;
        featureFlagEnabled?: boolean;
        groupCreators?: { recruiting?: number | null; dispatch?: number | null; support?: number | null };
      };
      const { upsertConfig } = await import("./services/platformConfigService");
      if (inboxId !== undefined) {
        await upsertConfig("sms.heymarket.inbox_id", inboxId, { label: "Heymarket Inbox ID", configCategory: "sms" });
      }
      if (creatorId !== undefined) {
        if (creatorId === null) {
          await db.execute(sql`DELETE FROM platform_configs WHERE config_key = 'sms.heymarket.creator_id'`);
        } else {
          await upsertConfig("sms.heymarket.creator_id", creatorId, { label: "Heymarket Creator ID", configCategory: "sms" });
        }
      }
      if (featureFlagEnabled !== undefined) {
        await upsertConfig("heymarket_texting_enabled", featureFlagEnabled, { label: "Heymarket Texting Enabled", configCategory: "sms" });
      }
      // Group creator IDs — per-role signatures for bulk sends
      if (groupCreators) {
        const groupMap = [
          { key: "sms.heymarket.group_creator.recruiting", label: "Heymarket Group Creator: Recruiting", val: groupCreators.recruiting },
          { key: "sms.heymarket.group_creator.dispatch",   label: "Heymarket Group Creator: Dispatch",   val: groupCreators.dispatch },
          { key: "sms.heymarket.group_creator.support",    label: "Heymarket Group Creator: Support",    val: groupCreators.support },
        ];
        for (const entry of groupMap) {
          if (entry.val === undefined) continue;
          if (entry.val === null) {
            await db.execute(sql`DELETE FROM platform_configs WHERE config_key = ${entry.key}`);
          } else {
            await upsertConfig(entry.key, entry.val, { label: entry.label, configCategory: "sms" });
          }
        }
      }
      const { getHeymarketStatus } = await import("./services/communicationsService");
      res.json({ success: true, status: await getHeymarketStatus() });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/platform/sms/stats — send totals and recent bulk send history
  app.get("/api/platform/sms/stats", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (user?.role !== "super_admin") return res.status(403).json({ message: "Forbidden" });
      const [totalsRes, recentRes] = await Promise.all([
        pool.query(`
          SELECT
            COUNT(*) FILTER (WHERE status = 'sent')    AS sent,
            COUNT(*) FILTER (WHERE status = 'failed')  AS failed,
            COUNT(*) FILTER (WHERE status IN ('pending_integration','sms_disabled','queued')) AS pending,
            COUNT(DISTINCT bulk_send_id) FILTER (WHERE bulk_send_id IS NOT NULL) AS bulk_sends,
            COUNT(DISTINCT bulk_send_id) FILTER (WHERE bulk_send_id IS NOT NULL AND created_at >= now() - interval '7 days') AS last_7_days
          FROM driver_communication_logs
          WHERE channel = 'sms' AND created_at >= now() - interval '30 days'
        `),
        pool.query(`
          SELECT
            bulk_send_id,
            MIN(created_at)     AS sent_at,
            MAX(context_module) AS context_module,
            MIN(recipient_name) AS sample_name,
            COUNT(*)                                          AS recipients,
            COUNT(*) FILTER (WHERE status = 'sent')          AS sent,
            COUNT(*) FILTER (WHERE status = 'failed')        AS failed
          FROM driver_communication_logs
          WHERE channel = 'sms' AND bulk_send_id IS NOT NULL
          GROUP BY bulk_send_id
          ORDER BY MIN(created_at) DESC
          LIMIT 20
        `),
      ]);
      res.json({ totals: totalsRes.rows[0] ?? {}, recentBulkSends: recentRes.rows });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

