  // GET /api/platform/sms/inboxes — detect inbox ID from the Heymarket API
  // Tries multiple endpoints since token scope varies by Heymarket plan/key type.
  app.get("/api/platform/sms/inboxes", isAuthenticated, async (req: any, res: Response) => {
    try {
      const apiToken = process.env.HEYMARKET_API_TOKEN;
      if (!apiToken) return res.status(400).json({ message: "HEYMARKET_API_TOKEN not set" });

      const headers = { "Authorization": `Bearer ${apiToken}`, "Content-Type": "application/json" };

      // Helper to extract inbox entries from any response shape
      function extractInboxes(data: any): { id: number; name: string; phone: string | null }[] {
        const seen = new Set<number>();
        const results: { id: number; name: string; phone: string | null }[] = [];
        const addInbox = (id: any, name?: any, phone?: any) => {
          const numId = typeof id === "number" ? id : parseInt(id, 10);
          if (numId && !isNaN(numId) && !seen.has(numId)) {
            seen.add(numId);
            results.push({ id: numId, name: name ?? `Inbox ${numId}`, phone: phone ?? null });
          }
        };
        const list = Array.isArray(data) ? data : (data.inboxes ?? data.messages ?? data.conversations ?? data.data ?? []);
        for (const item of list) {
          // Direct inbox object
          if (item.id && (item.name || item.phone_number)) {
            addInbox(item.id, item.name ?? item.title, item.phone_number ?? item.phone);
          }
          // Nested inbox in message/conversation
          if (item.inbox_id) addInbox(item.inbox_id, item.inbox?.name, item.inbox?.phone_number);
          if (item.inboxId) addInbox(item.inboxId, item.inbox?.name, item.inbox?.phone_number);
        }
        return results;
      }

      // Try endpoints in order — stop at first success with usable inbox IDs
      const endpoints = [
        "https://api.heymarket.com/v1/inboxes",
        "https://api.heymarket.com/v1/conversations?limit=5",
        "https://api.heymarket.com/v1/messages?limit=5",
        "https://api.heymarket.com/v1/chats?limit=5",
        "https://api.heymarket.com/v1/threads?limit=5",
      ];

      for (const url of endpoints) {
        try {
          const r = await fetch(url, { headers });
          if (!r.ok) continue;
          const data = await r.json();
          const inboxes = extractInboxes(data);
          if (inboxes.length > 0) return res.json({ inboxes, source: url });
        } catch { continue; }
      }

      // Nothing worked — return actionable guidance
      return res.status(422).json({
        message: "inbox_lookup_unavailable",
        hint: "Could not auto-detect the inbox ID. In Heymarket, open the Integrations tab in Admin settings — your API key will show which inbox it belongs to. The inbox ID is a number like 12345.",
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // GET /api/platform/sms/creators — fetch Heymarket team members (for creator_id config)
  app.get("/api/platform/sms/creators", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (user?.role !== "root_super_admin" && user?.role !== "super_admin") {
        return res.status(403).json({ message: "Forbidden" });
      }
      const apiToken = process.env.HEYMARKET_API_TOKEN;
      if (!apiToken) return res.status(400).json({ message: "HEYMARKET_API_TOKEN not set" });

      const headers = { "Authorization": `Bearer ${apiToken}`, "Content-Type": "application/json" };

      function extractMembers(data: any): { id: number; name: string; email: string | null }[] {
        const seen = new Set<number>();
        const results: { id: number; name: string; email: string | null }[] = [];
        const list = Array.isArray(data) ? data : (data.members ?? data.users ?? data.team ?? data.data ?? []);
        for (const item of list) {
          const numId = typeof item.id === "number" ? item.id : parseInt(item.id, 10);
          if (numId && !isNaN(numId) && !seen.has(numId)) {
            seen.add(numId);
            const firstName = item.first_name ?? item.firstName ?? "";
            const lastName  = item.last_name  ?? item.lastName  ?? "";
            const name = [firstName, lastName].filter(Boolean).join(" ") || item.name || item.username || `Member ${numId}`;
            results.push({ id: numId, name, email: item.email ?? null });
          }
        }
        return results;
      }

      const endpoints = [
        "https://api.heymarket.com/v1/members",
        "https://api.heymarket.com/v1/users",
        "https://api.heymarket.com/v1/team",
        "https://api.heymarket.com/v1/account/members",
      ];
      for (const url of endpoints) {
        try {
          const r = await fetch(url, { headers });
          if (!r.ok) continue;
          const data = await r.json();
          const members = extractMembers(data);
          if (members.length > 0) return res.json({ members, source: url });
        } catch { continue; }
      }
      return res.status(422).json({
        message: "creator_lookup_unavailable",
        hint: "Could not auto-detect team members. Find your Creator ID in Heymarket Admin → Team. It is the numeric ID shown for each team member.",
      });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

  // ── Heymarket User Mappings ────────────────────────────────────────────────
