  // POST /api/platform/sms/user-mappings/sync — auto-match DriverHub users to Heymarket members by email
  app.post("/api/platform/sms/user-mappings/sync", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (user?.role !== "root_super_admin" && user?.role !== "super_admin" && user?.role !== "super_user") {
        return res.status(403).json({ message: "Forbidden" });
      }

      const apiToken = process.env.HEYMARKET_API_TOKEN;
      if (!apiToken) return res.status(400).json({ message: "HEYMARKET_API_TOKEN not set" });

      // Fetch Heymarket team members
      const headers = { "Authorization": `Bearer ${apiToken}`, "Content-Type": "application/json" };
      let heymarketMembers: { id: number; name: string; email: string | null }[] = [];

      function extractMembers(data: any): { id: number; name: string; email: string | null }[] {
        const seen = new Set<number>();
        const results: { id: number; name: string; email: string | null }[] = [];
        const list = Array.isArray(data) ? data : (data.members ?? data.users ?? data.team ?? data.data ?? []);
        for (const item of list) {
          const numId = typeof item.id === "number" ? item.id : parseInt(item.id, 10);
          if (numId && !isNaN(numId) && !seen.has(numId)) {
            seen.add(numId);
            const firstName = item.first_name ?? item.firstName ?? "";
            const lastName  = item.last_name  ?? item.lastName  ?? "";
            const name = [firstName, lastName].filter(Boolean).join(" ") || item.name || item.username || `Member ${numId}`;
            results.push({ id: numId, name, email: item.email ?? null });
          }
        }
        return results;
      }

      const endpoints = [
        "https://api.heymarket.com/v1/members",
        "https://api.heymarket.com/v1/users",
        "https://api.heymarket.com/v1/team",
        "https://api.heymarket.com/v1/account/members",
      ];
      for (const url of endpoints) {
        try {
          const r = await fetch(url, { headers });
          if (!r.ok) continue;
          const data = await r.json();
          const members = extractMembers(data);
          if (members.length > 0) { heymarketMembers = members; break; }
        } catch { continue; }
      }

      if (heymarketMembers.length === 0) {
        return res.status(422).json({
          message: "creator_lookup_unavailable",
          hint: "Could not fetch Heymarket team members. Add mappings manually.",
        });
      }

      // Build email → Heymarket member map (lowercase for case-insensitive match)
      const hmByEmail = new Map<string, { id: number; name: string; email: string }>();
      for (const m of heymarketMembers) {
        if (m.email) hmByEmail.set(m.email.toLowerCase().trim(), { id: m.id, name: m.name, email: m.email });
      }

      // Load all DriverHub users with emails
      const dhUsers = (await db.execute(sql`
        SELECT id, email, first_name, last_name FROM users WHERE email IS NOT NULL
      `)).rows as { id: string; email: string; first_name: string | null; last_name: string | null }[];

      let matched = 0;
      let skipped = 0;
      const matchedHmEmails = new Set<string>();
      const results: { driverHubUserId: string; email: string; status: string; heymarketName?: string }[] = [];

      for (const dhUser of dhUsers) {
        const emailKey = dhUser.email.toLowerCase().trim();
        const hmMember = hmByEmail.get(emailKey);
        if (!hmMember) { skipped++; continue; }

        // Upsert — preserve manual mappings unless sync is forced
        await db.execute(sql`
          INSERT INTO heymarket_user_mappings
            (driverhub_user_id, heymarket_user_id, driverhub_email, heymarket_email, heymarket_name, matched_by, is_active, last_verified_at, updated_at)
          VALUES
            (${dhUser.id}, ${hmMember.id}, ${dhUser.email}, ${hmMember.email}, ${hmMember.name}, 'email', TRUE, NOW(), NOW())
          ON CONFLICT (driverhub_user_id) DO UPDATE
            SET heymarket_user_id  = EXCLUDED.heymarket_user_id,
                driverhub_email    = EXCLUDED.driverhub_email,
                heymarket_email    = EXCLUDED.heymarket_email,
                heymarket_name     = EXCLUDED.heymarket_name,
                matched_by         = 'email',
                is_active          = TRUE,
                last_verified_at   = NOW(),
                updated_at         = NOW()
          WHERE heymarket_user_mappings.matched_by = 'email'
        `);

        matchedHmEmails.add(emailKey);
        matched++;
        results.push({ driverHubUserId: dhUser.id, email: dhUser.email, status: "matched", heymarketName: hmMember.name });
      }

      // Heymarket members that had no matching DriverHub user
      const unmatchedHeymarket = heymarketMembers.filter(
        m => m.email && !matchedHmEmails.has(m.email.toLowerCase().trim()),
      ).map(m => ({ id: m.id, name: m.name, email: m.email }));

      console.log(`[Heymarket] User mapping sync: ${matched} matched, ${skipped} unmatched DH users, ${unmatchedHeymarket.length} unmatched HM members out of ${dhUsers.length} DriverHub users`);
      res.json({ matched, skipped, total: dhUsers.length, unmatchedHeymarket, results });
    } catch (e: any) {
      console.error("[Heymarket Sync]", e);
      res.status(500).json({ message: e.message });
    }
  });

  // PUT /api/platform/sms/user-mappings/:driverHubUserId — manually create or update a mapping
  app.put("/api/platform/sms/user-mappings/:driverHubUserId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const requestingUserId = req.user?.claims?.sub || (req.session as any)?.userId;
      const requestingUser = await storage.getUser(requestingUserId);
      if (requestingUser?.role !== "root_super_admin" && requestingUser?.role !== "super_admin" && requestingUser?.role !== "super_user") {
        return res.status(403).json({ message: "Forbidden" });
      }
      const { driverHubUserId } = req.params;
      const { heymarketUserId, heymarketEmail, heymarketName } = req.body as {
        heymarketUserId: number;
        heymarketEmail?: string | null;
        heymarketName?: string | null;
      };
      if (!heymarketUserId || isNaN(heymarketUserId)) {
        return res.status(400).json({ message: "heymarketUserId (integer) is required" });
      }
      // Resolve the DriverHub user's email for the driverhub_email column
      const dhUserRow = (await db.execute(sql`SELECT email FROM users WHERE id = ${driverHubUserId}`)).rows[0] as { email: string | null } | undefined;
      const dhEmail = dhUserRow?.email ?? null;
      await db.execute(sql`
        INSERT INTO heymarket_user_mappings
          (driverhub_user_id, heymarket_user_id, driverhub_email, heymarket_email, heymarket_name, matched_by, is_active, updated_at)
        VALUES
          (${driverHubUserId}, ${heymarketUserId}, ${dhEmail}, ${heymarketEmail ?? null}, ${heymarketName ?? null}, 'manual', TRUE, NOW())
        ON CONFLICT (driverhub_user_id) DO UPDATE
          SET heymarket_user_id = EXCLUDED.heymarket_user_id,
              driverhub_email   = EXCLUDED.driverhub_email,
              heymarket_email   = EXCLUDED.heymarket_email,
              heymarket_name    = EXCLUDED.heymarket_name,
              matched_by        = 'manual',
              is_active         = TRUE,
              updated_at        = NOW()
      `);
      res.json({ success: true });
    } catch (e: any) {
      res.status(500).json({ message: e.message });
    }
  });

