  // POST /api/corporate/customers/:id/drivers/text-selected
  // Routes through the Communications Framework (communicationsService.ts).
  // Validates recipients, dispatches via Heymarket when configured, logs every attempt.
  app.post("/api/corporate/customers/:id/drivers/text-selected", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const accountId = req.params.id;
      const { driverIds, message, contextModule = "assigned_drivers", contextEntityId, groupSignature } =
        req.body as { driverIds: string[]; message?: string; contextModule?: string; contextEntityId?: string; groupSignature?: string | null };

      if (!driverIds?.length) return res.status(400).json({ message: "No drivers selected" });
      if (!message?.trim()) return res.status(400).json({ message: "Message is required" });

      // Bulk/group sends require a group signature selection
      const isBulk = driverIds.length > 1;
      if (isBulk && !groupSignature) {
        return res.status(400).json({ message: "groupSignature is required for bulk sends. Choose one of: recruiting, dispatch, support." });
      }

      const { sendBulkSms, GROUP_SIGNATURES } = await import("./services/communicationsService");

      // Validate groupSignature value if provided
      const validValues = GROUP_SIGNATURES.map(s => s.value);
      if (groupSignature && !validValues.includes(groupSignature as any)) {
        return res.status(400).json({ message: `Invalid groupSignature. Must be one of: ${validValues.join(", ")}` });
      }

      const result = await sendBulkSms({
        accountId,
        driverIds,
        message: message.trim(),
        sentByUserId:  userId,
        contextModule,
        contextEntityId,
        groupSignature: groupSignature as any ?? null,
      });

      res.json(result);
    } catch (e: any) {
      console.error("[TextSelected]", e);
      res.status(500).json({ message: e.message });
    }
  });

  app.patch("/api/corporate/customers/:id/drivers/:driverId/set-primary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { id: accountId, driverId } = req.params;
      // Clear all primaries for this driver, then set this account as primary
      await db.update(driverAccounts).set({ isPrimary: false }).where(eq(driverAccounts.driverId, driverId));
      await db.update(driverAccounts).set({ isPrimary: true })
        .where(and(eq(driverAccounts.driverId, driverId), eq(driverAccounts.accountId, accountId)));
      res.json({ success: true });
    } catch (e: any) {
      console.error("[AccountDrivers SetPrimary]", e);
      res.status(500).json({ message: "Failed to set primary driver" });
    }
  });

  // ── Ops Work Plan: MVR Expired ───────────────────────────────────────────────
  app.get("/api/driver-ops/mvr-expired", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT
          d.id, u.first_name, u.last_name,
          d.mvr_date, d.status AS driver_status,
          d.driver_classification,
          d.state AS driver_state,
          d.hire_date,
          (CURRENT_DATE - d.mvr_date) - 365 AS days_expired,
          d.license_number, d.license_expiration,
          COALESCE(pa.id,  c.id)            AS account_id,
          COALESCE(pa.customer_name, c.customer_name) AS account_name,
          d.mvr_progress,
          d.mvr_request_sent_date,
          d.mvr_process_start_date,
          d.mvr_communication_type,
          d.mvr_result,
          CASE
            WHEN d.mvr_progress_updated_at IS NOT NULL
            THEN (CURRENT_DATE - d.mvr_progress_updated_at::date)::int
            ELSE NULL
          END AS days_in_status
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        LEFT  JOIN driver_accounts da ON da.driver_id = d.id AND da.is_primary = true AND da.assignment_ended_at IS NULL
        LEFT  JOIN customers pa ON pa.id = da.account_id
        LEFT  JOIN customers c  ON c.id  = d.drivershift_customer_id
        WHERE d.status = 'active'
          AND d.mvr_date IS NOT NULL
          AND (CURRENT_DATE - d.mvr_date) > 365
        ORDER BY d.mvr_process_start_date ASC NULLS LAST, d.mvr_date ASC
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        driverId:             r.id,
        driverName:           `${r.first_name || ""} ${r.last_name || ""}`.trim(),
        driverStatus:         r.driver_status || "active",
        workerClassification: r.driver_classification || null,
        driverState:          r.driver_state || null,
        hireDate:             r.hire_date ? String(r.hire_date) : null,
        mvrDate:              r.mvr_date,
        daysExpired:          r.days_expired,
        accountName:          r.account_name || null,
        accountId:            r.account_id   || null,
        licenseNumber:        r.license_number    || null,
        licenseExpiration:    r.license_expiration || null,
        mvrProgress:          r.mvr_progress || null,
        mvrRequestSentDate:   r.mvr_request_sent_date ? String(r.mvr_request_sent_date) : null,
        mvrProcessStartDate:  r.mvr_process_start_date ? String(r.mvr_process_start_date) : null,
        mvrCommunicationType: r.mvr_communication_type || null,
        mvrResult:            r.mvr_result || null,
        daysInStatus:         r.days_in_status !== null && r.days_in_status !== undefined ? Number(r.days_in_status) : null,
      })));
    } catch (e: any) {
      console.error("[driver-ops/mvr-expired]", e);
      res.status(500).json({ message: "Failed to fetch expired MVR drivers" });
    }
  });

  // ── Ops Work Plan: MVR Expiring ───────────────────────────────────────────────
  app.get("/api/driver-ops/mvr-expiring", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const days = parseInt(String(req.query.days ?? "60"), 10);
      const rows = await db.execute(sql`
        SELECT
          d.id, u.first_name, u.last_name,
          d.mvr_date,
          (d.mvr_date + INTERVAL '365 days')::date AS mvr_expiration_date,
          d.status AS driver_status,
          d.driver_classification,
          d.state AS driver_state,
          d.hire_date,
          365 - (CURRENT_DATE - d.mvr_date) AS days_remaining,
          d.license_number, d.license_expiration,
          COALESCE(pa.id,  c.id)            AS account_id,
          COALESCE(pa.customer_name, c.customer_name) AS account_name
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        LEFT  JOIN driver_accounts da ON da.driver_id = d.id AND da.is_primary = true AND da.assignment_ended_at IS NULL
        LEFT  JOIN customers pa ON pa.id = da.account_id
        LEFT  JOIN customers c  ON c.id  = d.drivershift_customer_id
        WHERE d.status = 'active'
          AND d.mvr_date IS NOT NULL
          AND (CURRENT_DATE - d.mvr_date) <= 365
          AND (CURRENT_DATE - d.mvr_date) >= 365 - ${days}
        ORDER BY d.mvr_date ASC
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        driverId:             r.id,
        driverName:           `${r.first_name || ""} ${r.last_name || ""}`.trim(),
        driverStatus:         r.driver_status || "active",
        workerClassification: r.driver_classification || null,
        driverState:          r.driver_state || null,
        hireDate:             r.hire_date ? String(r.hire_date) : null,
        mvrDate:              r.mvr_date,
        mvrExpirationDate:    r.mvr_expiration_date ? String(r.mvr_expiration_date) : null,
        daysRemaining:        r.days_remaining,
        accountName:          r.account_name || null,
        accountId:            r.account_id   || null,
        licenseNumber:        r.license_number    || null,
        licenseExpiration:    r.license_expiration || null,
      })));
    } catch (e: any) {
      console.error("[driver-ops/mvr-expiring]", e);
      res.status(500).json({ message: "Failed to fetch expiring MVR drivers" });
    }
  });

  // ── Ops Work Plan: License Expired ───────────────────────────────────────────
  app.get("/api/driver-ops/license-expired", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT d.id, u.first_name, u.last_name, d.license_expiration, d.status AS driver_status,
               (CURRENT_DATE - d.license_expiration::date)::int AS days_expired,
               d.license_number,
               d.driver_classification,
               d.state AS driver_state,
               COALESCE(pa.id,  c.id)             AS account_id,
               COALESCE(pa.customer_name, c.customer_name) AS account_name
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        LEFT  JOIN driver_accounts da ON da.driver_id = d.id AND da.is_primary = true AND da.assignment_ended_at IS NULL
        LEFT  JOIN customers pa ON pa.id = da.account_id
        LEFT  JOIN customers c  ON c.id  = d.drivershift_customer_id
        WHERE d.status = 'active'
          AND d.license_expiration IS NOT NULL
          AND d.license_expiration::date < CURRENT_DATE
        ORDER BY d.license_expiration ASC
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        driverId:             r.id,
        driverName:           `${r.first_name || ""} ${r.last_name || ""}`.trim(),
        driverStatus:         r.driver_status || "active",
        licenseExpiration:    r.license_expiration || null,
        daysExpired:          Number(r.days_expired),
        accountName:          r.account_name || null,
        accountId:            r.account_id   || null,
        licenseNumber:        r.license_number || null,
        workerClassification: r.driver_classification || null,
        driverState:          r.driver_state || null,
      })));
    } catch (e: any) {
      console.error("[driver-ops/license-expired]", e);
      res.status(500).json({ message: "Failed to fetch expired license drivers" });
    }
  });

