  // ── Unassigned Drivers ────────────────────────────────────────────────────────
  app.get("/api/driver-ops/unassigned-drivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT
          d.id,
          u.first_name,
          u.last_name,
          d.status          AS driver_status,
          d.driver_type,
          d.driver_classification,
          d.market,
          d.created_at,
          d.last_move_date,
          wu.match_status   AS wiw_match_status,
          wu.wiw_integration_status,
          wu.id             AS wiw_user_id,
          (
            SELECT MAX(ws.start_time)
            FROM wiw_shifts ws
            WHERE ws.wiw_user_id = wu.id
          ) AS last_shift_at
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        LEFT JOIN wiw_users wu ON wu.driver_id = d.id AND wu.wiw_status = 'active'
        WHERE d.status = 'active'
          AND NOT EXISTS (
            SELECT 1 FROM driver_accounts da
            WHERE da.driver_id = d.id
              AND da.assignment_ended_at IS NULL
          )
        ORDER BY
          GREATEST(
            d.last_move_date,
            (SELECT MAX(ws2.start_time) FROM wiw_shifts ws2 WHERE ws2.wiw_user_id = wu.id)
          ) DESC NULLS LAST,
          d.created_at ASC
      `);

      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => {
        const hasWiwActivity = r.wiw_user_id && r.wiw_match_status === "matched";
        return {
          driverId:             r.id,
          driverName:           `${r.first_name || ""} ${r.last_name || ""}`.trim(),
          driverStatus:         r.driver_status || "active",
          driverType:           r.driver_type || null,
          driverClassification: r.driver_classification || null,
          market:               r.market || null,
          createdAt:            r.created_at ? new Date(r.created_at).toISOString() : null,
          lastMoveDate:         r.last_move_date || null,
          lastShiftAt:          r.last_shift_at ? new Date(r.last_shift_at).toISOString() : null,
          wiwMatchStatus:       r.wiw_match_status || null,
          wiwIntegrationStatus: r.wiw_integration_status || null,
          priority:             hasWiwActivity ? "high" : "low",
        };
      }));
    } catch (e: any) {
      console.error("[driver-ops/unassigned-drivers]", e);
      res.status(500).json({ message: "Failed to fetch unassigned drivers" });
    }
  });

  // ── Multi-Account Drivers ─────────────────────────────────────────────────────
  app.get("/api/driver-ops/multi-account-drivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT
          d.id,
          u.first_name,
          u.last_name,
          (
            SELECT c.customer_name
            FROM customers c
            INNER JOIN driver_accounts da_p ON da_p.account_id = c.id
            WHERE da_p.driver_id = d.id
              AND da_p.is_primary = true
              AND da_p.assignment_ended_at IS NULL
            LIMIT 1
          ) AS primary_account_name,
          (
            SELECT da_p2.account_id
            FROM driver_accounts da_p2
            WHERE da_p2.driver_id = d.id
              AND da_p2.is_primary = true
              AND da_p2.assignment_ended_at IS NULL
            LIMIT 1
          ) AS primary_account_id,
          (
            SELECT json_agg(json_build_object('id', c2.id, 'name', c2.customer_name) ORDER BY c2.customer_name)
            FROM customers c2
            INNER JOIN driver_accounts da_s ON da_s.account_id = c2.id
            WHERE da_s.driver_id = d.id
              AND da_s.is_primary = false
              AND da_s.assignment_ended_at IS NULL
          ) AS secondary_accounts,
          (
            SELECT COUNT(*)::int
            FROM driver_accounts da_cnt
            WHERE da_cnt.driver_id = d.id
              AND da_cnt.assignment_ended_at IS NULL
          ) AS account_count
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        WHERE d.status = 'active'
          AND (
            SELECT COUNT(*)
            FROM driver_accounts da
            WHERE da.driver_id = d.id
              AND da.assignment_ended_at IS NULL
          ) >= 2
        ORDER BY
          CASE WHEN (
            SELECT COUNT(*) FROM driver_accounts da_chk
            WHERE da_chk.driver_id = d.id
              AND da_chk.is_primary = true
              AND da_chk.assignment_ended_at IS NULL
          ) = 0 THEN 0 ELSE 1 END ASC,
          u.first_name ASC,
          u.last_name ASC
      `);

      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        driverId:           r.id,
        driverName:         `${r.first_name || ""} ${r.last_name || ""}`.trim(),
        primaryAccountId:   r.primary_account_id || null,
        primaryAccountName: r.primary_account_name || null,
        secondaryAccounts:  Array.isArray(r.secondary_accounts) ? r.secondary_accounts : [],
        accountCount:       r.account_count || 0,
      })));
    } catch (e: any) {
      console.error("[driver-ops/multi-account-drivers]", e);
      res.status(500).json({ message: "Failed to fetch multi-account drivers" });
    }
  });

