  // GET /api/driver-ops/photo-approvals — pending driver_app submissions (Ops Work Plan widget)
  app.get("/api/driver-ops/photo-approvals", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT
          dpa.id,
          dpa.driver_id,
          dpa.submitted_by_type,
          dpa.status,
          dpa.created_at,
          dpa.reviewed_at,
          dpa.decline_reason,
          u.first_name  AS driver_first_name,
          u.last_name   AS driver_last_name,
          d.profile_photo_url AS current_photo_url,
          proposed_doc.file_data AS proposed_photo_url,
          reviewer.first_name AS reviewer_first_name,
          reviewer.last_name  AS reviewer_last_name
        FROM driver_photo_approvals dpa
        INNER JOIN drivers d ON d.id = dpa.driver_id
        INNER JOIN users u   ON u.id = d.user_id
        LEFT JOIN driver_documents proposed_doc ON proposed_doc.id = dpa.proposed_photo_document_id
        LEFT JOIN users reviewer ON reviewer.id = dpa.reviewed_by_user_id
        WHERE dpa.status = 'pending'
          AND dpa.submitted_by_type = 'driver_app'
        ORDER BY dpa.created_at ASC
      `);

      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        id:               r.id,
        driverId:         r.driver_id,
        driverName:       `${r.driver_first_name || ""} ${r.driver_last_name || ""}`.trim(),
        submittedByType:  r.submitted_by_type,
        status:           r.status,
        createdAt:        r.created_at,
        reviewedAt:       r.reviewed_at,
        declineReason:    r.decline_reason,
        currentPhotoUrl:  r.current_photo_url,
        proposedPhotoUrl: r.proposed_photo_url,
        reviewerName:     r.reviewer_first_name ? `${r.reviewer_first_name} ${r.reviewer_last_name || ""}`.trim() : null,
      })));
    } catch (e: any) {
      console.error("[driver-ops/photo-approvals]", e);
      res.status(500).json({ message: "Failed to fetch photo approvals" });
    }
  });

  // POST /api/driver-ops/photo-approvals/:id/approve
  app.post("/api/driver-ops/photo-approvals/:id/approve", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const approvalId = req.params.id;
      const rows = await db.execute(sql`
        SELECT dpa.*, d.user_id AS driver_user_id, doc.file_data AS proposed_photo_url
        FROM driver_photo_approvals dpa
        INNER JOIN drivers d ON d.id = dpa.driver_id
        LEFT JOIN driver_documents doc ON doc.id = dpa.proposed_photo_document_id
        WHERE dpa.id = ${approvalId}
        LIMIT 1
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      const approval = data[0];
      if (!approval) return res.status(404).json({ message: "Photo approval not found" });
      if (approval.status !== "pending") return res.status(400).json({ message: "Approval is not in pending status" });

      // Apply the proposed photo as the active driver photo
      if (approval.proposed_photo_url) {
        await storage.updateDriver(approval.driver_id, { profilePhotoUrl: approval.proposed_photo_url });
        if (approval.driver_user_id) {
          await storage.updateUser(approval.driver_user_id, { profileImageUrl: approval.proposed_photo_url });
        }
      }

      await db.execute(sql`
        UPDATE driver_photo_approvals
        SET status = 'approved',
            reviewed_by_user_id = ${userId},
            reviewed_at = NOW(),
            approved_photo_applied_at = NOW(),
            updated_at = NOW()
        WHERE id = ${approvalId}
      `);

      res.json({ success: true });
    } catch (e: any) {
      console.error("[driver-ops/photo-approvals/approve]", e);
      res.status(500).json({ message: "Failed to approve photo" });
    }
  });

  // POST /api/driver-ops/photo-approvals/:id/decline
  app.post("/api/driver-ops/photo-approvals/:id/decline", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const approvalId = req.params.id;
      const { reason } = req.body as { reason?: string };
      if (!reason?.trim()) return res.status(400).json({ message: "A decline reason is required" });

      const rows = await db.execute(sql`
        SELECT id, status FROM driver_photo_approvals WHERE id = ${approvalId} LIMIT 1
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      const approval = data[0];
      if (!approval) return res.status(404).json({ message: "Photo approval not found" });
      if (approval.status !== "pending") return res.status(400).json({ message: "Approval is not in pending status" });

      await db.execute(sql`
        UPDATE driver_photo_approvals
        SET status = 'declined',
            reviewed_by_user_id = ${userId},
            reviewed_at = NOW(),
            decline_reason = ${reason.trim()},
            updated_at = NOW()
        WHERE id = ${approvalId}
      `);

      res.json({ success: true });
    } catch (e: any) {
      console.error("[driver-ops/photo-approvals/decline]", e);
      res.status(500).json({ message: "Failed to decline photo" });
    }
  });

  // ── Attendance: No Show Today ─────────────────────────────────────────────────
  app.get("/api/attendance/no-show-today", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const rows = await db.execute(sql`
        SELECT s.id AS shift_id, wu.driver_id, wu.name AS driver_name,
               s.start_time, s.end_time,
               c.customer_name, c.id AS account_id,
               EXTRACT(EPOCH FROM (NOW() - s.start_time))::int / 60 AS minutes_past_start
        FROM wiw_shifts s
        JOIN wiw_users wu ON wu.id = s.wiw_user_id
        JOIN drivers d ON d.id = wu.driver_id AND d.status = 'active'
        LEFT JOIN wiw_times t ON t.wiw_shift_id = s.id AND t.clock_in IS NOT NULL
        LEFT JOIN customers c ON c.id = s.driverhub_account_id
        WHERE s.status != 'deleted'
          AND s.start_time::date = CURRENT_DATE
          AND s.start_time <= NOW() - INTERVAL '30 minutes'
          AND s.end_time > NOW()
          AND t.id IS NULL
        ORDER BY s.start_time ASC
      `);
      const data = ((rows as any).rows ?? rows) as any[];
      res.json(data.map(r => ({
        shiftId: r.shift_id,
        driverId: r.driver_id || null,
        driverName: r.driver_name || "Unknown",
        scheduledStart: r.start_time,
        scheduledEnd: r.end_time,
        minutesPastStart: r.minutes_past_start,
        accountName: r.customer_name || null,
        accountId: r.account_id || null,
      })));
    } catch (e: any) {
      console.error("[attendance/no-show-today]", e);
      res.status(500).json({ message: "Failed to fetch no-show data" });
    }
  });

