  // GET /api/payroll/earnings — list with filters: driverId, batchId, status, from, to
  app.get("/api/payroll/earnings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { driverId, batchId, status, from, to, limit: limitStr } = req.query as Record<string, string>;
      const conditions: ReturnType<typeof eq>[] = [];
      if (driverId) conditions.push(eq(driverEarnings.driverId, driverId));
      if (batchId)  conditions.push(eq(driverEarnings.batchId as any, batchId));
      if (status)   conditions.push(eq(driverEarnings.status, status));
      if (from)     conditions.push(gte(driverEarnings.earningDate, from));
      if (to)       conditions.push(lte(driverEarnings.earningDate, to));
      const limitN = Math.min(parseInt(limitStr ?? "200", 10) || 200, 500);
      const rows = await db.select().from(driverEarnings)
        .where(conditions.length ? and(...conditions) : undefined)
        .orderBy(desc(driverEarnings.earningDate))
        .limit(limitN);
      res.json({ earnings: rows, total: rows.length });
    } catch (e: any) {
      console.error("[Earnings GET]", e);
      res.status(500).json({ message: "Failed to fetch earnings" });
    }
  });

  // GET /api/payroll/earnings/driver/:driverId/summary — total + breakdown for a driver
  app.get("/api/payroll/earnings/driver/:driverId/summary", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { driverId } = req.params;
      const { from, to } = req.query as Record<string, string>;
      const conditions = [eq(driverEarnings.driverId, driverId)];
      if (from) conditions.push(gte(driverEarnings.earningDate, from));
      if (to)   conditions.push(lte(driverEarnings.earningDate, to));
      const rows = await db.select().from(driverEarnings)
        .where(and(...conditions))
        .orderBy(desc(driverEarnings.earningDate))
        .limit(200);
      const pending  = rows.filter(r => r.status === "pending");
      const approved = rows.filter(r => r.status === "approved");
      const paid     = rows.filter(r => r.status === "paid");
      const sum = (arr: typeof rows) => arr.reduce((s, r) => s + Number(r.totalAmount), 0);
      res.json({
        total:         rows.length,
        pendingCount:  pending.length,
        approvedCount: approved.length,
        paidCount:     paid.length,
        pendingAmount:  sum(pending),
        approvedAmount: sum(approved),
        paidAmount:     sum(paid),
        totalAmount:    sum(rows),
        recentEarnings: rows.slice(0, 10),
      });
    } catch (e: any) {
      console.error("[Earnings Summary]", e);
      res.status(500).json({ message: "Failed to fetch earnings summary" });
    }
  });

  // POST /api/payroll/earnings — create a manual earnings record
  app.post("/api/payroll/earnings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { driverId, earningDate, payType, description, hoursWorked, otHours, moveCount, milesLogged,
              baseAmount, otAmount, bonusAmount, adjustmentAmount, totalAmount, batchId, moveId, payProfileId,
              employeeId, calculationLog } = req.body;
      if (!driverId || !earningDate || !payType) {
        return res.status(400).json({ message: "driverId, earningDate, payType required" });
      }
      const base = Number(baseAmount ?? 0);
      const ot   = Number(otAmount ?? 0);
      const bon  = Number(bonusAmount ?? 0);
      const adj  = Number(adjustmentAmount ?? 0);
      const total = Number(totalAmount ?? (base + ot + bon + adj));
      const rows = await db.insert(driverEarnings).values({
        driverId, earningDate, payType,
        description: description ?? null,
        employeeId: employeeId ?? null,
        payProfileId: payProfileId ?? null,
        batchId: batchId ?? null,
        moveId: moveId ?? null,
        hoursWorked: hoursWorked ? String(hoursWorked) : null,
        otHours: String(otHours ?? 0),
        moveCount: moveCount ?? null,
        milesLogged: milesLogged ? String(milesLogged) : null,
        baseAmount: String(base),
        otAmount: String(ot),
        bonusAmount: String(bon),
        adjustmentAmount: String(adj),
        totalAmount: String(total),
        status: "pending",
        calculationSource: "manual",
        calculationLog: calculationLog ?? [],
        adjustedBy: userId,
      }).returning();
      res.json(rows[0]);
    } catch (e: any) {
      console.error("[Earnings POST]", e);
      res.status(500).json({ message: "Failed to create earnings record" });
    }
  });

  // PATCH /api/payroll/earnings/:id — update status or adjustment
  app.patch("/api/payroll/earnings/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const allowed = ["status","adjustmentAmount","adjustmentNote","batchId","description","bonusAmount"];
      const update: Record<string, unknown> = { updatedAt: new Date() };
      for (const k of allowed) if (k in req.body) update[k] = req.body[k];
      if (req.body.adjustmentAmount !== undefined) {
        update.adjustedBy = userId;
        // Recalculate total
        const [curr] = await db.select().from(driverEarnings).where(eq(driverEarnings.id, req.params.id)).limit(1);
        if (curr) {
          const newAdj = Number(req.body.adjustmentAmount);
          update.totalAmount = String(
            Number(curr.baseAmount) + Number(curr.otAmount) + Number(curr.bonusAmount) + newAdj
          );
        }
      }
      const rows = await db.update(driverEarnings).set(update).where(eq(driverEarnings.id, req.params.id)).returning();
      if (!rows[0]) return res.status(404).json({ message: "Earnings record not found" });
      // Recalc batch totals if in a batch
      if (rows[0].batchId) {
        const { recalcBatchTotals } = await import("./services/payRulesEngine");
        await recalcBatchTotals(rows[0].batchId);
      }
      res.json(rows[0]);
    } catch (e: any) {
      console.error("[Earnings PATCH]", e);
      res.status(500).json({ message: "Failed to update earnings record" });
    }
  });

  // POST /api/payroll/calculate/:driverId — run pay rules engine for a driver
  app.post("/api/payroll/calculate/:driverId", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { driverId } = req.params;
      const {
        earningDate, hoursWorked, moveCount, milesLogged, moveId,
        adjustmentAmount, description, batchId,
      } = req.body;
      if (!earningDate) return res.status(400).json({ message: "earningDate required" });

      const { getPayProfile, calculateEarnings, createEarningsRecord } = await import("./services/payRulesEngine");
      const profile = await getPayProfile(driverId);
      if (!profile) return res.status(404).json({ message: "No pay profile configured for this driver" });

      const result = calculateEarnings({
        payType: profile.payType,
        workerType: profile.workerType,
        hourlyRate: profile.hourlyRate ? Number(profile.hourlyRate) : 0,
        otMultiplier: Number(profile.otMultiplier),
        otThresholdHrs: Number(profile.otThresholdHrs),
        perMoveRate: profile.perMoveRate ? Number(profile.perMoveRate) : 0,
        perMileRate: profile.perMileRate ? Number(profile.perMileRate) : 0,
        bonusRules: (profile.bonusRules as any) ?? [],
        hoursWorked: hoursWorked ? Number(hoursWorked) : 0,
        moveCount: moveCount ? Number(moveCount) : 0,
        milesLogged: milesLogged ? Number(milesLogged) : 0,
        adjustmentAmount: adjustmentAmount ? Number(adjustmentAmount) : 0,
      });

      const record = await createEarningsRecord({
        driverId,
        employeeId: profile.employeeId,
        payProfileId: profile.id,
        batchId: batchId ?? null,
        moveId: moveId ?? null,
        earningDate,
        payType: profile.payType,
        description: description ?? null,
        hoursWorked: hoursWorked ? Number(hoursWorked) : undefined,
        moveCount: moveCount ? Number(moveCount) : undefined,
        milesLogged: milesLogged ? Number(milesLogged) : undefined,
        calculationSource: "auto_calculate",
        earnings: result,
      });

      res.json({ record, calculation: result });
    } catch (e: any) {
      console.error("[Calculate Earnings]", e);
      res.status(500).json({ message: "Failed to calculate earnings" });
    }
  });

  // ── Payroll Batches ──────────────────────────────────────────────────────────

  // GET /api/payroll/batches — list batches
  app.get("/api/payroll/batches", isAuthenticated, async (req: any, res: Response) => {
    try {
      const { status, limit: limitStr } = req.query as Record<string, string>;
      const conditions: ReturnType<typeof eq>[] = [];
      if (status) conditions.push(eq(payrollBatches.status, status));
      const limitN = Math.min(parseInt(limitStr ?? "50", 10) || 50, 200);
      const rows = await db.select().from(payrollBatches)
        .where(conditions.length ? and(...conditions) : undefined)
        .orderBy(desc(payrollBatches.weekStart))
        .limit(limitN);
      res.json({ batches: rows });
    } catch (e: any) {
      console.error("[Batches GET]", e);
      res.status(500).json({ message: "Failed to fetch batches" });
    }
  });

  // POST /api/payroll/batches — create a batch (idempotent by weekStart+payGroup)
  app.post("/api/payroll/batches", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { weekStart, weekEnd, payGroup, notes } = req.body;
      if (!weekStart || !weekEnd) return res.status(400).json({ message: "weekStart and weekEnd required" });
      const { getOrCreateBatch } = await import("./services/payRulesEngine");
      const batch = await getOrCreateBatch(weekStart, weekEnd, payGroup ?? "DRIVERS_WEEKLY");
      if (notes && !batch.notes) {
        await db.update(payrollBatches).set({ notes, updatedAt: new Date() }).where(eq(payrollBatches.id, batch.id));
      }
      res.json(batch);
    } catch (e: any) {
      console.error("[Batches POST]", e);
      res.status(500).json({ message: "Failed to create batch" });
    }
  });

  // GET /api/payroll/batches/:id — batch detail with earnings breakdown
  app.get("/api/payroll/batches/:id", isAuthenticated, async (req: any, res: Response) => {
    try {
      const [batch] = await db.select().from(payrollBatches).where(eq(payrollBatches.id, req.params.id)).limit(1);
      if (!batch) return res.status(404).json({ message: "Batch not found" });
      const earnings = await db.select().from(driverEarnings)
        .where(eq(driverEarnings.batchId as any, req.params.id))
        .orderBy(driverEarnings.driverId, desc(driverEarnings.earningDate));
      // Group by driver
      const byDriver: Record<string, { driverId: string; earnings: typeof earnings; total: number }> = {};
      for (const e of earnings) {
        if (!byDriver[e.driverId]) byDriver[e.driverId] = { driverId: e.driverId, earnings: [], total: 0 };
        byDriver[e.driverId].earnings.push(e);
        if (e.status !== "voided") byDriver[e.driverId].total += Number(e.totalAmount);
      }
      res.json({ batch, driverGroups: Object.values(byDriver), rawEarnings: earnings });
    } catch (e: any) {
      console.error("[Batch Detail]", e);
      res.status(500).json({ message: "Failed to fetch batch detail" });
    }
  });

  // PATCH /api/payroll/batches/:id/status — advance batch status
  app.patch("/api/payroll/batches/:id/status", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { status, notes } = req.body;
      const VALID = ["open","under_review","approved","paid","voided"];
      if (!VALID.includes(status)) return res.status(400).json({ message: `status must be one of: ${VALID.join(", ")}` });
      const update: Record<string, unknown> = { status, updatedAt: new Date() };
      if (notes) update.notes = notes;
      if (status === "approved") { update.approvedBy = userId; update.approvedAt = new Date(); }
      if (status === "paid")     { update.paidAt = new Date(); }
      // If approving, also mark all pending earnings as approved
      if (status === "approved") {
        await db.update(driverEarnings)
          .set({ status: "approved", updatedAt: new Date() })
          .where(and(eq(driverEarnings.batchId as any, req.params.id), eq(driverEarnings.status, "pending")));
      }
      // If marking paid, also mark all approved earnings as paid
      if (status === "paid") {
        await db.update(driverEarnings)
          .set({ status: "paid", updatedAt: new Date() })
          .where(and(eq(driverEarnings.batchId as any, req.params.id), eq(driverEarnings.status, "approved")));
      }
      const { recalcBatchTotals } = await import("./services/payRulesEngine");
      await recalcBatchTotals(req.params.id);
      const rows = await db.update(payrollBatches).set(update).where(eq(payrollBatches.id, req.params.id)).returning();
      if (!rows[0]) return res.status(404).json({ message: "Batch not found" });
      res.json(rows[0]);
    } catch (e: any) {
      console.error("[Batch Status PATCH]", e);
      res.status(500).json({ message: "Failed to update batch status" });
    }
  });

  // POST /api/payroll/batches/:id/assign-earnings — bulk assign earnings to a batch
  app.post("/api/payroll/batches/:id/assign-earnings", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });
      const { earningIds } = req.body as { earningIds: string[] };
      if (!Array.isArray(earningIds) || earningIds.length === 0) {
        return res.status(400).json({ message: "earningIds array required" });
      }
      await db.update(driverEarnings)
        .set({ batchId: req.params.id, updatedAt: new Date() })
        .where(inArray(driverEarnings.id, earningIds));
      const { recalcBatchTotals } = await import("./services/payRulesEngine");
      await recalcBatchTotals(req.params.id);
      res.json({ success: true, updated: earningIds.length });
    } catch (e: any) {
      console.error("[Assign Earnings]", e);
      res.status(500).json({ message: "Failed to assign earnings to batch" });
    }
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // OPERATIONS MAP — /api/ops-map/*
  // Returns geolocated records for each layer (accounts, drivers, employees, moves).
  // Geocoding is done via Nominatim (OpenStreetMap) server-side with rate limiting;
  // results are stored in the DB so re-geocoding only happens once per record.
  // ═══════════════════════════════════════════════════════════════════════════

  // ── Internal geocode helper (Nominatim, max 1 req/sec) ───────────────────
  async function nominatimGeocode(query: string): Promise<{ lat: number; lng: number } | null> {
    try {
      const url = `https://nominatim.openstreetmap.org/search?format=json&q=${encodeURIComponent(query)}&limit=1`;
      const resp = await fetch(url, {
        headers: { "User-Agent": "DriverHub360/1.0 (contact@driverondemand.co)" },
      });
      if (!resp.ok) return null;
      const data = (await resp.json()) as { lat: string; lon: string }[];
      if (data.length === 0) return null;
      return { lat: parseFloat(data[0].lat), lng: parseFloat(data[0].lon) };
    } catch {
      return null;
    }
  }

  // ── Helper: sleep (rate-limit between geocode calls) ──────────────────────
  const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

  // ── GET /api/ops-map/accounts ─────────────────────────────────────────────
  app.get("/api/ops-map/accounts", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { status, region, market } = req.query as Record<string, string>;

      // Fetch accounts with or without coordinates
      const rows = await db.execute(sql`
        SELECT
          c.id,
          c.customer_name,
          c.status,
          c.customer_address,
          c.customer_city,
          c.customer_state,
          c.customer_zip,
          c.network,
          c.customer_latitude,
          c.customer_longitude
        FROM customers c
        WHERE c.is_deleted IS DISTINCT FROM TRUE
          ${status ? sql`AND LOWER(c.status) = LOWER(${status})` : sql``}
          ${region ? sql`AND LOWER(c.customer_state) LIKE LOWER(${'%' + region + '%'})` : sql``}
          ${market ? sql`AND LOWER(c.network) LIKE LOWER(${'%' + market + '%'})` : sql``}
        ORDER BY c.customer_name
        LIMIT 500
      `);

      const data = ((rows as any).rows ?? rows) as any[];

      // Geocode up to 5 records that are missing coordinates (store for reuse)
      let geocodedCount = 0;
      const results = [];
      for (const r of data) {
        let lat = r.customer_latitude ? parseFloat(r.customer_latitude) : null;
        let lng = r.customer_longitude ? parseFloat(r.customer_longitude) : null;

        if ((lat === null || lng === null) && geocodedCount < 5) {
          const addrParts = [r.customer_address, r.customer_city, r.customer_state, r.customer_zip]
            .filter(Boolean).join(", ");
          if (addrParts) {
            const geo = await nominatimGeocode(addrParts);
            if (geo) {
              lat = geo.lat;
              lng = geo.lng;
              // Store for reuse
              await db.execute(sql`
                UPDATE customers
                SET customer_latitude = ${lat}, customer_longitude = ${lng}
                WHERE id = ${r.id}
              `);
              geocodedCount++;
              if (geocodedCount < 5) await sleep(1100); // Nominatim rate limit: 1 req/sec
            }
          }
        }

        if (lat !== null && lng !== null) {
          const addr = [r.customer_address, r.customer_city, r.customer_state].filter(Boolean).join(", ");
          results.push({
            id: r.id,
            name: r.customer_name,
            status: r.status || "Unknown",
            region: r.customer_state || null,
            network: r.network || null,
            market: null,
            driverModel: null,
            lat,
            lng,
            address: addr || null,
          });
        }
      }

      res.json(results);
    } catch (e: any) {
      console.error("[ops-map/accounts]", e);
      res.status(500).json({ message: "Failed to fetch account map data" });
    }
  });

  // ── GET /api/ops-map/drivers ──────────────────────────────────────────────
  app.get("/api/ops-map/drivers", isAuthenticated, async (req: any, res: Response) => {
    try {
      const userId = req.user?.claims?.sub || (req.session as any)?.userId;
      const user = await storage.getUser(userId);
      if (!hasCorporateAccess(user?.role)) return res.status(403).json({ message: "Forbidden" });

      const { status, region, market } = req.query as Record<string, string>;

      const rows = await db.execute(sql`
        SELECT
          d.id,
          u.first_name,
          u.last_name,
          u.email,
          d.status,
          d.phone_number,
          d.address,
          d.city,
          d.state,
          d.zip_code,
          d.latitude,
          d.longitude,
          COALESCE(
            (SELECT json_agg(c.customer_name ORDER BY c.customer_name)
             FROM driver_accounts da
             JOIN customers c ON c.id = da.account_id
             WHERE da.driver_id = d.id
               AND da.assignment_ended_at IS NULL), '[]'::json
          ) AS accounts
        FROM drivers d
        INNER JOIN users u ON u.id = d.user_id
        WHERE d.status != 'deleted'
          ${status ? sql`AND LOWER(d.status) = LOWER(${status})` : sql``}
          ${region ? sql`AND LOWER(COALESCE(d.state,'')) LIKE LOWER(${'%' + region + '%'})` : sql``}
          ${market ? sql`AND EXISTS (SELECT 1 FROM driver_accounts da2 JOIN customers c2 ON c2.id = da2.account_id WHERE da2.driver_id = d.id AND da2.assignment_ended_at IS NULL AND LOWER(COALESCE(c2.network,'')) LIKE LOWER(${'%' + market + '%'}))` : sql``}
        ORDER BY u.first_name, u.last_name
        LIMIT 1000
      `);

      const data = ((rows as any).rows ?? rows) as any[];

      let geocodedCount = 0;
      const results = [];
      for (const r of data) {
        let lat = r.latitude ? parseFloat(r.latitude) : null;
        let lng = r.longitude ? parseFloat(r.longitude) : null;

        if ((lat === null || lng === null) && geocodedCount < 5) {
          const query = r.zip_code
            ? `${r.zip_code} USA`
            : [r.city, r.state].filter(Boolean).join(", ") + " USA";
          if (query.trim() !== "USA") {
            const geo = await nominatimGeocode(query);
            if (geo) {
              lat = geo.lat;
              lng = geo.lng;
              await db.execute(sql`
                UPDATE drivers SET latitude = ${lat}, longitude = ${lng} WHERE id = ${r.id}
              `);
              geocodedCount++;
              if (geocodedCount < 5) await sleep(1100);
            }
          }
        }

        if (lat !== null && lng !== null) {
          results.push({
            id: r.id,
            name: `${r.first_name || ""} ${r.last_name || ""}`.trim(),
            status: r.status || "Unknown",
            phone: r.phone_number || null,
            email: r.email || null,
            accounts: Array.isArray(r.accounts) ? r.accounts : [],
            lat,
            lng,
            city: r.city || null,
            state: r.state || null,
          });
        }
      }

      res.json(results);
    } catch (e: any) {
      console.error("[ops-map/drivers]", e);
      res.status(500).json({ message: "Failed to fetch driver map data" });
    }
  });

